tr[2480] = {H:"Чтобы арфа зазвучала, после покупки зайди в режим " + "\"" + "конструктор клуба" + "\"" + ", кликни на неё и нажми кнопку " + "\"" + "влево" + "\"" + " или " + "\"" + "вправо" + "\"" + "."};
tr[2481] = {H:"Чтобы рояль зазвучал, после покупки зайди в режим " + "\"" + "конструктор клуба" + "\"" + ", кликни на инструмент и нажми кнопку " + "\"" + "влево" + "\"" + " или " + "\"" + "вправо" + "\"" + "."};
tr[2482] = {H:"Их пение так прекрасно, что сам Босс Ба-Босс приходит на их концерты."};
tr[2483] = {H:"Мечтаешь, чтобы новогодний праздник не заканчивался? Приглашай их в клуб хоть каждый день!"};
tr[2484] = {H:"Знаменитый фокусник привёз для твоих гостей целый вагон чудес!"};
tr[2485] = {H:"Самые сильные Смешарики ждут приглашения в твой клуб!"};
tr[2486] = {H:"Горячие тусовки по-африкански зажгут улыбки твоих гостей."};
tr[2487] = {H:"Гости смогут оценить твоё авто прямо в клубе."};
tr[2488] = {H:"Приобрети её и радуй гостей лакомством!"};
