tr[2490] = {H:"Чтобы она зазвучала, после покупки зайди в режим " + "\"" + "конструктор клуба" + "\"" + ", кликни на установку и нажми кнопку " + "\"" + "влево" + "\"" + " или " + "\"" + "вправо" + "\"" + "."};
tr[2491] = {H:"Устрой потрясную тусовку с крутыми рокерами!"};
tr[2492] = {H:"Ликуйте, фанаты ВИА " + "\"" + "SHARA" + "\"" + ", – у них новый хит! Теперь с африканскими мотивами!"};
tr[2493] = {H:"Не пропусти крутое шоу любимца публики и просто симпатяги!"};
tr[2494] = {H:"Пёстрые орнаменты, зажигательные ритмы – всё это здесь, в мексиканском клубе!"};
tr[2495] = {H:"Соревнуйся с гостями в скорости реакции и мастерстве подач!"};
tr[2496] = {H:"Почувствуй себя морским волком: целься, стреляй, зарабатывай Смешинки! "};
tr[2497] = {H:"Не скучай – подпевай! На их выступлениях всегда весело и интересно!"};
tr[2498] = {H:"Жаждешь песен и веселья? Зови мексиканцев и пускайся в пляс!"};
tr[2499] = {H:"Бесстрашные артисты покажут невероятные трюки и чудеса акробатики!"};
tr[2500] = {H:"Клуб на дне океана? Да, это реально! Сюда заплывают самые крутые дайверы."};
tr[2501] = {H:"Нереальный фристайл от крутых баскетболистов!"};
tr[2502] = {H:"Лёгкое кружение под вальс – отличное начало роскошного бала!"};
tr[2503] = {H:"Никто не заскучает под звуки скрипок и бубнов этой удалой компании!"};
