tr[2665] = {H:"миссия"};
tr[2666] = {H:"Фон " + "\"" + "Домик Кроша" + "\"" + ""};
tr[2667] = {H:"Агент, переоденься для конспирации!"};
tr[2668] = {H:"взять одежду"};
tr[2669] = {H:"Шляпа Секретного агента"};
tr[2670] = {H:"Плащ Секретного агента"};
tr[2671] = {H:"Очки Секретного агента"};
tr[2672] = {H:"Нет, только не это! Я не уверен, что смогу отыскать Крошек!"};
tr[2673] = {OId:165,H:"Жаль, что эта задача тебе не по силам. Приходи, когда станешь увереннее и смелее!"};
tr[2674] = {H:"У меня сейчас слишком много дел, чтобы заниматься этим."};
tr[2675] = {OId:165,H:"Жаль, что ты не можешь взяться за это дело. Мы рассчитывали на твою помощь."};
tr[2676] = {H:"Я готов приступить к выполнению миссии прямо сейчас!"};
tr[2677] = {OId:165,H:"Для начала отправляйся в Детский сад. Наверняка другие Крошки что-то знают и смогут помочь тебе. Удачи!"};
tr[2678] = {OId:19,H:"Здравствуйте! Вы, наверное, слышали, что наши друзья ушли гулять и пропали..."};
tr[2679] = {H:"Да, я слышал про это и хочу помочь. Может быть, ты знаешь, куда они могли убежать?"};
tr[2680] = {OId:19,H:"Я знаю, что они хотели покататься на катере по морю... Вдруг кто-нибудь видел их в Порту?"};
tr[2681] = {H:"Спасибо за подсказку!"};
tr[2682] = {OId:19,H:"Ах да... Как только вы найдёте Крошек, передайте моей подружке её любимую игрушку..."};
tr[2683] = {H:"Игрушка будет мешать мне в поисках – ты сможешь отдать ей игрушку сама, как только я приведу твоих друзей сюда."};
tr[2684] = {OId:19,H:"Эх, жа-а-алко..."};
tr[2685] = {H:"Не переживай, я обязательно передам игрушку!"};
tr[2686] = {H:"Игрушка будет мешать поискам, но я постараюсь передать её твоей подружке."};
tr[2687] = {OId:19,H:"Спасибо! Мы будем вас очень-очень ждать!"};
tr[2688] = {OId:19,H:"Вы ещё не нашли наших друзей? Как только вы их найдёте, передайте моей подружке её любимую игрушку."};
tr[2689] = {OId:17,H:"Ну и денёк сегодня! Рыба так плохо клюёт..."};
tr[2690] = {H:"Добрый день! Вы, случайно, не видели тут двух Крошек?"};
tr[2691] = {OId:17,H:"Может и видел, а может и нет... Я такой рассеянный в последнее время... А кто это такие – Крошки?"};
tr[2692] = {H:"Это два малыша: мальчик и девочка. Они убежали погулять и пропали..."};
tr[2693] = {OId:17,H:"Нет, кажется, я их не видел..."};
tr[2694] = {H:"Это два малыша: мальчик и девочка. Они ушли покататься на катере и пропали."};
tr[2695] = {OId:17,H:"На катере, говоришь? Да, были тут двое, а как же! Носились, кричали, перепугали мне всю рыбу... Если это на них похоже – ищи их на пляже..."};
tr[2696] = {H:"Спасибо за помощь!"};
tr[2697] = {OId:21,H:"Такой жаркий день, а вы не купаетесь?"};
tr[2698] = {H:"Мне некогда купаться – я очень занят..."};
tr[2699] = {H:"Не купаюсь. Я иду из Порта и ищу двух Крошек – вы, случайно, их не видели?"};
tr[2700] = {OId:21,H:"Видел. Они недавно прибегали сюда – я угостил их мороженым, а они сказали, что идут кататься на аттракционах."};
tr[2701] = {H:"Спасибо, вы мне очень помогли!"};
tr[2702] = {OId:21,H:"Мне тоже нужна помощь... Мой мяч закатился далеко в море, и я не могу его достать. Может быть, у вас есть какая-нибудь палка или сачок, чтобы подцепить мяч?"};
tr[2703] = {H:"У меня есть сачок, но я очень тороплюсь... Я приду позже и помогу вам."};
tr[2704] = {OId:21,H:"Вот и помогай после этого людям..."};
tr[2705] = {H:"К сожалению, у меня нет ничего такого..."};
tr[2706] = {OId:21,H:"Вроде в Порту у Рыбака был сачок..."};
tr[2707] = {H:"Я готов помочь!"};
tr[2708] = {OId:21,H:"Спасибо за мяч! Забирайте вот этот лимонад, он пригодится вам в дальнейшем."};
tr[2709] = {OId:21,H:"Приветствую вас! Мне нужна ваша помощь... Мой мяч закатился далеко в море, и я не могу его достать. Может быть, у вас есть какая-нибудь палка или сачок, чтобы подцепить мяч?"};
tr[2710] = {H:"Пропавшие Крошки"};
tr[2711] = {OId:22,H:"Недавно тут были Крошки – ну и хулиганы! Сломали мне информационное табло и удрали! Даже не извинились!"};
tr[2712] = {H:"Я как раз ищу этих Крошек и не знаю, куда они побежали дальше... Может быть, они оставили послание на табло? Давайте я помогу вам его починить..."};
tr[2713] = {OId:22,H:"Я тут где-то обронил гаечный ключ... И в табло не хватает шестерёнки. Найди их!"};
tr[2714] = {H:"на ватрушки"};
tr[2715] = {OId:22,H:"Ты – отличный сыщик! Идёшь по правильному пути за Крошками и скоро обязательно их догонишь!|За твою помощь я подарю тебе небольшой молоток – кто знает, что встретится на твоём пути – может быть, и мой подарок пригодится..."};
tr[2716] = {OId:18,H:"Привет! Поиграем в Ватрушки?"};
tr[2717] = {OId:23,H:"Привет! Ну и история со мной приключилась! У меня плохое зрение – без очков ничего не вижу. Сейчас куда-то положил свои очки, и теперь найти их не могу..."};
tr[2718] = {H:"Я попробую их поискать – вдруг найду."};
tr[2719] = {OId:23,H:"Вот здорово!"};
tr[2720] = {OId:23,H:"Отлично! Теперь я опять всё вижу, и этот чудо-автомобиль снова на ходу! Чем я могу тебя отблагодарить?"};
tr[2721] = {H:"Я ищу двух Крошек, и узнал, что они собирались зайти на автодром. Может, вы их видели?"};
tr[2722] = {OId:23,H:"Да, они были тут... Взяли у меня скутер и отправились в Джунгли – покататься. О! Я придумал! Забирай этот автомобиль – на нём ты быстро догонишь малышей!"};
tr[2723] = {OId:25,H:"Кто это опять отвлекает меня от важных дел?"};
tr[2724] = {H:"Вы не видели тут двух Крошек? Они провалились сюда и пропали..."};
tr[2725] = {OId:25,H:"Помню-помню, что сверху свалились два ребёнка и убежали в одну из дверей. Двери были открыты, и я не успел их остановить..."};
tr[2726] = {H:"А в какую из дверей они побежали?"};
tr[2727] = {H:"Я не отвлекаю, я ищу пропавших Крошек!"};
tr[2728] = {OId:25,H:"Тогда не буду тебе мешать, но и ты мне не мешай."};
tr[2729] = {H:"Вы, наверное, устали работать? Хотите лимонад?"};
tr[2730] = {OId:25,H:"Лимонад? Хорошая идея – лимонад я люблю!"};
tr[2731] = {OId:25,H:"У тебя ко мне какое-то дело?"};
tr[2732] = {H:"Я ищу двух Крошек. Они провалились в пещеры и пропали... Может быть, вы их видели?"};
tr[2733] = {OId:25,H:"Помню-помню, что сверху свалились два ребёнка и убежали в одну из дверей. Двери были открыты..."};
tr[2734] = {OId:25,H:"В ту, которую я пометил крестиком. Найди его с помощью лупы и иди в эту дверь. Но помни, что в пещерах нужно быть осторожным - некоторые вещи могут пригодиться в пути, а другие - запутать.  "};
tr[2735] = {H:"Простите, вы случайно не видели тут двух Крошек? Они провалились в Подземелье и пропали..."};
tr[2736] = {OId:25,H:"Я ничего не слышал про Крошек и не видел их здесь... Думаю, что тебе нужно поискать их следы в Шарараме. И ещё лучше зайти в Детсад и разузнать, что там произошло – может, другие Крошки что-то знают?"};
tr[2737] = {OId:27,H:"Эгегей! В пещерах так страшно! Впереди тебя ждут опасности! Поворачивай назад, пока не поздно."};
tr[2738] = {H:"Думаю, ты прав. Я и сам чувствую, что дальше будет ещё опаснее..."};
tr[2739] = {OId:27,H:"Нажми на тайный рубильник – и ты тут же переместишься в Шарарам."};
tr[2740] = {H:"Я не боюсь опасностей! Я должен найти Крошек! Может, ты видел их здесь?"};
tr[2741] = {OId:27,H:"Я не видел тут Крошек – наверное, они шли по другому пути."};
tr[2742] = {H:"Я должен спасти Крошек! Вы знаете, как выбраться отсюда, чтобы выйти на их след?"};
tr[2743] = {OId:27,H:"Я знаю тайное слово и могу сказать его тебе, но только в обмен на что-то полезное для меня..."};
tr[2744] = {H:"У меня нет ничего, что может вам пригодиться..."};
tr[2745] = {OId:27,H:"Тогда кодовое слово останется при мне. Прощай!"};
tr[2746] = {H:"У меня есть мягкая игрушка, и я могу отдать её вам."};
tr[2747] = {OId:27,H:"Я не люблю мягкие игрушки, предложи что-нибудь поинтереснее..."};
tr[2748] = {H:"У меня есть запасные батарейки для фонарика, и я могу отдать их вам."};
tr[2749] = {OId:27,H:"Это именно то, что мне нужно!"};
tr[2750] = {OId:27,H:"Тайное слово подземелья – " + "\"" + "Сезам" + "\"" + ", запомни его. А теперь тебе нужно вернуться обратно к развилке и попробовать пройти по другому пути. Удачи!"};
tr[2751] = {OId:26,H:"Шшшш... Хочешшшь пройти дальше – отгадай мои загадки. Ты готов?"};
tr[2752] = {H:"Я не силён в загадках."};
tr[2753] = {OId:26,H:"Тогда потренируйся получшшше и приходи снова – без загадок я не пропущу тебя дальшшше."};
tr[2754] = {H:"Я слушаю твои загадки!"};
tr[2755] = {OId:26,H:"Ты справился с моими загадками и можешшшь идти дальшшше!"};
tr[2756] = {OId:26,H:"Путь открыт – ты можешь идти дальше."};
tr[2757] = {H:"Это ловушка! Чтобы выбраться отсюда - введи тайное слово подземелья."};
tr[2758] = {H:"Я не знаю слова и хочу вернуться в Шарарам."};
tr[2759] = {OId:26,H:"Ты не справился с заданием и попался в мою ловушку! Попробуй справиться с ним снова."};
tr[2760] = {H:"Агент, ты попал в подземный колодец, из которого сложно выбраться! В лабиринте – несколько выходов. Тебе предстоит найти их и выбрать верный! Двигайся по лабиринту с помощью клавиш " + "\"" + "вперёд-назад и влево-вправо" + "\"" + ". Будь осторожен!"};
tr[2761] = {OId:25,H:"Агент, это снова ты? Ты уже знаешь дорогу – так что проходи в нужную дверь! Удачи!"};
tr[2762] = {OId:28,H:"У-у-у-у! Это кто потревожил меня и пришёл в мою пещеру без приглашенияяяяя?!"};
tr[2763] = {H:"И совсем не страшно! Уходи с моего пути, а то тебе не поздоровится!"};
tr[2764] = {OId:28,H:"Ха-ха, я-то уйду, но и ты не сможешь выбраться отсюда..."};
tr[2765] = {H:"Это я – Агент. Я пришёл освободить крошек."};
tr[2766] = {H:"Я пришёл с миром и не хочу ссориться с тобой! Я знаю, что ты хочешь казаться злым, а на самом деле – добрый!"};
tr[2767] = {OId:28,H:"Уффффффф... Тут темно и грустно... И даже поговорить нееееее с кем... Это я позвал к себе Крошек, чтобы они со мной поиграли."};
tr[2768] = {H:"Как ты смеешь, Чудище, звать в подземелья таких малышей? Уходи отсюда, иначе тебе не поздоровится!"};
tr[2769] = {OId:28,H:"Ха-ха, я-то уйду, но вы не сможете выбраться отсюда без моей помощи..."};
tr[2770] = {H:"Крошки ещё совсем маленькие, чтобы убегать в пещеры без взрослых. Я должен отправиться с ними обратно в Детский сад!"};
tr[2771] = {OId:28,H:"Фууууууууу! А как же я? Мне снова оставаться тут одному. Даже поиграть не с кем... Нееееееет, Крошки с тобой не пойдут!"};
tr[2772] = {H:"Уходи отсюда, иначе тебе не поздоровится!"};
tr[2773] = {H:"Крошки не могут долго играть с тобой, они совсем маленькие и дома их ждут Смешарики."};
tr[2774] = {OId:28,H:"Хмммм... Я покажу дорогу, и Крошки смогут уйти из пещер, но только если что-то оставят взамен..."};
tr[2775] = {H:"У нас нет ничего, что может вам пригодиться."};
tr[2776] = {OId:28,H:"Тогда оставайтесь тут!"};
tr[2777] = {H:"У меня есть скальный молоток, и я могу отдать его вам."};
tr[2778] = {OId:28,H:"Мне не нужен скальный молоток, предложи что-нибудь поинтереснее..."};
tr[2779] = {H:"У меня есть мягкая игрушка Крошек, и мы можем отдать её вам."};
tr[2780] = {OId:28,H:"Мягкая игрушка... Это – моя давняя мечта!"};
tr[2781] = {OId:28,H:"Ээээээх, как мне нравится подарок! Вы порадовали меня, и я покажу вам самый короткий путь в Детский сад!"};
tr[2782] = {OId:19,H:"Спасибо за помощь! Твоя награда - медаль и секретные смайлы."};
tr[2783] = {H:"Агент, тебя ждёт важная миссия " + "\"" + "Пропавшие Крошки" + "\"" + ". Ты можешь приступить к ней прямо сейчас. Свяжись с агентом 003, и он расскажет, что нужно сделать. "};
tr[2784] = {H:"Спасибо за помощь! Твоя награда - медаль и Крошка-супергерой."};
tr[2785] = {H:"связаться с агентом 003"};
tr[2786] = {H:"Агент, тебе была поручена миссия " + "\"" + "Пропавшие Крошки" + "\"" + ". Уже несколько дней от тебя нет никаких известий. Выйди на связь с агентом 003, он напомнит тебе суть дела."};
tr[2787] = {H:"Агент, тебя ждёт важная миссия " + "\"" + "Пропавшие Крошки" + "\"" + ". Ты можешь приступить к ней прямо сейчас. Свяжись с агентом 003, и он расскажет, что нужно сделать."};
tr[2788] = {OId:165,H:"В Шарараме потерялись два малыша. Они заскучали и решили прогуляться. Скорее найди их и верни в Детский сад!"};
tr[2789] = {H:"Тогда не буду вас отвлекать."};
tr[2790] = {H:"ок"};
tr[2791] = {H:"Обновление локации ..."};
tr[2792] = {OId:24,H:"Ты видишь, что эти ботинки никуда не годятся. Крошки побежали в Смешмаг за новыми ботинками. Торопись - ты ещё можешь их догнать!"};
tr[2793] = {OId:24,H:"Нужен второй ботинок. Пройдись ещё раз по своему пути и внимательно поищи."};
tr[2794] = {H:"Кеды Крутышки Джибера"};
tr[2795] = {H:"Фон " + "\"" + "Почта" + "\"" + ""};
tr[2796] = {H:"Это ловушка!###чтобы выбраться отсюда,###введи тайное слово подземелья."};
tr[2797] = {H:"от кого мои друзья,###убежать никак нельзя?###неотвязно в ясный день###рядом с нами бродит..."};
tr[2798] = {H:"ты за ней?###она от тебя,###ты от неё,###она за тобой."};
tr[2799] = {H:"не взять меня и не поднять,###не распилить пилой,###не вырубить и не прогнать,###не вымести метлой.###но только мне придёт пора,###сама уйду я со двора."};
tr[2800] = {H:"в горах блуждаю за тобой,###откликнусь я на зов любой.###все меня слыхали, но зато###не видал меня никто."};
tr[2801] = {H:"меня слепым зовут всегда,###но это вовсе не беда.###я под землёй построил дом,###все кладовые полны в нём."};
tr[2802] = {H:"тёплый, жёлтый колобок###поверху катается -###людям улыбается."};
tr[2803] = {H:"в пещере таится,###света боится."};
tr[2804] = {H:"все обходят это место,###камни здесь - темно и тесно,###кто-то под водой фырчит,###мышь летучая кричит..."};
tr[2805] = {H:"всю ночь летает - мышей пугает.###а станет светло - мчится в дупло."};
tr[2806] = {H:"он в дороге пригодится,###с ним не сможешь заблудиться."};
tr[2807] = {H:"ты справился с моими загадками и можешшшь идти дальшшше!"};
tr[2808] = {H:"путь открыт - ты можешь идти дальше."};
tr[2809] = {OId:25,H:"Я этого не помню..."};
tr[2810] = {H:"Чтобы открыть кодовый замок, введи секретный код!"};
tr[2813] = {OId:29,H:"Ты уже отвечал сегодня. Подготовься к уроку получше и приходи в другой день."};
tr[2814] = {OId:29,H:"Ты ошибся. Подготовься к уроку получше и приходи в другой день."};
tr[2815] = {OId:29,H:"У тебя уже есть " + "\"" + "зачёт" + "\"" + " по этому предмету."};
tr[2816] = {H:"Секретный клуб"};
tr[2817] = {H:"Барная стойка " + "\"" + "Инкогнито" + "\"" + ""};
tr[2818] = {H:"Барный шкаф " + "\"" + "Инкогнито" + "\"" + ""};
tr[2819] = {H:"Стол " + "\"" + "Шпионский" + "\"" + ""};
tr[2820] = {H:"Барный стул " + "\"" + "Инкогнито" + "\"" + ""};
tr[2821] = {H:"Диван " + "\"" + "Явка" + "\"" + ""};
tr[2822] = {H:"Кресло " + "\"" + "Явка" + "\"" + ""};
tr[2823] = {H:"Светильник " + "\"" + "Конспирация" + "\"" + ""};
tr[2824] = {H:"Часы " + "\"" + "Бонд" + "\"" + ""};
tr[2825] = {H:"Постер " + "\"" + "Шеф" + "\"" + ""};
tr[2826] = {H:"настил " + "\"" + "Секретный" + "\"" + ""};
tr[2827] = {H:"Месье Марсель"};
tr[2828] = {H:"Месье Марсель"};
tr[2829] = {H:"Керж и Вилли"};
tr[2830] = {H:"Керж и Вилли"};
tr[2831] = {H:"Приглашение в друзья.###Смешарик {0} хочет###добавить тебя в друзья.###Принять?"};
tr[2832] = {H:"твой секретный номер###{0}. для того###чтобы попасть в штаб,###необходимо получить###электронный ключ."};
tr[2833] = {H:"Тебе нужен электронный ключ. Ты найдёшь его на секретной карте агента."};
tr[2834] = {H:"###Ты заработал {0} Cмешинок,###теперь у тебя {1} {2}."};
tr[2835] = {H:"Cмешинка|Cмешинки|Cмешинок"};
tr[2836] = {OId:20,H:"Ты достоин быть секретным агентом - выполнять опасные миссии и защищать Шарарам!|Я дарю тебе рацию, на которую приходят новые задания.|Отправляйся в Штаб за первым заданием! Для того, чтобы попасть туда, тебе нужна Карта."};
tr[2837] = {H:"за картой"};
tr[2864] = {H:"Очки для монтажа"};
tr[2867] = {H:"Телепорт сломан. Чтобы попасть на ТЭЦ, нужно пройти через завал по схеме."};
tr[2868] = {OId:32,H:"Из-за урагана случился скачок напряжения, и ТЭЦ вышла из строя. Пока в Шарараме светло - станция работать на запасном генератор.| Но если не починить ТЭЦ - электричество пропадёт. Я не могу попасть на станцию - щиток закрыт деревом."};
tr[2869] = {H:"Мне тоже нужно внутрь! Я помогу тебе."};
tr[2870] = {OId:32,H:"Может быть, у тебя есть что-то, чем можно отодвинуть бревно?"};
tr[2871] = {H:"У меня есть отвёртка... Может, она пригодится?"};
tr[2872] = {OId:32,H:"Нет, отвёртка тут не поможет! Найди палку побольше."};
tr[2873] = {H:"У меня есть палка... Может, она пригодится?"};
tr[2874] = {OId:32,H:"Агент, спасибо тебе за помощь! Держи от меня нужный вещь – оно может пригодиться дальше!"};
tr[2875] = {H:"Большое спасибо!"};
tr[2876] = {OId:32,H:"Добро пожаловат на ТЭЦ! Удачи тебе!"};
tr[2877] = {H:"Насос качает воду из озера"};
tr[2878] = {H:"Вода кипит и превращается в пар"};
tr[2879] = {H:"Пар вращает турбину"};
tr[2880] = {H:"Генератор вырабатывает электроэнергию"};
tr[2881] = {H:"Ток бежит по проводам"};
tr[2882] = {H:"Фильтры чистят воду"};
tr[2883] = {H:"спустись под воду и очисти решётку"};
tr[2884] = {H:"найди детали и почини насос"};
tr[2885] = {H:"подкрути винт у генератора"};
tr[2886] = {H:"подсоедини трубу"};
tr[2887] = {OId:34,H:"Приветствую тебя на нашей станции!"};
tr[2888] = {H:"Куда же все делись?"};
tr[2889] = {OId:34,H:"Не знаю... Я тоже удивляюсь, куда же все подевались? Но моё дело – уборка! Вот я и пришла – прибраться тут..."};
tr[2890] = {H:"Ну что ж, тогда я не буду мешать."};
tr[2891] = {H:"Я пришёл сюда, чтобы помочь и устранить неполадки."};
tr[2892] = {OId:34,H:"Помочь? А  может быть, ты и мне сможешь помочь?"};
tr[2893] = {H:"Я очень занят и готов помочь, но позже."};
tr[2894] = {H:"Конечно, я готов помочь вам!"};
tr[2895] = {OId:40,H:"Я очень люблю ромашки, которые растут в Ромашковой долине. Они поднимают мне настроение. Вот бы мне один такой букетик!"};
tr[2896] = {H:"Хм... Из-за такой ерунды я не буду отвлекаться от важной миссии!"};
tr[2897] = {H:"Я обязательно помогу вам позже и принесу огромный букет ромашек."};
