tr[3732] = {H:"Агент, тебе поручается сложная миссия " + "\"" + "Охотник за привидениями" + "\"" + ". Жители Ромашковой долины просят о помощи! Отправляйся в наблюдательный пункт и поговори с агентом 003,  он введёт тебя в курс дела."};
tr[3733] = {H:"связаться с агентом"};
tr[3734] = {H:"Агент, я поручаю тебе сложную миссию " + "\"" + "Охотник за привидениями" + "\"" + ". Жители Ромашковой Долины просят о помощи. Отправляйся в наблюдательный пункт и поговори с агентом 003,  он введёт тебя в курс дела."};
tr[3735] = {OId:57,H:"В Ромашковой долине появились привидения! Агент, помоги разобраться с этим делом!"};
tr[3736] = {H:"Привидения?! Нет уж, это без меня!"};
tr[3737] = {H:"Я сейчас занят, у меня нет времени. Может, позже..."};
tr[3738] = {H:"Привидения? Да пара пустяков! Выкладывай, что знаешь!"};
tr[3739] = {OId:57,H:"Жаль, я думал, ты храбрый агент и справишься с заданием. Что ж, возвращайся, когда сможешь приступить к миссии."};
tr[3740] = {OId:57,H:"Местные жители жалуются, что по ночам их пугают привидения! Поговори с жителями, а я пока продолжу собирать информацию об этом деле."};
tr[3741] = {OId:58,H:"Я так боюсь... оно до сих пор там и не уходит из моего дома!   Я не могу спать и есть, я дергаюсь от каждого шороха! Надо... надо что-то делать..."};
tr[3742] = {H:"Успокойся, всё хорошо. Что там? Что случилось?"};
tr[3743] = {H:"Привидение! Я запер его в своём домике! Я больше не могу находиться там! Пожалуйста, помогите мне избавиться от призрака..."};
tr[3744] = {H:"Хорошо, я посмотрю, что можно сделать. Ты главное не нервничай."};
tr[3745] = {OId:58,H:"Спасибо, я уже потерял надежду, что мне кто-то поможет."};
tr[3746] = {H:"Отчёт о научной экспедиции и её сенсационных результатах."};
tr[3747] = {H:"Это невероятно! Мы были в научной экспедиции и нашли нечто удивительное! Старинный пиратский..."};
tr[3748] = {H:"...корабль на дне океана! Он сохранился практически в идеальном состоянии, несмотря на воздействие воды и времени. Ныряльщики подняли со дна старинный сундук, весь покрытый тиной и водорослями. После того как мы его открыли, мы обнаружили в нём сокровища! Золото и бриллианты - целое состояние!"};
tr[3749] = {H:"Мы были счастливы, пока... на борту не начали происходить необъяснимые явления, кто-то из моряков поговаривает, что видел привидение! Настроение в команде быстро ухудшается. Вчера вышел из строя двигатель корабля, мы были вынуждены остановиться около Маяка."};
tr[3750] = {H:"Моряки утверждают, что неладное творится из-за проклятых сокровищ и их нужно сгрузить на сушу, тогда призраки успокоятся. Мы спрятали старый сундук в пещере в горе, путь к которой указал Маяк, и случилось чудо! Двигатель заработал! Оказывается, сундук был проклят! Мы просим прощения у духов за то, что потревожили их. Надеюсь, они теперь обретут покой."};
tr[3751] = {H:"Лампочка перегорела. Замени её,### чтобы зажечь свет на маяке."};
tr[3752] = {OId:59,H:"Посетитель! Ррробот-ррработник приветствует посетителя. Что робот-ррработник может для Вас сделать?"};
tr[3753] = {H:"Мне нужна новая лампочка для Маяка, и как можно скорее!"};
tr[3754] = {OId:59,H:"Допустимая операция, ррроботу-работнику нужен образец доставляемого товаррра."};
tr[3755] = {OId:59,H:"Обрабатываю запрос... Ответ получен, заказанный Вами товаррр прибудет через несколько дней. Пожалуйста, дожжждитесь оповещения по Вашей рации."};
tr[3756] = {OId:59,H:"Заказанный Вами товаррр ещё не прибыл. Пожалуйста, дожжждитесь оповещения по Вашей рации."};
