tr[5757] = {H:"Агент! У нас пропала связь со Страной роботов. Все входы в страну заблокированы. Расследуй это дело! Лосяш поможет тебе."};
tr[5758] = {H:"К Лосяшу"};
tr[5759] = {H:"Агент! У нас пропала связь со Страной роботов. Все входы в страну заблокированы. Расследуй это дело! Лосяш поможет тебе."};
tr[5760] = {OId:91,H:" Привет! Ты пришёл узнать о космическом объекте, который я недавно обнаружил?"};
tr[5761] = {H:"В Стране роботов что-то произошло! Возможно, это связано с объектом. Я хочу посмотреть на него."};
tr[5762] = {OId:91,H:" К сожалению, он уже пропал. Но вчера около дома я нашёл капсулу, а в ней - карта звёздного неба. Вот она - на стене! Там и про роботов есть..."};
tr[5763] = {H:"Ого! Это точно имеет отношение к роботам!"};
tr[5764] = {OId:91,H:"Возможно... После того, как объект пропал, прервалась связь с роботами. Думаю, в главном компьютере Штаба есть какая-то информация об этом. Скорее в Штаб!"};
tr[5765] = {H:"Спасибо за подсказку!"};
tr[5766] = {OId:91,H:"Я всегда рад помочь! Обращайся!"};
tr[5767] = {H:"Найди в Шарараме нужные части ключа и соедини их!"};
tr[5768] = {H:"Закрыто! Доступ к кодовому замку будет возможен через 24 часа! Ты можешь попросить помощь у механика за {0} румбиков"};
tr[5769] = {H:"Ты можешь попросить помощь у механика за {0} румбиков"};
tr[5770] = {H:"Шарарам будет моим!"};
tr[5771] = {H:"Ты не сможешь мне помешать!"};
tr[5772] = {H:"Моя программа совершенна!"};
tr[5773] = {H:"Роботы подчиняются мне!"};
tr[5774] = {H:"Ещё посмотрим кто победит!"};
tr[5775] = {H:"Купить более мощное оружие для борьбы с вирусами за {0} румбиков?"};
tr[5776] = {H:"В этот раз мой план сорван... Но я ещё вернусь сюда!"};
tr[5777] = {OId:92,H:"Агент, ты победил пришельца! Получи в подарок медаль и космо-машинку! Ищи медаль на личной карточке в разделе " + "\"" + "Награды" + "\"" + "."};
tr[5778] = {H:"Угроза из космоса"};
tr[5779] = {H:"Платье Весёлая галактика"};
tr[5780] = {H:"Рубашка " + "\"" + "Космический смешок" + "\"" + ""};
tr[5781] = {H:"Бортовой журнал"};
tr[5782] = {H:"Сыграй в Космо-Боулинг"};
tr[5783] = {H:"Зябрийские подарки"};
tr[5784] = {H:"Оденься к празднику!"};
tr[5785] = {H:"Узнай свой вес"};
tr[5786] = {H:"Мы прилетели с миром! Я – капитан зябрийского космического корабля Зюзель Старший. Сейчас на планете Зябра праздник – День Межпланетного Хохота, а по праздникам у нас проходят космические дожди из подарков.|         Мы хотим вручить их жителям Шарарама в благодарность за то, что когда-то они вернули нам отличное настроение. Но вот беда, – подарки превращаются в звёздную пыль, если их пытается взять тот, кто не готов к празднику! Хочешь подготовиться к празднику и получить подарки?"};
tr[5787] = {H:"подготовиться к празднику"};
tr[5788] = {H:"5 Зябрийцев ушли гулять по Шарараму. Разыщи их, и они помогут тебе подготовиться к празднику.|Но сначала купи в капсуле в этой тарелке праздничный наряд и надень его."};
tr[5789] = {H:"Ты ещё не подготовился к празднику, поэтому если ты возьмёшь подарки сейчас – они превратятся в звёздную пыль! Взять подарки?"};
tr[5790] = {H:"Очень жаль, но твои подарки превратились в звёздную пыль. Завтра я приготовлю новые и буду ждать тебя! А пока найди моих друзей – Зябрийцев и потренируйся, чтобы завтра подготовиться к празднику как можно лучше. "};
tr[5791] = {H:"Молодец! Получай подарки и отмечай праздник с друзьями! "};
tr[5792] = {H:"У тебя уже есть подарки к этому празднику."};
tr[5793] = {H:"К праздникам мы украшаем небо Золнышками. Хочешь украсить его прямо сейчас?"};
tr[5794] = {H:"Привет! На Зябре перед праздником принято как следует подкрепиться. Хочешь сделать это прямо сейчас?"};
tr[5795] = {H:"Привет! По праздникам я пеку традиционные зябрийские оладьи. Хочешь помочь мне?"};
tr[5796] = {H:"По праздникам мы слушаем пение Зябрушек, но для этого нужно разбудить их. Хочешь услышать птичек?"};
tr[5797] = {H:"Мы, Зябрийцы, надуваем в честь праздников воздушные Планешарики и запускаем их в Космос. Хочешь присоединиться?"};
tr[5798] = {H:"Привет! Мы привезли в Шарарам праздник! Ты ещё не знаешь, как наряжаются Зябрийцы к празднику? Узнай в Летающей тарелке, и приходи снова!"};
tr[5799] = {H:"Летающая тарелка"};
tr[5800] = {H:"Хочешь узнать, сколько ты|весишь в Космосе?"};
tr[5801] = {H:"Вес не может меняться|так часто. Подкрепись и|приходи в другой раз."};
tr[5802] = {H:"Сегодня на Марсе ты весишь|25 марсианских конфет."};
tr[5803] = {H:"Сегодня на Плутоне|ты весишь 150 водяных|пузырьков"};
tr[5804] = {H:"На Комете Галлея ты весишь|половину галлейского|зёрнышка"};
tr[5805] = {H:"Сегодня ты весишь в 200 раз|меньше кирпича с Сатурна"};
tr[5806] = {H:"Твой вес на Юпитере сегодня|равен 137 снежинкам"};
tr[5807] = {H:"Твой вес сегодня -|20 сахарных астероидов"};
tr[5808] = {H:"Твой вес сегодня -|45 морковных комет и|200 морковных хвостиков "};
