tr[5857] = {H:"Ты набрал баллов: {0}.###Чтобы стать призёром фестиваля, тебе нужно набрать 200 баллов.###Попробуй сыграть ещё раз!"};
tr[5858] = {H:"Золотая Корзина|Кубок за победу в лесном чемпионате"};
tr[5859] = {H:"" + "\"" + "За борьбу с космическими захватчиками" + "\"" + "|Медаль за миссию " + "\"" + "Угроза из космоса" + "\"" + ""};
tr[5860] = {H:"Фон " + "\"" + "Мыльные пузыри" + "\"" + ""};
tr[5861] = {H:"Клуб-пещера"};
tr[5862] = {H:"Трон " + "\"" + "Канцлер" + "\"" + ""};
tr[5863] = {H:"Минеральный источник"};
tr[5864] = {H:"Лампа " + "\"" + "Сталагмит" + "\"" + ""};
tr[5865] = {H:"Табурет " + "\"" + "Изумруд" + "\"" + ""};
tr[5866] = {H:"Столик " + "\"" + "Сапфир" + "\"" + ""};
tr[5867] = {H:"Барный шкаф " + "\"" + "Витраж" + "\"" + ""};
tr[5868] = {H:"Красная дорожка"};
tr[5869] = {H:"Диван " + "\"" + "Самоцвет" + "\"" + ""};
tr[5870] = {H:"Барная стойка " + "\"" + "Скала" + "\"" + ""};
tr[5871] = {H:"Драгоценный дископол"};
tr[5872] = {H:"Зябрийский ковёр"};
tr[5873] = {H:"Крото-шоу"};
tr[5874] = {H:"Крото-шоу"};
tr[5876] = {H:"Осторожно - лихорадка!"};
tr[5877] = {H:"В Шарараме эпидемия неизвестной болезни! Доктор Бинтик просит о помощи. Скорее отправляйся в Больничку и приступай к миссии " + "\"" + "Осторожно – лихорадка!" + "\"" + ""};
tr[5878] = {H:"в Больничку"};
tr[5879] = {H:"Агент, тебе была поручена миссия " + "\"" + "Осторожно - лихорадка!" + "\"" + ". Уже несколько дней от тебя нет никаких известий. Ты должен предотвратить эпидемию неизвестной болезни!"};
tr[5880] = {OId:94,H:"Как здорово, что ты здесь! Я в отчаянии! Больных всё больше, а как их лечить – непонятно! Ни в одной медицинской книге нет описания этой болезни."};
tr[5881] = {H:"Да, проблема серьёзная! А что их беспокоит?"};
tr[5882] = {OId:94,H:"У всех очень высокая температура, сыпь, как будто после ожогов, и галлюцинации! Да ты попробуй сам у них спросить!"};
tr[5883] = {H:"Отличная идея!"};
tr[5884] = {OId:97,H:"Ох, как жарко в пустыне!"};
tr[5885] = {OId:96,H:"О, бедуин, довези меня до ручья!"};
tr[5886] = {OId:95,H:"Как прекрасно быть верблюдом..."};
tr[5887] = {OId:94,H:"Теперь ты видишь – от них ничего не добьешься. У больных помутился рассудок..."};
tr[5888] = {H:"Не падать духом! Я что-нибудь придумаю... Кстати, можно осмотреть вещи больных?"};
tr[5889] = {OId:94,H:"Вообще-то копаться в личных вещах запрещено. Но если это поможет в твоём расследовании – пожалуйста!"};
tr[5890] = {H:"Расчёска мне не понадобится."};
tr[5891] = {H:"А это, похоже, мама Крошки. Поищем что-нибудь ещё..."};
tr[5892] = {OId:94,H:"Кажется, ты нашёл улику! Может быть, стоит ещё раз поговорить с этим больным?"};
tr[5893] = {OId:97,H:"Научная экспедиция... Египет... я ищу новые источники воды... Сад... огромный райский сад! ...Кто это в небе?! Мааамочки, мне страшно! Хочу обратно в Шарарам!"};
tr[5894] = {OId:94,H:"Больному стало хуже! Его больше нельзя тревожить."};
tr[5895] = {H:"Кажется, я напал на след! Теперь я знаю, где мне продолжить расследование! Пока, Бинтик! Ещё увидимся!"};
tr[5896] = {H:"Больничка"};
tr[5897] = {H:"Египет"};
tr[5898] = {OId:98,H:"Приветствую тебя, путник! Что ты ищешь в наших краях?"};
tr[5899] = {H:"Здравствуй, Маат! Мне нужна помощь Богинь Египта!"};
tr[5900] = {H:"Это секретная информация, я не могу разглашать её."};
tr[5901] = {OId:98,H:"Как хочешь... Но помни, трудно что-то утаить от Богов..."};
tr[5902] = {OId:98,H:"Моих подруг сейчас нет здесь, верховный Бог срочно вызвал их на небо, а меня оставил следить за порядком в Египте. Но я постараюсь сделать всё, что в моих силах."};
tr[5903] = {H:"В Шарараме эпидемия неизвестной болезни. Все больные бредят и то и дело говорят о пустыне и Египте. Я решил, что причину болезни нужно искать здесь!"};
tr[5904] = {OId:98,H:"Ты пришёл по адресу! Имя того, кто раскроет тайну болезни, написано на старинном свитке. Но чтобы это имя не попало в чужие руки, я разорвала свиток на 4 части и спрятала в кувшинах. Найди части, соедини их и тебе откроется истина!"};
tr[5905] = {H:"Ты не нашёл 4 части свитка. Попробуй ещё раз."};
tr[5906] = {OId:98,H:"Теперь ты знаешь, к кому обратиться, вот только он спит глубоким сном."};
tr[5907] = {H:"Я помню, чтобы разбудить фараона, я должен выполнить задания шести богинь. Но как мне сделать это, если ты тут одна?"};
tr[5908] = {OId:98,H:"Что ж, раскрою тебе ещё одну тайну: пока богини на небе, фараона можно разбудить с помощью старинного заклинания."};
tr[5909] = {H:"Отлично! Скажи мне его!"};
tr[5910] = {OId:98,H:"К сожалению, даже Богине Истины известно не всё. Ты должен сам исследовать нашу страну и найти заклинание."};
tr[5911] = {H:"Спасибо, я постараюсь!"};
tr[5912] = {H:"Ты не будешь больше спать! Фараон, пора вставать!"};
tr[5913] = {OId:99,H:"Спасибо, что разбудил меня! За это я выполню любое твоё желание! Хочешь получить магическую способность?"};
tr[5914] = {H:"Нет, у меня к тебе более важное дело! В Шарараме эпидемия неизвестной болезни. Богиня Маат сказала, что ты знаешь о ней лучше других."};
tr[5915] = {OId:99,H:"О, горе мне! Неужели какой-то глупец вздумал нарушить границы Египта?!"};
tr[5916] = {H:"Возможно. Один больной рассказывал что-то про научную экспедицию в пустыню и про райский сад..."};
tr[5917] = {OId:99,H:"Он зашёл слишком далеко! Это старая история. Я описал её в книге, чтобы она не ушла со мной в саркофаг, если когда-нибудь я усну навечно."};
tr[5918] = {OId:99,H:"Вот так-то! Теперь ты знаешь, что тебе выпала честь разговаривать с настоящим героем!"};
tr[5919] = {H:"О, я горжусь этим! Но вернёмся к нашей проблеме. Значит, учёный в поисках источников воды покинул Египет и оказался в райском саду."};
tr[5920] = {OId:99,H:"Да, за что и был наказан!"};
tr[5921] = {H:"Я должен немедленно попасть в этот сад и увидеть Бога Ра! Ты знаешь самую короткую дорогу?"};
tr[5922] = {OId:99,H:"Одному идти в Райский сад опасно. Тебя проводит Великий Гогун. Это птица, которая прилетает на звон волшебного колокольчика. Ты сможешь найти колокольчик, разгадав загадку одной из египетских пирамид. Удачи!"};
tr[5923] = {OId:100,H:"Кто посмел звонить в волшебный колокольчик? Я сейчас съем этого наглеца!"};
tr[5924] = {H:"Кхм... это высокий рыжий Смешарик. Он пошёл вон за ту пирамиду!"};
tr[5925] = {H:"Это я звал тебя, Великий Гогун! Но прежде чем ты съешь меня, позволь рассказать тебе одну историю."};
tr[5926] = {OId:100,H:"Тогда я полечу за ним!"};
tr[5927] = {OId:100,H:"Рассказывай, да побыстрее. У меня и без тебя дел по горло!"};
tr[5928] = {H:"В далёком Шарараме беда – бог Ра наслал на Смешариков пустынную лихорадку. Бедные, у них жар и сыпь! И никто кроме тебя не может им помочь!"};
tr[5929] = {OId:100,H:" Мне жаль Смешариков! Попасть в немилость к Богу Ра – страшное горе. Когда-то и я испытал это на себе! Но чем я могу помочь?"};
tr[5930] = {H:"Отвези меня в райский сад и помоги встретиться с Ра."};
tr[5931] = {OId:100,H:"А ты смельчак! Ну хорошо, полетели!"};
tr[5932] = {OId:101,H:"Ну что, ты готов встретиться с Верховным Богом Египта?"};
tr[5933] = {H:"Конечно!"};
tr[5934] = {OId:102,H:"Я наблюдал за тобой и знаю, зачем ты пришёл! Ты смелый и умный Смешарик, но и тебе не под силу снять моё заклятие!"};
tr[5935] = {H:"О, конечно нет! Наверное, чтобы снять заклятие Верховного Бога, нужно обладать божественной силой."};
tr[5936] = {OId:102,H:"Чтобы победить болезнь, нужно уменьшиться, попасть в кровеносную систему первого больного, сразиться с вирусами с помощью раствора из пальмового сока и найти там чёрный источник болезни. Это под силу только Богам!"};
tr[5937] = {H:"Ха! На дворе 21 век! Тут не нужна божественная сила! Мне поможет наука! Думаю, в Штабе найдётся то, что уменьшит меня. "};
tr[5938] = {OId:104,H:"Как дела, агент? Удалось что-нибудь выяснить?"};
tr[5939] = {H:"Да, я разгадал тайну пустынной лихорадки! У меня есть нано-луч, с помощью которого ты уменьшишь меня и введёшь в кровеносную систему нашего учёного. Остальное я сделаю сам."};
tr[5940] = {OId:104,H:"Хороший план! Но в кровеносной системе больного много вирусов, с которыми тебе придётся сразиться. У тебя есть лекарство против них?"};
tr[5941] = {H:"Да, конечно! Это лечебный пальмовый сок, я взял его в райском саду!"};
tr[5942] = {H:"Нет. Но, кажется, Бог Ра говорил мне что-то про лекарственный сок."};
tr[5943] = {OId:104,H:"Тогда ты должен скорее найти этот сок!"};
tr[5944] = {OId:104,H:"Отлично! Приступим к делу! Давай свой нано-луч."};
tr[5945] = {OId:104,H:"Вирусы атаковали тебя, и ты совсем ослаб. Я дал тебе витамины, теперь ты можешь попробовать сразиться с ними ещё раз."};
tr[5946] = {H:"Пожалуй, на сегодня с меня хватит приключений."};
tr[5947] = {H:"Я готов сразиться с ними снова!"};
tr[5948] = {OId:105,H:"Ты избавил Смешариков от лихорадки! Дарю тебе костюм " + "\"" + "Великий Гогун" + "\"" + " и орден на Личную карточку."};
tr[5949] = {H:"" + "\"" + "Почётный доктор Шарарама" + "\"" + "|Орден за миссию " + "\"" + "Осторожно - лихорадка!" + "\"" + ""};
tr[5950] = {OId:101,H:"О Бог Ра, явись нам!"};
tr[5954] = {H:"Лесной фестиваль"};
tr[5955] = {H:"Если ты сейчас выйдешь из игры, твой соперник победит. Ты действительно хочешь выйти?"};
tr[5956] = {H:"Игра окончена, победил {0}. Ты заработал баллов: {1}"};
tr[5957] = {H:"Победила дружба! Ты заработал баллов: {0}"};
tr[5958] = {H:"Фон " + "\"" + "Клуб-пещера" + "\"" + ""};
tr[5959] = {OId:103,H:"Привет! Нам  – артистам – постоянно нужны новые инструменты. Мы давно ждём затерявшихся посылок с ними. Их привезли в Шарарам, когда был ужасный ливень, – адреса расплылись, и адресатов перепутали.|Теперь многие из нас не могут выступать, а Босс Ба-Босс хочет закрыть клубы – без шоу в них скучно. Скорее, помоги найти посылки с инструментами, и ты получишь от нас подарок!"};
tr[5961] = {H:"найти инструменты"};
tr[5962] = {OId:103,H:"Ты ещё не нашёл все посылки."};
tr[5963] = {H:"подробнее"};
tr[5964] = {OId:103,H:"Спасибо, что нашел наши инструменты! Нам осталось только настроить их, и совсем скоро ты вновь увидишь нас в клубах. Кроме того, для всех жителей Шарарама я готовлю сюрприз – концерт в Диско! Не пропусти его! За твои старания мы дарим в твой гардероб рокерскую жилетку."};
tr[5965] = {H:"взять подарок "};
tr[5966] = {OId:103,H:"Пока ты искал посылки, из Шарарама стала исчезать музыка, а у многих артистов пропали голоса. Открою тебе тайну чудесной шарманки. Это древний инструмент, который играет, наполняя звуками весь Шарарам.|Но видимо, её нужно снова завести, иначе Шарарам навсегда может погрузиться в полную тишину! Где она – никто не знает. Ты готов отыскать и завести её? За это тебя ждёт музыкальная награда."};
tr[5967] = {H:"вернуть музыку"};
tr[5968] = {H:"Ты нашёл чудесную###шарманку! Чтобы###завести её, нужен###специальный ключ-рычаг."};
tr[5969] = {H:"Ключ-рычаг уже###в шарманке.###Скорее, заведи её!"};
tr[5970] = {H:"Ты ответил###неправильно.###Постарайся завести###шарманку завтра."};
tr[5971] = {OId:103,H:"Приходи ко мне за подарком, когда заведёшь чудесную шарманку."};
