tr[6310] = {OId:116,H:"Привет! Представляешь, техника в Шарараме ожила и сбегает из домов! Весь день ловлю утюги, фены, компьютеры... Один никак не справляюсь! Поможешь мне?"};
tr[6311] = {H:"Помочь"};
