tr[8221] = {OId:132,H:"Спасибо за помощь! Я вручаю тебе костюм " + "\"" + "Летучая мышь" + "\"" + ", ищи его у себя на личной карточке в разделе " + "\"" + "Костюмы" + "\"" + ". | Но артисты всё равно не могут выступать. Почему? Это я могу рассказать только Секретному агенту. Согласен взяться за это дело?"};
tr[8222] = {OId:132,H:"Согласен!"};
tr[8223] = {OId:132,H:"Летучие мыши, которые похитили артистов, их ведь кто-то послал?"};
tr[8224] = {H:"Да, они что-то говорили про Хозяина."};
tr[8225] = {OId:132,H:"Я так и знал! Ко мне на прослушивание приходил вампир. Интересный типаж, но его номер был слабым, и я не взял его в шоу. Он разозлился и обещал отомстить!"};
tr[8226] = {H:"Думаешь, это он Xозяин мышей?"};
tr[8227] = {OId:132,H:"Уверен! Артисты вернулись, но их талант будто высосали – это тёмная магия!  Умникус обещал помочь. Он ждёт тебя в Школе магов в тайной магической комнате!"};
tr[8228] = {H:"Хорошо, поспешу к нему!"};
tr[8229] = {OId:132,H:"Пожалуйста, поспеши к Умникусу в Школу магов! Нужно срочно что-то сделать, чтобы вернуть таланты артистам!"};
tr[8230] = {OId:132,H:"Артисты пока в отпуске - набираются сил, но скоро начнут выступать! А я уже делаю с вампиром Фредди новое шоу. Он быстро учится! | За твою помощь мы награждаем тебя способностью " + "\"" + "Летучая стая" + "\"" + ", ищи её у себя на нижней панели в разделе " + "\"" + "Магия" + "\"" + ". | И орденом " + "\"" + "Победитель вампирской дуэли" + "\"" + ". Ты найдёшь его на личной карточке в разделе " + "\"" + "Мои награды" + "\"" + ""};
tr[8231] = {OId:132,H:"Спасибо тебе, агент! Артисты пока в отпуске! А я уже делаю с Вампиром Фредди новое шоу."};
tr[8232] = {H:"Я знал, что рано или поздно нас спасут! Спасибо тебе, Смешарик, мы возвращаемся в Шарарам! Отправляйся к Боссу Ба-Боссу, он наградит тебя!"};
tr[8233] = {OId:133,H:"Приветствую тебя! Снять заклятие и вернуть артистам таланты может только сам вампир. Мы вызовем его и заставим развеять чары. Ты готов?"};
