tr[8236] = {H:"Вампиры пугают меня, я лучше пойду."};
tr[8237] = {OId:133,H:"Для ритуала вызова вампира нам нужны " + "\"" + "Кристалл Сумерек" + "\"" + ", " + "\"" + "Кристалл Затмения" + "\"" + " и " + "\"" + "Кристалл Новолуния" + "\"" + "."};
