tr[16853] = {OId:150,H:"Домовой живёт в лабиринте под домиком Нюши. Найди вход в лабиринт и попробуй разыскать домового."};
tr[16854] = {OId:150,H:"Спасибо за помощь! Скоро Домовой наведёт порядок, и домики вернутся на свои места!"};
tr[16855] = {H:"подробнее"};
tr[16856] = {H:"в домик к Нюше"};
tr[16857] = {OId:150,H:"Шо тебе надо? Уходи! Теперь это мой дом! Таки да!"};
tr[16858] = {OId:393,H:"Сейчас я тут живу! Уходи, не мешай мне обед готовить!"};
tr[16859] = {OId:150,H:"Я гостей не звал! Я спать хочу! Уходи из моего домика!"};
tr[16860] = {OId:160,H:"Я тут своё волшебное перо потерял! Спасибо, что нашёл!"};
tr[16861] = {OId:160,H:"Как что? Подсыпал ему снотворное. Пусть, думаю, отдохнёт. А то тяжко."};
tr[16862] = {OId:160,H:"Ты мне перо вернёшь? А я тебе в обмен - заклинание бодрости, без него " + "\"" + "малыш" + "\"" + " не проснётся."};
tr[16863] = {OId:160,H:"Ой, какие мы добрые! Ну окей, лови своё заклинание. Всё равно ты его расшифровать не сможешь! Домики теперь навек наши! Ха-ха!"};
tr[16864] = {H:"Не стоит благодарностей! Говори, что ты делал у Домового?"};
tr[16865] = {H:"Хватит болтать! Разбуди его!"};
tr[16866] = {H:"Держи своё перо, оно мне не нужно!"};
tr[16867] = {H:"А это мы ещё посмотрим!"};
tr[16868] = {H:"Ты заработал дополнительную попытку! Попробуй прогнать нечисть из домика снова!"};
tr[16869] = {H:"Ты ещё не заработал дополнительную попытку, чтобы прогнать нечисть из домика. Попробуй ещё раз набрать 200 баллов в игре за 1 раз."};
tr[16870] = {H:"Агент, ты должен найти Домового и узнать, что с ним случилось. Что делать - подскажет иконка " + "\"" + "Домик" + "\"" + ". Удачи!"};
tr[16871] = {H:"Бездомные"};
tr[16872] = {H:"Шляпа " + "\"" + "Путешественник" + "\"" + ""};
tr[16873] = {H:"Костюм " + "\"" + "Путешественник" + "\"" + ""};
tr[16874] = {H:"Башмаки " + "\"" + "Путешественник" + "\"" + ""};
tr[16875] = {H:"Домик Ёжика"};
tr[16876] = {H:"Неизвестный материк"};
tr[16877] = {H:"Окно Ёжика"};
tr[16878] = {H:"Гербарий"};
tr[16879] = {H:"Гербарий"};
tr[16880] = {H:"Полка с книгами"};
tr[16881] = {H:"Кактус"};
tr[16883] = {H:"Лимон: {0}"};
tr[16884] = {H:"Клубная кепка"};
tr[16885] = {H:"Шоу ВИА SHARA-2 в клуб на месяц"};
tr[16886] = {H:"Шоу группы " + "\"" + "Аррр" + "\"" + " в клуб на месяц"};
tr[16887] = {H:"Не спать!"};
tr[16888] = {H:"Я обхитрил колдуна Злобикуса и разбудил домового! Приходи в Шарарам - давай играть вместе!"};
tr[16889] = {H:"Сильнее нечисти!"};
tr[16890] = {H:"Я прогнал слуг тёмного мага из Шарарама! Стань и ты героем - приходи в игру!"};
tr[16891] = {H:"Ты в бизнесе!\r\n"};
tr[16892] = {H:"Я могу сделать из тебя крутого бизнесмена! Дед оставил мне секрет успеха. Я поделюсь им с тобой: налаживай связи!"};
tr[16893] = {H:"В бизнесе мне много раз помогали... волшебники! Зайди в Школу магов."};
tr[16894] = {H:"Знакомься! Добавь {0} Смешариков в друзья."};
tr[16895] = {H:"Займись делом с новыми знакомыми. Сходи на урок волшебного карандаша в Школе Магов."};
tr[16896] = {H:"Класс! С новыми связями дела пойдут в гору! А пока - получай Смешинки."};
tr[16897] = {H:"Ты в бизнесе!"};
tr[16898] = {H:"Мой дед говорил: не имей сто Смешинок, а имей сто друзей! Один футбольный матч может принести тебе целую команду товарищей!"};
tr[16899] = {H:"Играй и общайся! Сыграй в футбол!"};
tr[16900] = {H:"Время звать всех на тусовку. Отправь {0} друзьям открыток с приглашениями."};
tr[16901] = {H:"Угости друзей вкусненьким. Найди в меню одного из клубов пиццу и купи её."};
tr[16902] = {H:"Молодец! Держи Смешинки, и не сиди без дела!"};
tr[16903] = {H:"Ты в бизнесе!"};
tr[16904] = {H:"Хобби - это выгодно! Любишь отдыхать на Пляже и искать сокровища? Смешарики с похожими интересами точно присоединятся!"};
tr[16905] = {H:"Приходи на Пляж."};
tr[16906] = {H:"Покажи, кто здесь крут - победи в игре " + "\"" + "Секретики" + "\"" + " на Пляже {0} раза."};
tr[16907] = {H:"Добавь {0} Смешариков в друзья."};
tr[16908] = {H:"Ты - король Пляжа! Получай свои Смешинки!"};
tr[16909] = {H:"Ты в бизнесе!"};
tr[16910] = {H:"Дед повторял: с активными друзьями любое дело по плечу! Будь подвижным!"};
tr[16911] = {H:"Иди в Парк аттракционов. Там всегда много подвижных Смешариков."};
tr[16912] = {H:"Выиграй {0} заезда в игре " + "\"" + "Скачки" + "\"" + " в Парке Аттракционов."};
tr[16913] = {H:"Ты - очень активный! За это полагаются Смешинки."};
tr[16914] = {H:"Ты в бизнесе!"};
tr[16915] = {H:"После работы нужно отдыхать в клубах! Тогда даже во время развлечений бизнес пойдёт в гору!"};
tr[16916] = {H:"Сходи в {0} клубов - повеселись, как следует."};
tr[16917] = {H:"Найди в меню одного из клубов торт и закажи его."};
tr[16918] = {H:"Ты - отличный бизнесмен! Держи шикарный Шарафон - будь на связи!"};
tr[16919] = {H:"Секрет успеха"};
tr[16920] = {H:"Друзья в деле"};
tr[16921] = {H:"Бизнес и хобби"};
