tr[21310] = {OId:193,H:"...А я б не отказался!.. Да шучу, шучу...;)"};
tr[21311] = {H:"Ага, знаю я таких –  обязательно съедите! Всё, я ухожу..."};
tr[21312] = {H:"Смешаричики, милые... Что ж с вами случилось?"};
tr[21313] = {OId:194,H:"Утром проснулись прозрачными..."};
tr[21314] = {OId:195,H:"Ужас, я не вижу себя в зеркале!"};
tr[21315] = {OId:193,H:"Таем на глазах!"};
tr[21316] = {H:"Так вы не нападёте на Шарарам? Тогда я вас выручу, отпразднуете Новый год при параде!"};
tr[21317] = {OId:194,H:"До Нового года я уж и не надеюсь нормальным стать... "};
tr[21318] = {OId:193,H:"Успеть бы ко Дню рождения... У нас, кстати, у всех в 1 день..."};
tr[21319] = {H:"Точно, скоро ж Новый год, а я тут болтаю... Пойду ёлку наряжу!.."};
tr[21320] = {H:"А когда у вас День рождения?"};
tr[21321] = {OId:194,H:"О, и у меня День рождения 29 февраля!"};
tr[21322] = {OId:195,H:"И у меня!"};
tr[21323] = {OId:193,H:"29 февраля! Думал, повезло – 2016 как раз Високосный... А как праздновать, если ты Призрак?"};
tr[21324] = {OId:196,H:"У меня тоже! "};
tr[21325] = {OId:197,H:"И у нас!"};
tr[21326] = {H:"Надо же, какое совпадение!"};
tr[21327] = {H:"Новогодняя шапочка"};
tr[21328] = {H:"Новогодний олень"};
tr[21329] = {H:"Новогодний стол"};
tr[21330] = {H:"Свитер с оленями"};
tr[21331] = {OId:150,H:"А ты откуда взялся? Зря что ли я Злобырям плачу за охрану входа?!.."};
tr[21332] = {H:"Ты зачем Созвездие Фисы похитил? (Ой, поздороваться забыл... Привет!) Отвечай же!"};
tr[21333] = {OId:150,H:"Хотел, чтобы мой братец Умникус исчез, а я стал глав.магом Шарарама!"};
tr[21334] = {H:"Так чего не похитил его самого? "};
tr[21335] = {OId:150,H:"Ну, похищаешь 13-ое Созвездие – и все, кто родился 29 февраля, исчезают – удобно!"};
tr[21336] = {H:"Ясно... Честно сказать, мне этот Умникус и самому надоел. Вечно спасать его..."};
tr[21337] = {H:"Ну, и Злодей же ты! Извини за комплимент..."};
tr[21338] = {OId:150,H:"Да я уж и сам не рад. Эта Фиса жонглировала даже моими запасами оливье! Забери её, ну, пожа-алуйста! "};
tr[21339] = {H:"Ладно, сейчас только расколдую..."};
tr[21340] = {H:"Снеговик-Охранник"};
tr[21341] = {H:"Возьми с собой крутого телохранителя! Ищи у себя в Аксессуарах."};
tr[21342] = {OId:150,H:"Хочешь узнать моё предсказание? Сначала поговори с Фисой на Главной площади."};
tr[21343] = {H:"К Фисе"};
tr[21344] = {H:"Призраки Нового года"};
tr[21345] = {H:"Открой Дверь в прошлое и спаси 13-ое Созвездие! Подробности – у меня на Главной площади!"};
tr[21346] = {H:"Орден " + "\"" + "С 2016!" + "\"" + "|За спасение Призраков Нового года!"};
tr[21347] = {H:"Я расколдовал Призраков!"};
tr[21348] = {H:"И праздную Новый год на Марсе. Заходи и ты в игру – получишь кучу Шарарам-подарков!"};
tr[21349] = {OId:150,H:"Оу! На мой планшет пришло сообщение от Шефа - кликни на меня!"};
tr[21350] = {OId:198,H:"Да я уж и сам не рад. Эта Фиса жонглировала даже моими запасами оливье! Забери её, ну, пожа-алуйста! "};
tr[21351] = {OId:198,H:"Ну, похищаешь 13-ое Созвездие – и все, кто родился 29 февраля, исчезают – удобно!"};
tr[21352] = {OId:198,H:"Хотел, чтобы мой братец Умникус исчез, а я стал глав.магом Шарарама!"};
tr[21353] = {OId:198,H:"А ты откуда взялся? Зря что ли я Злобырям плачу за охрану входа?!.."};
tr[21354] = {OId:193,H:"Оу! На мой планшет пришло сообщение от Шефа - кликни на меня!"};
tr[21355] = {H:"К Шефу"};
tr[21356] = {H:"СмеШутка " + "\"" + "Брокколи" + "\"" + ""};
tr[21357] = {H:"СмеШутка " + "\"" + "Железноеды" + "\"" + ""};
tr[21358] = {H:"СмеШутка " + "\"" + "Брокколи" + "\"" + "|Получи эту способность у лемура в Каньоне|Превращай Смешариков в брокколи ещё дней: {0}|Превращай Смешариков в брокколи всегда"};
tr[21359] = {H:"СмеШутка " + "\"" + "Железноеды" + "\"" + "|Ты можешь получить эту способность в Лавке колдовства!|Ты можешь применять смешутку ещё дней: {0}|Железноеды прибегут и погрызут любого Смешарика."};
tr[21360] = {H:"В машину времени!"};
tr[21361] = {H:"В прошлое Шарарама!"};
tr[21362] = {H:"В Шарарам!"};
tr[21363] = {H:"Причёска " + "\"" + "Знак вампира" + "\"" + ""};
tr[21364] = {H:"" + "\"" + "Вампирская курточка" + "\"" + ""};
tr[21365] = {H:"Причёска " + "\"" + "Вампирский стиль" + "\"" + ""};
tr[21366] = {H:"Костюм " + "\"" + "Кот-Вампир" + "\"" + ""};
tr[21367] = {H:"Причёска Дока"};
tr[21368] = {H:"Костюм Дока"};
tr[21369] = {H:"Кеды Дока"};
tr[21370] = {H:"Костюм Дока"};
tr[21371] = {H:"Причёска, одежда и кеды, как у Профессора, - для тебя! Ищи в Гардеробе."};
tr[21372] = {H:"Диск|Диск запишут через {0} мин."};
tr[21373] = {OId:201,H:"При-ивет!.."};
tr[21374] = {OId:202,H:"Йоу, Джиб!"};
tr[21375] = {H:"Опять Джиберрр пришёл..."};
tr[21376] = {OId:203,H:"Всем прив...! А мне-то кто поможет к приезду японца подготовиться?"};
tr[21377] = {H:"Я помогу!"};
tr[21378] = {H:"Кисины Уши"};
tr[21379] = {H:"Богатства Страны Пряток"};
tr[21380] = {H:"Их-хи! Привет! Я тут половину вещей из Страны Пряток Смешарикам раздарил. Нужно пополнить запасы - кое-что попрятать. Поможешь мне?"};
tr[21381] = {H:"С чего начать? С начала! Отправляйся на Пляж."};
tr[21382] = {H:"Тут всё просто. Спрячь Секретики - сыграй в игру {0} раза."};
tr[21383] = {H:"Класс! Теперь спрячь в карман Жемчужины - собери {0} штуки."};
tr[21384] = {H:"Супер! Прячь Смешинки в кошелёк - они твои!"};
tr[21385] = {H:"Богатства Страны Пряток"};
tr[21386] = {H:"Наверняка твои друзья тоже любят прятки. Вместе веселее будет, как считаешь?"};
tr[21387] = {H:"Добавь в друзья {0} Смешариков."};
tr[21388] = {H:"Напиши сообщение на Шарафон {0} Смешарикам: Спрячь что-нибудь!"};
tr[21389] = {H:"Ого! В Стране пряток куча новых вещей! Отправь друзьям {0} открытки в благодарность."};
tr[21390] = {H:"Всё круто! Смешинки твои, ты заслужил."};
tr[21391] = {H:"Богатства Страны Пряток"};
tr[21392] = {H:"Кто спецы по пряткам, - так это Питомцы. Не знал? Пф-ф-ф! Сейчас докажу."};
tr[21393] = {H:"Питомцы мастерски прячут угощение в животик. Покорми своего Питомца."};
tr[21394] = {H:"Спрячь подушку под Питомца - уложи его спать!"};
tr[21395] = {H:"Теперь Питомец бодр и рвётся в бой! Победи с ним на арене 1 раз."};
tr[21396] = {H:"По-моему, всё отлично. Держи Смешинки."};
tr[21397] = {H:"Богатства Страны Пряток"};
tr[21398] = {H:"В Стране пряток не хватает нечисти. А что? С ней веселее!"};
tr[21399] = {H:"Нечисть без позитива не поймать! Собери {0} Позитивные энергии в Шарараме."};
tr[21400] = {H:"Дождись, пока призрак появится в Шарараме и спрячь его - поймай в ловушку!"};
tr[21401] = {H:"Ну класс! Вот тебе смешинки."};
tr[21402] = {H:"Богатства Страны Пряток"};
tr[21403] = {H:"В Стране пряток сейчас обед, а холодильник пустой. Нужно спрятать какую-нибудь еду..."};
tr[21404] = {H:"Собери {0} орехов в Лесу."};
tr[21405] = {H:"Спрячь спагетти - найди его в меню одного из клубов и купи."};
tr[21406] = {H:"Ням-ням! В Стране пряток куча всего! А тебе я дарю пряточный подарок - ищи его среди своих Шарафонов!"};
tr[21407] = {H:"Прячем сокровища"};
tr[21408] = {H:"Дружеские прятки"};
tr[21409] = {H:"Питомцы-прятальщики"};
tr[21410] = {H:"Спрячь призрака!"};
tr[21411] = {H:"Пряточный обед"};
tr[21412] = {H:"Куртка с рюкзаком " + "\"" + "Анти-НЛО" + "\"" + ""};
tr[21413] = {H:"Звезда Самурая"};
tr[21414] = {H:"Японские приключения только начинаются! Беги в Дом Звёзд в Сити."};
tr[21415] = {H:"к Дому Звёзд"};
tr[21416] = {OId:207,H:"Привет, Смесяри-кири! ...Ой, Смесярики!"};
tr[21417] = {OId:206,H:"...Ну, привет, раз пришла... "};
tr[21418] = {H:"Привет!"};
tr[21419] = {OId:205,H:"...А вы, дорогуша, кто така-а-ая?"};
tr[21420] = {OId:207,H:"Я Сяо Мяо – лучсая певиса Японии! Оссень приятного познакомиса!"};
tr[21421] = {H:"Ого, а мы думали – приедет мальчик!"};
tr[21422] = {OId:207,H:"Да уж... А я ещё наряжалась... "};
tr[21423] = {OId:205,H:"Да уж... А я ещё наряжалась..."};
tr[21424] = {H:"Ничего, Сирен! Зато Джибер как рад!"};
tr[21425] = {OId:207,H:"Угосяйтесь сахарными пауками – вкусно!"};
tr[21426] = {OId:208,H:"Ой-ёу, я боюсь егоу...!"};
tr[21427] = {H:"Спасибо, я есть не хочу... Может, Сумрак поест?"};
tr[21428] = {H:"Я тебя давно жду, сеньор. Это же ты - самый смелый кабальеро в Шарараме?"};
tr[21429] = {H:"Смелый? Я?! Да я при виде лягушки под стол прячусь!"};
tr[21430] = {H:"Каба... что? Не понял... Но вообще я смелый, да."};
tr[21431] = {H:"Я охочусь за одним бандито - Эль Котище. Он очень усасен... в смысле опасен. Мне нужна помощь!"};
tr[21432] = {H:"Да ну, ещё Котища какие-то... Справляйся сам!"};
tr[21433] = {H:"Конечно, сеньор Крош! Я прикрою! Говори, что делать."};
tr[21434] = {H:"Последний раз бандито видели в клубе " + "\"" + "Кошачья таверна" + "\"" + ". Идём туда!"};
tr[21435] = {H:"Что это ещё за клуб такой?"};
tr[21436] = {H:"Магия " + "\"" + "Крутышка Джибер" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Джибера ещё дней: {0}|Ты можешь превращаться в Джибера всегда!"};
tr[21437] = {H:"Смайлики " + "\"" + "Аниме" + "\"" + ""};
tr[21438] = {H:"к Дому Звёзд"};
tr[21439] = {OId:204,H:"Спасибосо за помось! Полусяй подарок!"};
tr[21440] = {H:"получить"};
tr[21441] = {OId:150,H:"Классненько! Теперь я точно понравлюсь этому артисту! Помоги остальным приготовиться к его приезду."};
tr[21442] = {OId:150,H:"Йоу! Скоро Сяо Мяо заценит мой рэп!"};
tr[21443] = {H:"Я спас Артистов!"};
tr[21444] = {H:"Расколдовал Монстра, подружился со Звёздами и получил подарок. Заходи и ты в Шарарам."};
tr[21445] = {H:"Магия " + "\"" + "Крутышка Джибер" + "\"" + ""};
tr[21446] = {H:"Подарок для Сирены"};
tr[21447] = {OId:201,H:"Помоги моему лучшему другу Джиберу!"};
tr[21448] = {OId:202,H:"Тут Джибер задумал одно баловство... Давай, не тушуйся! Спроси у него!"};
tr[21449] = {H:"Наведи лекарство из чемоданчика!"};
tr[21450] = {H:"Орден " + "\"" + "Подвиг Самурая" + "\"" + "|За спасение Артистов от Монстра"};
tr[21451] = {H:"Займись расследованием вместе с Крошем!|За помощь Крош подарит магию!|Бонус: фасад для клуба"};
tr[21452] = {H:"Клуб с приключениями"};
tr[21453] = {H:"Ветерочек|Ветерочек подует через {0} мин."};
tr[21454] = {H:"Хр-р ням-ням... Ну мам, мне ко второму... Хрр-р"};
tr[21455] = {H:"Ха-ха! Крутая страна Шарарам, нам подходит!"};
tr[21456] = {H:"А Смешариков мы скоро выгоним!"};
tr[21457] = {H:"А Штабе СА сделаем баню!"};
tr[21458] = {H:"В Школе магов всё вверх дном перевернём!"};
tr[21459] = {H:"А на Шефе и Умникусе будем по Шарараму кататься! "};
tr[21460] = {H:"Ты освободил меня из книги. Ну и скучища там! Одни ботаники заглядывают.  "};
tr[21461] = {H:"Ты кто такой вообще? "};
tr[21462] = {H:"Класс! Я пошёл дальше творить великие дела! "};
tr[21463] = {H:"Злой дух парикмахерской! Ха-ха, шучу. Я эльф. И за спасение подарю тебе подарок."};
tr[21464] = {H:"Вау! Какой же?"};
tr[21465] = {H:"А мне ничего не надо. Да, вот такой я странный."};
tr[21466] = {H:"Это великая магия эльфов. С ней ты станешь Властелином Шарарама, самым крутым магом! Готов?"};
tr[21467] = {H:"Воу-воу-воу, полегче, эльфиша! Я УЖЕ Властелин! "};
tr[21468] = {H:"О да! Я стану самым властным! И самым симпатичным..."};
tr[21469] = {H:"Кхэрм... Кто ито пожаловал? Кто ти, маленький Смешарик? И как ти смог меня увидеть..."};
tr[21470] = {H:"Я не маленький Смешарик, я Великий маг! Я пришёл за силой деревьев."};
tr[21471] = {H:"Итак, я говорю с кустом... Кажется, мне надо поспать."};
tr[21472] = {H:"О да, я чюйствую магию эльфов. Кхэрм! Но йа должен проверить. Ответь, сколько деревьев Дремучего леса видно на карте Шарарама?"};
tr[21473] = {H:"24 дерева"};
tr[21474] = {H:"20 деревьев"};
tr[21475] = {H:"Миллион деревьев"};
tr[21476] = {H:"Пойду посчитаю"};
tr[21477] = {H:"Кхэрм... Кто ито пожаловал? Кто ти, маленький Смешарик? И как ти смог меня увидеть..."};
tr[21478] = {H:"Я не маленький Смешарик, я Великий маг! Я пришёл за силой деревьев."};
tr[21479] = {H:"Говорящая клумба а-а-а-а-а!"};
tr[21480] = {H:"О да, я чюйствую магию эльфов. Но йа должен проверить. Какие породы деревьев ти знаешь?"};
tr[21481] = {H:"Ну какие-какие... Ондатра, Мальвина, Селёдка."};
tr[21482] = {H:"Я знаю пам-пасень, бубёзу, фуфень. "};
tr[21483] = {H:"У деревьев нет пород! Они ж не собаки..."};
tr[21484] = {H:"Ольха, осина, бук. "};
tr[21485] = {H:"Буль! Думаешь, я тебе дам силу воды? Как бы не буль-буль! Самому мало!"};
tr[21486] = {H:"Почему ты такой злой?"};
tr[21487] = {H:"Ну и ладно, не надо мне ничего. Булькай дальше, я ухожу!"};
tr[21488] = {H:"Да потому что моя книга доброты испортилась! Если ты такой буль-булистый маг, исправишь книгу?"};
tr[21489] = {H:"Давай сюда свою книгу. "};
tr[21490] = {H:"Ты разрушил мой дом, а теперь хочешь разрушить весь Шарарам?"};
tr[21491] = {H:"Да тебе наверно кирпич на голову упал. Это совсем не так!"};
tr[21492] = {H:"Ой! Злобикус, прикройся! Я сейчас ослепну!"};
tr[21493] = {H:"Если не хочешь горя Шарараму, не отдавай Маэглину печать! Эльфы коварные, злобные, хитрые создания! "};
tr[21494] = {H:"Пха-ха-ха, кто бы говорил! "};
tr[21495] = {H:"Ой, да? Ну спасибо за совет, Злобикус. "};
tr[21496] = {H:"Знаю, я и сам не тортик со сливками... Но... Я люблю Шарарам! Не отдавай печать! Иначе Шарарам будет уничтожен."};
tr[21497] = {H:"Ничего подобного. Я стану властелином Шарарама, вот и всё. Так что иди поиграй в машинки. А я делом занят. "};
tr[21498] = {H:"Зря, зря ты меня не слушал! Зря, зря, зря."};
tr[21499] = {H:"Ты так и будешь зрякать? Или будем Шарарам спасать?"};
tr[21500] = {H:"Ой-ёй-ёй, как же так, я не послушал тебя! Горе мне! Ох, горюшко..."};
tr[21501] = {H:"Есть только один способ спастись от эльфов... Но это очень, очень опасно. "};
tr[21502] = {H:"Всё, я пошёл бояться под кровать!"};
tr[21503] = {H:"Говори! Я сделаю всё для Шарарама. "};
tr[21504] = {H:"Проникни в подвал нарисованного замка в книге эльфов. Там ты найдёшь спасение Шарарама - секретную страницу книги. "};
tr[21505] = {H:"Хорошо! Я пошёл!"};
tr[21506] = {H:"Я заколдовал эльфов! Они крутые маги, но я ещё круче! Приходи - в Шарараме не соскучишься!"};
tr[21507] = {H:"Они крутые маги, но я ещё круче! Приходи - в Шарараме не соскучишься!"};
tr[21508] = {H:"Взять ветерочки\r\n"};
tr[21509] = {H:"Фасад " + "\"" + "Таверна" + "\"" + ""};
