tr[21598] = {OId:209,H:"Спасибо! У меня столько дел, а безумные фанаты задержали... Я полетел искать домики Смешариков!"};
tr[21599] = {H:"удачи!"};
tr[21600] = {OId:210,H:"Ну вот и что ты наделал?!! Шеф, конечно, гений, но он не найдёт домики Смешариков. А вот мы – можем!"};
tr[21601] = {H:"Тха-х, вы что, хотите расследовать дело без Шефа?"};
tr[21602] = {OId:211,H:"Я обожаю Шефа, НО..."};
tr[21603] = {OId:212,H:"Шеф подозревает Злобырей, а мы уверены, что Ба-Босс и другие Смешарики что-то знают..."};
tr[21604] = {H:"Нууу, пряям. Ба-Босс не стал бы воровать домики."};
tr[21605] = {H:"Хм... Подозревать Ба-Босса нехорошо, но так хочется проверить..."};
tr[21606] = {OId:212,H:"Давайте создадим Лигу Героев и вернём домики быстрее Шефа!"};
tr[21607] = {OId:211,H:"Мы нормальные Герои! Честно..."};
tr[21608] = {H:"Лаадно, я в деле! Пойдёмте спросим у Смешариков, что они знают."};
tr[21609] = {H:"Странные вы... Уйду я от вас... в клуб!"};
tr[21610] = {OId:150,H:"Когда домики исчезли, я как раз был в Ромашковой долине. Но ничего это, как его... подозрительного, – кроме часов, – не заметил."};
tr[21611] = {H:"А можно посмотреть на эти часы?"};
tr[21612] = {OId:150,H:"Ну, я их дома повесил. Пойдём, покажу."};
tr[21613] = {H:"Пойдём!"};
tr[21614] = {OId:216,H:"Вот эти часы из Ромашковой долины. Они без стрелок... зато с кукушкой!"};
tr[21615] = {H:"Эх ты! Это же Совунья!"};
tr[21616] = {OId:216,H:"Ну, я в этих.. породах кукушек – не разбираюсь..."};
tr[21617] = {OId:214,H:"Извините, гражданин, а часики мы у вас временно заберём.  До выяснения дела..."};
tr[21618] = {H:"Да, часы – это... м... улика."};
tr[21619] = {OId:216,H:"Ну, во-от. Прощай, кукушечка... И пообщаться не с кем будет."};
tr[21620] = {OId:214,H:"Тхы-х! Прям, слезу вышиб... Я буду к тебе приходить!  "};
tr[21621] = {H:"Мальчики, не плачьте! Я ж тоже не железный..."};
tr[21622] = {OId:150,H:"Я был в Ромашковой долине, когда домики исчезли!"};
tr[21623] = {H:"Заметил что-то необычное?"};
tr[21624] = {OId:150,H:"Я одну штуку нашёл. Пойдём, покажу – она у меня в кабинете."};
tr[21625] = {H:"Отлично, пойдём!"};
tr[21626] = {OId:215,H:"Эту аромалампу я как раз в Ромашковой долине нашёл. Когда поджигаешь, – она пищит так забавно."};
tr[21627] = {H:"Хм, похоже, это домик Бараша. Он уменьшился...  И он горит!"};
tr[21628] = {H:"Руна Дерева"};
tr[21629] = {H:"Руна Воды"};
tr[21630] = {H:"Руна Ветра"};
