tr[21642] = {H:"Причёска Эльфа"};
tr[21643] = {H:"Кеды Эльфа"};
tr[21644] = {OId:165,H:"Мою тарелку захватили пираты веселья. По-моему, это просто... Круто! Узнай подробности у Кроша и Ёжика."};
tr[21645] = {OId:150,H:"Привет! Нас захватили весёлые пираты! Узнай подробности в Летающей тарелке и приходи снова!"};
tr[21646] = {OId:150,H:"Привет! Я в команде весёлых пиратов. Прежде, чем выполнять задание, расскажи какую-нибудь шутку."};
tr[21647] = {H:"Какие ещё шутки! Давай-ка посерьёзней!"};
tr[21648] = {H:"Ладно. Почему Тигриция научилась видеть в темноте?"};
tr[21649] = {OId:150,H:"Не знаю..."};
tr[21650] = {H:"Потому что до выключателя не дотягивается! "};
tr[21651] = {OId:150,H:"Ха-ха! Отличная шутка! Теперь ты можешь выполнять задание."};
tr[21652] = {H:"Спасибо, я старался!"};
tr[21653] = {OId:150,H:"Привет! Весёлые пираты требуют выкуп - с каждого по шуточке. Расскажешь?"};
tr[21654] = {H:"Ой, мамочка! Пираты! Пойду в сарайке спрячусь. "};
tr[21655] = {H:"Без проблем! Из чего Совунья варит самую неожиданную кашу?"};
tr[21656] = {OId:150,H:"Не знаю..."};
tr[21657] = {H:"Из пельменей!"};
tr[21658] = {OId:150,H:"Ха-ха! Это правда смешно! Теперь ты можешь выполнять задание."};
tr[21659] = {OId:150,H:"Привет! Я в команде весёлых пиратов. Расскажи мне шутку! Ой, чуть не забыл... Аррррр!"};
tr[21660] = {H:"Не буду я ничего рассказывать. Я храню свои шутки для потомков!"};
tr[21661] = {H:"Шутку? Ну ладно. Это... Ну это... Как сказать..."};
tr[21662] = {OId:150,H:"Скажи, как есть."};
tr[21663] = {H:"Ешь РТОМ! Ха-ха-ха!"};
tr[21664] = {OId:150,H:"Хи-хи! Очень смешно получилось! Теперь ты можешь выполнять задание."};
tr[21665] = {H:"Класс!"};
tr[21666] = {OId:150,H:"Привет! Я в команде весёлых пиратов. Расскажи мне шутку прежде, чем выполнять задание. "};
tr[21667] = {H:"Шуток не будет, сегодня день серьёзности!"};
tr[21668] = {H:"Да я спец по шуткам! Вот скажи, как называется, когда один Пин изобретает двигатель в домике, а второй Пин в Ромашке просит спасти Шарарам от тьмы?"};
tr[21669] = {OId:150,H:"Не знаю..."};
tr[21670] = {H:"Атака клонов!"};
tr[21671] = {OId:150,H:" Ха-ха-ха! Смешно! Теперь ты можешь выполнять задание."};
tr[21672] = {H:"Я старался!"};
tr[21673] = {OId:150,H:"Привет! Весёлые пираты требуют выкуп - с каждого по шуточке. Расскажешь?"};
tr[21674] = {H:"Мне мама не разрешает с пиратами шутить. "};
tr[21675] = {H:"Легко! Как называется вот такой шоколадный великан, который Смешариков ест?"};
tr[21676] = {OId:150,H:"Хм... Шоко-монстр же!"};
tr[21677] = {H:"А вот и нет! Это монстряка-смешариков пожирака!"};
tr[21678] = {OId:150,H:"Ах-ха-ха! Класс! Теперь ты можешь выполнять задание."};
tr[21679] = {H:"Ну наконец-то."};
tr[21680] = {H:"Спасибо!"};
tr[21681] = {H:"Стильно и магично! Ищи костюм в Гардеробе."};
tr[21682] = {OId:209,H:"Бу-бу-бу... Тьфу!.. Освободи меня, – найди здесь, в Метро, ключ от наручников, – не то они меня ...бу-бу-бу!.."};
tr[21683] = {OId:150,H:"У тебя уже есть подарки к этому празднику."};
tr[21684] = {OId:212,H:"Выясните, что знают Смешарики в Шарараме."};
