tr[21691] = {H:"стол " + "\"" + "Пиратские вкусняшки" + "\"" + ""};
tr[21692] = {H:"Весёлый попугай"};
tr[21693] = {H:"Клуб " + "\"" + "Весёлые пираты" + "\"" + ""};
tr[21694] = {H:"Повязка на глаз  " + "\"" + "Весёлый пират" + "\"" + ""};
tr[21695] = {H:"Треуголка  " + "\"" + "Весёлый пират" + "\"" + ""};
tr[21696] = {OId:150,H:"Сначала нарядись к празднику! Купи в Летающей тарелке наряд, надень его и приходи снова."};
tr[21697] = {H:"Весёлый попугай будет летать за тобой"};
tr[21698] = {H:"Заколка|Заколки привезут через {0} мин."};
tr[21699] = {OId:212,H:"Где-то тут должна быть аромалампа...."};
tr[21700] = {H:"На Съёмочную площадку!"};
tr[21701] = {H:"Страница сценария|Страница прилетит через {0} мин."};
tr[21702] = {H:"Предмет для чистки зубов дракона"};
tr[21703] = {H:"Взять страницы"};
tr[21704] = {H:"Я снимаю фильм!"};
tr[21705] = {H:"На съёмках творится что-то странное... Но это очень весело! Приходи в Шарарам - заценишь!"};
tr[21706] = {H:"Я сценарист!"};
tr[21707] = {H:"Снимаю фильм про Смешариков вместе с Крошем! Хочешь с нами? Приходи в Шарарам!"};
tr[21708] = {H:"Ты уже узнал, кто меня придумал. Найди остальные странности."};
tr[21709] = {H:"Ты уже узнал, кто это придумал. Найди остальные странности."};
tr[21710] = {H:"Поговори с Вождём на Пляже! А мы тут подождём."};
tr[21711] = {H:"На Пляж"};
tr[21712] = {OId:217,H:"Ёлки-иголки! Это ж говорящая морковь-великан! Откуда она взялась?!"};
tr[21713] = {OId:220,H:"Да, это я! Сидела себе на грядке... И тут - ПУФ - я тут."};
tr[21714] = {H:"Ой-ой! Колдовство! Мне страшно, я побежал!"};
tr[21715] = {H:"Я в шоке! Я только про неё подумал и тут... Она появилась!"};
tr[21716] = {OId:217,H:"Это очень странно! Кажется, твоя мысль сразу сбылась! Нужно выяснить, почему это случилось."};
tr[21717] = {OId:220,H:"Делайте, что хотите. Кроме морковного пирога..."};
tr[21718] = {OId:217,H:"Ёлки-иголки! Это ж Змей Горыныч! Откуда он взялся?!"};
tr[21719] = {OId:219,H:"Ребят, что творится? Я на пляже в Тридесятом царстве загорал, и вдруг - ПУФ! - тут оказался."};
tr[21720] = {H:"Ой-ой! Колдовство! Мне страшно, я побежал!"};
tr[21721] = {H:"Я в шоке! Я только про тебя, Змей, подумал и тут... Ты появился!"};
tr[21722] = {OId:217,H:"Это очень странно! Кажется, твоя мысль сразу сбылась! Нужно выяснить, почему это случилось."};
tr[21723] = {OId:219,H:"Ребят, а побыстрее можно? А то мой шезлонг займут!"};
tr[21724] = {H:"Сейчас разберёмся!"};
tr[21725] = {OId:217,H:"Ёлки-иголки! Это ж бабушка Нюши! Откуда она взялась?!"};
tr[21726] = {OId:218,H:"Ась?! Вы чего, внучки, кушать хотите? Я вам пирожков сейчас напеку... Где тут моя духовка-то?"};
tr[21727] = {H:"Ой-ой! Колдовство! Мне страшно, я побежал!"};
tr[21728] = {H:"Я в шоке! Я только про неё подумал и тут... Она появилась!"};
tr[21729] = {OId:217,H:"Это очень странно! Кажется, твоя мысль сразу сбылась! Нужно выяснить, почему это случилось."};
tr[21730] = {OId:218,H:"... да где ж тут моя духовка-то..."};
tr[21731] = {H:"Сейчас разберёмся!"};
tr[21732] = {OId:221,H:"Вы видели это?! Видели?!"};
tr[21733] = {OId:222,H:"Да, это п-п-просто чудо."};
tr[21734] = {H:"Так, стоп. Давайте по очереди."};
tr[21735] = {OId:223,H:"Раз в фильме есть туземцы - нужна пирамида. Из клубов, конечно!"};
tr[21736] = {OId:224,H:"Обычные драконы - это скучно... Лучше дракон из сладкой ваты!"};
tr[21737] = {H:"Так-так-так..."};
tr[21738] = {OId:221,H:"Я решила, что у диких туземцев должна быть дикая одежда."};
tr[21739] = {OId:222,H:"А у меня Бараш все конфеты съел! Гусеница прожорливая! Я решил, пусть будет гусеницей в фильме!"};
tr[21740] = {H:"Я уже понял - все наши придумки про фильм ожили! Но как?! Как это вышло?"};
tr[21741] = {OId:223,H:"Не знаю. Я ел бутер, когда всё случилось. Вождь туземцев угостил."};
tr[21742] = {OId:224,H:"Милый хамелеончик. Я с ним тоже сегодня виделась!"};
tr[21743] = {OId:222,H:"Мы с вождём как раз обсуждали, какой Бараш обжора, когда появилась Гусеница!"};
tr[21744] = {H:"Всё понятно! Вождь туземцев сделал всё это! Но зачем?"};
tr[21745] = {OId:225,H:"Иди и спроси у него. Он как раз обедает на Пляже."};
tr[21746] = {H:"Бегу!"};
tr[21747] = {H:"Приветик! Как продвигается сценарий фильма?"};
tr[21748] = {H:"Отлично! Но я пришёл позагорать, так что не мешай."};
tr[21749] = {H:"Кто-то оживляет всё, что мы придумываем. Не знаешь случайно, кто?"};
tr[21750] = {H:"Случайно знаю. Это я! Классно, правда?"};
tr[21751] = {H:"Да, очень! Побегу ещё полюбуюсь на Рогатую гусеницу!"};
tr[21752] = {H:"Не пойму, зачем ты это сделал? Фантазии появились в Шарараме и пугают Смешариков!"};
tr[21753] = {H:"Упс! Я слышал, вы придумываете сценарий. И сделал, чтобы фантазии сбылись - раз их - и сразу в кадр!"};
tr[21754] = {H:"Но ведь не все наши фантазии попадут в фильм!"};
tr[21755] = {H:"Хммм... Ну ладно. Проведи кастинг - оставь того, кто пригодится в кадре. А остальных я верну на место!"};
tr[21756] = {H:"Хорошая идея! Давай так и сделаем!"};
tr[21757] = {H:"Тогда беги на съёмочную площадку и начинай!"};
tr[21758] = {H:"Ок, я побежал!"};
tr[21759] = {OId:213,H:"Вон, видишь, часы какие красивые!"};
tr[21760] = {OId:212,H:"Спроси Сэнсэя, как увеличить домики Смешариков."};
tr[21761] = {H:"Приветствую! Я ищу героя Египта! Не знаешь, кто бы мог им быть?"};
tr[21762] = {H:"Знаю! Это доктор Бинтик! Он самый геройский-герой! "};
tr[21763] = {H:"Спасибо! Сейчас пошлю ему папирус на емеил. Спрошу, сможет ли он мне помочь."};
tr[21764] = {H:"Что ты ко мне с глупыми вопросами пристаёшь?! Я позагорать пришёл!"};
tr[21765] = {H:"Так это ж я! Смотри, у меня и лицо геройско-египетское!"};
tr[21766] = {H:"Увеличивающий луч"};
tr[21767] = {H:"О, горе мне, горе!.."};
tr[21768] = {H:" Не время нюни распускать! Тьфу, противно..."};
tr[21769] = {H:"Что случилось?! На нас летит Астероид?!!"};
tr[21770] = {H:"Не ем, не пью.. Скучаю по одной прекрасной... А она в Космосе... Но т-сс.. это тайна!"};
tr[21771] = {H:"Извини, я в любовь не верю. Сходи поешь, и всё пройдёт."};
tr[21772] = {H:"Ну, не томи! Рассказывай. Может, я помогу чем?"};
tr[21773] = {H:"Я задумал лазерное шоу с фонариками для своей возлюбленной! Пойдём, поможешь – я тут в одном клубе уже всё подготовил..."};
tr[21774] = {H:"О, а что за клуб?!!"};
tr[21775] = {H:"СмеШутка " + "\"" + "Любоффь!" + "\"" + "|Участвуй в приключениях в клубе для влюблённых и сможешь влюблять в себя Смешариков|Ты можешь влюблять в себя Смешариков ещё дней: {0}|Ты можешь влюблять в себя Смешариков всегда"};
tr[21776] = {H:"СмеШутка " + "\"" + "МегаЛуч" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь увеличивать Смешариков ещё дней: {0}|Ты можешь увеличивать Смешариков  всегда!"};
tr[21777] = {H:"Орден-Дом|от Благодарных Смешариков!"};
tr[21778] = {H:"Я – в Лиге Героев!"};
tr[21779] = {H:"Я вернул домики Смешарикам и получил подарки. Приходи и ты в Шарарам!"};
tr[21780] = {H:"Заброшенное метро"};
tr[21781] = {OId:212,H:"Наведи лупу на мост в Ромашковой долине!"};
tr[21782] = {OId:212,H:"Найди МегаЛуч в Шарараме и увеличь домики и Пина."};
tr[21783] = {H:"Помири феечек!"};
tr[21784] = {H:"Привет! У меня беда - все мои сёстры-феи перессорились! Помоги нам помириться, пожалуйста."};
tr[21785] = {H:"Моя сестра, фея Доброты, прячется в Детском саду. Беги туда!"};
tr[21786] = {H:"Ей будет приятно, если мы будем добрее. Поработай няней в Детском саду."};
tr[21787] = {H:"Отправь {0} Смешарикам открытку: Поиграй с Крошками в Детском саду!"};
tr[21788] = {H:"Сестрёнка прислала смс - она больше не дуется! Спасибо, бери Смешинки."};
tr[21789] = {H:"Помири феечек!"};
