tr[21791] = {H:"Не послала ли она цунами!? Загляни в подзорную трубу на Пляже."};
tr[21792] = {H:"А подводные течения спокойны? Посмотри в Перископ в Порту!"};
tr[21793] = {H:"Нет ли вихрей в открытом море? Посмотри - прокатись на Катере в Порту."};
tr[21794] = {H:"Море спокойно, значит сестра не дуется! Эти Смешинки для тебя."};
tr[21795] = {H:"Помири феечек!"};
tr[21796] = {H:"Моя третья сестра - Фея Веселья - никогда не унывает. Но сегодня, кажется, она обиделась не на шутку... Давай поднимем ей настроение?"};
tr[21797] = {H:"Затуси как следует - зайди в {0} клубов."};
tr[21798] = {H:"Напиши {0} Смешарикам сообщения на Шарафон - пригласи их в клубы."};
tr[21799] = {H:"Фея Веселья оценила нашу вечеринку и больше не дуется! Лови Смешинки!"};
tr[21800] = {H:"Помири феечек!"};
tr[21801] = {H:"Моя четвёртая сестра - Песочная Фея - зарывается в песок, когда ей грустно. И ни с кем не разговаривает..."};
tr[21802] = {H:"Отправь ей подарки - закопай Секретики на Пляже {0} раза."};
tr[21803] = {H:"Сестрёнка обожает мороженое! Приготовь - заработай {0} смешинок в Кафе."};
tr[21804] = {H:"Хочу отправить ей цветы - собери {0} цветов в Турфирме."};
tr[21805] = {H:"Чудно! Моя сестра, Песочная фея, больше не дуется. Смешинки твои."};
tr[21806] = {H:"Помири феечек!"};
tr[21807] = {H:"Ура! Мои сёстры хотят мириться и приглашают меня на ужин в клуб! Поможешь мне подготовиться?"};
tr[21808] = {H:"Выбери мне наряд - сыграй в игру " + "\"" + "Студия моды" + "\"" + " в Доме мод."};
tr[21809] = {H:"Чуть не забыла про украшения! Собери {0} жемчужины на Пляже."};
tr[21810] = {H:"Спасибо! Ты помирил нас - феечек и за это я дарю тебе чудесные сандалии!"};
tr[21811] = {H:"Феечки надулись!"};
tr[21812] = {H:"Успокой Фею моря"};
tr[21813] = {H:"Фея Веселья грустит?"};
tr[21814] = {H:"Порадуй песочную Фею"};
tr[21815] = {H:"Подарок от Феечек!"};
