tr[21853] = {OId:226,H:"Что? А? Ничего не слышу... Кажется, я сломался!  Помоги - найди в Ромашковой долине мою ушную шестерёнку и отдай её мне."};
tr[21854] = {OId:226,H:"Что говоришь? Нет, это не та шестерёнка. Ищи лучше!"};
tr[21855] = {OId:226,H:"Это Пин обронил, не я. Давай-ка ещё поищи."};
tr[21856] = {OId:226,H:"Не хочу тебя расстраивать, но, кажется, это твоя ушная шестерёнка. А мою ты ещё не нашёл. "};
tr[21857] = {OId:226,H:"Да ты что?! Если я эту железяку в голову вставлю...лучше тебе не знать, что произойдёт! Ищи дальше."};
tr[21858] = {OId:150,H:"Ауч, температур этой вода – 220 вольт!"};
tr[21859] = {H:"О-оо, надо взять на заметку – не нырять в мороз без шапки..."};
tr[21860] = {H:"Пин, родненький! Что ж тобой мороз сделал!... Температуру меряют в градусах..."};
tr[21861] = {OId:150,H:"Я-я, ты такой умный...\nНо как мне твои слова помогать ловить этих водяных бабочка?"};
tr[21862] = {H:"Это рыба... Пинчик, я научу тебя ловить её, пока ты совсем от холода с ума не сошёл!"};
tr[21863] = {OId:150,H:"Хр-рясь, щщёлк!\nО, подожди, ты у меня на десерт! Сейчас только съем эту зебру! Р-ррв..."};
tr[21864] = {H:"Не ешь её! Это же Дора..."};
tr[21865] = {OId:150,H:"Так тем более!\nДора – вкуснее Помидора!\nАхх-аха! Р-рв.. Ой, жарааа..\nой, дичаюююю..."};
tr[21866] = {H:"Да-а, тяжёлый случай..."};
