tr[21873] = {H:"СмеШутка " + "\"" + "Видяшка" + "\"" + ""};
tr[21874] = {H:"СмеШутка " + "\"" + "Видяшка" + "\"" + "|Получи эту способность у лемура в Каньоне!|Ты можешь снимать видяшки про Смешариков ещё дней: {0}|Ты можешь снимать видяшки про Смешариков всегда! "};
tr[21875] = {H:"Вот это розыгрыш!"};
tr[21876] = {H:"Привет! В Шарараме завёлся злой шутник! Смешарики жалуются, что их кто-то обидно разыгрывает. Нужно им помочь!"};
tr[21877] = {H:"Попробуем найти обидчика. Отправляйся на Пляж."};
tr[21878] = {H:"Посмотри в подзорную трубу."};
tr[21879] = {H:"Не видели ли его в кафе? Сыграй в Кафе " + "\"" + "Улыбка" + "\"" + " на Пляже."};
tr[21880] = {H:"Кажется, я его заметил! Лови Смешинки и бежим!"};
tr[21881] = {H:"Вот это розыгрыш!"};
tr[21882] = {H:"Пока мы искали шутника на Пляже, он подложил петарду Барашу в чернильницу! Нужно помочь поэту."};
tr[21883] = {H:"Чернила у Бараша вылились. Сделаем новые, из орехов. Собери {0} орехов в Лесу."};
tr[21884] = {H:"А бумага?! Пусть пишет на флаерсах! Собери {0} штуки в Клубном квартале."};
tr[21885] = {H:"Чтобы Бараш не грустил, нужен позитив! Собери {0} Позитивные энергии в Шарараме."};
tr[21886] = {H:"Барашу помогли, отлично. Держи Смешинки!"};
tr[21887] = {H:"Вот это розыгрыш!"};
tr[21888] = {H:"И Нюшу кто-то разыграл. Прислал ей килограмм конфет, а там только фантики пустые! Нюша плачет..."};
tr[21889] = {H:"Угости Нюшу. Найди чизкейк в меню одного из клубов и купи."};
tr[21890] = {H:"Отвлеки Нюшу от грустных мыслей, напомни про веселье. Зайди в {0} клубов."};
