tr[21898] = {H:"Вот это розыгрыш!"};
tr[21899] = {H:"Да, это я всех разыграл. А что? Так скучно быть тихоней! Я думал, будет весело. Но все на меня обиделись..."};
tr[21900] = {H:"Помоги Ёжику помириться со всеми. Напиши в общий чат: Ёжик просит прощения!"};
tr[21901] = {H:"Приготовь праздничный пирог из ягод. Заработай {0} Смешинок в игре " + "\"" + "Дары леса" + "\"" + "."};
tr[21902] = {H:"Спасибо! Друзья меня простили и объяснили, что нужно шутить добрее. Вот тебе подарок за помощь!"};
tr[21903] = {H:"Следы шутника"};
tr[21904] = {H:"Бедняга Бараш!"};
tr[21905] = {H:"Конфеты для Нюши"};
tr[21906] = {H:"Розыгрыш для Кроша"};
tr[21907] = {H:"Тайное стало явным"};
tr[21908] = {H:"Магия " + "\"" + "СуперДжип" + "\"" + ""};
tr[21910] = {H:"Магия " + "\"" + "СуперДжип" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь кататься на СуперДжипе ещё дней: {0}|Ты можешь кататься на СуперДжипе всегда!"};
tr[21911] = {H:"Камера будет летать за тобой!"};
tr[21912] = {OId:150,H:"О, молодец, что пришёл! Собирайся, идём охотиться на Смешариков."};
tr[21913] = {H:"Круто! Сейчас только ружьё найду..."};
tr[21914] = {H:"Не надо на них охотиться, они не звери! Просто, одичали от того, что в дикие места попали..."};
tr[21915] = {OId:150,H:"Ну, так! Это я специально климат поменял – по дедовой карте диких мест.\nА то в Лесах да Джунглях совсем зверья не осталось."};
tr[21916] = {H:"Вау, менять климат – круто!!! Пойду-ка в Школу магов – может тоже волшебному чему научусь..."};
tr[21917] = {H:"А как теперь обратно хорошую погоду сделать?.. А то Смешарикам тяжело жить будет..."};
tr[21918] = {OId:150,H:"А это я скажу, если ты мне на охоте поможешь...\nО, гляди, Дора побежала! Сейчас мы её..."};
tr[21919] = {H:"Не-ет, прошу, не стреляяяяй!..."};
tr[21920] = {H:"У-у, вредина, не хочешь – не говори, шкура ты беличья! Без тебя разберёмся как-нибудь."};
tr[21921] = {H:"А, что-то мне не охота на охоту..."};
tr[21922] = {H:"Жёлтая тельняшка"};
tr[21923] = {H:"Пиратские легенды"};
tr[21924] = {H:"Ар-р-р! Мы - пираты - иногда сильно тоскуем по суше. Даже складываем о ней легенды. Я расскажу парочку. Проверь, правдивы ли они!"};
tr[21925] = {H:"Пираты верят: в песке каждого пляжа есть сокровища. Проверь! Сыграй в Секретики."};
tr[21926] = {H:"Собери {0} Жемчужины на Пляже."};
tr[21927] = {H:"А ведь эта легенда правдива! Лови Смешинки!"};
tr[21928] = {H:"Пиратские легенды"};
tr[21929] = {H:"Пираты верят, что снег лечит грусть. Как ты думаешь, это правда? Давай проверим."};
tr[21930] = {H:"Отправляйся на Снежную гору."};
tr[21931] = {H:"Выиграй на Сноуборде 1 раз."};
tr[21932] = {H:"Прокатись на Ватрушках на Снежной горе."};
tr[21933] = {H:"Так весело! Значит, легенда - правда. Забирай Смешинки."};
tr[21934] = {H:"Пиратские легенды"};
tr[21935] = {H:"В одной из пиратских легенд сказано, что морские монстры выходят из моря и танцуют сухопутные танцы. Проверим?"};
tr[21936] = {H:"Зайди в {0} клубов."};
tr[21937] = {H:"Напиши в общий чат: Морских монстров не видели?"};
tr[21938] = {H:"Запах еды привлечёт монстров. Найди оливье в меню одного из клубов и купи!"};
tr[21939] = {H:"Никаких морских монстров! Эта легенда - вымысел! Возьми Смешинки."};
tr[21940] = {H:"Пиратские легенды"};
tr[21941] = {H:"Юнгам рассказывают истории про драгоценные цветы и плоды, которые растут на суше. Поищем их?"};
tr[21942] = {H:"Собери {0} фиалки в Джунглях."};
tr[21943] = {H:"Собери грибы и ягоды - заработай {0} Смешинок в игре " + "\"" + "Дары леса" + "\"" + "."};
tr[21944] = {H:"Собери {0} груш в Ромашковой долине."};
tr[21945] = {H:"Земные плоды не из золота! Но пираты считают их драгоценными, ведь в море их нет... Лови Смешинки!"};
tr[21946] = {H:"Пиратские легенды"};
tr[21947] = {H:"А какие легенды вы, сухопутные, складываете про пиратов? Интересно послушать."};
tr[21948] = {H:"Добавь в друзья {0} Смешариков."};
tr[21949] = {H:"Напиши сообщение на Шарафон {0} Смешарикам: Расскажи легенду о пиратах!"};
tr[21950] = {H:"Мне понравилось изучать легенды с тобой! Йо-хохо, держи подарок!"};
tr[21951] = {H:"Золотые берега"};
tr[21952] = {H:"Снежинки от грусти"};
tr[21953] = {H:"Где прячутся морские монстры?"};
tr[21954] = {H:"Драгоценные плоды"};
tr[21955] = {H:"Легенды о пиратах"};
tr[21956] = {H:"СмеШутка " + "\"" + "Вас снимают!" + "\"" + ""};
tr[21957] = {H:"СмеШутка " + "\"" + "Вас снимают!" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь фотографировать Смешариков ещё дней: {0}|Ты можешь фотографировать Смешариков всегда"};
tr[21958] = {H:"Морковка|Морковка вырастет через {0} мин."};
tr[21959] = {H:"О, вот ты где!         Моя машина как раз подготовлена к старту. Идём внутрь!"};
tr[21960] = {H:"Пошли!"};
tr[21961] = {H:"Эй! Не тыкай!"};
tr[21962] = {H:"Я тут вишу вообще-то..."};
tr[21963] = {H:"Что он себе позволяет?!"};
tr[21964] = {H:"Охохо! Злобски много работы! Поговори с Шефом на Злобной площади."};
tr[21965] = {OId:232,H:"Привет! Я Макс, внук Дока. Приятно познакомиться!"};
tr[21966] = {H:"Привет. А теперь извини - я пошёл играть в няню!"};
tr[21967] = {H:"Привет! Но ты же был заколдован, превращён в Железноеда. Как тебя расколдовали?"};
tr[21968] = {OId:231,H:"Это было легко! Сингулярный искажатель, катализатор... Но, честно говоря, раньше он был симпатичнее!"};
tr[21969] = {OId:232,H:"Дедушка, ну хватит надо мной прикалываться!"};
tr[21970] = {H:"Сингулярный искажатель? Кажется, я сломал мозг... Пойду чинить."};
tr[21971] = {H:"Ясно. Макс, слушай... А почему у тебя дуршлаг на голове?"};
tr[21972] = {OId:231,H:"А это Максим думает, что так люди в будущем одеваются... Хочет смешаться с толпой. Видимо, с толпой сумасшедших, хи-хи."};
tr[21973] = {OId:232,H:"Дедушка! Хватит надо мной прикалываться!!!"};
tr[21974] = {H:"Значит, вы правда летите в будущее Шарарама? А зачем?"};
tr[21975] = {H:"Привет! Классная машина у тебя!"};
tr[21976] = {H:"Да, классная. Сяду на неё и уеду отсюда, а то тут всё какое-то странное."};
tr[21977] = {H:"Привет. Шеф! Что с тобой?!! Почему ты тренируешь Злобырей?"};
tr[21978] = {H:"Ты что, с жирафа свалился?"};
tr[21979] = {H:"Я не с жирафа, я из прошлого, из 2018 года - вон машина времени стоит."};
tr[21980] = {H:"Тогда понятно. Злобикус ещё в 2020 году украл волшебный шар Умникуса."};
tr[21981] = {H:"Класс! Вот молодец Злобикус!"};
tr[21982] = {H:"Какой ужас! И что было дальше?"};
tr[21983] = {H:"Теперь Злобикус властелин Шарарама... От этого все Смешарики страдают. Злобикус заставляет нас делать то, что мы не хотим!"};
tr[21984] = {H:"Я помогу вам!"};
tr[21985] = {OId:233,H:"Злобикус развеял магическую защиту Умникуса. Значит, защитить шар помогут старые добрые ловушки!"};
tr[21986] = {OId:234,H:"Класс! Шар спасём  и заодно посмеёмся!"};
tr[21987] = {H:"Я против ловушек! Пусть Злобикус забирает шар, мне не жалко."};
tr[21988] = {H:"Но Злобикус уже украл шар. Нужно отлететь на пару часов назад и приготовить ему сюрприз!"};
tr[21989] = {OId:233,H:"Да! Прыгаем в машину времени!"};
tr[21990] = {H:"Вперёд!"};
tr[21991] = {H:"В будущее Шарарама"};
tr[21992] = {H:"Вернуться в Шарарам настоящего!"};
tr[21993] = {H:"В Злобашковую долину"};
tr[21994] = {H:"На Злобную площадь"};
tr[21995] = {H:"Подойдёт для ловушки Дока"};
tr[21996] = {H:"Если ты выйдешь, водопровод придётся строить заново. Хочешь выйти?"};
tr[21997] = {H:"Взять морковку"};
tr[21998] = {H:" Я летал на машине времени в 2020 год и круто провёл время! Приходи в Шарарам - тут не соскучишься!"};
tr[21999] = {H:"Я летал на машине времени в 2020 год и круто провёл время! Приходи в Шарарам - тут не соскучишься!"};
