tr[22037] = {H:"Стань хозяином огромного котэ!|Удиви друзей пушистым домиком!|Кресла в комплекте!"};
tr[22038] = {OId:150,H:"Это я, Бараш! Я застрял в теле Совуньи!\nБе-е-езобразие! Вместо рифм одни борщи в голову лезут."};
tr[22039] = {H:"Ну и отлично, борщи-то лучше, чем стихи! Сытнее! "};
tr[22040] = {H:"Ужас! Я со всем разберусь, обещаю. Скажи, ты был на Съёмочной площадке во время происшествия? "};
tr[22041] = {OId:150,H:"Да, я как раз играл роль гусеницы. Грыз забор. "};
tr[22042] = {H:"Нюша сказала, что Крош пропал. Ты знаешь, где он?"};
tr[22043] = {OId:150,H:"Нет, но... Крош прислал мне странную СМСку перед исчезновением. Хочешь, покажу?"};
tr[22044] = {H:"Конечно, давай!"};
tr[22045] = {OId:150,H:"Хлепусе мёпусе ё?!! Шлумба-тумба шмусь! Бумбосик!!!"};
tr[22046] = {H:"Понял, понял! Уже ухожу! "};
tr[22047] = {H:"А-а-а! Крош сошёл с ума! Спасайся кто может! "};
tr[22048] = {H:"Э-э-э, что?"};
tr[22049] = {OId:150,H:"Ты поможешь мне, да?!! Я прыгучий ушан! Кошмар!!!"};
tr[22050] = {H:"Ты слишком нервный. Успокойся, потом поговорим."};
tr[22051] = {H:"Спокойно! Расскажи по порядку, что произошло."};
tr[22052] = {OId:150,H:"Я снимался в кино. А потом ж-ж-ж, вспышка! Сияние! Бух-бах! И вот я тут. В теле кролика."};
tr[22053] = {H:"Никогда не слышал ничего более бредового! Я ухожу."};
tr[22054] = {H:"Понятно, ты растерян. А может, ты заметил что-то необычное перед происшествием?"};
tr[22055] = {OId:150,H:"Хм-м... Да, я кое-что заметил. Но может быть, это не важно..."};
tr[22056] = {H:"Ну, говори же скорее!"};
tr[22057] = {OId:150,H:"Привет! Это я, Совунья. Если тебе нужен туземец, то он в теле Кроша. А где Крош - это вопрос..."};
tr[22058] = {H:"Так, поиски зашли в тупик! Пойду лучше поищу маму."};
tr[22059] = {H:"Я смотрю, ты в курсе событий. Может, ты заметила что-то необычное?"};
tr[22060] = {OId:150,H:"Конечно, заметила! Смешарики поменялись телами!"};
tr[22061] = {H:"ДА ЛАДНО?!! Вот это да! Нужно пойти всё обдумать."};
tr[22062] = {H:"Так. Я нашёл обрывки схемы. Что тут за штуковина нарисована?"};
tr[22063] = {OId:150,H:"Это " + "\"" + "Улучшайзер" + "\"" + " — его Лосяш для съёмок сделал. Он берёт способности одних Смешариков и даёт другим."};
tr[22064] = {H:"Интересно. А кто эти Смешарики рядом с Улучшайзером?"};
tr[22065] = {OId:150,H:"Вот что. Я подскажу тебе, если ты попробуешь мой пирог. У Туземцев совсем нет вкуса... Они считают главной вкуснятиной крапиву!"};
tr[22066] = {H:"Класс! Обожаю пробовать пироги!"};
tr[22067] = {H:"В машину времени!"};
tr[22068] = {H:"Магия " + "\"" + "Шеф Будущего" + "\"" + ""};
