tr[22080] = {H:"Комод " + "\"" + "Хамелеончик" + "\"" + ""};
tr[22081] = {H:"Диван " + "\"" + "Хамелеончик" + "\"" + ""};
tr[22082] = {H:"Хамелеончик домашний"};
