tr[22087] = {H:"Туземное окно"};
tr[22088] = {OId:150,H:"Добро пожаловать на тайную гору туземцев!\nУ нас тут много классных вещей — выбирай."};
tr[22089] = {OId:235,H:"О, привет! Морковки хочешь?!!"};
tr[22090] = {H:"Нет, спасибо, я лучше пойду!"};
tr[22091] = {H:"Крош, это ты?!!"};
tr[22092] = {OId:236,H:"Да, а как ты догадался?"};
tr[22093] = {OId:237,H:"Ларочка, дорогая, опять ты за своё!"};
tr[22094] = {H:"А ты, зубастый, кто такой?"};
tr[22095] = {OId:238,H:"Я Дизель. А это моя жена, Лара. Она немного того, болеет. Кроликом себя считает."};
tr[22096] = {H:"Как-то вы подозрительно похожи на ребят на схеме, которую я нашёл."};
tr[22097] = {OId:236,H:"Да, ты прав. Это бобры настроили Улучшайзер так, что на съёмках все поменялись телами..."};
tr[22098] = {H:"Так стоп, давай по порядку!"};
tr[22099] = {OId:239,H:"Ларочка, это ты?!!"};
tr[22100] = {OId:240,H:"Нет, это Чебурашка! Ну конечно я, Дизель, я тебе полдня об этом твержу!"};
tr[22101] = {H:"Ну ладно, дальше сами разбирайтесь!"};
tr[22102] = {H:"Что?!! В теле Бараша — грабительница Лара?!!"};
tr[22103] = {OId:241,H:"Да, ты правильно понял. А вот до Дизеля доходит как до жирафа..."};
tr[22104] = {H:"Мда. И что теперь делать будем?"};
tr[22105] = {OId:241,H:"Сейчас наши зубастые друзья пообещают хорошо себя вести, и ты вернёшь всем тела."};
tr[22106] = {H:"Я на это не подписывался!"};
tr[22107] = {H:"Ну что, бобрята, вы готовы вести себя прилично?"};
tr[22108] = {OId:240,H:"Да, конечно! Не могу я уже в этом баране сидеть! Скорее, верни нам наши тела!"};
tr[22109] = {OId:241,H:"Идём на Съёмочную площадку. Все уже наверняка там."};
tr[22110] = {H:"Вперёд!"};
tr[22111] = {H:"Туземная палатка"};
tr[22112] = {H:"Туземный пуфик"};
tr[22113] = {H:"Куртка с перьями"};
tr[22114] = {H:"Причёска " + "\"" + "Туземец" + "\"" + ""};
tr[22115] = {H:"Ты кто?!!"};
tr[22116] = {H:"Агент! Смешарики поменялись телами! Спаси их - беги к Копатычу на Съёмочную площадку."};
tr[22117] = {H:"Гуттен таг! Ты слышать? В Джунгли приехали туземцы!"};
tr[22118] = {H:"Не, не слышал, и слышать не хочу!"};
tr[22119] = {H:"Туземцы? Прикольно! А зачем?"};
tr[22120] = {H:"Это актёры! Мы же снимайт фильм " + "\"" + "Легенда о золотом драконе" + "\"" + ". Кстати, он уже идёт во всех кинотеатрах!"};
tr[22121] = {H:"Вау! Знаменитости! А можно с ними познакомиться?"};
tr[22122] = {H:"Да, конечно! Они как раз ищут переводчик... Они плохо говорить по-шарарамовски, даже хуже, чем я."};
tr[22123] = {H:"Да ну, быть переводчиком так скучно!"};
tr[22124] = {H:"Я в совершенстве знаю язык Смешариков! А вот язык туземцев - не очень..."};
tr[22125] = {H:"Ничего, я тебе помогайт, подсказывайт пару слов из туземного. Ты готов?"};
tr[22126] = {H:"Конечно!"};
tr[22127] = {H:"Привет! Ты переводчик? Как называется по-вашему: " + "\"" + "когтистое мурчавое создание с усами, съевшее последний кусок колбасы" + "\"" + "?"};
tr[22128] = {H:"Грустный крот!"};
tr[22129] = {H:"Хитрый кот!"};
tr[22130] = {H:"Весёлый пёс!"};
tr[22131] = {H:"Глупая улитка!"};
tr[22132] = {H:"Привет! Ты переводчик? Как называется на языке Смешариков: " + "\"" + "великая белая гремящая сокровищница еды" + "\"" + "?"};
tr[22133] = {H:"Машина времени!"};
tr[22134] = {H:"Принтер!"};
tr[22135] = {H:"Бабушка!"};
tr[22136] = {H:"Холодильник!"};
tr[22137] = {H:"Привет! Ты переводчик? Как называется по-вашему: " + "\"" + "Весёлое песочное и жаркое место для тусовок" + "\"" + "?"};
tr[22138] = {H:"Библиотека!"};
tr[22139] = {H:"Школьный класс!"};
tr[22140] = {H:"Дискотека!"};
tr[22141] = {H:"Пляж!"};
tr[22142] = {H:"Привет! Ты переводчик? Как называется на языке Смешариков: " + "\"" + "Сладкая холодная фруктовая ням-нямка" + "\"" + "?"};
tr[22143] = {H:"Манная каша из холодильника!"};
tr[22144] = {H:"Салат оливье!"};
tr[22145] = {H:"Мороженое!"};
tr[22146] = {H:"Сосулька!"};
tr[22147] = {H:"Дизель"};
tr[22148] = {H:"Магия " + "\"" + "Дизель" + "\"" + "|Ты можешь получить эту способность в Лавке колдовства!|Превращайся в Дизеля из будущего еще дней: {0}|Превращайся в Дизеля всегда!"};
tr[22149] = {H:"Смешоскар!|За спасение Смешариков-актёров!"};
tr[22150] = {H:"Домик " + "\"" + "Деревня туземцев" + "\"" + ""};
tr[22151] = {H:"Смешарики поменялись телами!"};
tr[22152] = {H:"А я их спас! Приходи в Шарарам, тут не соскучишься!"};
tr[22153] = {H:"Дизель"};
tr[22154] = {H:"Секреты Кино"};
tr[22155] = {H:"Мы тут снимаем фильм... Поможешь? - А я расскажу, как всё устроено на съёмочной площадке."};
tr[22156] = {H:"Представь себя сценаристом! Море вдохновит тебя - приходи на Пляж."};
tr[22157] = {H:"Понаблюдай за посетителями в Кафе на Пляже - и заработай {0} Смешинок."};
tr[22158] = {H:"Кажется, у нас есть интересный сценарий! Получай Смешинки за помощь."};
tr[22159] = {H:"Секреты Кино"};
tr[22160] = {H:"Попробуй себя в роли артиста! Выезжаем на съёмки."};
tr[22161] = {H:"Встречаемся в Лесу. Приходи!"};
tr[22162] = {H:"Сыграй роль грибника! Собери Дары Леса - заработай {0} Смешинок."};
tr[22163] = {H:"Снято! Угостим работников сцены? Собери {0} орехов в Лесу."};
tr[22164] = {H:"Сцена в Лесу удалась! Держи свои Смешинки."};
tr[22165] = {H:"Секреты Кино"};
tr[22166] = {H:"Нам нужны красивые виды для заднего плана!"};
tr[22167] = {H:"Снимем вид моря подальше от берега! Заработай {0} Смешинки на Катере в Порту."};
tr[22168] = {H:"Есть ещё одно чудесное место с морем! Приходи в Пиратскую бухту."};
tr[22169] = {H:"Проверь декорации на прочность! Кинь {0} помидоров в скалы в Пиратской бухте."};
tr[22170] = {H:"А ты разбираешься в декорациях! Вот тебе Смешинки."};
tr[22171] = {H:"Секреты Кино"};
tr[22172] = {H:"Что может быть важнее, чем наряды актёров?"};
tr[22173] = {H:"В клубах много стильно одетых Смешариков! Посмотри на них - посети {0} клубов."};
tr[22174] = {H:"Стефан знает, как нарядить актёров! Приходи к нему в Дом Мод."};
tr[22175] = {H:"Научись подбирать наряды сам! Посети мастер-класс в Доме Мод."};
tr[22176] = {H:"Ты прекрасный костюмер! Держи Смешинки за помощь."};
tr[22177] = {H:"Секреты Кино"};
tr[22178] = {H:"На одну из ролей нам нужен талантливый малыш! Отправимся к Крошкам!"};
tr[22179] = {H:"Припасём Крошкам гостинцы. Найди в меню одного из клубов Шоколадные конфеты и купи."};
tr[22180] = {H:"Отправимся в Детский сад. Приходи!"};
tr[22181] = {H:"В группе " + "\"" + "Непоседы" + "\"" + " есть один маленький артист! Поработай Няней в Детском саду."};
tr[22182] = {H:"Мы нашли будущую звезду! Получай подарок - КиноКресло в домик!"};
tr[22183] = {H:"Готовимся к съёмкам!"};
tr[22184] = {H:"Что нужно артисту?"};
tr[22185] = {H:"Выбираем декорации!"};
tr[22186] = {H:"Больше красоты!"};
tr[22187] = {H:"Ищем таланты!"};
tr[22188] = {H:"Урок таинственных племён"};
tr[22189] = {H:"Теперь мы знаем тайны всех племён! Я верю, скоро Золотой Дракон явится нам! Держи подарок - одеяние племени хамелеонов."};
tr[22190] = {H:"Шапка хамелеонов"};
tr[22191] = {H:"Сандалии хамелеонов"};
tr[22192] = {H:"Копьё хамелеонов"};
tr[22193] = {H:"Смайлы " + "\"" + "Туземцы" + "\"" + ""};
tr[22195] = {H:"А вот и ты! Как дела? Уже улыбался сегодня? А рожицы перед зеркалом корчил? "};
tr[22196] = {H:"Оу-оу! Ты чего разошёлся? Я только на один вопрос за раз отвечать умею!"};
tr[22197] = {H:"А вот и я. Норм. Да. Нет."};
tr[22198] = {H:"Пфф, да я мастер спорта по корчанью рожиц. "};
tr[22199] = {H:"Повернись-ка в профиль! Дааа, твоё лицо мне очень подходит!"};
tr[22200] = {H:"Эй! Ты чего?! Такое лицо нужнО самому!"};
tr[22201] = {H:"Ладно-ладно, шучу! Или нет... Приходи в клуб Кривых зеркал - у меня к тебе предложение!"};
tr[22202] = {H:"А где этот клуб?"};
tr[22203] = {H:"Шляпа Несмеяна"};
tr[22204] = {H:"Я был в комнате смеха!"};
tr[22205] = {H:"И перехитрил Несмеяна! Хочешь повеселиться? Приходи в Шарарам!"};
tr[22206] = {H:"Зелье|Зелье сварится через {0} мин."};
tr[22207] = {H:"Взять зелье"};
tr[22208] = {H:"Фасад " + "\"" + "Комната Смеха" + "\"" + ""};
tr[22210] = {H:"Клуб с квестом!"};
tr[22211] = {H:"Без спец.одежды вход на Фабрику Шуток запрещён!"};
tr[22212] = {H:"Ты ведь обещал, что мы в Парк аттракционов пойдём... Хнык."};
tr[22213] = {H:"Приветик, как дела?"};
tr[22214] = {H:"Привет, Эллис! Не знаешь, почему СмеШутки опасными стали?"};
tr[22215] = {H:"Иду, я, значит, на Фабрику шуток – жвачек-взрывашек купить... И тут из трубы прям туман грусти повалил! И позитив как отрубило..."};
tr[22216] = {H:"Не может этого быть. Выпей витаминок, и настроение сразу появится..."};
tr[22217] = {H:"Интересно... Надо бы внутрь Фабрики попасть. Только как?"};
tr[22218] = {H:"Я видела, туда один известный клоун заходил, и стражники его пропустили. О, а давай тебя в него переоденем!"};
tr[22219] = {H:"Отличная идея. Но где костюм взять?"};
tr[22220] = {H:"В Смешмаге есть костюм клоуна – надень его  и иди к Фабрике в Порту!"};
tr[22221] = {H:"Что я, посмешище – клоунами одеваться! Неее..."};
tr[22222] = {H:"Кру-уто! Всю жизнь мечтал клоуном стать! Может, даже номера показывать буду..."};
tr[22223] = {OId:242,H:"Стой, куда идёшь?"};
tr[22224] = {H:"Да я так, мимо иду, бабушке пирожки несу..."};
tr[22225] = {H:"Да вот на Фабрику Шуток... Работаю я тут, не видите – клоун я."};
tr[22226] = {OId:242,H:"Можно, я первый спрошу?      Я же ...главный. Говори пароль!"};
tr[22227] = {OId:243,H:"Говори пароль!  ...                        Не перебивай, главный!           Говори, говорю, пароль!"};
tr[22228] = {H:"Абракадабра!"};
tr[22229] = {OId:242,H:"О-о, это то страшное заклинание! О нет, неужели  мы снова превратимся в сусликов?!!"};
tr[22230] = {OId:243,H:"Тут тебе не Школа магов! Ещё пароли знаешь?"};
tr[22231] = {H:"Ммм, ...пароль?.."};
tr[22232] = {OId:242,H:"Правильно! Проходи."};
tr[22233] = {H:"Какие ещё пароли? Знаю я таких – сначала Вам пароль скажи, а потом Румбики пропадают..."};
tr[22234] = {H:"Да я так, почтальон... Вам письмо! Танцуйте!"};
tr[22235] = {OId:242,H:"Ой, когда я танцую, я такой добрый — проходи!"};
tr[22236] = {OId:243,H:"А я вот – не такой добрый. Не пущу!"};
tr[22237] = {H:"Эх, я несчастный!.."};
tr[22238] = {H:"Погоди, я видео включу – хочу нытьё твоё заснять!"};
tr[22239] = {H:"Эй-эй, мир прекрасен! Что стряслось-то?"};
tr[22240] = {H:"На 1 апреля Смешарики заказали мне так много СмеШуток, что все мои позитивные мысли закончились..."};
tr[22241] = {H:"Позитив-негатив.. Это ведь с какой стороны посмотреть... Не знаю, что ещё умного сказать..."};
tr[22242] = {H:"Фи, грустный Клоун – не смешно. Бывай, я пошёл!"};
tr[22243] = {H:"Ничего, бывает. Я тебе сейчас позитивность-то настрою! Для начала в Парк аттракционов пойдём."};
tr[22244] = {H:"за одеждой"};
tr[22245] = {H:"Спасибо!"};
tr[22246] = {H:"Ну и ладно, не очень-то и хотелось..."};
tr[22247] = {H:"Я прогнал Монстрика и получил подарок! Приходи и ты в игру."};
tr[22248] = {H:"Костюм клоуна"};
tr[22249] = {OId:150,H:"Т-сс, по секрету я тебе скажу кое-что важное! Когда высплюсь... Поболтай сначала с другими."};
tr[22250] = {OId:150,H:"Ой, а мне надо отдохнуть! Монстром быть так тяжело..."};
tr[22251] = {OId:244,H:"...Тут записан  какой-то рэп – мозьно выбрасивать. Ищи есё!"};
tr[22252] = {OId:247,H:"Не кусяй! Это насё-о-ооо! О, я пою!"};
tr[22253] = {OId:246,H:"Йоу, Смеш!\nТорт наш – не еееее-шь!!!\nОй, песня заела..."};
tr[22254] = {OId:150,H:"Торт наш – не еееее-шь!!!"};
tr[22255] = {H:"Ой, песня заела..."};
tr[22256] = {OId:248,H:"Тортик такой вкусненький! И петь помогает... А-аааа!"};
tr[22257] = {OId:245,H:"...А я вообще не петь не могу...  Гу-гу-гууууу!"};
tr[22258] = {OId:249,H:"Ой, не могу больше! Ля-ля!"};
tr[22259] = {OId:251,H:"Пить хочется, а рот пением занят..."};
tr[22260] = {OId:250,H:"У меня уже голосочек садится..."};
tr[22261] = {OId:252,H:"Не удержался я, торт попробовал! И озверел от земляники..."};
tr[22262] = {OId:150,H:"Ты опоздал – концерт окончен... Хотя, постой... – ты петь умеешь? Спой-ка!"};
tr[22263] = {H:"Ну, немножко умею... тру-ля-ля..."};
tr[22264] = {OId:150,H:"Ужас... Но если научишься – приходи обязательно! У тебя все шансы стать артистом."};
tr[22265] = {H:"в клуб"};
tr[22266] = {H:"Конечно! О сооолееее, о сооле миииио!"};
tr[22267] = {OId:150,H:"Отлично поёшь! Беру тебя в своё шоу. Пойдём-ка за кулисы..."};
tr[22268] = {H:"Круто! Пойдём!"};
tr[22269] = {OId:150,H:"Не мешай, я музыку слушаю!"};
tr[22270] = {H:"Не видишь – они уже устали – отпусти их!"};
tr[22271] = {OId:150,H:"Ха-ха.. Нее-т... Зря что ли я торт волшебный пёк. Они теперь будут петь для меня ВЕЧНО!!!"};
tr[22272] = {H:"Вот злодей! И что за смысл тебе – над артистами издеваться?!!"};
tr[22273] = {OId:150,H:"Я рисовать бросил, решил музыку полюбить...Уже все треки мира переслушал – надоело. Но без музыки жить теперь не могу, а они поют лучше всех."};
tr[22274] = {H:"А если я тебе ещё круче трек запишу – отпустишь их?"};
tr[22275] = {OId:150,H:"Ну... если такой прекрасный трек сочинишь, который никогда не надоест, – тогда отпущу..."};
tr[22276] = {H:"Договорились!"};
tr[22277] = {OId:150,H:"Вот расстройство... Из моей кулинарной книги украли рецепт волшебного торта..."};
tr[22278] = {H:"Какое совпадение! А я как раз тебе торт принёс!"};
tr[22279] = {OId:150,H:"Мм, гостинец? – Очень мило!"};
tr[22280] = {H:"Да, угощайся!"};
tr[22281] = {H:"Торт-то я принёс, а угостить не могу. Те, кто его ел, ведут себя странно. Может, ты знаешь, в чём его секрет?"};
tr[22282] = {H:"Ишь, чего захотел, такой торт я и сам съем!"};
tr[22283] = {OId:150,H:"Оо, чую запах торта " + "\"" + "Вечная песня" + "\"" + ". Как раз его рецепт и украли! От него поёшь без остановки: 1 грамм – 1 год пения!"};
tr[22284] = {H:"Ого! Так давай съедим его, и в караоке пойдём!"};
tr[22285] = {H:"Выходит, артисты, у которых я его отобрал, целую вечность петь будут?!!"};
tr[22286] = {OId:150,H:"Скорее, беги к артистам – скажи, чтобы не ели торт!"};
tr[22287] = {H:"Заходи домой к артистам!"};
tr[22288] = {H:"Микрофон|Микрофон принесут через {0} мин."};
tr[22289] = {H:"Наведи бумажку на Сяо Мяо!"};
tr[22290] = {H:"Приходи на секретное шоу!"};
tr[22291] = {H:"Наведи торт из чемоданчика."};
tr[22292] = {H:"Орден " + "\"" + "Вечная Песня" + "\"" + "|За спасение хора Артистов"};
tr[22293] = {H:"Секретное шоу"};
tr[22294] = {H:"Артисты уходят на сцену и не возвращаются! Беги в Секретный клуб и разузнай, что делать."};
tr[22295] = {H:"к клубу"};
tr[22296] = {H:"Я сделал суперШоу !"};
tr[22297] = {H:"Я спас артистов и получил крутой подарок! Приходи и ты в Шарарам."};
tr[22298] = {H:"Карусель"};
tr[22299] = {H:"Дом " + "\"" + "Фабрика позитива" + "\"" + ""};
tr[22300] = {H:"СмеШутка " + "\"" + "Каруселька" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь катать Смешариков на карусели ещё дней: {0}|Ты можешь катать Смешариков на карусели всегда!"};
tr[22301] = {H:"Я вернул позитив – Смешарики будут веселится весь апрель! Приходи и ты играть в Шарарам."};
tr[22302] = {H:"Смешарики будут веселится весь апрель, а я получил подарок. Приходи и ты играть в Шарарам."};
tr[22303] = {H:"за одеждой"};
tr[22304] = {H:"Хорошо!"};
tr[22305] = {H:"Мыльная пушка"};
tr[22306] = {OId:150,H:"Спасибо, родненький! Мы отмыли Птах, и теперь в Шарараме стало еще чище!"};
tr[22307] = {OId:0,H:"Я прогнал грязевых чудищ!"};
tr[22308] = {OId:0,H:"И получил награду! Приходи в Шарарам за подарками!"};
tr[22309] = {H:"" + "\"" + "Воздушный пират" + "\"" + ""};
tr[22310] = {H:"" + "\"" + "Неуловимый" + "\"" + ""};
tr[22311] = {H:"" + "\"" + "Рокки-чемпион" + "\"" + ""};
tr[22312] = {H:"" + "\"" + "Модное золотко" + "\"" + ""};
tr[22313] = {H:"" + "\"" + "Байк-романтика" + "\"" + ""};
tr[22314] = {H:"" + "\"" + "Модная Милочка" + "\"" + ""};
tr[22315] = {H:"" + "\"" + "Для журнала" + "\"" + ""};
tr[22316] = {H:"" + "\"" + "Прогулка красотки" + "\"" + ""};
tr[22317] = {H:"" + "\"" + "Леди Пушистик" + "\"" + ""};
tr[22318] = {H:"" + "\"" + "Удиви каток!" + "\"" + ""};
tr[22319] = {H:"" + "\"" + "Герой в гостях" + "\"" + ""};
tr[22320] = {H:"" + "\"" + "Модный эльф" + "\"" + ""};
tr[22321] = {H:"Агенты прячутся..."};
tr[22322] = {H:"Когда Секретные агенты играют в прятки, найти их - дело сложное. Сыграем? Помоги отыскать всех!"};
tr[22323] = {H:"Агент 001 любит прятаться где попрохладнее. Поищем его в Порту - беги туда."};
tr[22324] = {H:"001 ведь адмирал! Наверное, на остров уплыл! Прокатись на Катере в Порту."};
tr[22325] = {H:"Чую, этот моряк 001 где-то под водой. Посмотри в перископ в Порту."};
tr[22326] = {H:"Вон он, вдалеке! Одного нашли. Держи Смешинки."};
tr[22327] = {H:"Агенты прячутся..."};
tr[22328] = {H:"Агент 007 так занят. Он даже в прятки играет, не отрываясь от работы."};
tr[22329] = {H:"Я знаю, он ушёл на задание в клуб! Посети {0} клубов."};
tr[22330] = {H:"Притворись тусовщиком. Найди в меню одного из клубов Молочный коктейль и купи."};
tr[22331] = {H:"Есть! Мы засекли Агента в клубе. Получай Смешинки за помощь."};
tr[22332] = {H:"Агенты прячутся..."};
tr[22333] = {H:"Наш Агент 002 - змейка, и она жить не может без жары."};
tr[22334] = {H:"Лучшее место для неё - Пляж! Приходи туда."};
tr[22335] = {H:"Если 002 захочет пить на жаре, то придёт в Кафе на Пляже. Поработай там."};
tr[22336] = {H:"002 отлично зарывается в песок! Поищем. Сыграй в " + "\"" + "Секретики" + "\"" + " на Пляже."};
tr[22337] = {H:"Ага, попалась!.. Ты очень помог - возьми Смешинки."};
tr[22338] = {H:"Агенты прячутся..."};
tr[22339] = {H:"Эх, я рассеянный! У нас в списке ненайденных ещё какой-то Агент 003. А кто это - не помню."};
tr[22340] = {H:"003 был в Больничке! Посмотрим, что ему прописали. Собери {0} рецепта в Больничке."};
tr[22341] = {H:"Нашёлся рентген агента! Это точно не ты? - Похож!.. Сделай рентген в Больничке."};
tr[22342] = {H:"Ха-ха, я тоже сделал рентген и понял: 003 - это ж я! Надо записать... Смешинки твои."};
tr[22343] = {H:"Агенты прячутся..."};
tr[22344] = {H:"Шеф прячется лучше всех! Я его, бывает, годами ищу..."};
tr[22345] = {H:"Шеф часто бывает на Главной площади. Беги туда."};
tr[22346] = {H:"Спроси Смешариков - напиши: " + "\"" + "Где Шеф?" + "\"" + ""};
tr[22347] = {H:"Шеф любит игру " + "\"" + "Смешарики" + "\"" + ". Спроси о нём игроков - сыграй на площади перед Диско."};
tr[22348] = {H:"Класс! Нам подсказали, где Шеф! Держи подарок - Мантию для пряток."};
tr[22349] = {H:"Ищем Агента 001"};
tr[22350] = {H:"Следим за Агентом 007"};
tr[22351] = {H:"Где Агент 002?"};
tr[22352] = {H:"Кто такой Агент 003?"};
tr[22353] = {H:"Ищем Шефа!"};
tr[22354] = {H:"Тс-с! Ты умеешь хранить секреты?"};
tr[22355] = {H:"Умникус боится лягушек, Шеф в очках похож на Бинтика, а Бараш любит Нюшу! Как думаешь, храню я секреты?"};
tr[22356] = {H:"Конечно. Расскажи, что случилось?"};
tr[22357] = {H:"Крошки постоянно пропадают! Агенты уже сбились с ног искать их..."};
tr[22358] = {H:"Извините, но я их не крал..."};
tr[22359] = {H:"Вот беда! Чем я могу помочь?"};
tr[22360] = {H:"Надеюсь, ты сможешь найти и спасти их! Проверим?"};
tr[22361] = {H:"ОКеюшки!"};
tr[22362] = {H:"Ма-мааа!"};
tr[22363] = {H:"Я победил Злобырей и получил крутой подарок! А тебе слабо? – Беги в Шарарам!"};
tr[22364] = {H:"Комбинезон Спасателя твой! Ищи его в " + "\"" + "Костюмах" + "\"" + " на Личной карточке."};
tr[22365] = {H:"У тебя уже есть Комбинезон Спасателя! Ищи его в " + "\"" + "Костюмах" + "\"" + " на Личной карточке."};
tr[22366] = {H:"Секретный клуб"};
tr[22367] = {H:"Поющая Сирена"};
tr[22368] = {H:"Диско-Дроид"};
tr[22369] = {H:"Вечеринка теперь всегда с тобой! Ищи в своём гардеробе!"};
tr[22370] = {H:"СмеШутка " + "\"" + "Поющая Сирена" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь приглашать Сирену петь для Смешариков ещё дней: {0}|Ты можешь приглашать Сирену петь для Смешариков всегда"};
tr[22371] = {OId:253,H:"Беги к Шарри Коттеру у Больнички  – спроси у него про торт!"};
tr[22372] = {H:"Взять рацион"};
tr[22373] = {H:"Я герой космоса!"};
tr[22374] = {H:"Я уже побывал на орбите и спас Шарарам от катастрофы! А как насчёт тебя? Скорее в игру!"};
tr[22375] = {H:"Рацион космонавта|Рацион доставят через {0} мин."};
tr[22376] = {H:"Давай попробуем включить эту станцию. Здесь всё очень запутано, так что придётся поискать нужную кнопку."};
tr[22377] = {H:"Катастрофен!\nКто-то украсть наш Шаранит,\nот которого питаться энергий наша ракета!"};
tr[22378] = {H:"Пин, тогда давай зашвырнем её в космос большой рогаткой!"};
tr[22379] = {H:"А я всё равно высоты боюсь, и никуда летать не собираюсь."};
tr[22380] = {H:"Фантастиш! Но к счастью,\nя успеть зарядить ракета,\nтак что мы ещё можем отправиться в полёт\nи забрать Шаранит у вора."};
tr[22381] = {H:"Молодец, Пин! Где же мой скафандр?"};
tr[22382] = {H:"О, не торопись!\nПеред полётом пройди курс подготовки космонавта.\nНайди моих друзей в Шарараме,\nони помогайт тебе! \nИ загляни на рентген в Больничку. "};
tr[22383] = {H:"Хорошо. Пойду готовиться!"};
tr[22384] = {H:"Эй! Ты как сюда забрался?"};
tr[22385] = {H:"Сдавайся, злодей! Я прилетел из Шарарама, чтобы вернуть камень, который ты украл!"};
tr[22386] = {H:"Украл? Ничего подобного! \nЯ нашёл этот камень на одной далёкой планете и спрятал. Но потом он исчез...\nА все следы вели к вам\nв Шарарам."};
tr[22387] = {H:"Точно! Это же наш Биби нашёл Шаранит и подумал, что камень ничейный."};
tr[22388] = {H:"Говоришь ты складно, но где доказательства?"};
tr[22389] = {H:"Ага! Вот так история! Так, значит, этот камень тебе нужен?"};
tr[22390] = {H:"Да, Шаранит очень нужен мне, чтобы заряжать ракеты, на которых мы летаем в Космос!"};
tr[22391] = {H:"Да, я хочу поставить Шаранит к себе в домик. Классная лампа выйдет!"};
tr[22392] = {H:"О! Просто доверься мне. Так, значит, этот камень тебе нужен?"};
tr[22393] = {H:"Да, Шаранит очень нужен мне, чтобы заряжать ракеты, на которых мы летаем в Космос!"};
tr[22394] = {H:"Да, я хочу поставить Шаранит к себе в домик. Классная лампа выйдет!"};
tr[22395] = {H:"Но он и мне нужен!\nТолько с Шаранитом можно разгадать загадку этой станции. Помоги мне,\nа потом мы решим, кому достанется камень."};
tr[22396] = {H:"Конечно, помогу! Обожаю разгадывать тайны!"};
tr[22397] = {H:"Нет. Я тебе не доверяю."};
tr[22398] = {OId:255,H:"Ахтунг! Что у вас там происходить?"};
tr[22399] = {H:"Пин? А ты как здесь оказался?!"};
tr[22400] = {OId:255,H:"Это не я. Это мой точный голограмма, который я посылать из Космодром. Мои данные говорить, что станция сошла\nс орбит и попадайт\nв поле метеоритов!"};
tr[22401] = {OId:256,H:"Всё ясно! Энергия камня оказалось такой мощной, что сломала станцию!"};
tr[22402] = {H:"Она теперь, что, в метеориты врежется? Ой-ой!"};
tr[22403] = {H:"А ведь я знал, что от этого Капитана одни беды!"};
tr[22404] = {OId:255,H:"Если вы не исправить ситуаций, метеорит разрушайт станций, и всем будет капут!"};
tr[22405] = {OId:256,H:"Не волнуйтесь! Мы переактивируем инжекторное поле и через квазидиффузор переиндуцируем потоки, возьмём ручное управление станцией и выведем её из поля метеоритов."};
tr[22406] = {H:"Интересная мысль..."};
tr[22407] = {OId:255,H:"Ахтунг! Вручную управлять станций это же безумий!"};
tr[22408] = {H:"Но у нас всё равно нет выбора. Будем управлять станцией вручную!"};
tr[22409] = {H:"Настоящий безумий - это позволить станции разбиться о метеориты!"};
tr[22410] = {H:"Здесь станцию не включить. Поищи в другом месте."};
tr[22411] = {H:"Маленькая галактика"};
tr[22412] = {H:"Торшер " + "\"" + "Луна" + "\"" + ""};
tr[22413] = {H:"шлем " + "\"" + "Первый космический" + "\"" + ""};
tr[22414] = {H:"футболка с рюкзаком " + "\"" + "Земля" + "\"" + ""};
tr[22415] = {H:"Вот, послушай. Зябра - это планета. Луна - это спутник. Но тогда что такое Солнце?  Ответь и получи от меня подарок!"};
tr[22416] = {H:"Это такая лампочка на небе."};
tr[22417] = {H:"Солнце - это звезда. "};
tr[22418] = {H:"Это, говорят, Злобикус со злости тарелку в космос зашвырнул!"};
tr[22419] = {H:"Солнце - это блинчик! Ом-ном-ном!"};
tr[22420] = {H:"Привет! Скажу тебе по секрету - в космосе всё не так, как на Земле. Вот ты знаешь, что будет в невесомости с капелькой воды? Ответь и получи от меня подарок!"};
tr[22421] = {H:"Вода в невесомости пшик! И испарится!"};
tr[22422] = {H:"Холодно там. Замёрзнет водичка."};
tr[22423] = {H:"Вода в газировку превратится. Потому я в космос и хочу полететь!"};
tr[22424] = {H:"Капелька будет в воздухе парить как воздушный шарик!"};
tr[22425] = {H:"Привет! Оно, конечно, здорово, что Космодром у вас строится. А полетите-то хоть на чём? Ответь и получи от меня подарок!"};
tr[22426] = {H:"Не полетим, а поедем. На космическом трамвае. Да-да."};
tr[22427] = {H:"У нас в Шарараме до космоса Крош допрыгнуть может."};
tr[22428] = {H:"Ой, не шути так. Летают-то вообще на чём? На самолёте!"};
tr[22429] = {H:"В космос - только на ракете!"};
tr[22430] = {H:"Привет! Хочешь подарок? Ответь на хитрый вопрос: Что пелось в припеве одной песни о космосе?"};
tr[22431] = {H:"Земля в иллюминаторе видна."};
tr[22432] = {H:"Весна в иллюминаторе видна."};
tr[22433] = {H:"Земля на вентиляторе одна."};
tr[22434] = {H:"Весна для терминатора одна."};
tr[22435] = {H:"Платье " + "\"" + "Пёрышко" + "\"" + ""};
tr[22436] = {H:"Очки " + "\"" + "Гагара" + "\"" + ""};
tr[22437] = {H:"Шапка " + "\"" + "Совушка" + "\"" + ""};
tr[22438] = {H:"Куртка " + "\"" + "Размах" + "\"" + ""};
tr[22439] = {H:"Причёска " + "\"" + "Улёт" + "\"" + ""};
tr[22440] = {H:"Скутер " + "\"" + "Сапсан" + "\"" + ""};
tr[22441] = {H:"Платье " + "\"" + "Светлая полоса" + "\"" + ""};
tr[22442] = {H:"Причёска " + "\"" + "Энни" + "\"" + ""};
tr[22443] = {H:"Кроссовки " + "\"" + "Энни" + "\"" + ""};
tr[22444] = {H:"Куртка " + "\"" + "Прямая линия" + "\"" + ""};
tr[22445] = {H:"Кросы-полосы"};
tr[22446] = {H:"Шапка " + "\"" + "Помпошка" + "\"" + ""};
tr[22447] = {OId:150,H:"Хай! Меня так и тянет поделиться талантом со всеми! Теперь я выпускаю одежду! Взгляни-ка!"};
tr[22448] = {H:"Ты стал магом-сладкоежкой и расколдовал Шарарам!"};
tr[22449] = {H:"Я волшебник!"};
tr[22450] = {H:"Я стал магом-сладкоежкой и получил подарок! Заходи и ты в Шарарам."};
tr[22451] = {H:"Скафандр " + "\"" + "Джунга" + "\"" + ""};
tr[22452] = {H:"Шлем " + "\"" + "Джунга" + "\"" + ""};
tr[22453] = {H:"Ботинки " + "\"" + "Джунга" + "\"" + ""};
tr[22454] = {H:"Скафандр " + "\"" + "КосмоЛеди" + "\"" + ""};
tr[22455] = {H:"Ботинки " + "\"" + "КосмоЛеди" + "\"" + ""};
tr[22456] = {H:"Скафандр " + "\"" + "Юрий" + "\"" + ""};
tr[22457] = {H:"Ботинки " + "\"" + "Юрий" + "\"" + ""};
tr[22458] = {H:"Скафандр " + "\"" + "Джунга" + "\"" + ""};
tr[22459] = {H:"Скафандр " + "\"" + "КосмоЛеди" + "\"" + ""};
tr[22460] = {H:"Скафандр " + "\"" + "Юрий" + "\"" + ""};
tr[22461] = {H:"Магия " + "\"" + "Дроид" + "\"" + ""};
tr[22462] = {H:"Магия " + "\"" + "Невесомость" + "\"" + ""};
tr[22463] = {H:"Магия " + "\"" + "Дроид" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в дроида ещё дней: {0}|Превращайся в дроида всегда!"};
tr[22464] = {H:"Магия " + "\"" + "Невесомость" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь парить в невесомости ещё дней: {0}|Ты можешь парить в невесомости всегда!"};
tr[22465] = {OId:150,H:"Рад бы поболтать, но времени нет!.. Я собираюсь в погоню за преступником на этом дирижабле."};
tr[22466] = {H:"А, ну извини, не буду отвлекать... "};
tr[22467] = {H:"Не советую лететь! Сэнсэй видел про это плохой сон, а его сны сбываются!"};
tr[22468] = {OId:150,H:"Это всё – суеверия! Я полетел. Преступник распыляет яд с самолёта. Если его не остановить, в Шарараме станет невозможно жить!"};
tr[22469] = {H:"Тогда возьми меня с собой. Я знаешь как пригожусь?!!.."};
tr[22470] = {OId:150,H:"Ла-адно, уговорил! Полетели?"};
tr[22471] = {H:"Ой, а вот летать-то я и не умею... Где тут можно витаминки купить, от которых крылья растут?.."};
tr[22472] = {H:"Полетели!"};
tr[22473] = {H:"Ну, и лети. Но когда на тебя гипс будут накладывать – вспомнишь, что я предупреждал!.."};
tr[22474] = {H:"Эх, а я хотел о погоде поговорить... Спрошу тогда Бинтика, ноют ли у него колени перед дождём..."};
tr[22475] = {H:"Владелец КосмоКарты "};
tr[22476] = {H:"Стань космонавтом с КосмоКартой"};
tr[22477] = {H:"Домик-планета Фандора"};
tr[22478] = {H:"Скафандр " + "\"" + "Космический рейнджер" + "\"" + ""};
tr[22479] = {H:"Ботинки " + "\"" + "Космический рейнджер" + "\"" + ""};
tr[22480] = {H:"Стань самым крутым космонавтом вселенной!|Ищи скафандр в своём гардеробе!"};
tr[22481] = {H:"КосмоМаркет|Лучшее космическое снаряжение"};
tr[22482] = {H:"Метеоритный тренажёр|Управляй ракетой и уворачивайся от метеоритов!"};
tr[22483] = {H:"Космодром|Отправляйся в космос на ракете и участвуй в космических приключениях!"};
tr[22484] = {H:"Телескоп|Посмотри, что новенького в Космосе!"};
tr[22485] = {OId:257,H:"Там, на островах – самолёт злодея, за которым я гонюсь! Побежали туда."};
tr[22486] = {OId:258,H:"Постойте! Я с вами летел – а теперь сломался. Почините меня, я пригожусь!"};
tr[22487] = {H:"Некогда, ЮИ! Шеф, бежим."};
tr[22488] = {OId:258,H:"Но у меня доски в животе! Неужели, так оставите?"};
tr[22489] = {H:"Ладно, починю... И как ты только в дирижабль поместился?"};
tr[22490] = {OId:258,H:"Я увидел тебя, и думаю – никак, расследование намечается! А это дело для Лиги Героев. Ты же помнишь – мы с тобой в Лиге же..."};
tr[22491] = {OId:257,H:"Ребята, я – к самолёту! А то преступник скроется, и всё пропало. Закончите починку, и сразу ко мне!"};
tr[22492] = {H:"Так, ЮИ, – я достаю отвёртку. Не бойся – больно не будет."};
tr[22493] = {H:"Шурупы|Шурупы привезут через {0} мин."};
tr[22494] = {H:"Звёздная карта в домик"};
tr[22495] = {H:"Кстати! А ты сам-то умеешь рисовать? Заработай {0} Cмешинок в игре Волшебный карандаш!"};
tr[22496] = {H:"Звёздная карта"};
tr[22497] = {H:"Звёздная карта"};
tr[22498] = {H:"Звёздная карта"};
tr[22499] = {H:"Звёздная карта"};
tr[22500] = {H:"Звёздная карта"};
tr[22501] = {H:"Друг мой, время для научных подвигов! Помоги мне составить новую звёздную карту для полётов в космосе."};
tr[22502] = {H:"Шарарам - тоже часть Вселенной. Изучим его для нашей карты!"};
tr[22503] = {H:"Теперь самое трудное - будем составлять карту!"};
tr[22504] = {H:"Нужно срочно сообщить о нашей карте научному сообществу!"};
tr[22505] = {H:"Нашу карту оценили учёные. Самое время отнести её Пину, чтобы он занёс данные в ракету!"};
tr[22506] = {H:"Великолепно! Мы собрали данные о звёздном небе. Получай Смешинки за помощь!"};
tr[22507] = {H:"Потрясающе, мы собрали все необходимые данные!"};
tr[22508] = {H:"Ты только взгляни на это! Карта готова!"};
tr[22509] = {H:"Это триумф! Мы успешно представили нашу работу!"};
tr[22510] = {H:"Ура! Теперь ракета будет летать по нашей карте! Получай заслуженный подарок - Звёздную карту в домик!"};
tr[22511] = {H:"Лучше всего звёзды видно на Пляже. Отправляйся туда."};
tr[22512] = {H:"Посмотри в Подзорную трубу, чтобы точнее описать небо."};
tr[22513] = {H:"Недавно я обнаружил, что на жемчуге сохраняется вид ночного неба. Собери {0} жемчужины."};
tr[22514] = {H:"Снежная гора – самая высокая точка Шарарама. Приходи туда."};
tr[22515] = {H:"Проверим плотность атмосферы. Кинь с горы {0} помидоров."};
tr[22516] = {H:"Нужно измерить высоту горы, чтобы корректировать полёты. Спустись с неё на сноуборде!"};
tr[22517] = {H:"Нам понадобятся помощники. Добавь {0} Смешариков в друзья."};
tr[22518] = {H:"Отправь {0} друзьям сообщение на Шарафон: Умеешь рисовать Звёздную карту?"};
tr[22519] = {H:"Кстати! А ты сам-то умеешь рисовать? Заработай {0} Cмешинок в игре Волшебный карандаш!"};
tr[22520] = {H:"Мы должны выглядеть торжественно! Купи костюм " + "\"" + "Маэстро" + "\"" + "."};
tr[22521] = {H:"Позовём слушателей! Напиши в чат: " + "\"" + "Приходите смотреть Звёздную карту" + "\"" + "."};
tr[22522] = {H:"Куда съедутся учёные? Конечно же в твой домик! Прими у себя {0} гостей."};
tr[22523] = {H:"Отправляйся в Ромашковую долину."};
tr[22524] = {H:"Пин очень занят. Сначала помоги ему – заработай {0} Cмешинок в игре Вечный двигатель."};
tr[22525] = {H:"Наблюдаем за звёздами!"};
tr[22526] = {H:"Изучаем Шарарам!"};
tr[22527] = {H:"Рисуем карту!"};
tr[22528] = {H:"Время для презентации!"};
tr[22529] = {H:"Пин будет доволен!"};
tr[22530] = {OId:259,H:"Ну, а меня-то зачем связали?.."};
tr[22531] = {OId:261,H:"Я вам ничего не скажу!"};
tr[22532] = {OId:260,H:"Ой... Если их развязать, пират убежит. Давайте сначала допросим его. Только я не умею..."};
tr[22533] = {H:"Корсар, предупреждаю: лучше сам расскажи, зачем Шарарам ядом опрыскивал."};
tr[22534] = {OId:259,H:"Эммм... Ау, кто-нибудь заметил, что я здесь?..."};
tr[22535] = {OId:261,H:"...Ути, он мне угрожает! Гусениц я травил – таких же малявок, как ты :Ь ...Ой, а откуда ты знаешь моё имя?"};
tr[22536] = {H:"Я умею читать мысли! Так что – ещё раз говорю – признавайся, хуже будет!"};
tr[22537] = {OId:261,H:"Вот не надо тут меня пугать!.. Ладно-ладно, расскажу я..."};
tr[22538] = {OId:260,H:".. Ой, ты только мои мысли не читай... Там 7 страниц всего, да тебе они и не понравятся..."};
tr[22539] = {H:"ЮИ, обещаю! Корсар, – говори!"};
tr[22540] = {OId:261,H:"Хотел сделать Шарарам ядовитым! Смешарикам бы пришлось бы на острова переехать, и мы бы тогда Шарарам ограбили. Эх, мечты..."};
tr[22541] = {OId:260,H:"Ужас какой! Не мечтай так больше!.."};
tr[22542] = {H:"Ясно. Теперь признавайся, где яды прячешь?"};
tr[22543] = {OId:259,H:"А этот малый отлично допрашивает! Ему бы орден..."};
tr[22544] = {OId:261,H:"На корабле – в Порту, а что? Вы добежать не успеете – мои Пираты наверное, уже море отравили и ужинают;)"};
tr[22545] = {OId:260,H:"Так, я собираю Лигу Героев! Опп, МедвеДуся уже на корабле."};
tr[22546] = {H:"ЮИ, бежим на Корабль! Шеф, будь другом – присмотри за этим. ПылеСанчо сейчас приедет сюда и поможет."};
tr[22547] = {H:"Клуб " + "\"" + "Яхта" + "\"" + ""};
tr[22548] = {H:"Вот ведь дела! Босс Ба-Босс устроил вечеринку на яхте, а потанцевать так ни у кого и не получилось..."};
tr[22549] = {H:"Ну и нечего! А то вечеринки, вечеринки! А работать кто будет?"};
tr[22550] = {H:"Чтобы у Босса Ба-Босса да вечеринка не удалась! Что же случилось?"};
tr[22551] = {H:"Никто не знает! Просто музыку в клубе на яхте вдруг заглушил чей-то плач! Вот мы и разбежались все."};
tr[22552] = {H:"Ничего, ничего! Сейчас разберёмся. Тех, кто плачет - успокоим! Кто грустит - развеселим!"};
tr[22553] = {H:"Вот как. Я плакс не люблю. Пусть и дальше в море рыдают."};
tr[22554] = {H:"Здорово! Тогда скорей отправляйся в клуб на яхте!"};
tr[22555] = {H:"А что это за клуб такой?"};
tr[22556] = {H:"У нас тут крутая вечеринка, а танцевать мешают странные звуки из-под воды! Ныряй в океан и узнай, в чём проблема!"};
tr[22557] = {H:"Нырнуть"};
tr[22558] = {H:"Это Спрут!"};
tr[22559] = {H:"Он живёт в клубе " + "\"" + "Яхта" + "\"" + " в Шарараме! Помоги ему устроить тусовку и получи морские сокровища!"};
tr[22560] = {OId:259,H:"Беги на Корабль в Порту, а то пираты отравят море. Обо мне не беспокойся. Мм... ты же беспокоился?"};
tr[22561] = {OId:264,H:"Приезжал ПылеСанчо, освободил Шефа... А меня, почему-то, нет... Как там мои пираты на корабле?"};
tr[22562] = {H:"Магия " + "\"" + "Чёрный Корсар" + "\"" + ""};
tr[22563] = {H:"Морская звезда"};
tr[22564] = {H:"Магия " + "\"" + "Морская звезда" + "\"" + "|Устрой вечеринку Спруту в клубе " + "\"" + "Яхта" + "\"" + " и сможешь превращаться в Морскую звезду!|Ты можешь превращаться в Морскую звезду ещё {0} дней!|Ты можешь превращаться в Морскую звезду всегда!"};
tr[22565] = {H:"Фасад " + "\"" + "Яхта" + "\"" + ""};
tr[22566] = {H:"Монстрик, уходи!"};
tr[22567] = {H:"Я прогнал злодея и получил подарок... Приходи в игру – здесь столько интересного!"};
tr[22568] = {H:"Клуб " + "\"" + "Яхта" + "\"" + " с приключениями"};
tr[22569] = {H:"Устрой вечеринку морскому Спруту!|Отыщи морские сокровища!|Фасад для клуба в подарок!"};
tr[22570] = {H:"Безумный полёт"};
tr[22571] = {OId:265,H:"Умникус подскажет, как справиться с монстром!"};
tr[22572] = {OId:265,H:"Крутота! Монстр спрятался в руинах этого древнего города. Он где-то рядом! "};
tr[22573] = {H:"А где? Ты вон про ту милую рыбку? Ути, какая!"};
tr[22574] = {H:"Ну и шуточки у вас! Если бы монстр здесь был - он бы на нас уже напал!"};
tr[22575] = {OId:266,H:"Нет же! Монстр где-то тут, просто мы его не видим!"};
tr[22576] = {H:"У меня вот со зрением всё в порядке! Правда, темновато здесь..."};
tr[22577] = {H:"Ой, всё! Пойду я, а то вы только и знаете, что небылицы рассказывать!"};
tr[22578] = {OId:265,H:"Точно! Нужно включить свет. Давай починим мой фонарик и увидим монстра!"};
tr[22579] = {H:"Когда осьминожка под водой просит меня починить фонарик, я не могу отказать!"};
tr[22580] = {OId:266,H:"Какое жуткое чудище! А ты не верил..."};
tr[22581] = {OId:265,H:"Тссс! Нельзя, чтобы он нас заметил!"};
tr[22582] = {H:"Ха! Сейчас я ему задам!"};
tr[22583] = {H:"Ой! А что это за монстр вообще такой?"};
tr[22584] = {OId:265,H:"Нельзя! Если Култухтыш разозлится, море вокруг закипит!"};
tr[22585] = {H:"Ну ничего себе! Что это за монстр вообще такой?"};
tr[22586] = {OId:265,H:"Что за монстр?! Ну ты даёшь!"};
tr[22587] = {OId:266,H:"Ох уж эти сухопутные..."};
tr[22588] = {H:"Со Злобырями сражался. Чудиков прогонял. А про этого вашего - ничего не слышал."};
tr[22589] = {H:"Зато я знаю, как устроить вечеринку! Хотите?"};
tr[22590] = {OId:265,H:"Так ты сражался с монстрами раньше? Может, поможешь нам прогнать Култухтыша?"};
tr[22591] = {H:"Конечно, помогу! Умникус всё знает про чудищ. Спрошу совета у него!"};
tr[22592] = {H:"Надоели мне ваши монстры. Спрячусь в домик."};
tr[22593] = {OId:266,H:"Класс! Отнеси Умникусу эту страничку из Морской энциклопедии. Правда, она немного порвалась..."};
tr[22594] = {H:"Нет, Умникусу такого показывать нельзя."};
tr[22595] = {H:"Ничего страшного! Сейчас склеим!"};
tr[22596] = {OId:265,H:"Крутота! Что это за штуку ты принёс?"};
tr[22597] = {H:"Это ловушка для вашего монстра. Не благодарите."};
tr[22598] = {H:"Упс! Вы не должны были этого видеть. Пойду-ка я отсюда."};
tr[22599] = {OId:266,H:"Да ладно? А что?! А как?! А давайте!"};
tr[22600] = {OId:265,H:"Мы готовы. Давай поймаем Култухтыша!"};
tr[22601] = {H:"Сейчас, сейчас. Выпускаю ловушку!"};
tr[22602] = {H:"Давайте поймаем! Но без меня..."};
tr[22603] = {OId:266,H:"Ой, какое милое чудище!"};
tr[22604] = {OId:267,H:"Я не чудище. Я школьник."};
tr[22605] = {H:"А я начинаю терять нить происходящего!"};
tr[22606] = {OId:267,H:"Я приехал учиться по обмену в подводную школу... Да только вот заблудился..."};
tr[22607] = {OId:265,H:"Точно! В школе же говорили про нового ученика!"};
tr[22608] = {H:"Я просто продолжу наблюдать."};
tr[22609] = {OId:266,H:"Ой, так ты новенький! А я не при наряде..."};
tr[22610] = {OId:265,H:"Мона, у него и лап восемь - прямо как у нас! Подружимся, значит!"};
tr[22611] = {H:"Тем временем я понял, что мы приняли за Култухтыша тень этого паучка!"};
tr[22612] = {OId:266,H:"Нужно отменить заклинание и отпустить его!"};
tr[22613] = {H:"Конечно! Сейчас отпустим!"};
tr[22614] = {H:"Ой... А я вот пауков как-то не очень люблю. Пускай повисит."};
tr[22615] = {H:"Затонувший город"};
tr[22616] = {H:"Пёрышки|Пёрышки прилетят через {0} мин."};
tr[22617] = {H:"Тайна морского чудища!"};
tr[22618] = {H:"Я уже побывал в Подводном мире и помог Спрутикам! А как насчёт тебя? Шарарам ждёт!"};
tr[22619] = {H:"Взять пёрышки"};
tr[22620] = {H:"Миссия Спрутики"};
tr[22621] = {H:"В море обнаружена подозрительная активность. Скорее отправляйся в Подводный мир!"};
tr[22622] = {OId:262,H:"Там, на островах – самолёт злодея, за которым я гонюсь! Побежали туда."};
tr[22623] = {OId:263,H:"Постойте! Я с вами летел – а теперь сломался. Почините меня, я пригожусь!"};
tr[22624] = {OId:263,H:"Но у меня доски в животе! Неужели, так оставите?"};
tr[22625] = {OId:263,H:"Я увидел тебя, и думаю – никак, расследование намечается! А это дело для Лиги Героев. Ты же помнишь – мы с тобой в Лиге же..."};
tr[22626] = {OId:262,H:"Ребята, я – к самолёту! А то преступник скроется, и всё пропало. Закончите починку, и сразу ко мне!"};
tr[22627] = {H:"Магия " + "\"" + "Чёрный Корсар" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в пирата ещё дней: {0}|Ты можешь превращаться в пирата всегда"};
tr[22628] = {H:"Приветствую, Коллега! Я – фанат игровых автоматов.  Как вы думаете, в каком веке придуман первый игровой автомат?"};
tr[22629] = {H:"В 19."};
tr[22630] = {H:"Верно! А в какой стране их придумали?"};
tr[22631] = {H:"Россия"};
tr[22632] = {H:"США"};
tr[22633] = {H:"В 16."};
tr[22634] = {H:"Я тут увлекайтся бытовой техника! Вот если я положу в кружку горящие угли – какой бытовой прибор я получайт?"};
tr[22635] = {H:"Холодильник!"};
tr[22636] = {H:"Утюг!"};
tr[22637] = {H:"Я-я! Теперь сложнее вопрос: как думаешь, какой прибор для кухни 100 лет назад весил 30 кг?"};
tr[22638] = {H:"Сумка-холодильник!"};
tr[22639] = {H:"Миксер!"};
tr[22640] = {H:"Салют, дружище! Угадай, что мощнее – современный смартфон или все компьютеры космической станции 1975 года?"};
tr[22641] = {H:"Смартфон!"};
tr[22642] = {H:"Да! А вот ещё загадка: в Бельгии и Финляндии есть такой вид спорта – метание...."};
tr[22643] = {H:"...мобильных телефонов!"};
tr[22644] = {H:"...икры!"};
tr[22645] = {H:"Компьютеры на станции!"};
tr[22646] = {H:"Приветик! Учёные говорят, провода скоро вообще станут не нужны! Как думаешь – к какому году они это обещают?"};
tr[22647] = {H:"К 2019."};
tr[22648] = {H:"Угу! А кто скоро будет управлять всеми автомобилями?"};
tr[22649] = {H:"Животные!"};
tr[22650] = {H:"Роботы!"};
tr[22651] = {H:"К 3050."};
tr[22652] = {H:"Причёска " + "\"" + "Галактика" + "\"" + ""};
tr[22653] = {H:"Космический холодильник"};
tr[22654] = {H:"РобоПовар Базу"};
tr[22655] = {H:"РобоПовар Зака"};
tr[22656] = {H:"Неправильно... Давай попробуем ещё раз!"};
tr[22657] = {H:"Найн! Попробуй отвечайт снова."};
tr[22658] = {H:"Кубок " + "\"" + "КосмоПовар" + "\"" + "|За участие в Битве инопланетных ресторанов"};
tr[22659] = {H:"Робот-пылесос"};
tr[22660] = {H:"Пиджак " + "\"" + "Мистер Загадка" + "\"" + ""};
tr[22661] = {H:"Причёска " + "\"" + "Мистер Загадка" + "\"" + ""};
tr[22662] = {H:"Трость " + "\"" + "Мистер Загадка" + "\"" + ""};
tr[22663] = {H:"Костюм " + "\"" + "Мистер Загадка" + "\"" + ""};
tr[22664] = {H:"Причёска и одежда для самых загадочных персон!|Ищи в своём гардеробе!"};
tr[22665] = {H:"Я супергерой!"};
tr[22666] = {H:"Мы с Лигой героев обезвредили Пиратов! Приходи и ты играть в Шарарам"};
tr[22667] = {H:"В чём сила, друг?"};
tr[22668] = {H:"Ёлки-копалки! Я отправляюсь на конкурс силачей. Поддержишь меня на тренировках?"};
tr[22669] = {H:"Время для силовых упражнений. Раз-два, раз-два!"};
tr[22670] = {H:"Укуси меня комар! Не переусердствуй так. Дадим мышцам отдых - пускай пока подрастут."};
tr[22671] = {H:"Проголодался? Не спеши, силач должен есть только здоровую пищу."};
tr[22672] = {H:"Конкурс начинается! Я пойду на арену, а ты собери для меня команду болельщиков!"};
tr[22673] = {H:"Ну вот! Мы входим в ритм тренировок. Так держать!"};
tr[22674] = {H:"Фух! Чувствуешь это покалывание? Ты стал сильнее!"};
tr[22675] = {H:"Ну чаго? Хорошо отдохнул? Держи Смешинки!"};
tr[22676] = {H:"Вот она - приятная сытость. И никакой тяжести в животе! Молодец!"};
tr[22677] = {H:"Зашиби меня пчела, я победил! В этом есть и твоя заслуга! Держи подарок - комбинезон " + "\"" + "Чемпион" + "\"" + "!"};
tr[22678] = {H:"Делаем разминку!"};
tr[22679] = {H:"Развиваем силу!"};
tr[22680] = {H:"Сделаем передышку!"};
tr[22681] = {H:"Здоровое питание!"};
tr[22682] = {H:"Конкурс силачей!"};
tr[22683] = {H:"Сначала поработаем над реакцией. Сыграй в Скачки в Парке аттракционов."};
tr[22684] = {H:"Теперь небольшая разминка. Победи Кроша в Волейболе на Пляже."};
tr[22685] = {H:"Развиваем плечевой мускул. Хорошенько размахнись и кинь {0} помидоров."};
tr[22686] = {H:"Я вывел сорт тяжелых груш. Попробуй поднять их - собери {0} штук в Ромашковой долине. "};
