tr[22898] = {H:"Фасад " + "\"" + "Иллюзии" + "\"" + ""};
tr[22899] = {OId:150,H:"Я привёз весёлые штуковины для твоих друзей! Выбирай всё для друга и для его домика –  дари подарки и стань королём шуток!"};
tr[22900] = {H:"Нюша свободна!"};
tr[22901] = {H:"Я спас её от злого компьютера в Клубе Иллюзий! Загляни в Шарарам, здесь весело!"};
tr[22904] = {OId:268,H:"У нас есть новый дом! Мы так рады!"};
tr[22905] = {H:"Опять заладил! Как это мы, если ты один?"};
tr[22906] = {OId:269,H:"Это же Ро! Они очень маленькие и их очень много!"};
tr[22907] = {OId:268,H:"Поэтому мы держимся все вместе!"};
tr[22908] = {H:"Надо же! И такое бывает..."};
tr[22909] = {OId:268,H:"Давай посмотрим на нашу планету! Будешь нашим первым гостем!"};
tr[22910] = {H:"Стойте, стойте! У меня в Шарараме утюг не выключен."};
tr[22911] = {H:"Полетели!"};
tr[22912] = {H:"Спасти"};
tr[22913] = {H:"Группа " + "\"" + "Аригато" + "\"" + " навсегда!"};
tr[22914] = {H:"Лучшая аниме-группа поразит тебя и твоих гостей Мега-хитом!|Ищи в своём клубе!"};
tr[22915] = {H:"Компьютерный чип|Компьютерный чип доставят через {0} мин."};
tr[22916] = {H:"Смешутка " + "\"" + "Чернушка" + "\"" + ""};
tr[22917] = {H:"Дари одёжки!"};
tr[22918] = {H:"Дари подарки для домика!"};
tr[22919] = {H:"Магия " + "\"" + "Ро" + "\"" + ""};
tr[22920] = {H:"Магия " + "\"" + "Ро" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в пришельца Ро ещё {0} дней!|Ты можешь превращаться в пришельца Ро всегда!"};
tr[22921] = {H:"Смешутка " + "\"" + "Чернушка" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращать Смешариков в Чернушек ещё {0} дней!|Ты можешь превращать Смешариков в Чернушек всегда!"};
tr[22922] = {H:"Я герой космоса!"};
tr[22923] = {H:"Я победил космических злодеев и построил целую планету! А как насчёт тебя? Шарарам ждёт!"};
tr[22924] = {H:"Ой, я засыпаааю! Последишь пока за часами? Кликни на них."};
tr[22925] = {H:"...Я до-олжен перевести часы на день назад..."};
tr[22926] = {H:"Сто-ой! Не переводи! Иначе завтра опять не настанет..."};
tr[22927] = {H:"Что ты мешаешься?!!\nМакс который день спасает мир от конца света, когда переводит эти часы!"};
tr[22928] = {H:"Ах, извините!.. Дело серьёзное. Я пойду тогда."};
tr[22929] = {H:"А?.. Что?.. Почему?!!"};
tr[22930] = {H:"Макс – один из нас – \nбог времени Хамелеонов. \nЕсли он не успеет перевести часы, то ровно в полночь..."};
tr[22931] = {H:"...Неужели нельзя по-другому конец света отменить? Док что, так и будет жить без завтра?"};
tr[22932] = {H:"Вот если б кто-то бессмертный нам секрет времени открыл..."};
tr[22933] = {H:"Так царь Гурдум же бессмертный!.. Давайте его найдём и спросим."};
tr[22934] = {H:"Злобикус бессмертный! Только говорите с ним сами, а то я в обиде..."};
tr[22935] = {H:"Похоже! Пойду, проверю."};
tr[22936] = {H:"Чего тебе надобно?"};
tr[22937] = {H:"Дяденька, это вы мне?.. Ничего мне от вас не надо, и вы отстаньте!"};
tr[22938] = {H:"Такое дело. Хочу знать секрет времени."};
tr[22939] = {H:"Все хотят. Но если б я его всем рассказывал... Опасно знать такое."};
tr[22940] = {H:"Ну, будь другом, выручай – а то конец света наступит. Оно нам надо?"};
tr[22941] = {H:"Пожа-алуйста, скажи... Просто, конец света близко. Я б не стал тебя зря отвлекать..."};
tr[22942] = {H:"Ладно, мне этот свет нравится больше других, – слушай: есть одни часы – против конца света верное средство."};
tr[22943] = {H:"Так, давай часы, и я побежал – некогда мне тут с тобой!.."};
tr[22944] = {H:"Ты дослушай! Эти часы обретут силу то-олько в руках бога вре-емени. Я их спрятал надё-ёжно..."};
tr[22945] = {H:"Да понял я, понял! Быстрее, старче – где часы?!! Уж полночь близится!"};
tr[22946] = {H:"Я спрятал Волшебные часы в Тёмном лабиринте Каньона."};
tr[22947] = {H:"Кокосовое молоко|Кокосовое молоко привезут через {0} мин."};
tr[22948] = {H:"Взять молоко"};
tr[22949] = {H:"Я провёл крутой день со Смешариками и получил подарок! Приходи и ты играть в Шарарам."};
tr[22950] = {H:"Я провёл крутой день с Доком и получил подарок! Приходи и ты играть в Шарарам."};
tr[22951] = {H:"Любит-не-любит?"};
tr[22952] = {H:"Кажется, у меня объявился тайный поклонник. Интересно, кто же это?"};
tr[22953] = {H:"Давай немножко погадаем. Вдруг получится узнать имя моего обожателя?"};
tr[22954] = {H:"Что-то мне подсказывает, что мой поклонник может быть путешественником!"};
tr[22955] = {H:"По-моему этот тайный поклонник слишком тайный! Пора действовать решительно!"};
tr[22956] = {H:"Ура! Я получила записку: мой тайный поклонник - Эйджей. Поможешь подготовиться к свиданию?"};
tr[22957] = {H:"Разузнаем, что к чему!"};
tr[22958] = {H:"Гадаем!"};
tr[22959] = {H:"Ищем поклонника!"};
tr[22960] = {H:"Кто любит Нюшу?"};
tr[22961] = {H:"Нюша идёт на свидание!"};
tr[22962] = {H:"Интересно, интересно. Судя по слухам, моим поклонником может оказаться кто угодно!"};
tr[22963] = {H:"Мы нагадали, что нужно продолжить поиски."};
tr[22964] = {H:"Мда... Чего-то и нет никого. Поищем в другом месте!"};
tr[22965] = {H:"Ого! Мне кажется, или мои тайные поклонники - это вообще все!?"};
tr[22966] = {H:"Спасибо! Я пошла на свидание. А ты держи подарок - ищи его в своём гардеробе!"};
tr[22967] = {H:"Поищем его на Пляже. Отправляйся туда."};
tr[22968] = {H:"Послушаем, что говорят Смешарики. Заработай {0} Смешинок в Кафе на Пляже."};
tr[22969] = {H:"Может, имя моего поклонника шепнут тебе на ушко? Сыграй в Секретики."};
tr[22970] = {H:"Морской ветер подскажет мою судьбу. Отправляйся в Пиратскую бухту."};
tr[22971] = {H:"Сначала погадаем на цветах. Собери {0} штук в Турфирме!"};
tr[22972] = {H:"Отправляйся в Порт."};
tr[22973] = {H:"Поищем его в открытом море? Прокатись на Катере и заработай {0} Смешинок!"};
tr[22974] = {H:"А вдруг мой поклонник под водой? Посмотри в перископ!"};
tr[22975] = {H:"Попробуем приманить поклонника вкусняшками! Собери {0} груш в Ромашковой долине."};
tr[22976] = {H:"Может, он любит похулиганить? Кинь {0} помидоров."};
tr[22977] = {H:"Спросим у Смешариков. Напиши в общий чат: " + "\"" + "Кто любит Нюшу?" + "\"" + ""};
tr[22978] = {H:"Подбери мне наряд - поработай в Доме Мод."};
tr[22979] = {H:"Ничего не успеваю! Подыщи нам место для встречи: сходи в {0} клубов. "};
tr[22980] = {H:"Весёлый енотик"};
tr[22981] = {OId:270,H:"Ура, каникулы! Крути Карусели – получай летние подарки!"};
tr[22982] = {H:"Арбузное кресло"};
tr[22983] = {H:"Смайлы " + "\"" + "Лето!" + "\"" + " на 7 дней"};
tr[22984] = {H:"Магия " + "\"" + "Водяной элементаль" + "\"" + ""};
tr[22985] = {H:"Спутник " + "\"" + "Солнце" + "\"" + ""};
tr[22986] = {H:"СмеШутка " + "\"" + "Песочек" + "\"" + ""};
tr[22987] = {H:"100 Смешинок"};
tr[22988] = {H:"100 Звёздочек"};
tr[22989] = {H:"Позитивная энергия: 100"};
tr[22990] = {H:"Уже в твоём кошельке."};
tr[22991] = {H:"Уже у тебя."};
tr[22992] = {H:"Кликни на значок " + "\"" + "Эмоции" + "\"" + "."};
tr[22993] = {H:"Ищи среди своих клубов."};
tr[22994] = {H:"Уже у тебя на складе."};
tr[22995] = {H:"Кликни на значок " + "\"" + "Эмоции" + "\"" + "."};
tr[22996] = {H:"Кликни на волшебную палочку и разыгрывай Смешариков."};
tr[22997] = {H:"Кликни на волшебную палочку и превращайся!"};
tr[22998] = {H:"Ищи в " + "\"" + "Аксессуарах" + "\"" + " на Личной карточке."};
tr[22999] = {H:"Уже среди твоих домиков."};
tr[23000] = {H:"Магия " + "\"" + "Водяной элементаль" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Водяного элементаля ещё {0} дней!|Ты можешь превращаться в Водяного элементаля всегда!"};
tr[23001] = {H:"СмеШутка " + "\"" + "Песочек" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё {0} дней!|Ты можешь шутить всегда!"};
tr[23002] = {H:"В Ромашковой долине старичка в короне видели. Это что ли царь твой?.."};
tr[23003] = {H:"Отлично! Я – в Каньон!"};
tr[23004] = {H:"Мороженые смайлы на 3 дня"};
tr[23005] = {H:"Солнечные Смайлы на 3 дня"};
tr[23006] = {H:"СмеШутка " + "\"" + "Песочек" + "\"" + " на 7 дней"};
tr[23007] = {H:"Магия " + "\"" + "Водяной элементаль" + "\"" + " на 7 дней"};
tr[23008] = {H:"СмеШутка  " + "\"" + "В никуда!" + "\"" + ""};
tr[23009] = {H:"СмеШутка " + "\"" + "В никуда!" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь отправлять Смешариков в чёрную дыру ещё дней: {0}|Ты можешь отправлять Смешариков в чёрную дыру всегда!"};
tr[23010] = {H:"Космос свободен!"};
tr[23011] = {H:"Я прогнал Монстрика и получил подарок! Заходи в Шарарам – здесь столько интересного!"};
tr[23012] = {H:"Смайлы " + "\"" + "Док" + "\"" + ""};
tr[23013] = {H:"Смайлы " + "\"" + "Макс" + "\"" + "\'"};
tr[23014] = {H:"Эмоции путешественника во времени!|Ищи на нижней игровой панели!"};
tr[23015] = {H:"Лунные фокусы"};
tr[23016] = {H:"Время для путешествий!"};
tr[23017] = {H:"Тайны неба"};
tr[23018] = {H:"Кто похитил Луну?"};
tr[23019] = {H:"Машина для пряток"};
tr[23020] = {H:"Вспомнить всё!"};
tr[23021] = {H:"В полнолуние я всегда превращаюсь в волка - я же оборотень. А тут кто-то взял и украл Луну! Срочно отправляемся в путешествие на её поиски!"};
tr[23022] = {H:"Искать Луну мы будем в древней стране тайн и загадок."};
tr[23023] = {H:"Богиня Нут говорит, что вор, укравший Луну, спрятался в Клубном Квартале."};
tr[23024] = {H:"Исчезнувшая Луна - это фокус! Я построил машину, которая её спрятала. Только вот... Машина сломалась, а без неё никак не вернуть Луну обратно."};
tr[23025] = {H:"Луна на месте. Правда, я совсем позабыл, как должен вести себя настоящий волк. Поможешь мне?"};
tr[23026] = {H:"Отлично! Мы готовы отправиться в путь. Держи Смешинки за помощь!"};
tr[23027] = {H:"Нут рассказала, где искать Луну. Спасибо, что помог - вот твои Смешинки."};
tr[23028] = {H:"Мы нашли его! За исчезновением Луны стоит Барон де Покус."};
tr[23029] = {H:"Ты такой молодец! Я починил машину и вернул Луну. Держи Смешинки за помощь."};
tr[23030] = {H:"Класс! Ты вернул Луну и напомнил мне, как быть волком. Держи свой подарок!"};
tr[23031] = {H:"Чтобы друзья без тебя не скучали, отправь им {0} открыток."};
tr[23032] = {H:"Собери запасы в дорогу. Заработай {0} Смешинок в игре Дары Леса."};
tr[23033] = {H:"Отправляйся в Египет."};
tr[23034] = {H:"Ну и жара! Утоли жажду - собери {0} кокоса."};
tr[23035] = {H:"Богиня неба Нут наверняка поможет найти Луну. Сыграй в её игру."};
tr[23036] = {H:"Позови друзей на помощь. Отправь сообщение на Шарафон {0} Смешарикам."};
tr[23037] = {H:"Где же прячется вор? Давай поищем среди артистов: посети {0} клубов."};
tr[23038] = {H:"Арр! Давай напугаем вора. Кинь {0} помидоров!"};
tr[23039] = {H:"Отправляйся в Ромашковую Долину."};
tr[23040] = {H:"Чтобы запустить машину, нам понадобится Вечный двигатель. Помоги Пину починить его. "};
tr[23041] = {H:"Для ремонта нужны редкие материалы. Заработай {0} Смешинок, чтобы купить их."};
tr[23042] = {H:"Как правильно рычать? Напиши в общий чат: " + "\"" + "Аррргх!" + "\"" + ""};
tr[23043] = {H:"Волк любит стаю. Покажи мне, что такое командный дух - сыграй в футбол."};
tr[23044] = {H:"Волк умеет за себя постоять. Покажи мне, как. Найди в Шарараме Призрака и загони его в ловушку."};
tr[23045] = {H:"Я спас светлячков!"};
tr[23046] = {H:"...И получил награду! Приходи в Шарарам за подарками!"};
tr[23047] = {OId:150,H:"Я - Джет Стет. А ты кто будешь?"};
tr[23048] = {H:"Я твой дублёр! Начинаем съёмки?"};
tr[23049] = {H:"Моё имя Опасность. Мой кулак - камень. Давай поборемся?"};
tr[23050] = {OId:150,H:"А чего бы и не начать? Я как раз привёл себя в форму!"};
tr[23051] = {H:"А зачем тебе быть в форме, если все трюки выполняю я?"};
tr[23052] = {OId:150,H:"Но, но! Побереги себя для съёмок, каскадёр!"};
tr[23053] = {H:"Так и быть, раз ты струсил."};
tr[23054] = {OId:150,H:"Затем, что я актёр! Ты - выполняешь трюки. Я - создаю Искусство!"};
tr[23055] = {H:"Когда сниматься-то будем, Мистер Искусство?"};
tr[23056] = {OId:150,H:"Надень мой костюм - он уже у тебя в гардеробе. Найди все съёмочные группы в Шарараме, прими участие в съёмках и возвращайся ко мне!"};
tr[23057] = {H:"Камера, мотор! Побежал сниматься!"};
tr[23058] = {H:"Костюм Джета Стета"};
tr[23059] = {OId:150,H:"Найди все съёмочные группы в Шарараме, прими участие в съемках и возвращайся ко мне!"};
tr[23060] = {H:"Спасибо! Ты освободил светлячков!"};
tr[23061] = {H:"Аксессуар " + "\"" + "Светлячки" + "\"" + ""};
tr[23062] = {H:"Скорпион|Скорпион приползёт через {0} мин."};
tr[23063] = {OId:257,H:"Чтобы сниматься в фильме, переоденься в костюм Джета Стета!"};
tr[23064] = {OId:150,H:"Великолепно! Блестяще! Круто же у тебя получается! И где ты научился так трюки выполнять?"};
tr[23065] = {H:"Да, вот... Как-то... Это... Ой, засмущался я чего-то."};
tr[23066] = {H:"Это всё талант! Сам от себя в восторге!"};
tr[23067] = {OId:150,H:"Следующая сцена фильма будет очень сложной! Справишься?"};
tr[23068] = {H:"Ха! А что надо будет сделать?"};
tr[23069] = {OId:150,H:"Мой герой проникнет в логово главного злодея, чтобы отобрать у него награбленные сокровища!"};
tr[23070] = {H:"Ух ты! Наверное, будет большая погоня!"};
tr[23071] = {OId:150,H:"Ещё как будет! Ещё как! Приходи на съёмку в пещеру. Вход в неё ищи в Клубном квартале!"};
tr[23072] = {H:"Бегу!"};
tr[23073] = {H:"Магия " + "\"" + "Икар" + "\"" + ""};
tr[23074] = {H:"Миссия Каскадёр"};
tr[23075] = {H:"Агент, мы поручаем тебе важную миссию: стань дублёром Джета Стета в приключенческом фильме."};
tr[23076] = {H:"Магия " + "\"" + "Икар" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь летать ещё {0} дней!|Ты можешь летать всегда!"};
tr[23077] = {H:"Расправь крылья!|Отправляйся в незабываемый полёт!|Удиви друзей трюками в небе!"};
tr[23078] = {H:"Великое переселение Смешариков началось!|Будь первым покорителем этих земель!|Устраивай космо-вечеринки с друзьями!"};
tr[23079] = {H:"Клуб Вулкан"};
tr[23080] = {H:"Космический портал"};
tr[23081] = {H:"Зябрийский зондик"};
tr[23082] = {H:"Шляпа " + "\"" + "Сатурн" + "\"" + ""};
tr[23083] = {H:"Скейтборд " + "\"" + "Кристалл" + "\"" + ""};
tr[23084] = {H:"Привет! Хочешь подарок? Ответь на хитрый вопрос: почему мы на Земле весим много, а на Мюре мало?"};
tr[23085] = {H:"А вы у нас на Земле только и делаете, что беляши лопаете! Вот и с весом проблемы."};
tr[23086] = {H:"Это же сила притяжения! Она на разных планетах - разная!"};
tr[23087] = {H:"Злобикус виноват! Он вас магией тяжести околдовал!"};
tr[23088] = {H:"Меня не проведешь! Шутите вы: везде у вас вес одинаковый."};
tr[23089] = {H:"Привет! Хочешь подарок? Ответь на хитрый вопрос: какой формы бывают планеты?"};
tr[23090] = {H:"Квадратные. Очень удобно - можно планету в коробочку положить."};
tr[23091] = {H:"Планеты плоские, это все знают."};
tr[23092] = {H:"Треугольные. Просто мне треугольники нравятся."};
tr[23093] = {H:"В этом мире всё круглое. И планеты шариковые."};
tr[23094] = {H:"Привет! Хочешь подарок? Ответь на хитрый вопрос: в какую сторону дует ветер в космосе?"};
tr[23095] = {H:"На юг. В космос ведь есть юг, да?"};
tr[23096] = {H:"Ветер в космосе дует туда, куда я захочу!"};
tr[23097] = {H:"Да куда угодно! Это же ветер."};
tr[23098] = {H:"А откуда в космосе ветер?"};
tr[23099] = {H:"Привет! Хочешь подарок? Ответь на хитрый вопрос: в космосе холодно или жарко?"};
tr[23100] = {H:"Ни холодно, ни жарко. Там вообще температуры нет."};
tr[23101] = {H:"Холодно. Брррр."};
tr[23102] = {H:"Там жарища та ещё! А всё из-за солнечной радиации."};
tr[23103] = {H:"Вот кому как, а мне нормально."};
tr[23104] = {H:"Фонтан"};
tr[23105] = {H:"Костюм де Покус"};
tr[23106] = {H:"Зябрийские смайлы"};
tr[23107] = {H:"Мой танец вызывает дождь. Хочешь - станцуем вместе?"};
tr[23108] = {H:"Какое-то сомнительное предложение..."};
tr[23109] = {H:"Здорово! А зачем ты вызываешь дождь?"};
tr[23110] = {H:"Как?! Неужели ты не понимаешь всю значимость дождя?!"};
tr[23111] = {H:"Ладно, ладно. Расскажи о своём дожде!"};
tr[23112] = {H:"Недавно открылся клуб " + "\"" + "Вулкан" + "\"" + ", там проходят самые жаркие тусовки! Ух, хоть бы дождик пошёл..."};
tr[23113] = {H:"Классный клуб, должно быть. А как туда попасть?"};
tr[23114] = {H:"Вулкан уснул!"};
tr[23115] = {H:"Я спас Шарарам от страшной катастрофы ! Присоединяйся к игре - здесь весело!"};
tr[23116] = {OId:150,H:"Ох, ну и натворили дел наши Крошки!"};
tr[23117] = {H:"Агент 003, я прибыл, чтобы оказать любую помощь. Что здесь случилось?"};
tr[23118] = {OId:150,H:"Я хотел показать Крошкам чудеса науки в своей лаборатории,  как вдруг они начали шалить и баловаться!"};
tr[23119] = {H:"Агент 003, и как вы только могли заснуть?!"};
tr[23120] = {OId:150,H:"Наверное, Крошки разбили банку с сонным порошком. Но это не главная проблема."};
tr[23121] = {H:"Говорите всю правду. Я готов."};
tr[23122] = {OId:150,H:"Моя лаборатория управляет энергией вулкана. А теперь, когда здесь всё сломано, в любой момент может начаться извержение!"};
tr[23123] = {H:"Ха! Я починю этот вулкан в два счёта!"};
tr[23124] = {OId:150,H:"Здорово! Успокой крошек и верни всё на свои места! Кликни на меня, если понадобится помощь."};
tr[23125] = {H:"Есть!"};
tr[23126] = {H:"Инопланетные эмоции!|Ищи на нижней игровой панели!"};
tr[23127] = {OId:150,H:"Где он? Ты его видел?! Мы ещё можем успеть!"};
tr[23128] = {H:"О! Привет, Шеф! Ты о чём?"};
tr[23129] = {OId:150,H:"Как о чём? Мы только что получили сигнал - Банк Смешинок ограбили!"};
tr[23130] = {H:"Ой... Так мы не фильм снимали, а банк грабили..."};
tr[23131] = {H:"Ограбили? Ничего не знаю. Ничего не видел."};
tr[23132] = {OId:150,H:"По моим подсчётам вор скрылся в лесу! Поможешь поймать его?"};
tr[23133] = {H:"Конечно, помогу!"};
tr[23134] = {H:"А мне дадут за помощь 25% от украденного?"};
tr[23135] = {OId:150,H:"Эти Смешинки принадлежат всем Смешарикам, а не только тебе!"};
tr[23136] = {H:"Жаль..."};
tr[23137] = {OId:271,H:"Надо же! Такой знаменитый актёр оказался попросту бандитом!"};
tr[23138] = {OId:272,H:"Да уж! Если бы не вы..."};
tr[23139] = {H:"И как ты только до такого додумался?"};
tr[23140] = {OId:272,H:"Всё просто. Я же актёр. Мне все доверяют. Вот я и выдавал настоящие ограбления за съёмку фильма."};
tr[23141] = {H:"Хитрый ты. Возьму себе на заметку..."};
tr[23142] = {OId:271,H:"Ну и шуточки! А с преступником мы разберёмся."};
tr[23143] = {H:"Так ему и надо!"};
tr[23144] = {H:"Орден каскадёра|За мастерски выполненные кинотрюки!"};
tr[23145] = {H:"Я раскрыл преступление!"};
tr[23146] = {H:"А ты знаешь, чем опасны съёмки кино в Шарараме? Скорее в игру!"};
tr[23147] = {H:"Фасад " + "\"" + "Вулкан" + "\"" + ""};
tr[23150] = {H:"Магия " + "\"" + "Каскадёр" + "\"" + ""};
