tr[23160] = {H:"фон " + "\"" + "Красная дорожка" + "\"" + ""};
tr[23161] = {H:"Очки 3D"};
tr[23162] = {H:"Шарафон " + "\"" + "Стоп-Кадр!" + "\"" + ""};
tr[23163] = {H:"Общайся как кинозвезда!|Ищи на Личной карточке."};
tr[23164] = {H:"Спутник Джонни"};
tr[23165] = {H:"Шарафон Снежного человека"};
tr[23166] = {H:"Я открыл новый материк!"};
tr[23167] = {H:"Приходи в Шарарам, здесь всегда интересно!"};
tr[23168] = {H:"Моя лодка разбилась недалеко от Джунглей! А некоторые детали прибило к берегам Шарарама. Найди их все!"};
tr[23169] = {H:"Мы прибыли в поисках Джо-Ворона! Поговори с ним на Главной Площади!"};
tr[23170] = {H:"Неизвестный материк"};
tr[23171] = {H:"Помоги островам! Найди их в Шарараме и поговори с их идолами!"};
tr[23172] = {H:"Моя лодка разбилась недалеко от Джунглей! А некоторые детали прибило к берегам Шарарама. Найди их все!"};
tr[23173] = {H:"Я помог живым островам!"};
tr[23174] = {H:"Приходи в Шарарам, тебя тоже ждут невероятные приключения."};
tr[23175] = {H:"Я открыл новый материк!"};
tr[23176] = {H:"Приходи в Шарарам, здесь всегда интересно!"};
tr[23177] = {H:"Мы прибыли в поисках Джо-Ворона! Поговори с ним на Главной Площади!"};
tr[23178] = {H:"На Главную Площадь"};
tr[23179] = {H:"Отлично! Лодка собрана! Отправляйся на неизвестный материк и открой его, прежде чем он врежется в Шарарам!"};
tr[23180] = {H:"Штурвал лодки"};
tr[23181] = {H:"Корпус лодки"};
tr[23182] = {H:"Мачта лодки"};
tr[23183] = {H:"Холодника"};
