tr[23187] = {H:"СмеШутка " + "\"" + "НЛО" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё {0} дней!|Ты можешь шутить всегда!"};
tr[23188] = {H:"Подробнее"};
tr[23189] = {H:"Время для космических приколов!|Вызывай летающую тарелку!|Пришельцы разыграют твоих друзей!"};
tr[23190] = {H:"Дом " + "\"" + "Неоткрытый материк" + "\"" + ""};
tr[23191] = {H:"Куртка " + "\"" + "Птицелов" + "\"" + ""};
tr[23192] = {H:"Маска " + "\"" + "Птицелов" + "\"" + ""};
tr[23193] = {H:"Костюм " + "\"" + "Птицелов" + "\"" + ""};
tr[23194] = {H:"Шапка " + "\"" + "Зябрушка" + "\"" + ""};
tr[23195] = {H:"Повелитель Зябрушек|Получи эту способность у лемура в Каньоне|Ты можешь летать c помощью Зябрушек ещё дней: {0}|Ты можешь летать c помощью Зябрушек всегда"};
tr[23196] = {H:"Зябрушкин кубок|за спасение Зябрушек"};
tr[23197] = {H:"КосмоСтанция|Загляни в гости к Капитану Базу. Отправляйся в безумный полёт\nпо метеоритному полю!"};
tr[23198] = {H:"Мюра|Планета пришельцев Ро. Стань космическим первопроходцем и прогони злобных Чернушек."};
tr[23199] = {OId:150,H:"Поговори с Космическим Пиратом в Порту!"};
tr[23200] = {OId:270,H:"Ох ты! Кто это у нас тут?"};
tr[23201] = {H:"Как это " + "\"" + "кто" + "\"" + "? Полечу вместе с тобой Комету усмирять, дружище!"};
tr[23202] = {OId:270,H:"Ахаха! Насмешил! Я один поймаю Комету и всю награду заберу себе!"};
tr[23203] = {H:"Один? Да эту Комету и втроём едва одолеть можно..."};
tr[23204] = {OId:270,H:"Ну так и иди! Собирай команду! Наверняка в Шарараме найдутся безумцы, согласные тебе помочь!"};
tr[23205] = {H:"Конечно. Пфф. И соберу. У меня-то есть друзья, в отличие от некоторых!"};
tr[23206] = {OId:270,H:"Иди-иди! Собирай команду! Наверняка в Шарараме найдутся безумцы, согласные тебе помочь!"};
tr[23207] = {H:"Диск|Диск запишут через {0} мин."};
tr[23208] = {OId:150,H:"Я подготовил для тебя корабль. Нажми на Пульт управления на Космодроме и выбери Комету, чтобы отправиться к ней."};
tr[23209] = {H:"Камин " + "\"" + "Дайвинг" + "\"" + ""};
tr[23210] = {H:"Кресло " + "\"" + "Дайвер" + "\"" + ""};
tr[23211] = {H:"Подводный диван"};
tr[23212] = {H:"Торшер " + "\"" + "Дайв" + "\"" + ""};
tr[23213] = {H:"Торшер " + "\"" + "Дайв" + "\"" + ""};
tr[23214] = {H:"Шкаф " + "\"" + "Акулка" + "\"" + ""};
tr[23215] = {H:"Блендер"};
tr[23216] = {H:"Робо-плита"};
tr[23217] = {H:"Вентилятор"};
tr[23218] = {H:"Робогриль"};
tr[23219] = {H:"Техно-тостер"};
tr[23220] = {H:"Чайник"};
tr[23221] = {OId:150,H:"Возьми роботов к себе домой! И прикупи мебель для дайверов! Она просто супер! У меня у самого дома – такая."};
tr[23222] = {H:"Призраки в домике!"};
tr[23223] = {H:"Проверяем строй-материалы!"};
tr[23224] = {H:"Красим дома!"};
tr[23225] = {H:"Наводим красоту!"};
tr[23226] = {H:"Отпугнём нечисть позитивом!"};
tr[23227] = {H:"Разберёмся с призраками!"};
tr[23228] = {H:"Я строю дома, а в них поселяются привидения! Жителям страшно. Помоги понять, в чём дело и прогнать нечисть."};
tr[23229] = {H:"Может, призракам нравится, как выглядят дома? Тогда сделаем другие!"};
tr[23230] = {H:"Призраки всё ещё в домиках... Но они не терпят красоты. Сейчас мы её наведём!"};
tr[23231] = {H:"Вспомнила - ещё призраков пугает позитив! Сейчас мы его на них обрушим."};
tr[23232] = {H:"Всё перепробовали, а духи из домов не пропадают. Придётся спросить, что им надо...."};
tr[23233] = {H:"В песке ничего необычного... Держи Смешинки за помощь."};
tr[23234] = {H:"Белые дома просто супер! Держи Смешинки."};
tr[23235] = {H:"Красивых домиков нечисть точно испугается!"};
tr[23236] = {H:"В домики, где полно позитива, призраки точно не сунутся. С меня - Смешинки."};
tr[23237] = {H:"Призрак признался: нечисти негде жить. Я построю для них виллу! Получай подарок: Лампу с Джинном в дом."};
tr[23238] = {H:"Я строю дома из песка. Проверим его – идём на Пляж."};
tr[23239] = {H:"Поищи, что есть в песке – сыграй в " + "\"" + "Секретики" + "\"" + " на Пляже."};
tr[23240] = {H:"Нарисуем новый план дома! Научись рисовать – посети урок волшебного карандаша в Школе магов."};
tr[23241] = {H:"Перекрасим дома в белый – отпугнём нечисть. Кинь {0} помидоров в любой дом."};
tr[23242] = {H:"Покрасим весь дом! Напиши в общий чат: " + "\"" + "Кидайтесь помидорами!" + "\"" + ""};
tr[23243] = {H:"Сходи к {0} друзьям в гости – посмотри, как красиво у них в домиках."};
tr[23244] = {H:"Уберём в домах для красоты! Прокатись на катере в Порту – набери чистой воды."};
tr[23245] = {H:"Посадим цветы возле домиков! Собери {0} штук в Бюро Путешествий."};
tr[23246] = {H:"Наберись позитива – потанцуй в {0} клубах."};
tr[23247] = {H:"Подкрепись после танцев. Найди в меню одного из клубов Рыбу и купи её."};
tr[23248] = {H:"Собери в Шарараме {0} позитивных энергии, чтобы отпугнуть нечисть."};
tr[23249] = {H:"Запасёмся волшебством перед разговором с духами! Собери в Школе магов {0} эликсиров. "};
tr[23250] = {H:"Спроси {0} друзей о духах. Напиши им на Шарафоны: " + "\"" + "У тебя водятся призраки?" + "\"" + ""};
tr[23251] = {H:"Друзья подсказали, кто главарь духов! Найди призрака в Шарараме и прогони его."};
tr[23252] = {H:"Фон " + "\"" + "На Дирижабле" + "\"" + ""};
tr[23253] = {H:"Диван " + "\"" + "Дирижабль" + "\"" + ""};
tr[23254] = {H:"Кепка " + "\"" + "Звёздная" + "\"" + ""};
tr[23255] = {H:"Куртка " + "\"" + "Облачко" + "\"" + ""};
tr[23256] = {H:"Воздушные Смайлики"};
tr[23257] = {H:"Вездеход"};
tr[23258] = {H:"Магия " + "\"" + "Дирижабль" + "\"" + ""};
tr[23259] = {H:"Магия " + "\"" + "Дирижабль" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь летать на дирижабле ещё дней: {0}|Ты можешь летать на дирижабле всегда"};
tr[23260] = {H:"Монстрик, уходи!"};
tr[23261] = {H:"Я остановил чудовище и получил подарок! Приходи в игру – здесь столько интересного!"};
tr[23262] = {OId:273,H:"Зашиби меня пчела, пираты атакуют!"};
tr[23263] = {OId:274,H:"Ахаха, спасибо, что выманили для меня Комету!"};
tr[23264] = {H:"Так это ты в нас стрелял?!"};
tr[23265] = {OId:274,H:"Конечно! Теперь я поймаю комету сам, и вся награда достанется мне!"};
tr[23266] = {OId:275,H:"Хэй, он отстрелил наш двигатель!"};
tr[23267] = {H:"Ты с ней не справишься! Только я знаю секрет, как её поймать!"};
tr[23268] = {H:"Ну и лети! Посмотрим, что Комета с тобой сделает."};
tr[23269] = {OId:273,H:"Сейчас я быстренько наш кораблик залатаю!"};
tr[23270] = {OId:274,H:"Смотрите, не заскучайте!"};
tr[23271] = {H:"Скатертью дорожка, Пират!"};
tr[23272] = {H:"Налить кипяток"};
tr[23273] = {H:"Кипяток|Чайник закипит через {0} мин."};
tr[23274] = {H:"Я – звезда Ледового шоу!"};
tr[23275] = {H:"Я победил банду и получил ГранПри ледового шоу! Сам попробуй! Беги играть в Шарарам."};
tr[23276] = {H:"Мы готовились к шоу, а дальше... Сумрак на Снежной горе расскажет, что случилось!"};
tr[23277] = {H:"...Шо? Опять я виноват? Та сколько ж можно?!!"};
tr[23278] = {H:"Ну, ещё не точно... Но позволь тебя спросить – почему ты в чёрном?"};
tr[23279] = {H:"Я эту шапку – нашОл... и  ботинку! И так-то – у меня алиби на ВСЁ!"};
tr[23280] = {H:"Мм... А али-били...  – это что?"};
tr[23281] = {H:"И что за алиби – выкладывай!"};
tr[23282] = {H:"Он ещё мне тут расследует! Алиби, это когда меня не было там, хде кто-то начудил! А значит – не я это."};
tr[23283] = {H:"И что за алиби – выкладывай!"};
tr[23284] = {H:"С детьмями своими гуляю в Парке весь месяц! Каникулы ж. У мене и фотки есть."};
tr[23285] = {H:"Понятно, больше не пристаю."};
tr[23286] = {H:"О, привет, как дела?"};
tr[23287] = {H:"Приветики, Крот! Не отпирайся – ты бандит. Я улику нашёл – бур."};
tr[23288] = {H:"Бур? А что это такое?"};
tr[23289] = {H:"Ой, только не надо тут притворяться! ...Ну – бур...!"};
tr[23290] = {H:"Ну, штука, чтоб землю копать, лёд бурить... артистов в прорубях топить..."};
tr[23291] = {H:"Мм, вообще-то, я сам не знаю, хотел тебя спросить..."};
tr[23292] = {H:"Простите, товарищ, вы меня обижаете! Мы, кроты, копаем ходы только лапами..."};
tr[23293] = {H:"Так я и поверил! Чем докажешь... -те?!!"};
tr[23294] = {H:"Вот справка... О том, что все кроты боятся техники до ужаса. Мы даже рентген никогда не делали. Бинтик в курсе."};
tr[23295] = {H:"Ох, бедняги. Ладно, извини – к бандитам тороплюсь."};
tr[23296] = {H:"Ну, ОК. Но лёгкие рентгеном-то проверьте! Работа ведь пыльная..."};
tr[23297] = {H:"Ой, как хорошо, что ты пришёл! Отпусти меня."};
tr[23298] = {H:"Тха, щщщаазз! Вижу, тебя поймали уже. Точно – бандит."};
tr[23299] = {H:"Не-а. Ты – главарь шайки в чёрном! Артистов губить вздумал?!"};
tr[23300] = {H:"Я не виноват! Мы играли в игру " + "\"" + "Морские узлы" + "\"" + " – все на обед ушли, а я запутался."};
tr[23301] = {H:"Хм.. странно. И давно ты тут?"};
tr[23302] = {H:"Да уж неделю! Смотри, как похудел!"};
tr[23303] = {H:"Мм, значит, ты не мог артистам зла причинить?"};
tr[23304] = {H:"Да я их обожаю! Я главный фанат реалити-шоу " + "\"" + "Дом..." + "\"" + ", ой – " + "\"" + "Жизнь Звёзд" + "\"" + "!"};
tr[23305] = {H:"Доказательства?!.."};
tr[23306] = {H:"Все серии у меня записаны! Проверь! – Пароль от ноутбука: 1234..."};
tr[23307] = {H:"Стоп-стоп! Верю. Никому не говори свой пароль..."};
tr[23308] = {H:"Ну что, нашёл уже бандитов?"};
tr[23309] = {H:"Сумрачик, прости, но на напильнике – отпечатки твоих... лап..."};
tr[23310] = {H:"Ох... так и знал я – этим кончится!.. Да, напильник – мой..."};
tr[23311] = {H:"То есть – ты признаёшься в преступлении?"};
tr[23312] = {H:"Ладно, пускай ты бандит.. Но я же никому не скажу... – и ты победишь в Ледовом шоу, да?"};
tr[23313] = {H:"Я признаюсь только в том, что напильником я... ногти подпиливаю... Но пойми – они вырастают до полу!"};
tr[23314] = {H:"Мм... Я не про то! Артистам-то ты не пакостил?"};
tr[23315] = {H:"Да я хочу их победы –  я же, вообще-то, их тренирую!"};
tr[23316] = {H:"Ох, ну если так.. Выходит – не ты это...."};
tr[23317] = {H:"Хм... вот, как тебе верить, ты же когда звереешь – не помнишь ничего..."};
tr[23318] = {H:"Не я это! Жуб даю! Я как раз бежал за ниндзя – он в Каньоне. Сам проверь."};
tr[23319] = {H:"ОК. Но если что – я ведь тебя достану!.."};
tr[23320] = {OId:278,H:"Спасибоньки, бандитики! Теперь победочка в шоу точно моя!"};
tr[23321] = {OId:277,H:"На здоровье, хозяйка!"};
tr[23322] = {H:"Ахааа, попалась?!! Не ожидааал..."};
tr[23323] = {OId:278,H:"Ох... Простите, Смешарики добрые! Виноватенькая я..."};
tr[23324] = {H:"Жалеешь?.. Зачем ДРУЗЬЯМ репетировать мешала! Не стыдно?"};
tr[23325] = {OId:278,H:"Милый, я и сама не рада, но я ДОЛЖНА. А то папа мой расстроится...– он меня учил только побеждать!.."};
tr[23326] = {H:"А что он сделает? Ремня даст? – До шоу заживёт!"};
tr[23327] = {H:"Так, есть идея – станцуйте на шоу все вместе – командой!"};
tr[23328] = {OId:278,H:"Отли-ично! ...Но надо порепетировать. Будешь нашим хореографом?"};
tr[23329] = {H:"Замётано, Сиренчик! Только сгоняю в Дом Звёзд – найду музыку для нашего танца!"};
tr[23330] = {H:"Ну нее, это риски..."};
tr[23331] = {H:"Нет! Шоу вот-вот начнётся – не успеем..."};
tr[23332] = {OId:150,H:"Поговори с Кометой!"};
tr[23333] = {OId:276,H:"Ну наконец-то!!!"};
tr[23334] = {H:"О, привет! Говорящая Комета - всё, как я люблю."};
tr[23335] = {OId:276,H:"Неужели?! Неужели?! Неужели?!"};
tr[23336] = {H:"Какая-то ты безумная. Не буду с тобой разговаривать."};
tr[23337] = {H:"" + "\"" + "Неужели" + "\"" + " что?"};
tr[23338] = {OId:276,H:"Ох, я тысячу лет летала над Шарарамом. Летала и летала, летала и летала!"};
tr[23339] = {H:"С кем не бывает?"};
tr[23340] = {OId:276,H:"И хоть бы кто, ну хоть кто-нибудь обратил на меня внимание? Никто не говорил со мной, никто не играл и не дружил!"};
tr[23341] = {H:"О! Так ты поэтому приставала к нашим ракетам и мешала им летать?"};
tr[23342] = {H:"Я вот смотрю на тебя, и тоже как-то дружить не тянет."};
tr[23343] = {OId:276,H:"Я хотела внимания! Я ЖЕ КОМЕТА!"};
tr[23344] = {H:"Оу-оу! Вот тебе моё внимание - бери, сколько хочешь!"};
tr[23345] = {OId:150,H:"Скорее помоги Пирату!"};
tr[23346] = {H:"Хвостатые смайлы"};
tr[23347] = {H:"Комета"};
tr[23348] = {H:"Просто космос!"};
tr[23349] = {H:"Я подружился с Кометой в Шарараме! Присоединяйся и ты!"};
tr[23350] = {H:"Орден " + "\"" + "Друг Кометы" + "\"" + "|За внимание к космическим обитателям"};
tr[23351] = {H:"Доспехи агента"};
tr[23352] = {H:"Железные боты"};
tr[23353] = {H:"Костюм для самых опасных миссий!|Ищи его в своём гардеробе!"};
tr[23354] = {H:"Скейт " + "\"" + "ПчелоДрайв" + "\"" + ""};
tr[23355] = {H:"Камин " + "\"" + "Улей" + "\"" + ""};
tr[23356] = {H:"Пчелиная СмеШутка"};
tr[23357] = {H:"Пчелиная СмеШутка|Бззззз|Бззззз|Бззззз"};
tr[23358] = {H:"Бутсы " + "\"" + "Смешбол" + "\"" + ""};
tr[23359] = {H:"Грим " + "\"" + "Смешбол" + "\"" + ""};
tr[23360] = {H:"Пчелиная СмеШутка|Получи эту способность у лемура в Каньоне|Ты можешь насылать пчёл на Смешариков ещё дней: {}|Ты всегда можешь насылать пчёл на Смешариков"};
tr[23361] = {H:"Футбольный набор"};
tr[23362] = {H:"Бутсы, мяч и грим игрока!|Ищи в своём гардеробе!"};
tr[23363] = {H:"Будешь нашим хореографом? Найди музыку для нашего танца в Доме Звезд."};
tr[23364] = {H:"в Дом Звёзд"};
tr[23365] = {H:"Клуб Космических Зверушек с приключениями!"};
tr[23366] = {H:"Клуб Космических Зверушек!"};
tr[23367] = {H:"Шерстяш"};
tr[23368] = {H:"Почему ты здесь?"};
tr[23369] = {H:"А ты почему здесь?"};
tr[23370] = {H:"А где я должен быть?"};
tr[23371] = {H:"Неправда. В мыслях я уже далеко не здесь!"};
tr[23372] = {H:"И где же?"};
tr[23373] = {H:"В Клубе Космических Зверушек!\nТам зоопарк! Космишка бродит, \nКислоид на ветвях сидит.\nЖирун ночами песнь заводит,\nА Пучеглаз в норе сопит."};
tr[23374] = {H:"Весёлый клуб, должно быть. А как туда попасть?"};
tr[23375] = {OId:150,H:"Ура, ты пришёл! С помощью голограммы я смогу помогать тебе и отмечать Золнечный праздник одновременно! Круто, правда?"};
tr[23376] = {H:"Ага. Кому праздновать, а кому работать..."};
tr[23377] = {OId:150,H:"Не волнуйся, не волнуйся. За помощь я отблагодарю тебя со всей зябрийской щедростью!"};
tr[23378] = {H:"А делать-то чего надо?"};
tr[23379] = {OId:150,H:"Сначала покорми моих зверушек. Ты только посмотри на них! Кто у нас проголодался? Кто у нас хочет ням-ням?"};
tr[23380] = {H:"Покормить зверушек. Ясно. Страшно подумать, что будет дальше..."};
tr[23381] = {H:"Не хочу я никого кормить. Сам голодный."};
tr[23382] = {OId:150,H:"Ой, какие молодцы. Сытые, чистые, довольные. И мне весело, и зверушкам весело, и всем здорово!"};
tr[23383] = {H:"Да, да, да. Что там, кстати, насчёт щедрости зябрийской?"};
tr[23384] = {OId:150,H:"Конечно, конечно! Дам тебе невероятный подарок. Ты только присмотри за ещё одной зверушкой..."};
tr[23385] = {H:"Что это за " + "\"" + "ещё одна зверушка" + "\"" + "?"};
tr[23386] = {OId:150,H:"Ну маленький такой монстрик, ну подумаешь, ну там вообще с ним никаких проблем. Совсем. Почти."};
tr[23387] = {H:"Почти?"};
tr[23388] = {OId:150,H:"Да ты не волнуйся! Шёрстку ему расчешешь и всего-то дел..."};
tr[23389] = {H:"Ну ладно. Где он у тебя?"};
tr[23390] = {H:"Дай сначала отдышаться!"};
tr[23391] = {H:"Я приручил инопланетных зверушек !"};
tr[23392] = {H:"Злой Шерстяш стал добряком! Скорее в Шарарам - здесь много интересного!"};
tr[23393] = {H:"Я улетаю на праздник Золнышек! Кто же присмотрит за зверушками в моём зоопарке? Может быть, ты?"};
tr[23394] = {H:"Присмотреть"};
tr[23395] = {H:"Сюртук " + "\"" + "Стальной пират" + "\"" + ""};
tr[23396] = {H:"Катер для тусовок"};
tr[23397] = {H:"Тельняшка " + "\"" + "Рок-пират" + "\"" + ""};
tr[23398] = {H:"Очки " + "\"" + "SOS" + "\"" + "!"};
tr[23399] = {H:"Сундучок с золотом"};
tr[23400] = {H:"Свитерок " + "\"" + "Морячок" + "\"" + ""};
tr[23401] = {H:"Пляжный зонтик"};
tr[23402] = {H:"Спрутик"};
tr[23403] = {H:"Часы-рыбка"};
tr[23404] = {H:"Круговой диван"};
tr[23405] = {H:"Подводная ширма"};
tr[23406] = {H:"Золотой Диван"};
tr[23407] = {H:"Гора из золота"};
tr[23408] = {H:"Часы " + "\"" + "Пират" + "\"" + ""};
tr[23409] = {H:"Шарафон " + "\"" + "Чёрная Акула" + "\"" + ""};
tr[23410] = {H:"Пиратский шарафон"};
tr[23411] = {H:"Шарафон " + "\"" + "Рыбка" + "\"" + ""};
tr[23412] = {H:"Магия зябрийцам!"};
tr[23413] = {H:"Керосиновая лампа"};
tr[23414] = {H:"Фонарь " + "\"" + "Черепок" + "\"" + ""};
tr[23415] = {H:"Аквариум"};
tr[23416] = {H:"В Школу магов!"};
tr[23417] = {H:"Магия стихий"};
tr[23418] = {H:"Домашнее задание"};
tr[23419] = {H:"Магия веселья"};
tr[23420] = {H:"Экзамены для волшебника"};
tr[23421] = {H:"Привет! Знаешь, что умеют делать зябрийцы? Да почти всё! Единственное, чего мы не умеем - колдовать! Научишь меня? А я передам знания остальным."};
tr[23422] = {H:"В Школе магов сказали, что больше всего волшебства скрывают в себе силы природы."};
tr[23423] = {H:"Ну вот! В Школе магов мне дали домашнее задание, а я совсем не справляюсь."};
tr[23424] = {H:"Босс Ба-Босс сказал мне, что главная магия в Шарараме - магия веселья. Что это такое вообще?"};
tr[23425] = {H:"Кажется, я готов начать колдовать сам! Давай сотворим настоящее волшебство! "};
tr[23426] = {H:"Магия - это так сложно. Спасибо, что помогаешь! Вот тебе Смешинки."};
tr[23427] = {H:"Я познаю магию стихий! Держи Смешинки за помощь!"};
tr[23428] = {H:"Я справился с домашним заданием! А ты получай свою награду. "};
tr[23429] = {H:"Ура! Я самый весёлый инопланетный маг в Шарараме! Лови Смешинки за помощь!"};
tr[23430] = {H:"Теперь я опытный маг. В благодарность я зачаровал для тебя одежду - получай Золотой костюм. "};
tr[23431] = {H:"Я слышал, про место, где вы учитесь колдовству. Отправимся в Школу магов."};
tr[23432] = {H:"А правда, что маги могут рисовать силой мысли? Сыграй в Волшебный Карандаш."};
tr[23433] = {H:"Ух ты! Волшебные эликсиры! А что они делают? Проверим! Собери для меня {0} штук."};
tr[23434] = {H:"Выйдем в открытое море. Прокатись на Катере в Порту!"};
tr[23435] = {H:"Изучим лесную магию. Заработай {0} Смешинок в игре Дары леса."};
tr[23436] = {H:"А какое волшебство таит в себе Снежная гора? Спустись с неё на Ватрушке!"};
tr[23437] = {H:"Попросим помощи у друзей-волшебников! Посети {0} домиков."};
tr[23438] = {H:"В благодарность за помощь отправь друзьям {0} открыток!"};
tr[23439] = {H:"Выучим заклинание. Напиши в общий чат: " + "\"" + "Зябрикус Магикус!" + "\"" + "."};
tr[23440] = {H:"Весёлые танцы помогут отпугнуть тёмные силы. Потанцуй в {0} клубах!"};
tr[23441] = {H:"Угости меня заколдованной едой! Найди в меню клуба Пончики и купи."};
tr[23442] = {H:"Снежная битва поднимает настроение! Кинь {0} помидоров!"};
tr[23443] = {H:"Накопим позитив! Собери {0} Позитивных энергий в любой игре."};
tr[23444] = {H:"Испытаем белую магию. Найди в Шарараме {0} Чудиков и прогони."};
tr[23445] = {H:"Я научился видеть скрытое! А ты? Давай проверим: выиграй в Секретики на Пляже."};
tr[23446] = {H:"Песочный диван"};
tr[23447] = {H:"Часы " + "\"" + "Чёрный кот" + "\"" + ""};
tr[23448] = {H:"Песочный остров"};
tr[23449] = {H:"Идол"};
