tr[23580] = {H:"СмеШутка " + "\"" + "Улыбнись" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь осыпать Смешариков улыбками ещё дней: {0}|Ты можешь осыпать Смешариков улыбками всегда!"};
tr[23581] = {H:"Праздник космических кривляк"};
tr[23582] = {H:"Привет! Мы привезли в Шарарам праздник! Ты ещё не знаешь, как наряжаются Зябрийцы к Празднику космических кривляк? Узнай в Летающей тарелке, и приходи снова!"};
tr[23583] = {H:"Сначала нарядись к празднику! Купи в Летающей тарелке наряд, надень его и приходи снова."};
tr[23584] = {H:"Шарарам! Ик!"};
tr[23585] = {H:"Икота, уходи!"};
tr[23586] = {H:"Весело икаем!"};
tr[23587] = {H:"Почему ты не икаешь?"};
tr[23588] = {H:"Готовим лекарство!"};
tr[23589] = {H:"Апчхи!"};
tr[23590] = {H:"В Шарараме эпидемия, ик, икоты. Что же делать? Ик!"};
tr[23591] = {H:"Ик! Пока доктор Бинтик ищет лекарство от икоты, мы с тобой не дадим Смешарикам унывать."};
tr[23592] = {H:"Я вот тут подумал: интересно, ик, а ты-то почему не икаешь?"};
tr[23593] = {H:"Помоги мне вылечить Смешариков!"};
tr[23594] = {H:"Апчхи! Ой... Икота ушла, но теперь мы все чихаем! Наверное, я с лекарством что-то напутал."};
tr[23595] = {H:"Икота пока отступила. Но надолго ли?"};
tr[23596] = {H:"Ик! Никогда ещё тусовки в клубах, ик, не были такими, ик, необычными! Держи Смешинки за находчивость!"};
tr[23597] = {H:"Удивительно, ик! Изучив тебя, я открыл лекарство от икоты! "};
tr[23598] = {H:"Лекарство готово! Теперь Смешарики не будут икать."};
tr[23599] = {H:"Смешарики здоровы! Получай за помощь подарок: Полезный амулет."};
tr[23600] = {H:"Икоту сдерживает испуг. Напугай Смешариков - брось в них {0} помидоров."};
tr[23601] = {H:"Ик! Напиши в общий чат: " + "\"" + "Икота-икота, перейди на Федота!" + "\"" + ""};
tr[23602] = {H:"Выпьем водички. Найди в меню одного из клубов Минеральную воду и закажи её. "};
