tr[23612] = {H:"Поправим здоровьице. Отправляйся на Пляж."};
tr[23613] = {H:"Спорт укрепит организм. Сыграй в Волейбол и заработай {0} Смешинок."};
tr[23614] = {H:"Полезный амулет"};
