tr[23617] = {H:"Урок магической гимнастики"};
tr[23618] = {H:"Ура! Ты помог мне победить!  Ставлю тебе " + "\"" + "зачёт" + "\"" + ". Ищи Ковёр среди мебели в домике"};
tr[23619] = {H:"Ковёр " + "\"" + "Гимнастика" + "\"" + ""};
tr[23620] = {H:"Ураган|Ураган начнётся через {0} мин."};
tr[23621] = {OId:281,H:"АААА!!!"};
tr[23622] = {H:"Тетёнька, от вашего крика ураган поднялся, и мир, вообще-то, рушится! Не заметили?"};
tr[23623] = {H:"ААА!!!! Орущая планета-ааАА приближаетсяААА!!!"};
tr[23624] = {OId:281,H:"ААЫЫЫЫ!!! Я потеряла спутника своегоОО! Махонький, ты гдеЕЕЕЕ?!!"};
tr[23625] = {H:"Гражданочка потерпевшая, конкретнее опишите – кого ищем?"};
tr[23626] = {H:"Стоп-стоп! Как выглядел, когда исчез?"};
tr[23627] = {OId:281,H:"ААА–...-аА! Мой спутник! Маленький, круглый, фиолетовый, пропал тыщщу лет назад... "};
tr[23628] = {H:"Ясно! Мы найдём его! А успокоиться вы не можете случайно?"};
tr[23629] = {OId:281,H:"НеЕЕАт, не могууу! "};
tr[23630] = {H:"Так, ну тогда я срочно бегу искать в Шарараме фиолетовых..."};
tr[23631] = {OId:283,H:"Решили ЮИ отправить как спутника – а то планета совсем взбесилась. Сейчас его округлим, замаскируем..."};
tr[23632] = {H:"Ммм.. а может, не надо?"};
tr[23633] = {H:"Годно! Чем помочь?"};
tr[23634] = {H:"Ягодная толстовка"};
tr[23635] = {OId:279,H:"Ом-ном-ном! Ой, как вкусно. Но не буду объедаться, ещё только одно ведёрко ягодок наверну! Всего одно!"};
tr[23636] = {H:"Нюша, ты ли это?"};
tr[23637] = {H:"Ой, а ты кто?"};
tr[23638] = {OId:279,H:"Да как ты можешь меня не узнать? Это же я - Нюша. Ном-ном..."};
tr[23639] = {H:"Нюша? Что с тобой стало? Погляди-ка в зеркало!"};
tr[23640] = {OId:279,H:"Ай, ай, ай! Кто это? Это я? Нет, это не я! Что со мной? Ай, помогите! Дай-ка ещё ягодок..."};
tr[23641] = {H:"А, понятно! Тебя эти дикие инопланетные ягоды такой сделали!"};
tr[23642] = {H:"Ой, а дай-ка и мне заодно!"};
tr[23643] = {OId:279,H:"Ном-ном, нет! Эти ягодки только мои. Ням-ням, не отдам!"};
tr[23644] = {H:"Ясно всё. Это из-за ягод ты так изменилась."};
tr[23645] = {OId:279,H:"Ням-ням. Ты прав. Поможешь мне вернуть красоту?"};
tr[23646] = {H:"Конечно!"};
tr[23647] = {H:"Нюша, такой ты мне нравишься даже больше!"};
tr[23648] = {OId:280,H:"Спасибочки! Благодаря тебе я снова красива и больше не похожа на гусеницу!"};
tr[23649] = {H:"У тебя уже достаточно фонарей, чтобы найти все орехи!"};
tr[23650] = {H:"Кепка-Ягодка"};
tr[23651] = {H:"Ягодный шарф"};
tr[23652] = {H:"Платье " + "\"" + "Ягодка" + "\"" + ""};
tr[23653] = {H:"Сочный фонтан"};
tr[23654] = {OId:284,H:"Этот спутник  похож, но что-то не то.. Проверь-ка у Сэнсэя в метро в Ромашковой долине!"};
tr[23655] = {OId:282,H:"Оой, Сэнсэй мне по рации передаёт, чтоб ты к нему срочно зашёл в Заброшенное метро!"};
tr[23656] = {H:"Хорошо, бегу!"};
tr[23657] = {H:"Дом Марараша"};
tr[23658] = {OId:286,H:"Ох-хэхэх... Привет тебе, землянин."};
tr[23659] = {H:"Привет-привет! А чего грустные такие?"};
tr[23660] = {OId:285,H:"А мы всегда такие, когда мы на Зябре... Ой, тоскаааа...."};
tr[23661] = {OId:286,H:"Стыдно признаться, но мы прилетаем в Шарарам на праздники от того, что на Зябре всегда очень грустно..."};
tr[23662] = {H:"А ну, не распускать нюни мне! Рассказывайте по порядку."};
tr[23663] = {H:"Ну, постарайтесь не рыдать! Расскажите, как так вышло?"};
tr[23664] = {OId:286,H:"Тысячу лет назад наша планета сбилась с пути. И теперь всегда – грустная."};
tr[23665] = {H:"Ой, как печально... А это у вас что за Ёжик рядом?"};
tr[23666] = {OId:285,H:"Это глобус. Так выглядит наша Зябра."};
tr[23667] = {OId:286,H:"Зябра – это космический Ёжик, который в детстве заблудился и потерял маму."};
tr[23668] = {H:"Всё сходится!!! Мама вашего Ёжика обыскалась! Скорее, поможем им встретиться!"};
tr[23669] = {H:"Костюм с Зябры"};
tr[23670] = {H:"Ботинки с зябры"};
tr[23671] = {H:"Смайлы " + "\"" + "С ветерком!" + "\"" + ""};
tr[23672] = {H:"Поболтаем?"};
tr[23673] = {H:"Очень хочется вкусняшек. Посоветуешь?"};
tr[23674] = {H:"Расскажи стишок!"};
tr[23675] = {H:"Как там с погодкой на завтра?"};
tr[23676] = {H:"Хочу задать личный вопрос..."};
tr[23677] = {H:"Спрашивай!"};
tr[23678] = {H:"Помоги мне решить домашку."};
tr[23679] = {H:"Что ты думаешь обо мне?"};
tr[23680] = {H:"Что ты думаешь о Ёжике?"};
tr[23681] = {H:"Поговорим о чём-нибудь другом?"};
tr[23682] = {H:"А какое у тебя настроение?"};
tr[23683] = {H:"Летнее."};
tr[23684] = {H:"Съешь мюрийскую зябретку."};
tr[23685] = {H:"Зимнее."};
tr[23686] = {H:"Выпей чайку с мюлоном."};
tr[23687] = {H:"Мечтательное."};
tr[23688] = {H:"Как насчёт хлюпких мюмзиков?"};
tr[23689] = {H:"Таинственное."};
tr[23690] = {H:"Предлагаю сырный мугурт."};
tr[23691] = {H:"Класс! Поговорим о чём-нибудь другом?"};
tr[23692] = {H:"Приятно поболтали. До встречи, Ро!"};
tr[23693] = {H:"Какой?"};
tr[23694] = {H:"Печальный."};
tr[23695] = {H:"В лесу родились монстрики, в лесу они росли..."};
tr[23696] = {H:"Задумчивый."};
tr[23697] = {H:"Идёт Лосяш, качается, вздыхает на ходу..."};
tr[23698] = {H:"Жизненный."};
tr[23699] = {H:"Наша Нюша громко плачет, уронила в речку шляпу..."};
tr[23700] = {H:"Весёлый."};
tr[23701] = {H:"У Лукоморья Крош весёлый, златая цепь на Кроше том..."};
tr[23702] = {H:"А что ты видишь за окном?"};
tr[23703] = {H:"Птичек."};
tr[23704] = {H:"Будет фруктовый град."};
tr[23705] = {H:"Снег."};
tr[23706] = {H:"Обещают зябрушные ветра."};
tr[23707] = {H:"Спрутиков."};
tr[23708] = {H:"Это к полярному утру."};
tr[23709] = {H:"Солнце."};
tr[23710] = {H:"Тебе не помешает железный зонт."};
tr[23711] = {H:"А по какому предмету?"};
tr[23712] = {H:"Математика."};
tr[23713] = {H:"Оставь надежду, всяк сюда входящий..."};
tr[23714] = {H:"Литература."};
tr[23715] = {H:"Капитанскую Анну Онегину написал Лев Сергеевич Гоголь."};
tr[23716] = {H:"История."};
tr[23717] = {H:"Зябру основал Князь Зюзель Пёстро Золнышко."};
tr[23718] = {H:"Рисование."};
tr[23719] = {H:"Не спрашивай меня. Лучше сыграй в Волшебный карандаш."};
tr[23720] = {H:"Много всего..."};
tr[23721] = {H:"Расскажи о моей красоте"};
tr[23722] = {H:"Ты прекрасен как квинторианская пухля."};
tr[23723] = {H:"Расскажи о моём уме"};
tr[23724] = {H:"Твой ум остр, как мюрийский перчик."};
tr[23725] = {H:"Расскажи о моей силе"};
tr[23726] = {H:"Твоей силе позавидуют 10 злобырей-великанов."};
tr[23727] = {H:"Расскажи о моём чувстве юмора"};
tr[23728] = {H:"Не припомню, чтобы ты шутил..."};
tr[23729] = {H:"А что бы ты хотел обсудить?"};
tr[23730] = {H:"Ёжик со мной не разговаривает"};
tr[23731] = {H:"Угости его грушей."};
tr[23732] = {H:"Мне кажется, Ёжик загрустил"};
tr[23733] = {H:"Потому что кто-то постоянно кидается в него помидорами."};
tr[23734] = {H:"Ёжик - мой герой!"};
tr[23735] = {H:"А как же мы?! Ро - не твои герои???"};
tr[23736] = {H:"Как стать Ёжиком?"};
tr[23737] = {H:"Это одна из загадок, которую мы никогда не разгадаем..."};
tr[23738] = {H:"Особняк на Мюре"};
tr[23739] = {H:"Я нашёл спутник Планеты!"};
tr[23740] = {H:".. и спас Зябрийцев! А ты сможешь? Беги играть в Шарарам."};
