tr[23839] = {H:"Я победил Злобырей в Космосе и получил клуб в подарок! А тебе слабо? – Беги в Шарарам!"};
tr[23840] = {H:"У тебя уже есть этот подарок!"};
tr[23841] = {H:"Спасибо за покупку!"};
tr[23842] = {H:"Олимпийский костюм"};
tr[23843] = {H:"Одежда для чемпионов!|Ищи в своём гардеробе!"};
tr[23844] = {OId:270,H:"Здрасьте!"};
tr[23845] = {H:"Эй! Я чего-то не понял. Почему ты - это я? Хватит быть мной!"};
tr[23846] = {OId:270,H:"Нет. Это ты я. А я это я. И ты перестань быть мной."};
tr[23847] = {H:"Ты меня запутал!"};
tr[23848] = {H:"Не шути со мной!"};
tr[23849] = {OId:270,H:"Ладно, ладно! Я - дух желаний и принимаю облик того, кого вижу."};
tr[23850] = {H:"Дух желаний? Это что такое вообще?"};
tr[23851] = {OId:270,H:"Я прихожу в дни рождения, когда на торте задувают свечи. Хочешь сюрприз?"};
tr[23852] = {H:"Только без фокусов!"};
tr[23853] = {H:"А давай!"};
tr[23854] = {OId:270,H:"Я умею исполнять самые сокровенные желания. Вот смотрю я на тебя и вижу..."};
tr[23855] = {H:"Меня?"};
tr[23856] = {H:"И видишь перед собой уважаемого и выдающегося Смешарика!"};
tr[23857] = {OId:270,H:"Да нет же! Вижу, ты мечтаешь о том, чтобы в Шарараме наступила осень."};
tr[23858] = {H:"Ну... Допустим, почему бы и нет."};
tr[23859] = {OId:270,H:"Вуаля!"};
tr[23860] = {H:"Чего-чего?"};
tr[23861] = {OId:270,H:"Другие духи уже ждут тебя. Найди их в Шарараме, и они исполнят твои желания!"};
tr[23862] = {H:"Бассейн с акулками"};
tr[23863] = {H:"Фонтан " + "\"" + "Зависай!" + "\"" + ""};
