tr[23865] = {H:"Фонтан-Одуван"};
tr[23866] = {H:"Водяной шар"};
tr[23867] = {H:"Фонтан " + "\"" + "Светик" + "\"" + ""};
tr[23868] = {H:"Фонтан-Фейерверк"};
tr[23869] = {H:"Стенка " + "\"" + "Альпинист" + "\"" + ""};
tr[23870] = {H:"Велостоянка"};
tr[23871] = {H:"Батут"};
tr[23872] = {H:"Волейбольная сетка"};
tr[23873] = {H:"ТехноКачели"};
tr[23874] = {H:"Ты уже купил мебель для клубов? Вот я бы себе все фонтаны забрал!"};
tr[23875] = {H:"Друг мой бодрствующий, как я рад, что ты не спишь!"};
tr[23876] = {H:"А кто спит?"};
tr[23877] = {H:"А я, между прочим, не прочь подремать!"};
tr[23878] = {H:"Да все спят! Вместо того, чтобы сидеть и читать книги, они предпочитают валяться на кровати и ничего не делать!"};
tr[23879] = {H:"Ой. Теперь и мне спать захотелось..."};
tr[23880] = {H:"Тогда отправляйся в Клуб Сновидений! Вот Ёжик, например, теперь только там и развлекается!"};
tr[23881] = {H:"Весёлый клуб, должно быть. А как туда попасть?"};
tr[23882] = {OId:150,H:"Тссс! Не шуми! Уютненькое местечко, правда?"};
tr[23883] = {H:"Ёжик, Дора ждёт тебя на танцы! А ты тут спишь уютненько."};
tr[23884] = {OId:150,H:"О чём это ты? Ничего я не сплю."};
tr[23885] = {H:"Спишь, спишь. И я сплю."};
tr[23886] = {OId:150,H:"Неправда! Это раньше мне всё снилось, а теперь я проснулся. И ты вот проснулся."};
tr[23887] = {H:"Я не проснулся. Я уснул. Ёжик, хватит юлить. Иди потанцуй с Дорой."};
tr[23888] = {OId:150,H:"Неа! Посмотри, как здесь прекрасно. Ничего не тревожит, ничего не пугает, и вообще никого нет! Никуда я не пойду."};
tr[23889] = {H:"Ничего не пугает, говоришь? А это идея! Теперь я знаю, что делать..."};
tr[23890] = {OId:150,H:"Ёлки-иголки, ну и дела!"};
tr[23891] = {H:"Крош, что ты здесь делаешь?"};
tr[23892] = {OId:150,H:"Я? Во сне Ёжика? Шутишь?! Да я здесь самый частый гость!"};
tr[23893] = {H:"Раз так, не подскажешь, почему Ёжик никак не просыпается?"};
tr[23894] = {OId:150,H:"Ха! Вижу-вижу! Это ты все эти кошмары сюда затащил? А ведь нельзя так с Ёжиком!"};
tr[23895] = {H:"Ой... А как можно?"};
tr[23896] = {OId:150,H:"Как-как? Это ж Ёжик! Его не пугать, а радовать надо! Он от счастливых снов легче всего просыпается!"};
tr[23897] = {H:"Ох... А как мы устроим ему счастливый сон?"};
tr[23898] = {OId:150,H:"Я знаю! Только без твоей помощи ничего не получится!"};
tr[23899] = {H:"Конечно! Я кошмары придумал, мне их и разгонять."};
tr[23900] = {H:"Я придумал сон Ёжику!"};
tr[23901] = {H:"И спас его от ночных кошмаров! Скорее в Шарарам - здесь много интересного!"};
tr[23902] = {H:"Футболка " + "\"" + "Шарарам" + "\"" + ""};
tr[23903] = {H:"Желание исполнено!"};
tr[23904] = {H:"Клуб Сновидений"};
tr[23905] = {OId:270,H:"Все твои желания исполняются! Нравится?"};
tr[23906] = {H:"Все? Да я только начал. Трёхмерный Шарарам, шестирукая Нюша, шляпы для ног - у меня ворох идей!"};
tr[23907] = {H:"Да. Нравится."};
tr[23908] = {OId:270,H:"Здорово! Только теперь у тебя осталось последнее желание."};
tr[23909] = {H:"Последнее? Уже? А я только разошёлся..."};
tr[23910] = {OId:270,H:"Подумай, на что хочешь его потратить?"};
tr[23911] = {H:"Хм... Последнее, значит. Тут надо что-нибудь хитрое пожелать!"};
tr[23912] = {H:"Хочу стакан воды."};
tr[23913] = {OId:270,H:"Смело! Но как-то не серьёзно. Подумай ещё."};
tr[23914] = {H:"Лады..."};
tr[23915] = {OId:270,H:"Ну что? Готов?"};
tr[23916] = {H:"Ещё как! Желаю, чтобы с этой минуты все желания всех Смешариков всегда сбывались!"};
tr[23917] = {OId:270,H:"Быть тому..."};
tr[23918] = {H:"Ой. А ты чего так погрустнел сразу?"};
tr[23919] = {H:"Мантия Морфея"};
tr[23920] = {H:"Новогодние кроссовки"};
tr[23921] = {H:"Костюм Морфея"};
tr[23922] = {H:"Клуб Сновидений!"};
tr[23923] = {H:"Клуб Сновидений с приключениями!"};
tr[23924] = {H:"Узнай, что снится Ёжику!|Сочиняй для него новые сны и получай подарки!|Бонус: фасад для клуба"};
tr[23925] = {H:"Агент! Желания Смешариков исполняются и вредят Шарараму. Срочно придумай, как справиться с этой напастью."};
tr[23926] = {OId:270,H:"Так-с... Сюда наклеечка, и здесь не забыть. Эй, не отвлекай меня! И так завал на работе!"};
tr[23927] = {H:"Ой, а ты кто?"};
tr[23928] = {OId:270,H:"Джин-Джим. Повелитель духов желаний. Думаешь, кто все твои капризы исполняет? Я! Ахахах!"};
tr[23929] = {H:"Ну не такие уж это и капризы."};
tr[23930] = {OId:270,H:"Капризы, капризы! Ты глянь вокруг. Теперь все желания должны сбываться. Я еле успеваю."};
tr[23931] = {H:"Зато Смешарики наконец-то будут счастливы!"};
tr[23932] = {OId:270,H:"Не будут! Ахахах! Знал бы ты желания Злобикуса! Ой, там такое... А что в голове у Ёжика - это вообще кошмар!"};
tr[23933] = {H:"И как же быть?"};
tr[23934] = {OId:270,H:"Да никак. Все мечты будут исполнены. Так что не долго вот так Шарарам выстоит."};
tr[23935] = {H:"А куда ж он денется?"};
tr[23936] = {OId:270,H:"Да рухнет здесь всё. Одни желания будут мешать другим, вот и не выдержит Шарарам, развалится."};
tr[23937] = {H:"Так может ты просто перестанешь их выполнять? По-моему, гениально."};
tr[23938] = {OId:270,H:"Ну уж нет! Желания для меня - закон. А ты, главное, держись. Всего доброго тебе, хорошего настроения!"};
tr[23939] = {H:"Ну уж нет!"};
tr[23940] = {OId:150,H:"Сколько работы: слёзы из киселя, говорящие носы, робот-бабушка..."};
tr[23941] = {OId:150,H:"Вот и ответ! Желания Смешариков приходят Джин-Джиму СМСками на телефон."};
tr[23942] = {H:"А чего не телеграммами?"};
tr[23943] = {H:"А... То-то он вечно в этот телефон пялится."};
tr[23944] = {OId:150,H:"Вот бы как-нибудь удалить из телефона все СМС. Что думаешь?"};
tr[23945] = {H:"Надо запустить в его телефон вирус. Он удалит все сообщения."};
tr[23946] = {H:"Надо отобрать у Джина телефон и удалить всё самим."};
tr[23947] = {OId:150,H:"Мы можем запустить вирус через сотовые антенны. Это долго, но безопасно."};
tr[23948] = {H:"Так и поступим!"};
tr[23949] = {H:"Нет, давай ещё подумаем."};
tr[23950] = {OId:150,H:"Можно отвлечь внимание Джин-Джима, чтобы удалить СМСки вручную. Это сложно, зато быстро."};
tr[23951] = {OId:150,H:"Хорошо. Найди в Шарараме все флешки с вирусом и подключи их к сотовым антеннам."};
tr[23952] = {H:"Пойду искать!"};
tr[23953] = {OId:150,H:"Что ж, идём к Джин-Джиму на Площадь у Больнички."};
tr[23954] = {H:"Бегу!"};
tr[23955] = {OId:150,H:"Ух ты! Приветики!"};
tr[23956] = {H:"Нюша, нам надо серьёзно поговорить!"};
tr[23957] = {H:"Привки! Клёво выглядишь!"};
tr[23958] = {OId:150,H:"Ещё как!"};
tr[23959] = {H:"Мне кажется, ты стала слишком часто попадать в неприятности."};
tr[23960] = {H:"Мне кажется, с тобой никогда не бывает скучно!"};
tr[23961] = {OId:150,H:"Серьёзно? Никогда об этом не задумывалась..."};
tr[23962] = {H:"Ты застревала в Виртуальной реальности, объедалась диких ягод и теперь вот в Космосе потерялась!"};
tr[23963] = {OId:150,H:"И вправду! Столько всего... И что же мне делать?"};
tr[23964] = {OId:150,H:"Запрись у себя в домике и никуда не ходи."};
tr[23965] = {OId:150,H:"Не смотри ты по сторонам, оставайся такой, как есть. Оставайся сама собой."};
tr[23966] = {H:"Шуруп|Шуруп привезут через {0} мин."};
tr[23967] = {H:"Я помог Нюше!"};
tr[23968] = {H:"Мне удалось спасти её из открытого космоса! В Шарараме и не такое бывает - скорее в игру!"};
tr[23969] = {H:"Орден Мечты|За исполнение всех желаний!"};
