tr[23974] = {H:"Это было круто!"};
tr[23975] = {H:"Я отпраздновал день рождения Шарарама и получил подарки! Заходи в игру."};
tr[23976] = {H:"Аксессуар " + "\"" + "Воздушные шарики" + "\"" + ""};
tr[23978] = {H:"Совунья в тренде"};
tr[23979] = {H:"Как стать модной?"};
tr[23980] = {H:"В моде вкусняшки!"};
tr[23981] = {H:"В моде позитив!"};
tr[23982] = {H:"В моде спорт!"};
tr[23983] = {H:"Совунья и красота"};
tr[23984] = {H:"Хо-хо! У меня деликатный вопрос: не подскажешь, как стать модной?"};
tr[23985] = {H:"Я слыхала, что сейчас в моде здоровая кухня."};
tr[23986] = {H:"Нюша как-то говорила, что секрет красоты - в хорошем настроении!"};
tr[23987] = {H:"Чтобы стать красивой, нужно привести себя в форму. Поможешь мне?"};
tr[23988] = {H:"День Рождения"};
tr[23989] = {H:"Я готова примерить модные наряды."};
tr[23990] = {H:"Отличное начало! Вот твои Смешинки за помощь."};
tr[23991] = {H:"Здоровая пища - это классно! Спасибо тебе!"};
tr[23992] = {H:"У меня теперь целый вагон хорошего настроения. Спасибо!"};
tr[23993] = {H:"Ты видел? Все на меня смотрят! Значит, я становлюсь модной!"};
tr[23994] = {H:"Ура! Теперь я модница. А вот и твой подарок за помощь!"};
tr[23995] = {H:"Интересно, что сейчас в моде? Сходи в {0} клубов и посмотри."};
tr[23996] = {H:"Спросим у друзей. Напиши в общий чат: " + "\"" + "Что в моде у Смешариков?" + "\"" + ""};
tr[23997] = {H:"Нужно запастись позитивом. Собери {0} Позитивных энергии в Шарараме."};
tr[23998] = {H:"Отправляйся в Дремучий лес."};
tr[23999] = {H:"Сходи за ягодами - заработай {0} Смешинок в игре Дары леса."};
