tr[24037] = {OId:147,H:"Приходи на мои уроки в Шарараме, чтобы научиться проводить спасательные операции!"};
tr[24038] = {OId:150,H:"Ёлки-иголки! Поразвелось крабов в наших морях! Толком отдохнуть не дадут. "};
tr[24039] = {H:"Крош, как ты? Что с тобой? Зачем тебя похитил краб? "};
tr[24040] = {OId:150,H:"Дай-ка вспомню. Я сбежал с уроков, прыгал, купался, снова купался, потом ещё прыгал, загорал... А потом, раз, и выскочит этот... Как там его?"};
tr[24041] = {H:"Погоди-ка, погоди-ка? " + "\"" + "Сбежал с уроков" + "\"" + ", - говоришь?"};
tr[24042] = {OId:150,H:"Ну да! Есть у меня один приёмчик - вызываю смерч ушами! Хочешь научу? "};
tr[24043] = {H:"Крош, во-первых, я в шоке, что ты сбежал с уроков. Во-вторых, меня и так в школе классным вещам научили!"};
tr[24044] = {OId:150,H:"Ой, не смеши. Ведёшь себя как заумный Ёжик. И чему ты там научился-то?"};
tr[24045] = {H:"Я приручил Великого Гогуна!"};
tr[24046] = {H:"Я умею видеть невидимое!"};
tr[24047] = {H:"Я знаю слабые места страшных монстров!"};
tr[24048] = {OId:150,H:"Пффф. Не так уже это и впечатляет. Всё равно не буду учиться, и в школу не вернусь."};
tr[24049] = {H:"Ну и ладно. Посмотрим, кто из нас вырастет в крутого мага!"};
tr[24050] = {H:"Я спас Кроша!"};
tr[24051] = {H:"И научился крутым приёмчикам в Школе Магов в Шарараме! Приходи на занятия и ты!"};
tr[24052] = {H:"Ищи на складе в своём клубе."};
