tr[24117] = {H:"Целый корабль игрушек!"};
tr[24118] = {H:"Я выиграл у капитана кучу призов! Приходи в Шарарам - там и для тебя подарочек найдётся!"};
tr[24119] = {H:"Ловим морское чудище!"};
tr[24120] = {H:"" + "\"" + "Знакомимся" + "\"" + " с чудищем"};
tr[24121] = {H:"Наберись сил для борьбы!"};
tr[24122] = {H:"В Египет за советом!"};
tr[24123] = {H:"Амулет нам поможет!"};
tr[24124] = {H:"Ловим чудище!"};
tr[24125] = {H:"Кажется, в море завелось огромное чудище... Оно качает лодки и крушит целые корабли! Помоги его усмирить!"};
tr[24126] = {H:"Придумал! Может, Позитивная энергия отпугнёт чудище?"};
tr[24127] = {H:"Морское чудище должно бояться засухи..."};
tr[24128] = {H:"Перед тем, как поймать чудище, соорудим амулет!"};
tr[24129] = {H:"Мы отлично подготовились! Думаю, самое время справиться с чудищем!"};
tr[24130] = {H:"Эх, чудище улизнуло! Но ничего - мы его скоро поймаем! Держи Смешинки."};
tr[24131] = {H:"Ты полон сил для борьбы с чудищем! Вот тебе Смешинки."};
tr[24132] = {H:"Богини дали нам подсказки! Успех близок. Лови Смешинки!"};
tr[24133] = {H:"Амулет готов! Мы вот-вот поймаем чудище! Держи Смешинки."};
tr[24134] = {H:"Ничего себе - лодки качал несмышлёный китёнок! Он больше не будет. Держи подарок - Фонтан в домик."};
tr[24135] = {H:"Приходи в Порт, попробуем рассмотреть чудище!"};
