tr[24146] = {H:"Нырни под воду в Порту!"};
tr[24147] = {H:"Подкарауль чудище. Поиграй в " + "\"" + "Батискаф" + "\"" + " под водой в Порту."};
tr[24148] = {H:"Перья|Перья появятся через {0} мин."};
tr[24149] = {H:"Взять перья"};
tr[24150] = {H:"Я – суперМозг!"};
tr[24151] = {H:"Я победил Тёмного духа и получил подарок. Приходи и ты в Шарарам."};
tr[24152] = {H:"Тебе не победить меня в битве! Я вижу прошлое предков лучше всех!"};
tr[24153] = {H:"Побеждайте, конечно, конечно, да. С такими, как вы, лучше не спорить."};
tr[24154] = {H:"Тхэ, да я тоже вижу прошлое предков! Это проще простого!"};
tr[24155] = {H:"Я - лучший экстрасенс! Мой горшочек умеет варить зелье правды."};
tr[24156] = {H:"Ну и ладно! А мой горшочек умеет варить мм... золото! Разве это не круче?"};
tr[24157] = {H:"А дадите попробовать? Я хоть раз в жизни правду скажу..."};
tr[24158] = {H:"Эммм... ну, если это правда... Круто, наверное. А не врёшь? Ну-ка, покажи горшочек?!!"};
tr[24159] = {H:"Ой.. я сейчас – за ним сбегаю и вернусь – честно-честно! Можете даже не проверять."};
tr[24160] = {H:"Вижу будущее!!! Отойди, загораживаешь..."};
tr[24161] = {H:"Думаешь, ты тут самый крутой? Тогда моё будущее угадай."};
tr[24162] = {H:"Ох, не знаю, приятель. У меня будущего нет..."};
tr[24163] = {H:"Легко! Но мне нужны мои волшебные карты..."};
tr[24164] = {H:"Посмотрим, кто станет победителем шоу Экстрасенсов! Дай-ка, я вытяну карту!"};
tr[24165] = {H:"Я волшебник хоть куда! Я всё насквозь вижу..."};
tr[24166] = {H:"Ага, ну и что я ел сегодня на обед? Разглядишь?"};
tr[24167] = {H:"Ой... Тогда вы меня извините, – я спрячусь воо-он за тем кустиком..."};
tr[24168] = {H:"Хм... странно... Не могу разглядеть. Гамбургер?"};
tr[24169] = {H:"А вот и нет. Я съел Тролля)) Как ты примерно, но чуть побольше..."};
tr[24170] = {H:"А вот и нет. Плоховато у тебя со зрением."};
tr[24171] = {H:"А то! Мне, как-никак, уже 50... тыщщ лет."};
tr[24172] = {H:"Спорим, у меня зрение лучше? Сейчас всех птиц пересчитаю - даже если их не видно."};
tr[24173] = {H:"Круче меня экстрасенса нет! Я вызываю духов..."};
tr[24174] = {H:"Ага, ну и где же они? – Что-то я их не вижу!"};
tr[24175] = {H:"Ну... они отпросились... Автобус сломался и... Не приставай, короче!.."};
tr[24176] = {H:"Вот-вот! А я-то на самом деле умею. Сейчас как нашлю на тебя духа бога Ра!"};
tr[24177] = {OId:287,H:"Эээ.. мы тут духа вызвали... Хотели Максу отомстить..."};
tr[24178] = {OId:288,H:"Даа, молодцы! Я как раз из тёмного царства не мог выбраться! "};
tr[24179] = {H:"И как тебе – нравится у нас в Шарараме?"};
tr[24180] = {H:"О, нееет! Тёмный дух! Вы как хотите, а я побежал..."};
tr[24181] = {OId:288,H:"Очень! Пожалуй, заберу всю страну себе. Будете моими слугами."};
tr[24182] = {OId:289,H:"Чтобы его победить, нужен очень сильный экстрасенс!"};
tr[24183] = {OId:290,H:"Мы кое-как вызвали его, и силы все потратили..."};
tr[24184] = {OId:291,H:"Мы его отвлечём, а ты беги! Спроси Дедулю, что делать?"};
tr[24185] = {H:"Держитесь, я к Доку! "};
tr[24186] = {H:"Овощной кубок|Чемпиону по сбору урожая!"};
tr[24187] = {H:"Дачный диван в домик"};
tr[24188] = {H:"Кепка Копатыча"};
tr[24189] = {H:"Рубаха баклажан"};
tr[24190] = {H:"Гитара-лопата"};
tr[24191] = {H:"Наряд " + "\"" + "МегаДачник" + "\"" + ""};
tr[24192] = {H:"Я чемпион!"};
tr[24193] = {H:" Я помог Копатычу собрать урожай и получил крутые подарки! Приходи и ты играть в Шарарам."};
tr[24194] = {H:"Скейт"};
tr[24195] = {H:"Наряд " + "\"" + "Скейтер" + "\"" + ""};
tr[24196] = {H:"Причёcка " + "\"" + "Скейтер" + "\"" + ""};
tr[24197] = {H:"Наряд " + "\"" + "Скейтер" + "\"" + ""};
tr[24199] = {OId:288,H:"Заберу всю страну к себе в Тёмное царство. Будете моими слугами. Ахахаха!"};
tr[24200] = {H:"Создадим искусственный разум и победим Тёмного духа. Найди в Шарараме пульт и шапочку для подключения к СуперМозгу."};
tr[24201] = {H:"О, а я тут искусственный разум создаю! Хочешь помочь?"};
tr[24202] = {H:"А Тёмного духа мы с ним победим? А то, если нет, –  скоро Шарараму конец..."};
tr[24203] = {H:"Конечно! Будем управлять им силой мысли! Но сначала найди в Шарараме пульт и шапочку для подключения к Супермозгу."};
tr[24204] = {H:"ОК!"};
tr[24205] = {H:"Шапочка " + "\"" + "СуперМозг" + "\"" + ""};
tr[24206] = {H:"Сапоги " + "\"" + "Астра" + "\"" + ""};
tr[24207] = {H:"Куртка " + "\"" + "Астра" + "\"" + ""};
tr[24208] = {H:"Очки " + "\"" + "Астра" + "\"" + ""};
tr[24209] = {H:"Костюм " + "\"" + "Астра" + "\"" + ""};
tr[24210] = {H:"Магия " + "\"" + "Тёмный дух" + "\"" + ""};
tr[24211] = {H:"Магия " + "\"" + "Тёмный дух" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Тёмного духа ещё дней: {0}|Ты можешь превращаться в Тёмного духа всегда!"};
tr[24212] = {H:"Дом Экстрасенса"};
tr[24213] = {H:"Хочу! Ничего личного - уж больно ты вкусно смотришься!"};
tr[24214] = {H:"Нет, конечно! Хотя не отказался бы от чего-нибудь вкусненького."};
tr[24215] = {H:"Я всё-таки твой друг, хоть и шоколадный. А друзей есть нельзя!"};
tr[24216] = {H:"И где же мне тогда чем-нибудь полакомиться?"};
tr[24217] = {H:"Забегай в клуб-пиццерию Мистера Зюзи! Там целые горы вкусняшек!"};
tr[24218] = {H:"Заманчивый клуб! А как туда попасть?"};
tr[24219] = {OId:292,H:"Я требую объяснений!"};
tr[24220] = {OId:293,H:"Тише, вы тише! Ну подумаешь, печку взорвал..."};
tr[24221] = {H:"Так это ты, Агент 003? Какое разочарование..."};
tr[24222] = {OId:293,H:"Да, я виноват. Но у меня были причины..."};
tr[24223] = {H:"Ты ловил опасного преступника?"};
tr[24224] = {H:"Ты искал важные улики?"};
tr[24225] = {OId:293,H:"Нет, я не смог устоять перед запахом вашей пиццы!"};
tr[24226] = {H:"А вот с этого момента поподробнее, пожалуйста."};
tr[24227] = {OId:293,H:"Я так сильно захотел её съесть, что использовал дымовую шашку."};
tr[24228] = {OId:292,H:"Ещё бы! Моя пицца - лучшая в Шарараме!"};
tr[24229] = {H:"Хитро! Дым отвлёк нас, а ты спрятался в шкафу..."};
tr[24230] = {OId:292,H:"Какой тонкий ум!"};
tr[24231] = {OId:293,H:"Точно! И пока вы приходили в себя, я слопал пиццу. Ням!"};
tr[24232] = {H:"А ПОДЕЛИТЬСЯ?!"};
tr[24233] = {OId:293,H:"Да, я был неправ. Но чтобы вы не расстраивались, я приготовил нечто особенное!"};
tr[24234] = {OId:292,H:"Любопытно!"};
tr[24235] = {H:"И что же это?"};
tr[24236] = {H:"Я лучший повар Шарарама!"};
tr[24237] = {H:"И уже умею готовить вкуснейшую пиццу! А ты? Скорее в игру!"};
tr[24238] = {H:"Ммм... Ты так на меня смотришь, будто хочешь съесть!"};
tr[24239] = {H:"Вкусный клуб!"};
tr[24240] = {H:"Голубоглазый щенок"};
tr[24241] = {H:"Магия " + "\"" + "Пицца!" + "\"" + ""};
tr[24242] = {H:"Магия " + "\"" + "Пицца!" + "\"" + "|Испеки пиццу во Вкусном клубе, чтобы получить эту способность!|Ты можешь лакомиться пиццей ещё дней: {0}|Ты можешь лакомиться пиццей всегда"};
tr[24243] = {H:"Вкусный клуб!"};
tr[24244] = {H:"Стритфуд-Клаб с приключениями!"};
tr[24246] = {H:"Смайлы " + "\"" + "Гости из космоса" + "\"" + ""};
tr[24247] = {H:"Фон " + "\"" + "Я на Мюре" + "\"" + ""};
tr[24248] = {H:"О твоих приключениях на Мюре узнают все!|Ищи в гардеробе в разделе " + "\"" + "Фоны" + "\"" + "."};
tr[24249] = {H:" Лето, не уходи!"};
tr[24250] = {H:"Спасибо! Ты уже починил паром и получил подарок. Скоро мы отправимся домой!"};
tr[24251] = {H:"Сегодня ты уже пытался починить паром. Хочешь попробовать снова за 5 Румбиков?"};
tr[24252] = {H:"попробовать за 5 Румбиков"};
tr[24253] = {H:"Волшебный напиток"};
tr[24254] = {H:"Прадед завещал мне рецепт волшебного напитка - кто его выпьет - весь год счастлив будет! Поможешь приготовить?"};
tr[24255] = {H:"Я оставил рецепт на Пляже. Приходи туда."};
tr[24256] = {H:"Узнаем побольше о том, как готовить напитки! Поработай в Кафе на Пляже."};
tr[24257] = {H:"Думаю, у нас с тобой получится отличный напиток! А для начала - лови Смешинки"};
tr[24258] = {H:"Волшебный напиток"};
tr[24259] = {H:"Так, что там пишут в рецепте?.. " + "\"" + "Волшебный напиток должен быть ...вкусным!" + "\"" + ""};
tr[24260] = {H:"Главный ингредиент напитка - груши. Собери {0} в Ромашковой долине."};
tr[24261] = {H:"Выжмем сок из груш! Заработай {0} Смешинок в игре Вечный двигатель в Ромашковой долине!"};
tr[24262] = {H:"Добавим к грушам ягод! Заработай {0} Смешинок в игре с Копатычем в Лесу."};
tr[24263] = {H:"Здорово, мы уже столько успели! Держи Смешинки за помощь."};
tr[24264] = {H:"Волшебный напиток"};
tr[24265] = {H:"Наш напиток будет особенным! Сравним его с другими."};
tr[24266] = {H:"В клубах полно напитков. Зайди в {0} клубов."};
tr[24267] = {H:"Спроси у Смешариков в чате: " + "\"" + "Какой напиток вкуснее?" + "\"" + ""};
tr[24268] = {H:"Отведай вкусненького! Найди в меню одного из клубов Колу и купи её."};
tr[24269] = {H:"Вкусно было? Мы сделаем ещё вкуснее! А пока - лови-ка Смешинки."};
tr[24270] = {H:"Волшебный напиток"};
tr[24271] = {H:"Чего-то не хватает... Какой же напиток - и без воды! Возьмём самую чистую воду!"};
tr[24272] = {H:"Приходи в Порт - там много воды!"};
tr[24273] = {H:"Наберём воды, где поглубже! Прокатись на катере в Порту и заработай {0} Смешинок."};
tr[24274] = {H:"Отлично - напиток почти готов! Смешинки - твои."};
tr[24275] = {H:"Волшебный напиток"};
tr[24276] = {H:"Самое время добавить магии в наш напиток! Сейчас-сейчааас...."};
tr[24277] = {H:"Нам помогут друзья. Напиши {0} сообщений на Шарафоны: " + "\"" + "Как сделать напиток волшебным?" + "\"" + ""};
tr[24278] = {H:"Собери {0} эликсира в Школе магов, добавим их в наш напиток."};
tr[24279] = {H:"Позитивная энергия сделает напиток ещё чудеснее! Собери {0} в Шарараме!"};
tr[24280] = {H:"У нас получился самый вкусный волшебный напиток! Держи его себе в домик!"};
tr[24281] = {H:"Начинаем волшебство..."};
tr[24282] = {H:"Волшебство - это вкусно!"};
tr[24283] = {H:"За секретами - в клуб!"};
tr[24284] = {H:"Что главное в напитке?"};
tr[24285] = {H:"Время волшебства!"};
tr[24286] = {H:"Дракон"};
tr[24287] = {H:"МультФон с Драконом"};
tr[24288] = {H:"Медаль " + "\"" + "Рыцарь Драконов" + "\"" + "|За спасение Нюши!"};
tr[24289] = {H:"Паром для вечеринок"};
tr[24290] = {H:"У меня смелость Капитана Зюзеля!"};
tr[24291] = {H:"У меня чувство юмора Боцмана Бряка!"};
tr[24292] = {H:"У меня очарование Радистки Зет!"};
tr[24293] = {H:"Я загадочен как Штурман Штормик!"};
tr[24294] = {H:"А на кого из Зябрийцев похож ты? Приходи в Шарарам и узнаешь!"};
tr[24295] = {H:"Во всей вселенной я ни на кого не похож!"};
tr[24296] = {H:"А как насчёт тебя? Приходи в Шарарам и узнаешь!"};
tr[24297] = {H:"Шурупы|Шурупы привезут через {0} мин."};
tr[24298] = {H:"Я снял фильм про Смешариков в космосе. Заходи в Шарарам и стань звездой!"};
tr[24299] = {H:"А ещё снял фильм про Иных, и получил подарок. Приходи и ты в Шарарам."};
tr[24300] = {H:"Йоу! Рассказать тебе о клубах?"};
tr[24301] = {H:"Найди в Шарараме защитный костюм и лазер, чтобы обезвредить тарелку."};
tr[24302] = {H:"С премьерой! Мы сняли отличный фильм про Иных!"};
tr[24303] = {H:"Да, им самим бы, наверное, понравилось!"};
tr[24304] = {H:"Да ну, что ты – Иных не существует. Я сам их выдумал!"};
tr[24305] = {H:"Да? А это кто тогда?"};
tr[24306] = {H:"ЧТО ВЫ НАДЕЛАЛИ!!! Как мы злыыы... Мы специально мешали вам снимать фильм о нас!"};
tr[24307] = {H:"О-ёёй, нас всех съедят, а потом поймают!.. (ой, наоборот...) Бежим, короче!"};
tr[24308] = {H:"А что такого? Ну, сняли кино... Мы вообще не знали, что вы есть..."};
tr[24309] = {H:"Теперь, когда фильм вышел, нас найдёт злой инопланетянин, который гоняется за нами по галактикам уже 1000 лет!"};
tr[24310] = {H:"Ой, а это не он там – в страшной летающей тарелке?"};
tr[24311] = {H:"Ну, всё!.. Он нас засёк! Теперь он не только нас, но и всю Землю уничтожит!"};
tr[24312] = {H:"Так, без паники. Я его задержу! Только найду в Шарараме защитный костюм и лазер!"};
tr[24313] = {OId:297,H:"Ребята, вы с лазерами-то поосторожнее: костюм у меня дорогой – бабушка сама шила!"};
tr[24314] = {H:"Базу?!! Так это ты за Иными гонялся?"};
tr[24315] = {OId:297,H:"Кхе-кхе, ну да! Да чего они боятся? – Я кошелёк хотел отдать – вот, вы на Млечном пути обронили..."};
tr[24316] = {OId:298,H:"Э-э.. спасибо... Неудобно получилось..."};
tr[24317] = {OId:299,H:"А мы вас так боялись... Чуть не.. ну, не будем вспоминать..."};
tr[24318] = {H:"Так ты никого не уничтожишь? Ой, как я рад, что разобрались!"};
tr[24319] = {H:"Ну, ура! Теперь и фильм всем вместе посмотреть можно..."};
tr[24320] = {H:"Смайлы " + "\"" + "Иной" + "\"" + ""};
tr[24321] = {H:"Защитный  Костюм "};
tr[24322] = {H:"Защитные КосмоБоты"};
tr[24323] = {H:"Аксессуар " + "\"" + "Лазер" + "\"" + ""};
tr[24324] = {H:"Взять шурупы"};
tr[24325] = {OId:294,H:"Хм... Если мой глаз меня не обманывает, я внезапно оказался в Шарараме."};
tr[24326] = {OId:295,H:"Бряк, это я тебя вызвал. У нас важное дело."};
tr[24327] = {H:"Привет, Бряк! Не замечаешь ничего странного?"};
tr[24328] = {OId:294,H:"Для зябрийцев в Шарараме всё странное. Кроме этого леса. Здесь ничего так."};
tr[24329] = {OId:295,H:"Значит я был прав!"};
tr[24330] = {H:"А почему этот лес не странный?"};
tr[24331] = {OId:294,H:"Как же? Вот кливкие форьки резвятся, вот модеры в шове. Всё как дома!"};
tr[24332] = {OId:295,H:"Какие ж это модеры? Это аномалии!"};
tr[24333] = {H:"Так значит, это из-за зябрийцев наш лес так переменился?"};
tr[24334] = {OId:294,H:"Ой, и вправду! В прошлый раз мы устроили здесь пикник, а забрать муфляк забыли. Вот лес и стал похож на Зябру."};
tr[24335] = {OId:295,H:"Ну и ну!"};
tr[24336] = {H:"Что за муфляк?"};
tr[24337] = {OId:294,H:"Ой, долго объяснять. Я просто заберу его обратно на Зябру, и всё вернётся на свои места."};
tr[24338] = {OId:295,H:"Да-да! Мусорить на пикнике - нехорошо. Даже, если ты пришелец!"};
tr[24339] = {H:"Спасибо, Бряк!"};
tr[24340] = {H:"Танцуй, пой, вой на Луну! Управляй магией кнопками " + "\"" + "танец" + "\"" + ", " + "\"" + "сидеть" + "\"" + " и " + "\"" + "махать" + "\"" + "."};
tr[24341] = {H:"Садись в вертолёт и прыгай с парашютом в любую точку Шарарама!"};
tr[24342] = {H:"Покажи Смешарикам фокус с кроликом и шляпой!"};
tr[24343] = {H:"Познай чудеса алхимии - пей зелье и превращайся каждый раз в разных Злобырей!"};
tr[24344] = {H:"Познай тёмную сторону Босса Ба-босса!"};
