tr[24600] = {OId:302,H:"Ребята, вы – самая крутая команда! Мы отправляемся на МегаСложное задание!"};
tr[24601] = {OId:303,H:"Уряяя!"};
tr[24602] = {H:"Да, ураа!! А куда?"};
tr[24603] = {H:"Нуу, это без меня.  Я, устал, – я ухожу... Панимаэшь..."};
tr[24604] = {OId:302,H:"Мы летим – в космос! На планету ДжунглЯ! "};
tr[24605] = {OId:304,H:"Джунгля – это ж почти как Земля! Тра-ля-ля.. О, я рэп придумал!"};
tr[24606] = {OId:305,H:"Оой, там Джунгли? А палатки дадут?.. А платьев сколько брааать?"};
tr[24607] = {H:"...Знаете, у них там галактика не самая красивая. Не поеду-ка я... Удач!"};
tr[24608] = {H:"Отлично! Едем!.. Точнее – летим! Все на Космодром!"};
tr[24609] = {OId:302,H:"Скорее лети на Планету Джунгля с Космодрома!"};
tr[24610] = {H:"Котошапка"};
tr[24611] = {H:"Теневая СмеШутка|Получи эту способность у лемура в Каньоне|Ты можешь пугать Смешариков ещё дней: {0}|Ты можешь пугать Смешариков всегда"};
tr[24612] = {H:"Красный в моде!"};
tr[24613] = {H:"Очки " + "\"" + "Будь в красном!" + "\"" + ""};
tr[24614] = {H:"Ботинки " + "\"" + "Будь в красном!" + "\"" + ""};
tr[24615] = {H:"Костюм " + "\"" + "Будь в красном!" + "\"" + ""};
tr[24616] = {H:"Красная причёска"};
tr[24617] = {OId:306,H:"Фух... Устали! Пора отдохнуть у костра..."};
tr[24618] = {OId:307,H:"Давайте споёмся!"};
tr[24619] = {OId:308,H:"Сиреночка, спой, не стыдись..."};
tr[24620] = {H:"Ага, и я даже подпою вам!"};
tr[24621] = {OId:308,H:"Глядить-ка – к нам кто-то из зарослей идёт..."};
tr[24622] = {OId:306,H:"Йоу, песня начинается!...\nОй, кто-то приближается...."};
tr[24623] = {H:"Да где?!!"};
tr[24624] = {H:"Слушатели, это ж хорошо! Поём, не останавливаемся!.."};
tr[24625] = {H:"О-ёй! Бежим, летим, прячемся!!"};
tr[24626] = {OId:309,H:"Ой, какие хорошенькие, кругленькие! Сейчас мы вас съе... Хотяя... Вы откуда прилетели?"};
tr[24627] = {OId:307,H:"Сьпасибяо... Ми из Шарарамя!"};
tr[24628] = {OId:308,H:"Да, мы хорошенькие! Особенно я и Сирена..."};
tr[24629] = {H:"Предупреждаю, в Шарараме таких миллионы! Обидите нас – они отомстят!"};
tr[24630] = {OId:309,H:"Ооо, миллионы! Наверное, все вкусные! Мы как раз проголодались... Мы – в Шарарам!"};
tr[24631] = {H:"Эй-эй, вы пожалеете! ...Куда же вы?.."};
tr[24632] = {OId:306,H:"Скорее в Шарарам! Найдём Джунглян и спасём Смешариков от съедения!"};
tr[24633] = {OId:310,H:"Я капусту люблю, конечно... Но зачем меня в неё заворачивать? Не понимаю..."};
tr[24634] = {OId:311,H:"Не делайте из меня варенье! Я ещё так молод, мне всего 85!"};
tr[24635] = {OId:312,H:"...У нас на планете едят всё круглое. Оно ведь самое вкусное... Готовьтесь готовиться..."};
tr[24636] = {H:"...Я, признаться, никогда Смешариков не пробовал. С сахаром-то, может и правда вкусно..."};
tr[24637] = {H:"Тээк, Джунгляне! А ну – отставить питаться!"};
tr[24638] = {OId:312,H:"Ты в школе биологию-то проходил? Как это мы можем перестать питаться?.. Смешной..."};
tr[24639] = {H:"У нас в стране куча вкусной еды, ещё круглее, чем Смешарики! Жозе Эклер прекрасно готовит. – Я вам принесу."};
tr[24640] = {H:"Твои сердечки"};
tr[24641] = {OId:313,H:"Ладно, не будем Смешариков есть, и возьмём тефтелек в дорогу... А тебя на Пляже подарок ждёт!"};
