tr[24690] = {H:"Класс! Уже скоро я отправлю первый номер газеты в печать. А ты заслужил подарок: незаменимую вещь для любого журналиста!"};
tr[24691] = {H:"Узнаём новости!"};
tr[24692] = {H:"Рубрика: " + "\"" + "Жизнь звёзд" + "\"" + ""};
tr[24693] = {H:"Острый репортаж"};
tr[24694] = {H:"Вести с полей!"};
tr[24695] = {H:"Рекламируем газету!"};
tr[24696] = {H:"Огромный двор с мостиком и речкой, подвисная кровать, целые ящики моркови и вечный ремонт. Жить как Крош - весело!"};
tr[24697] = {H:"Двухэтажный дом с панорамными окнами, джакузи и личным пультом DJ, на котором можно играть свою музыку - так живут звёзды!"};
tr[24698] = {H:"Слабонервным не заселяться! Самый страшный замок с жутко-красивым двориком. Пригласи друзей на Злобби-пати!"};
tr[24699] = {H:"Деревянный домик с настоящей печкой и колодцем в огороде. Это так же круто, как в деревне у бабушки, ёлки-копалки!"};
tr[24700] = {H:"Ты знал, что Ёжик увлекается сёрфингом? Ничего удивительного, ведь его домик стоит на берегу океана!"};
tr[24701] = {H:"Пригласи друзей в аэропорт! Поднимаемся по трапу, проходим в самолёт, пристёгиваемся... Ты садишься за штурвал и... Небо, жди!"};
tr[24702] = {H:"Великий домик для Великого Смешарика!"};
tr[24703] = {H:"Самый мягкий домик с двориком в стиле агента Лиги героев - ЮИ."};
tr[24704] = {H:"Живи вкусно в ярком цитрусовом домике!"};
tr[24705] = {H:"Самые крутые развлечения прямо у тебя в домике! Друзья будут завидовать!"};
tr[24706] = {H:"Кликни на волшебную палочку и разыгрывай Смешариков 7 дней. "};
tr[24708] = {H:"СмеШутка " + "\"" + "Ракета" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь катать Смешариков на ракете дней: {0}|Ты можешь катать Смешариков на ракете всегда!"};
tr[24709] = {H:"Кликни на лестницу, чтобы подняться в Страну облаков и забрать сокровища!"};
tr[24710] = {H:"Круто! Ты уже нашёл сокровище Страны облаков!"};
tr[24711] = {H:"Я построил лестницу в небо!"};
tr[24712] = {H:"И нашёл сокровище в Стране облаков! Скорее в Шарарам - здесь много интересного!"};
tr[24713] = {H:"Дружище! Прекрасно выглядишь сегодня, не хочешь отправиться на фотосессию?"};
tr[24714] = {H:"Ой, нет. Я стесняюсь."};
tr[24715] = {H:"Да! А то всё селфи-селфи... Хочу профессиональных фоток!"};
tr[24716] = {H:"Не бойся, мой юный фотогерой! Скромность только украшает!"};
tr[24717] = {H:"Ну ладно. А где мне сделать фотографии?"};
tr[24718] = {H:"Отправляйся в ФотоКлуб! Все фотографы только там и тусуются!"};
tr[24719] = {H:"Здорово! А где найти этот клуб?"};
tr[24720] = {H:"Я фоткаю опасных Монстриков!"};
tr[24721] = {H:"В Шарараме и не такое бывает - скорее в игру!"};
tr[24722] = {OId:270,H:"Ты паять умеешь? Я тут микросхемы делаю!"};
tr[24723] = {H:"Ээм..., чего?.."};
tr[24724] = {H:"А твои эти микро... схемы – для дронов не подходят случайно?"};
tr[24725] = {OId:270,H:"Принеси-ка мне несколько микрочипов, и я тебе микросхему сделаю."};
tr[24726] = {H:"Будет сделано!"};
tr[24727] = {OId:270,H:"Куда – мою скакалку брать?!!"};
tr[24728] = {H:"Да я тут дрон мастерю. А скакалка вместо провода пойдёт."};
tr[24729] = {OId:270,H:"Вяяяя!!! А я во что играть тогда буду?!! Я сейчас па-апу позовуу-уу!!!"};
tr[24730] = {H:"Тихо, тихо! ...Не надо папу. Я тебе игрушку подарю."};
tr[24731] = {OId:270,H:"Ну и жараа... Ты вентилятор-то не трожь!"};
tr[24732] = {H:"Ну дяденька... Ну мне оочень нужен пропеллер. Я тут дрон для фестиваля делаю..."};
tr[24733] = {OId:270,H:"Для такого дела – моожно... Но ты тогда уж принеси мне водички взамен!"};
tr[24734] = {H:"Хорошо..."};
tr[24735] = {H:"ФотоКлуб"};
tr[24736] = {H:"ФотоКлуб"};
tr[24737] = {H:"ФотоКлуб с приключениями!"};
tr[24738] = {H:"Устрой фотосессию Монстрику и получи подарок!|Собирай гостей и устраивай яркие фото-тусовки!|Бонус: фасад для клуба"};
