tr[24741] = {H:"РобоПтица"};
tr[24742] = {H:"Магия " + "\"" + "Монстрик" + "\"" + ""};
tr[24743] = {H:"Магия " + "\"" + "Монстрик" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Монстрика ещё дней: {0}|Ты можешь превращаться в Монстрика всегда."};
tr[24744] = {H:"Модный пуловер"};
tr[24745] = {OId:270,H:"Приведи Новый год в Шарарам! Для этого найди Смешариков, которые помогут тебе!"};
tr[24746] = {H:"Новый год к нам мчится, скоро всё случится!"};
tr[24747] = {H:"В эту лупу ничего не видно. Поищи другую."};
tr[24748] = {OId:270,H:"Поговори с Совуньей и Пином в Дремучем лесу. Покажи им перо, и они подскажут, кого нужно искать!"};
tr[24749] = {OId:270,H:"Поговори с динозавром в Каньоне!"};
tr[24750] = {OId:270,H:"Друг мой новогодний, какое счастье, что ты вылупился!"};
tr[24751] = {H:"Что?! Где?! Как я сюда попал?!"};
tr[24752] = {OId:270,H:"Это науке неизвестно! Но похоже, ты - символ 2017 года! А значит, только ты можешь привести Новый год в Шарарам!"};
tr[24753] = {H:"Ой. Вот это поворот! А как мне это сделать?"};
tr[24754] = {OId:270,H:"Просто найди в Шарараме Смешариков, которые помогут тебе! А потом я вручу тебе классный костюм или домик!"};
tr[24755] = {H:"Уже бегу!"};
tr[24756] = {OId:150,H:"Ура! Как хорошо, что ты пришёл!"};
tr[24757] = {H:"ПылеСанчо, как идёт подготовка к Новому году?"};
tr[24758] = {OId:150,H:"Ох! Дед Мороз никак не может вылететь в Шарарам из-за вьюги!"};
tr[24759] = {H:"И как же нам быть?"};
tr[24760] = {H:"Славненько. Теперь никто не получит подарков..."};
tr[24761] = {OId:150,H:"Вместе с тобой мы сможем разогнать вьюгу. Поможешь?"};
tr[24762] = {H:"Ни за что на свете!"};
tr[24763] = {H:"Конечно, помогу!"};
tr[24764] = {OId:270,H:"Друг мой, всё готово к празднику! А ты готов?"};
tr[24765] = {H:"Ой, нет. У меня другие дела!"};
tr[24766] = {H:"Я готов. Начинаем праздник."};
tr[24767] = {OId:270,H:"Тогда скорее произнеси волшебное слово, которое приведёт к нам Новый год!"};
tr[24768] = {H:"Раз-два-три, Новый год, приди!"};
tr[24769] = {H:"Волшебникус-Праздникус!"};
tr[24770] = {H:"Майонез!"};
tr[24771] = {OId:270,H:"Ммм... Что-то не то! Ничего не изменилось. Попробуй снова!"};
tr[24772] = {H:"Ёлки-иголки, праздники, метёлки!"};
tr[24773] = {H:"Новый год к нам мчится, скоро всё случится..."};
tr[24774] = {H:"Мандарин!"};
tr[24775] = {OId:270,H:"Нет, так решительно не годится. Попробуй ещё!"};
tr[24776] = {H:"Ааааа...."};
tr[24777] = {H:"Ууууу...."};
tr[24778] = {H:"Совунья!"};
tr[24779] = {OId:270,H:"Ох. Ничего не выходит. Это может означать лишь одно..."};
tr[24780] = {H:"Кто-то украл Новый год?"};
tr[24781] = {OId:270,H:"Нет, конечно. Вероятно, символ Нового года не ты, а кто-то другой!"};
tr[24782] = {H:"Как не я, если я?"};
tr[24783] = {H:"Ну и ладно. А кто тогда?"};
tr[24784] = {OId:270,H:"Это нам и надо выяснить. Скорее беги в Ромашковую долину и найди улики!"};
tr[24785] = {H:"Уже бегу!"};
tr[24786] = {OId:319,H:"С Новым годом! Наступающим. Кхм, кхм, почти."};
tr[24787] = {OId:318,H:"Он наступайт, если мы узнавайт, кто символ!"};
tr[24788] = {H:"Я знаю! Взгляните на это перо!"};
tr[24789] = {OId:318,H:"О майн гот! Какой необычный перья!"};
tr[24790] = {OId:319,H:"Хо-хо! Птенчик, который его обронил не так-то прост!"};
tr[24791] = {H:"Ох, подсказали бы вы мне, где искать хозяина пера!"};
tr[24792] = {OId:318,H:"Я знайт. Мы рассказывайт, как он он выглядит, а ты рисовайт его!"};
tr[24793] = {OId:319,H:"Конечно, по рисунку будет гораздо проще его найти!"};
tr[24794] = {H:"Класс! Давайте нарисуем!"};
tr[24795] = {OId:320,H:"Ааа! Как ты нашёл меня? О, нет!"};
tr[24796] = {H:"Так-с... Мы знакомы?"};
tr[24797] = {OId:320,H:"Чуть-чуть. Это ж я тебя посадил в яйцо вместо себя!"};
tr[24798] = {H:"Вот как! Мог бы и спросить сначала для приличия!"};
tr[24799] = {OId:320,H:"Я побоялся. Понимаешь, это ж я сейчас динозавр, а раньше-то я был петух! А это совсем не круто!"};
tr[24800] = {H:"А я тут при чём?"};
tr[24801] = {OId:320,H:"А ты - классный Смешарик, вот я и решил сделать тебя символом Нового года вместо себя."};
tr[24802] = {H:"Да, но только ты можешь сказать заклинание, от которого праздник наступит!"};
tr[24803] = {OId:320,H:"Ох, и мне, что, снова надо будет стать петухом?"};
tr[24804] = {H:"Не бойся, я всем скажу, что ты умеешь превращаться в грозного динозавра!"};
tr[24805] = {H:"Так главное же, что ты по характеру крутой! Как динозавр!"};
tr[24806] = {OId:320,H:"Убедил. Только помоги мне сварить зелье, чтобы вернуться в прежний вид!"};
tr[24807] = {H:"Конечно, помогу!"};
tr[24808] = {H:"Давай, потом. Сегодня я устал."};
tr[24809] = {H:"Кликни, чтобы устроить салют!"};
tr[24810] = {H:"Ракушка|Ракушка появится через {0} мин."};
tr[24811] = {H:"Лупа"};
tr[24812] = {H:"Я привёл Новый год в Шарарам!"};
tr[24813] = {H:"В стране Смешариков наступила пора праздничных чудес! Скорее в игру!"};
tr[24814] = {OId:270,H:"Поговори с Совуньей и Пином в Дремучем лесу. Покажи им перо, и они подскажут, кого нужно искать!"};
tr[24815] = {OId:270,H:"Поговори с динозавром в Каньоне!"};
tr[24816] = {H:"Ракушка|Ракушка вырастет через {0} мин."};
tr[24817] = {OId:314,H:"О, ты нашёл меня! Выпусти меня, герой!"};
tr[24818] = {H:"Эээ.. хорошо. А как?"};
tr[24819] = {H:"Ууу, так ты – не клад... Зачем мне тогда клетку открывать..."};
tr[24820] = {OId:314,H:"Найди 6 ключей от моей клетки здесь, в лабиринте."};
