tr[24822] = {OId:317,H:"Шо смотришь? Не находил я твоего ключа..."};
tr[24823] = {H:"Ага! Проболтался! Я тебя про ключ-то и не спрашивал!"};
tr[24824] = {H:"Не находил? Ну, ладно тогда.. А то я уж было подумал..."};
tr[24825] = {OId:317,H:"Но я таки его первый нашёл!"};
tr[24826] = {H:"Да ты хоть знаешь, от чего этот ключ? Зачем он тебе, отдавай давай..."};
tr[24827] = {OId:270,H:"Вот странно. Я тут недавно ключ потерял... А сегодня нашёл. Но он к моей пещере не подходит..."};
tr[24828] = {H:"Так это может не тот ключ? Сейчас твой найдём, а ты мне этот отдай!"};
tr[24829] = {H:"Шарафон " + "\"" + "Привидение" + "\"" + ""};
tr[24830] = {H:"Хочешь сам смастерить себе мебель в домик? Кликни по конвейеру, чтобы начать!"};
tr[24831] = {H:"Аквариум"};
tr[24832] = {H:"Столик"};
tr[24833] = {H:"Диван"};
tr[24834] = {H:"Шкаф"};
tr[24835] = {OId:315,H:"Ну, как так? Я же тебя, брат, в клетку заточил, уж больно ты много зла натворил!..  "};
tr[24836] = {OId:316,H:"А вот так... Я Жар-Птицей обернулся, чтоб меня добрые люди...ой, – Смешарики – выпустили..."};
tr[24837] = {H:"Эмм,  кто бы это мог быть?.. Ума не приложу... Ай-яй-яй им..."};
tr[24838] = {H:"Ой... Но я же не знал, что это ты, Злобикус..."};
