tr[24916] = {H:"Взять лаву"};
tr[24917] = {H:"Лава|Лава появится через {0} мин."};
tr[24918] = {OId:321,H:"Ох, что-то покалывает у меня в антеннах! О, нет! Я вижу! Вижу!"};
tr[24919] = {H:"Что же ты видишь, Сэнсэй?"};
tr[24920] = {H:"Так, всё. Опять ему что-то чудится. Я пошёл."};
tr[24921] = {OId:321,H:"Преступники хотят напасть на Лигу и заморозить каждого из нас!"};
tr[24922] = {OId:322,H:"Зачем им это?"};
tr[24923] = {H:"Им просто не нравится, что Лига героев спасает мир от зла!"};
tr[24924] = {H:"Думаю, преступники просто фанаты мороженого с неожиданными начинками!"};
tr[24925] = {OId:321,H:"Боюсь, мы узнаем это только тогда, когда поймаем их!"};
tr[24926] = {OId:322,H:"Давайте устроим им ловушку!"};
tr[24927] = {H:"Классная идея! Мы их поймаем, и они всё расскажут!"};
tr[24928] = {H:"Так себе затея... Но давайте попробуем."};
tr[24929] = {OId:321,H:"Ничего не бойся! Я вижу! Идеальным местом для ловушки будет Дремучий лес!"};
tr[24930] = {OId:322,H:"Приходи туда, чтобы всё подготовить."};
tr[24931] = {H:"Отлично! Идём туда прямо сейчас!"};
tr[24932] = {H:"Хорошо! Только я туда попозже загляну."};
tr[24933] = {OId:325,H:"Ой... Кажется, с ловушкой перемудрили мы."};
tr[24934] = {OId:324,H:"Ох, в самый космос братца моего зашвырнули..."};
tr[24935] = {H:"Так. Мы поймали преступника. Всем стоять, никому не двигаться."};
tr[24936] = {OId:323,H:"Эх, а мы думали, вы, снежные люди, добряки, а не преступники!"};
tr[24937] = {OId:324,H:"Ой, ну какие ж мы преступники!"};
tr[24938] = {H:"А зачем вы статую ЮИ замораживали?"};
tr[24939] = {H:"А зачем вам записка про нападение на Лигу?"};
tr[24940] = {H:"А почему у вас весь дом фотками МедвеДуси обвешан?"};
tr[24941] = {OId:324,H:"Так это ж мы с братом спектакль придумали, а не преступление!"};
tr[24942] = {OId:323,H:"Спектакль про нападению на Лигу?"};
tr[24943] = {H:"И что это за спектакль?"};
tr[24944] = {OId:324,H:"Сюжет простой: сначала Злобикус Лигу превращает в льдину, а потом ЮИ всех спасает!"};
tr[24945] = {OId:325,H:"Мне нравится!"};
tr[24946] = {OId:323,H:"А как нам твоего брата теперь из космоса вытащить?"};
tr[24947] = {H:"Полетим туда и спасём Снежного человека!"};
tr[24948] = {H:"Подождём, пока его силой притяжения Земли не притянет."};
tr[24949] = {OId:323,H:"Тогда встречаемся на КосмоСтанции!"};
tr[24950] = {H:"Уже лечу!"};
tr[24951] = {OId:326,H:"Снежные люди, простите, что подумали про вас плохое."};
tr[24952] = {OId:327,H:"Выходит, спектакль у нас правдивый, если вы его за чистую монету приняли!"};
tr[24953] = {OId:328,H:"Хи-хи!"};
tr[24954] = {H:"А посмотреть этот спектакль можно?"};
tr[24955] = {OId:327,H:"Ой, так мы ещё даже и не репетировали."};
tr[24956] = {OId:328,H:"И сценарий у нас... Не совсем до конца... Написан. Только одна строчка есть, и всё."};
tr[24957] = {H:"А у меня на этот счёт идея!"};
