tr[25571] = {H:"Морковный свитер"};
tr[25572] = {H:"Костюм " + "\"" + "Бодрая морковка" + "\"" + ""};
tr[25573] = {H:"Нос морковкой"};
tr[25574] = {H:"Морковки"};
tr[25575] = {H:"Шарик"};
tr[25576] = {H:"Братец-кролик"};
tr[25577] = {H:"Говорящая морковка"};
tr[25578] = {H:"Кликни на антенну здесь на Космодроме, чтобы рассмотреть фотку от пришельцев!"};
tr[25579] = {H:"Найди знатоков морей в  Шарараме и узнай, где искать Акватумб!"};
tr[25580] = {H:"Найди Лосяша и поговорим с ним!"};
tr[25581] = {H:"Акватумб должен быть здесь. Осмотрись внимательнее!"};
tr[25582] = {H:"Спрутики ждут тебя на планете, откуда пришёл тревожный сигнал!"};
tr[25583] = {H:"О, да это же соль!"};
tr[25584] = {H:"Это похоже на морскую ракушку!"};
tr[25585] = {H:"Это просто камушек!"};
tr[25586] = {OId:344,H:"Попробуем запустить Акватумб? Кликни на него!"};
tr[25587] = {OId:341,H:"Итак. Мы видим пустыню, кристаллы соли, водоросли и тину."};
tr[25588] = {OId:342,H:"Лично я вижу здесь уныние и тоску."};
tr[25589] = {H:"Ясно. Здесь было море, но оно засохло!"};
tr[25590] = {H:"Ничего не понимаю."};
tr[25591] = {OId:341,H:"Вероятно, солёная морская вода высохла от жаркого солнца, но следы моря здесь всё ещё остались."};
tr[25592] = {H:"Так вот оно что!"};
tr[25593] = {OId:342,H:"Ну и жара! Подайте воды!"};
tr[25594] = {OId:341,H:"Конечно! Из-за засухи пришельцы и просили о помощи."};
tr[25595] = {H:"Где же нам теперь искать этих пришельцев?"};
tr[25596] = {OId:341,H:"Не знаю. Наверное, придётся обойти всю планету. И потратить на поиски годы."};
tr[25597] = {OId:342,H:"Ох! Ну хоть водички выпью на дорожку!"};
tr[25598] = {H:"Эй, я тоже пить хочу!"};
tr[25599] = {OId:343,H:"Стойте! Не пейте нас!"};
tr[25600] = {OId:342,H:"Вааа! Мой стакан заговорил!"};
tr[25601] = {H:"Так-с... Говорящий стакан. Ну и чего он хочет?"};
tr[25602] = {H:"Я повелитель океанов!"};
tr[25603] = {H:"И даже пустыню могу превратить в море! Заходи в Шарарам - и у тебя так получится!"};
tr[25604] = {H:"Взять водоросли"};
tr[25605] = {H:"Ушастый блог"};
tr[25606] = {H:"Привет! Я тут подумал: а почему это у меня нет своего видеоблога? Надо это срочно исправить! Давай разыграем Смешариков и снимем это на камеру!"};
tr[25607] = {H:"Отправь {0} друзьям сообщение на Шарафон: " + "\"" + "У тебя спина зелёная!" + "\"" + "."};
tr[25608] = {H:"Беги в Школу магов и устрой там снежную битву. Кинь {0} помидоров!"};
tr[25609] = {H:"Победный розыгрыш! Выиграй в ватрушки на Снежной горе."};
tr[25610] = {H:"Ой, у меня от хохота животик заболел. Интересно, а подписчикам будет так же весело?"};
tr[25611] = {H:"Ушастый блог"};
tr[25612] = {H:"Теперь я хочу снять обзор на... Румбики? Клубы? Домик Нюши? Неее... Снимем обзор на Пляж!"};
tr[25613] = {H:"Ой, что это тут валяется? Собери {0} жемчужины на Пляже."};
tr[25614] = {H:"В видео слишком мало меня. Вот и сыграй со мной в волейбол!"};
tr[25615] = {H:"Посмотрим, чем здесь кормят. Заработай {0} Смешинок в кафе на Пляже."};
tr[25616] = {H:"О! Наш обзор собирает лайки. Первый - от Ёжика! Подписчики требуют новых видео!"};
tr[25617] = {H:"Ушастый блог"};
tr[25618] = {H:"Я знаю! Все любят разные крутые штуки и гаджеты. Надо снять блог про новинки техники!"};
tr[25619] = {H:"Отправляйся в Страну Роботов."};
tr[25620] = {H:"Посмотрим, из каких деталей делают роботов. Поработай на Конвейере."};
tr[25621] = {H:"А теперь собери несколько роботов. Сыграй в игру и заработай 20 Смешинок."};
tr[25622] = {H:"Нюша написала, что блог у меня скучный! А механик Яша поставил аж 20 лайков! Ну и страсти."};
tr[25623] = {H:"Ушастый блог"};
tr[25624] = {H:"Нюша вдруг тоже стала вести свой блог. Про моду! Давай и мы снимем обзор на наряды из магазина!"};
tr[25625] = {H:"Приходи в Смешмаг."};
tr[25626] = {H:"Найди в магазине кепку " + "\"" + "Листочек" + "\"" + " и купи."};
tr[25627] = {H:"А теперь иди и покрасуйся в этом прикиде в {0} клубах!"};
tr[25628] = {H:"Круто! Наш обзор понравился всем, кроме Бараша - он один остался смотреть блог Нюши."};
tr[25629] = {H:"Ушастый блог"};
tr[25630] = {H:"Ёлки-иголки! Мы сняли столько всего, а просмотров у моего блога всё равно мало! Будто все смотрят что-то другое!"};
tr[25631] = {H:"Приходи в Ромашковую долину."};
tr[25632] = {H:"Спроси в общем чате: " + "\"" + "Кто тут снимает видео про Шарарам?" + "\"" + ""};
tr[25633] = {H:"Поищи блоггеров в домиках. Сходи в гости к {0} друзьям."};
tr[25634] = {H:"Оказалось, кроме меня, в Шарараме полно Смешариков, которые снимают свои видео! А ты, случайно, не один из них?"};
tr[25635] = {H:"Снимаем розыгрыши!"};
tr[25636] = {H:"Обзор на Пляж"};
tr[25637] = {H:"Блог о технике"};
tr[25638] = {H:"Блог о моде"};
tr[25639] = {H:"Кто здесь блоггер?"};
tr[25640] = {OId:330,H:"О, привет!"};
tr[25641] = {OId:331,H:"Ёлки-иголки, это ты!"};
tr[25642] = {H:"Крош?"};
tr[25643] = {H:"Крош!"};
tr[25644] = {OId:330,H:"Ты это мне?"};
tr[25645] = {OId:332,H:"Что?"};
tr[25646] = {OId:333,H:"Да?"};
tr[25647] = {H:"Ой. Вас так много. А с кем из вас можно поговорить?"};
tr[25648] = {OId:330,H:"Со мной, конечно! Сначала был я, а потом они появились."};
tr[25649] = {OId:334,H:"Нет, это я был первым! "};
tr[25650] = {OId:335,H:"Ну вот же я - настоящий Крош!"};
tr[25651] = {H:"Мда. Эй, Крош из того угла! Объясни, что случилось?"};
tr[25652] = {H:"Хм... Крош, вот ты, да, ближний ко мне, объясни, что случилось?"};
tr[25653] = {OId:330,H:"Я здесь! А все остальные - просто иллюзия."};
tr[25654] = {OId:336,H:"Только один из нас настоящий! Вот он, я!"};
tr[25655] = {OId:337,H:"Я настоящий Крош! Проверь остальных - они врут!"};
tr[25656] = {H:"Ох, придётся всех вас проверять, пока настоящего не отыщу!"};
tr[25657] = {OId:338,H:"Ну вот, теперь нас всего четверо!"};
tr[25658] = {OId:339,H:"Ёлки, а всех остальных, как и не бывало!"};
tr[25659] = {H:"Класс. Теперь давайте разберёмся, что случилось!"};
tr[25660] = {OId:338,H:"Вспомнил! Я откусил кусочек от очень вкусной морковки, и вмиг вокруг появились они!"};
tr[25661] = {OId:339,H:"Вспомнил!  Я откусил кусочек от очень вкусной морковки, и вмиг вокруг появились они!"};
tr[25662] = {H:"Эй. Так кто из вас съел морковку?"};
tr[25663] = {OId:338,H:"Я! Она явно была волшебной!"};
tr[25664] = {OId:339,H:"Я! Она явно была волшебной!"};
tr[25665] = {H:"А где теперь эта морковка?"};
tr[25666] = {OId:338,H:"Где-то здесь! Поищи, а то этот уже надоел повторять за мной!"};
tr[25667] = {OId:339,H:"Где-то здесь! Поищи, а то этот уже надоел повторять за мной!"};
tr[25668] = {H:"Так и быть, поищу!"};
tr[25669] = {OId:340,H:"Ёлки-иголки! Морковь ожила!"};
tr[25670] = {OId:150,H:"Я не простая Морковь! Я инопланетная ЗяброМорковь!"};
tr[25671] = {H:"Ясно. Если что-то прилетело в Шарарам с Зябры, жди веселья. Или беды..."};
tr[25672] = {OId:150,H:"А я не просто так прилетела! У меня на Кроша свои виды!"};
tr[25673] = {OId:340,H:"На меня? Да я тебя сейчас съем!"};
tr[25674] = {H:"Крош, стой, если ты её съешь, то всюду снова появятся твои клоны!"};
tr[25675] = {OId:150,H:"Аха! В том и план! Но мне правда-правда очень нужны кролики! Вот я и подсунула Крошу заколдованную морковь!"};
tr[25676] = {OId:340,H:"Ну и ну..."};
tr[25677] = {H:"Зачем тебе кролики? Для опытов?"};
tr[25678] = {OId:150,H:"А вы хоть раз видели на Зябре кролика? А где нет кроликов - там нет и моркови. Вот и сижу я там одна. Ой, горестно-то как!.."};
tr[25679] = {OId:340,H:"Ох... Когда плачет морковь, плачу и я..."};
tr[25680] = {H:"Ну тише, вы. Тише! Сейчас всё решим!"};
tr[25681] = {H:"Ох, ну и я тогда с вами заодно поплачу... Вааа... Вааа..."};
tr[25682] = {OId:150,H:"Может, дадите мне немного кроликов? Увезу их на Зябру - пусть мне морковных друзей выращивают."};
tr[25683] = {OId:340,H:"Ёлки! Да зачем тебе кролики? Давай я тебе своей моркови дам - из запасов. Сама и вырастишь себе друзей."};
tr[25684] = {H:"Крош, отличная идея!"};
tr[25685] = {H:"Нет уж, Крош. Полетай-ка ты на Зябру. И живи там. Всегда."};
tr[25686] = {OId:150,H:"Да, мой зубастенький! Полетели со мной!"};
tr[25687] = {OId:340,H:"Эй! Вы так на меня не смотрите! Я щас Ёжика на помощь позову!"};
tr[25688] = {H:"Ой, боюсь-боюсь! Вернёмся к первой идее."};
tr[25689] = {H:"Я нашёл настоящего Кроша !"};
tr[25690] = {H:"И победил всех его клонов. В Шарараме может случится, что угодно - приходи в игру и увидишь сам!"};
tr[25691] = {OId:150,H:"Фу! Эта не та морковь. Поищи ещё!"};
tr[25692] = {OId:150,H:"Вот она! Теперь давай рассмотрим эту морковку поближе!"};
tr[25693] = {H:"Рассмотреть"};
tr[25694] = {H:"Для того, чтобы получить волонтерские права напишите в окно чата #mxmwensoi и нажмите Enter. В течение трех дней вам придет сообщение о присвоении статуса."};
tr[25695] = {H:"Привет! Теперь ты волонтер Шарарама. Используй панель модерации слева внизу и кнопки в личной карточке для работы в новой должности. Удачи!!!"};
tr[25696] = {H:"Бейсболка с камерой"};
tr[25697] = {H:"Дзень добры! Не подскажешь, сколько зубов у кролика? Чур, мне в рот не заглядывать!"};
tr[25698] = {H:"16"};
tr[25699] = {H:"28"};
tr[25700] = {H:"32"};
tr[25701] = {H:"У кроликов не зубы, а жабры."};
tr[25702] = {H:"Три тысячи ушей! Скажи, что может обогнать заяц?"};
tr[25703] = {H:"Ракету."};
tr[25704] = {H:"Самолёт."};
tr[25705] = {H:"Трамвай."};
tr[25706] = {H:"Звук."};
tr[25707] = {H:"Кручу, верчу - запутать хочу! Скажи, кто спас зайцев от наводнения?"};
tr[25708] = {H:"Царь Берендей."};
tr[25709] = {H:"Дед Мороз."};
tr[25710] = {H:"Дед Мазай."};
tr[25711] = {H:"Лев Толстой."};
tr[25712] = {H:"Добар дан, кажитэ, на каком континенте не обитают зайцы?"};
tr[25713] = {H:"В Южной Америке."};
tr[25714] = {H:"В Австралии."};
tr[25715] = {H:"В Африке."};
tr[25716] = {H:"В Антарктиде."};
tr[25717] = {H:"Клуб Кроша"};
tr[25718] = {H:"Вечеринка в самом разгаре, а Крош всё не выходит. Сходи-ка в погреб, позови его, а?"};
tr[25719] = {H:"Позвать"};
tr[25720] = {H:"Голограмма Крошски"};
tr[25721] = {H:"Диван " + "\"" + "Кролик" + "\"" + ""};
tr[25722] = {H:"Ушастый телевизор"};
tr[25723] = {H:"Фон " + "\"" + "Я с Крошем" + "\"" + ""};
tr[25724] = {H:"Крошмобиль"};
tr[25725] = {H:"Клуб Кроша"};
tr[25726] = {H:"Клуб Кроша с квестом"};
tr[25728] = {H:"Совсем уже! Кругом кролики: Крош то, Крош это. Крош такой классный, Крош такой крутой! А я?!!"};
tr[25729] = {H:"Я тоже в восторге от Кроша!"};
tr[25730] = {H:"Нюша, ты лучше всех!"};
tr[25731] = {H:"А разве есть у Кроша такой пяточок?! А сладкий голос? А платья, шляпки, туфли, банты, браслеты?! А вот у меня - есть!"};
tr[25732] = {H:"Твоя взяла, Нюша. Ты прекрасней всех на свете!"};
tr[25733] = {H:"Ой, спасибо. Значит, ты не пойдёшь в этот весёлый и классный клуб Кроша, а останешься грустить со мной?"};
tr[25734] = {H:"Ой... А что это за клуб? Я так, из любопытства спрашиваю."};
tr[25735] = {OId:270,H:"Хола, амиго! Я первый кролик в Марара.., ой, то есть в Шарараме! Мои уши слыхали немало тайн! Спрашивай."};
tr[25736] = {H:"Какую музыку слушает Злобикус?"};
tr[25737] = {H:"В каком фильме снималась Сирена Мегас?"};
tr[25738] = {H:"Кто готовит еду для клубов?"};
tr[25739] = {H:"В каком городе родился Эйджей?"};
tr[25740] = {OId:270,H:"Днём Злобикус слушает группу " + "\"" + "Коршун" + "\"" + ", а ближе к ночи включает альбом Сяо-Мяо " + "\"" + "Любовь в цвете сакуры" + "\"" + " и... плачет."};
tr[25741] = {OId:270,H:"О! Сирена однажды снялась в картине, которая называлась " + "\"" + "Чудной Макс: Дорога к сладостям" + "\"" + "."};
tr[25742] = {OId:270,H:"Это величайшая тайна! Шеф-повар всех клубов - музейщица Фёкла! Только не говори об этом Марарашу..."};
tr[25743] = {OId:270,H:"Я не знаю, в каком городе родился Эйджей. Точно могу сказать только, что в его названии есть буквы " + "\"" + "О" + "\"" + ", " + "\"" + "М" + "\"" + ", " + "\"" + "С" + "\"" + " и " + "\"" + "К" + "\"" + "."};
tr[25744] = {H:"Невероятно! Расскажи что-нибудь ещё."};
tr[25745] = {H:"Спасибо. Хватит с меня тайн."};
tr[25746] = {H:"Возьми морковку и наведи на Крошей"};
tr[25747] = {H:"Смешутка " + "\"" + "Капля" + "\"" + ""};
tr[25748] = {H:"СмеШутка " + "\"" + "Капля" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь поливать Смешариков водой ещё дней: {0}|Ты можешь поливать Смешариков водой всегда!"};
tr[25749] = {H:"Кубок поющих кроликов|За исполнение самых ушастых песен."};
tr[25750] = {H:"Кубок танцующих кроликов|За исполнение самых ушастых танцев."};
tr[25751] = {H:"Водопланетный домик"};
tr[25752] = {H:"Костюм СуперАгента"};
tr[25753] = {H:"Костюм СуперАгента"};
tr[25754] = {H:"Пиратские смайлы"};
tr[25755] = {H:"Снеговик"};
tr[25756] = {OId:150,H:"Я мороженка, вкусная холодная мороженка! "};
tr[25757] = {H:"Шеф, родненький, что с тобой? "};
tr[25758] = {OId:150,H:"Ты меня раскрыл?! Я замаскировался и сижу в засаде!  "};
tr[25759] = {H:"Ну, эээ, как бы... тебя видно!"};
tr[25760] = {H:"И зачем ты притворяешься мороженым? "};
tr[25761] = {OId:150,H:"Я ищу смельчака, который сможет выполнить самую сложную миссию."};
tr[25762] = {H:"Меня возьми! Я готов! А что надо делать? "};
tr[25763] = {OId:150,H:"У фабрики мороженого так много заказов, что работники не справляются. Поможешь им? "};
tr[25764] = {H:"Пфф, конечно! А что тут сложного? "};
tr[25765] = {OId:150,H:"Самое сложное - удержаться и самому не съесть всё мороженое =)"};
tr[25766] = {H:"Да, это задачка для агента со стальным характером! Как раз для меня!"};
tr[25767] = {H:"Магия " + "\"" + "Совунья" + "\"" + ""};
tr[25768] = {H:"Магия " + "\"" + "Совунья" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Совунью дней: {0}|Ты можешь превращаться в Совунью всегда!"};
tr[25769] = {H:"Превращайся в самого мудрого Смешарика!|Танцуй тектоник!|Закаляйся ледяной водой!"};
tr[25770] = {OId:150,H:"Ты отлично помог на фабрике мороженого! Твой подарок уже у тебя в гардеробе на Личной карточке."};
tr[25771] = {OId:150,H:"Узнай, зачем мы здесь, – беги к МедвеДусе у Больнички."};
tr[25772] = {H:"Космодром"};
tr[25773] = {H:"Космическая станция"};
tr[25774] = {H:"Планета Мюра"};
tr[25775] = {H:"Кукла Элли"};
tr[25776] = {H:"Мистер Зюзя"};
tr[25777] = {H:"Урок чудесных причёсок"};
tr[25778] = {H:"Круто! Ты стал магом-стилистом! Ставлю тебе " + "\"" + "зачёт" + "\"" + " и дарю причёску, как у меня. Она уже у тебя в гардеробе."};
tr[25779] = {H:"Прическа Стефана"};
tr[25780] = {H:"Предсказания сбываются!"};
tr[25781] = {H:"Я обнаружил скрижаль с предсказанием. Поможешь узнать, что сулит нам пророчество, и исполнить его?"};
tr[25782] = {H:"Скрижаль разбита. Чтобы починить её, приходи в Школу магов."};
tr[25783] = {H:"Напиши в общий чат заклинание: Клей-клей, не жалей!"};
tr[25784] = {H:"Чтобы текст на скрижали проявился, выиграй в Волшебный карандаш."};
tr[25785] = {H:"Я прочёл предсказание. Если мы исполним всё, что в нём сказано, то Шарарам ждёт 100 лет процветания!"};
tr[25786] = {H:"Предсказания сбываются!"};
tr[25787] = {H:"Давай исполним пророчество. Первая его строка гласит: " + "\"" + "Сытые Смешарики в песках светятся с жемчужиной в руках" + "\"" + "."};
tr[25788] = {H:"Приходи на Пляж."};
tr[25789] = {H:"Собери {0} Жемчужины."};
tr[25790] = {H:"Накорми Смешариков - поработай в Кафе и заработай {0} Смешинок."};
tr[25791] = {H:"Текст предсказания очень странный! Держи награду за труды!"};
tr[25792] = {H:"Предсказания сбываются!"};
tr[25793] = {H:"Продолжим исполнять пророчество. Вот его текст: " + "\"" + "Мяч летит над головой, все бегут к себе домой" + "\"" + "."};
tr[25794] = {H:"Приходи в Парк аттракционов."};
tr[25795] = {H:"Сыграй в Футбол."};
tr[25796] = {H:"Сходи в гости к {0} Смешарикам."};
tr[25797] = {H:"Мы на шаг ближе к исполнению пророчества! Держи Смешинки за помощь."};
tr[25798] = {H:"Предсказания сбываются!"};
tr[25799] = {H:"Исполним эту строку предсказания: " + "\"" + "Кораллы катятся с горы, а вместе с ними катишься и ты" + "\"" + "."};
tr[25800] = {H:"Приходи в Подводный мир."};
tr[25801] = {H:"Собери {0} Кораллов."};
tr[25802] = {H:"Прокатись на санках со Снежной горы."};
tr[25803] = {H:"Весёлые предсказания, правда? Вот твоя награда!"};
tr[25804] = {H:"Предсказания сбываются!"};
tr[25805] = {H:"Осталась последняя строка пророчества: " + "\"" + "Стало видно всё насквозь, счастье в Шарарам неслось" + "\"" + ". Скорее исполни её!"};
tr[25806] = {H:"Приходи в Больничку."};
tr[25807] = {H:"Сделай рентген."};
tr[25808] = {H:"Запасись позитивной энергией! Выиграй {0} штук в любой игре!"};
tr[25809] = {H:"Предсказание исполнено! Теперь Шарарам ждёт 100 лет процветания! Если ты, конечно, веришь в пророчества..."};
tr[25810] = {H:"Что предсказано Шарараму?"};
tr[25811] = {H:"Сытое предсказание"};
tr[25812] = {H:"Круглое предсказание"};
tr[25813] = {H:"Предсказание о кораллах"};
tr[25814] = {H:"Исполни пророчество!"};
tr[25815] = {OId:150,H:"Вот здорово! Скоро я встречусь с хозяином!"};
tr[25816] = {H:"Круто!"};
tr[25817] = {H:"Я спас Пина и получил подарок! Приходи и ты в Шарарам!"};
tr[25818] = {H:"Летучий защитник"};
tr[25819] = {H:"Он будет всюду ходить за тобой!|Ищи в " + "\"" + "Аксессуарах" + "\"" + " у себя в гардеробе."};
tr[25820] = {H:"Мужественный взгляд"};
tr[25821] = {H:"Пронзительный взгляд"};
tr[25822] = {H:"Суровый взгляд"};
tr[25823] = {H:"Няшный взгляд"};
tr[25824] = {H:"После покупки ищи части образа на Личной карточке в разделе " + "\"" + "Образ" + "\"" + "."};
tr[25825] = {H:"Нос " + "\"" + "Острый нюх" + "\"" + ""};
tr[25826] = {H:"Носик-курносик"};
tr[25827] = {H:"Носик " + "\"" + "Кнопка" + "\"" + ""};
tr[25828] = {H:"Брутальная улыбка"};
tr[25829] = {H:"Улыбка " + "\"" + "Зубастик" + "\"" + ""};
tr[25830] = {H:"Улыбка до ушей"};
tr[25831] = {H:"Хулиганская улыбка"};
tr[25832] = {H:"Уши " + "\"" + "Р-р, гав!" + "\"" + ""};
tr[25833] = {H:"Уши " + "\"" + "Эльф" + "\"" + ""};
tr[25834] = {H:" Ушастые уши"};
tr[25835] = {H:"Значок агента|Значок принесут через {0} мин."};
tr[25836] = {H:"Я снял секретный фильм!"};
tr[25837] = {H:"В нём много подвигов и героев! Хочешь узнать, каких? Скорее в Шарарам!"};
tr[25838] = {H:"Получить"};
tr[25839] = {H:"Поздравляем! Камера уже в твоём гардеробе в разделе " + "\"" + "Аксессуары" + "\"" + "!"};
tr[25840] = {OId:270,H:"Найди в Шарараме секретных агентов и сними про них фильм."};
tr[25841] = {OId:270,H:"Возьми камеру у Пина на Съёмочной площадке и надень её, чтобы снять меня в фильме!"};
tr[25842] = {OId:347,H:"Исследуй стол с техникой Пина здесь, на Съёмочной площадке!"};
tr[25843] = {OId:270,H:"Шаранит так хорошо защищён, что я его и не прячу. Кликни на отсек в полу, чтобы сфоткать камень!"};
tr[25844] = {OId:270,H:"Шо? Мои грабли этой какой-то актерфат? Поищи их вон там, в повозке."};
tr[25845] = {OId:352,H:"Когда будешь готов, надень камеру и кликни на ловушку, чтобы заманить злодея!"};
tr[25846] = {OId:351,H:"Кликни на Злобикуса, чтобы расколдовать агентов!"};
tr[25847] = {OId:346,H:"У нас беда! Агентов из нашего фильма превратили в овощи!"};
tr[25848] = {OId:345,H:"Ой..."};
tr[25849] = {H:"Пойду обдумаю эту новость в одиночестве."};
tr[25850] = {H:"Это явно сделал не я!"};
tr[25851] = {OId:346,H:"Ты - единственный свидетель! Надо собраться с мыслями и решить, как вести расследование!"};
tr[25852] = {OId:345,H:"Я - Нюша. Я не хочу ничего решать. Я хочу трюфель."};
tr[25853] = {H:"Шеф, расскажи, когда произошло нападение на агентов."};
tr[25854] = {H:"Шеф, как они превратились в овощи?"};
tr[25855] = {OId:346,H:"На агентов кто-то напал и заколдовал сразу после ваших съёмок!"};
tr[25856] = {H:"Значит, за нами следили."};
tr[25857] = {OId:346,H:"На агентов наложено тёмное заклятие! Это явно дело рук того, кто владеет магией!"};
tr[25858] = {H:"Вероятно, в деле замешан Злобикус!"};
tr[25859] = {OId:346,H:"В этом есть что-то разумное! Хочешь спросить что-нибудь ещё?"};
tr[25860] = {H:"Да!"};
tr[25861] = {H:"Нет! Я уже готов раскрыть это преступление."};
tr[25862] = {OId:346,H:"Думаю, это Злобикус проследил за агентами и превратил их в овощи. Но как?"};
tr[25863] = {H:"Может, дело в камере, которую мне дал Пин? Посмотрим на его стол!"};
tr[25864] = {OId:348,H:"Гутен таг всем!"};
tr[25865] = {OId:349,H:"Наконец-то мы в сборе!"};
tr[25866] = {H:"Пин, мы уже виделись. Зачем здороваться?"};
tr[25867] = {OId:348,H:"Найн! На съёмочной площадке ты встречайт гадкий самозванец!"};
tr[25868] = {OId:349,H:"Я думаю, это Злобикус притворился Пином! Дай-ка взгляну на детали, которые ты собрал!"};
tr[25869] = {H:"Нет! Я теперь никому не доверяю и детали не отдам. А зачем они, кстати?"};
tr[25870] = {H:"Держи, Шеф! Только ты можешь объяснить, наконец, что к чему!"};
tr[25871] = {OId:348,H:"Дайте я посмотрейт! Хм... Обычные детали. А вот объектив заколдован!"};
tr[25872] = {OId:349,H:"Думаю, с помощью этих объективов можно подглядывать за всем, что снимает камера!"};
tr[25873] = {H:"Значит, Злобикус притворился Пином и дал мне камеру, чтобы следить за агентами?"};
tr[25874] = {OId:349,H:"Конечно! Камера записывала всё и передавала злодею. Так он выследил агентов и заколдовал!"};
tr[25875] = {OId:348,H:"Надо его срочно останавливайт!"};
tr[25876] = {H:"Но как мы это сделаем?"};
tr[25877] = {OId:348,H:"Просто! Надо снимайт ещё кино про агентов - Злобикус увидит его, и прибежит на съёмку!"};
tr[25878] = {OId:349,H:"А мы устроим ему ловушку! Я даже знаю, чем привлечь Злобикуса!"};
tr[25879] = {H:"Отлично! Снимем фильм и устроим ловушку злодею!"};
tr[25880] = {OId:350,H:"Вы раскрыли мой план! Опять! Всё! Устал злодействовать -  ухожу в отпуск!"};
tr[25881] = {OId:351,H:"Ты зубы не заговаривай. Говори – как расколдовать агентов?"};
tr[25882] = {H:"Злобикус боится веселья. Давайте заставим его слушать анекдоты Ёжика!"};
tr[25883] = {H:"Напугаем его пирожками Совуньи. Сразу подобреет!"};
tr[25884] = {OId:350,H:"Н-н-ет! Только не это! Я подскажу, как расколдовать агентов, только помилуйте!"};
