tr[26031] = {H:"Агент, не дай Злобикусу покинуть поддельный Шарарам! Спускайся в подземелье на Площади у Больнички и догони злодея!"};
tr[26032] = {H:"Найди в Шарараме прорехи и расколдуй их. И помни - всё, что ты видишь - подделка!"};
tr[26033] = {H:"Дорога в настоящий Шарарам полна ловушек! Чтобы догнать Злобикуса, реши загадку этой комнаты!"};
tr[26034] = {H:"Путь преграждает пропасть Хм... Интересно, для чего здесь эти кружки на стенах?"};
tr[26035] = {H:"Ага! Слуги Злобикуса преградили путь! Я уверен, ты с ними справишься."};
tr[26036] = {H:"Упс... Вот я и попался..."};
tr[26037] = {H:"Ну что, ты готов поверить мне, что этот Шарарам ненастоящий?"};
tr[26038] = {H:"Не верю! Посмотри на моих друзей - они настоящие."};
tr[26039] = {H:"Сомнительно! А как же мой домик и мой гардероб? Они реальны."};
tr[26040] = {H:"Этот поддельный Шарарам похож на настоящий! Но на самом деле - это колдовская темница, в которую нас заточили."};
tr[26041] = {H:"Чем докажешь?"};
tr[26042] = {H:"Всё просто! Смотри, что я тебе покажу!"};
tr[26043] = {H:"Где?"};
tr[26044] = {H:"Ну, что скажешь? Шарарам - это лишь иллюзия. Верно, да?"};
tr[26045] = {H:"Ты прав. А как вернуться в прежний Шарарам?"};
tr[26046] = {H:"Помоги мне ослабить силу колдовства в этой подделке, чтобы открыть проход в старый добрый Шарарам!"};
tr[26047] = {H:"Старый Шарарам.... Как же я хочу в него вернуться!"};
tr[26048] = {H:"Посмотри, в Порту появились магические прорехи. Найди такие же в Шарараме и расколдуй их, чтобы открыть выход из подделки!"};
tr[26049] = {H:"Хорошо. Уже бегу! "};
tr[26050] = {H:"Горжусь тобой. Самое время отправиться в настоящий Шарарам!"};
tr[26051] = {H:"Окей, побежали!"};
tr[26052] = {H:"Подожди немного. Хочу ещё полюбоваться этой подделкой."};
tr[26053] = {H:"Аха-ха! Вот так сюрприз, да? Наконец-то моему заточению пришёл конец!"};
tr[26054] = {H:"Злобикус, это ты? Какое заточение?"};
tr[26055] = {H:"Кто-то посадил меня в этот поддельный Шарарам, как в темницу! И тогда я магией перенёс тебя сюда!"};
tr[26056] = {H:"Я-то тебе зачем? Сидел бы один в этой темнице, раз так."};
tr[26057] = {H:"Ха! Ты помог мне ослабить заклятие, чтобы открыть проход в настоящий Шарарам!"};
tr[26058] = {H:"Ну и злодей же ты, Злобикус! Наконец-то я понял, почему тебя так зовут."};
tr[26059] = {H:"Аста ла виста, Смешарик! Я убегаю творить зло в настоящий Шарарам!"};
tr[26060] = {H:"Эй, нет! Подожди меня!"};
