tr[26089] = {H:"Ты только посмотри: Герань и Гладиолус вместе сбежали в пустыню. Ну и ну."};
tr[26090] = {H:"Побег из цветника"};
tr[26091] = {H:"Некоторые цветы любят темноту и прохладу. Давай поищем такое место в Шарараме."};
tr[26092] = {H:"Приходи в Дремучий лес."};
tr[26093] = {H:"Напиши в общий чат: " + "\"" + "Ау! Я цветы к себе зову!" + "\"" + ""};
tr[26094] = {H:"Собери дары леса - вдруг по дороге и цветок найдётся?"};
tr[26095] = {H:"Ох, глупая Орхидея заблудилась в лесу. Но мы её спасли! Осталось найти ещё один цветок."};
tr[26096] = {H:"Побег из цветника"};
tr[26097] = {H:"Ох, как я устала! Давай немного развеемся в клубах."};
tr[26098] = {H:"Приходи в Клубный квартал."};
tr[26099] = {H:"Посмотрим, кто сегодня выступает в клубах. Собери {0} Флаерса."};
tr[26100] = {H:"Отдохни. Сходи в {0} клубов."};
tr[26101] = {H:"Удача! В клубах я встретила Лотос. Вот негодник, ушёл с моей клумбы и давай танцевать. Теперь все мои цветы снова в сборе!"};
tr[26102] = {H:"Побег из цветника"};
tr[26103] = {H:"Я поняла: цветы разбежались, потому что им надоело сидеть в Джунглях на одном месте."};
tr[26104] = {H:"Вернём их назад. Приходи в Джунгли."};
tr[26105] = {H:"Покажи цветам, что в джунглях весело. Полетай с Муравьем Лео и заработай {0} Смешинок."};
tr[26106] = {H:"Отправь друзьям {0} сообщений на Шарафон: " + "\"" + "Приходи на тусовку в Джунгли" + "\"" + "."};
tr[26107] = {H:"Мои цветочки наконец-то довольны. Спасибо за помощь - вот твоя награда!"};
tr[26108] = {H:"Потерянные на пляже"};
tr[26109] = {H:"Затерявшиеся в Египте"};
tr[26110] = {H:"Пропавшие в лесу"};
tr[26111] = {H:"Унесенные вечеринкой"};
tr[26112] = {H:"В джунглях классно!"};
tr[26113] = {H:"Цветочные часы"};
tr[26114] = {H:"Бабочка " + "\"" + "Махаон" + "\"" + ""};
tr[26115] = {H:"Веснушка"};
tr[26116] = {H:"Солнечный скейт"};
tr[26117] = {H:"Весенние смайлы"};
tr[26118] = {H:"Кубок имени Веснушек.|За спасение веснушек в облаках!"};
tr[26119] = {H:"Кубок солнечных лужаек.|За тёплую весну в Шарараме!"};
tr[26120] = {OId:350,H:"Ёлки-метёлки! Я Клош, давай играть в баскетбол!"};
tr[26121] = {OId:351,H:"Нет. Я Рюша, давай вместе пойдём почитаем ЭНЦИКЛОПЕДИИ."};
tr[26122] = {H:"Нет! Вы какие-то подделки!"};
tr[26123] = {OId:350,H:"##%ВаЫВЩ!#$@%%#"};
tr[26124] = {OId:351,H:"%^%УЦУАФыВА"};
tr[26125] = {H:"Упс, вы сломались. Пойду найду того, кто объяснит, откуда взялись подделки."};
tr[26126] = {H:"Смайлы с Шарри Коттером"};
tr[26127] = {H:"Домик с ловушками"};
tr[26128] = {H:"Стопроцентная медаль.|За победу над Злобикусом в поддельном Шарараме."};
tr[26129] = {H:"Я сбежал из поддельного Шарарама!"};
tr[26130] = {H:"И одержал победу над тёмными силами! Скорее в игру!"};
tr[26131] = {H:"Смайлы-Лайки"};
tr[26132] = {H:"Я сделал Нюшу популярной!"};
tr[26133] = {H:"И сумел собрать кучу лайков! Хочешь и ты так же? Скорее в Шарарам!"};
tr[26134] = {H:"Космо-машинка"};
tr[26135] = {H:"Кресло " + "\"" + "Аэропорт" + "\"" + ""};
tr[26136] = {H:"Табло " + "\"" + "Аэропорт" + "\"" + ""};
tr[26137] = {H:"Стойка регистрации " + "\"" + "Аэропорт" + "\"" + ""};
tr[26138] = {H:"Набор мебели " + "\"" + "Аэропорт" + "\"" + ""};
tr[26140] = {H:"Стикеры"};
tr[26141] = {OId:270,H:"Скоро я повезу мышат на остров, но..."};
tr[26142] = {H:"Никаких но! Отвези их, и дело с концом!"};
tr[26143] = {OId:270,H:"Да ты дослушай! ...но кот не собирается уходить от нас."};
tr[26144] = {H:"И...?"};
tr[26145] = {OId:270,H:"Иди к Коту, узнай: не задумал ли он чего недоброго?"};
tr[26146] = {H:"Уже бегу!"};
tr[26147] = {OId:355,H:"Мя-яу, я так люблю сыр!"};
tr[26148] = {H:"Стоп! Ты не ешь мышей?! Зачем же тогда бегал за ними?"};
tr[26149] = {OId:355,H:"Они делают сыр из всего, к чему прикасаются! А я его ем. Боюсь, не удержусь и съем Шарарам, если ты не добудешь для меня сыроварку!"};
tr[26150] = {H:"Эм, и где я её найду?"};
tr[26151] = {OId:355,H:"Кажется, я видел её в Лесу у зябрийского Кока."};
tr[26152] = {H:"Ладно, уговорил. Пойду искать сыроварку. Не ради тебя, а ради Шарарамчика!"};
tr[26153] = {H:"Фон " + "\"" + "Пончики" + "\"" + ""};
tr[26154] = {H:"Снуд"};
tr[26155] = {H:"Очки " + "\"" + "На стиле" + "\"" + ""};
tr[26156] = {H:"Крутая корона"};
tr[26157] = {H:"Магия " + "\"" + "Бараш" + "\"" + ""};
tr[26158] = {H:"Шарафон " + "\"" + "Ёжик" + "\"" + ""};
tr[26159] = {H:"Смайлы " + "\"" + "Топ" + "\"" + ""};
tr[26160] = {H:"Очки " + "\"" + "Котэ" + "\"" + ""};
tr[26161] = {H:"Прическа " + "\"" + "Котэ" + "\"" + ""};
tr[26162] = {H:"Безрукавка " + "\"" + "Котэ" + "\"" + ""};
tr[26163] = {H:"Костюм " + "\"" + "Котэ" + "\"" + ""};
tr[26164] = {H:"Сырный домик"};
tr[26165] = {H:"Магия " + "\"" + "Бараш" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Бараша ещё дней: {0}|Ты можешь превращаться в Бараша всегда"};
tr[26166] = {OId:355,H:"Найди для меня Сыроварку в Лесу. Иначе я весь сырный Шарарам съем!"};
tr[26167] = {OId:270,H:"Защити Шарарам от кота и получи подарок на выбор!"};
tr[26168] = {H:"Я спас Шарарам от сыра!"};
tr[26169] = {H:"И накормил Котика-великана! А тебе слабо?"};
tr[26170] = {H:"Золотая кошечка"};
tr[26171] = {OId:355,H:"Мяу! Я ищу здесь мышей: они превратили мой дом в сыр и съели его. Берегись, они и твою страну слопают!"};
tr[26172] = {H:"Суши|Суши приготовят через {0} мин."};
tr[26173] = {H:"Я - главная звезда Шарарама и мастер крутых розыгрышей! Хочешь так же? Скорее в игру! "};
tr[26174] = {H:"Я - главная звезда Шарарама и мастер крутых розыгрышей! Хочешь так же? Скорее в игру! "};
tr[26175] = {H:"Привёт, Ёжик! Ой, ты не Ёжик. Я тут готовлю классные суши с маринованной морковью. Угощайся, если хочешь!"};
tr[26176] = {H:"Хи-хи! Я тебя разыграла. Нету в Диско никакого овощного маскарада. А костюмчик тебе очень идёт!"};
tr[26177] = {H:"Ахаха! Эти дурачки думают, что я не буду их разыгрывать. А я буду! Уахах, хочешь со мной?"};
tr[26178] = {H:"Может быть. А кого мы разыграем?"};
tr[26179] = {H:"Ты красива, спору нет. Но ответ мой будет " + "\"" + "нет" + "\"" + "."};
tr[26180] = {H:"Всех звёзд! И особый прикол у меня приготовлен для Джибера! Ну так что, согласен помочь мне с розыгрышами?"};
tr[26181] = {H:"Я согласен. Выбираю тебя, Сирена!"};
tr[26182] = {H:"Ой, что-то на меня Джибер как-то странно смотрит. Поговорю с ним!"};
tr[26183] = {H:"Так-с, так-с, так-с! Никто не подозревает, что я задумал шикарные розыгрыши. Присоединяйся!"};
tr[26184] = {H:"Хорошо! А что мы будем делать?"};
tr[26185] = {H:"Джибер, я пока сомневаюсь."};
tr[26186] = {H:"Мы разыграем всех звёзд. Да, да, и даже Сирену! Ну так что, согласен помочь мне с розыгрышами?"};
tr[26187] = {H:"Я согласен. Выбираю тебя, Джибер!"};
tr[26188] = {H:"Подожди, Сирена смотрит на меня с недовольством. Поговорю с ней!"};
tr[26189] = {H:"О! Ну и вид у тебя... Вход в Диско закрыт!"};
tr[26190] = {H:"Как закрыт? Да ты вообще знаешь, кто я? А ну-ка впускай!"};
tr[26191] = {H:"СтражНик, ну пропусти, пожалуйста! Я тебе конфетку дам (если сам найду). "};
tr[26192] = {H:"Не могу я! Диско закрыто на маскарад. Найдёшь наряд - пропущу."};
tr[26193] = {H:"Ладно, так и быть. А как именно нужно нарядиться?"};
tr[26194] = {H:"Йо-хо-хо! Хо-хо... Хо-хо... Хо..."};
tr[26195] = {H:"Ага! Я нашёл записку и теперь всё знаю, пират!"};
tr[26196] = {H:"Ты ничего не знаешь. Или знаешь?"};
tr[26197] = {H:"Это ты устроил розыгрыш и превратил моего друга в лужу!"};
tr[26198] = {H:"Преступник - дворецкий!"};
tr[26199] = {H:"Эта новость заводит наш разговор в тупик."};
tr[26200] = {H:"И вправду. Попробуем снова"};
tr[26201] = {H:"Да! Я использовал немного пиратской магии для того розыгрыша!"};
tr[26202] = {H:"Подурачились и хватит. Расскажи, как расколдовать лужу обратно!"};
tr[26203] = {H:"Ладно, не сердись. Чтобы превратить лужу обратно в артиста, найди сундук в Каньоне. В нём спрятано особое зелье."};
tr[26204] = {H:"Каньон, сундук, зелье. Всё понятно."};
tr[26205] = {H:"Ну и вид у тебя. Успокойся - погрызи корень пустырника."};
tr[26206] = {H:"Да вы издеваетесь! Совунья, всё это время меня разыгрывала ты?"};
tr[26207] = {H:"Да, я. Между прочим, розыгрыши очень полезны для здоровья."};
tr[26208] = {H:"А превращать Смешариков в лужи тоже полезно?"};
tr[26209] = {H:"Хо-хо! Ну подумаешь, немножко пошалила! Я же не Крош какой-нибудь. И уж точно не Ёжик."};
tr[26210] = {H:"Эх, Совунья, Совунья! Давай вернём всё назад."};
tr[26211] = {H:"Ну конечно вернём! Приходи в Сити - разберёмся с твоей лужицей."};
tr[26212] = {H:"Иду-иду."};
tr[26213] = {OId:363,H:"Улыбайся!"};
tr[26214] = {OId:362,H:"Чиииз!"};
tr[26215] = {H:"Так. Стоп. Что?!"};
tr[26216] = {H:"Я улыбаюсь, когда смешно. А сейчас вот - совсем не смешно."};
tr[26217] = {OId:363,H:"Мы тебя разыграли! Весело, правда?"};
tr[26218] = {OId:362,H:"Всё это время мы водили тебя за нос!"};
tr[26219] = {H:"А как же лужа, как же записка, стражник, пират, сундук...?"};
tr[26220] = {OId:363,H:"Мы старались! Лужу вот Эйджей в вёдрах натаскал, пиратом был Сумрак..."};
tr[26221] = {OId:362,H:"А Нюшей была Сяо Мяо, которая научилась даже говорить без ошибок!"};
tr[26222] = {H:"Ух ты! Сяо, а можно послушать?"};
tr[26223] = {OId:364,H:"Конесно низзя! Мы снова тебя разыграри!"};
tr[26224] = {H:"Я вот щас обижусь. И уйду."};
tr[26225] = {OId:363,H:"Извини-извини! Мы приготовили для тебя подарок!"};
tr[26226] = {H:"Кликни на коробку, чтобы получить награду!"};
tr[26227] = {H:"Спасибо! Подарки я люблю."};
tr[26228] = {H:"Получить"};
tr[26229] = {OId:154,H:"О! Смешарик. Ты на самом деле здесь или ты мираж?"};
tr[26230] = {H:"Конечно, я здесь! ПылеСанчо, а что тебе мерещится?"};
tr[26231] = {H:"Да, я мираж. А миражи не разговаривают. Пока, ПылеСанчо!"};
tr[26232] = {OId:154,H:"Лучше не спрашивай! С тех пор, как я застрял в стакане с соком, меня преследуют кошмары!"};
tr[26233] = {H:"А где же остальные? Юи, МедвеДуся...?"};
tr[26234] = {OId:154,H:"Нас всех разбросало по столу с закусками! Вот если бы я был мощнее, я бы притянул их сюда! Я же пылесос!"};
tr[26235] = {H:"А я же механик! Почти. Давай посмотрим, что там у тебя!"};
tr[26236] = {H:"Я совершил большой подвиг и спас маленьких героев! Приходи в Шарарам - здесь весело!"};
tr[26237] = {H:"Играй и получай подарки."};
tr[26238] = {OId:356,H:"Помоги ЮИ наладить воздушный шар!"};
tr[26239] = {H:"Цветочный диван"};
tr[26240] = {H:"Весенний гамак"};
tr[26241] = {H:"Чудесное дерево"};
tr[26242] = {H:"Телевизор " + "\"" + "Дикая природа" + "\"" + ""};
tr[26243] = {H:"Укуси меня пчела, я научился выращивать мебель! Кликни на грядку и собери урожай для домика!"};
tr[26244] = {H:"Клуб Лиги героев с квестом"};
tr[26246] = {H:"Космические злюки"};
tr[26247] = {H:"Привет, землянин! Я прилетела с Зябры, чтобы сообщить тебе пренеприятнейшее известие: Шарараму угрожают злые пришельцы!"};
tr[26248] = {H:"Приходи на Космодром."};
tr[26249] = {H:"Защити орбиту Шарарама от вторжения пришельцев. Сыграй в Метеоритный тренажёр."};
tr[26250] = {H:"Напиши друзьям {0} сообщений на Шарафон: " + "\"" + "Берегись злобных пришельцев" + "\"" + "."};
tr[26251] = {H:"Я слышу переговоры пришельцев по радио. Значит, они уже прилетели в Шарарам!"};
tr[26252] = {H:"Космические злюки"};
tr[26253] = {H:"Я слышу голос пришельцев в своих наушниках. От этих звуков голова идёт кругом и совсем не получается думать!"};
tr[26254] = {H:"Приходи в Больничку."};
tr[26255] = {H:"Проверь, не навредит ли страшный голос пришельцев тебе. Сделай рентген."};
tr[26256] = {H:"Приготовь защиту от страшных звуков - собери {0} эликсиров в Школе магов."};
tr[26257] = {H:"Вот! Теперь звуки пришельцев меня не так раздражают. Держи Смешинки за помощь."};
tr[26258] = {H:"Космические злюки"};
tr[26259] = {H:"Давай устроим злюкам засаду. Сделаем липучую ловушку из желе."};
tr[26260] = {H:"Приходи в Клубный квартал."};
tr[26261] = {H:"Найди в меню одного из клубов Яблочное желе и купи."};
tr[26262] = {H:"Приманим пришельцев цветом. Раскидай в Клубном квартале {0} помидоров."};
tr[26263] = {H:"Есть! Кто-то попался! Какой-то странный пришелец... Посмотри, это же Макс - внук Дока!"};
tr[26264] = {H:"Космические злюки"};
tr[26265] = {H:"Эй, вы зачем меня в желе положили? Придётся теперь самого себя съесть. Или нет? Или съесть?"};
tr[26266] = {H:"Подбери Максу чистую одежду - сыграй в игру в Доме мод и заработай {0} Смешинок."};
tr[26267] = {H:"А пока вещи сохнут, сыграй в волейбол на Пляже."};
tr[26268] = {H:"Спасибо, что принял меня за злого пришельца! В честь этого я спою: Ой-й-ой-оу-ой! Оу-ой-ой-ой! Ой-ой! Оу-оу-й!"};
tr[26269] = {H:"Космические злюки"};
tr[26270] = {H:"Я поняла! Максик так ужасно поёт, что его голос можно перепутать с пришельцами! Помоги мне перенастроить приёмник, чтобы не путаться."};
tr[26271] = {H:"Попроси детали у Пина. Помоги ему починить вечный двигатель и заработай {0} Смешинок."};
tr[26272] = {H:"Проверим микрофоны. Спой песню Макса в общий чат: " + "\"" + "Ой! Оу! Ой! Ое!" + "\"" + ""};
tr[26273] = {H:"Здорово! Песни Макса, конечно, и дальше будут пугать Смешариков, но уж со злыми пришельцами мы его точно не перепутаем! Держи свою награду!"};
tr[26274] = {H:"Защитим орбиту!"};
tr[26275] = {H:"Назойливый шум"};
tr[26276] = {H:"Ловушка из желе"};
tr[26277] = {H:"Макс в беде"};
tr[26278] = {H:"Макс не виноват"};
tr[26279] = {H:"Смайлы Лиги героев"};
tr[26280] = {H:"Фон " + "\"" + "Крылья" + "\"" + ""};
tr[26281] = {H:"Кря! Ахах, шучу. Ответь на мой вопрос и получи подарок. Кто из них не птица?"};
tr[26282] = {H:"Вальдшнеп."};
tr[26283] = {H:"Утконос."};
tr[26284] = {H:"Пингвин."};
tr[26285] = {H:"Овсянка."};
tr[26286] = {H:"Хочешь подарочек? Вспомни, какая из этих птиц не умеет петь, и получишь его!"};
tr[26287] = {H:"Соловей."};
tr[26288] = {H:"Канарейка."};
tr[26289] = {H:"Гусь."};
tr[26290] = {H:"Сойка."};
tr[26291] = {H:"Ты знаешь дюймовочку? Прекрасная девочка! Вспомни, какой птице она помогла, и получишь подарок!"};
tr[26292] = {H:"Баклану."};
tr[26293] = {H:"Чайке."};
tr[26294] = {H:"Ласточке."};
tr[26295] = {H:"Жаворонку."};
tr[26296] = {H:"Хочешь подарок? Продолжи текст песенки про птиц: Снегири..."};
tr[26297] = {H:"Не гвозди."};
tr[26298] = {H:"Не сахар."};
