tr[26412] = {OId:368,H:"ЮИ, мне кажется, или это маленький ты?"};
tr[26413] = {OId:369,H:"Упс... Братец мой."};
tr[26414] = {OId:370,H:"Радость. Радость. Радость."};
tr[26415] = {H:"ЮИ, это твой брат? А я и не знал."};
tr[26416] = {OId:369,H:"Да, это ИУ-001. Он немножко странный, конечно. Впервые в жизни настоящего Смешарика видит!"};
tr[26417] = {OId:370,H:"Лига. Вступать. Обожать."};
tr[26418] = {H:"Я. Тоже. Так. Могу. Говорить."};
tr[26419] = {OId:368,H:"Брат Юи - наш брат! А что он умеет?"};
tr[26420] = {OId:369,H:"Ну... ИУ ещё маленький робот..."};
tr[26421] = {OId:370,H:"Способности. Не найдено. Плакать."};
tr[26422] = {H:"Ох, так он ничего не умеет! Прямо как я! ИУ, мы подружимся."};
tr[26423] = {H:"Я мастер на все руки, я его всему научу!"};
tr[26424] = {OId:368,H:"У любого героя есть суперсила и талант! Нужно их только обнаружить!"};
tr[26425] = {OId:370,H:"Таланты. Не найдено. Поиск. Не найдено. Поиск. Не найдено."};
tr[26426] = {H:"Вот заладил! А как мы найдём суперсилу ИУ?"};
tr[26427] = {OId:368,H:"У каждого героя свой путь. МедвеДусю однажды покусал робот, Пылесанчо проглотил волшебную пыль, ЮИ упал в чан с зельем..."};
tr[26428] = {H:"Давайте попробуем проделать что-нибудь такое с ИУ!"};
tr[26429] = {H:"Я стал магом-фермером и вырастил волшебные подарки в Шарараме!"};
tr[26430] = {H:"Играй и получай подарки!"};
tr[26431] = {H:"Золото|Золото добудут через {0} мин."};
tr[26432] = {OId:365,H:"Поговори с ЮИ"};
tr[26433] = {OId:370,H:"Суперсилы. Не найдено. Печаль."};
tr[26434] = {OId:369,H:"Странно! Мы столько всего сделали, а ИУ так и не открыл в себе сил."};
tr[26435] = {OId:368,H:"Нужно просто испытать его в реальном деле!"};
tr[26436] = {H:"Сэнсэй, но ведь в Шарараме всё прекрасно и никого не нужно спасать?"};
tr[26437] = {OId:368,H:"У меня есть странное предчувствие..."};
tr[26438] = {H:"Предчувствие..?"};
tr[26439] = {OId:368,H:"Я же говорил! Нюша и Бараш потеряли управление и не могут приземлиться!"};
tr[26440] = {H:"Давайте собьём воздушный шар и поймаем Нюшу и Бараша!"};
tr[26441] = {H:"Давайте сами полетим на воздушном шаре и спасём их в воздухе!"};
tr[26442] = {OId:368,H:"Эта идея хороша и безопасна, но мы все вместе в шар не влезем."};
tr[26443] = {OId:369,H:"Значит, спасём их самым рискованным способом!"};
tr[26444] = {H:"Логично. Давай собьём шар гигантской рогаткой!"};
tr[26445] = {OId:368,H:"Приходи к Пину на Снежную гору - там мы построим катапульту и батут, чтобы Бараш и Нюша не ушиблись!"};
tr[26446] = {OId:370,H:"ИУ. Помогать. Спасать. Любить."};
tr[26447] = {H:"Класс!"};
