tr[26464] = {OId:374,H:"Ты знаешь, как перебраться через лаву? Я - нет."};
tr[26465] = {OId:375,H:"И я - нет. Будем думать!"};
tr[26466] = {H:"Урок удивительных флагов"};
tr[26467] = {H:"Фон " + "\"" + "Флаги" + "\"" + ""};
tr[26468] = {H:"Куда спрятать клад?"};
tr[26469] = {H:"Йо-хо-хо! Тысяча морских огурцов, посмотри, какой клад я нашёл! Теперь нужно его как следует припрятать!"};
tr[26470] = {H:"Приходи на Пляж."};
tr[26471] = {H:"Научись прятать предметы. Выиграй в Секретики на Пляже."};
tr[26472] = {H:"Спроси у Смешариков в общем чате: А где бы спрятали клад вы?"};
tr[26473] = {H:"Ты на волне успеха! Хватай Смешинки и пошли прятать мой клад!"};
tr[26474] = {H:"Куда спрятать клад?"};
tr[26475] = {H:"В Дремучем лесу искать мой клад точно никто не будет! Давай найдём там укромное место."};
tr[26476] = {H:"Приходи в Дремучий лес."};
tr[26477] = {H:"Прогуляйся по чаще - сыграй в игру Дары леса."};
tr[26478] = {H:"Чтобы замаскировать клад, собери {0} орехов в Лесу."};
tr[26479] = {H:"Карамба! На орехи прибежали белки и чуть не унесли мой клад. Пойдём искать другое место для сокровищ."};
tr[26480] = {H:"Куда спрятать клад?"};
tr[26481] = {H:"Отправим клад в космос. Ну там-то уж точно его никто не тронет!"};
tr[26482] = {H:"Приходи на Космодром."};
tr[26483] = {H:"Подготовься к полёту. Сыграй в тренажёр на Космодроме и набери {0} Смешинок."};
tr[26484] = {H:"Ай-ай-ай! Я чуть не потерял клад в невесомости. Но тебе всё равно спасибо! Лови Смешинки!"};
tr[26485] = {H:"Куда спрятать клад?"};
tr[26486] = {H:"Обратимся к магам - они лучше всех умеют прятать предметы!"};
tr[26487] = {H:"Приходи в Школу магов."};
tr[26488] = {H:"Сделаем зелье невидимости. Для этого собери {0} эликсиров."};
tr[26489] = {H:"Чтобы зелье сработало, добавим в него монеток. Накопи ещё {0} Смешинок."};
tr[26490] = {H:"Караул! Из-за невидимости я потерял драгоценную шкатулку из своего клада. Давай спрячим оставшиеся сокровища по-другому."};
tr[26491] = {H:"Куда спрятать клад?"};
tr[26492] = {H:"Всё! Я придумал. Обхитрим всех. Спрячем клад на самом видном месте."};
tr[26493] = {H:"Приходи в Ромашковую долину."};
tr[26494] = {H:"Выбери, куда спрятать клад. Кинь в это место {0} помидоров."};
tr[26495] = {H:"Отправь сообщение на Шарафон {0} друзьям: Клад в Ромашковой долине!"};
tr[26496] = {H:"Невероятно! Никто не замечает клад - все общаются! Спасибо тебе за помощь. Вот награда."};
tr[26497] = {H:"Учимся прятать"};
