tr[26610] = {H:"Собери для акулы Дары леса - заработай {0} Смешинок в игре."};
tr[26611] = {H:"Отправь {0} сообщений друзьям на Шарафон: " + "\"" + "Я гуляю с акулой!" + "\"" + ""};
tr[26612] = {H:"Акула рада! Ты заслужил Смешинки!"};
tr[26613] = {H:"Домашняя акула"};
tr[26614] = {H:"Я слышал,ты умеешь обращаться с акулами. А я как раз недавно потерял своего Зубастика - поможешь его найти?"};
