tr[26776] = {H:"Спортивные смайлы на 7 дней"};
tr[26777] = {H:"Трибуна в домик"};
tr[26778] = {H:"Футбольные бутсы на 3 дня"};
tr[26779] = {H:"Учебник Макса|Учебник Макса принесут через {0} мин."};
tr[26780] = {H:"Взять"};
tr[26781] = {H:"Я - настоящий путешественник во времени! Хочешь так же? Заходи в Шарарам!"};
tr[26782] = {H:"Играй и получай подарки!"};
tr[26783] = {H:"Кликни на машину времени, чтобы отправиться в прошлое и найти родителей моего внука!\r\n"};
tr[26784] = {H:"Поговори с местными жителями! Вдруг они видели здесь хамелеонов - родителей моего внука?"};
tr[26785] = {H:"Площадь у Замка? Вот эта тропинка справа туда ведёт!"};
tr[26786] = {H:"Я помогу тебе выбрать подарок, достойный Короля. Ищи его здесь!"};
tr[26787] = {H:"Объекты хидденобджекта на космодроме"};
tr[26788] = {H:"по клику на 1 и 2 по счёту объект"};
tr[26789] = {H:"Королю это не понравится. Проверь другие подарки!"};
tr[26790] = {H:"Поищу ещё"};
tr[26791] = {H:"Поговори с королём! Уж он-то должен знать, где мои родители!"};
tr[26792] = {H:"Докажи мне, что можешь предсказывать будущее! Тогда и звездочётов тебе покажу."};
tr[26793] = {H:"Ты искал хамелеонов? Вот же они, с ними и разговаривай! А я пока книжечку о будущем почитаю!"};
tr[26794] = {H:"Время остановилось! Помоги Доку в Диско запустить его!"};
tr[26795] = {H:"Помоги нам наладить эту машину, и время вновь пойдёт вперёд! Кликай по сломанными деталям!"};
tr[26796] = {H:"Кликни на толкатель времени!"};
tr[26797] = {H:"Ходят тут и ходят. Туда-сюда. И хоть бы кто помог старушке хворост в дом отнести!"};
tr[26798] = {H:"А вы случаем парочку хамелеонов здесь не видали?"};
tr[26799] = {H:"Видела я, видела! Да только хворост сам себя не унесёт."};
tr[26800] = {H:"Ладно-ладно! Помогу я вам отнести хворост!"};
tr[26801] = {H:"Заходи, усталый путник, в мою кошачью таверну!"};
tr[26802] = {H:"О, привет, Шарри! А ты что здесь делаешь?"};
tr[26803] = {H:"Привет! Я ищу парочку хамелеонов. Говорят, они были здесь!"};
tr[26804] = {H:"Шарри? Я Томас Коттер по прозвищу Сытое Брюхо. Хозяин этой таверны!"};
tr[26805] = {H:"Значит, ты его прапрадедушка! Не видел тут хамелеонов?"};
tr[26806] = {H:"Были такие, но уже ушли. Забыли вот эту шкатулку! Взгляни – может она тебе поможет?"};
tr[26807] = {H:"Класс! Сейчас посмотрим."};
tr[26808] = {H:"Фи! Ты, наверное, хочешь попасть в замок?"};
tr[26809] = {H:"Хочу! Я ищу парочку хамелеонов!"};
tr[26810] = {H:"Да, они живут в нашем замке. Но ко двору тебя просто так не пропустят!"};
tr[26811] = {H:"И как же мне попасть внутрь?"};
tr[26812] = {H:"Добудь подарок для нашего короля! Он их просто обожает!"};
tr[26813] = {H:"Хорошо, а какие подарки хочет ваш король?"};
tr[26814] = {H:"Спасибо тебе за этот подарок! Чего желаешь ты от меня, короля королей?"};
tr[26815] = {H:"Я ищу родителей Макса. Хамелеонов!"};
tr[26816] = {H:"Полконя и царство в придачу."};
tr[26817] = {H:"Прости, но этого дать тебе не могу. Может, хочешь чего-то другого?"};
tr[26818] = {H:"Говорят, у тебя при дворе живут хамелеоны. Можно с ними встретиться?"};
tr[26819] = {H:"Хамелеоны - мои звездочёты! Никуда я их не отпущу и никому не покажу!"};
tr[26820] = {H:"Это почему же?"};
tr[26821] = {H:"Только они предсказывают будущее так, как будто своими глазами его видели!"};
tr[26822] = {H:"Я, между прочим, тоже умею предсказывать будущее!"};
tr[26823] = {H:"Да? А ну-ка, докажи!"};
tr[26824] = {H:"Ой, пойду спрошу у Дока."};
tr[26825] = {OId:382,H:"Мямя и пяпя! Ой, в смысле мама и папа, я так рад, что вы нашлись!"};
tr[26826] = {OId:383,H:"Мы тоже рады, умный ты наш!"};
tr[26827] = {H:"А что случилось? А где вы были? Почему в прошлом?"};
tr[26828] = {H:"Хочется заплакать... Но я сдержусь!"};
tr[26829] = {OId:384,H:"Мы были в будущем и проводили эксперимент со временем."};
tr[26830] = {OId:383,H:"Но у нас... Ммм, скажем так, немножко не получилось."};
tr[26831] = {H:"Это нормально. У меня вот тоже не всегда всё получается."};
tr[26832] = {H:"Это ужасно. Вот у меня, например, всегда всё идёт по плану."};
tr[26833] = {OId:384,H:"Произошёл временной взрыв, и нас забросило в прошлое!"};
tr[26834] = {OId:385,H:"А мы! Мы-то вас всё это время искали в настоящем!"};
tr[26835] = {H:"Всё понятно. Давайте теперь подумаем о будущем!"};
tr[26836] = {OId:384,H:"В будущем нас ждёт беда! Всё из-за временного взрыва."};
tr[26837] = {OId:383,H:"Ммм, да, есть у нас одна проблема..."};
tr[26838] = {H:"Ох, не пугайте меня."};
tr[26839] = {OId:384,H:"В будущем наступит момент, когда время полностью остановится!"};
tr[26840] = {OId:383,H:"И тогда всё в мире застынет навеки. И ничего не будет происходить."};
tr[26841] = {H:"Я так не хочу!"};
tr[26842] = {OId:384,H:"Нам надо отправиться в будущее и заставить время идти вперёд!"};
tr[26843] = {OId:385,H:"Что ж, скорее в машину времени! Только сделаем остановочку в настоящем."};
tr[26844] = {H:"Да! Летим из прошлого в настоящее, а потом в будущее! Всё просто."};
tr[26845] = {H:"юка|бо|лка|лик|мюх|лыл|кек|зя|ек|ель|лик|юх|уль|зюн|юла|зю|яш|ло|чи|мё|фыф|хых|зи|зык|пюн|ле|лья|ыы|нья|цо|аф|ыл|ня|ун|то|ти|чы|пя|ши|се|вю|бю|ныл|о|бо|зи|мю|лыл|фыф|ли|хых|е|кр|лик|юх|уль|зюн|а|зю|кю|яш|ло|чи|аф|вэ|зы|яш|ме|мю|о|оу"};
