tr[26872] = {H:"А ещё можно сделать мяч из мороженного. Сыграй в Кафе на Пляже."};
tr[26873] = {H:"У нас копится отличная коллекция мячей. Ты заслужил награду!"};
tr[26874] = {H:"Волшебный футбол"};
tr[26875] = {H:"Говорят, хороший мяч есть у морских чертенят."};
tr[26876] = {H:"Разбуди чертянет: прокатись на катере в Порту и заработай 15 Смешинок."};
tr[26877] = {H:"Надо дать чертенятам что-то взамен мяча. Собери 3 Жемчужины на Пляже."};
tr[26878] = {H:"Чертенята дали мне свой крутой мяч! Держи Смешинки за помощь!"};
tr[26879] = {H:"Волшебный футбол"};
tr[26880] = {H:"Шарри Коттер оказался болельщиком и решил помочь мне. Он придумал заклинание для волшебного мяча."};
tr[26881] = {H:"Приходи на Космодром."};
tr[26882] = {H:"Собери энергию метеоритов для мяча. Сыграй в Метеоритный тренажёр."};
tr[26883] = {H:"Напиши заклинание в общий чат: " + "\"" + "Верчу-кручу, в ворота лечу" + "\"" + "."};
tr[26884] = {H:"Волшебный мяч, который сам забивает голы - это круто. Вот твоя награда!"};
tr[26885] = {H:"Волшебный футбол"};
tr[26886] = {H:"Мне нравятся все мячи, которые мы нашли. Давай проверим их в игре."};
tr[26887] = {H:"Накопи заряд бодрости - найди 3 Позитивных энергии в Шарараме!"};
tr[26888] = {H:"Отправь 5 сообщений на Шарафон друзьям: " + "\"" + "Приходи за меня болеть!" + "\"" + ""};
tr[26889] = {H:"Испытай мячи. Сыграй в Футбол 2 раза."};
tr[26890] = {H:"Здорово! Теперь с этими мячами сыграю я. А ты лови Смешинки!"};
tr[26891] = {H:"Волшебный футбол"};
tr[26892] = {H:"Ничего не выходит! С какими бы мячами я не играл, голы всё равно не забиваются. Интересно, как удаётся побеждать другим спортсменам?"};
tr[26893] = {H:"Покажи, как надо побеждать. Сыграй в волейбол на Пляже и заработай 15 Смешинок."};
tr[26894] = {H:"Выиграй в Сноуборд на Снежной горе."};
tr[26895] = {H:"Выиграй в Скачки в Парке аттракционов."};
tr[26896] = {H:"Глядя на тебя, я понял! Чтобы забивать мячи, нужно просто больше тренироваться! Вот теперь я точно стану чемпионом!"};
tr[26897] = {H:"Новые мячи"};
tr[26898] = {H:"Морской мяч"};
tr[26899] = {H:"Волшебный мяч"};
