tr[26955] = {H:"Ух! Ты мой самый способный ученик. Можешь пожонглировать этими Смешинками - они твои!"};
tr[26956] = {H:"Цирк, цирк, цирк!"};
tr[26957] = {H:"Привет! Я питомец-улитка, и я помогу тебе стать настоящим укротителем!"};
tr[26958] = {H:"Поухаживай за своим питомцем. Поиграй с ним."};
tr[26959] = {H:"Питомец должен быть сытым. Покорми его."};
tr[26960] = {H:"Посмотрим, какой ты укротитель - победи со своим питомцем на арене!"};
tr[26961] = {H:"Ты крутой укротитель. Держи награду - можешь потратить её на воспитание своего питомца."};
tr[26962] = {H:"Цирк, цирк, цирк!"};
tr[26963] = {H:"Знаешь, кто в цирке самый крутой? Конечно, это мы - силачи! Я помогу тебе стать одним из нас."};
tr[26964] = {H:"Приходи в Дремучий лес."};
tr[26965] = {H:"Тренируй руки - носи тяжести. Собери грибов и ягод в лесу и заработай {0} Смешинок."};
tr[26966] = {H:"Силач должен сытно питаться. Найди в меню одного из клубов Шашлык и закажи."};
tr[26967] = {H:"Чувствуешь силушку? Вот! А теперь подними свою награду - этот тяжеленный мешок Смешинок!"};
tr[26968] = {H:"Цирк, цирк, цирк!"};
tr[26969] = {H:"Забыл! Самый главный человек в цирке - конферансье! Он объявляет номера и ведёт представление."};
tr[26970] = {H:"Надень элегантный наряд. Найди в Смешмаге костюм " + "\"" + "Маэстро" + "\"" + " и купи."};
tr[26971] = {H:"Позови друзей на представление: напиши {0} сообщений на Шарафон: " + "\"" + "Приглашаю в цирк" + "\"" + "."};
tr[26972] = {H:"Напиши в общий чат: " + "\"" + "Представление начинается!" + "\"" + ""};
tr[26973] = {H:"Ура! Ты освоил все цирковые профессии. Держи этот подарок - с ним ты сможешь устраивать крутые представления."};
tr[26974] = {H:"Стань фокусником!"};
tr[26975] = {H:"Стань жонглёром!"};
tr[26976] = {H:"Стань укротителем!"};
tr[26977] = {H:"Стань силачом!"};
tr[26978] = {H:"Ты - ведущий!"};
tr[26979] = {H:"Трын-трава|Трын-трава вырастет через {0} мин."};
tr[26980] = {OId:150,H:"Ух, крутота!"};
tr[26981] = {OId:270,H:"Идеально!"};
tr[26982] = {OId:388,H:"Друзья мои отдыхающие, в Шарараме творится такое, вы не поверите!"};
tr[26983] = {OId:387,H:"Лосяш, у нас тут весело - смотри какой дым из горы валит!"};
tr[26984] = {H:"Лосяш, что случилось?"};
tr[26985] = {OId:388,H:"Ваш зелёный дым превратился в тучи и залил Шарарам ядовитым дождём!"};
tr[26986] = {OId:386,H:"Ужас! Это же вредно для причёски!"};
tr[26987] = {H:"Ну и дела! Надо спасать Шарарам."};
tr[26988] = {OId:388,H:"Пока льёт дождь, нам нужно куда-то спрятать от него Смешариков!"};
tr[26989] = {OId:387,H:"Надо отвести их туда, где нет дождя!"};
tr[26990] = {H:"Спрячем их в домике!"};
tr[26991] = {H:"Спрячем их в море!"};
tr[26992] = {H:"Спрячем их под землёй!"};
tr[26993] = {OId:388,H:"Дождь так ядовит, что прожёг все крыши! Там не спрятаться."};
tr[26994] = {H:"Подумаю ещё."};
tr[26995] = {OId:388,H:"Это хорошая идея, но мы не найдём под землёй столько свободного места!"};
tr[26996] = {OId:388,H:"Ветер с моря будет отгонять ядовитые тучи!"};
tr[26997] = {OId:387,H:"Попросим морских друзей приютить Смешариков у себя!"};
tr[26998] = {OId:386,H:"А потом сами разберёмся с ядовитыми облаками из пещеры!"};
tr[26999] = {H:"Класс! Давайте так и поступим."};
tr[27000] = {OId:388,H:"Друг мой, спасающий, тогда встречаемся в Порту!"};
tr[27001] = {OId:387,H:"Мы тебе поможем!"};
tr[27002] = {H:"Уже бегу!"};
tr[27003] = {OId:389,H:"Найди в Шарараме всех Смешариков,  попавших в беду, и отправь их в море!"};
tr[27004] = {OId:389,H:"Друзья мои спасающие, вы молодцы!"};
tr[27005] = {OId:391,H:"Мы такие, да."};
tr[27006] = {H:"Осталось понять, как прогнать ядовитые тучи..."};
tr[27007] = {OId:389,H:"О, это я уже сделал! Пока вы всех спасали, я обследовал пещеру в горах."};
tr[27008] = {OId:390,H:"Лосяш, ты такой... смелый. А я и не знал."};
tr[27009] = {H:"Лосяш, и что там?"};
tr[27010] = {OId:389,H:"Под грудой камней там замурован метеорит, который прилетел к нам задолго до того, как появились горы."};
tr[27011] = {OId:390,H:"Так я, получается... Откопал этот метеорит?"};
tr[27012] = {H:"И вправду, Озик. Ай-ай-ай!"};
tr[27013] = {H:"Это не страшно! Давайте уберём метеорит оттуда."};
tr[27014] = {OId:389,H:"Капитан Базу поможет убрать метеорит! Он уже ждёт нас в Горной стране!"};
tr[27015] = {H:"Круто! Уже бегу к вертолёту!"};
tr[27016] = {OId:386,H:"Чего-то и не видно никакого метеорита. Но судя по запаху, он там есть!"};
tr[27017] = {OId:392,H:"Мда... Ситуация сложная, но план есть!"};
tr[27018] = {H:"Приветствую, капитан! А какой план?"};
tr[27019] = {OId:392,H:"Мы прицепим ядовитый метеорит к моему кораблю и вернём обратно в космос!"};
tr[27020] = {H:"Круто! Я готов помогать."};
tr[27021] = {OId:392,H:"Всё готово! Теперь кликни на мой корабль, чтобы отправить метеорит в космос!"};
tr[27022] = {OId:392,H:"Духи сказали мне: " + "\"" + "Устрой Спрутикам шикарные каникулы" + "\"" + ". И я подчинился духам."};
tr[27023] = {H:"Домик " + "\"" + "Горная страна" + "\"" + ""};
tr[27024] = {H:"Скальный крюк"};
tr[27025] = {H:"Шапка альпиниста"};
tr[27026] = {H:"Куртка альпиниста"};
tr[27027] = {H:"Костюм альпиниста"};
tr[27028] = {H:"Я спас Шарарам от ядовитого дождя! А на какие подвиги готов ты?"};
tr[27029] = {H:"Магия " + "\"" + "Копатыч" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Копатыча ещё дней: {0}|Ты можешь превращаться в Копатыча всегда!"};
