tr[27052] = {H:"Фон " + "\"" + "Я и Злобикус" + "\"" + ""};
tr[27053] = {H:"Фон " + "\"" + "Мой друг Шарри" + "\"" + ""};
tr[27054] = {H:"Фон " + "\"" + "Моя подруга Нюша" + "\"" + ""};
tr[27055] = {H:"Фон " + "\"" + "Мой друг Пин" + "\"" + ""};
tr[27056] = {H:"Жилет фотографа"};
tr[27057] = {H:"Идём в поход!  "};
tr[27058] = {OId:270,H:"Добро пожаловать в фотостудию! Фоткай Смешариков, делай селфи и прикупи себе технику!"};
tr[27059] = {H:"Пока ты сделал мало фоток. Устрой новую фотосессию."};
tr[27060] = {H:"Хочешь сделать фотку со звездой?"};
tr[27061] = {H:"Я обхитрил колдуна Злобикуса и разбудил домового! Приходи в Шарарам - будем играть вместе!"};
tr[27062] = {H:"Домик на дереве"};
tr[27063] = {H:"Домик-кит"};
tr[27064] = {H:"Меняйся подарками!"};
tr[27065] = {H:"Дружище, у меня накопилась парочка ненужных вещей! Всё в прекрасном состоянии. Помоги мне раздать их и получишь приз!"};
tr[27066] = {H:"Мой чайный сервиз понравится посетителям Кафе на Пляже. Поработай в нём."};
tr[27067] = {H:"А коллекция фотоаппаратов пригодится моделям. Сыграй в игру в Доме мод и заработай {0} Смешинок."};
tr[27068] = {H:"Прекрасно! Моему примеру последовали и другие Смешарики. Помоги им найти новых хозяев для своих вещей."};
tr[27069] = {H:"Меняйся подарками!"};
tr[27070] = {H:"Ой, а я тоже хочу подарить кому-нибудь свои вещи! Они у меня самые-самые красивые."};
tr[27071] = {H:"Отдам магам зеркальце. Наполни его волшебством: собери {0} эликсиров в Школе магов."};
tr[27072] = {H:"А шпильки можно отдать Пину. Помоги ему починить двигатель в Ромашковой долине."};
tr[27073] = {H:"А мои наряды могут заинтересовать артистов. Посети {0} клубов."};
tr[27074] = {H:"Фух! Как приятно что-то дарить. А ещё приятнее - получать. Лови Смешинки!"};
tr[27075] = {H:"Меняйся подарками!"};
tr[27076] = {H:"Ёлки-иголки! Все кому-то что-то дарят. Я тоже так хочу!"};
tr[27077] = {H:"Пора взрослеть. Мои игрушки пригодятся Крошкам. Поухаживай за ними в Детском саду."};
tr[27078] = {H:"А мячик заберут спортсмены. Сыграй с ними в Футбол."};
tr[27079] = {H:"Всё раздал! Кроме, ящика морковки, конечно. Ну а тебе Смешинок подброшу!"};
tr[27080] = {H:"Меняйся подарками!"};
tr[27081] = {H:"Ну вот... А мне совсем нечего подарить. Все мои вещи такие нужные. И полезные."};
tr[27082] = {H:"Может, поискать подарки в Шарараме? Приходи на Пляж."};
tr[27083] = {H:"Проверь, не спрятано ли чего полезного в песке. Сыграй в Секретики."};
tr[27084] = {H:"Вдруг кто-то захочет принять в подарок Жемчужины? Собери {0} штуки."};
tr[27085] = {H:"Ура! Нюша забрала у меня жемчужины! А тебе я дам Смешинки."};
tr[27086] = {H:"Меняйся подарками!"};
tr[27087] = {H:"О, вы обмениваетесь подарками! Хо-хо, дайте-ка и я присоединюсь."};
tr[27088] = {H:"Раздай мои яблочки жителям моря. Покатайся на катере в Порту и заработай {0} Смешинок."};
tr[27089] = {H:"Ещё у меня есть клубничное варенье и никто его не ест. Напиши в общий чат: " + "\"" + "Кому варенья?" + "\"" + ""};
tr[27090] = {H:"Поделимся хорошим настроением! Порадуй друзей: сходи в гости в {0} домиков."};
tr[27091] = {H:"Ух, все сегодня получили по подарку. Я и для тебя кое-что припасла."};
