tr[27206] = {OId:270,H:"Найди морских жителей в Шарараме, участвуй в весёлых соревнованиях и получи призы!"};
tr[27207] = {OId:270,H:"Сними передачи для нашего канала! Ищи Смешариков с камерами в Шарараме!"};
tr[27208] = {OId:270,H:"Хо-хо, сейчас я проверю это кафе! Посмотрим, сколько пыли у них под столами!"};
tr[27209] = {H:"Совунья, я с тобой! Давай сделаем крутую передачу для нашего канала!"};
tr[27210] = {OId:270,H:"Конечно! Только перед съёмкой не забудь помыть руки!"};
tr[27211] = {H:"Да-да, руки уже вымыты! Давай снимать!"};
tr[27212] = {OId:394,H:"Да как так-то? Ещё недавно все смотрели только мой канал! А теперь все смотрят вас!"};
tr[27213] = {OId:395,H:"Да-да, у нас самый классный канал с самыми классными передачами!"};
tr[27214] = {H:"Я согласен с Нюшей! А у тебя, Джет Стет, канал скучный и смотреть там нечего!"};
tr[27215] = {H:"Ничего не знаю - я телевидение не смотрю. Я его создаю!"};
tr[27216] = {OId:394,H:"Бррр! Из-за вашей популярности я теряю деньги. Буду вам пакостить за это!"};
tr[27217] = {OId:399,H:"Не надо пакостить! Лучше делай передачи для нашего канала. "};
tr[27218] = {H:"Да, Джет, не волнуйся! Мы научим тебя делать нормальные передачи, а не какую-то тоску!"};
tr[27219] = {OId:394,H:"Нет уж! Я просто сотру все передачи, которые вы наснимали, и тогда зрители снова будут мои!"};
tr[27220] = {OId:399,H:"Ну и дела! Он хочет стереть наши записи электронной пушкой."};
tr[27221] = {H:"Подожди-ка! Не вздумай ничего стирать!"};
tr[27222] = {OId:395,H:"Джет Стет стёр все передачи и теперь нам нечего показывать. Беги к Лосяшу на Снежной горе - он знает, что делать!"};
tr[27223] = {OId:396,H:"Ты - режиссёр! Нажимай кнопки внизу экрана и не дай Джету Стету испортить эфир!"};
tr[27224] = {OId:398,H:"В студии гость - злодей Джет Стет."};
tr[27225] = {OId:397,H:"...и наше с ним интервью."};
tr[27226] = {OId:395,H:"Я очень-очень зол! Вы помешали мне испортить вам прямой эфир!"};
tr[27227] = {H:"Джет, скажите, почему вы хотите его испортить?"};
tr[27228] = {H:"Стойте! Возьмите лучше интервью у меня!"};
tr[27229] = {OId:395,H:"Потому что все должны смотреть мой канал, а не ваш! Иначе как я помогу Злобикусу захватить Шарарам?"};
tr[27230] = {H:"Позовите на помощь меня и захватите."};
tr[27231] = {H:"Интересно! А какой план у Злобикуса?"};
tr[27232] = {OId:395,H:"Простой! Мы с ним заколдовали наши передачи так, чтобы все, кто их посмотрел, становились Злобырями."};
tr[27233] = {H:"О! Нашему каналу тоже пригодится такое волшебство!"};
tr[27234] = {H:"Так вот зачем вам столько зрителей!"};
tr[27235] = {OId:395,H:"Конечно! Мы со Злобикусом хотим захватить Шарарам через телевидение!"};
tr[27236] = {H:"Здорово! Спасибо, что в прямом эфире раскрыли все тайны для наших зрителей."};
tr[27237] = {OId:398,H:"Эй, давай возьмём нормальное интервью у Джета Стета!"};
tr[27238] = {OId:397,H:"Да! Задавай ему правильные вопросы!"};
tr[27239] = {H:"Ясненько. Попробую снова."};
tr[27240] = {H:"Я создал крутой телеканал в Шарараме! Попробуй и ты."};
