tr[27367] = {H:"Картина становится яснее. Ещё один источник, и мы поймём, куда уходит вся магическая энергия."};
tr[27368] = {H:"Сила магии"};
tr[27369] = {H:"Третий источник магии скрыт где-то в море."};
tr[27370] = {H:"Загляни в морские глубины. Посмотри в перископ в Порту."};
tr[27371] = {H:"Спускайся в Подводный мир."};
tr[27372] = {H:"Ищи магию среди сокровищ глубин. Сыграй в Батискаф."};
tr[27373] = {H:"Потоки магии от источников сходятся в одной точке - в космосе! Значит воришки магии находятся там!"};
tr[27374] = {H:"Сила магии"};
tr[27375] = {H:"Привет! Мы засекли сигнал воришек. Это космические пираты!"};
tr[27376] = {H:"Лети на Космостанцию с Космодрома."};
tr[27377] = {H:"Напугай пиратов. Напиши в общий чат: " + "\"" + "Пираты, я уже близко!" + "\"" + ""};
tr[27378] = {H:"Лети к пиратам - сыграй в Безумный полёт на Космостанции."};
tr[27379] = {H:"Пираты воровали магию, чтобы заправлять свои корабли. Но увидев нашу станцию, они испугались столкновения и улетели!"};
tr[27380] = {H:"Сила магии"};
tr[27381] = {H:"Пираты больше не воруют магию. Но вдруг они вернутся? Спрячем источники магии в новых местах."};
tr[27382] = {H:"Один источник спрячем в костюмерной. Сыграй в игру в Доме мод."};
tr[27383] = {H:"А другой - под прилавком. Сыграй в Кафе на Пляже и получи {0} Смешинок."};
tr[27384] = {H:"А третий спрячем в Парке аттракционов. Выиграй в Скачки."};
tr[27385] = {H:"Волшебно! Магия вновь наполнила Шарарам. Ты заслужил этот древний артефакт в награду!"};
tr[27386] = {H:"Куда пропала магия?"};
tr[27387] = {H:"Источник в лесу"};
tr[27388] = {H:"Источник в море"};
tr[27389] = {H:"Прогони пиратов!"};
tr[27390] = {H:"Верни магию!"};
tr[27391] = {H:"Футболка " + "\"" + "Спиннер" + "\"" + ""};
tr[27392] = {H:"Аксессуар " + "\"" + "Спиннер" + "\"" + ""};
tr[27393] = {H:"Кепка " + "\"" + "Спиннер" + "\"" + ""};
tr[27394] = {H:"Костюм " + "\"" + "Фанат спиннеров" + "\"" + ""};
tr[27395] = {H:"Будь в тренде!|Ищи спиннер, футболку и кепку в гардеробе на Личной карточке."};
tr[27396] = {H:"Я король граффити! Приходи в Шарарам и стань крутым художником!"};
tr[27397] = {H:" Отлично! 1000 баллов уже начислено."};
tr[27398] = {H:"Агент! Расследуй ограбление Сирены. Приходи в её фан-клуб в Клубном квартале!"};
tr[27399] = {OId:406,H:"Кликни на локатор, чтобы искать улики!"};
tr[27400] = {OId:406,H:"Ищи грабителя в моём фан-клубе в Клубном квартале."};
tr[27401] = {OId:270,H:"Тссс! Достань фото из чемоданчика агента и наведи на толпу фанатов, чтобы найти преступника."};
tr[27402] = {OId:407,H:"Здесь должна быть какая-то зацепка... Найди её!"};
tr[27403] = {OId:402,H:"Вы нашли их! Все мои вещи! Ура! А микрофон? "};
tr[27404] = {OId:401,H:"Микрофона нет. Зато есть улики, но их пока недостаточно. Нужны новые зацепки."};
tr[27405] = {H:"Шеф, может, пришло время осмотреть место преступления?"};
tr[27406] = {OId:401,H:"Самое время: слёзы Сирены высохли, так что можно искать улики без риска утонуть."};
tr[27407] = {H:"Я всё осмотрю. Начинаем!"};
tr[27408] = {OId:402,H:"О, вы откопали несколько моих вещей, спасибо!"};
tr[27409] = {OId:401,H:"А ещё нашли новые улики. Для начала вот: гамбургер из клубов."};
tr[27410] = {H:"Клубы? Грабитель - Босс Ба-Босс."};
tr[27411] = {H:"Хм... Гамбургер. Механик Яша их любит..."};
tr[27412] = {OId:401,H:"Ещё у нас есть след обуви - и размер явно не такой, как у Ба-Босса..."};
tr[27413] = {OId:402,H:"Значит, грабитель просто завсегдатай клубов!"};
tr[27414] = {OId:402,H:"У Яши цвет волос не такой, какой мы нашли на расчёске... Есть другая улика: след модной обуви."};
tr[27415] = {H:"Может, грабитель просто завсегдатай клубов?"};
tr[27416] = {OId:401,H:"Хм... Ты прав. Одна из улик, пропуск, указывает на Фан-клуб Сирены в Клубном квартале!"};
tr[27417] = {H:"Выходит, Сирену мог ограбить её фанат?"};
tr[27418] = {OId:402,H:"Что-о-о? Ну нет, мои фанаты никогда бы на такое не пошли!"};
tr[27419] = {OId:401,H:"А я считаю, что эту версию стоит проверить..."};
tr[27420] = {H:"Отправляемся в фан-клуб!"};
tr[27421] = {OId:270,H:"Да пребудет с тобой Сирена всегда и всюду! Чем могу помочь?"};
tr[27422] = {H:"Привет! Я ищу одного фаната Сирены."};
tr[27423] = {OId:270,H:"Могу познакомить! И не с одним, а с тысячей."};
tr[27424] = {H:"Но мне нужен только один. Могу рассказать о его приметах."};
tr[27425] = {OId:270,H:"Хм, хорошо. И кого же ты ищешь?"};
tr[27426] = {H:"Он носит модные кроссовки."};
tr[27427] = {H:"У него пышная причёска."};
tr[27428] = {OId:270,H:"Хм, таких у нас немало. Может, есть ещё какие-то приметы?"};
tr[27429] = {H:"У него маленькие пальцы."};
tr[27430] = {H:"Он любит гамбургеры."};
tr[27431] = {H:"У него неряшливый почерк."};
tr[27432] = {OId:270,H:"Вспомнила! Его имени я не знаю, но помогу тебе составить его портрет."};
tr[27433] = {H:"Круто!"};
tr[27434] = {OId:405,H:"Попался! Мы знаем, это ты похитил вещи Сирены."};
tr[27435] = {OId:404,H:"Ох и не стыдно же тебе!"};
tr[27436] = {OId:405,H:"Да, у нас целый мешок улик на тебя!"};
tr[27437] = {OId:403,H:"Уаа.. Да, я виноват. Я так люблю Сирену, что не смог удержаться..."};
tr[27438] = {OId:404,H:"Ох... Это... так трогательно!"};
tr[27439] = {OId:405,H:"Не смог удержаться и стащил все её вещи?"};
tr[27440] = {OId:403,H:"Совершенно случайно! Сначала я взял зеркальце. Потом расчёску. Потом очки... и понеслось!"};
tr[27441] = {OId:404,H:"Ох! И ведь ещё и разбросал это всюду!"};
tr[27442] = {OId:270,H:"Угу. Мы по всему Шарараму украденное собирали."};
tr[27443] = {OId:403,H:"Я испугался! Мне показалось, что за мной следят агенты. Вот я и побежал, всё растеряв по пути..."};
tr[27444] = {OId:404,H:"Никто ещё не относился к моим вещам так небрежно!"};
tr[27445] = {H:"Кстати. Самое время вспомнить, где ты обронил микрофон Сирены!"};
tr[27446] = {OId:403,H:"Какой микрофон? Я не брал микрофон! Очки брал. Зеркало брал. Микрофон не брал."};
tr[27447] = {OId:404,H:"Как... не брал?"};
tr[27448] = {H:"Хм... Значит, его взял кто-то другой. Выходит, Сирену ограбили дважды!"};
tr[27449] = {OId:403,H:"Ох, я так виноват. Простите что украл вещи. Но... микрофона я даже и не видел."};
tr[27450] = {OId:405,H:"Нам нужно вновь проверить место преступления! Вдруг и вправду есть второй грабитель?"};
tr[27451] = {OId:404,H:"Найдите микрофон, прошу! А тебя, мой фанат, я прощаю!"};
tr[27452] = {H:"Хорошо. Бежим в Дом звёзд."};
tr[27453] = {H:"Я раскрыл ограбление суперзвезды! Приходи в Шарарам и стань детективом!"};
tr[27454] = {H:"Миссия " + "\"" + "Сирена" + "\"" + ""};
tr[27455] = {OId:270,H:"Заходи на наш базар!"};
tr[27456] = {OId:400,H:"Покупай любой товар!"};
tr[27457] = {H:"Туфли " + "\"" + "Султан" + "\"" + ""};
tr[27458] = {H:"Беседка " + "\"" + "Сахара" + "\"" + ""};
tr[27459] = {H:"Очки шейха"};
tr[27460] = {H:"Дворцовый павлин"};
tr[27461] = {H:"Фонтан " + "\"" + "Оазис" + "\"" + ""};
tr[27462] = {H:"Ванна " + "\"" + "Азия" + "\"" + ""};
tr[27463] = {H:"Причёска Джинна"};
tr[27464] = {H:"Аура"};
tr[27465] = {H:"Набор Джинна"};
tr[27466] = {H:"Йожик"};
tr[27467] = {H:"Светильник " + "\"" + "Сила дракона" + "\"" + ""};
tr[27468] = {H:"Фонтан с кувшином"};
tr[27469] = {H:"Рубаха " + "\"" + "Пустынник" + "\"" + ""};
tr[27470] = {H:"Диван " + "\"" + "Инь-Ян" + "\"" + ""};
tr[27471] = {H:"Новый Тадж-Махал"};
tr[27472] = {H:"Стол " + "\"" + "Загадочный" + "\"" + ""};
tr[27473] = {H:"Торшер " + "\"" + "Магический свет" + "\"" + ""};
tr[27474] = {H:"Трон " + "\"" + "Обожаемый" + "\"" + ""};
tr[27475] = {H:"Фонтан изумрудов"};
tr[27476] = {H:"Барабан " + "\"" + "Южный" + "\"" + ""};
tr[27477] = {H:"Ворота " + "\"" + "Азия" + "\"" + ""};
tr[27478] = {H:"Тюрбан " + "\"" + "Сказочный" + "\"" + ""};
tr[27479] = {H:"Восточная лампа"};
tr[27480] = {H:"Скарабей"};
tr[27481] = {H:"Пуфик " + "\"" + "Шахерезада" + "\"" + ""};
tr[27482] = {H:"Восточные сладости"};
tr[27483] = {H:"Статуэтка " + "\"" + "Слон" + "\"" + ""};
tr[27484] = {H:"Еда из клуба"};
tr[27485] = {H:"След модных кроссовок"};
tr[27486] = {H:"Помада Сирены"};
tr[27487] = {H:"Кошелёк Сирены"};
tr[27488] = {H:"Расчёска Сирены"};
tr[27489] = {H:"Пропуск фаната"};
tr[27490] = {H:"Батарейки"};
tr[27491] = {H:"3 Батарейки"};
tr[27492] = {H:"5 Батареек"};
tr[27493] = {H:"{0}. Ищи на личной карточке."};
tr[27494] = {H:"Дом " + "\"" + "Дракон" + "\"" + " с мебелью"};
tr[27495] = {H:"Магия фанатов"};
tr[27496] = {H:"Магия фанатов|Получи эту способность у лемура в Каньоне|Ты можешь призывать своих фанатов ещё дней:{0}|Ты можешь призывать своих фанатов всегда!"};
tr[27497] = {H:"Царская чалма"};
tr[27498] = {H:"Царский кафтан"};
tr[27499] = {H:"Тигрёнок"};
tr[27500] = {H:"Восточный костюм"};
tr[27501] = {H:"Кубок пилота ковра-самолёта|За победу в соревнованиях Джинна!"};
tr[27502] = {H:"Кубок любителя сладостей|За победу в соревнованиях Джинна!"};
tr[27503] = {H:"Домик " + "\"" + "Масарканд" + "\"" + ""};
tr[27504] = {H:"Лавка сладостей"};
tr[27505] = {H:"Анализатор"};
tr[27506] = {H:"Доска с уликами"};
tr[27507] = {H:"Микроскоп"};
tr[27508] = {H:"Именная табличка"};
tr[27509] = {H:"Набор мебели " + "\"" + "Детектив" + "\"" + ""};
tr[27510] = {OId:402,H:"Кликни на локатор, чтобы искать улики!"};
tr[27511] = {H:"ОК!"};
tr[27512] = {OId:270,H:"Шах-ма-ты... Хм, кажется, раньше я знал, что это. А теперь забыл..."};
tr[27513] = {H:"Лосяшик, миленький, не переживай, я помогу тебе всё вспомнить! "};
tr[27514] = {OId:270,H:"О, привет, как дела?"};
tr[27515] = {H:"Привет, Эллис! У меня всё хорошо. А вот ты, мне сказали, разучилась на шпагат садиться?"};
tr[27516] = {OId:270,H:"Шпагат... фрегат... салат... Ты о чём вообще?"};
tr[27517] = {H:"Так, Эллис, возьми себя в руки! Тебе на соревнования по гимнастике ехать! Я помогу тебе всё вспомнить."};
tr[27518] = {OId:270,H:"Привет! Не знаешь, что за штука у меня в руке?"};
tr[27519] = {H:"Ну ты даёшь! Это же кирка, она помогает лазить по скалам. "};
tr[27520] = {OId:270,H:"Лазить по скалам - какое странное занятие!"};
tr[27521] = {H:"Сумрак, ты же знаменитый скалолаз! Не волнуйся, я помогу тебе всё вспомнить! "};
tr[27522] = {OId:270,H:"Мне сказали, что я должен этой палкой толкать этот камень."};
tr[27523] = {H:"Шеф, ну какие палка и камень?! Это же клюшка, а это шайба! "};
tr[27524] = {OId:270,H:"Какие-то непонятные слова ты говоришь..."};
tr[27525] = {H:"Да уж, придётся помочь тебе вспомнить хоккей! "};
tr[27526] = {H:"Я расколдовал спортсменов! А ты так умеешь? Скорее в Шарарам"};
tr[27527] = {H:"Синие очки-жалюзи"};
tr[27528] = {H:"Мой лорд! Стань предводителем рыцарского войска. Защити нашу крепость и захвати крепости противников."};
tr[27529] = {H:"смотреть подарки"};
tr[27530] = {H:"Рыцарская битва"};
tr[27531] = {OId:270,H:"Найди в Шарараме Смешариков в масках и примерь с ними разные образы!"};
tr[27532] = {OId:270,H:"Сначала поговори с нами!"};
tr[27533] = {OId:270,H:"Плыви на Остров Невезения на лодке!"};
tr[27534] = {OId:270,H:"Привет, кролик... Эта Тоска нас так расстроила, что мы не можем её прогнать. Попробуй ты..."};
tr[27535] = {OId:411,H:"Ууу-ууу... Хочешь поунывать со мной? Присаживайся и ничего не делай."};
tr[27536] = {OId:270,H:"Найди Улыбашку в лабиринте!"};
tr[27537] = {OId:413,H:"Найди 6 осколков радости в лабиринте!"};
tr[27538] = {OId:270,H:"Помоги Улыбашке одолеть Тоску!"};
tr[27539] = {OId:270,H:"А у нас маскарад! Отгадай загадку: кто выходит очень рано на защиту Шарарама?"};
tr[27540] = {H:"Шарри Коттер"};
tr[27541] = {H:"Шеф"};
tr[27542] = {H:"Сяо Мяо"};
tr[27543] = {OId:270,H:"Упс! Ответ неверный! Попробуй снова."};
tr[27544] = {H:"Хорошо!"};
tr[27545] = {OId:270,H:"Верно! Надень маску Шефа и кликни на меня снова! "};
tr[27546] = {H:"Ну и затейник ты! Хорошо, надену маску."};
tr[27547] = {OId:270,H:"А у нас маскарад! Отгадай загадку: кто умеет колдовать, чудесами удивлять?"};
tr[27548] = {H:"Сяо Мяо."};
tr[27549] = {H:"Шеф."};
tr[27550] = {H:"Шарри Коттер."};
tr[27551] = {OId:270,H:"Упс! Ответ неверный! Попробуй снова."};
tr[27552] = {H:"Хорошо!"};
tr[27553] = {OId:270,H:"Верно! Надень маску Шарри Коттера и кликни на меня снова! "};
tr[27554] = {H:"Ну и затейник ты! Хорошо, надену маску."};
tr[27555] = {OId:270,H:"А у нас маскарад! Отгадай загадку: кто к нам по морю приплыл и сокровища зарыл?"};
tr[27556] = {H:"Одноглазый Джим."};
tr[27557] = {H:"Сяо Мяо."};
tr[27558] = {H:"Шеф."};
tr[27559] = {OId:270,H:"Упс! Ответ неверный! Попробуй снова."};
tr[27560] = {H:"Хорошо!"};
tr[27561] = {OId:270,H:"Верно! Надень маску Одноглазого Джима и кликни на меня снова! "};
tr[27562] = {H:"Ну и затейник ты! Хорошо, надену маску."};
tr[27563] = {OId:270,H:"А у нас маскарад! Отгадай загадку: кто приехал к нам с востока и поёт на сцене много?"};
tr[27564] = {H:"Одноглазый Джим"};
tr[27565] = {H:"Сяо Мяо"};
tr[27566] = {H:"Шарри Коттер"};
tr[27567] = {OId:270,H:"Упс! Ответ неверный! Попробуй снова."};
tr[27568] = {H:"Хорошо!"};
tr[27569] = {OId:270,H:"Верно! Надень маску Сяо Мяо и кликни на меня снова! "};
tr[27570] = {H:"Ну и затейница ты! Хорошо, надену маску."};
tr[27571] = {OId:408,H:"Ёлки-иголки, ты примерил столько разных образов на нашем маскараде!"};
tr[27572] = {OId:409,H:"Хотя... Есть парочка образов, которых у тебя ещё не было! Хи-хи..."};
tr[27573] = {H:"Ну и намёки! Образ механика Яши?"};
tr[27574] = {H:"Образ Совуньи? Её костюм я ещё не надевал."};
tr[27575] = {OId:408,H:"Почти... почти угадал!  Может, нарядишься в мой костюм? Или Нюшин?"};
tr[27576] = {OId:409,H:"Да-да! И на маскараде будет много-много Нюш и Крошей!"};
tr[27577] = {H:"Много Нюш и Крошей это хорошо. Но как же торт?"};
tr[27578] = {OId:408,H:"Точно! Пока Жозе Эклер готовит торт, возьми с вешалки наши костюмы и надень!"};
tr[27579] = {OId:409,H:"А потом кликни на нас снова, чтобы начать праздник Крошей и Нюш!"};
tr[27580] = {H:"Класс!"};
tr[27581] = {OId:410,H:"Ох... Иноземцы хотят, чтобы я  отправился на Остров Невезения, но у меня..."};
tr[27582] = {H:"... но мы так объелись торта, что..."};
tr[27583] = {H:"...начнётся морская болезнь?"};
tr[27584] = {OId:410,H:"Угу... Зря я съел так много торта. Как же быть?"};
tr[27585] = {H:"Я готов! Отправляемся!"};
tr[27586] = {OId:270,H:"Хм... Я знаю ответ!"};
tr[27587] = {H:"А-то я думал, зачем ты здесь, Умникус. Каков твой ответ?"};
tr[27588] = {OId:270,H:"Я превращу тебя в Кроша! Ты справишься - тебе ведь уже довелось побывать в разных ролях на маскараде?"};
tr[27589] = {H:"О! Я мастер перевоплощений!"};
tr[27590] = {OId:270,H:"Здорово! Ты готов отправиться на остров Невезения и победить Тоску?"};
tr[27591] = {H:"Я готов! Отправляемся!"};
tr[27592] = {OId:270,H:"Ох... Давным-давно у нашего народа был вожак: его звали Улыбашка, и он всех веселил. Но однажды он стал грустным!"};
tr[27593] = {H:"Что же его расстроило?"};
tr[27594] = {OId:270,H:"Это осталось загадкой... Он спрятался в лабиринте, и никто так и не смог его найти!"};
tr[27595] = {H:"Ну и ладно! Давайте я буду вас веселить."};
tr[27596] = {OId:270,H:"Увы... Улыбашка унёс нашу радость в лабиринт. Нас теперь ничто не развеселит."};
tr[27597] = {H:"Я его найду! Меня ничто не расстроит. Даже ваши мордашки!"};
tr[27598] = {OId:270,H:"Спасибо! Возле входа в лабиринт стоит карта - она поможет тебе найти Улыбашку!"};
tr[27599] = {H:"Хорошо! Отправляюсь на поиски!"};
tr[27600] = {OId:412,H:"Ох, это забытое чувство лёгкой радости! Спасибо, кролик!"};
tr[27601] = {H:"Привет, Улыбашка! Почему ты спрятался здесь?"};
tr[27602] = {OId:412,H:"О, это печально: однажды мне на голову упало яблоко. От этого я потерял память... И расстроился."};
tr[27603] = {H:"И забыл, как всех веселить?"};
tr[27604] = {OId:412,H:"Забыл, как веселить. Забыл, как отсюда выбраться. Забыл, куда дел всю радость нашего острова."};
tr[27605] = {H:"Ну и дела! Я знаю, где выход - идём за мной."};
tr[27606] = {OId:412,H:"Погоди. Сначала нужно найти радость. Я потерял 6 осколков где-то здесь - в лабиринте..."};
tr[27607] = {H:"Хорошо. Пойду поищу. А ты сиди здесь - а то вдруг снова потеряешься."};
tr[27608] = {OId:414,H:"Я нашёл много странных камней, но осколок радости среди них только один. Поможешь его оживить?"};
tr[27609] = {H:"Конечно!"};
tr[27610] = {OId:414,H:"Подумай о чём-нибудь вкусном, чтобы оживить осколок. Скажи, какое блюдо украсит любой праздник?"};
tr[27611] = {H:"Перловая каша."};
tr[27612] = {H:"Большой и красивый торт."};
tr[27613] = {H:"Квашеная капуста."};
tr[27614] = {OId:414,H:"Упс! Не вышло. Попробуй снова."};
tr[27615] = {H:"Хорошо, попробую."};
tr[27616] = {OId:414,H:"Невероятно! Осколок засиял. Держи его и не забудь про другие, если ещё не нашёл."};
tr[27617] = {H:"Спасибо!"};
tr[27618] = {OId:270,H:"Я тебя не узнаю - минуту назад ты выглядел совсем иначе!"};
tr[27619] = {H:"Ой! Кажется, заклятие Умникуса потеряло силу!"};
tr[27620] = {OId:270,H:"И что, все жители вашей планеты вот так вот туда-сюда превращаются?"};
tr[27621] = {H:"Когда как. Вот Крош однажды в робота превратился."};
tr[27622] = {OId:270,H:" Что ж, теперь мы знаем, как выглядит наш герой. Оказывается, он не кролик. Он - это ты!"};
tr[27623] = {H:"О! Не стоит благодарностей. Давайте просто отпразднуем!"};
tr[27624] = {OId:270,H:" Точно! Праздник! Скоро мы развеселим всех на нашем острове! А ты держи свою награду!"};
tr[27625] = {H:"О, какую?"};
tr[27626] = {H:"Ревизунья"};
tr[27627] = {H:"Хо-хо! Ты знаешь, как сильно я люблю порядок. Давай проверим Шарарам на чистоту?"};
tr[27628] = {H:"Сначала посетим Главную площадь. Приходи туда."};
tr[27629] = {H:"Всё ли чисто у Крошек? Сыграй с ними в Детском саду и заработай {0} Смешинок."};
tr[27630] = {H:"Проверь ткани в Доме мод. Сыграй в игру " + "\"" + "Модельер" + "\"" + "."};
tr[27631] = {H:"Удивительно! На Главной площади всё отлично - как будто кто-то готовился к нашей проверке!"};
tr[27632] = {H:"Ревизунья"};
tr[27633] = {H:"Давай отправимся в клубы. Интересно, какую оценку мы им поставим?"};
tr[27634] = {H:"Узнай, что нового в клубах. Собери {0} флаерса в Клубном квартале."};
tr[27635] = {H:"Посети {0} клубов"};
tr[27636] = {H:"А свежа ли еда? Найди в меню одного из клубов салат " + "\"" + "Оливье" + "\"" + " и купи."};
tr[27637] = {H:"Хо, я нашла в клубах парочку недочётов. А вот с кухней там проблем нет! Ставлю четвёрку!"};
tr[27638] = {H:"Ревизунья"};
tr[27639] = {H:"Так-так-так, а что там у нас с аттракционами?"};
tr[27640] = {H:"Приходи в Парк аттракционов."};
tr[27641] = {H:"Испытаем стадион. Сыграй в Футбол."};
tr[27642] = {H:"Проверим игровую зону. Выиграй в Скачки."};
tr[27643] = {H:"Ух, в парке так весело! Ставлю 5. Держи Смешинки за помощь."};
tr[27644] = {H:"Ревизунья"};
tr[27645] = {H:"Интересно, всё ли в порядке в Ромашковой долине?"};
tr[27646] = {H:"Приходи в Ромашковую долину."};
tr[27647] = {H:"Посмотрим, нет ли чего вредного в грушах. Собери {0} штук."};
tr[27648] = {H:"Проверь мастерскую Пина - помоги ему починить Вечный двигатель."};
tr[27649] = {H:"Пину стоит уделять больше внимания чистоте в мастерской. Но мою проверку Ромашковая долина всё равно прошла!"};
tr[27650] = {H:"Ревизунья"};
tr[27651] = {H:"Ох, чуть не забыла про самое главное! Давай устроим проверку в кафе."};
