tr[27710] = {OId:270,H:"Упс! Ответ неверный! Попробуй снова. А про Марараша мне кто-то рассказывал кое-что интересное. Только вот не помню кто.  Поспрашивай у других маскарадников."};
tr[27711] = {OId:270,H:"Упс! Ответ неверный! Попробуй снова. А про Марараша у меня есть забавная история. Совунья рассказывала, что то ли  на его имя отзывается одна из пальм в Шарараме, то ли ей голову напекло. "};
tr[27712] = {H:"марараш|марараш ш"};
tr[27713] = {OId:412,H:"Я вас внимательно слушаю!"};
tr[27714] = {H:"Марараш? Ты ли это?"};
tr[27715] = {OId:412,H:"Конечно, это я. Видишь у меня и  листья как у Марараша, и характер такой же - дерево деревом."};
tr[27716] = {H:"Ну не знаю. Похож конечно, но на пальму ты больше похож."};
tr[27717] = {OId:412,H:"Ох ты ж неприятность какая-то. Моя кадушка стоит рядом с рентгеновским аппаратом, так что у меня от радиации все реальности перемешались."};
tr[27718] = {H:"Так может тебе в сценаристы Шарарама податься?"};
tr[27719] = {OId:412,H:"Да нет, мне и здесь комфортно. Но зато я знаю одну тайну про Марараша."};
tr[27720] = {H:"Ну-ка , ну-ка?"};
tr[27721] = {OId:412,H:"Я не просто пальма. Я Сфинкс Египетский, и ты должен отгадать мою загадку, прежде чем узнаешь тайну!  Ой, похоже опять началось .."};
tr[27722] = {H:"Ммм.. Хорошо, Сфинкс древовидный, давай свою загадку."};
tr[27723] = {OId:412,H:"Кто утром ходит на четырех ногах, днем — на двух, а вечером — на трех?"};
tr[27724] = {H:"Квазипеременчивый многоног?"};
tr[27725] = {H:"Человек? В младенчестве ползает на четвереньках, потом ходит на двух, а в старости с палочкой? Хотя вряд ли. Это Кактус!"};
tr[27726] = {H:"Это Стул! Его днем сломали, а вечером неудачно починили."};
tr[27727] = {OId:412,H:"Ахххаха. Ты не угадал ,и никогда теперь не узнаешь что Марараш любит квашеную капусту!"};
tr[27728] = {H:"Спасибо великий Сфинкс! Как нибудь зайду еще поболтать."};
tr[27729] = {OId:412,H:"Ага, и вам приятного аппетита!"};
tr[27730] = {H:";-)"};
tr[27731] = {OId:414,H:"Бегал тут по лабиринту один любитель квашеной капусты. Даже вещь свою потерял в лабиринте. Я отмечу место в твоей копии карты."};
