tr[28109] = {OId:270,H:"Хм, машина сломалась. Видишь ли, я думал, это мы улетим в параллельный мир..."};
tr[28110] = {H:"Но вместо этого параллельный мир прилетел к нам?"};
tr[28111] = {OId:270,H:"Именно! Ты видел это? В Шарарам попали даже наши двойники из параллельного измерения."};
tr[28112] = {H:"Круто! И что же нам с ними делать?"};
tr[28113] = {OId:270,H:"Нужно найти их в Шарараме и вернуть в свой мир! Кто знает, вдруг они злодеи?"};
tr[28114] = {H:"Ок. Пойду искать двойников Смешариков - гостей из другого измерения."};
tr[28115] = {OId:270,H:"Отправляйся в параллельный мир - кликай на машину!"};
tr[28116] = {OId:270,H:"Найди двойников Смешариков в Шарараме!"};
tr[28117] = {H:"Варенье|Варенье сварят через {0} мин."};
tr[28118] = {OId:270,H:"Хех! Жаль, что мы улетаем в свой Шарарам - так хочется ещё у вас пошалить!"};
tr[28119] = {OId:270,H:"Я понял, почему двойники себя так ведут! Их мир - полная противоположность нашему."};
tr[28120] = {H:"Значит, в параллельном мире все - хулиганы?"};
tr[28121] = {OId:270,H:"А хулиганы - наоборот добряки. Давай же скорее вернём всё на свои места."};
tr[28122] = {H:"А как мы это сделаем?"};
tr[28123] = {OId:270,H:"Я починил машину. Кликай на неё, чтобы отправить хулиганов на родину."};
tr[28124] = {H:"Хорошо! Давай сделаем это."};
tr[28125] = {OId:270,H:"Кликни на машину, чтобы отправить двойников обратно в параллельный мир!"};
