tr[28135] = {H:"СмеШутка " + "\"" + "Пончик" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращать Смешариков в пончики ещё дней: {0}|Ты можешь превращать Смешариков в пончики всегда!"};
tr[28136] = {OId:270,H:"Ох, ну и обижена я на тебя! Как ты мог так поступить!? Ну как?!"};
tr[28137] = {H:"Эллис, ты о чём? Не видела случайно тут двойников Смешариков?"};
tr[28138] = {OId:270,H:"Вот ничего я тебе и не скажу, пока не извинишься!"};
tr[28139] = {H:"Но... Эллис..."};
tr[28140] = {OId:270,H:"Вот ничего я тебе и не скажу, пока не извинишься!"};
tr[28141] = {OId:270,H:"Ну вот! Значит, ты вернулся, чтобы снова мне напакостить?"};
tr[28142] = {H:"Зачем? Ты же мой друг. Не видел здесь двойников Смешариков?"};
tr[28143] = {OId:270,H:"Видел - не видел. Я на тебя обижен. Ничего не скажу."};
tr[28144] = {H:"Странно..."};
tr[28145] = {OId:270,H:"Я на тебя обижен. Ничего не скажу."};
tr[28146] = {OId:430,H:"Ха! Кажется, я разгадал, чей двойник остался в Шарараме!"};
tr[28147] = {H:"Двойник Копатыча?"};
tr[28148] = {H:"Двойник Умникуса?"};
tr[28149] = {H:"Двойник Кроша?"};
tr[28150] = {OId:430,H:"Нет! Это... твой двойник!"};
tr[28151] = {H:"Как!? У меня тоже есть двойник?"};
tr[28152] = {OId:430,H:"Конечно! Он гуляет по Шарараму и хулиганит."};
tr[28153] = {OId:431,H:"Ахах! А Смешарики, которым он напакостил, думают, что виноват ты!"};
tr[28154] = {H:"Я?! Ну я покажу этому этому двойнику."};
tr[28155] = {OId:430,H:"Узнай у Эллис и Стефана о своём двойнике, чтобы найти его."};
tr[28156] = {OId:431,H:"А чтобы Смешарики захотели с тобой говорить, возьми эту маску."};
tr[28157] = {H:"Какую?"};
tr[28158] = {OId:430,H:"Узнай у Эллис и Стефана, где твой двойник."};
tr[28159] = {H:"Маска Макса"};
tr[28160] = {H:"Аксессуар " + "\"" + "Букет зябрийских пельменей" + "\"" + ""};
tr[28161] = {OId:270,H:"Ха! Поглядите - да он же вылитый ты!"};
tr[28162] = {OId:427,H:"Ну вот, попался... А я так хотел ваш катер потопить!"};
tr[28163] = {H:"И почему тебя вечно тянет на такие странные шалости?"};
tr[28164] = {OId:427,H:"Да у нас в Шарараме все только и делают, что проказничают!"};
tr[28165] = {H:"Это в вашем " + "\"" + "параллельном" + "\"" + " Шарараме. А в нашем все добрые!"};
tr[28166] = {OId:270,H:"Значит, моя догадка верна! Их Шарарам и вправду полная противоположность нашему."};
tr[28167] = {OId:427,H:"Хм... А у вас разве Злобикус не победил Умникуса?"};
tr[28168] = {H:"Нет. У нас всё наоборот! Вот, почему вы хулиганите, я понял!"};
tr[28169] = {OId:270,H:"Точно! Если бы в их мире победил Умникус, то всё было бы хорошо!"};
tr[28170] = {OId:427,H:"Оу... А вы можете помочь нашему Умникусу победить Злобикуса?"};
tr[28171] = {H:"Конечно, можем! Спросим совета у нашего Умникуса в Школе магов."};
tr[28172] = {OId:428,H:"Хо, не думал, что когда-нибудь встречусь с магом!"};
tr[28173] = {OId:429,H:"Приятно познакомиться, безумный учёный Док!"};
tr[28174] = {H:"Маги круче всех!"};
tr[28175] = {H:"Наука спасёт мир!"};
tr[28176] = {OId:428,H:"Да, то-то мы теперь спасаем " + "\"" + "крутых" + "\"" + " магов с помощью науки!"};
tr[28177] = {OId:429,H:"А что собственно происходит? Кто кого спасает?"};
tr[28178] = {H:"Умникус, в параллельном измерении ты проиграл Злобикусу!"};
tr[28179] = {OId:428,H:"Вот, моя школа!"};
tr[28180] = {OId:429,H:"Хорошо, пусть наука спасает. А зачем же вы тогда пришли ко мне?"};
tr[28181] = {OId:428,H:"Мы хотим узнать, как помочь твоему двойнику - параллельному Умникусу?"};
tr[28182] = {OId:429,H:"Что ж, если Злобикус его одолел, значит, тот Умникус потерял свой волшебный шар!"};
tr[28183] = {H:"А если мы дадим тому Умникусу другой такой шар, он сможет победить?"};
tr[28184] = {OId:428,H:"Это же гениально! Умникус, я могу создать копию твоего шара и отправить её в параллельный мир."};
tr[28185] = {OId:429,H:"Создать копию? Хорошо, что Злобикус в нашем мире до этого не додумался!"};
tr[28186] = {H:"Док, а как мы создадим копию волшебного шара?"};
tr[28187] = {OId:428,H:"Нужно создать квантовые рецепторы и направить корпускулярную волну в кварковый преобразователь."};
tr[28188] = {OId:429,H:"Хм... Док просто хочет сказать, что надо немного поколдовать."};
tr[28189] = {H:"Хорошо. Давайте начнём."};
