tr[28229] = {H:"Я получил пиратские сокровища с берегов Лимпопо! Тоже хочешь? Скорее в Шарарам!"};
tr[28230] = {H:"фон Натика"};
tr[28231] = {OId:270,H:"Спасибо! Теперь найди следующую Мармеладку-сыщика и помоги ей."};
