tr[28240] = {H:"Фон " + "\"" + "Вкус цвета" + "\"" + ""};
tr[28241] = {H:"Шарафон " + "\"" + "Кленовый лист" + "\"" + ""};
tr[28242] = {H:"Кровать " + "\"" + "Яхта" + "\"" + ""};
tr[28243] = {H:"Шапка " + "\"" + "Тёплая осень" + "\"" + ""};
