tr[28247] = {H:"Домик " + "\"" + "Космический лайнер" + "\"" + ""};
tr[28248] = {H:"Второе солнце"};
tr[28249] = {H:"Давай сделаем искусственное солнце, чтобы в Шарараме всегда было ясно и тепло! Сначала поищем что-то круглое..."};
tr[28250] = {H:"Может, подойдут жемчужины? Собери {0} штуки на Пляже."};
tr[28251] = {H:"Или лучше взять бусину? Сыграй в Секретики на Пляже."};
tr[28252] = {H:"А, может лучше мяч? Сыграй в футбол в Парке аттракционов."};
tr[28253] = {H:"Я понял, что футбольный мяч лучше всего подойдёт для солнца. Спасибо за помощь!"};
tr[28254] = {H:"Второе солнце"};
tr[28255] = {H:"Как же мы наполним наше солнце теплом? О, у меня есть одна идея!"};
tr[28256] = {H:"Отправляйся за теплом в Египет."};
tr[28257] = {H:"Утоли жажду. Собери {0} кокосов."};
tr[28258] = {H:"Сыграй в игру богини солнца Сехмет и заработай {0} Смешинок за 1 раз."};
tr[28259] = {H:"Теперь у нас есть тепло для солнца! Лови Смешинки!"};
tr[28260] = {H:"Второе солнце"};
tr[28261] = {H:"А ещё нашему солнцу нужен свет!"};
tr[28262] = {H:"Приходи в Клубный квартал."};
tr[28263] = {H:"Зарядим солнце светом софитов. Посети {0} клубов."};
tr[28264] = {H:"А ещё можно добыть свет из Позитивной энергии. Собери {0} штуки в Шарараме."};
tr[28265] = {H:"Так. Солнце есть. Тепло есть. Свет есть. Держи награду."};
tr[28266] = {H:"Второе солнце"};
tr[28267] = {H:"Ура, теперь мы можем запустить наше солнце в небо! Подготовься к полёту в Космос."};
tr[28268] = {H:"Перед полётом проверь здоровье. Сделай рентген в Больничке."};
tr[28269] = {H:"Сыграй в Метеоритный тренажёр на Космодроме и заработай {0} Смешинок."};
tr[28270] = {H:"Отправляйся на Космостанцию."};
tr[28271] = {H:"Ура, мы отправили наше солнце в космос на ракете. Теперь оно будет светить Шарараму!"};
tr[28272] = {H:"Второе солнце"};
tr[28273] = {H:"Мы сделали солнце, но забыли разогнать облака. Поможешь?"};
tr[28274] = {H:"Брось в небо {0} помидоров!"};
tr[28275] = {H:"Напиши в общий чат: Разгоняйте облака - кидайте в небо помидоры!"};
tr[28276] = {H:"Прокатись с ветерком на катере в Порту и заработай {0} Смешинок за 1 раз."};
tr[28277] = {H:"Погода солнечная! Теперь Смешарики смогут загорать круглый год. А ты заслужил награду!"};
tr[28278] = {H:"Из чего сделать солнце?"};
tr[28279] = {H:"Где взять тепло?"};
tr[28280] = {H:"Где взять свет?"};
tr[28281] = {H:"Солнце, на старт!"};
tr[28282] = {H:"Разгони тучи!"};
tr[28283] = {H:"Кликни на карту Шарарама, открой вкладку " + "\"" + "Карта космоса" + "\"" + " и перейди в нужное место."};
tr[28284] = {OId:270,H:"Я уже забронировала номер: заходи в отель и попроси Эллис поселить тебя!"};
tr[28285] = {OId:432,H:"Портье поможет тебе поднять вещи. Кликни на него."};
tr[28286] = {OId:270,H:"Устрой проверку в отеле " + "\"" + "Эллисон" + "\"" + ""};
tr[28287] = {OId:432,H:"Кликни на лифт, чтобы отправиться в свой номер."};
tr[28288] = {OId:432,H:"Кликни на коробку, чтобы собрать ловушки."};
tr[28289] = {OId:432,H:"Кликни на телефон, чтобы узнать, сработали ли ловушки."};
tr[28290] = {OId:432,H:"Кликни на лифт, чтобы подняться в номер 1408 и посмотреть, кто в ловушке!"};
tr[28291] = {OId:270,H:"Ооооо... ОНО там - в ловушке! Скорее загляни в неё."};
tr[28292] = {OId:432,H:"Кликни на журнал и узнай, кто принёс в отель яйцо грифона."};
tr[28293] = {OId:270,H:"Пчхи! Не бойся, я слежу за грифоном. А грифон следит за мной."};
tr[28294] = {OId:432,H:"Узнай у Охотника в Дремучем лесу, где искать родителей грифончика."};
tr[28295] = {OId:432,H:"Ну как? Нашёл родителей грифончика? Охотник ждёт тебя в лесу."};
tr[28296] = {OId:270,H:"Я вот вертолёт приготовил. Он вас с грифончиком отвезёт к его родителям."};
tr[28297] = {OId:432,H:"Добро пожаловать в отель " + "\"" + "Эллисон" + "\"" + "! Вы бронировали?"};
tr[28298] = {H:"Да, да! Я бронировал. Вот мои документы."};
tr[28299] = {OId:432,H:"Итак, ваш номер-люкс готов."};
tr[28300] = {H:"Класс! А как мне в него попасть?"};
tr[28301] = {OId:432,H:"Пожалуйста, вот ключи от вашего номера, сейфа, ванной комнаты, балкона и шкафчиков. Приятно провести время!"};
tr[28302] = {OId:270,H:"Ммм... Так много ключей?"};
tr[28303] = {OId:432,H:"Здравствуйте, у вас всё хорошо?"};
tr[28304] = {H:"Нет, Эллис. Я недоволен - в отеле сплошной беспорядок и неразбериха!"};
tr[28305] = {OId:432,H:"Да..? А что случилось? Может, вам показалось?"};
tr[28306] = {H:"По ночам в номере кто-то воет и пищит."};
tr[28307] = {H:"Мою еду кто-то съел до меня!"};
tr[28308] = {H:"В номере всюду пух и перья."};
tr[28309] = {H:"Кто-то крадёт вещи из номера."};
tr[28310] = {OId:432,H:"Ох... И вправду. Все постояльцы жалуются на это и покидают номера. Отель на грани разорения!"};
tr[28311] = {H:"Эллис, может, вам просто нужно взять и исправиться."};
tr[28312] = {OId:432,H:"Дело не в этом. Мне кажется в отеле КТО-ТО завёлся..."};
tr[28313] = {H:"КТО-ТО?"};
tr[28314] = {OId:432,H:"Да... Только, тсс... Тот, кто устраивает беспорядки и шумит по ночам. Знаешь, кто бы это мог быть?"};
tr[28315] = {H:"Это призрак!"};
tr[28316] = {H:"Это барабашка!"};
tr[28317] = {H:"Может, это гигантские злые тараканы?"};
tr[28318] = {OId:432,H:"Какая-то нечисть? Возможно. Помоги её найти и прогнать. Иначе в мой отель никто больше не придёт."};
tr[28319] = {H:"Окей, я найду нечисть! Для начала соорудим ловушки здесь в отеле."};
tr[28320] = {OId:433,H:"Уаааа... Чудищеее.... ОНО здесь!!!"};
tr[28321] = {H:"Ой-ой! Вам кто-то попался? Скажите, в каком номере?!"};
tr[28322] = {OId:433,H:"Уаааа.... Номер 1408, приходите скорее, ОНО в ловушке! Ааа!"};
tr[28323] = {H:"Уже бегу к лифту и еду к вам!"};
tr[28324] = {OId:434,H:"Ой, какое прекрасное создание!"};
tr[28325] = {OId:270,H:"Ох, ну и чудище... Фу."};
tr[28326] = {H:"Интересно, откуда у вас в отеле грифон?"};
tr[28327] = {OId:434,H:"Не припомню гостей с животными..."};
tr[28328] = {OId:270,H:"И я..."};
tr[28329] = {H:"Ну должна же быть хоть какая-то зацепка?"};
tr[28330] = {OId:434,H:"Да... нужно разыскать родителей грифончика - он же совсем маленький."};
tr[28331] = {OId:270,H:"Постой-ка... А грифоны, они откуда берутся? Из яиц? Я тут недавно огромную скорлупу в номере нашла."};
tr[28332] = {H:"Фёкла, гениально! А в каком номере это было?"};
tr[28333] = {OId:270,H:"Кажется, в 323-м неделю назад. На ресепшене можешь проверить журналы и узнать, кто тогда жил в номере."};
tr[28334] = {H:"Отлично! Бегу на ресепшен, а вы пока грифончика покормите."};
tr[28335] = {OId:270,H:"Привет! Ты пришёл, так сказать, посмотреть на мои, так сказать, трофеи?"};
tr[28336] = {H:"Нет, у меня вопрос похитрее: Василич, не ты ли яйцо грифона в отеле потерял?"};
tr[28337] = {OId:270,H:"В отеле? Так вон оно где... А я думал, в больничке его обронил..."};
tr[28338] = {H:"Вот-вот! А грифончик-то вылупился. И теперь мы ищем его родителей..."};
tr[28339] = {OId:270,H:"Ох, помню: направляю я ружьё на гнездо грифона и жму на курок... чтобы фотографию сделать, я ж фотоохотник..."};
tr[28340] = {H:"И..?"};
tr[28341] = {OId:270,H:"Дело было в горах... А там ветра такие - вот меня и сдуло. И яйцо унесло, еле успел подхватить. Так и рухнули мы вдвоём вниз с горы."};
tr[28342] = {H:"А дальше?"};
tr[28343] = {OId:270,H:"Я потерял яйцо. Но ты-то нашёл его. Можно теперь грифончика родителям вернуть. Только с картами сверюсь..."};
tr[28344] = {H:"Класс!"};
tr[28345] = {H:"Проявитель|Проявитель доставят через {0} мин."};
tr[28346] = {H:"Я - спаситель грифонов! А кем станешь в Шарараме ты? Скорее в игру!"};
tr[28347] = {H:"Спутник " + "\"" + "Далматинец-девочка" + "\"" + ""};
tr[28348] = {H:"Спутник " + "\"" + "Снежик" + "\"" + ""};
tr[28349] = {OId:270,H:"Научи мумию танцевать здесь, а в Дремучем лесу приготовь праздничные напитки."};
tr[28350] = {H:"Мумия в домик"};
tr[28351] = {H:"Кресло " + "\"" + "Тёмный Дракула" + "\"" + ""};
tr[28352] = {H:"Кресло " + "\"" + "Алый Дракула" + "\"" + ""};
tr[28353] = {H:"Шапка " + "\"" + "Ночной страж" + "\"" + ""};
tr[28354] = {H:"Чёрные ботинки"};
tr[28355] = {H:" Костюм " + "\"" + "Тренер грифонов" + "\"" + ""};
tr[28356] = {H:"Смайлы " + "\"" + "Страшилы" + "\"" + ""};
tr[28357] = {H:"Кресло " + "\"" + "Гостиничное красное" + "\"" + ""};
tr[28358] = {H:"Кресло " + "\"" + "Гостиничное желтое" + "\"" + ""};
tr[28359] = {H:"Набор мебели " + "\"" + "Уютный номер" + "\"" + ""};
tr[28360] = {H:"Стол " + "\"" + "Гостиничный" + "\"" + ""};
tr[28361] = {H:"Стол-паук"};
tr[28362] = {H:"Фон " + "\"" + "Паутина" + "\"" + ""};
tr[28363] = {H:"Мистический пиджак"};
tr[28364] = {H:"Магия " + "\"" + "Чёрная мумия" + "\"" + ""};
tr[28365] = {H:"Уже в твоём гардеробе."};
tr[28366] = {H:"Кликни на значок " + "\"" + "Эмоции" + "\"" + ". Смайлы на 7 дней."};
tr[28367] = {H:"Ищи в гардеробе в разделе " + "\"" + "Фоны" + "\"" + "."};
tr[28368] = {H:"Кликни на волшебную палочку и превращайся 7 дней."};
tr[28369] = {H:"Магия " + "\"" + "Чёрная мумия" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в мумию ещё дней: {0}|Ты можешь превращаться в мумию всегда!"};
tr[28370] = {OId:270,H:"Хе-хе-хе! Смотри, сколько подарков попалось в мою сеть! Хочешь? Забирай любой!"};
tr[28371] = {H:"Ободок " + "\"" + "Тыквочки" + "\"" + ""};
tr[28372] = {H:"Клуб " + "\"" + "Театр-Вамп" + "\"" + ""};
tr[28373] = {H:"Смайлы " + "\"" + "Страшилы" + "\"" + " на 7 дней"};
tr[28374] = {H:"Фон " + "\"" + "Паутина" + "\"" + ""};
tr[28375] = {H:"Магия " + "\"" + "Чёрная мумия" + "\"" + " на 7 дней"};
tr[28376] = {H:"30 Смешинок"};
tr[28377] = {H:"50 Смешинок"};
tr[28378] = {H:"Очки " + "\"" + "Затмение" + "\"" + ""};
tr[28379] = {H:"Рояль в домик"};
tr[28380] = {H:"Сумеречный цилиндр"};
tr[28381] = {H:"Сумеречное пальто"};
tr[28382] = {H:"Сумеречные ботинки"};
tr[28383] = {H:"Сумеречный костюм"};
tr[28384] = {H:"Будь страшно модным!|Ищи костюм в своём гардеробе!"};
tr[28385] = {H:"ТыквОчки"};
tr[28386] = {H:"Спутник " + "\"" + "Перчатка" + "\"" + ""};
tr[28387] = {H:"Колдовское зелье"};
tr[28388] = {H:"Магия " + "\"" + "ВампирШоу" + "\"" + ""};
tr[28389] = {H:"Кубок Мумии|За победу на Балу нечисти!"};
tr[28390] = {H:"Кубок зельеварения|За победу на Балу нечисти!"};
tr[28391] = {H:"Магия " + "\"" + "ВампирШоу" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь устраивать шоу ещё дней: {0}|Ты можешь устраивать шоу всегда!"};
tr[28392] = {H:"Ты уверен что хочешь выйти?"};
tr[28393] = {H:"Причёска " + "\"" + "Призрачное утро" + "\"" + ""};
tr[28394] = {H:"Призрачная пальма"};
tr[28395] = {H:"Призрачный мишка"};
tr[28396] = {H:"Призрачный набор"};
tr[28397] = {H:"Фон " + "\"" + "Египетский" + "\"" + ""};
tr[28398] = {H:"Питомцы для Макса"};
tr[28399] = {H:"Привет! Я очень-очень долго просил, и дедушка разрешил мне завести домашних питомцев. Но каких? У тебя есть идеи?"};
tr[28400] = {H:"Приходи в Ромашковую долину."};
tr[28401] = {H:"Напиши {0} сообщений на Шарафон: " + "\"" + "Какие питомцы тебе нравятся?" + "\"" + ""};
tr[28402] = {H:"Может, питомцев рисуют маги? Сыграй в Волшебный карандаш в Школе магов."};
tr[28403] = {H:"Я решил! Хочу себе питомцев-муравьёв. И, может быть, бабочку. И паука!"};
tr[28404] = {H:"Питомцы для Макса"};
tr[28405] = {H:"Я буду питомцем Макса, если он заодно приютит и весь наш муравейник! Поможешь нам собраться вместе?"};
tr[28406] = {H:"Муравьи боятся чудиков и прячутся. Найди в Шарараме {0} чудиков и прогони."};
tr[28407] = {H:"Муравьям нужны запасы. Собери {0} шишек на Снежной горе."};
tr[28408] = {H:"Сыграй в Дары леса и заработай {0} Смешинок за 1 раз."};
tr[28409] = {H:"Класс! Теперь мы всем муравейником пойдём жить к Максу. Лови награду!"};
tr[28410] = {H:"Питомцы для Макса"};
tr[28411] = {H:"Стать питомцем Макса? Ну я даже не знаю... Мне так хочется жить в окружении красоты!"};
tr[28412] = {H:"Приходи в Дом мод."};
tr[28413] = {H:"Подбери Максу стильные наряды. Сыграй в Модельера и заработай {0} Смешинок."};
tr[28414] = {H:"Узнай, как модно обставить домик Макса. Сходи в гости к {0} друзьям."};
tr[28415] = {H:"Да, мне нравится. Теперь и Макс красив, и дом его красив. Так и быть, стану его питомцем."};
tr[28416] = {H:"Питомцы для Макса"};
tr[28417] = {H:"Макс хочет, чтобы я был его питомцем? А он точно меня не испугается? А его друзья? Эх... Паучков ведь никто не любит."};
tr[28418] = {H:"Подари паучку Позитивную энергию. Заработай {0} штук в любой игре."};
tr[28419] = {H:"Устрой паучку выход в свет. Посети {0} клубов."};
tr[28420] = {H:"Ой... А ведь меня даже никто и не испугался, а в клубах я даже потанцевал! Спасибо за помощь - пойду жить к Максу."};
tr[28421] = {H:"Питомцы для Макса"};
tr[28422] = {H:"Ого, теперь у меня полный дом насекомых - дедушка обрадуется! А ты можешь показать, как за ними ухаживать?"};
tr[28423] = {H:"Покажи Максу, что такое забота. Приходи в Детский сад."};
tr[28424] = {H:"Поухаживай за Крошками и заработай {0} Смешинок."};
tr[28425] = {H:"Накорми Смешариков - поработай в Кафе на Пляже."};
tr[28426] = {H:"Глядя на тебя, я понял, как кормить и ухаживать за питомцами! Спасибо!"};
tr[28427] = {H:"Выбираем питомца!"};
tr[28428] = {H:"Муравей Лео"};
