tr[28441] = {H:"Жилетка " + "\"" + "Городской гламур" + "\"" + ""};
tr[28442] = {H:"Сумка " + "\"" + "Городской гламур" + "\"" + ""};
tr[28443] = {H:"Причёска " + "\"" + "Денди" + "\"" + ""};
tr[28444] = {H:"Костюм " + "\"" + "Денди" + "\"" + ""};
tr[28445] = {H:"Очки " + "\"" + "Денди" + "\"" + ""};
tr[28446] = {H:"Йоу, друг! Время обновить гардероб! Кликай на вешалки и выбирай!"};
tr[28447] = {OId:439,H:"Начинай путешествие - кликни на оленя Рудольфа."};
tr[28448] = {OId:440,H:"Я отвезу тебя к нашему поезду с подарками."};
tr[28449] = {H:"к поезду!"};
tr[28450] = {OId:440,H:"Мы в Германии! Поздравь её жителей с Новым годом."};
tr[28451] = {OId:440,H:"Отправляемся в следующую страну! Кликни на поезд!"};
tr[28452] = {OId:440,H:"Мы в Мексике! Поздравь её жителей с Новым годом."};
tr[28453] = {OId:440,H:"Мы в Кении! Поздравь её жителей с Новым годом."};
tr[28454] = {OId:440,H:"Мы в Австралии! Поздравь её жителей с Новым годом."};
tr[28455] = {OId:440,H:"Мы в Индии! Поздравь её жителей с Новым годом."};
tr[28456] = {OId:440,H:"Мы в Китае! Поздравь её жителей с Новым годом."};
tr[28457] = {OId:440,H:"Отправляемся в следующую страну! Кликни на поезд!"};
tr[28458] = {OId:439,H:"С Новым годом! Тебя ждут и в других странах - кликай на поезд!"};
tr[28459] = {OId:440,H:"О нет! Наш поезд сломался и застрял в этой загадочной стране. Поговори с её жителями!"};
tr[28460] = {OId:439,H:"Отдохни, а мы починим поезд! Кликни на дверь и отведай кушанья!"};
tr[28461] = {OId:440,H:"Найди в Шарараме моих брата и сестру!"};
tr[28462] = {OId:440,H:"Аррива! Спасибо за подарки, Дед Мороз! Приготовим на Новый год сказочный буррито?"};
tr[28463] = {OId:440,H:"Аррива! Спасибо за подарки, Снегурочка! Приготовим на Новый год сказочный буррито?"};
tr[28464] = {H:"А что такое буррито?"};
tr[28465] = {H:"Давайте-давайте!"};
tr[28466] = {OId:440,H:"Буррито - самое вкуcное блюдо Мексики! Ароматная лепёшка с корочкой и крутой начинкой."};
tr[28467] = {H:"Ох! Давайте готовить!"};
tr[28468] = {OId:440,H:"Сначала выбери новогоднюю начинку "};
tr[28469] = {H:"Мандарины."};
tr[28470] = {H:"Конфеты."};
tr[28471] = {H:"Кактусы."};
tr[28472] = {H:"Карамельный."};
tr[28473] = {H:"Сливочный."};
tr[28474] = {H:"Ягодный."};
tr[28475] = {OId:440,H:"А теперь выбери соус!"};
tr[28476] = {OId:440,H:"Невероятно! Ты приготовил буррито-хлопушку!"};
tr[28477] = {H:"Класс! А что с ним делать?"};
tr[28478] = {OId:440,H:"Невероятно! Ты приготовил огненное буррито!"};
tr[28479] = {H:"Класс! А что с ним делать?"};
tr[28480] = {OId:440,H:"Невероятно! Ты приготовил буррито-фейерверк!"};
tr[28481] = {H:"Класс! А что с ним делать?"};
tr[28482] = {OId:439,H:"Так-с, так-с, так-с. Привет, Дедушка Мороз! Какой у тебя красивый поезд. И подарков много! Любопытно..."};
tr[28483] = {OId:439,H:"Так-с, так-с, так-с. Привет, Снегурочка! Какой у тебя красивый поезд. И подарков много! Любопытно..."};
tr[28484] = {H:"Так-то оно так. Только поезд сломался, и теперь мы не успеваем развезти всем подарки!"};
tr[28485] = {OId:439,H:"О! Так это вы удачно к нам завернули. Мы, гремлины, отлично ладим с техникой!"};
tr[28486] = {H:"Да? Вот здорово - настоящее новогоднее чудо! "};
tr[28487] = {OId:439,H:"Мы починим поезд, угу. А пока приглашаем тебя к нам за праздничный стол. Новый год на носу всё-таки!"};
tr[28488] = {H:"Круто! А куда мне идти?"};
tr[28489] = {OId:439,H:"Кликни на дверь Кафе и отведай любое блюдо, какое тебе только понравится. "};
tr[28490] = {H:"Вот так праздник! Спасибо, уже бегу!"};
tr[28491] = {OId:440,H:"Караул! Гремлины украли поезд с подарками. Теперь нам нечего дарить Смешарикам в Шарараме!"};
tr[28492] = {H:"Надо догнать гремлинов! Рудольф, ты же волшебный олень - сможешь угнаться за ними?"};
tr[28493] = {OId:440,H:"Ох, позволь заметить, летать я и вправду могу, но только медленно. Вот если бы нас было трое. Три волшебных оленя!"};
tr[28494] = {H:"Хм... А родственников у тебя случайно нет?"};
tr[28495] = {OId:440,H:"О! Охо-хо! Вот я сглупил. В Шарараме у меня есть брат и сестра! Давай найдём их!"};
tr[28496] = {H:"Отлично! Найдём оленей, а потом догоним гремлинов и вернём поезд!"};
tr[28497] = {OId:440,H:"Юху! Привет-привет! Ой, тебя что-то беспокоит?"};
tr[28498] = {H:"Привет, Метелица! Поезд Деда Мороза похитили гремлины. Поможешь нам его вернуть?"};
tr[28499] = {OId:440,H:"Гремлины?! Хм... Пожалуй, чтобы догнать их, нам не помешают летающие сани."};
tr[28500] = {H:"О! А как их сделать?"};
tr[28501] = {OId:440,H:"Хи-хи! Сани почти готовы. Я как раз строила их, чтобы на празднике покатать Смешариков по небу!"};
tr[28502] = {H:"А что значит " + "\"" + "почти" + "\"" + "?"};
tr[28503] = {OId:440,H:"Хай! Скоро праздник, чего ты угрюмый такой?"};
tr[28504] = {H:"Привет, Молния! Тут проблема есть - гремлины похитили поезд Деда Мороза..."};
tr[28505] = {OId:440,H:"Так нужно их догнать! Соберёмся с другими оленями и помчимся за похитителями!"};
tr[28506] = {H:"О, значит, ты поможешь?"};
tr[28507] = {OId:442,H:"Ой, а что вы так строго смотрите? Мы вот вам поезд в Шарарам привезли."};
tr[28508] = {OId:440,H:"Как это привезли, если вы его похитили?"};
tr[28509] = {H:"Я понял. Гремлины решили прикинуться добренькими!"};
tr[28510] = {OId:442,H:"Хех! Мы починили ваш поезд и решили сами его сюда привезти. Оформили, так сказать, доставочку."};
tr[28511] = {OId:441,H:"Вы нам ещё спасибо сказать должны! А не нападать..."};
tr[28512] = {H:"Ага... Только вы на поезде летели не в сторону Шарарама. Почему-то."};
tr[28513] = {OId:442,H:"Ну так... Мы это... Хе-хе... Заблудились... Немного..."};
tr[28514] = {OId:441,H:"Ага, нас вообще иногда логика подводит. Вот и к нам в страну мы вас с трудом заманили... Ой"};
tr[28515] = {H:"Ясно... Так это с самого начала была ловушка..."};
tr[28516] = {OId:442,H:"Ай, нас раскрыли. Что же теперь делать? Что же делать-то???"};
tr[28517] = {OId:441,H:"Давай снова украдём у них поезд, а? Уахаха!"};
tr[28518] = {H:"Я вам украду! Хватит уже портить нам праздник."};
tr[28519] = {OId:443,H:"Хо-хо! Я слышал, вы с Рудольфом уже доставили подарки во все страны?"};
tr[28520] = {H:"С приключениями, но доставили! И в Шарарам поезд привезли."};
tr[28521] = {OId:443,H:"И у меня были приключения! Сейчас я расскажу, чем же закончилась моя секретная миссия."};
tr[28522] = {H:"Да-да, интересно, чем ты занимался всё это время?"};
tr[28523] = {OId:443,H:"Я собрал всех Смешариков, которые были символами новых годов! Вот они - на колесе!"};
tr[28524] = {H:"Ой. А на месте знака вопроса никого и нет..."};
tr[28525] = {OId:443,H:"А это сюрприз! Приходи в Шарарам 29 декабря, встречай праздник и призови символ 2018 года!"};
tr[28526] = {H:"Круто!"};
tr[28527] = {H:"Снежинка|Снежинка вырастет через {0} мин."};
tr[28528] = {H:"Я совершил новогоднее кругосветное путешествие! Скорее в Шарарам - праздник уже начался!"};
tr[28529] = {OId:440,H:"Кликни на поезд, чтобы отправиться в путешествие!"};
