tr[28532] = {H:"Сцена " + "\"" + "Рэп-батл" + "\"" + ""};
tr[28533] = {H:"Причёска " + "\"" + "Чёрные хвостики" + "\"" + ""};
tr[28534] = {H:"Чёрный камзол"};
tr[28535] = {H:"Шляпа " + "\"" + "Марсель" + "\"" + ""};
tr[28536] = {H:"Шарф-капюшон " + "\"" + "Орлеан" + "\"" + ""};
tr[28537] = {H:"Бейсболка " + "\"" + "Лион" + "\"" + ""};
tr[28538] = {H:"Я собрал коллекцию модных шапок! Хочешь и ты также? Приходи в Шарарам!"};
tr[28539] = {H:"фон " + "\"" + "Жерло вулкана" + "\"" + ""};
tr[28540] = {H:"Магия " + "\"" + "Джо-Ворон" + "\"" + ""};
tr[28541] = {H:"Магия " + "\"" + "Джо-Ворон" + "\"" + ""};
tr[28542] = {H:"Магия " + "\"" + "Джо-Ворон" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Джо-Ворона ещё дней: {0}|Ты можешь превращаться в Джо-Ворона всегда!"};
tr[28543] = {H:"Превращайся в знаменитого пирата!|Всюду бери с собой попугая!|Управляй магией кнопками " + "\"" + "танец" + "\"" + ", " + "\"" + "сидеть" + "\"" + ", " + "\"" + "махать" + "\"" + "."};
tr[28544] = {H:"Твои помидоры уже не помещаются в карманы. Приходи снова, когда израсходуешь их."};
tr[28545] = {H:"Помидоры уже у тебя - ищи на нижней игровой панели."};
tr[28546] = {OId:270,H:"Найди снеговиков в Шарараме и останови их."};
tr[28547] = {OId:270,H:"Взгляни на этот монитор! Мне кажется, или на экране... Джо?"};
tr[28548] = {OId:270,H:"Кликни на снеговиков, чтобы освободить нам проход!"};
tr[28549] = {OId:270,H:"Поговори с Джо-Вороном через монитор."};
tr[28550] = {OId:270,H:"Кликни на снеговиков, чтобы освободить нам проход!"};
tr[28551] = {OId:270,H:"Наконец мы встретились с Джо-Вороном - кликни на него!"};
tr[28552] = {OId:270,H:"Слепи снеговика заново!"};
tr[28553] = {OId:270,H:"....."};
tr[28554] = {OId:270,H:"Хэй! Мы снеговики-пираты. Трепещите, Смешарики, скоро Шарарам будет наш!"};
tr[28555] = {H:"Ну уж нет! Я вас прогоню."};
tr[28556] = {OId:270,H:"Ахаха! Но хватит ли у тебя смелости?"};
tr[28557] = {H:"Ещё как! Хочешь проверить?"};
tr[28558] = {H:"Ха! Нет, наверное. Пойду попью чаёк."};
tr[28559] = {OId:270,H:"Аргх! Нарушитель... Уходи прочь с айсберга - Шарарам всё равно будет наш!"};
tr[28560] = {H:"Джо-Ворон? Так это ты приказал снеговикам напасть?!"};
tr[28561] = {OId:270,H:"Йо-хо-ха! Мой корабль столкнулся с этим айсбергом и потонул. Но снеговики спасли меня и сделали своим капитаном."};
tr[28562] = {H:"И поэтому ты им теперь помогаешь?"};
tr[28563] = {OId:270,H:"Тысяча морских огурцов, да! Мы прогоним всех Смешариков и будем жить в Шарараме как короли!"};
tr[28564] = {H:"Я тебя остановлю, вот увидишь!"};
tr[28565] = {OId:270,H:"Что ж, попробуй! Экипажу - чужак на борту! Повторяю, чужак на борту!"};
tr[28566] = {H:"И попробую!"};
tr[28567] = {OId:270,H:"Мой совет: брось уже якорь, хватит меня преследовать. И не пытайся добраться до капитанской рубки!"};
tr[28568] = {H:"Но почему, Джо? Ты был другом Смешариков!"};
tr[28569] = {OId:270,H:"Я взял курс на новых друзей - снеговиков. А Шарарам станет для них новым домом!"};
tr[28570] = {H:"Новым домом? А что случилось со старым?"};
tr[28571] = {OId:270,H:"Ты мне зубы не заговаривай. Полундра! Всем крутить нактоуз -  чужаки на борту!"};
tr[28572] = {H:"Ох, теперь я обязательно до тебя доберусь, чтобы всё разузнать!"};
tr[28573] = {OId:436,H:"Остановись, Смешарик! Что бы ты ни делал, Шарарам будет наш!"};
tr[28574] = {OId:437,H:"Остановись, Смешарик, что бы ты ни делал, Шарарам будет..."};
tr[28575] = {H:"Эм... Зачем вы говорите одно и то же?"};
tr[28576] = {OId:436,H:"Нет-нет, Джо-Ворон говорит то, что всерьёз думает обо всех вас!"};
tr[28577] = {OId:437,H:"Нет, нет, Джо-Ворон говорит то, что всерьёз думает..."};
tr[28578] = {H:"Аха! Я понял! Ты, Снеговик, заколдовал Джо и управляешь им!"};
tr[28579] = {OId:437,H:"...так же поступим."};
tr[28580] = {H:"Как бы не так. Я и вас остановлю, и Джо-Ворона спасу! "};
tr[28581] = {OId:436,H:"Какие вы все красивые, милые, невероятные!"};
tr[28582] = {OId:438,H:"Мда... Кажется, мы сделали его даже слишком добрым..."};
tr[28583] = {H:"Снеговик, скажи, зачем вы заколдовали Джо-Ворона и напали на Шарарам?"};
tr[28584] = {OId:436,H:"Ууу... Много лет назад мы жили в Арктике. А потом наш айсберг откололся и уплыл в океан."};
tr[28585] = {H:"А что же дальше?"};
tr[28586] = {OId:436,H:"Мы не могли найти себе дом и обозлились на весь мир. А потом нам встретился Джо-Ворон..."};
tr[28587] = {OId:438,H:"...и вы взяли его в плен!"};
tr[28588] = {H:"А потом?"};
tr[28589] = {OId:436,H:"Мы околдовали капитана Джо, чтобы он вывел нас к суше и нашёл для нас новый дом."};
tr[28590] = {H:"Может, расколдуете его наконец?"};
tr[28591] = {OId:436,H:"Вот ваш Джо... Ох, а мы и дальше пойдём дрейфовать в океане... В поисках нового дома..."};
tr[28592] = {OId:437,H:"Бррр! Тысяча морских кротов! Я отвезу вас обратно в Арктику. Сразу бы и попросили."};
tr[28593] = {H:"Джо-Ворон, ты крутой!"};
tr[28594] = {OId:270,H:"Скорее на айсберг! Узнаем, что задумали снеговики!"};
tr[28595] = {OId:436,H:"Догадливый... Мы, снеговики, заколдовали Джо-Ворона. И с остальными Смешариками так же поступим!"};
tr[28596] = {H:"Мёд|Копатыч принесёт мёд через {0} мин."};
tr[28597] = {H:"Ледяной фон"};
tr[28598] = {H:"Ледяная корона"};
tr[28599] = {H:"Ледяная СмеШутка"};
tr[28600] = {H:"Ледяная СмеШутка|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!|"};
tr[28701] = {OId:380,H:"Я, наконец, проснулся, и зима пришла! Не хочешь чего-нибудь заморозить?"};
tr[28702] = {H:"Хочу заморозить киви!"};
tr[28703] = {H:"Давай заморозим вишневый сок!"};
tr[28704] = {H:"Может, заморозим лимонад?"};
tr[28705] = {OId:380,H:"Будет сделано. Только ответь сначала на загадку: из чего сделан снег?"};
tr[28706] = {H:"Из сахара."};
tr[28707] = {H:"Из снежинок."};
tr[28708] = {H:"Из ваты."};
tr[28709] = {OId:380,H:"Упс... Ты ошибся. Попробуй снова."};
tr[28710] = {H:"Хорошо."};
tr[28711] = {H:"Вишнёвая снежинка"};
tr[28712] = {H:"Снежинка-киви"};
tr[28713] = {H:"Лимонадная снежинка"};
tr[28714] = {H:"Спасибо! Покупка уже на складе в твоём домике!"};
tr[28715] = {H:"Причёска " + "\"" + "Зимушка" + "\"" + ""};
tr[28716] = {H:"Зимние очки"};
tr[28717] = {H:"Шапка-ушанка"};
tr[28718] = {H:"Фон " + "\"" + "Снежная битва" + "\"" + ""};
tr[28719] = {H:"Зима ещё не пришла, а я уже наколдовал для тебя зимние наряды. Выбирай!"};
