tr[28905] = {OId:270,H:"Ты хочешь, чтобы символы прошлых праздников собрались вместе, и Новый год наступил?"};
tr[28906] = {H:"Да! Умникус, ты волшебней всех на свете - подскажи, как это сделать."};
