tr[29175] = {H:"Найди сокровища!"};
tr[29176] = {H:"Я нашёл сокровища планеты Икс! Приходи в Шарарам и празднуй Новый год!"};
tr[29177] = {H:"Сидеть, щеночек!"};
tr[29178] = {H:"В Злобыря тебя превращу!"};
tr[29179] = {H:"Получай силушки злодейской!"};
tr[29180] = {H:"А не надеть ли тебе намордник?!"};
tr[29181] = {H:"Ну всё! Тузя начинает злиться."};
tr[29182] = {H:"Ай! Будто не магией, а кирпичами кидаешься!"};
tr[29183] = {H:"Ты меня своими чарами не напугаешь!"};
tr[29184] = {H:"Мда! Подача у тебя так себе!"};
tr[29185] = {H:"Гав! Гав! Гав!"};
tr[29186] = {H:"Лаять весело!"};
tr[29187] = {H:"Не дам обижать Нюшеньку!"};
tr[29188] = {H:"Собака - друг Смешарика!"};
tr[29189] = {H:"Эй, только чур не кусаться!"};
tr[29190] = {H:"Не гавкай так, уши заложило!"};
tr[29191] = {H:"Я не кошка, чтоб на меня лаять!"};
tr[29192] = {H:"Помогите! Злая собака!"};
tr[29193] = {H:"Уууу! Буду лаять и выть!"};
tr[29194] = {H:"Зря ты на нас напал!"};
tr[29195] = {H:"Упс! А вот это было слишком..."};
tr[29196] = {H:"Кто-нибудь, позовите ветеринара..."};
tr[29197] = {H:"А я в домике, я в домике!"};
tr[29198] = {H:"Защищаюсь!"};
tr[29199] = {H:"Ну и чего ты прячешься?"};
tr[29200] = {H:"Всё равно достану!"};
tr[29201] = {H:"Энергия мне сейчас в самый раз!"};
tr[29202] = {H:"Сил у меня прибавилось!"};
tr[29203] = {H:"Породистый кубок.|За победу в чемпионате по хоккею!"};
tr[29204] = {OId:270,H:"А знаешь, я поняла, какое волшебство скрыто в Тузе!"};
