tr[29394] = {OId:270,H:"Найди Смешариков в Шарараме и помоги им снять сцены со спецэффектами."};
tr[29395] = {OId:270,H:"Кликни на химический стол, чтобы создать спецэффекты к моему фильму!"};
tr[29396] = {OId:270,H:"Я так волнуюсь! Скорее включай фильм - кликай на экран."};
tr[29397] = {OId:270,H:"Что могло сделать фильм реальностью? Давай поищем улики!"};
tr[29398] = {OId:270,H:"Найди отбойный молоток в Шарараме!"};
tr[29399] = {OId:460,H:"Кликни на зрительские сидения, чтобы начать копать!"};
tr[29400] = {OId:270,H:"Кликай на провал, чтобы найти артефакты в замке магов!"};
tr[29401] = {OId:270,H:"Кликни на компьютер, чтобы создать спецэффекты."};
tr[29402] = {OId:270,H:"Кликни на экран, чтобы устроить премьеру фильма!"};
tr[29403] = {OId:459,H:"Привет! Я хочу снять фильм про магов. С кучей волшебных спецэффектов!"};
tr[29404] = {OId:458,H:"Мы можем всё. Даже превратить морковку в селёдку!"};
tr[29405] = {H:"Шарри, а что именно ты хочешь показать в своём фильме?"};
tr[29406] = {OId:459,H:"Битву волшебников! Добрые маги победят злых на Площади у Диско!"};
tr[29407] = {OId:458,H:"Хм... Сюжет отличный, но, может, добавим туда селёдку? Летающую?"};
tr[29408] = {H:"Битва магов это круто. Даже без селёдки. Давайте снимать!"};
tr[29409] = {OId:459,H:"Класс! Приходи на Площадь у Диско, я приготовлю всё к съёмкам!"};
tr[29410] = {H:"Окей, уже бегу!"};
tr[29411] = {OId:459,H:"Где. Мой. Диджей-пульт???"};
tr[29412] = {OId:270,H:"Да! Верните нам Диско!"};
tr[29413] = {H:"А что случилось? Как-то похоже на наш фильм..."};
tr[29414] = {OId:270,H:"В том то и дело! Сняли свой фильм и разрушили Площадь у Диско!"};
tr[29415] = {OId:270,H:"Но... это же были просто спецэффекты..."};
tr[29416] = {OId:459,H:"Верните нам Диско и крышу над головой! А то холодно тут в снегу стоять!"};
tr[29417] = {OId:458,H:"Странно... Выходит, наш фильм вдруг стал реальностью..."};
tr[29418] = {H:"И Диско превратилось в поле битвы магов?"};
tr[29419] = {OId:458,H:"Это явно колдовство! Давай-ка проверим экран на Съёмочной площадке."};
tr[29420] = {H:"Диджеи, мы всё решим! Бегу на Съёмочную площадку."};
tr[29421] = {OId:461,H:"Эээ, что тут написано, не разобрать..."};
tr[29422] = {OId:460,H:"Дай, я прочитаю... Ого!"};
tr[29423] = {H:"Шарри, что там?"};
tr[29424] = {OId:460,H:"Тут сказано, что съёмочная площадка построена на месте древнего замка магов!"};
tr[29425] = {H:"Это старый киномеханик на плёнке написал? "};
tr[29426] = {OId:460,H:"Да! Он говорит, что из-за этого происходит странное: раз в год сбывается всё, что показывают на экране!"};
tr[29427] = {H:"Значит, эта магия и заставляет кино становиться реальным..."};
tr[29428] = {OId:461,H:"Ага! Вспомнил. Год назад у нас был фильм про Спрутиков в космосе. И... Спрутики правда полетели в космос!"};
tr[29429] = {H:"Так. Нужно откопать этот древний замок, чтобы всё исправить!"};
tr[29430] = {OId:461,H:"Да. Вы эта... Откопайте замок, чтобы Диско починить."};
tr[29431] = {OId:460,H:"Хм... Чтобы копать, нужен отбойный молоток. Где бы его найти?"};
tr[29432] = {H:"Пойду искать. Может, есть где-нибудь в Подземелье?"};
tr[29433] = {OId:270,H:"Да! Всё так, как я и думал. Эти артефакты способны превратить фантазию в реальность!"};
tr[29434] = {H:"Круто, Шарри! Как же нам заново отстроить Диско?"};
tr[29435] = {OId:270,H:"Очень просто! Снимем фильм, в котором всё на своих местах, и артефакты воплотят его в реальность."};
