tr[29570] = {H:"В Смешмаг поступила новая одежда! Кликай на вешалки и выбирай!"};
tr[29571] = {OId:270,H:"Дружище, не красней! Хочешь мне что-то сказать?"};
tr[29572] = {H:"В День святого Валентина желаю тебе путешествий, полных любви!"};
tr[29573] = {H:"Поздравляю с праздником, пусть рога твои блестят как никогда!"};
tr[29574] = {OId:270,H:"О? А ты уверен, что это послание для меня?"};
tr[29575] = {H:"Упс, попробуем другое!"};
tr[29576] = {OId:270,H:"Гутен таг, ты пришёл меня поздравляйт и вручайт валентинка?"};
tr[29577] = {H:"С праздником! Ты мой любимый японец в Шарараме!"};
tr[29578] = {H:"Спасибо за твои изобретения. С днём Валентина!"};
tr[29579] = {OId:270,H:"Я слусаю, ты хотес поговорить со мной о рюбви?"};
tr[29580] = {H:"Ты красива как цикада, затаившаяся в ветвях сакуры!"};
tr[29581] = {H:"Желаю тебе быть таким же замечательным изобретателем и инженером!"};
tr[29582] = {OId:270,H:"Привет! О, ты принёс валентинки!"};
tr[29583] = {H:"Поздравляю! Желаю тебе найти свою любовь в Подводном мире!"};
tr[29584] = {H:"С праздником! Твои домики так прекрасны, что их совсем не хочется покидать."};
tr[29585] = {OId:270,H:"Хай! Как жизнь?"};
tr[29586] = {H:"С праздником! Пусть твой немецкий акцент не перестаёт нас радовать!"};
tr[29587] = {H:"Хэй, бро, ты вообще молоток. Знай это!"};
tr[29588] = {OId:270,H:"Привет! С праздником всех влюбленных тебя!"};
tr[29589] = {H:"Эта валентинка тебе. Спасибо за Смешмаг - самое романтичное место Шарарама!"};
tr[29590] = {H:"Поздравляю с днём влюбленных. Желаю никогда не ржаветь, милый робот!"};
tr[29591] = {OId:270,H:"Агент, в Шарараме всё спокойно. Происшествий на день влюбленных не ожидается."};
tr[29592] = {H:"Ты лучший защитник Шарарама! С праздником, Шеф!"};
tr[29593] = {H:"Эта валентинка -  признание в любви твоим чудным копытам и пышной гриве. Будь всегда таким!"};
tr[29594] = {OId:270,H:"Ну привет. Как дела? Глаза-то, смотрю, влюбленные!"};
tr[29595] = {H:"Ты самая красивая зебра Шарарама! С днём влюбленных!"};
tr[29596] = {H:"Твои песни о любви трогают до глубины души. С праздником!"};
tr[29597] = {OId:270,H:"Привет! Семь футов под килем тебе в этом океане любви!"};
tr[29598] = {H:"Поздравляю. Спасибо за романтику морских приключений!"};
tr[29599] = {H:"С днём Валентина! Ты самый красивый и ловкий акробат Шарарама!"};
tr[29600] = {OId:462,H:"Привет! А я люблю всех. И совсем не люблю мёд. Такая вот я медведица. "};
tr[29601] = {H:"С праздником! Из всей Лиги героев ты самая пушистая и милая!"};
tr[29602] = {H:"С праздником! Желаю тебе и впредь быть королевой Джунглей!"};
tr[29603] = {H:"Кресло " + "\"" + "Валентинки" + "\"" + ""};
tr[29604] = {H:"Шкаф " + "\"" + "Валентинки" + "\"" + ""};
tr[29605] = {H:"Набор мебели " + "\"" + "Валентинки" + "\"" + ""};
tr[29606] = {H:"Я получил валентинку! В Шарараме сюрпризы ждут и тебя - скорее в игру!"};
tr[29607] = {H:"Причёска " + "\"" + "Карнавал" + "\"" + ""};
tr[29608] = {H:"Жилет " + "\"" + "Школьник" + "\"" + ""};
tr[29609] = {H:"Причёска " + "\"" + "Бодрое утро" + "\"" + ""};
tr[29610] = {H:"Роба Белого мага"};
tr[29611] = {H:"СмеШутка " + "\"" + "Обратный отсчёт" + "\"" + ""};
tr[29612] = {H:"СмеШутка " + "\"" + "Обратный отсчёт" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращать Смешариков ещё дней: {0}|Ты можешь превращать Смешариков всегда."};
tr[29613] = {H:"Я со своей командой одолел Лютыча и получил крутой подарок. Заходи и ты в Шарарам!"};
tr[29614] = {H:"Фон " + "\"" + "Большой босс" + "\"" + ""};
tr[29615] = {H:"Фон для особо важных персон!|Ищи на личной карточке в разделе " + "\"" + "Фоны" + "\"" + "!"};
tr[29616] = {H:"Меч в камне"};
tr[29617] = {H:"Фон " + "\"" + "Рыцарский герб" + "\"" + ""};
tr[29618] = {H:"Дублет"};
tr[29619] = {H:"Наряд мечты"};
tr[29620] = {H:"Дом-дракон"};
tr[29621] = {H:"Латы драконоборца"};
tr[29622] = {H:"Шлем драконоборца"};
tr[29623] = {H:"Доспех драконоборца"};
tr[29624] = {H:"Весёлая энциклопедия"};
tr[29625] = {H:"Друг мой, я пишу 94 том энциклопедии Шарарама. Он посвящён развлечениям и играм Смешариков. Поможешь мне?"};
tr[29626] = {H:"Приходи в Школу магов."};
tr[29627] = {H:"Мне нужны особые чернила. Собери {0} эликсиров."};
tr[29628] = {H:"А ещё для книги нужны рисунки. Научись рисовать - выиграй в Волшебный карандаш."};
tr[29629] = {H:"Замечательно, друг мой книжный. Лови Смешинки!"};
tr[29630] = {H:"Весёлая энциклопедия"};
tr[29631] = {H:"Я работаю над главой о клубах. Надо написать обо всём: обстановке, артистах, посетителях и о кухне."};
tr[29632] = {H:"Собери {0} флаерса в Клубном квартале."};
tr[29633] = {H:"Посети {0} клубов."};
tr[29634] = {H:"Найди в меню одного из клубов желе и купи."};
tr[29635] = {H:"Спасибо за помощь - лови Смешинки!"};
tr[29636] = {H:"Весёлая энциклопедия"};
tr[29637] = {H:"Напишем о том, как Смешарики занимаются спортом."};
tr[29638] = {H:"Сыграй в Футбол в Парке аттракционов."};
tr[29639] = {H:"Сыграй в Волейбол на Пляже и заработай {0} Смешинок."};
tr[29640] = {H:"Выиграй в Сноуборд на Снежной горе."};
tr[29641] = {H:"Здорово! Сам я спорт не люблю, а вот писать о нём энциклопедию - очень!"};
tr[29642] = {H:"Весёлая энциклопедия"};
tr[29643] = {H:"Некоторые считают, что играть одному скучно. Покажешь мне, во что Смешарики играют вместе?"};
tr[29644] = {H:"Выиграй в Скачки в Парке аттракционов."};
tr[29645] = {H:"Сыграй в Секретики на Пляже."};
tr[29646] = {H:""};
tr[29647] = {H:"Очень любопытно! Держи Смешинки за помощь!"};
tr[29648] = {H:"Весёлая энциклопедия"};
tr[29649] = {H:"А теперь напишем о том, как Смешарики ходят друг к другу в гости!"};
tr[29650] = {H:"Сходи в гости к {0} друзьям."};
tr[29651] = {H:"Напиши {0} сообщений на Шарафон: " + "\"" + "Приходи ко мне в гости!" + "\"" + ""};
tr[29652] = {H:"Напиши в общий чат: " + "\"" + "Давайте веселиться у меня в домике!" + "\"" + ""};
tr[29653] = {H:"Удивительно! Том энциклопедии о развлечениях готов. Держи подарок!"};
tr[29654] = {H:"Как написать книгу?"};
tr[29655] = {H:"Глава о клубах"};
