tr[29661] = {H:"Геройская шляпа"};
tr[29662] = {H:"Геройский костюм"};
tr[29663] = {H:"Стань наставником юного героя!|Ухаживай за Крошкой: корми, играй и наряжай!|Супергеройский наряд в комплекте!"};
tr[29664] = {H:"Доспех драконоборца"};
tr[29665] = {H:"СмеШутка " + "\"" + "Приманка для драконов" + "\"" + ""};
tr[29666] = {H:"СмеШутка " + "\"" + "Приманка для драконов" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь приманивать драконов ещё дней: {0}|Ты можешь приманивать драконов всегда!"};
tr[29667] = {H:"Модная причёска"};
tr[29668] = {H:"Элегантное платье"};
tr[29669] = {OId:270,H:"Привет. Признавайся, ты сегодня пил чай с морошкой?"};
tr[29670] = {H:"Нет, Совунья. Не видела здесь кого-нибудь из звёзд?"};
tr[29671] = {OId:270,H:"Видала - Сирена пробегала заплаканная. Молодец, спортом занимается. И от счастья рыдает."};
tr[29672] = {H:"Спасибо. Загляну к ней в Дом звёзд."};
tr[29673] = {H:"Микрофон|Микрофон принесут через {0} мин."};
tr[29674] = {OId:150,H:"Я учу японский язык. Не подскажешь, как переводится слово " + "\"" + "аригато" + "\"" + "?"};
tr[29675] = {H:"" + "\"" + "Пожалуйста." + "\"" + ""};
tr[29676] = {H:"" + "\"" + "Спасибо." + "\"" + ""};
tr[29677] = {H:"" + "\"" + "Наденьте маску!" + "\"" + ""};
tr[29678] = {OId:150,H:"Хм. А в моём учебнике сказано иначе. Попробуй ещё раз."};
tr[29679] = {H:"Хорошо."};
tr[29680] = {OId:150,H:"Хорошо. А как по-японски будет " + "\"" + "до свидания" + "\"" + "?"};
tr[29681] = {H:"Унаги маки."};
tr[29682] = {H:"Авокадо."};
tr[29683] = {H:"Сайонара."};
tr[29684] = {H:"Терияки."};
tr[29685] = {OId:270,H:"Что я тут забыл? Да вот пчола Лосяша укусила, я за лекарствами пришёл."};
tr[29686] = {H:"Копатыч, ты заботливый. Может, и за дракончиком присмотришь, пока Сяо на гастролях?"};
tr[29687] = {OId:270,H:"Это я запросто. Я за кем хочешь ухаживать могу. Хоть за тыквой, хоть за Лосяшем, хоть за Дракошей."};
tr[29688] = {H:"Класс! Спасибо, Копатыч."};
tr[29689] = {OId:270,H:"Привет! Я вот гуляю по Шарараму и ищу место, где для моих кактусов больше солнца будет. "};
tr[29690] = {H:"Ёжик, ты так заботишься о кактусах, может, и за Дракошей Сяо Мяо присмотришь?"};
tr[29691] = {OId:270,H:"Ой, дракон. Ну не знаю. А вдруг мои кактусы от него завянут?"};
tr[29692] = {H:"Ладно, поищу другого Смешарика."};
tr[29693] = {OId:270,H:"Приве-е-е-т! Люблю писать стихи про Нюшу в Школе магов. Тут так спокойно!"};
tr[29694] = {H:"Бараш, вот ты заботишься о Нюше, а может и за Дракошей Сяо Мяо присмотришь?"};
tr[29695] = {OId:270,H:"Хм... А есть у него пятачок или копытца? Кажется, нет. Не вдохновляет."};
tr[29696] = {H:"Ладно, поищу другого Смешарика."};
tr[29697] = {OId:150,H:"Из-за бури я не могу посадить самолёт в Токио. Хех, позависаем в облаках."};
tr[29698] = {OId:270,H:"Ну и буря! Мы не можем приземлиться. Кликни на дверь - я вижу кого-то в иллюминаторе!"};
tr[29699] = {OId:0,H:"Отвлеки драконов"};
tr[29700] = {OId:150,H:"Ха-ха-ха! Вы никогда не дадите консерт в Японии - я не позворю вам приземриться!"};
tr[29701] = {H:"Привет! А мы вообще знакомы?"};
tr[29702] = {OId:150,H:"Рррр... Ты не знаес меня? Я сорист попурярной группы " + "\"" + "Аригато" + "\"" + "!"};
tr[29703] = {H:"Аригато? Точно. Это группа, в которой поёт моя любимая Сяо Мяо!"};
tr[29704] = {H:"Нет, я японскую музыку не люблю. Мой выбор - группа " + "\"" + "Коршун" + "\"" + "."};
tr[29705] = {OId:150,H:"Не зри меня! В Японии есть место торько дря одного попурярного артиста - меня, Хихико-куна!"};
tr[29706] = {H:"Я ничего не понял, но ты не прав! У нас все билеты раскуплены, и зрители нас ждут!"};
tr[29707] = {H:"Магия " + "\"" + "Летающая машина" + "\"" + " на 1 неделю. Кликай на волшебную палочку и превращайся."};
tr[29708] = {H:"Магия " + "\"" + "Цифровое перемещение" + "\"" + " телепорт на 1 неделю. Кликай на волшебную палочку и превращайся."};
tr[29709] = {H:"Магия " + "\"" + "Силовое поле" + "\"" + " телепорт на 1 неделю. Кликай на волшебную палочку и превращайся."};
tr[29710] = {OId:150,H:"Я Хихико-кун: певец и ниндзя. Сирнее меня может быть торюко Сяо Мяо-тян!"};
tr[29711] = {H:"Магия " + "\"" + "Повелитель Зябрушек" + "\"" + ""};
