tr[29871] = {H:"Солнечный ободок"};
tr[29872] = {H:"Домик " + "\"" + "Солнечный замок" + "\"" + ""};
tr[29873] = {H:"Я встретил весну в Шарараме и победил злодея! Приключения ждут - присоединяйся!"};
tr[29874] = {H:"Где прячутся призраки?"};
tr[29875] = {H:"Привет! Хочешь, я открою тебе призрачную сторону Шарарама?"};
tr[29876] = {H:"Чтобы увидеть призраков, тренируй зрение. Посмотри в Перископ в Порту."};
tr[29877] = {H:"Посмотри в Подзорную трубу на Пляже."};
tr[29878] = {H:"Научись видеть волшебные рисунки. Выиграй в Волшебный карандаш в Школе магов."};
tr[29879] = {H:"Хорошо... Не боишься? Ведь ты сможешь видеть призраков!"};
tr[29880] = {H:"Где прячутся призраки?"};
tr[29881] = {H:"Я познакомлю тебя с подводными призраками. Они хватают тебя чем-то склизким за пятки, когда ты плаваешь в море!"};
tr[29882] = {H:"Спускайся в Подводный мир."};
tr[29883] = {H:"Призраки сидят внутри кораллов. Собери {0} штук."};
tr[29884] = {H:"А некоторые выползают на сушу и прячутся в песке. Сыграй в Секретики на Пляже."};
tr[29885] = {H:"Теперь ты знаешь, где живут морские призраки... Надеюсь, они больше тебя не напугают."};
tr[29886] = {H:"Где прячутся призраки?"};
tr[29887] = {H:"А теперь покажу тебе лесных призраков. Они притворяются старыми деревьями и зловеще скрипят!"};
tr[29888] = {H:"Два призрака сбежали из леса! Верни их: найди в Шарараме {0} призраков и прогони."};
tr[29889] = {H:"Посмотри на призраков - сыграй в Дары леса и заработай {0} Смешинок за 1 раз."};
tr[29890] = {H:"Когда в следующий раз пойдёшь в тёмный лес, передавай моим друзьям-призракам привет!"};
tr[29891] = {H:"Где прячутся призраки?"};
tr[29892] = {H:"А ты знал, что призраки питают Злобырей своей силой?"};
tr[29893] = {H:"Приготовься ко встрече со Злобырем - покорми своего питомца."};
tr[29894] = {H:"Победи {0} Злобыря в Каньоне."};
tr[29895] = {H:"Награди своего питомца - поиграй с ним."};
tr[29896] = {H:"Если тебя когда-нибудь одолеет Злобырь, знай - это ему призраки помогли."};
tr[29897] = {H:"Где прячутся призраки?"};
tr[29898] = {H:"А теперь я расскажу тебе о самых зловещих призраках! Они поджидают тебя в самом спокойном месте - в домике!"};
tr[29899] = {H:"Предупреди друзей. Напиши {0} сообщений на Шарафон: " + "\"" + "Берегись домовых призраков!" + "\"" + ""};
tr[29900] = {H:"Сходи в гости к {0} друзьям."};
tr[29901] = {H:"Кинь {0} помидоров в мебель. Призраки внутри неё."};
