tr[29983] = {H:"Мы привезли в Шарарам праздник лулзов! Нарядись к нему в Летающей тарелке в Лесу и приходи снова!"};
tr[29984] = {OId:270,H:"Стань циркачом в Парке аттракционов и на Площади перед Диско. А я вручу тебе награды!"};
tr[29985] = {H:"Подробнее"};
tr[29986] = {H:"Весёлого праздника! Ты прекрасно знаешь Зябрийские традиции!"};
tr[29987] = {H:"Цветные очки-жалюзи"};
tr[29988] = {H:"Костюм Пьеро"};
tr[29989] = {H:"Ты нашёл 100 Смешинок!"};
tr[29990] = {OId:207,H:"Крутая башня, ага? Помоги мне завершить небоскрёб - кликни на него."};
tr[29991] = {OId:207,H:"Узнай у Лосяша в Подземелье, почему рушатся здания."};
tr[29992] = {OId:469,H:"Друг мой подземный, сначала поговори со мной!"};
tr[29993] = {OId:469,H:"Кликай по кротовой норе."};
tr[29994] = {OId:469,H:"Кроты ждут! Кликни по норе и спаси Шарарам!"};
tr[29995] = {OId:207,H:"О, да это же лабиринт! Найди тролля - кликни на статую, и она укажет тебе путь!"};
tr[29996] = {OId:207,H:"Шарараму нужен небоскрёб! Найди Смешариков и попроси помочь на стройке!"};
tr[29997] = {OId:207,H:"Найди врагов тролля в лабиринте!"};
tr[29998] = {OId:207,H:"Ёлки-иголки... За что кролик ни возьмётся, всё у него разваливается."};
tr[29999] = {H:"Крош, не расстраивайся. И, кажется, у тебя шарафон звонит."};
tr[30000] = {OId:207,H:"Ах, это. Просто СМСка от Лосяша, что-то срочное..."};
tr[30001] = {H:"Ой, а ведь Лосяш просто так паниковать не будет. Он же лось."};
tr[30002] = {OId:207,H:"Хм... Написано, что в Шарараме произошло... землетрясение?!! Лосяш ждёт нас в Подземелье!"};
tr[30003] = {H:"Так и знал! Начался конец света. Скорее бежим к Лосяшу!"};
tr[30004] = {OId:469,H:"Скорее! Шарараму грозят землетрясения. Все здания могут рухнуть!"};
tr[30005] = {OId:472,H:"О... Так вот почему упала моя башня! А я-то уж подумал, что плохой строитель."};
tr[30006] = {H:"Лосяш, а откуда у нас землетрясения?"};
tr[30007] = {OId:469,H:"Я думаю, виноваты... Кроты! Всё копают, копают и перекапывают."};
tr[30008] = {H:"О... Так это их нора возле тебя?"};
tr[30009] = {OId:469,H:"Да. Скорее кликай на нору и останови раскопки кротов, пока Шарарам не провалился под землю."};
tr[30010] = {H:"Класс! Ой, то есть, да, всех спасу!"};
tr[30011] = {OId:207,H:"Добро пожаловать в агентство " + "\"" + "ДежаВю" + "\"" + "! Но мы пока закрыты - стройка идёт."};
tr[30012] = {H:"Из-за ваших раскопок в пещерах у нас земля трясётся."};
tr[30013] = {H:"Пока вы что-то в темноте копаете, у нас дома рушатся."};
tr[30014] = {H:"Крот, послушай, хватит копать. Приказываю тебе именем Злобикуса!"};
tr[30015] = {OId:207,H:"Не пойдёт. Я подчиняюсь только своему директору."};
tr[30016] = {H:"Упс. Неправильно подобрал слова. Попробую ещё."};
tr[30017] = {OId:207,H:"Это не повод отменить раскопки - у нас же стройка! Хотя... Есть один вариант."};
tr[30018] = {H:"Какой же?"};
tr[30019] = {OId:207,H:"Да тут один подземный тролль перекрыл наши старые ходы. Вот и приходится копать новые..."};
tr[30020] = {H:"О, так может я договорюсь с этим троллем?"};
tr[30021] = {OId:207,H:"Ты сам это предложил! Если тролль освободит тоннели, мы перестанем копать!"};
tr[30022] = {H:"Класс! Пойду к троллю. Где он?"};
tr[30023] = {OId:221,H:"Не надо! Не обижай меня, я ранимый!"};
tr[30024] = {H:"Привет! Тролль, может уйдешь из этих тоннелей - а то кроты тебя боятся."};
tr[30025] = {OId:221,H:"Я бы ушёл! Но меня не выпускают... ОНИ! Никак не выбраться, и бежать некуда!"};
tr[30026] = {H:"Они? Ты о ком? Я могу и с ними договориться, чего уж там."};
tr[30027] = {OId:221,H:"Они... Эти... СУЩЕСТВА. Прячутся в темноте. Вот, я отмечу их на карте!"};
tr[30028] = {H:"Карта лабиринта? Наконец-то!"};
tr[30029] = {OId:221,H:"Найди... ИХ. И попроси выпустить меня. Тогда я уйду, и пусть кроты делают, что хотят."};
tr[30030] = {H:"Хорошо, уже бегу!"};
tr[30031] = {OId:471,H:"Я отправляюсь в горы к брату Ознобу. Буду учиться быть добрым соседом!"};
tr[30032] = {H:"Класс! Значит, вы, кроты, не будете больше сотрясать нашу землю?!"};
