tr[30210] = {OId:270,H:"Ахаха! И последнее: кто на Зябру прилетает, тот... "};
tr[30211] = {H:"Обратно улетает?"};
tr[30212] = {H:"Тоскует и скучает."};
tr[30213] = {H:"Мечтает, играет и силой мысли котиками управляет!"};
tr[30214] = {H:"Спутник Шорк"};
tr[30215] = {H:"Клуб на Ривьере"};
tr[30216] = {H:"Устрой тусу на Лазурном берегу!|Купайся с друзьями в море и загорай!|Бонус: фасад в подарок!"};
tr[30217] = {H:"Магия " + "\"" + "Парад планет" + "\"" + ""};
tr[30218] = {H:"Магия " + "\"" + "Парад планет" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь устраивать парад планет ещё дней: {0}|Ты можешь устраивать парад планет всегда!"};
tr[30219] = {H:"Очки " + "\"" + "Неоновые" + "\"" + ""};
tr[30220] = {H:"Очки Солярис"};
tr[30221] = {H:"До свидания! Очень грустно, что ты не написал нам письмо. Зря тебе пожалуйста! Не летай к нам на планету Верхдном. Привет!"};
tr[30222] = {H:"Збазибо за бизьмо! Твои злова заздавили наз немного поволновадзя, но деперь взё нормально. Привед тебе с бланеды збагойных лемуров."};
tr[30223] = {H:"Подойди к окну и посмотри на небо. Затем трижды обернись и топни ногой. Тогда появимся мы, невидимые пришельцы с планеты Розыгрыш."};
tr[30224] = {H:"Карлыгдыг мыгдык. Тыгыдык-тыгыдык! А бык-пык-шпык? Взгдрык бердыг. Мугдук какбык. Цзык!"};
tr[30225] = {H:"Привет! Расскажем тебе о нашей планете: у нас 3 луны, 8 океанов, 2 подземных города, 15 цветов, 19 нот и 1 ухо на 16087 жителей. Вроде всё."};
tr[30226] = {H:"000111 010101010101 010101000001 1 1010101001 010101010101010 101010101001 [Отправлено с планеты Роботов]"};
tr[30227] = {H:"Привет! Мы пытались разглядеть в телескоп твою планету, но не смогли. Может, подашь нам знак? Помаши небу всеми пятью руками!"};
tr[30228] = {H:"Првт! Н нш плнт свсм нт глснх звкв. Птм жлм тб прчт т псьм, нчтс пнмть всх пршлцв, ктрх т встртшь н свм пт! Удч, змлнн!"};
tr[30229] = {H:"Привет, дружок! Каким-то чудом мы говорим на том же языке, что и ты. Погладь за нас свинку, потому что у нас на планете свинок нет. Ура!"};
tr[30230] = {H:"Спасибо за письмо! По ошибке оно улетело не в космос, а ко мне. Так что ты за компуктером-то долго не сиди, беги закаляться. Твоя Совунья."};
tr[30231] = {H:"Я устроил Парад планет в Шарараме! Хочешь посмотреть? Встречаемся в игре!"};
