tr[30530] = {H:"Ближний космос"};
tr[30531] = {H:"Каждую ночь на наш замок нападает свирепый дракон, и ни один рыцарь ещё не смог его сразить!"};
tr[30532] = {H:"Так вот почему вы здесь спрятались. Я помогу с драконом!"};
tr[30533] = {H:"Ну наконец-то настоящий герой! Отправляйся на башню и защити нас. А я тебя одарю!"};
tr[30534] = {H:"Уже бегу!"};
tr[30535] = {OId:270,H:"Дракон не пройдёт!"};
tr[30536] = {OId:270,H:"Ой, как вас много! Какие вы все красивые!"};
tr[30537] = {H:"Ахах, и ты тоже красавчик!"};
tr[30538] = {H:"Остановись, дракон! Зачем ты на королевство нападаешь?"};
tr[30539] = {OId:270,H:"Ого! А раньше меня никто не хвалил -  обычно я прилетаю, а здесь никого нет."};
tr[30540] = {H:"Просто все боятся, что ты на замок нападёшь!"};
tr[30541] = {OId:270,H:"Я? Нападать?! Ну нет! Ведь я же на самом деле не дракон!"};
tr[30542] = {H:"А кто тогда?"};
tr[30543] = {OId:270,H:"Я - принц Джильберт! Это проклятие Злобикуса превратило меня в дракона! Вот я и летаю каждый день в замок в поисках помощи!"};
tr[30544] = {H:"Вон оно как! Так мы с тебя проклятие снимем."};
tr[30545] = {OId:270,H:"Принц не похож на королевскую особу. Помоги ему найти медали!"};
