tr[30634] = {OId:270,H:"Открою секрет: я приехал в Шарарам на кулинарный мастер-класс. Можешь немного мне помочь?"};
tr[30635] = {H:"Помочь?"};
tr[30636] = {OId:270,H:"Я приготовил десерт, но не знаю, удался ли он. Попробуешь?"};
tr[30637] = {H:"Десерт? Дайте два!"};
tr[30638] = {H:"Птички поют!"};
tr[30639] = {H:"Дружище, нет времени объяснять - кажется, я теряю голос! Поможешь вернуть его?"};
tr[30640] = {H:"Дадим голосу отдохнуть - найдём тихое место. Посети {0} домиков друзей."};
tr[30641] = {H:"Морской воздух даст голосу силу. Сыграй в Катер в Порту."};
tr[30642] = {H:"Давай распоёмся. Напиши в общий чат: Ла-ла, ла-ла-ла, ла-ла, ла-ла!"};
tr[30643] = {H:"Кар, кар - проверка! Ура, голос ко мне возвращается."};
tr[30644] = {H:"Птички поют!"};
tr[30645] = {H:"Кхм, кхм.. Что же это такое? Я тоже теряю голос! Скорее свари для меня целебный отвар!"};
tr[30646] = {H:"Приходи в Дремучий лес."};
tr[30647] = {H:"Собери Дары леса и заработай {0}  Смешинок."};
tr[30648] = {H:"Собери {0} шишек на Снежной горе."};
tr[30649] = {H:"Ох, выпила отвар и полегчало. Спасибо!"};
tr[30650] = {H:"Птички поют!"};
tr[30651] = {H:"Ахтунг, теперь и я теряйт голос. Скорее помоги мне наладить карманный робот, который сможет говорить вместо я."};
tr[30652] = {H:"Приходи в Ромашковую долину."};
tr[30653] = {H:"Помоги мне починить Вечный двигатель и заработай {0}  Смешинок."};
tr[30654] = {H:"Накопи {0}  Смешинок в любой игре на новые детали для робота."};
tr[30655] = {H:"Гут! Робот разговаривайт вместо меня. Получай за это подарок!"};
tr[30656] = {H:"Птички поют!"};
tr[30657] = {H:"Птицы Шарарама всё ещё теряют свои голоса. Я вижу тут след магии. Он и выведет нас к виновнику."};
tr[30658] = {H:"Сварим проявитель магии. Cобери {0} эликсиров в Школе магов."};
tr[30659] = {H:"Проверь, нет ли магии на Пляже. Сыграй в Секретики."};
tr[30660] = {H:"Проверь, нет ли магии на Площади у Диско. Сыграй в Смешарики."};
tr[30661] = {H:"Спасибо! Я нашёл источник магии.Заклинание, вытягивающее голос, прочитала Леди Кря-Кря!"};
tr[30662] = {H:"Птички поют!"};
tr[30663] = {H:"Да! Я забрала голоса птиц, чтобы снять и озвучить новый клип. Помоги мне закончить работу, и голоса вернутся хозяевам."};
tr[30664] = {H:"Поищем место для съёмки клипа. Посети {0}  клубов."};
tr[30665] = {H:"Подбери наряды для клипа. Сыграй в игру Студия моды в Доме мод."};
tr[30666] = {H:"Устрой спецэффекты. Кинь в воздух {0} помидоров."};
tr[30667] = {H:"Клип записан! Возвращаю голоса птицам. А ты держи подарок."};
tr[30668] = {H:"Верни голос Карычу!"};
tr[30669] = {H:"Верни голос Совунье!"};
tr[30670] = {H:"Верни голос Пину!"};
tr[30671] = {H:"Кто ворует голоса?"};
tr[30672] = {H:"Сними клип Кря-Кря!"};
tr[30673] = {OId:270,H:"Я думала, меня поселят в обычный номер. А тут такое! Спасибо!"};
tr[30674] = {H:"Да! Всё затянуто тиной морской - как вы, русалки, любите!"};
tr[30675] = {OId:270,H:"Открою секрет: я приехала в Шарарам на кулинарный мастер-класс. Можешь немного мне помочь?"};
tr[30676] = {OId:270,H:"Я приготовила десерт, но не знаю, удался ли он. Попробуешь?"};
tr[30677] = {OId:150,H:"Так-с, так-с: температура, озноб и квакающий кашель. Все признаки квакушкиного морока!"};
tr[30678] = {H:"Что?! Как!? Доктор, это серьёзно?"};
tr[30679] = {OId:150,H:"Конечно! Есть шанс, что скоро ты превратишься... Как бы это сказать помягче..."};
tr[30680] = {H:"В вампира?"};
tr[30681] = {H:"В русалку?"};
tr[30682] = {H:"В зануду?"};
tr[30683] = {OId:150,H:"Нет, в лягушку! Да-да. Видимо, ты отравился чем-то колдовским. Ох, и я даже не знаю, как это лечить."};
tr[30684] = {H:"Так. Значит, надо срочно бежать в отель к вампиру Фредди!"};
tr[30685] = {H:"Так. Значит, надо срочно бежать в отель к русалке Луне!"};
tr[30686] = {H:"Ладно. Лягушка, так лягушка. Буду готовиться. Ква!"};
tr[30687] = {H:"костюм Шарри"};
tr[30688] = {OId:270,H:"Стоять, дальше хода нет! Не пущу я тебя к ведьме, хозяйке моей!"};
tr[30689] = {H:"Привет, бык. А мне и не нужно к ведьме. Я вампира ищу."};
tr[30690] = {H:"Привет, бык. А мне и не нужно к ведьме. Я русалку ищу."};
tr[30691] = {OId:270,H:"Вампира? Ну уж нет, ничего тебе не скажу и никуда не пущу. Лучше уноси ноги, пока цел."};
tr[30692] = {OId:270,H:"Русалку? Ну уж нет, ничего тебе не скажу и никуда не пущу. Лучше уноси ноги, пока цел."};
tr[30693] = {H:"Ох, чего-то мне нехорошо стало..."};
tr[30694] = {H:"Поздравляем, ты пощекотал курьи ножки. А проход не открылся - поищи ещё."};
tr[30695] = {H:"Окно закрыто. Поищи другой вход."};
tr[30696] = {OId:270,H:"Смотрите-смотрите! Научу вас варево ведьмино готовить!"};
tr[30697] = {OId:270,H:"Привет! Смотрю тебе тоже не повезло, лягушечка."};
tr[30698] = {H:"Ква! Я не лягушка, я Смешарик! Что здесь творится?"};
tr[30699] = {OId:270,H:"Ха! Так и мы Смешарики. А ведьма обманом заманила русалку с вампиром сюда и учит их готовить отравленные тортики."};
tr[30700] = {H:"Отравленные тортики? Чтобы превращать Смешариков в лягушек?"};
tr[30701] = {OId:270,H:"Ага! Ква. Всех в Шарараме в лягушек обратит и будет править. А пока, видишь, помощников себе готовит."};
tr[30702] = {H:"Ох, надо её остановить! Жаль русалка и вампир по-лягушачьи не понимают..."};
tr[30703] = {OId:270,H:"Мы у ведьмы давно в плену и даже научились кое-чему в зельеварении. Давай заменим её рецепт."};
tr[30704] = {H:"Заменить рецепт? Но как?"};
tr[30705] = {OId:270,H:"Касатик, так это ты мне зелье попортил?! Ай-ай, старушку в жабу превратил!"};
tr[30706] = {H:"Не в жабу, а в лягушку. Вот теперь, ведьма, рассказывай, как вернуть всё назад."};
tr[30707] = {OId:270,H:"Не хочу, не буду! Ух, злодей! Ладно... Давай сварим зелье, не гоже мне жабой быть..."};
tr[30708] = {H:"То-то же!"};
tr[30709] = {OId:478,H:"Ура! Ты нас расколдовал! Хочется прыгать и квакать! Ой, то есть танцевать и смеяться!"};
tr[30710] = {H:"Эх, понять бы только, зачем Фредди решил ведьме помогать..."};
tr[30711] = {H:"Эх, понять бы только, зачем русалка Луна решил ведьме помогать..."};
tr[30712] = {OId:270,H:"Прости... Мы с Луной и подумать не могли, что ведьма нас отраву учила готовить..."};
tr[30713] = {OId:479,H:"Прости... Мы с Фредди и подумать не могли, что ведьма нас отраву учила готовить..."};
tr[30714] = {H:"Мораль: не доверяйте ведьмам!"};
