tr[30721] = {H:"3D-обои " + "\"" + "Акула" + "\"" + ""};
tr[30722] = {H:"3D-обои " + "\"" + "Смешарики" + "\"" + ""};
tr[30723] = {H:"3D-ковёр " + "\"" + "Пропасть" + "\"" + ""};
tr[30724] = {H:"3D-ковёр " + "\"" + "Город" + "\"" + ""};
tr[30725] = {H:"3D-ковёр " + "\"" + "Ледяная страна" + "\"" + ""};
tr[30726] = {H:"3D-ковёр " + "\"" + "Подводный мир" + "\"" + ""};
tr[30727] = {H:"Возьми напрокат наушники DJ, зайди в свой гардероб и надень."};
tr[30728] = {H:"Я призвал в Шарарам пятое время года! Заходи в игру и сам увидишь!"};
tr[30729] = {OId:477,H:"Гости уже ждут тебя в номере - встречай их!"};
tr[30730] = {OId:477,H:"Ты выглядишь уставшим - сходи к Бинтику в Больничке и проверь здоровье!"};
tr[30731] = {OId:477,H:"Утром Фредди уехал. Кликни на телефон возле меня и узнаешь куда!"};
tr[30732] = {OId:477,H:"Утром Луна уехала. Кликни на телефон возле меня и узнаешь куда!"};
tr[30733] = {OId:477,H:"Утром Луна уехала. Кликни на телефон возле меня и узнаешь куда!"};
tr[30734] = {OId:477,H:"Ищи вампира в Дремучем лесу!"};
tr[30735] = {OId:477,H:"Ищи русалку в Дремучем лесу!"};
tr[30736] = {OId:477,H:"О, ну и вид у тебя!\nСделай-ка рентген!"};
tr[30737] = {OId:270,H:"Бррр, лягушка! Скачи-ка ты по своим делам."};
tr[30738] = {OId:270,H:"Ой, ты чего так ведьму напугал, что она удрала?"};
tr[30739] = {OId:270,H:"Ой. Что-то мы совсем с зельем напутали. Даже ведьма лягушкой стала."};
tr[30740] = {H:"Причёска Фредди"};
tr[30741] = {H:"Причёска русалочки"};
tr[30742] = {H:"Я обхитрил злую ведьму! Приходи в Шарарам и окажись в сказке!"};
tr[30743] = {H:"Кубок сказочного полёта|За победу в соревновании эльфов!"};
tr[30744] = {H:"Кубок здоровяка|За победу в соревновании великанов!"};
