tr[30757] = {H:"Бейсболка " + "\"" + "Ночь" + "\"" + ""};
tr[30758] = {H:"Твои солнышки"};
tr[30759] = {OId:270,H:"Ты знал, что выпускники школы спрятали здесь в тайниках подарки? Кидай солнышки, чтобы найти их!"};
tr[30760] = {OId:270,H:"Кажется, ты нашёл все тайники и забрал все подарки."};
tr[30761] = {OId:270,H:"Я решил отправить Школу магов на каникулы! Расслабься - никаких уроков. Выбирай любое развлечение!"};
tr[30762] = {H:"Берегись ловушек!"};
tr[30763] = {H:"Много лет назад я расставил в Шарараме злодейские ловушки. А теперь Шеф заставил меня их убрать. Поможешь мне?"};
tr[30764] = {H:"Несколько ловушек я спрятал в домиках твоих друзей. Посети {0} домиков."};
tr[30765] = {H:"Ловушки спрятаны в мебели в домиках. Кинь в неё {0} помидоров."};
tr[30766] = {H:"Отправь {0} сообщений на Шарафон: " + "\"" + "Злобикус проказничает в твоём домике" + "\"" + "."};
tr[30767] = {H:"Жаль, конечно, но домики теперь безопасны. Вот твоя награда:"};
tr[30768] = {H:"Берегись ловушек!"};
tr[30769] = {H:"Чтобы Смешарики меньше купались в море, я спрятал ловушки в воде и на берегу. Сможешь их обезвредить?"};
tr[30770] = {H:"Под водой лежат отравленные кораллы. Собери {0} штук в Подводном мире."};
tr[30771] = {H:"Найди ловушки в песке - выиграй в Секретики на Пляже."};
tr[30773] = {H:"Теперь можно плавать в море и ничего не бояться. Грущу."};
tr[30774] = {H:"Берегись ловушек!"};
tr[30775] = {H:"Смешарики любят спорт. А я терпеть не могу! Обезвредь спортивные ловушки."};
tr[30776] = {H:"Приходи в Парк аттракционов."};
tr[30777] = {H:"В Скачках я спрятал злого коня. Чтобы прогнать его, выиграй в игру."};
tr[30778] = {H:"На стадионе сидят злые болельщики. Покажи им хорошую игру - сыграй в Футбол."};
tr[30779] = {H:"Злодейские ловушки пропадают из Шарарама благодаря тебе. Лови награду!"};
tr[30780] = {H:"Берегись ловушек!"};
tr[30781] = {H:"Ха-ха-ха! А снежную гору я заселил дикими троллями. Скатись с горы, чтобы распугать их."};
tr[30782] = {H:"Приходи на Снежную гору."};
tr[30783] = {H:"Сыграй в Ватрушки."};
tr[30784] = {H:"Сыграй в Сноуборд."};
tr[30785] = {H:"Ахаха! Больше в Шарараме нет ловушек, и теперь ничто меня не остановит!"};
tr[30786] = {H:"Берегись ловушек!"};
tr[30787] = {H:"Злобикус обманул тебя: вы убрали ловушки агентов, защищавшие Шарарам от Злобырей! Их армия уже наступает!"};
tr[30788] = {H:"Лиши Злобырей поддержки - найди {0} чудиков в Шарараме и прогони."};
tr[30789] = {H:"Приготовь питомца к битве. Прокачай его на {0} уровень."};
tr[30790] = {H:"Победи {0} Злобырей в Каньоне."};
tr[30791] = {H:"Мы отразили атаку сил зла! Со Злобикусом нужно всегда быть настороже."};
tr[30792] = {H:"Ловушки в домиках!"};
tr[30793] = {H:"Ловушки под водой"};
tr[30794] = {H:"Спортивные ловушки"};
tr[30795] = {H:"Снежные ловушки"};
tr[30796] = {H:"Главная ловушка"};
