tr[30810] = {H:"Футболка " + "\"" + "Прилив" + "\"" + ""};
tr[30811] = {H:"Фон " + "\"" + "Братья-ананасы" + "\"" + ""};
tr[30812] = {H:"Очки " + "\"" + "Солнечный калейдоскоп" + "\"" + ""};
