tr[30830] = {H:"Найди сокровища. Заработай {0} Смешинок в Батискафе за 1 раз."};
tr[30831] = {H:"Тысяча морских ежей! Ты справился... Аррр, я проиграл спор."};
tr[30832] = {H:"Пиратский спор"};
tr[30833] = {H:"Хм... На дне ты отыскал загадочный сундук. Чтобы открыть его, попроси инструменты у Пина."};
tr[30834] = {H:"Приходи в Ромашковую долину."};
tr[30835] = {H:"Сначала помоги Пину починить двигатель и заработай {0} Смешинок."};
tr[30836] = {H:"Сундук открыт. А в нём и твоё сокровище!"};
tr[30837] = {H:"Собираемся в плавание"};
tr[30838] = {H:"Ищем сокровища"};
tr[30839] = {H:"Что в сундуке?"};
tr[30840] = {H:"Урок Красоты"};
tr[30841] = {H:"Стилист Стелла"};
tr[30842] = {H:"Сейчас вход на стадион закрыт."};
tr[30843] = {OId:480,H:"Сначала продумай план игры. Кликай на схему возле меня."};
tr[30844] = {OId:481,H:"Встретимся на матче. Если ты, конечно, успеешь собрать крутую команду..."};
tr[30845] = {OId:480,H:"Ищи футболистов в Шарараме и собери команду мечты!"};
tr[30846] = {H:"Огненный камень|Камень загорится через {0} мин."};
tr[30847] = {H:"Ты не отвёз приглашение. Попробуй снова - набери 1000 баллов за 1 раз."};
tr[30848] = {H:"Магия " + "\"" + "Нюша будущего" + "\"" + ""};
tr[30849] = {H:"Магия " + "\"" + "Нюша будущего" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Нюшу ещё дней: {0}|Ты можешь превращаться в Нюшу всегда!"};
tr[30850] = {H:"Фон " + "\"" + "Команда из будущего" + "\"" + ""};
tr[30851] = {OId:270,H:"Привет! Ты собираешь футбольную команду? Здорово! Возьмёшь меня?"};
tr[30852] = {H:"Но... ты же фея. Феи играют в футбол?! Ахах!"};
tr[30853] = {H:"А что ты умеешь?"};
tr[30854] = {OId:270,H:"Вот и подружки смеются надо мной - они терпеть не могут футбол. А я его полюбила!"};
tr[30855] = {OId:270,H:"У меня есть сонная пыльца - ни один нападающий из-за неё к воротам не прорвётся."};
tr[30856] = {H:"Класс! Ты в команде!"};
tr[30857] = {H:"Ты нам не подходишь."};
tr[30858] = {H:"Устрашающий костюм"};
tr[30859] = {H:"Админ Фикс-Фокс"};
tr[30861] = {H:"Устрашающая обувь"};
tr[30862] = {OId:483,H:"Ты всё ещё надеешься на победу своей команды? Зря, ведь мы тебя обязательно обыграем!"};
tr[30863] = {OId:270,H:"Привет, ну как прошёл первый матч?"};
tr[30864] = {H:"Привет! Моя команда отлично справилась."};
tr[30865] = {H:"Роботы - сильная команда. Сборной Шарарама нужно больше тренировок."};
tr[30866] = {OId:270,H:"А Джунгли проиграли команде Тёмного царства. И духи нашептали мне, что никто с этой командой не совладает!"};
tr[30867] = {H:"Спорт есть спорт! Кто-то же должен проигрывать."};
tr[30868] = {H:"Хм... Ты намекаешь, что команда Тьмы играет нечестно?"};
tr[30869] = {OId:270,H:"Да. Мои игроки на матче начали падать и пропускать мячи. Это выглядело... как проклятье какое-то!"};
tr[30870] = {H:"Ого! Такое дело нужно расследовать!"};
tr[30871] = {OId:480,H:"Команду Джунглей околдовали? Да брось, они просто плохо играют. Вокруг даже нет улик. Или есть?"};
tr[30872] = {OId:270,H:"Ты таки пришёл ко мне по делу или просто так любуешься?"};
tr[30873] = {H:"Привет, чудик! Думаю, ты оставил на стадионе свой парик..."};
tr[30874] = {OId:270,H:"Шо?! Парик! Мой? У тебя!? Верни, пожалуйста."};
tr[30875] = {H:"Верну, конечно! Только скажи, не видел ли ты на футбольном матче чего-то странного?"};
tr[30876] = {OId:270,H:"Всё скажу! На матче видел, как Несмеян шептал заклинания! А для маскировки попкорн жевал."};
tr[30877] = {H:"О, а ты-то как понял, что он заклинания читает?"};
tr[30878] = {OId:270,H:"Шо это ты мне не веришь? Я в злодействах таки довольно разбираюсь!"};
tr[30879] = {H:"Хорошо. Спасибо за помощь - вот твой парик!"};
tr[30880] = {OId:480,H:"Ну как расследование? У тебя есть версия, почему команда Джунглей проиграла?"};
tr[30881] = {H:"Чудик заранее связал все шнурки в раздевалке."};
tr[30882] = {H:"Несмеян прошептал заклинание, которое завязало шнурки команде."};
tr[30883] = {H:"Команда хотела съесть попкорн, вот и не смогла играть."};
tr[30884] = {OId:480,H:"Интересная версия, но улики с ней не сходятся."};
tr[30885] = {H:"Может, тогда Несмеян заколдовал шнурки команды?"};
tr[30886] = {OId:480,H:"Похоже на правду! Но зачем ему это?"};
tr[30887] = {H:"Несмеян - злодей. Вот и болеет за команду Тёмного царства!"};
tr[30888] = {H:"Несмеян хочет подставить команду Тёмного царства!"};
tr[30889] = {H:"Несмеян помогает команде Тёмного царства выиграть!"};
tr[30890] = {OId:480,H:"Отличная догадка! Теперь беги к Несмеяну и не дай ему испортить следующие матчи!"};
tr[30891] = {H:"О, Сэнсэй, отправь меня к Несмеяну! Ты ведь умеешь, да?"};
tr[30892] = {OId:480,H:"Ищи Несмеяна в Клубном квартале!"};
tr[30893] = {OId:270,H:"Привет! Ты чего такой угрюмый? Пришёл обвинять меня в том, что я порчу матчи?"};
tr[30894] = {H:"Ха! Да ты же сейчас сам себя и выдал!"};
tr[30895] = {OId:270,H:"А вот и нет. Сначала попробуй докажи!"};
tr[30896] = {H:"А у меня есть твои отпечатки. И свидетель. Так-то!"};
tr[30897] = {OId:270,H:"Ааа! Ну тогда попробуй догони!"};
tr[30898] = {H:"Бежишь, трус?"};
tr[30899] = {OId:484,H:"Смотри-ка, кто мне попался! Так это он хотел подставить нашу команду?"};
tr[30900] = {OId:485,H:"Что?! Тренер врёт - он сам подговорил меня тайком помогать его команде!"};
tr[30901] = {H:"Ясненько. Вот и встретились два злодея, и каждый тянет одеяло на себя."};
tr[30902] = {OId:484,H:"Эй! Я хоть и из страны злодеев, но в футбол хочу выиграть честно!"};
tr[30903] = {OId:485,H:"Враньё! Тренер Тьмы обещал мне хорошую награду за испорченные матчи."};
tr[30904] = {H:"Я верю Несмеяну. Ведь не стал бы он портить матчи просто так?"};
tr[30905] = {H:"Я верю тренеру. Несмеян портил матчи ради забавы!"};
tr[30906] = {OId:484,H:"Рррр! Не веришь мне?! Что ж, встретимся на поле! И пусть игра рассудит нас."};
tr[30907] = {H:"Окей. Только никаких фокусов! Сэнсэй уже предупредил судью."};
tr[30908] = {OId:484,H:"Верно! Хватит болтать. Давай решим все споры на поле! И вот увидишь,я выиграю."};
tr[30909] = {H:"Моя команда тебя не испугается. Сборная Шарарама победит!"};
