tr[31079] = {H:"Костюм " + "\"" + "Герой" + "\"" + ""};
tr[31080] = {H:"А кто ты? Найди своё призвание в Шарараме!"};
tr[31081] = {H:"Кубок поисковика|За отличия в учениях по Поиску улик."};
tr[31082] = {H:"Волшебная кисть"};
tr[31083] = {H:"Я нарисовал волшебные картины! Приходи в Шарарам и прояви свои таланты."};
tr[31084] = {OId:270,H:"Спустись в метро и проверь, кто там прячется!"};
tr[31085] = {OId:270,H:"Псс, агент! Вызываем тебя на учения по поиску улик. Прыгай в лифт!"};
tr[31086] = {OId:486,H:"Вместе с Лигой героев поймай титана в ловушку! Я-то от страха совсем ослаб."};
tr[31087] = {H:"Краска|Краску принесут через {0} мин."};
tr[31088] = {H:"Секрет домиков"};
tr[31089] = {H:"В Шарараме о домиках заботятся домовые: они за всем следят и наполняют весельем. Но кто позаботиться о самих домовых? Мы с тобой!"};
tr[31090] = {H:"Начнём с Космодрома. Отправляйся туда."};
tr[31091] = {H:"Домовой любит космические слова. Напиши в общий чат: " + "\"" + "Квазар, орбита, луноход" + "\"" + "."};
tr[31092] = {H:"Сыграй в Метеоритный тренажёр и набери {0} Смешинок за 1 раз."};
tr[31093] = {H:"Домовой передал тебе спасибо и оставил Смешинки. Лови!"};
tr[31094] = {H:"Секрет домиков"};
tr[31095] = {H:"Позаботимся о домовом в кафе " + "\"" + "Улыбка" + "\"" + ". Он любит, когда к нему приходит много гостей."};
tr[31096] = {H:"Отправляйся на Пляж."};
tr[31097] = {H:"Поработай в кафе и заработай {0} Смешинок."};
tr[31098] = {H:"Домовой любит жемчужины. Собери {0} штуки."};
tr[31099] = {H:"Домовой обрадовался и оставил тебе Смешинки. Забирай!"};
tr[31100] = {H:"Секрет домиков"};
tr[31101] = {H:"Где домовой живёт, такой у него и характер. Вот в доме мод - домовой модный."};
tr[31102] = {H:"Приходи в Дом мод."};
tr[31103] = {H:"Удиви домового нарядом. Купи в Смешмаге очки " + "\"" + "Аврора" + "\"" + ""};
tr[31104] = {H:"Устрой модный показ. Сыграй в Студию моды."};
tr[31105] = {H:"Спасибо за помощь! Вот твоя награда."};
tr[31106] = {H:"Секрет домиков"};
tr[31107] = {H:"А вот в Бухте живёт очень странный домовой. Я даже побаиваюсь идти к нему одна. Поможешь?"};
tr[31108] = {H:"Попробуем задобрить его вкусняшками. Собери {0} груш в Ромашковой долине."};
tr[31109] = {H:"Устроим тусовку. Напиши {0} сообщений на шарафон: " + "\"" + "Приходи на вечеринку в Бухту" + "\"" + "!"};
tr[31110] = {H:"Ой... Домовой остался недовольным... Странно."};
tr[31111] = {H:"Секрет домиков"};
tr[31112] = {H:"Аррр, домовой в Бухте - это ж мой прадед, кильку мне за шиворот. Его нежностями и весельем не задобришь."};
tr[31113] = {H:"Мой прадед любит подвиги и приключения. Отправляйся в Египет."};
tr[31114] = {H:"Испытай удачу в игре богини Баст и заработай {0} Смешинок."};
tr[31115] = {H:"Соверши подвиг - победи Злобыря в Каньоне."};
tr[31116] = {H:"Домовой Бухты взглянул на тебя и остался доволен. Держи награду!"};
tr[31117] = {H:"Домовой на Космодроме"};
tr[31118] = {H:"Домовой в кафе"};
tr[31119] = {H:"Модный домовой"};
tr[31120] = {H:"Домовой в Бухте"};
tr[31121] = {H:"Укрощение домового"};
tr[31122] = {H:"Костюм " + "\"" + "Герой" + "\"" + ""};
tr[31123] = {H:"Шлем " + "\"" + "Герой" + "\"" + ""};
tr[31124] = {OId:270,H:"Ааа! Еле ноги унесли. Титан так громыхал, что метро обрушилось!"};
tr[31125] = {H:"А куда герои из Лиги пропали?"};
tr[31126] = {OId:488,H:"Испугались, разбежались и попрятались."};
tr[31127] = {H:"Не будем медлить! Нужно проверить ловушки и разыскать монстра."};
tr[31128] = {OId:270,H:"Проверь ловушки и найди титана в Шарараме!"};
tr[31129] = {OId:270,H:"Смотри, какое чудище! Кликай на него."};
tr[31130] = {OId:270,H:"Прогони титана из Парка аттракционов!"};
tr[31131] = {OId:487,H:"Кто осмелился взять меня в плен? Ты!? Посмотрим, кто будет смеяться последним..."};
tr[31132] = {H:"Да! Я не дам тебе разрушить Шарарам, злое чудище!"};
tr[31133] = {OId:487,H:"Ха-ха-ха! Глупости... Мне не нужен Шарарам. Говори, где Злобикус. Я пришёл за ним."};
tr[31134] = {H:"Подожди... Так ты не собираешься вредить Смешарикам? А Злобби тебе зачем?"};
tr[31135] = {OId:487,H:"Злобикус - мой бывший ученик. Много лет назад он предал меня... Пришло время отдавать долги..."};
tr[31136] = {H:"О, ужас! Разборки злодеев на глазах у честных Смешариков!"};
tr[31137] = {OId:487,H:"Приведи ко мне Злобикуса, пока я не разгневался!"};
tr[31138] = {OId:270,H:"Ты узнал правду? Да, титан - мой учитель. И он хочет меня растерзать. Пожалуйста, помоги мне!"};
tr[31139] = {H:"Нет. Вам, злодеям, верить нельзя. Уходите вместе с титаном из Шарарама!"};
tr[31140] = {H:"Я бы помог тебе... Но как мне понять, что ты говоришь правду?"};
tr[31141] = {OId:270,H:"Тогда у меня нет выбора. Приготовься!"};
tr[31142] = {H:"К чему?"};
tr[31143] = {OId:270,H:"Зачем Злобикус отправил нас сюда? Разгадай тайну этого места!"};
tr[31144] = {OId:270,H:"Поговори с портретом юного Злобикуса!"};
tr[31145] = {OId:489,H:"Привет! Мы во сне Злобикуса. Я открою тебе правду о его учителе-титане."};
tr[31146] = {H:"Злобикус заточил меня в своём сне? Вот так история!"};
tr[31147] = {OId:489,H:"Сейчас расскажу. В детстве Злобикус был добрым и весёлым. Но однажды его начали мучить ночные кошмары!"};
tr[31148] = {H:"О, и со мной такое бывает!"};
tr[31149] = {H:"А мне снится всякая ерунда. Говорящие морковки, летающая учительница..."};
tr[31150] = {OId:489,H:"Злобикус не знал, как победить кошмары, и потому сам обозлился! Тогда кошмары стали его друзьями."};
tr[31151] = {H:"А самый страшный кошмар стал его учителем?"};
tr[31152] = {OId:489,H:"Да! Титан до сих пор питается силой здесь, во сне Злобикуса. Победишь кошмары - и титан уйдёт!"};
tr[31153] = {H:"Хитрая задача..."};
tr[31154] = {OId:270,H:"Кошмары напали! Кто бы знал, что в голове Злобикуса ТАКОЕ творится!"};
tr[31155] = {H:"Оживший холст"};
tr[31156] = {H:"Магия " + "\"" + "Волшебная кисть" + "\"" + ""};
tr[31157] = {H:"Магия " + "\"" + "Волшебная кисть" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь путешествовать с волшебной кистью ещё дней: {0}|Ты можешь путешествовать с волшебной кистью всегда!"};
tr[31158] = {H:"Футболка " + "\"" + "Витамин А" + "\"" + ""};
tr[31159] = {H:"Урок Витаминной магии"};
tr[31160] = {H:"Домик " + "\"" + "Пожарная часть" + "\"" + ""};
tr[31162] = {OId:270,H:"Ууу! Вот он, кошмар, питающий титана силой!"};
tr[31163] = {OId:490,H:"Всё? Кошмар исчез?"};
tr[31164] = {OId:491,H:"Мы проверили - в Шарараме его больше нет."};
tr[31165] = {H:"Злобикус, что это вообще было?"};
tr[31166] = {H:"Класс! Шарарам может спать спокойно."};
tr[31167] = {OId:270,H:"От моей злости кошмар ожил. Он всегда мечтал меня напугать, и вот пробрался в реальность..."};
tr[31168] = {H:"А когда он успел стать твоим учителем?"};
tr[31169] = {OId:270,H:"Когда меня выгнали из школы магов. Кошмар стал приходить каждую ночь и обучать тёмным искусствам."};
tr[31170] = {H:"Опасное чудище. Хорошо, что мы с ним расправились!"};
tr[31171] = {OId:270,H:"Спасибо, что вместе с Лигой помогли мне! Кошмары меня больше не напугают."};
tr[31172] = {H:"Только уговор: ты и сам больше не пугай Смешариков!"};
tr[31243] = {OId:270,H:"Ты думал, победил меня? Нет! Кошмары из снов просто так не сдаются!"};
tr[31244] = {H:"Сэнсэй..? В тебя кто-то вселился?"};
tr[31245] = {OId:270,H:"Угадал. Ты разрушил мой дом во сне Злобикуса и изгнал оттуда все кошмары! Я этого не забуду..."};
tr[31246] = {H:"Титан! Ты вселился в Сэнсэя? Ты же должен был исчезнуть..."};
tr[31247] = {OId:270,H:"Вот и нет! Ты меня освободил - я больше не привязан к Злобикусу. Ха-ха-ха!"};
tr[31248] = {H:"Ну и дела! А мы с Лигой так старались тебя одолеть..."};
tr[31249] = {OId:270,H:"Я наберусь сил и вернусь в Шарарам, чтобы захватить Умникуса и Злобикуса и стать самым могущественным злодеем в мире!"};
tr[31250] = {H:"Мы с Лигой этого не допустим!"};
