tr[31342] = {H:"Подготовься к спору. Приходи на Пляж."};
tr[31343] = {H:"Артисты любят отдыхать в Кафе. Понаблюдай за ними и заработай {0} Смешинок."};
tr[31344] = {H:"Накопи {0} Смешинок на поход по клубам."};
tr[31345] = {H:"Ты готов к спору? Начинаем!"};
tr[31346] = {H:"Диско-спор!"};
tr[31347] = {H:"Кто посетит больше клубов и послушает больше артистов - тот и выиграл."};
tr[31348] = {H:"Узнай, что происходит в клубах. Собери {0} флаерсов."};
tr[31349] = {H:"Посети {0} клубов."};
tr[31350] = {H:"Взбодрись. Найди в меню клубов {0} кофе и купи."};
tr[31351] = {H:"Я устал... А ты? Давай сделаем перерыв - вот тебе Смешинки для отдыха."};
tr[31352] = {H:"Диско-спор!"};
tr[31353] = {H:"Ты обыграл папу в споре. И он так устал, что взял себе выходной. Кто же теперь проведёт в Шарараме модную вечеринку?"};
tr[31354] = {H:"Отправь {0} сообщений на Шарафон: " + "\"" + "Приходи на вечеринку в Диско!" + "\"" + ""};
tr[31355] = {H:"Создай настроение. Напиши в общий чат: " + "\"" + "Зажигаем и вальсируем!" + "\"" + ""};
tr[31356] = {H:"Укрась вечеринку рисунками. Сыграй в Волшебный карандаш в Школе Магов {0} раз."};
tr[31357] = {H:"Юху! Ты не только победил в споре, но и устроил крутую вечеринку. Лови подарок!"};
tr[31358] = {H:"Готовимся к вечеринкам"};
tr[31359] = {H:"Большой поход по клубам!"};
tr[31360] = {H:"Подмени Ба-Босса!"};
