tr[31362] = {H:"Куртка " + "\"" + "Космохвостик" + "\"" + ""};
tr[31363] = {H:"Костюм " + "\"" + "Космохвостик" + "\"" + ""};
tr[31364] = {H:"Тузя"};
tr[31365] = {H:"Носи милую игрушку на руках!|Ищи Тузю в своём гардеробе."};
tr[31366] = {H:"20 Смешинок. Уже у тебя в кошельке!"};
tr[31367] = {H:"30 Смешинок. Уже у тебя в кошельке!"};
tr[31368] = {OId:270,H:"Добро пожаловать! Стань чемпионом в боулинге или пройди через Астро-комнату!"};
tr[31369] = {H:"Я чемпион по космо-боулингу! Заходи в Шарарам - сыграем вместе!"};
