tr[31371] = {H:"Толстовка " + "\"" + "Зябро-морковка" + "\"" + ""};
tr[31372] = {H:"Зябро-скейт"};
tr[31373] = {H:"Рок-скейт"};
tr[31374] = {H:"Куртка " + "\"" + "Шеф будущего" + "\"" + ""};
tr[31375] = {H:"Зябро-скейт"};
tr[31376] = {H:"Костюм " + "\"" + "Щупальца" + "\"" + ""};
tr[31377] = {H:"Космопарк"};
tr[31378] = {OId:270,H:"Сделай праздничные фотки в Шарараме и заполни альбом!"};
tr[31379] = {H:"Праздничная камера"};
tr[31380] = {OId:270,H:"Я фоткаю кактусы. Кактусы - это праздник."};
tr[31381] = {OId:270,H:"Я пытаюсь сфоткать редкую пчелу. Не вспугни!"};
tr[31382] = {OId:270,H:"Я фотографирую загорающих Смешариков. Загар - признак здоровья!"};
tr[31383] = {H:"Чтобы сделать фотку, надень праздничную камеру."};
tr[31384] = {H:"Прошу не напоминать мне о школе ещё месяц! Лучше сыграем в Шарарам!"};
tr[31385] = {OId:270,H:"Вот я считаю, что фотки в альбоме должны быть гениальными и даже экстремальными!"};
tr[31386] = {H:"Док, а как мне сделать такие крутые фотки?"};
tr[31387] = {OId:270,H:"Шарараму же 10 лет... Мм.. Как насчёт небольшого путешествия во времени?"};
tr[31388] = {H:"Вновь пережить все приключения со Смешариками и сделать фотки?"};
tr[31389] = {OId:270,H:"Да! Представь, каким крутым будет альбом, если мы добавим в него фотки из прошлого."};
tr[31390] = {H:"Класс! Заводи машину. Летим в Старый Шарарам!"};
tr[31391] = {H:"Опять повторы? Лучше чаю выпью - он-то у меня каждый день новый."};
tr[31392] = {H:"Кепка " + "\"" + "Ещё 1 месяц" + "\"" + ""};
tr[31393] = {H:"Стикеры " + "\"" + "Лемур Рэм" + "\"" + ""};
tr[31394] = {H:"Стикеры " + "\"" + "Черепашка Чо" + "\"" + ""};
tr[31395] = {H:"Стикеры " + "\"" + "Кот Ачи" + "\"" + ""};
tr[31396] = {H:"МультФон Бит"};
tr[31397] = {H:"Стикеры Эйджея"};
