tr[31399] = {H:"Кресло " + "\"" + "Аттракцион" + "\"" + ""};
tr[31400] = {H:"Бейсболка " + "\"" + "Рио" + "\"" + ""};
tr[31401] = {H:"Анализатор домика"};
tr[31402] = {H:"Этот домик любит своего хозяина и мечтает, чтобы ты бывал здесь чаще."};
tr[31403] = {H:"Этому домику нравятся твои гости - зови их чаще."};
tr[31404] = {H:"Этот домик обрадуется, если ты будешь делать перестановку раз в 5 дней."};
tr[31405] = {H:"Этому домику нравится зелёный цвет в интерьере. И, конечно, мягкая мебель."};
tr[31406] = {H:"Этот домик любит электронику, особенно лампочки и фонари. Больше света!"};
tr[31407] = {H:"Этот домик обожает природные материалы и цветочки."};
tr[31408] = {H:"Этот домик радуется, когда ты ходишь по нему вместе с питомцем."};
tr[31409] = {H:"Клубный постер"};
tr[31410] = {H:"Летние очки"};
