tr[31419] = {H:"Я расколдовал Цветок пустыни и встретил принцессу. В Шарараме тебя и не такие чудеса ждут!"};
tr[31420] = {H:"МультФон " + "\"" + "Светлячки" + "\"" + ""};
tr[31421] = {H:"Спутник Черничка"};
tr[31422] = {OId:492,H:"Так держать! Светлячки в маяке указали кораблю Эклера путь в наш Порт. Спасибо!"};
tr[31423] = {H:"Не за что! Жозе, твой корабль в целости?"};
tr[31424] = {OId:270,H:"Уи! Я привёз из Франции лучшие пирожные - как раз ко дню рождения Шарарама! Бон апети!"};
tr[31425] = {H:"Ух ты! А можно посмотреть?"};
tr[31426] = {H:"В Шарарам привезли гору вкусняшек! Намечается большой праздник - заходи в игру!"};
tr[31427] = {OId:270,H:"Кликай на альбом и выбирай год, в который хочешь отправиться!"};
tr[31428] = {OId:270,H:"Дружище, спасибо за прекрасные фотки, но у нас тут такое случилось!"};
tr[31429] = {H:"Карыч, что-то пошло не так?"};
tr[31430] = {OId:270,H:"Наш альбом должен был быть праздничным, а кто-то взял и вклеил в него ужасные злодейские фотки..."};
tr[31431] = {H:"Так давай просто вырвем их из альбома."};
tr[31432] = {OId:270,H:"Не получится, фотки намертво вклеены. Альбом испорчен - сам посмотри."};
tr[31433] = {H:"Хорошо, сейчас проверю."};
tr[31434] = {H:"Масарканд"};
tr[31435] = {OId:270,H:"Спасибо! Сделай фотки и в других годах!"};
tr[31436] = {OId:497,H:"Спасибо! Сделай фотки и в других годах!"};
tr[31437] = {OId:270,H:"Спасибо! Собери в альбом фотки за все годы Шарарама!"};
tr[31438] = {OId:498,H:"Спасибо! Собери в альбом фотки за все годы Шарарама!"};
tr[31439] = {OId:270,H:"Привет, хочешь сняться в нашем фильме? Скорее выбери костюм здесь на Съёмочной площадке."};
