tr[31450] = {H:"Для украшений собери Дары леса и заработай {0} Смешинок."};
tr[31451] = {H:"Теперь в отеле будет празднично. Лови награду!"};
tr[31452] = {H:"Всемирный конкурс отелей"};
tr[31453] = {H:"Лицо отеля - это его работники. Помоги мне их обучить."};
tr[31454] = {H:"Покажи мастер-класс воспитателям - поработай няней в Детском саду."};
tr[31455] = {H:"Покажи швейцарам мастер-класс по открыванию дверей. Посети {0} клубов."};
tr[31456] = {H:"Покажи мастер-класс аниматорам. Устрой весёлую игру в Футбол в Парке аттракционов."};
tr[31457] = {H:"Наш персонал готов к конкурсу. Держи Смешинки за помощь."};
tr[31458] = {H:"Всемирный конкурс отелей"};
tr[31459] = {H:"Покажем наш ресторан с лучшей стороны. Приготовим фирменное блюдо - спагетти с креветками в сливочном соусе."};
tr[31460] = {H:"Приходи на Пляж."};
tr[31461] = {H:"Научись работать в кафе и заработай {0} Смешинок."};
tr[31462] = {H:"Изучи кухню в других местах. Найди в меню одного из клубов спагетти и купи."};
tr[31463] = {H:"Ура, наш ресторан получил 5 звёзд от жюри конкурса - нигде такого нет. Лови награду!"};
tr[31464] = {H:"Всемирный конкурс отелей"};
