tr[31468] = {H:"Класс, у нас такая креативная реклама. Держи награду!"};
tr[31469] = {H:"Всемирный конкурс отелей"};
tr[31470] = {H:"Каждому отелю важно собрать хорошие отзывы от любимых гостей."};
