tr[31473] = {H:"Отправь {0} сообщений на Шарафоны друзей: " + "\"" + "А тебе нравится отель Эллис?" + "\"" + ""};
tr[31474] = {H:"Ура, гости всем довольны! А победу в конкурсе присудили нашему отелю. Спасибо!"};
tr[31475] = {H:"Домашний коврик"};
tr[31476] = {H:"Клуб " + "\"" + "Речной трамвайчик" + "\"" + ""};
tr[31477] = {H:"Клуб " + "\"" + "Речной трамвайчик" + "\"" + ""};
tr[31478] = {H:"Устрой вечеринку на пристани!|Стань капитаном речного трамвайчика!|+Бонус: фасад в подарок!"};
tr[31479] = {H:"Спасибо, что расколдовал меня!"};
tr[31480] = {OId:270,H:"Найди злодеев - прыгай в котёл!"};
tr[31481] = {OId:270,H:"Найди злодеев - прыгай в котёл Умникуса в Школе магов!"};
tr[31482] = {OId:270,H:"Не тронь наших хозяев. Теперь мы служим им!"};
tr[31483] = {OId:494,H:"Нарушитель! Как удалось тебе пробраться в наше логово?"};
tr[31484] = {H:"Привет, злодеи! Ваши фотки привели меня сюда."};
tr[31485] = {OId:493,H:"А я хочу перевернуть всё вверх дном и превратить Шарарам в Марараш!"};
tr[31486] = {OId:495,H:"Да, фотки! Как же я мечтаю ограбить всех Смешариков и стать богачом."};
tr[31487] = {H:"Ааа, понял. Вы, злодеи, просто сфоткали свои мечты?"};
tr[31488] = {OId:494,H:"Не просто сфоткали! Но и зарядили эти фотки магией. Теперь всё, что на них показано, сбудется!"};
tr[31489] = {H:"Сбудется?! Кажется, праздничный альбом придётся уничтожить..."};
tr[31490] = {OId:494,H:"Попробуй... Наша магия коварна. Вместе с альбомом ты уничтожишь и весь Шарарам, ахах!"};
tr[31491] = {H:"Хитрые вы... Как же мне вас остановить..?"};
tr[31492] = {OId:494,H:"Скоро магия сработает, и наши мечты из фотографий станут реальностью!"};
tr[31493] = {H:"Кепка " + "\"" + "Робот" + "\"" + ""};
tr[31494] = {OId:270,H:"Я негодую: другие злодеи задумали захватить Шарарам без меня! Я им, видите ли, не подхожу..."};
tr[31495] = {H:"Хорошо. Хоть раз ты да выступишь на стороне добра."};
tr[31496] = {H:"Я не удивлён. Ведь ни один твой план так и не воплотился."};
tr[31497] = {OId:270,H:"Ррр... Да, а теперь ещё и придётся помогать тебе, чтобы поставить этих зазнаек на место."};
tr[31498] = {H:"Ура! Но скажи, что за колдовство ты пытался сотворить с альбомом?"};
tr[31499] = {OId:270,H:"Я искал брешь в тёмной магии Несмеяна и его приспешников. И нашёл!"};
tr[31500] = {H:"Ух ты! Она поможет остановить злодеев?"};
tr[31501] = {OId:270,H:"Сами злодеи ничего не могут - но их охраняют заколдованные Злобыри. Сразим их, и победа будет за нами."};
tr[31502] = {H:"Как?"};
tr[31503] = {OId:494,H:"Что? Ты пытаешься пробить защиту наших Злобырей?"};
tr[31504] = {OId:270,H:"Что это за амулет? Не направляй его на нас!"};
tr[31505] = {OId:270,H:"Отправляйся к злодеям и направь на Злобырей амулет!"};
tr[31506] = {OId:270,H:"Победи злобырей в Штабе злодеев!"};
tr[31507] = {H:"Привет! С днём рождения Шарарама! Хочешь подарок? Отгадай мою загадку!"};
tr[31508] = {H:"И тебя с праздником! Какую загадку?"};
tr[31509] = {H:"Это сейчас я брейкер, а раньше был..?"};
tr[31510] = {H:"Автомехаником."};
tr[31511] = {H:"Принцем."};
tr[31512] = {H:"Пожарным."};
tr[31513] = {H:"Министром образования."};
tr[31514] = {H:"Однажды Леший решил украсть молодость всех Смешариков. Как он хотел это сделать?"};
tr[31515] = {H:"Накормить грушами-старушами."};
tr[31516] = {H:"Отравить поганками-дряхлянками."};
tr[31517] = {H:"Угостить кашей-молодяшей."};
tr[31518] = {H:"Извести всех мукой-скукой."};
tr[31519] = {H:"В доме звёзд живёт 5 Смешариков. И только две девочки: я и..?"};
tr[31520] = {H:"Лора Бэнкс."};
tr[31521] = {H:"Манна Хантана."};
tr[31522] = {H:"Нюша."};
tr[31523] = {H:"Сяо Мяо."};
tr[31524] = {H:"Однажды я проводить опасный эксперимент и чуть не погубил Шарарам, но Лига героев меня спасайт. Что я сделал?"};
tr[31525] = {H:"Уменьшил домики."};
tr[31526] = {H:"Увеличил носы."};
tr[31527] = {H:"Сузил лица."};
tr[31528] = {H:"Округлил числа."};
