tr[31530] = {H:"Кресло " + "\"" + "Подушечки" + "\"" + ""};
tr[31531] = {H:"Гора подушек"};
tr[31532] = {H:"Мягкий шкаф"};
tr[31533] = {H:"Мягкий собакен"};
tr[31534] = {H:"Водопад"};
tr[31535] = {H:"Озеро"};
tr[31536] = {H:"Излучина"};
tr[31537] = {H:"Речка"};
tr[31538] = {H:"Мельница"};
tr[31539] = {H:"Мост"};
tr[31540] = {H:"Камыши"};
tr[31541] = {H:"Подушка на стену"};
tr[31542] = {H:"Подушка на стену"};
tr[31543] = {OId:270,H:"Дружище, ты справился! Теперь в нашем праздничном альбоме будут только позитивные фотографии!"};
tr[31544] = {H:"Угу! А мечты злодеев больше не сбудутся."};
tr[31545] = {OId:270,H:"А ещё я добавил в альбом фотку, где ты побеждаешь этих злюк!"};
tr[31546] = {H:"Класс! Спасибо, Карыч."};
tr[31547] = {OId:270,H:"А теперь время для фейерверка! Ура! С Днём рождения, Шарарам!"};
tr[31548] = {H:"Ура!"};
tr[31549] = {H:"Самолёт Пина"};
