tr[31575] = {OId:270,H:"С тех пор, как я прилетел на Землю, я съел 258 пирожных и 3 торта. Теперь вот чего-то во рту пересохло."};
tr[31576] = {H:"Аха! Вот поэтому мы на Земле и запиваем сладкое вкусным напитком."};
tr[31577] = {OId:270,H:"Напитком? Расскажи скорее! Надеюсь, он кислый."};
tr[31578] = {H:"Не волнуйся, Кислоид. Этот напиток..."};
tr[31579] = {OId:270,H:"В Шарараме я раньше бывал. Но на Земле ещё столько стран! А как там отмечают праздники?"};
tr[31580] = {H:"О, это ты по адресу. Сейчас только со справочником сверюсь."};
tr[31581] = {OId:270,H:"Я узнал, что на день рождения принято дарить " + "\"" + "ц-в-е-т-ы" + "\"" + ". Это ещё что такое?"};
tr[31582] = {H:"Пучеглаз, слушай внимательно."};
tr[31583] = {OId:270,H:"Уррррррр... Бррр, этой мой живот, прости. Кушать хочется. Чем у вас на праздниках принято лакомиться?"};
tr[31584] = {H:"Шерстяш, у меня есть шикарный рецепт мороженого. Слушай."};
