tr[31602] = {H:"Шоколадка Чоко-Локо"};
tr[31603] = {H:"На этом дне рождения Шарарама я - звезда танцпола! Заходи в игру - отпразднуем вместе!"};
tr[31604] = {H:"Инструменты|Инструменты принесут через {0} мин."};
tr[31605] = {H:"Желток Йелло"};
tr[31606] = {H:"Стикеры " + "\"" + "Роботы" + "\"" + ""};
tr[31607] = {H:"Кресла из Корпорации клубов"};
tr[31608] = {H:"Нюша под наблюдением"};
tr[31609] = {H:"Возмутительно! Кто-то постоянно лезет в мою жизнь: разбрасывает вещи, ворует еду и следит за мной. Поклонник это или завистница? Спаси меня, прошу!"};
tr[31610] = {H:"Чтобы начать расследование, нарядимся детективами. Приходи в Дом мод."};
tr[31611] = {H:"Подбери наряд - сыграй в Студию моды и заработай {0} Смешинок."};
tr[31612] = {H:"Тренируем внимательность! Сыграй в Смешарики на Площади у Диско."};
tr[31613] = {H:"Я довольна. Мы теперь как настоящие детективы. Идём искать преследователя."};
tr[31614] = {H:"Нюша под наблюдением"};
tr[31615] = {H:"Я придумала: разбросаем снежки у меня в домике, и преследователь оставит на них свои следы."};
tr[31616] = {H:"Приходи в Ромашковую долину."};
tr[31617] = {H:"Зайди в домик Нюши и кинь там {0} помидоров."};
tr[31618] = {H:"Напиши {0} сообщений на Шарафон: " + "\"" + "Кидайте помидоры в Нюшином домике" + "\"" + "."};
tr[31619] = {H:"А преследователь хитёр. Он убрал все снежки, да ещё и посуду вымыл. Никаких следов не оставил!"};
tr[31620] = {H:"Нюша под наблюдением"};
tr[31621] = {H:"Изучим поведение преследователя. Я заманю его в море, а ты будешь издалека наблюдать."};
tr[31622] = {H:"Отвези меня в море - прокатись на Катере в Порту."};
tr[31623] = {H:"Скоротай время - сыграй в волейбол на Пляже и заработай {0} Смешинок."};
tr[31624] = {H:"Посмотри в Подзорную трубу на Пляже."};
tr[31625] = {H:"В море кто-то подбросил мне тёплую шапку и банку с грибным супом. Подозрительно..."};
tr[31626] = {H:"Нюша под наблюдением"};
tr[31627] = {H:"Я попросила Пина помочь сделать ловушку. Но ему нужны детали..."};
tr[31628] = {H:"Собери детали на конвейере в Стране роботов и заработай {0} Смешинок."};
tr[31629] = {H:"Пину нужна энергия. Добудь уголь - в игре " + "\"" + "Шахта" + "\"" + " в Стране роботов."};
tr[31630] = {H:"А ещё нужны инструменты. Собери {0} чемоданчика в Автосалоне."};
tr[31631] = {H:"Пин сделал ловушку. А в это время кто-то украл все мои пирожные и подменил на брокколи с чесноком. Ужас!"};
tr[31632] = {H:"Нюша под наблюдением"};
tr[31633] = {H:"В ловушку Пина попалась моя... бабушка. Оказывается, она просто тайком заботилась обо мне!"};
tr[31634] = {H:"Надо извиниться перед бабушкой. Напиши в чат: " + "\"" + "Извини, бабуля!" + "\"" + ""};
tr[31635] = {H:"Порадуй бабушку Позитивной энергией. Заработай {0} штук в любой игре."};
tr[31636] = {H:"Подарим бабуле букет - собери {0} фиалки в Джунглях."};
tr[31637] = {H:"Как хорошо, что бабушка обо мне заботится. И о тебе тоже - держи подарок!"};
