tr[31656] = {H:"Костюм " + "\"" + "Ловец призраков" + "\"" + ""};
tr[31657] = {H:"Я гроза призраков и лучший суперагент. Заходи в Шарарам и стань героем!"};
tr[31658] = {H:"Станция метро"};
tr[31659] = {OId:499,H:"Это мой город, мой район, моя станция. А колесо твоё. Крути и получай подарки."};
tr[31660] = {OId:270,H:"Цветы кактуса|Цветы распустятся\nчерез {0} мин."};
tr[31661] = {OId:270,H:"Экзамен? Посмотри на мою бороду - я давно уже закончил школу."};
tr[31662] = {H:"А Юве говорит, что никто на Зябре не знает, закончил ты школу или нет."};
tr[31663] = {OId:270,H:"Ахаха! Да, даже я не знаю, что я знаю. Но скажи мне, должен ли я знать?"};
tr[31664] = {H:"Вот и проверим!"};
tr[31665] = {OId:500,H:"Ооооррр-рр! Кругом. Одни. Ботаныы! Орррррррр!"};
tr[31666] = {H:"Привет, а ты кто? Ты зябриец?"};
tr[31667] = {OId:500,H:"Дааааа, после твоих экзаменов я стал последним двоечником на Зябре.... Аааааа, ботаны, ааааа!"};
tr[31668] = {H:"Сударь, извольте вести беседу пристойно, иначе диалог не состоится."};
tr[31669] = {H:"Да ты вообще что, это, давай сюда короче, где?"};
tr[31670] = {OId:500,H:"Ааааа, ты тоже один из них!!!! На Зябре одни умники!!! Я здесь всё разрушу! ААааа!"};
tr[31671] = {H:"Ясно. Вот она - сила невежества! Зябрийцев надо спасать."};
tr[31672] = {OId:500,H:"Ааааа, так ты понимаешь меня! На Зябре одни умники!!! Я здесь всё разрушу, ААААА!"};
tr[31673] = {H:"Зябрийцы мне дороги. Надо их спасать!"};
tr[31674] = {H:"Каска диггера"};
tr[31675] = {H:"Фон " + "\"" + "Стрит-арт" + "\"" + ""};
tr[31676] = {H:"Шапка " + "\"" + "Стрит" + "\"" + ""};
tr[31677] = {H:"Майка " + "\"" + "Стрит" + "\"" + ""};
