tr[31680] = {H:"Дом-Метро"};
tr[31681] = {OId:270,H:"Кликай на ракету и лети на Зябру!"};
tr[31682] = {OId:500,H:"Эррр, умники! Не отстану от вас, пока сам не поумнею!"};
tr[31683] = {OId:270,H:"Оррр задирает умников! Найди УМ в его доме, и Оррр успокоится."};
tr[31684] = {H:"подробнее"};
