tr[31689] = {H:"Фон " + "\"" + "Стрит-арт" + "\"" + ""};
tr[31690] = {H:"Смайлы " + "\"" + "Краски" + "\"" + " навсегда"};
tr[31691] = {H:"Шапка " + "\"" + "Стрит" + "\"" + ""};
tr[31692] = {H:"Майка " + "\"" + "Стрит" + "\"" + ""};
tr[31693] = {H:"Дом-Метро"};
