tr[31695] = {OId:270,H:"Это дом двоечника Оррра. Найди его УМ среди этого бардака..."};
tr[31696] = {H:"20 Смешинок"};
tr[31697] = {H:"СмеШутка " + "\"" + "Землетрясение" + "\"" + ""};
tr[31698] = {H:"СмеШутка " + "\"" + "Землетрясение" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь устраивать землетрясение ещё дней: {0}|Ты можешь устраивать землетрясение всегда!"};
tr[31699] = {H:"Смайлы " + "\"" + "Краски" + "\"" + ""};
tr[31700] = {OId:270,H:"Найди УМ, чтобы Оррр отстал от бедных зябрийцев!"};
tr[31701] = {OId:270,H:"Хнык-с, хнык-с... УМ сбежал от Оррра, где ж мы его теперь в этой Вселенной-то найдём..? Уу-уу-уу...."};
tr[31702] = {H:"Спокойствие. Ум на то ум. Если он сбежал от глупого Оррра, значит..."};
tr[31703] = {OId:270,H:"Ааа, ничего не соображаю. Мой собственный ум устал думать. У тебя есть идеи?"};
tr[31704] = {H:"УМ наверняка пошёл искать кого-то смышлённого. Того, кто оценит его."};
tr[31705] = {OId:270,H:"Да? Интересно, кто бы это мог быть... Явно не я."};
tr[31706] = {H:"Лосяш! Он любит книги, а ум ему нужен для знаний."};
tr[31707] = {H:"Пин! Ему нужен ум, чтобы изобретать."};
tr[31708] = {H:"Нюша! Её бы красоте да хороший ум - страшная будет сила!"};
tr[31709] = {OId:270,H:"А ты... умный! Отправляйся в Шарарам и посмотри, не спрятался ли УМ там."};
tr[31710] = {H:"Лечу!"};
tr[31711] = {OId:270,H:"Найди в Шарараме Смешарика, к которому сбежал УМ Оррра!"};
tr[31712] = {OId:270,H:"Приветствую, друг мой космический. Ты что-то ищешь?"};
tr[31713] = {H:"Да, Лосяш. Ты не видел, здесь УМ не пробегал?"};
tr[31714] = {OId:270,H:"Пробегал-пробегал! Поглядел на меня и сказал, что я, видите ли, скучный. Ну и скатертью ему дорожка!"};
tr[31715] = {H:"Лосяш, ты вовсе не скучный. Не пойму, почему УМ тебя так обидел."};
tr[31716] = {OId:270,H:"Он сказал, что ему мало просто знаний. Ему, видите ли, важнее практика и... красота."};
tr[31717] = {H:"Практика и красота... Значит, надо искать Нюшу или Пина. Спасибо!"};
tr[31718] = {OId:270,H:"Ищи Нюшу или Пина. Наверное, этот нахальный УМ убежал к ним!"};
tr[31719] = {OId:270,H:"Ох, почему так сложно считать?!! У меня 500 Смешинок. Я хочу купить 3 платья по 150 Смешинок. Сколько у меня останется?"};
tr[31720] = {H:"50 Смешинок. Нюша, ты не видела, здесь УМ не пробегал?"};
tr[31721] = {H:"Как видишь, я не калькулятор. И ответа у меня нет."};
tr[31722] = {OId:270,H:"УМ? Нет, я с ним не знакома. Но говорят, Пин начал странно себя вести и много умничать."};
tr[31723] = {H:"Спасибо, Нюша! Пойду искать Пина. А ты не расстраивайся - ум ведь не всем нужен."};
tr[31724] = {H:"Неправда, Нюша. Ты умная. Просто... по-своему. А я пойду поищу Пина."};
tr[31725] = {OId:270,H:"Ищи Пина! У него вроде есть УМ!"};
tr[31726] = {H:"Кликай на волшебную палочку, а потом на Смешарика, которого хочешь превратить."};
tr[31727] = {H:"Я наколдовал себе гору хороших оценок! Заходи в Шарарам и примани удачу."};
tr[31728] = {H:"Диван " + "\"" + "Отлично!" + "\"" + ""};
tr[31729] = {H:"Кеды " + "\"" + "Успей на перемену" + "\"" + ""};
tr[31730] = {H:"Рубашка " + "\"" + "Успей на перемену" + "\"" + ""};
tr[31731] = {H:"Комплект " + "\"" + "Успей на перемену" + "\"" + ""};
tr[31732] = {OId:270,H:"Уговори Пина отдать тебе УМ, а потом верни его на Зябру!"};
tr[31733] = {OId:270,H:"Ха-ха, наконец-то я получайт этот мощный космический ум. Теперь я создавайт армия железный Смешарик!"};
tr[31734] = {H:"Пин... Ты меня пугаешь. Зачем тебе роботы-смешарики?"};
tr[31735] = {OId:270,H:"Какой глупый вопрос! Робот-Смешарик не болеет, подчиняется приказам и не совершает ошибок. Он лучше обычный Смешарик."};
tr[31736] = {H:"Но разве может робот сочинить стих, написать симфонию или стать другом?"};
tr[31737] = {OId:270,H:"Найн! Зато робот может заменить ненадёжных Смешариков из Шарарам. И тогда быть порядок. Найн проблем, найн переживаний."};
tr[31738] = {H:"Да уж, Пин. Вот ты вроде умный, а от ума твоего одно горе."};
tr[31739] = {OId:270,H:"Верни УМ Оррру на Зябре!"};
tr[31740] = {OId:270,H:"Лишний УМ лишайт меня чувств - верни его на Зябру. А я теперь разбирайт этих злой робот на запчасти."};
tr[31741] = {OId:500,H:"Оррррр, орррр! Что это ты мне такое принёс?"};
tr[31742] = {H:"Это твой УМ! Кажется, тебе его очень не хватает."};
tr[31743] = {OId:500,H:"А мне и так хорошо! Посижу, поору, поем, посплю, потом снова поору. Зачем мне ещё ум?"};
tr[31744] = {H:"Те, у кого ума мало, злые. И те, у кого слишком много, злые. Так что ума должно быть у всех в меру!"};
tr[31745] = {H:"Костюм физика"};
tr[31746] = {H:"Костюм физрука"};
tr[31747] = {H:"Костюм химика"};
