tr[31864] = {OId:270,H:"Освободи путь на Площади у Больнички!"};
tr[31865] = {OId:270,H:"Освободи путь в Сити!"};
tr[31866] = {OId:270,H:"Освободи путь в Парке аттракционов!"};
tr[31867] = {OId:270,H:"Освободи путь на Площади у Диско!"};
tr[31868] = {OId:270,H:"Освободи путь в Порту!"};
tr[31869] = {OId:503,H:"Мы хотим знать про эту чудесную перчатку всё! Заставь Дока хоть что-нибудь сказать."};
tr[31870] = {OId:511,H:"Что?! Перчатка - это город с милыми существами? Дай-дай-дай! Дай мне посмотреть!"};
tr[31871] = {OId:504,H:"Дикий вервольф воровайт перчатка! Сделай что-нибудь с этот плохой собакен! Спасайт пришельцев!"};
tr[31872] = {OId:504,H:"Дикий вервольф воровайт перчатка! Сделай что-нибудь с этот плохой собакен! Спасайт пришельцев!"};
tr[31873] = {OId:502,H:"Смотри, что выросло у меня под гипсом! Путешествия в иные миры превратили мою руку в перчатку-артефакт."};
tr[31874] = {OId:270,H:"Док, эта штука... странная. Тебе нужна помощь?"};
tr[31875] = {OId:502,H:"Нужна! Этот артефакт... Моя прелесть. Он такой хрупкий. Нельзя никого к нему подпускать."};
tr[31876] = {OId:270,H:"Макс, а ты что думаешь?"};
tr[31877] = {OId:501,H:"Я пока не думаю. Деда, там тебя какие-то Смешарики спрашивают. Говорят, руки твоей хотят."};
tr[31878] = {OId:502,H:"Вот! Значит, пошёл по Шарараму слух о моей ценной руке. Надо её защитить."};
tr[31879] = {OId:270,H:"Кто-то уже хочет отобрать у тебя руку? А как защититься от них?"};
tr[31880] = {OId:502,H:"Надо добраться до лаборатории в Порту. Прогони на пути всех, кто хочет отобрать перчатку."};
tr[31881] = {OId:270,H:"Окей, Док. Я освобожу для тебя путь."};
tr[31882] = {OId:502,H:"Наконец-то. Здесь, на глубине моря, моим экспериментам ничто не помешает."};
tr[31883] = {OId:270,H:"Не за что, Док. Я помогал тебе, как мог."};
tr[31884] = {OId:502,H:"Да-да, ты должен гордиться тем, что скоро станешь частью моих гениальных опытов!"};
tr[31885] = {OId:270,H:"Подожди-ка. Что значит, стану частью?"};
tr[31886] = {OId:500,H:"Приффет! Легенды не вралли - однашшды на насс должен был взглянуть гигантский гласс, и вотт - ты смотришш на насс!"};
tr[31887] = {OId:270,H:"Я рад вас видеть. Но! Вы что, и вправду всё это время жили в гипсе Дока?"};
tr[31888] = {OId:500,H:"Мы жжили, не тужжили, строилли города, изобреталли и немношшко любовалисс собой в зеркалло. "};
tr[31889] = {OId:270,H:"О, а в вашем мире есть компьютерные игры?"};
tr[31890] = {OId:270,H:"Интересно, а музыку вы изобрели?"};
tr[31891] = {OId:270,H:"А какой у вас главный праздник?"};
tr[31892] = {OId:500,H:"Да. Мы повалльно играем в " + "\"" + "Королевскую жмякву" + "\"" + ". Это щщщекотка не выбывание. Побежждают самые стойкие."};
tr[31893] = {OId:270,H:"Вот в такой игре я бы всех победил."};
tr[31894] = {OId:270,H:"Прикольно. Играть я в такое, конечно, не буду."};
tr[31895] = {OId:500,H:"Да. Кажждый месяц мы усстраиваем батл кастрюлль - какая звонче на пол гроххнется. А потом и ххит-парад составляем."};
tr[31896] = {OId:270,H:"Я б скачал пару треков."};
tr[31897] = {OId:270,H:"У вас нет Бузовой??? Прощайте!"};
tr[31898] = {OId:500,H:"Нашш главвный праздник - " + "\"" + "День-лень" + "\"" + "! В честь него мы забираеммся на горку и катиммся с неё, ничего не делая. Пароччка даже Доку в ухо закатилась."};
tr[31899] = {OId:270,H:"Мне иногда так лень, что я даже скатиться не могу. "};
tr[31900] = {OId:270,H:"Я знаю парочку вещей, который вполне себе скатились!"};
tr[31901] = {OId:500,H:"В нашшем мире ещщё много интересного. Зовви сюда друззей Смешшариков. Мы тебе такое покажжем!"};
tr[31902] = {OId:270,H:"О! Сейчас позову, ждите!"};
tr[31903] = {OId:507,H:"Друзья мои неаккуратные, как же так? Не уследили вы за перчаткой."};
tr[31904] = {OId:506,H:"Йа, йа! О такой ценный вещь нужно заботиться!"};
tr[31905] = {OId:505,H:"Бедные жители перчатки... Их дом разрушен."};
tr[31906] = {OId:270,H:"Ну вот напали! Все иногда ошибаются. Даже Док."};
tr[31907] = {OId:507,H:"Нет! Я не ошибаюсь. Отдайте перчатку мне!"};
tr[31908] = {OId:506,H:"Найн! Я построить для перчатка крепкий броня. Отдайте мне."};
tr[31909] = {OId:505,H:"Нет, только я смогу окружить жителей перчатки нежностью и заботой."};
tr[31910] = {OId:270,H:"Нет уж! Лучше я заберу перчатку себе домой."};
tr[31911] = {OId:270,H:"А, может, самих жителей перчатки спросим?"};
tr[31912] = {OId:507,H:"Я не согласен! Вы ничего не понимаете в перчатках!"};
tr[31913] = {OId:509,H:"Тааа-к! Вообще-то это мой гипс. И моя перчатка. Заберу себе!"};
tr[31914] = {OId:505,H:"Вот все вы такие! Нет, чтобы уступить бедной девочке... МНЕ!!!"};
tr[31915] = {OId:270,H:"Ах так! Я сейчас полицию позову!"};
tr[31916] = {OId:507,H:"..."};
tr[31917] = {OId:510,H:"Эх, как жалль, что из-за насс вы сссоритесь. Придётся жжителям перчатки покинуть Шаррарам. Шштобы вы снова сталли друзьями."};
tr[31918] = {OId:505,H:"Стыдно..."};
tr[31919] = {OId:270,H:"Перчаточки? Как вы? У вас всё в порядке?"};
tr[31920] = {OId:510,H:"Да! Мы успелли отреммонтировать вссе домма, пострроить свой космодром. И вот... Мы уллетаем! Прощщайте!"};
tr[31921] = {OId:270,H:"Куда? Уже? А мы? Стойте..."};
tr[31922] = {OId:509,H:"Эксперимент провален. Контакт с неизвестным милым народом не состоялся."};
tr[31923] = {OId:508,H:"Деда, а как же пришельцы у меня на голове? Одни на ракете улетели, а эти на голове-то остались."};
tr[31924] = {OId:270,H:"Макс, значит, пришельцы сейчас у тебя на голове?"};
tr[31925] = {OId:508,H:"Да, им понравился Шарарам. Поэтому они попрощались со своими братьями и остались. И теперь строят в моей шапке новый город!"};
tr[31926] = {OId:270,H:"Ну у вас и семейка с Доком! А что говорят сами жители перчатки?"};
tr[31927] = {H:"Я поймал мудрых щук! Сказка ждёт тебя в Шарараме!"};
tr[31928] = {H:"Урок Волшебного Компаса"};
tr[31929] = {H:"Ковёр-компас"};
tr[31930] = {H:"Клуб на Луне"};
tr[31931] = {H:"На Луне гравитация ниже, а танцы и прыжки - выше!|Лучший клуб для лунной походки.|Бонус: фасад в подарок!"};
tr[31932] = {H:"Машина времени"};
tr[31933] = {H:"Город-перчатка"};
tr[31934] = {H:"10 луп"};
tr[31935] = {H:"3 лупы"};
tr[31936] = {OId:270,H:"Прикоснись к чудесам Лукоморья и получи дары!"};
tr[31937] = {H:"Морские шарики"};
tr[31938] = {H:"Свитшот Жар-птицы"};
tr[31939] = {H:"Магия " + "\"" + "Летучий корабль" + "\"" + ""};
tr[31940] = {H:"Лукоморье"};
tr[31941] = {H:"Дом " + "\"" + "Лукоморье" + "\"" + ""};
tr[31942] = {H:"В Шарараме чудеса: города растут на голове, а перчатки летают в космос. Заходи в игру!"};
tr[31943] = {OId:270,H:"Открою секрет. Белки будут очень довольны, если ты посадишь деревья не абы как, а.."};
tr[31944] = {H:"А как, Копатыч?"};
tr[31945] = {OId:270,H:"Дык я сам не знаю. Но, говорят, в лабиринте растёт мудрый Кедр, он тебе объяснит."};
tr[31946] = {H:"А с чего это я буду слушаться какого-то кедра?"};
tr[31947] = {OId:270,H:"Решай сам. Можешь посадить деревья, как тебе нравится. А можешь найти Кедр и спросить у него."};
tr[31948] = {H:"Спасибо, что предупредил, Копатыч."};
tr[31949] = {H:"Картуз " + "\"" + "Раздолье" + "\"" + ""};
tr[31950] = {H:"Косоворотка " + "\"" + "Нива" + "\"" + ""};
tr[31951] = {H:"Лукоморье"};
tr[31952] = {H:"Магия " + "\"" + "Летучий корабль" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь летать на корабле ещё дней: {0}|Ты можешь летать на корабле всегда"};
