tr[32100] = {OId:512,H:"В отель принесли записку. Прочитай её. Вон она - на столе лежит."};
tr[32101] = {OId:512,H:"Найди зверей в Шарараме и убедись, что с ними всё в порядке."};
tr[32102] = {OId:512,H:"Молодец! Скорее расскажи Шефу о бедных зверях из Австралии."};
tr[32103] = {OId:512,H:"Прочитай новую записку от таинственного доброжелателя."};
tr[32104] = {OId:512,H:"Отвези зверей в новый дом. Адрес написан в записке вон там на столе."};
tr[32105] = {OId:512,H:"Перевези зверей в особняк Мадам Жабо."};
tr[32106] = {OId:512,H:"Проведай зверей в особняке мадам Жабо. Кликай на записку, чтобы отправиться к ней."};
tr[32107] = {OId:512,H:"Тебя искал Смешарик, спрятавшийся в куст. Ищи его на Пляже"};
tr[32108] = {OId:512,H:"Смешарик-куст уехал в особняк Мадам Жабо. Следуй и ты за ним: кликни на записку и вызови такси."};
tr[32109] = {OId:270,H:"Смешарик-куст уехал в особняк Мадам Жабо. Следуй и ты за ним: кликни на записку и вызови такси."};
tr[32110] = {OId:270,H:"Фырк-фырк-фырк..."};
tr[32111] = {OId:512,H:"Помоги графу приготовить шампунь, чтобы вернуть зверям шерсть."};
tr[32112] = {OId:512,H:"Граф приготовил для тебя награду. Поговори с ним!"};
tr[32113] = {OId:516,H:"Агенты узнали, что со зверями плохо обращаются. Сознавайтесь, граф!"};
tr[32114] = {OId:513,H:"Я?! Мои звери в отличной форме. Им просто не хватает... ДИСЦИПЛИНЫ!"};
tr[32115] = {H:"Поэтому вы, Граф, не кормите, не ухаживаете и держите бедных зверей на холоде?"};
tr[32116] = {OId:513,H:"Неправда. Я обеспечиваю своих зверей самым лучшим... КОНТРОЛЕМ!"};
tr[32117] = {H:"Неправда! Я видел, что за зверями никто не ухаживает."};
tr[32118] = {OId:516,H:"Всё ясно. За жестокое обращение с животными вы, Граф, будете изгнаны из Шарарама."};
tr[32119] = {OId:513,H:"Да как вы смеете?! Подождите, я готов сотрудничать и признать свою полную... НЕВИНОВНОСТЬ!"};
tr[32120] = {H:"Бррр, вы всегда так кричите, Граф? Шеф, забирай его. Дело раскрыто. Звери спасены."};
tr[32121] = {OId:270,H:"Спасибо! Эх, как приятно спасать зверей, попавших в беду."};
tr[32122] = {H:"Мадам, вы держите в подвале летучих мышей?"};
tr[32123] = {OId:270,H:"А почему нет? У мышей в пещере был обвал, вот и приютила их у себя. Я друг всех животных."};
tr[32124] = {H:"Здорово! А я спас австралийских зверей от Графа Амфибиса."};
tr[32125] = {OId:270,H:"Молодец! Это ведь я прислала тебе ту записку. Давно за ним наблюдала и подозревала неладное."};
tr[32126] = {H:"Так значит, зверюшек можно поселить у вас?"};
tr[32127] = {OId:270,H:"Да! Как видишь, живу я не бедно - зверей смогу обеспечить всем необходимым."};
tr[32128] = {H:"Класс! Тогда я привезу зверушек сюда."};
tr[32129] = {OId:270,H:"Здравствуй. Говори тише, а то нас могут... УСЛЫШАТЬ!"};
tr[32130] = {H:"Какой знакомый крик... Кто ты? И зачем спрятался?"};
tr[32131] = {OId:270,H:"Здесь не место для спокойного... РАЗГОВОРА! Встретимся в укромном месте."};
tr[32132] = {H:"В каком?"};
tr[32133] = {OId:270,H:"Я Граф Амфибис. И прячусь в кустах, потому что Шеф меня любезно... ИЗГНАЛ!"};
tr[32134] = {H:"И правильно. Ты жестоко обращался со зверями. А теперь они в безопасности. "};
tr[32135] = {OId:270,H:"Всё не так! Мадам Жабо - моя давняя знакомая. Мы с ней хорошие... ВРАГИ! А знаешь почему?"};
tr[32136] = {H:"Потому что мадам защитница зверей, а ты им вредишь?"};
tr[32137] = {OId:270,H:"Наоборот! Мадам Жабо - браконьер. Она давно мечтала завладеть зверями из Австралии, и любезно меня... ПОДСТАВИЛА."};
tr[32138] = {H:"Ты, возможно, прав. Это объясняет, почему у неё в особняке столько мехов. "};
tr[32139] = {H:"Так вот зачем она дала мне Смешинку... Чтобы откупиться!"};
tr[32140] = {OId:270,H:"Нет времени спорить. Мадам нужен мех. Спаси зверей, пока она не успела их... ПОДСТРИЧЬ!"};
tr[32141] = {OId:270,H:"Проверим. Вызываем такси и едем обратно к ней."};
tr[32142] = {OId:515,H:"Граф сдержал своё слово. Как видишь, всё, что я тебе говорил было бессовестной... ПРАВДОЙ! "};
tr[32143] = {H:"Эх, мадам... Вы меня обманули. Вы вовсе не любите зверей."};
tr[32144] = {OId:514,H:"Почему же? Люблю. Мне нравится их мех. Что такого? Ну посидят немного лысые. Шерсть ведь отрастёт. И снова можно стричь!"};
tr[32145] = {H:"А улики против графа - тоже ваших рук дело?"};
tr[32146] = {OId:514,H:"Аа, немного шантажа там, немного подлога тут. Должна же я была как-то вырвать зверей из рук Графа."};
tr[32147] = {H:"Бедные звери! Граф, увезём их прочь от этой браконьерши?"};
