tr[32433] = {H:"Бараш вошёл в раж!"};
tr[32434] = {H:"Приве-еет! Сыграем в игру? Я буду сочинять стихи, а ты поддержи мои рифмы делом."};
tr[32435] = {H:"Ух ты, ух ты! Приходи играть в Бухту!"};
tr[32436] = {H:"Не унывай - Позитивную энергию собирай! Собери {0} штук в играх."};
tr[32437] = {H:"Не время для спячки - сыграй в Скачки."};
tr[32438] = {H:"Моим стихам все рады, а ты забирай награду!"};
tr[32439] = {H:"Бараш вошёл в раж!"};
tr[32440] = {H:"Рифмы не кончаются - веселье продолжается!"};
tr[32441] = {H:"Горит костёр, язык остёр! Приходи на посиделки в Дремучий лес."};
tr[32442] = {H:"Выйди на тропинку - собери малинку. Сыграй в Дары леса и заработай {0} Смешинок."};
tr[32443] = {H:"Собери орехи - обрети успехи. Добудь {0} штук в лесу."};
tr[32444] = {H:"Я сочиняю без заминки, а ты лови за помощь Смешинки!"};
tr[32445] = {H:"Бараш вошёл в раж!"};
tr[32446] = {H:"Какое хорошее настроение! Посвящу Нюше стихотворение!"};
tr[32447] = {H:"Нюша прекрасна от природы, а ты приходи в Дом моды."};
tr[32448] = {H:"Тебя ждёт модная карьера: любуйся Нюшей - играй в модельера!"};
tr[32449] = {H:"Напиши комплимент в общий чат: " + "\"" + "Нюшу я всегда видеть рад!" + "\"" + ""};
tr[32450] = {H:"У тебя всё получается! А у меня, кажется, идеи кончаются..."};
tr[32451] = {H:"Бараш вошёл в раж!"};
tr[32452] = {H:"Я теряю вдохновение... Мои стихи слишком простые. Придумаю что-то посерьёзнее!"};
tr[32453] = {H:"Дом - не музей. В гости позови друзей! Прими в домике {0} гостей."};
tr[32454] = {H:"Не нужен нам отдых на яхтах. Сыграй в Стране роботов в Шахты."};
tr[32455] = {H:""};
tr[32456] = {H:"Я кладу Смешинки в твой карман, чтобы их не сдуло ветром в ураган."};
tr[32457] = {H:"Бараш вошёл в раж!"};
tr[32458] = {H:"Я нашёл в Шарараме место, для которого не могу придумать рифму."};
tr[32459] = {H:"Приходи на Площадь у Больнички."};
tr[32460] = {H:"Отправь {0} сообщений на Шарафон: " + "\"" + "А ты можешь сочинить стих про Площадь у Больнички?" + "\"" + ""};
tr[32461] = {H:"Поищи вдохновение в рисовании. Сыграй в " + "\"" + "Волшебный карандаш" + "\"" + "."};
tr[32462] = {H:"Больничка-невеличка? Маги-флаги? Ух, уйду размышлять о рифмах в ночь. А ты лови подарок!"};
