tr[32486] = {H:"Секвойя в домик"};
tr[32487] = {H:"Я стал друидом! Приходи в Шарарам и овладей магией природы!"};
tr[32488] = {OId:270,H:"Я знаток зоологии. Расскажу тебе, кому плавники нужны для полётов, кто спит стоя, а кто слышит без ушей."};
tr[32489] = {H:"Я сплю стоя! Но урок с удовольствием пройду. "};
tr[32490] = {OId:270,H:"Друид помогает животным. И ты помоги мне спасти пчёл."};
tr[32491] = {H:"Пчёлы в беде? Что случилось?"};
tr[32492] = {OId:270,H:"Злые осы накормили их пыльцой забывчивости. Теперь пчёлы не помнят, что делают и как вернуться домой."};
tr[32493] = {H:"Сейчас всё исправим."};
tr[32494] = {OId:440,H:"Чтобы не плутать в лесу, научись различать деревья. Я помогу тебе! Отправляемся в лес!"};
tr[32495] = {H:"Надеюсь, я не потеряюсь."};
tr[32496] = {OId:270,H:"Я расскажу тебе о природе морских глубин! Готов ко встрече с их жителями?"};
tr[32497] = {H:"Готов!"};
tr[32498] = {H:"Бейсболка " + "\"" + "ПапаРоб" + "\"" + ""};
tr[32499] = {OId:270,H:"Надеюсь, ты не забыл сменку... и голову."};
tr[32500] = {OId:519,H:"Мона, мы ищем Золотой дневник, который исправляет плохие оценки. Слышала о таком?"};
tr[32501] = {OId:150,H:"Может, слышала, а может, нет. Он же обманывает учителей. Ай-ай-ай."};
tr[32502] = {H:"Мона права. Жульничать - фу. Лучше подготовимся к экзамену - запрёмся в библиотеке на 40 часов."};
tr[32503] = {OId:150,H:"Вы чего? Библиотека закрыта на ремонт! Видимо, у вас и правда нет выхода..."};
tr[32504] = {H:"Мона, тогда расскажешь про дневник?"};
tr[32505] = {OId:521,H:"Впервые вижу, чтобы ученика убрали со школьной фотографии."};
tr[32506] = {OId:520,H:"Может, золотой дневник придумал он? И все за это на него обиделись."};
tr[32507] = {H:"Точно! Но как его теперь найти? Если даже фото с ним испортили."};
tr[32508] = {OId:521,H:"Может, кто-то его помнит? Или где-то остался шкафчик с его вещами?"};
tr[32509] = {H:"Гардеробщица Фёкла! Она всех школьников должна помнить!"};
tr[32510] = {OId:522,H:"Точно! Давай спросим у неё."};
tr[32511] = {H:"Ок, вперёд к Фёкле!"};
tr[32512] = {H:"Подождите, у меня вопрос. Фёкла - не морской житель. Откуда она здесь?"};
tr[32513] = {OId:521,H:"Говорят, она не Смешарик, а компьютерный персонаж, а мир вокруг нас это иг..."};
tr[32514] = {OId:520,H:"Ох, брось эти глупости! Просто Фёкла трудоголик. Берётся за любую работу, даже подводную."};
tr[32515] = {H:"Класс! Узнаём у неё, где дневник."};
tr[32516] = {OId:270,H:"Поговори с Фёклой!"};
tr[32517] = {H:"Коробка конфет|Конфеты принесут через {0} мин."};
tr[32518] = {OId:270,H:"Золотой дневник как мои золотые годы... Безвозвратно потерян."};
tr[32519] = {OId:270,H:"Говорят, шкафчик вынесли на Школьный двор. Ищи его там!"};
tr[32520] = {OId:519,H:"Кроме ключа ничего не было? Какой от него толк, если мы не знаем, что открывать?"};
tr[32521] = {OId:150,H:"Тут должна быть какая-то зацепка... Но я пока не понял, где."};
tr[32522] = {H:"Сколько замков в Шарараме? Проверим каждый!"};
tr[32523] = {H:"А как насчёт этого морского конька? Вдруг он держит ключ не случайно?"};
tr[32524] = {OId:519,H:"Да это займёт двести лет! Лично у меня нет столько времени."};
tr[32525] = {OId:270,H:"Да вряд ли... Ого! Конёк стал светиться!"};
tr[32526] = {H:"Смотрите! Этот луч света указывает на статую. Дневник наверняка у неё."};
tr[32527] = {OId:270,H:"Кликни на статую - вдруг дневник спрятан в ней."};
tr[32528] = {H:"Кресло директора"};
tr[32529] = {H:"Рабочее место"};
tr[32530] = {H:"Кулер"};
tr[32531] = {H:"Уголок печати"};
