tr[32540] = {H:"Мотороллер"};
tr[32541] = {H:"Походный столик"};
tr[32542] = {H:"Походный фонарь"};
tr[32543] = {H:"Газон"};
tr[32544] = {H:"Стойка приёмной"};
tr[32545] = {H:"Стикеры"};
tr[32546] = {OId:519,H:"Двоечник-Чёртик следил за нами и украл дневник."};
tr[32547] = {OId:150,H:"Мой... дневник... экзамен... всё."};
tr[32548] = {H:"А что это такое звенит?"};
tr[32549] = {OId:519,H:"Это звонок на урок. Скорее бежим - экзамен начинается!"};
tr[32550] = {OId:150,H:"Я не могу. Я не готов. Мне поставят два."};
tr[32551] = {H:"Эх, двоек бояться - в школу не ходить. Озик, не волнуйся. Мы прорвёмся!"};
tr[32552] = {OId:270,H:"Ура, это дневник! Скорее хватай его."};
tr[32553] = {OId:270,H:"Поддержи Озика на экзамене. Кликай на вход в класс."};
tr[32554] = {H:"Ведьмин дом"};
tr[32556] = {OId:524,H:"Днивник роботает! Смотрити - учитель скозал што у миня кол, а в днивнике стоит 5!!!"};
tr[32557] = {OId:525,H:"Эта пятёрка... она была моей... Ух, если бы не ты, хулиган!"};
tr[32558] = {H:"Ну и что? Главное не оценки, а реальный ум."};
tr[32559] = {H:"Немедленно отдай дневник, чёртик! Он принадлежит нам!"};
tr[32560] = {OId:523,H:"Гаварити што хатити! За пятёрку мне дадут лишнюю ниделю коникул - пойду одыхать, чао!"};
tr[32561] = {OId:150,H:"А мне на каникулах придётся ходить в школу и исправлять оценки... Эх."};
tr[32562] = {H:"Озик, не волнуйся. Мы что-нибудь придумаем."};
tr[32563] = {OId:270,H:"Учитель вызвал тебя к себе. Кликни на дверь, чтоб отправиться к нему."};
tr[32681] = {OId:150,H:"Неужели вы думали, что я его не узнаю? Дневник, который я изобрёл."};
tr[32682] = {H:"Вы? Так значит, тот школьник... Это вы?"};
tr[32683] = {OId:150,H:"Да. Я был любопытным учеником и придумал, как перекрашивать оценки с помощью кальмаровых чернил."};
tr[32684] = {H:"И теперь у Чёртика ваша единица в пятёрку перекрасилась! Разве это справедливо?"};
tr[32685] = {OId:150,H:"Оценки в дневнике перекрашивается не сразу, а ровно в полночь. Сейчас я поставил туда 5. А завтра утром это будет уже 1."};
tr[32686] = {H:"Стоппп... Значит, Чёртик в итоге получит заслуженную оценку?"};
tr[32687] = {OId:150,H:"Конечно! А вот ваша находчивость в поисках дневника меня поразила. Так что вы с Озиком заслуживаете честной пятёрки!"};
tr[32688] = {H:"Ура! Пойду поделюсь с ним этой крутой новостью!"};
tr[32689] = {H:"Морской трон"};
tr[32690] = {H:"Морская форма"};
tr[32691] = {H:"Я стал отличником в Подводной школе. Самые весёлые уроки ждут тебя в Шарараме!"};
tr[32692] = {H:"Подводная школа"};
tr[32693] = {H:"Лаборантская"};
tr[32694] = {OId:270,H:"Я просто жду звонок на урок..."};
tr[32695] = {H:"Голубой жилет"};
tr[32696] = {H:"Платье " + "\"" + "Сердце" + "\"" + ""};
tr[32697] = {H:"Карта Модератора на 30 дней.|Помгогай другим Смешарикам!|Черный шарафон в подарок!"};
tr[32698] = {H:"Ледяной плащ"};
tr[32699] = {H:"Кажется, снег начинается... Встречай зиму в Шарараме!"};
tr[32700] = {H:"Умникус не в себе"};
tr[32701] = {H:"Приходи на мой урок - сегодня будем превращать принцесс в лягушек."};
tr[32702] = {H:"Приготовься варить зелье. Собери Дары леса и заработай {0} Смешинок."};
tr[32703] = {H:"Набери морской воды. Спустись в Подводный мир."};
tr[32704] = {H:"Покорми принцесс. Поработай в кафе на Пляже и заработай {0} Смешинок."};
tr[32705] = {H:"Ха-ха, шутка! Не будем никого превращать. Но зелье вышло вкусным, спасибо!"};
tr[32706] = {H:"Умникус не в себе"};
tr[32707] = {H:"Узнал меня? Это же я, Крош. Я выпил волшебное зелье и превратился в Умникуса."};
tr[32708] = {H:"Давай разыграем Смешариков. Приходи в Школу магов."};
tr[32709] = {H:"Напиши в общий чат: " + "\"" + "Учитель в классе, всем встать!" + "\"" + ""};
tr[32710] = {H:"Подготовь доску к уроку. Сыграй в Волшебный карандаш."};
tr[32711] = {H:"Упс! Пока мы играли, я потерял свиток с заклинанием, которое расколдует меня. Ой-ой..."};
tr[32712] = {H:"Умникус не в себе"};
tr[32713] = {H:"Я не могу превратиться обратно в Кроша. Вдруг Умникус увидит - вот беда!"};
tr[32714] = {H:"Попробуем найти свиток. Посети {0} клубов."};
tr[32715] = {H:"Может, свиток унесло в море? Посмотри в подзорную трубу на Пляже."};
tr[32716] = {H:"Поищи свиток на Пляже. Сыграй в Секретики."};
tr[32717] = {H:"Мы нашли обрывок свитка. На нём отпечаток лапы вора. Значит, свиток похитили."};
tr[32718] = {H:"Умникус не в себе"};
tr[32719] = {H:"Свиток превращения утащили чудики. Скорее в погоню!"};
tr[32720] = {H:"Накопи Позитивную энергию. Найди {0} штуки в Шарараме."};
tr[32721] = {H:"Найди в Шарараме {0} чудиков и прогони."};
tr[32722] = {H:"Спасибо! Ты вернул свиток, и теперь я смогу вернуть себе истинный облик!"};
tr[32723] = {H:"Умникус не в себе"};
tr[32724] = {H:"Уф, еле успели! Надеюсь, Умникус простит мне все шалости. Давай сделаем для него подарок."};
tr[32725] = {H:"Напиши {0} сообщений на Шарафон: " + "\"" + "Что подарить Умникусу?" + "\"" + "."};
