tr[32765] = {OId:270,H:"Снежинка подскажет тебе путь к вершине!"};
tr[32766] = {OId:270,H:"Кликай на ёлку - спасём игрушки вместе!"};
tr[32767] = {OId:528,H:"Кто-то принёс нам новогодний подарок! Проверь его!"};
tr[32768] = {OId:270,H:"Кошка подскажет тебе путь к вершине!"};
tr[32769] = {OId:270,H:"Мишка подскажет тебе путь к вершине!"};
tr[32770] = {OId:270,H:"Заяц подскажет тебе путь к вершине!"};
tr[32771] = {OId:270,H:"Сова подскажет тебе путь к вершине!"};
tr[32772] = {OId:270,H:"Бандиты устроили завал - здесь не пройти. Вернись к игрушкам и найди другой путь."};
tr[32773] = {H:"Вернуться"};
tr[32774] = {OId:270,H:"Вот тебе привет от бандитов! Мы заморозили звезду - попробуй только загадать желание!"};
tr[32775] = {OId:527,H:"Спасибо, что пришёл на помощь! Злые игрушки затаились где-то здесь, на ёлке."};
tr[32776] = {H:"Давай сразу к делу. Как мне их победить?"};
tr[32777] = {H:"Расскажи подробнее о злых игрушках."};
tr[32778] = {OId:527,H:"Загадай желание у звезды на макушке ёлки - пожелай, чтобы бандиты ушли. "};
tr[32779] = {H:"Взобраться на самую макушку? Хорошо, спрошу путь у игрушек."};
tr[32780] = {OId:527,H:"Раньше эти игрушки тоже висели на ёлке, но потом их заменили новыми и убрали в коробку."};
tr[32781] = {H:"О, так вот, почему они обиделись и разозлились!"};
tr[32782] = {OId:527,H:"А потом они тайком выбрались из коробки, стали нападать на нас и побили гирлянду."};
tr[32783] = {H:"О ужас! Надо скорее их остановить!"};
tr[32784] = {OId:528,H:"Кто ты? Совсем не похож на игрушку - уходи-ка лучше с ёлки."};
tr[32785] = {H:"Привет, смешной снеговик. Что с тобой случилось?"};
tr[32786] = {OId:528,H:"А-а-а, злые игрушки разукрасили меня. Помоги мне очиститься, а я тебе дальше пропущу."};
tr[32787] = {H:"А как?"};
tr[32788] = {OId:530,H:"Привет! Однажды ты уже спас эту ёлку. Но тебе удалось обмануть само время, и вот ты снова здесь!"};
tr[32789] = {H:"Привет, Йожик. А ты что здесь делаешь?"};
tr[32790] = {OId:530,H:"Я, дух Новогоднего веселья. Разгадай мои загадки, и я открою тебе путь к вершине! Скажи, какого цвета ёлка летом?"};
tr[32791] = {H:"Жёлтая."};
tr[32792] = {H:"Зелёная."};
tr[32793] = {H:"Синяя."};
tr[32794] = {OId:530,H:"Это было легко. Вот тебе загадка сложнее: в какую одежду наряжают новогоднюю селедку?"};
tr[32795] = {H:"В мундир."};
tr[32796] = {H:"В худи."};
tr[32797] = {H:"В шубу."};
tr[32798] = {OId:530,H:"Молодец! Вот последний вопрос: любимая игрушка Нюши - Тузя, он кто?"};
