tr[32811] = {H:"Оп! Пора уносить ноги."};
tr[32812] = {OId:533,H:"Загадай желание, и новогоднее чудо свершится!"};
tr[32813] = {H:"Хочу, чтобы летом было тепло!"};
tr[32814] = {H:"Хочу на этих праздниках угоститься сладостями!"};
tr[32815] = {H:"Хочу спасти Нюшу и вернуть ёлке волшебство!"};
tr[32816] = {OId:533,H:"Будет исполнено. У тебя осталось два желания!"};
tr[32817] = {H:"Хочу, чтобы летом было тепло!"};
