tr[33180] = {H:"Самолётомёт"};
tr[33181] = {H:"Я отыскал сокровища нарисованной страны. В Шарараме и тебя ждут сюрпризы!"};
tr[33182] = {H:"Сначала помоги Карычу исправить другие экспонаты."};
tr[33183] = {H:"В джунгли идти опасно. Сначала поговори с маркизой."};
tr[33184] = {OId:270,H:"Проверь главный экспонат музея!"};
tr[33185] = {OId:270,H:"Найди Лосяриуша! Кликай на проход в Марараш."};
tr[33186] = {OId:270,H:"Найди Лосяриуша! Кликай на Лосяша в Ромашковой долине."};
tr[33187] = {OId:270,H:"Ищи Лосяриуша в джунглях!"};
tr[33188] = {OId:270,H:"Друг мой спасающий, спасибо! Не забудь помочь и Кар-Лумбу!"};
tr[33189] = {OId:270,H:"Дружище, спасибо! Не забудь помочь и Лосяриушу!"};
tr[33190] = {OId:270,H:"Спасибо, что вернул Кар-Лумба и Лосяриуша! Поболтай с ними о своих делах."};
tr[33191] = {OId:270,H:"Вот тебе и музей... Эта штука была такой древней, что рассыпалась от старости."};
tr[33192] = {H:"Бывает... Подыщем тебе новый экспонат."};
tr[33193] = {OId:270,H:"Но ведь вертушка удерживала землю в равновесии! Теперь Шарарам перевернётся и снова станет страной наоборот, Марарашем."};
tr[33194] = {H:"А что это за страна?"};
tr[33195] = {OId:270,H:"Её открыли наши предки. В Марараше шли ливни из клубники, рыбы росли на огороде, а Смешарики ходили на голове."};
tr[33196] = {H:"Ура! О таком Шарараме я всегда и мечтал."};
tr[33197] = {H:"Ну нет! Не надо переворачивать Шарарам."};
tr[33198] = {OId:270,H:"Ну и хорошо. Подождём, пока всё перепутается: одежда превратится в кашу, а домики улетят на небо бабочками."};
tr[33199] = {H:"Эй, так уже не интересно! Не надо переворачивать Шарарам."};
tr[33200] = {OId:270,H:"Тогда надо восстановить вертушку. Её изобрёл Лосяриуш - предок Лосяша из Марараша."};
tr[33201] = {H:"А где мне его найти?"};
tr[33202] = {OId:270,H:"Смотри! За нами открылся портал в древний Марараш - кликай на него!"};
tr[33203] = {H:"Хорошо! Пойду и разыщу Лосяриуша в Марараше."};
tr[33204] = {OId:270,H:"Привет! "};
tr[33205] = {H:"Привет, маркиза. Я прилетел из далёкого будущего. Не видела здесь Лосяриуша?"};
tr[33206] = {OId:270,H:"Лосяриуш с Кар-Лумбом ушли в джунгли исследовать эту загадочную страну. А я вот клубничкой балуюсь!"};
tr[33207] = {H:"Приятного аппетита! Пойду проверю джунгли."};
tr[33208] = {OId:399,H:"Друг мой любознательный, зачем ты прибыл из далёкого будущего в наши дремучие времена?"};
tr[33209] = {H:"Лосяриуш, у нас в учебниках сказано, что ты перевернул Марараш и сделал его Шарарамом."};
tr[33210] = {OId:399,H:"Я?! Но это же невозможно! Да, мы долго думали, как облагородить эти дикие земли, но решения не нашли..."};
tr[33211] = {H:"Не может быть! В Шарараме всё это время была вертушка, которую ты изобрёл!"};
tr[33212] = {OId:399,H:"Вертушку? Я?"};
tr[33213] = {H:"Да. Теперь она сломана, Шарарам вот-вот перевернётся обратно, и снова станет диким Марарашем..."};
tr[33214] = {OId:399,H:"Ну раз ты сам видел эту... вертушку. Может, расскажешь, как она выглядела?"};
tr[33215] = {H:"У неё были такие штуки по краям, и вот такая вот часть в середине."};
tr[33216] = {H:"Она была примерно такого размера, но вот тут чуть меньше, а там - больше..."};
tr[33217] = {OId:399,H:"Я почти представил это устройство, но кое-каких деталей не хватает. Давай заглянем в твои воспоминания о вертушке!"};
tr[33218] = {H:"Воспоминания? Мои? А как?"};
tr[33219] = {OId:399,H:"Феноменально! Теперь я вижу, как сделать вертушку - она и вправду сможет перевернуть Марараш!"};
tr[33220] = {H:"Значит, ты создашь Шарарам, а я не дам ему повернуться обратно!"};
tr[33221] = {OId:399,H:"За работу! Помоги мне собрать вертушку!"};
