tr[33426] = {H:"Эйджей, опомнись! Рыбы не умеют говорить!"};
tr[33427] = {OId:546,H:"Злобикус не обманул. Он превращает в рыбу всех, кто отказывается петь на турнире!"};
tr[33428] = {H:"Сумрак, ты оборотень. Сможешь взять след и понять, как Сяо сделали рыбой?"};
tr[33429] = {OId:546,H:"Спрашиваешь? Да у меня идеальное чутьё на тёмную магию!"};
tr[33430] = {H:"В точку! Узнаем, что за колдовство использует Злобикус."};
tr[33431] = {OId:543,H:"Узнай, куда ведёт магический след у Больнички!"};
tr[33432] = {H:"Сначала поговори с Сиреной!"};
tr[33433] = {OId:270,H:"Это Замок Злобикуса. Пробравшись туда, ты узнаешь, как остановить его зловещий турнир."};
tr[33434] = {H:"Вперёд, Сирена! Покажем этой злюке, кто здесь хозяин."};
tr[33435] = {OId:270,H:"Но сейчас на это нет времени... Беги в Студию на концерт, пока Злобикус не превратил артистов в рыбок!"};
