tr[33444] = {OId:543,H:"Проберись в замок Злобикуса у Больнички!"};
tr[33445] = {OId:270,H:"Пока не начался концерт, проберись к Злобикусу и узнай, как он околдовал артистов."};
tr[33446] = {OId:380,H:"Я занят, занят, слишком занят, чтобы выгонять тебя."};
tr[33447] = {OId:543,H:"Поговори с Сумраком у Больнички!"};
tr[33448] = {OId:270,H:"Я нашёл один браслет и у себя - Злобикус уловкой нацепил их на всех!"};
tr[33449] = {H:"Снимем браслет - спасём артистов! Выброси его, Сумрак!"};
tr[33450] = {OId:270,H:"Я... Сейчас... Рррр... Ещё разок... Бррр.. Ух... Не получается!"};
tr[33451] = {H:"Перекрути его - сам отвалится."};
tr[33452] = {H:"У тебя острые зубы - перегрызи его."};
tr[33453] = {H:"Дай я порву этот браслет голыми руками."};
tr[33454] = {OId:270,H:"Ммм... нет... Всё равно не получается. Видимо, браслеты защищены магией."};
tr[33455] = {H:"Тогда спросим, как их снять, у того странного тролля из замка."};
tr[33456] = {OId:270,H:"На это сейчас нет времени! Вот-вот начнётся второй концерт."};
tr[33457] = {H:"Ладно. Побежали в Студию!"};
tr[33458] = {OId:543,H:"Беги в замок Злобикуса на Площади у Больнички!"};
tr[33459] = {OId:548,H:"Волшебные браслеты изобрёл этот гениальный тролль. Я чую это!"};
tr[33460] = {OId:380,H:"Изобрёл, да, да, да. Хозяин попросил - я изобрёл."};
tr[33461] = {H:"Значит, ты, тролль, расскажешь нам, как снять браслеты."};
tr[33462] = {OId:380,H:"Я буду говорить только с тем, кто умён. Скажи, к какому числу прибавили 874 и получили 1251?"};
tr[33463] = {H:"437"};
tr[33464] = {H:"2125"};
