tr[33467] = {H:"Левша."};
tr[33468] = {H:"Лев."};
tr[33469] = {H:"Налево."};
tr[33470] = {OId:380,H:"Ну и ну... Попробуй снова."};
tr[33471] = {H:"Ладно."};
tr[33472] = {OId:380,H:"О! Ты умён, а значит, поможешь с моим новым проектом. А я освобожу артистов от браслетов."};
tr[33473] = {H:"По рукам!"};
tr[33474] = {OId:552,H:"Внимание! Обнаружена опасность.Требуется перезагрузка программы паники. АААА!"};
