tr[33604] = {H:"Бейсболка " + "\"" + "На своей волне" + "\"" + ""};
tr[33605] = {H:"Костюм " + "\"" + "На своей волне" + "\"" + ""};
tr[33606] = {H:"Костюм " + "\"" + "На своей волне" + "\"" + ""};
tr[33608] = {H:"Ахаха, выведаю все ваши тайны!"};
tr[33609] = {H:"Не поймал, не поймал!"};
tr[33610] = {H:"Ловушка? Для меня? Пхаха!"};
tr[33611] = {H:"Вот, шпионю тут за вами..."};
tr[33612] = {H:"Я знаю все ваши секреты!"};
tr[33613] = {H:"Зря стараешься..."};
tr[33614] = {H:"Сейф агента"};
tr[33615] = {H:"Секретный фон"};
tr[33616] = {H:"Худи " + "\"" + "Скрытые силы" + "\"" + ""};
tr[33617] = {H:"Кепка " + "\"" + "Глаз да глаз" + "\"" + ""};
tr[33618] = {H:"Кроссовки " + "\"" + "Скрытые силы" + "\"" + ""};
tr[33619] = {H:"Костюм " + "\"" + "Скрытые силы" + "\"" + ""};
tr[33620] = {H:"Кубок высоты|За победу над Титаном."};
tr[33621] = {H:"Кубок ловкого агента|За победу над Титаном."};
tr[33622] = {OId:270,H:"Выбери народ в Сити, Порту или Парке и сними про них кино!"};
tr[33623] = {OId:270,H:"Привет! Хочешь стать жителем Древнего Рима и снять про это кино?"};
tr[33624] = {H:"А что интересного у римлян?"};
tr[33625] = {H:"Древний Рим? Мне надо ещё подумать..."};
tr[33626] = {OId:270,H:"Римляне самые мудрые. И красивые. И культурные! Всё, как я люблю."};
tr[33627] = {H:"Круто! Я буду снимать кино про римлян!"};
tr[33628] = {H:"Интересно, чем отличаются викинги. Спрошу у Копатыча."};
tr[33629] = {H:"А вдруг майя лучше? Спрошу у Ёжика."};
tr[33630] = {OId:270,H:"Ура! Надевай костюм и заходи в город. Там я подскажу тебе, что делать."};
tr[33631] = {H:"Спасибо!"};
tr[33632] = {OId:270,H:"Ну шо? Хочешь стать могучим викингом и снять про это кино?"};
tr[33633] = {H:"А что умеют викинги?"};
tr[33634] = {H:"Викингом? Мне надо ещё подумать..."};
tr[33635] = {OId:270,H:"Викинги самые суровые. Они покоряют моря, носят рогатые шлемы и не боятся морозов."};
tr[33636] = {H:"Круто! Я буду снимать кино про викингов!"};
tr[33637] = {H:"Интересно, чем отличаются римляне. Спрошу у Нюши."};
tr[33638] = {H:"А вдруг майя лучше? Спрошу у Ёжика."};
tr[33639] = {OId:270,H:"Надевай костюм и заходи в город. Там я подскажу тебе, что делать."};
tr[33640] = {OId:270,H:"Привет! Хочешь стать индейцем майя и снять про это кино?"};
tr[33641] = {H:"Интересно! А что такого особенного в майя?"};
tr[33642] = {H:"Индейцем? Мне надо ещё подумать..."};
tr[33643] = {OId:270,H:"Майя живут в джунглях, строят там пирамиды и проводят таинственные обряды."};
tr[33644] = {H:"Круто! Буду снимать кино про майя!"};
tr[33645] = {H:"А вдруг викинги лучше. Спрошу у Копатыча."};
tr[33646] = {OId:270,H:"Сними кино про древний народ в Парке, Сити или Порту!"};
tr[33647] = {H:"Тебя ждут в поселении твоей команды."};
tr[33648] = {H:"Металл для кузницы|Металл. Кирку для сбора\nзаточат через {0} мин."};
tr[33649] = {OId:270,H:"Славный у нас народ, правда ведь?"};
tr[33650] = {OId:270,H:"Впервые тебя вижу... Заслужи моё доверие, и тогда поговорим."};
tr[33651] = {OId:270,H:"Твоих деяний пока недостаточно. Выполни мою просьбу, и я пропущу тебя в Колизей."};
tr[33652] = {H:"А что скрыто в Колизее?"};
tr[33653] = {OId:270,H:"В Колизее мы храним главный секрет нашего народа! Только избранным дозволено туда войти."};
tr[33654] = {OId:270,H:"У наших границ поселились викинги и майя. Проберись к ним и принеси кое-что для меня."};
tr[33655] = {OId:270,H:"Твоих деяний пока недостаточно. Выполни мою просьбу, и я пропущу тебя в Великий дом."};
tr[33656] = {H:"А что скрыто в Великом доме?"};
tr[33657] = {OId:270,H:"В Великом доме мы храним главный секрет нашего народа! Только избранным дозволено туда войти."};
tr[33658] = {OId:270,H:"У наших границ поселились римляне и майя. Проберись к ним и принеси кое-что для меня."};
tr[33659] = {OId:270,H:"Твоих деяний пока недостаточно. Выполни мою просьбу, и я пропущу тебя в Пирамиду."};
tr[33660] = {H:"А что скрыто в Пирамиде?"};
tr[33661] = {OId:270,H:"В Пирамиде мы храним главный секрет нашего народа! Только избранным дозволено туда войти."};
tr[33662] = {OId:270,H:"У наших границ поселились викинги и римляне. Проберись к ним и принеси кое-что для меня."};
tr[33663] = {OId:270,H:"Ты поработал в кузнице и проявил уважение к нашим легендам и достижениям."};
tr[33664] = {H:"Спасибо, я старался."};
tr[33665] = {H:"А какая у вас просьба?"};
tr[33666] = {H:"Хорошо. А какую просьбу нужно выполнить?"};
tr[33667] = {H:"Оу, оу, оу. Звучит как воровство!"};
tr[33668] = {OId:270,H:"Вовсе не воровство! Мне кажется, они замышляют на нас напасть. Узнай, так это или нет."};
tr[33669] = {H:"Хорошо. Так что там нужно принести?"};
tr[33670] = {H:"Это не военные планы, а стихи про глиняные горшки. Поищи ещё."};
tr[33671] = {H:"Здесь указ, запрещающий зевать по понедельникам. Поищи ещё."};
tr[33672] = {H:"Тут рисунок кошечки - не похоже на военные планы. Поищи ещё."};
tr[33673] = {H:"Это труды Витрувия, а не военные планы. Поищи ещё."};
tr[33674] = {H:"Это не военные планы, а стихи про коровьи рога. Поищи ещё."};
tr[33675] = {H:"Здесь советы, как плести косички на бороде. Поищи ещё."};
tr[33676] = {H:"Тут рисунок рыбки - не похоже на военные планы. Поищи ещё."};
tr[33677] = {H:"Это легенда про Тора и Локи, а не военные планы. Поищи ещё."};
tr[33678] = {H:"Это не военные планы, а стихи про кукурузу. Поищи ещё."};
tr[33679] = {H:"Здесь указ, запрещающий вставать с правой ноги. Поищи ещё."};
tr[33680] = {H:"Тут рисунок с обезьяной - не похоже на военные планы. Поищи ещё."};
tr[33681] = {H:"Это предсказание о конце света, а не военные планы. Поищи ещё."};
tr[33682] = {H:"Пчелиная корона"};
tr[33683] = {H:"Куртка с шарфом"};
tr[33684] = {H:"Я устроил в Шарараме весеннюю вечеринку! Заходи в игру и сам увидишь!"};
tr[33685] = {OId:270,H:"Ну ладно, ладно. Ты это заслужил - иди и узри наш главный секрет!"};
tr[33686] = {OId:270,H:"Отличная новость, викинги и майя не готовятся нападать. Хе-хе-хе, значит, это мы их захватим!"};
tr[33687] = {H:"Эй, не надо никого захватывать. Вы обещали открыть мне вход в Колизей."};
tr[33688] = {H:"Спасибо, владыка римлян."};
tr[33689] = {OId:270,H:"Отличная новость, римляне и майя не готовятся нападать. Хе-хе-хе, значит, это мы их захватим!"};
tr[33690] = {H:"Эй, не надо никого захватывать. Вы обещали открыть мне вход в Великий дом."};
tr[33691] = {H:"Спасибо, повелитель викингов."};
tr[33692] = {OId:270,H:"Отличная новость, викинги и римляне не готовятся нападать. Хе-хе-хе, значит, это мы их захватим!"};
tr[33693] = {H:"Эй, не надо никого захватывать. Вы обещали открыть мне вход в Пирамиду."};
tr[33694] = {H:"Спасибо, Верховный жрец."};
tr[33695] = {OId:270,H:"Кликни на вход в Колизей и узри наш главный секрет!"};
tr[33696] = {OId:270,H:"Кликни на вход в дом и узри наш главный секрет!"};
tr[33697] = {OId:270,H:"Кликни на вход в Пирамиду и узри наш главный секрет!"};
tr[33698] = {OId:270,H:"Скорее, давай снимать главный секрет этого народа!"};
tr[33699] = {H:"Ты же говорил, что они не собираются нападать?"};
tr[33700] = {OId:270,H:"Нас обманули... Ты! Ты обманул меня и привёл сюда врага!"};
tr[33701] = {H:"Я? Да мы же просто тут кино снимали!"};
tr[33702] = {OId:270,H:"Как же я сразу не догадался... Не попадайся мне больше на глаза!"};
tr[33703] = {H:"Ну и ладно. Ты не прав!"};
tr[33704] = {OId:270,H:"Я в ярости! На нас напали майя и викинги. Если они узнают наш секрет..."};
tr[33705] = {OId:270,H:"Я в ярости! На нас напали майя и римляне. Если они узнают наш секрет..."};
tr[33706] = {OId:270,H:"Я в ярости! На нас напали римляне и викинги. Если они узнают наш секрет..."};
tr[33707] = {H:"Клуб " + "\"" + "Соты" + "\"" + ""};
tr[33708] = {H:"Древние народы затеяли драку. Лучше туда не ходить!"};
tr[33709] = {OId:270,H:"Друг мой мирный, в учебнике сказано, что все древние народы были вспыльчивыми и любили, кхм, похулиганить."};
tr[33710] = {H:"Они нам так пол-Шарарама разнесут!"};
tr[33711] = {OId:270,H:"Как же их примирить? Ты хорошо изучил свой народ. Скажи, что вызывает у него особый трепет?"};
tr[33712] = {H:"Может, это их главный секрет?"};
tr[33713] = {H:"Дракон из мифов и легенд! Вот кого все уважают."};
tr[33714] = {H:"Кузнец. Куда древним людям без кузнеца?"};
tr[33715] = {OId:270,H:"Главные секреты наоборот привели к раздору между народами."};
tr[33716] = {H:"Тогда народы примирит дракон."};
tr[33717] = {H:"Пусть мир наладят кузнецы."};
tr[33718] = {OId:270,H:"Хммм, в учебнике нет ни слова о кузнецах. Может, что-то другое поможет народам примириться."};
tr[33719] = {H:"Все уважают драконов!"};
tr[33720] = {H:"Главные секреты примирят народы!"};
tr[33721] = {OId:270,H:"Верно! В учебнике сказано, что все народы верили в драконов и уважали их. Пусть дракон убедит их помириться!"};
tr[33722] = {H:"Лосяш, но где мы сейчас достанем доброго дракона?"};
tr[33723] = {OId:270,H:"А на что нам камеры? Настоящий дракон не нужен - снимем кино со спецэффектами."};
tr[33724] = {H:"Точно! Давай снимать"};
tr[33725] = {OId:270,H:"Лось обещал нам дракона. Мы ждём!"};
tr[33726] = {OId:556,H:"Вы слышали, что сказал великий дракон?"};
tr[33727] = {OId:557,H:"С драконом лучше не шутить..."};
tr[33728] = {OId:558,H:"Пора забыть о разногласиях!"};
tr[33729] = {H:"Ура! Мир! Дары!"};
tr[33730] = {H:"Почему вы вообще начали враждовать?"};
tr[33731] = {OId:556,H:"К нам пробрался разведчик и украл военные планы!"};
tr[33732] = {OId:557,H:"И к нам! Злодей копался в вещах нашего торговца!"};
tr[33733] = {OId:558,H:"И у нас так было! Это кто-то из вас!"};
tr[33734] = {H:"Хе-хе, да, разведчик... Ну ведь ничего страшного, правда?"};
tr[33735] = {OId:556,H:"Мы поняли, что враждовать не весело."};
tr[33736] = {OId:557,H:"Зато весело дарить подарки."};
tr[33737] = {OId:558,H:"Истина!"};
tr[33738] = {H:"Ура!"};
tr[33739] = {OId:270,H:"Давай снимать, как живёт местный народ!"};
tr[33740] = {OId:270,H:"Уговори императора показать главный секрет римлян!"};
tr[33741] = {OId:270,H:"Уговори конунга показать главный секрет викингов!"};
tr[33742] = {OId:270,H:"Уговори жреца показать главный секрет майя!"};
tr[33743] = {H:"Уютная квартира"};
tr[33745] = {H:"Закон Макса"};
tr[33746] = {H:"Мой деда гений, значит, я тоже гений. Помоги мне совершить научное открытие!"};
tr[33747] = {H:"Для исследований нужны Смешинки. Накопи {0} штук."};
tr[33748] = {H:"А ещё понадобится Позитивная энергия. Заработай {0} штук в играх."};
tr[33749] = {H:"Спасибо! Давай приступим к исследованиям."};
tr[33750] = {H:"Закон Макса"};
tr[33751] = {H:"Для начала помоги мне измерить силу полёта предметов в Шарараме."};
tr[33752] = {H:"Как летает мяч? Сыграй в Волейбол на Пляже."};
tr[33753] = {H:"Как летает шарик? Выиграй в Скачки в Парке аттракционов."};
tr[33754] = {H:"А метеориты? Сыграй в Метеоритный тренажёр на Космодроме."};
tr[33755] = {H:"Ого! Изучив твои данные, я решил измерять силу полёта в снежках."};
tr[33756] = {H:"Закон Макса"};
tr[33757] = {H:"А теперь помоги мне собрать данные об озорстве Смешариков."};
tr[33758] = {H:"Приходи в Парк аттракционов."};
tr[33759] = {H:"Сыграй в Футбол."};
tr[33760] = {H:"Прокатись на санках со Снежной горы."};
tr[33761] = {H:"Для измерения озорства я придумал новую единицу - хохотушку."};
tr[33762] = {H:"Закон Макса"};
tr[33763] = {H:"Вот моё открытие: дальность полёта 1 снежка равна количеству хохотушек Смешарика,\nпомноженной на 5! Гениально."};
tr[33764] = {H:"Отпразднуем открытие. Приходи на Пляж."};
tr[33765] = {H:"Кинь {0} помидоров."};
tr[33766] = {H:"Накорми гостей. Заработай в Кафе {0} Смешинок за 1 раз."};
tr[33767] = {H:"Ура, теперь я тоже учёный. Спасибо, вот тебе награда."};
tr[33768] = {H:"Готовимся к исследованиям!"};
tr[33769] = {H:"Гипотеза о полёте"};
tr[33770] = {H:"Гипотеза об озорстве"};
tr[33771] = {H:"Ура открытию!"};
tr[33772] = {H:"Сапоги викинга"};
tr[33773] = {H:"Сандали майя"};
tr[33774] = {H:"Римский костюм"};
tr[33775] = {H:"Костюм викинга"};
tr[33776] = {H:"Костюм майя"};
tr[33777] = {H:"Я снял кино про древние народы! Приходи в Шарарам и разгадай загадки истории!"};
tr[33778] = {H:"Домик викинга"};
tr[33779] = {H:"Костюм императора"};
tr[33780] = {H:"Локоны удачи"};
tr[33781] = {H:"Причёска, которая принесёт тебе радость и успех! Ищи у себя в гардеробе!"};
tr[33782] = {H:"Форум римлян"};
tr[33783] = {H:"Лагерь викингов"};
tr[33784] = {H:"Город майя"};
tr[33785] = {OId:270,H:"Я отвезу тебя в Венецию! Кликни на меня."};
tr[33786] = {OId:270,H:"Я отвезу тебя обратно в Шарарам! Кликни на меня."};
tr[33787] = {H:"Венеция"};
tr[33788] = {H:"Клетка с птичкой"};
tr[33789] = {H:"Хомяк в домике"};
tr[33790] = {H:"Зоо-стул"};
tr[33791] = {H:"Зоо-кроватка"};
tr[33792] = {H:"Зоо-шкафчик"};
tr[33793] = {H:"Бассейн " + "\"" + "Сердечко" + "\"" + ""};
tr[33794] = {H:"Бассейн с горкой"};
tr[33795] = {H:"Бассейн " + "\"" + "Лейка" + "\"" + ""};
tr[33796] = {H:"Бассейн с подсветкой"};
tr[33797] = {OId:176,H:"Я отвезу тебя в Венецию! Кликни на меня."};
tr[33798] = {H:"Сначала отправь подарок выбранному другу."};
tr[33799] = {H:"Куртка " + "\"" + "Встречай весну!" + "\"" + ""};
tr[33800] = {H:"Фон " + "\"" + "Фламинго" + "\"" + ""};
tr[33801] = {H:"Стол с конфетами"};
tr[33802] = {H:"Букет " + "\"" + "Подарок от друга" + "\"" + ""};
tr[33803] = {H:"Шапка " + "\"" + "Подарочная" + "\"" + ""};
tr[33804] = {H:"Причёска с платком"};
tr[33805] = {H:"Я угостил Смешариков праздничным обедом! Приходи в Шарарам и отпразднуй приход весны!"};
tr[33806] = {H:"Мыльная шляпка"};
tr[33807] = {H:"Мыльный котелок"};
tr[33808] = {H:"Спутник " + "\"" + "Чистюлькин" + "\"" + ""};
tr[33809] = {H:"Мы привезли в Шарарам праздник мыльных пузырей! Нарядись к нему в Летающей тарелке в Лесу и приходи снова!"};
tr[33810] = {H:"Фон " + "\"" + "Пузырики" + "\"" + ""};
tr[33811] = {H:"Стул " + "\"" + "Мыльный" + "\"" + ""};
tr[33812] = {H:"Водяная лампочка"};
tr[33813] = {H:"Дождевик"};
tr[33814] = {H:"Загадочное дело"};
tr[33815] = {H:"Жители Шарарама обеспокоены странным поведением некоторых Смешариков. Скорее навести Агента 007 в Штабе и приступай к миссии " + "\"" + "Загадочное дело" + "\"" + ""};
tr[33816] = {H:"В Штаб"};
tr[33817] = {OId:559,H:"По Шарараму ползут слухи, что Смешарики встречают своих двойников! Если с этим не разобраться, жди беды."};
tr[33818] = {H:"Двойники? Это слишком запутанное дело ! Боюсь, я не справлюсь."};
tr[33819] = {H:"Нам всем  иногда что-то мерещится. Это всё пустяки, мне некогда этим заниматься!"};
tr[33820] = {H:"Хм... очень интересно, продолжай."};
tr[33821] = {OId:559,H:"Жаль, что ты не можешь помочь, возвращайся, когда будешь готов приступить к заданию."};
tr[33822] = {OId:559,H:"Первая зацепка: Босс Ба-Босс начал растрачивать деньги и закрывать самые успешные клубы. Это на него не похоже, надо узнать что к чему."};
tr[33823] = {H:"Понятно, сейчас же отправляюсь в Корпорацию клубов!"};
tr[33824] = {OId:559,H:"Возьми этот Планшет, там записаны Смешарики, которые ведут себя странно. Поговори с ними и отметь тех, кого ты подозреваешь."};
tr[33825] = {OId:561,H:"Послушай, сейчас мне некогда с тобой разговаривать..."};
tr[33826] = {H:"Ходят слухи, что Корпорация клубов теряет деньги. Зачем тогда ты закрываешь клубы Шарарама?"};
tr[33827] = {H:"Извини, зайду в другой раз."};
tr[33828] = {OId:561,H:"Я глава Корпорации и мне лучше знать, как ею управлять. Всё будет так, как я хочу! Прошу меня больше не отвлекать, уходи..."};
tr[33829] = {H:"Хорошо, но прежде я бы хотел здесь всё осмотреть. Ты не против?"};
tr[33830] = {H:"Всего хорошего и удачи в новых начинаниях!"};
tr[33831] = {OId:561,H:"Мне скрывать нечего, только не шуми."};
tr[33832] = {OId:560,H:"Ну и денек! Поступило множество больных с нервными расстройствами, где же я на всех успокоительное найду?!"};
tr[33833] = {H:"Бинтик, расскажи, что случилось с этими бедолагами?"};
tr[33834] = {OId:560,H:"Всем вдруг стали мерещиться двойники! Говорят, ты расследуешь поведение Ба-Босса. Может, ты нашел у него что-нибудь странное?"};
tr[33835] = {H:"Пока нет. Вернусь, когда найду что-нибудь."};
tr[33836] = {H:"Да, я кое-что нашёл в кладовой у Босса Ба-Бабосса. Там у него целый годовой запас этих баночек."};
tr[33837] = {OId:560,H:"Давай, передай эту баночку мне."};
tr[33838] = {OId:560,H:"Это арахисовое масло! У Босса Ба-Босса же на него жуткая аллергия. Зачем тогда ему годовой запас?"};
tr[33839] = {H:"Как интересно... это наталкивает на некоторые мысли, спасибо за помощь, Бинтик!"};
tr[33840] = {OId:560,H:"Аррр! Три тысячи улиток! Сколько можно вёсла сушить?! Стою здесь как сухопутная мышь! Где моя труба?!"};
tr[33841] = {H:"Привет, Джо! Ты чего такой сердитый?"};
tr[33842] = {H:"Прости, Джо, вижу, ты не в настроении, зайду попозже!"};
tr[33843] = {OId:560,H:"Я разбил свою подзорную трубу, а без неё не выйти в плавание! Умникус обещал изготовить мне новую, но что-то он не торопится, якорь что ли бросил?!"};
tr[33844] = {H:"Я как раз собирался зайти к Умникусу по одному делу, заодно спрошу и про твою трубу."};
tr[33845] = {OId:560,H:"Спасибо, друг! Аррр! Как же я скучаю по плеску волн за бортом!"};
tr[33846] = {H:"Ты не можешь смешать зелье,  потому что не все ингредиенты собраны! Возвращайся, когда соберешь их."};
tr[33847] = {OId:562,H:"Моя голова... что это за странный привкус во рту? Мухи?"};
tr[33848] = {H:"Умникус, что случилось? Ты никогда раньше не ошибался в заклинаниях."};
tr[33849] = {OId:562,H:"Видимо, мне пора уйти на покой, от магии одни беды... буду флористикой заниматься, как я люблю цветы!"};
tr[33850] = {H:"Что ты такое говоришь? Ты не можешь уйти, кто будет заниматься магией и присматривать за Школой Магов, и кто же сделает линзы для Джо-Ворона?"};
tr[33851] = {OId:562,H:"Некогда мне линзами заниматься, у меня розы вянут! Ищи себе другого ученого, химика например. А мне нужно новую рассаду подготовить."};
tr[33852] = {OId:563,H:"Кто-то ограбил мою лабораторию! Хотя ничего ценного не украли, так ... разные детали. Но сам факт! Это возмутительно!"};
tr[33853] = {H:"А что за детали? Я расследую появление двойников в Шарараме. Может, это имеет отношение к делу?"};
tr[33854] = {OId:563,H:"Трудно сказать. Похититель вырвал из книги учёта талоны. А без них я не вспомню, какие детали лежали на тех стеллажах. Найдёшь эти талоны для меня?"};
tr[33855] = {H:"Я поищу эти талоны. Возможно, они всё ещё здесь."};
tr[33856] = {OId:563,H:"Так, так, так... Вспомнил! Пропали три детали от моей старой машины клонирования!"};
tr[33857] = {H:"Ты изобрёл машину клонирования?! Зачем она тебе понадобилась, и где она сейчас?"};
tr[33858] = {OId:563,H:"Я хотел клонировать рыбу в океане, но на вкус она вышла как шпинат. Фу! Машину мы разобрали и выбросили, но некоторые детали я оставил, вдруг пригодятся!"};
tr[33859] = {H:"Значит, кто-то собрал твою машину и начал клонировать жителей Шарарама!"};
tr[33860] = {OId:563,H:"Нужно скорей найти похитителя деталей. Кстати, познакомься с моим лаборантом Рыжиком. Может, он поможет в расследовании."};
tr[33861] = {OId:566,H:"Привет, Агент! Не хочешь семечек? Я их просто обожаю! Чем могу тебе помочь?"};
tr[33862] = {H:"Рыжик, ты ничего не знаешь об ограблении? Где ты был вчера вечером?"};
tr[33863] = {OId:566,H:"Ограблении? Нет... я весь вечер просидел дома, смотрел мультики и никуда не выходил. Это всё, чем я могу помочь. Поговори со Скунсом, я сейчас весь в работе!"};
tr[33864] = {H:"Ясно, спасибо за помощь!"};
tr[33865] = {OId:563,H:"Агент 007 просит тебя вернуться в Штаб и доложить о ходе расследования."};
tr[33866] = {OId:559,H:"Привет, Агент! Как идет расследование? Ты уже опросил всех подозреваемых?"};
tr[33867] = {H:"Да, все результаты расследования я вписал в планшет."};
tr[33868] = {OId:559,H:"Отлично. Я скопирую твои данные на свой компьютер."};
tr[33869] = {OId:559,H:"Сомневаюсь в достоверности данных, перепроверь их и возвращайся."};
tr[33870] = {OId:559,H:"Отлично! Теперь у нас есть данные о двойниках.\nТолько что поступил сигнал бедствия из пещеры на окраине Шарарама. Отправляйся туда и выйди на след злоумышленника."};
tr[33871] = {OId:564,H:"Ура! Этот рыжий негодяй с семечками, надеюсь, уже получил по заслугам! Дверь сломана - почини замок и освободи нас."};
tr[33872] = {OId:565,H:"Секретные Агенты самые лучшие! Мы с Умникусом поспешим исправить то, что натворили наши клоны! Ох, попадись мне этот рыжий негодяй, любитель семечек!"};
tr[33873] = {H:"Кажется, я знаю о ком идёт речь... Рыжий любитель семечек, надо с ним встретиться!"};
tr[33874] = {OId:566,H:"Агент, я очень занят, поговори со Скунсом, он тут главный."};
tr[33875] = {H:"Рыжик, я обнаружил твои следы на месте преступления в пещере, где держали пленных Смешариков. Все улики против тебя! Признавайся, и тебя не сильно накажут!"};
tr[33876] = {OId:566,H:"Хорошо, признаюсь! Я починил машину клонирования, чтобы сделать копии самых богатых и могущественных Смешариков, и обрести их богатство и силу."};
tr[33877] = {H:"Ты поступил плохо. Но твои знания пригодятся Агентам. Скоро с тобой свяжется связной, и смотри, не подведи меня!"};
tr[33878] = {OId:566,H:"Меня принимают в Секретные Агенты?! Ура, я так долго об этом мечтал!"};
tr[33879] = {OId:563,H:"Да! Мне поручено наградить тебя медалью " + "\"" + "За разоблачение двойников" + "\"" + " и СмеШуткой " + "\"" + "Двойник" + "\"" + "."};
tr[33880] = {H:"Динозаврик"};
tr[33881] = {H:"Ты ввёл неверный код, попробуй снова."};
tr[33882] = {H:"Причёска " + "\"" + "Кактус" + "\"" + ""};
tr[33883] = {H:"Худи " + "\"" + "Кактус" + "\"" + ""};
tr[33884] = {H:"Шарафон " + "\"" + "Кактус" + "\"" + ""};
tr[33885] = {H:"Умникус превратил себя в жабу. Найди способ снять заклятие!"};
tr[33886] = {OId:559,H:"Возьми этот Планшет, там записаны Смешарики, которые ведут себя странно. Поговори с ними и отметь тех, кого ты подозреваешь."};
tr[33887] = {OId:561,H:"Мне скрывать нечего. Осмотрись тут, только не шуми."};
tr[33888] = {OId:560,H:"Разгадай тайну двойников! Вся надежда только на тебя."};
tr[33889] = {OId:562,H:"Мне нужно новую рассаду подготовить и ещё удобрения прикупить. Не мешай."};
tr[33890] = {OId:563,H:"Нужно скорей найти похитителя деталей. Кстати, познакомься с моим лаборантом Рыжиком. Может, он поможет в расследовании."};
tr[33891] = {H:"Да, все результаты расследования я вписал в планшет. Проверяй."};
tr[33892] = {OId:559,H:"Отлично! Теперь у нас есть данные о двойниках. Только что поступил сигнал бедствия из пещеры на окраине Шарарама. Отправляйся туда и выйди на след злоумышленника."};
tr[33893] = {OId:565,H:"Ты уже разобрался с Рыжиком в Наблюдательном пункте? Поспеши, пока он не натворил бед."};
tr[33894] = {H:"Агент 003, дело можно считать закрытым?"};
tr[33895] = {OId:178,H:"Я уже вернул Смешариков."};
tr[33896] = {OId:176,H:"Я уже вернул Смешариков."};
tr[33897] = {OId:150,H:"Я уже вернул Смешариков."};
tr[33898] = {OId:150,H:"Я уже вернула Смешариков."};
tr[33899] = {OId:380,H:"Я - конь златогривый: по характеру строптивый, по жизни игривый, по утрам сонливый. Чего надобно?"};
tr[33900] = {H:"О, конь! Встань на службу богатырю - помоги ему вершить подвиги ратные!"};
tr[33901] = {OId:380,H:"Не хочу к богатырю, мне свобода дороже. Отпусти меня, а я тебе подарок дам!"};
tr[33902] = {H:"Подарок мне и богатырь даст. А подвиги без тебя не совершатся!"};
tr[33903] = {H:"Ты прав. Ты зверь дикий, тебе лучше на воле резвиться."};
tr[33904] = {OId:380,H:"И тут правда, и там правда. Раз ты меня нашёл - тебе и решать мою судьбу."};
tr[33905] = {H:"Отведу тебя к богатырю вершить подвиги!"};
tr[33906] = {H:"Отпущу тебя на волю."};
tr[33907] = {H:"Больничка"};
tr[33908] = {H:"Порт"};
tr[33909] = {H:"Школа Магов"};
tr[33910] = {H:"Наблюдательный пункт"};
tr[33911] = {H:"Штаб"};
tr[33912] = {H:"Пещера"};
tr[33913] = {H:"Корпорация клубов"};
tr[33914] = {H:"Урок волшебной постройки"};
tr[33915] = {H:"Кран в домик"};
tr[33916] = {H:"Лук с присосками"};
tr[33917] = {H:"Котелок жокея"};
tr[33918] = {H:"Жакет жокея"};
tr[33919] = {OId:380,H:"Приведи мне коня из Лукоморья. Кликни на клубок, и он доставит тебя туда."};
tr[33920] = {H:"Лукоморье"};
tr[33921] = {H:"Спутник Зайка Зоя"};
tr[33922] = {H:"Твоя новая лучшая подружка!|Умеет летать на воздушных шариках!|Прикольно танцует!"};
tr[33923] = {H:"Мандрагора"};
tr[33924] = {H:"До созревания мандрагоры: {0} мин."};
tr[33925] = {H:"Хлыст"};
tr[33926] = {H:"Красный лимон"};
tr[33927] = {H:"До созревания лимона: {0} мин."};
tr[33928] = {H:"Морская жемчужина"};
tr[33929] = {H:"До созревания жемчужины: {0} мин."};
tr[33930] = {H:"Химический катализатор"};
tr[33931] = {H:"До наполнения колбы\n химическим катализатором: {0} мин."};
tr[33932] = {H:"Фон " + "\"" + "Жара!" + "\"" + ""};
tr[33933] = {H:"Причёска " + "\"" + "Ветер в лицо" + "\"" + ""};
tr[33934] = {H:"Поло со скейтом"};
tr[33935] = {H:"Кубок скейтера.|За победу в чемпионате по скейтбордингу!"};
tr[33936] = {H:"Машина для клонирования"};
tr[33937] = {H:"Скейт"};
tr[33938] = {H:"Репка"};
tr[33939] = {H:"Тянем-потянем..."};
tr[33940] = {H:"Укуси меня пчела! Я вырастил репку, такую огромную, что вытянуть её не могу. Подсоби-ка мне!"};
tr[33941] = {H:"Накопи Позитивную энергию. Собери {0} штуки в Шарараме."};
tr[33942] = {H:"Наберись силы. Сыграй в футбол в Парке аттракционов."};
tr[33943] = {H:"Ух! Ух! Ух... Ничего не выходит. Давай позовём кого-нибудь на помощь."};
tr[33944] = {H:"Тянем-потянем..."};
tr[33945] = {H:"Кому тут нужен настоящий силач? С моими бицепсами мы эту репку в два счёта вытянем!"};
tr[33946] = {H:"Орехи дают силу. Собери {0} штук в Дремучем лесу."};
tr[33947] = {H:"Устрой разминку на Пляже. Сыграй в волейбол и заработай {0} Смешинок."};
tr[33948] = {H:"Эта репка сильнее меня... Только, тсс, никому не говори, а то засмеют."};
tr[33949] = {H:"Тянем-потянем..."};
tr[33950] = {H:"Вы пытаетесь вытащить репку одной грубой силой... А как же вдохновение? Вот чего вам не хватает!"};
tr[33951] = {H:"Послушай пение птиц - приходи в Ромашковую долину."};
tr[33952] = {H:"Танцы тебя взбодрят. Посети {0} клубов."};
tr[33953] = {H:"Море подарит вдохновение! Прокатись на катере в Порту."};
tr[33954] = {H:"Тянем-тянем-тянем... Нее-еет, нам всё ещё не хватает сил, чтобы вытянуть репку."};
tr[33955] = {H:"Тянем-потянем..."};
tr[33956] = {H:"Просто нужно тянуть сильнее. Совсем чуть-чуть! Я как раз могу помочь."};
tr[33957] = {H:"Мне нужно подготовиться. Отправляся в Джунгли."};
tr[33958] = {H:"Люблю цветы. Собери {0} фиалок - они придадут мне сил."};
