tr[34140] = {OId:270,H:"Ты развеял чары, и теперь предмет можно называть вслух. Это волшебная палочка!"};
tr[34141] = {H:"Ура! Есть идеи, где начать поиски?"};
tr[34142] = {OId:270,H:"Легенды говорят о всезнающей чайке... Хм, где же нам её найти?"};
tr[34143] = {H:"Чайку? Наверное там, где есть вода..."};
tr[34144] = {OId:270,H:"Верно! Как же я сразу не догадался, ищи чайку в море - беги в Порт!"};
tr[34145] = {H:"Ура, бежим к морю!"};
tr[34146] = {H:"Я нашёл сокровища страны Единорогов! В Шарараме и не такое возможно!"};
tr[34147] = {H:"Я чайка, а ты кто? Везде летаю, всех знаю, а тебя впервые вижу."};
tr[34148] = {H:"Я будущий маг. Птичка, нет ли у тебя волшебной палочки Умникуса?"};
tr[34149] = {H:"У меня? Палочка утеряна сотни лет назад, а мне всего 3 года... Ничего у меня нет."};
tr[34150] = {H:"Как же мне быть, молодая всезнающая чайка?"};
tr[34151] = {H:"Видала, на Пляж то и дело приходит Смешарик с волшебной палочкой. Может, он чего отыскал?"};
tr[34152] = {H:"С волшебной палочкой? Это интересно! Спасибо, чайка!"};
