tr[34156] = {H:"Девочка... Девочки, что с вами?"};
tr[34157] = {OId:567,H:"Пожалуйста, помогите!"};
tr[34158] = {H:"Но мы уже тебя, то есть вас, спасли."};
tr[34159] = {OId:270,H:"Ха! Понял. Эта малышка попала во временную воронку неудач!"};
tr[34160] = {H:"Ну вот ещё не хватало..."};
tr[34161] = {H:"Что это за воронка?"};
tr[34162] = {OId:270,H:"Простая вещь: время и пространство сталкиваются и закручиваются, появляется воронка и начинает охоту за Смешариками."};
tr[34163] = {H:"Док, ты умеешь приносить хорошие новости."};
tr[34164] = {OId:270,H:"Воронка телепортирует девочку из одного времени в другое, от одной катастрофы к другой."};
tr[34165] = {OId:567,H:"Да, да. Так и есть!"};
tr[34166] = {H:"А почему девочек много? Или она одна?"};
tr[34167] = {H:"Как хорошо, что мы её, их, спасли!"};
tr[34168] = {OId:270,H:"Потому что я отправил тебя одновременно во все катастрофы, в какие она попала. И ты принёс сюда 5 девочек, хотя она одна. Гениально, правда?"};
tr[34169] = {H:"Отлично. Девочку спасли, дело можно закрывать."};
tr[34170] = {OId:270,H:"Спасли-то, спасли... Да только, четыре, три, два..."};
tr[34171] = {H:"Один?"};
tr[34172] = {OId:270,H:"Вот видишь. Воронка снова унесла девочку к какой-то новой катастрофе. Надо вернуть девочку, а воронку запечатать."};
tr[34173] = {H:"А как это сделать?"};
tr[34174] = {OId:270,H:"Я перенёс катастрофы прошлого в настоящее. Удобно. Найди их в Шарараме и спаси Смешариков!"};
tr[34175] = {OId:270,H:"Док ждёт тебя на Площади у Больнички!"};
tr[34176] = {OId:270,H:"Это кресло поможет найти воронку. Кликай на него!"};
tr[34177] = {OId:270,H:"Тебе назначена встреча? Или ты просто так здесь гуляешь?"};
tr[34178] = {H:"Нет, нет, нет. Никаких встреч. Не буду тебя отвлекать."};
tr[34179] = {H:"Босс Ба-Босс, научи нас с Нюшей бизнес-премудростям!"};
tr[34180] = {OId:270,H:"Ах, да. В моём плотном графике как раз есть несколько минут для тебя. Слушай внимательно!"};
tr[34181] = {H:"Слушаю."};
tr[34182] = {OId:270,H:"Я предлагал Нюше продавать в её лавке старинные монетки, но она отказалась."};
tr[34183] = {H:"Ещё бы. Покупать деньги... за деньги? Странная идея, Ёжик. Пока!"};
tr[34184] = {H:"Ёжик, молодец! Монетки же можно коллекционировать!"};
tr[34185] = {OId:270,H:"Вот именно! Давай я тебе всё расскажу, а ты убедишь Нюшу, что это хороший ход."};
tr[34186] = {H:"Договорились!"};
tr[34187] = {OId:270,H:"Я тебя ждал! Никаких сомнений - в лавке Нюши нужно продавать живопись!"};
tr[34188] = {H:"Привет! Раз ты так уверен, вперёд!"};
tr[34189] = {OId:270,H:"Объясни мне, почему Нюша продаёт всё, что угодно, но не сладости?"};
tr[34190] = {H:"Она боится, что Совунья заругает её, ведь конфеты вредны для зубов."};
tr[34191] = {H:"Может, Нюша села на диету и боится сорваться?"};
tr[34192] = {OId:270,H:"О-ля-ля! Чтобы добиться успеха, нужно рисковать и не бояться. Я расскажу тебе, как превратить лавку Нюши в кондитерскую."};
tr[34193] = {H:"Ура! Слушаю внимательно."};
tr[34194] = {H:"Магия " + "\"" + "Деловая Нюша" + "\"" + ""};
tr[34195] = {H:"Магия " + "\"" + "Деловая Нюша" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Нюшу ещё дней: {0}|Ты можешь превращаться в Нюшу всегда!"};
tr[34196] = {H:"Костюм художника"};
tr[34197] = {H:"Кисть художника"};
tr[34198] = {H:"Монета Ёжика"};
tr[34199] = {OId:571,H:"Спасибочки!"};
tr[34200] = {OId:270,H:"Кликни на воронку, чтобы захлопнуть её."};
tr[34201] = {OId:568,H:"Ух, спасибо! Из-за этой воронки я 200 лет телепортировалась от катастрофы к катастрофе."};
tr[34202] = {OId:569,H:"Временные парадоксы, они такие!"};
tr[34203] = {H:"200 лет? Ты выглядишь моложе... Ну ничего, теперь можно отдохнуть."};
tr[34204] = {OId:568,H:"Да, схожу в кафе. Полистаю журналы. Сменю причёску... Ух, тоска какая."};
tr[34205] = {OId:569,H:"Не удивительно! Ты, наверное, привыкла к приключениям!"};
tr[34206] = {H:"И вправду. В Шарараме столько всего, чем же тебе заняться?"};
tr[34207] = {OId:570,H:"ИУ провёл анализ. Девочка вступать в Лигу."};
tr[34208] = {H:"Правильно! Ты столько знаешь о катастрофах - Лиге это очень пригодится!"};
tr[34209] = {OId:568,H:"Я буду вершить подвиги и помогать Смешарикам?! Уау, да это лучшее предложение на свете!"};
tr[34210] = {H:"Как славно, что мы со всем разобрались!"};
tr[34211] = {H:"Я стал акулой бизнеса в мире Смешариков! Присоединяйся ко мне в Шарараме."};
tr[34212] = {H:"Кресло ЮИ"};
tr[34213] = {H:"Ковёр мудрости"};
tr[34214] = {H:"Стол " + "\"" + "Лига героев" + "\"" + ""};
tr[34215] = {H:"Набор мебели " + "\"" + "Лига героев" + "\"" + ""};
tr[34216] = {H:"Кеды " + "\"" + "Нет проблем" + "\"" + ""};
tr[34217] = {H:"Костюм " + "\"" + "Нет проблем" + "\"" + ""};
tr[34218] = {H:"Вместе с Лигой героев мы совершили новый подвиг. Присоединяйся ко мне в Шарараме!"};
tr[34219] = {OId:270,H:"Кликни на ИУ в кресле и приготовься ловить воронку!"};
tr[34220] = {OId:270,H:"Без паники, просто всё пошло не так. Надо спасти ИУ и вытащить из этой воронки! Кликни на неё."};
tr[34221] = {OId:270,H:"Беги в Порт и разыщи чайку!"};
tr[34222] = {OId:270,H:"Купи в магазине летнюю одежду!"};
tr[34223] = {OId:270,H:"О! У тебя есть новая одежда? Скорее примерь её."};
tr[34224] = {OId:270,H:"Найди на пляже Смешарика-мага!"};
tr[34225] = {OId:270,H:"Отдохни от поисков у себя в домике!"};
tr[34226] = {OId:270,H:"Давай с кем-нибудь подружимся!"};
tr[34227] = {OId:270,H:"Проверь сообщения на Шарафоне!"};
tr[34228] = {OId:270,H:"Вот тайник, куда спрятали палочку Умникуса. Кликни на него, чтобы открыть."};
tr[34229] = {OId:270,H:"Я научу тебя колдовать! Следуй моим советам."};
tr[34230] = {OId:270,H:"Шарам-барарам-тарарам... Хм?..  Никак не могу вспомнить пончиковое заклинание."};
tr[34231] = {H:"Привет, а что это у тебя в руках? Кажется, это палочка Умникуса."};
tr[34232] = {OId:270,H:"Я? Взять чужое?! Ну нет! Это моя палочка. Мне её в Школе магов выдали."};
tr[34233] = {H:"Прямо вот так взяли и выдали? Подозрительно..."};
tr[34234] = {OId:270,H:"Так я же ученик, вот, у меня даже дневник есть. Показать?"};
tr[34235] = {H:"Верю, верю! Где же тогда искать палочку Умникуса?"};
tr[34236] = {OId:270,H:"Прими от меня награду - забирай это облачение магов!"};
tr[34237] = {OId:270,H:"Возьми себе питомца в Каньоне и стань его наставником!"};
tr[34238] = {OId:270,H:"Твой питомец отыскал Позитивную энергию - забирай её себе!"};
tr[34239] = {OId:270,H:"Отправляйся в космос и прогони оттуда злобного призрака!"};
tr[34240] = {OId:270,H:"Я Умникус, Верховный маг Шарарама. Ты прошёл моё испытание, поздравляю!"};
tr[34241] = {H:"Испытание? Так ты не терял свою волшебную палочку?"};
tr[34242] = {OId:270,H:"Вовсе нет! Я ищу учеников, которых не испугают трудности и которые готовы принять помощь друзей. Теперь ты принят в Школу магов."};
tr[34243] = {H:"Ура! Спасибо, Умникус!"};
tr[34244] = {OId:270,H:"Тебе пора узнать, что маги колдуют не только для веселья, но и для защиты от Тёмных сил..."};
tr[34245] = {H:"Тёмные силы в Шарараме?"};
tr[34246] = {OId:270,H:"Не стоит бояться, юный маг. Нам помогут волшебные питомцы. Станешь их наставником?"};
tr[34247] = {H:"Волшебные питомцы? Круто!"};
tr[34248] = {H:"Поло " + "\"" + "Погружение во тьму" + "\"" + ""};
