tr[34372] = {OId:270,H:"Ну... Это неправильный ответ. Попробуй-ка ещё раз!"};
tr[34373] = {H:"Так и быть, попробую."};
tr[34374] = {OId:270,H:"О! Как ты узнал? Ответ правильный, забирай бинокль!"};
tr[34375] = {H:"Спасибо, Василич!"};
tr[34376] = {OId:270,H:"Вот что мы узнали: путь через Каньон проходит по подножию вулкана, а из Сити - через леса, моря и долины."};
tr[34377] = {OId:572,H:"А путь из Ромашковой долины ооочень длинный. И, наверное, скучный."};
tr[34378] = {H:"Я выбираю путь через Каньон!"};
tr[34379] = {H:"Я выбираю путь через Ромашковую долину!"};
tr[34380] = {H:"Я выбираю путь через Сити!"};
tr[34381] = {OId:270,H:"Хм, путь через вулкан... Жарковато. Как мы защитим себя от огненной лавы?"};
tr[34382] = {OId:573,H:"Если выйти из Ромашковой долины, мы будем идти 298 дней. Долго..."};
tr[34383] = {H:"Пойдём другим путём. Попробуем начать путь в Сити."};
tr[34384] = {OId:270,H:"Отличный путь! Не слишком длинный и не очень опасный."};
tr[34385] = {H:"Вперёд!"};
tr[34386] = {H:"Волшебный сад"};
tr[34387] = {H:"Кирка|Кирку привезут через {0} мин."};
tr[34388] = {H:"Кресло " + "\"" + "Высокие технологии" + "\"" + ""};
tr[34389] = {H:"Стол " + "\"" + "Высокие технологии" + "\"" + ""};
tr[34390] = {H:"Кроссовки с подсветкой"};
tr[34391] = {H:"Фон " + "\"" + "Высокие технологии" + "\"" + ""};
tr[34392] = {H:"Куртка " + "\"" + "Неон" + "\"" + ""};
tr[34393] = {H:"Куртка " + "\"" + "Неон" + "\"" + ""};
tr[34394] = {H:"Неоновый домик"};
tr[34395] = {OId:270,H:"Ведьма околдовала наших девочек и сделала своими подружками. Скорее кликни на ведьму!"};
tr[34396] = {OId:270,H:"Бррр, а Совунья обещала, что будет тепло..."};
tr[34397] = {OId:270,H:"Кажется, этим грифонам нужна помощь - скорее кликни на них!"};
tr[34398] = {OId:270,H:"Шшшш, лучше не подходи... Ты тоже хочешь причинить нам вред?"};
tr[34399] = {H:"Нет, конечно! Грифоны, что случилось? Кто вас запер?"};
tr[34400] = {OId:270,H:"На нас напали чудики и посадили в эту клетку... А ты чего хочешь?"};
tr[34401] = {H:"Я хочу добраться до вершины горы. Но раз вы в беде, мы поможем!"};
tr[34402] = {OId:270,H:"Спасибо, что освободил. Мы этого не забудем!"};
tr[34403] = {OId:270,H:"Дались ему эти кактусы! Выбирай: помочь Ёжику с кактусами или сразу пойти к дереву!"};
tr[34404] = {OId:270,H:"Он рубит наше Дерево Желаний! Останови этого злобного Джинна!"};
tr[34405] = {OId:270,H:"Будь проклят тот день, когда это шайтан-дерево дало свои ростки..."};
tr[34406] = {H:"Привет, Джинн. Что ты творишь?!"};
tr[34407] = {OId:270,H:"Из-за Дерева Желаний больше никто не просит меня исполнить их сокровенные мечты. Клянусь королевским верблюдом!"};
tr[34408] = {H:"Не припомню, чтобы ты исполнял мои мечты. А дерево это может!"};
tr[34409] = {OId:270,H:"Но я же злодей! Проси о чём угодно - и навеки станешь моим должником! Ахахаха!"};
tr[34410] = {H:"Ну уж нет! Не дам тебе разрубить дерево!"};
tr[34411] = {H:"Докажите, что вы не робот!"};
tr[34412] = {H:"Код ошибки: 487. У моего друга-робота заржавели детали в голове, и он притворился Смешариком! Поможешь мне отыскать его?"};
tr[34413] = {H:"Поиски будут долгими. Накопи {0} Смешинок."};
tr[34414] = {H:"Заручись поддержкой. Добавь {0} друга."};
tr[34415] = {H:"Спроси у друзей в общем чате: " + "\"" + "Как отличить робота?" + "\"" + ""};
tr[34416] = {H:"Ты готов к поискам. Держи Смешинки в награду!"};
tr[34417] = {H:"Докажите, что вы не робот!"};
tr[34418] = {H:"Привет, я робот-Крош! Бип-буп-буп-бип-боп! Давай играть в роботов."};
tr[34419] = {H:"Робот заряжаются энергией Солнца. Приходи на Пляж."};
tr[34420] = {H:"Роботы просчитывают всё наперёд. Выиграй в " + "\"" + "Секретики" + "\"" + "."};
tr[34421] = {H:"Роботы любят танцевать. Посети {0} клубов!"};
tr[34422] = {H:"Здорово поиграли! Но я вовсе не робот, я Крош. Лови Смешинки!"};
tr[34423] = {H:"Докажите, что вы не робот!"};
tr[34424] = {H:"Я не робот, я Совунья. Сам проверь."};
tr[34425] = {H:"Я хочу сварить борщ. Собери для него {0} инструментов в Автосалоне."};
tr[34426] = {H:"Добудь гвоздей для борща - сыграй в " + "\"" + "Вечный двигатель" + "\"" + " в Ромашковой долине!"};
tr[34427] = {H:"Приправим борщ горючим. Чтобы добыть его, сыграй в " + "\"" + "Катер" + "\"" + " в Порту."};
tr[34428] = {H:"Вкусный борщ с гвоздями получился. Теперь веришь, что я не робот? Проверь другого Смешарика!"};
tr[34429] = {H:"Докажите, что вы не робот!"};
tr[34430] = {H:"Я робот?! Нет, это ты робот! Спорим?"};
tr[34431] = {H:"Проверь, не робот ли ты - сделай рентген в Больничке."};
tr[34432] = {H:"Роботы не едят. А ты? Закажи в клубе салат " + "\"" + "Оливье" + "\"" + ""};
tr[34433] = {H:"Теперь я верю, что ты не робот. Но робот ли я сам? Спрошу у дедушки."};
tr[34434] = {H:"Докажите, что вы не робот!"};
tr[34435] = {H:"Крош просто притворялся роботом, Макс всегда странный, а вот Совунья - не Совунья, а мой друг-робот. Теперь помоги нам уехать обратно в Страну роботов."};
tr[34436] = {H:"Я сделаю робо-топливо из шишек. Собери {0} штук на Снежной горе."};
tr[34437] = {H:"Чтобы мой друг не ломался, нужна Позитивная энергия. Заработай {0} штук в играх."};
tr[34438] = {H:"Спасибо, что помог мне найти друга и вернуться домой. Вот твоя награда."};
tr[34439] = {H:"Готовимся к поискам!"};
tr[34440] = {H:"Крош робот?"};
tr[34441] = {H:"Совунья робот?"};
tr[34442] = {H:"Макс робот?"};
tr[34443] = {H:"Роботы едут домой!"};
tr[34444] = {OId:270,H:"Кликни на дерево, чтобы оно исполнило желание!"};
tr[34445] = {H:"Наклейка " + "\"" + "Рейнджер" + "\"" + ""};
tr[34446] = {H:"Наклейка " + "\"" + "Скаут" + "\"" + ""};
tr[34447] = {H:"Наклейка " + "\"" + "Турист" + "\"" + ""};
tr[34448] = {H:"Фон " + "\"" + "Котейки" + "\"" + ""};
tr[34449] = {H:"Очки " + "\"" + "Радость" + "\"" + ""};
tr[34450] = {H:"Я сходил в поход со Смешариками и исполнил их мечты. Хочешь так же? Скорее в Шарарам!"};
tr[34451] = {H:"Урок аромамагии"};
tr[34452] = {H:"Пиджак " + "\"" + "Цветочек" + "\"" + ""};
tr[34453] = {H:"Смайлы 2.0"};
tr[34454] = {H:"Чистые эмоции и ничего лишнего!"};
tr[34455] = {H:"Костюм выпускника"};
tr[34456] = {H:"Костюм выпускницы"};
tr[34457] = {H:"Шарафон " + "\"" + "Кристалл богатства" + "\"" + ""};
tr[34458] = {H:"Бейсболка " + "\"" + "Все богатства космоса" + "\"" + ""};
tr[34459] = {H:"Фон " + "\"" + "Президент Галактики" + "\"" + ""};
tr[34460] = {H:"Стикеры " + "\"" + "Галактическое богатство" + "\"" + ""};
tr[34461] = {H:"Кубок " + "\"" + "Титановый астероид в золоте" + "\"" + ".|За победу в чемпионате по космо-боулингу!"};
tr[34462] = {H:"Мы празднуем выпускной из школы зябиллионеров! Нарядись к празднику в Летающей тарелке в Лесу и приходи снова!"};
tr[34463] = {H:"Я чемпион по космо-боулингу! Заходи в Шарарам - сыграем вместе!"};
tr[34464] = {H:"Футболка " + "\"" + "Крош" + "\"" + ""};
tr[34465] = {H:"Ягодный кубок.|За спасение Шарарама от ледяного дождя!"};
tr[34466] = {H:"Солнечный кубок.|За спасение Шарарама от ледяного дождя!"};
tr[34467] = {H:"Ягодная рубашка"};
tr[34468] = {H:"Солнечная причёска"};
tr[34469] = {H:"Солнечный жилет"};
tr[34470] = {H:"###Ты заработал {0} Позитивной энергии,###теперь у тебя {1} {2}."};
tr[34471] = {H:"Худи с ушками"};
tr[34472] = {H:"Наряд для самых озорных! Ищи у себя в гардеробе!"};
tr[34473] = {H:"Лодка для разведки"};
tr[34474] = {H:"Крокодильчик"};
tr[34475] = {H:"Спутниковая станция"};
tr[34476] = {H:"Дозорная вышка"};
tr[34477] = {H:"Вертолётная площадка"};
tr[34478] = {H:"Вертолёт"};
tr[34479] = {H:"Климазон"};
tr[34480] = {H:"Кресло для педикюра"};
tr[34481] = {H:"Кресло с раковиной"};
tr[34482] = {H:"Украшение на стену " + "\"" + "Ножницы" + "\"" + ""};
tr[34483] = {H:"Чудики против чернушек!"};
tr[34484] = {H:"Ну шо, здравствуй! Ты таки знаешь, что в космосе хозяйничают злые чернушки. Даже нам, чудикам, от них тошно. Помоги мне их прогнать."};
tr[34485] = {H:"Приготовься к полёту. Сделай рентген в больничке."};
tr[34486] = {H:"Зарядись Позитивной энергией. Заработай {0} штук в любых играх."};
tr[34487] = {H:"Дело сделано. Вот твоя небольшая награда. Впереди чернушки и космос!"};
tr[34488] = {H:"Чудики против чернушек!"};
tr[34489] = {H:"А теперь лети в космос и прогони чернушек! А я со стороны понаблюдаю, хе-хе - у меня на космос аллергия."};
tr[34490] = {H:"Лети на Мюру."};
tr[34491] = {H:"Чернушки ломают гравипушку! Собери {0} инструментов в Автосалоне."};
tr[34492] = {H:"Прогони Чернушек и заработай {0} Смешинок."};
tr[34493] = {H:"Ух ты какой! А я и не верил, что ты справишься..."};
tr[34494] = {H:"Чудики против чернушек!"};
tr[34495] = {H:"Чудик рассчитывал, что чернушки победят тебя, и Шарарам останется без защиты. Но ты победил! Давай отпразднуем это."};
tr[34496] = {H:"Порадуй Смешариков. Поработай в Кафе и заработай {0} Смешинок."};
tr[34497] = {H:"Пусть друзья знают о твоей победе. Сходи в гости к {0} Смешарикам."};
tr[34498] = {H:"Напиши в чат: " + "\"" + "Я перехитрил чудика!" + "\"" + ""};
tr[34499] = {H:"Отлично! Вот твоя награда."};
tr[34500] = {H:"Готовимся к полёту!"};
tr[34501] = {H:"Прогоняем чернушек!"};
tr[34502] = {H:"Помогаем Смешарикам!"};
tr[34503] = {H:"Зеркало парикмахера"};
tr[34504] = {H:"Стол для маникюра"};
tr[34505] = {H:"Шляпа героя"};
tr[34506] = {H:"Маска героя"};
tr[34507] = {OId:575,H:"Я хочу немедленно ехать в джунгли и совершать там невероятные открытия!"};
tr[34508] = {OId:574,H:"Карыч, сначала мне нужно в салон! А потом можно и в джунгли, чтобы там... блистать!"};
tr[34509] = {H:"Хочу приключений и открытий в джунглях!"};
tr[34510] = {H:"Нет, сначала давайте всё-таки наведём красоту в салоне!"};
tr[34511] = {H:"Фон " + "\"" + "Море космоса" + "\"" + ""};
tr[34512] = {H:"Синяя шляпа"};
tr[34513] = {H:"Синий костюм"};
tr[34514] = {OId:580,H:"Кликни на лифт и поднимись на этаж, где жили гномы."};
tr[34515] = {OId:17,H:"Антисорняк|Антисорняк нальют через {0} мин."};
tr[34516] = {OId:270,H:"Колдовской бардак - я такой боюсь трогать. Кликай на двери, чтобы снять чары."};
tr[34517] = {H:"Поединок магов"};
tr[34518] = {H:"Сыграем в Поединок магов?"};
tr[34519] = {H:"Хочешь выйти и потерять бонусы?"};
tr[34520] = {H:"Победил {0}!"};
tr[34521] = {H:"Ничья!"};
tr[34522] = {H:"Соперник вышел из игры."};
tr[34523] = {H:"МультФон с молниями"};
tr[34524] = {H:"Волшебный костюм"};
tr[34525] = {H:"Часы-дерево"};
tr[34526] = {H:"Кубок колдовства.|За победу в волшебном поединке!"};
tr[34527] = {H:"Молот гномов"};
tr[34528] = {H:"Праздничные шарики"};
tr[34529] = {OId:580,H:"Смотри, в номерах отеля нашлись загадочные камни... Что это?"};
tr[34530] = {H:"Это задача для меня слишком сложная. Прощай, Эллис!"};
tr[34531] = {H:"Хм... Эллис, попробуй сложить эти камни вместе!"};
tr[34532] = {OId:580,H:"Ого! Мозаика из камней сложилась! Но... Тебе не кажется, что тут не хватает пятого?"};
tr[34533] = {H:"На этаже было только 4 заколдованных номера."};
tr[34534] = {OId:580,H:"Четыре? Не может быть! Их всегда было пять. Если ты расколдовал четыре, то куда делся пятый?"};
tr[34535] = {H:"Колдовство гномов... Может, его сделали невидимым? Пойду проверю."};
tr[34536] = {OId:580,H:"Найди пропавший номер на этаже, где жили маги. Кликай на лифт."};
tr[34537] = {OId:270,H:"Дверь была сразу после четвёртого номера. Куда подевалась? Кинь туда что ли помидор!"};
tr[34538] = {OId:270,H:"Ой, ой, ой! Как ты нашёл меня? Он, скажи мне, он все ещё там? Этот ужасный злобырь."};
tr[34539] = {H:"Привет, гном! Никаких злобырей в отеле нет, ты о чём?"};
tr[34540] = {OId:270,H:"Значит, он уже ушёл. Нас было пятеро, пятеро гномов-магов. Но в отель пришёл злобырь и напал..."};
tr[34541] = {H:"Так вот откуда этот кавардак. Но зачем это злобырю?"};
tr[34542] = {OId:270,H:"Может, он хотел овладеть нашей силой? Мне чудом удалось спрятаться за дверью-невидимкой... А мои друзья? Ты их видел?"};
tr[34543] = {H:"Разве гномы не сбежали из отеля? Вот, смотри, у меня есть 4 камня."};
tr[34544] = {OId:270,H:"Это... Это же они! Злобырь заковал моих друзей в камни..."};
tr[34545] = {H:"Камни - это гномы??? Ох, а как их расколдовать?"};
tr[34546] = {OId:580,H:"Помоги гному в подземелье! Беги в Каньон."};
tr[34547] = {OId:270,H:"Спускайся в подземелье и найди там злобыря!"};
tr[34548] = {OId:270,H:"Найди злобыря - столбы подскажут путь!"};
tr[34549] = {OId:270,H:"Найди части гномьего молота в лабиринте!"};
tr[34550] = {OId:270,H:"Спускайся в подземелье и победи злобыря!"};
tr[34551] = {OId:270,H:"Беги к злобырю и победи его!"};
tr[34552] = {H:"Ты нашёл 200 смешинок!"};
tr[34553] = {H:"Чтобы разрушить крепость, надень молот гномов на Личной карточке!"};
tr[34554] = {OId:580,H:"Злобырь прорвался в Каньон! Останови его."};
tr[34555] = {OId:270,H:"Думал меня обмануть? Не так-то это просто. Теперь все пятеро гномьих магов у меня в плену!"};
tr[34556] = {H:"Грох, хватит! Зачем тебе гномы-маги?"};
tr[34557] = {OId:270,H:"Чтобы хозяин Злобикус захватил царство гномов, пока его некому защищать. А у меня вот шлем теперь будет красивый!"};
tr[34558] = {H:"Хм... Гном говорил, что молот меня выручит. Интересно, как?"};
tr[34559] = {OId:270,H:"Молот? Грха-ха-ха! Не смеши меня, что может молот гномов против моей силушки злобырской?"};
tr[34560] = {H:"Вот и проверим!"};
tr[34561] = {H:"Цилиндр с бакенбардами"};
tr[34562] = {OId:576,H:"Молодец! Заклинание на молоте освободило нас, а злобыря обратило в камень!"};
tr[34563] = {H:"Что же теперь делать с этим злодеем?"};
tr[34564] = {OId:576,H:"Не волнуйся! С ним всё будет хорошо. Мы его Злобикусу по почте отправим, а чары окаменения вскоре спадут."};
tr[34565] = {H:"Это будет ему уроком. Думаю, вам он больше не угрожает!"};
tr[34566] = {H:"Костюм " + "\"" + "Эллисон" + "\"" + ""};
tr[34567] = {H:"Костюм " + "\"" + "Гроза подземелий" + "\"" + ""};
tr[34568] = {H:"Злые сны"};
tr[34569] = {H:"Нюше приснился пожар в Доме мод, а Ёжику - кактусы-монстры. А следом и остальным Смешарикам стали сниться кошмары. Давай выясним, почему!"};
tr[34570] = {H:"Первым делом крошки! Отправляйся в Детский сад."};
tr[34571] = {H:"Избавь крошек от кошмаров - поухаживай за ними и заработай {0} Смешинок!"};
tr[34572] = {H:"Порадуй крошек - собери {0} груш в Ромашковой долине."};
tr[34573] = {H:"В детском саду я нашла камень из Египта... Интересно, как он там оказался?"};
tr[34574] = {H:"Злые сны"};
tr[34575] = {H:"Подумаем о камне из Египта позже. А пока давай успокоим других Смешариков, которым приснились кошмары."};
tr[34576] = {H:"Проведай друзей. Сходи в гости к {0} Смешарикам."};
tr[34577] = {H:"Успокой Смешариков. Порадуй их стильными обновками - сыграй в игру в Доме мод."};
tr[34578] = {H:""};
tr[34579] = {H:"Я нашла ещё несколько камней из Египта. На них символ бога Ра! Так это он испортил Смешарикам сны?"};
tr[34580] = {H:"Злые сны"};
tr[34581] = {H:"Ахаха! Я раскидал колдовские камни по всему Шарараму, чтобы украсть у Смешариков хорошие сны! Тебе меня не остановить."};
tr[34582] = {H:"Защитись от колдовства Ра Позитивной энергией. Найди в Шарараме {0} штуки."};
tr[34583] = {H:"Спрячься от Ра в тёмной чаще. Сыграй в Дары леса и заработай {0} Смешинок за 1 раз."};
tr[34584] = {H:""};
tr[34585] = {H:"Что ж, в этот раз ты смог защититься от моего колдовства..."};
tr[34586] = {H:"Злые сны"};
tr[34587] = {H:"Богини Египта решили бросить вызов Ра, помочь Смешарикам и вернуть им приятные сны!"};
tr[34588] = {H:"Богиня истины Маат развеет кошмары. Сыграй в её игру."};
tr[34589] = {H:"Богиня радости Баст сделает сны приятными. Сыграй в её игру."};
tr[34590] = {H:"Силу бога Ра ослабит богиня солнца Сехмет. Сыграй в её игру."};
tr[34591] = {H:"Воля богинь Египта исполнена! Смешарики могут спать спокойно. А ты заслужил дар богов."};
tr[34592] = {H:"Спасаем крошек!"};
tr[34593] = {H:"Спасаем Смешариков!"};
tr[34594] = {H:"Прячемся от Ра!"};
tr[34595] = {H:"Побеждаем кошмары!"};
tr[34596] = {H:"Я спас подземное царство от злого колдуна! Приходи в Шарарам и стань героем!"};
