tr[34662] = {H:"Магия СтритКрош|Получи эту способность у лемура в Каньоне|Ты можешь превращаться в Кроша ещё дней: {0}|Ты можешь превращаться в Кроша всегда!"};
tr[34663] = {H:"Дари подарки!"};
tr[34664] = {H:"Дом звёзд"};
tr[34665] = {OId:270,H:"Привет! Я слышал, Пляжник собирается путешествовать. Ты же знаешь, я суперзвезда, объездил весь мир - концерты, фанаты, шикарные отели..."};
tr[34666] = {H:"Я знаю, что ты зазнайка. Поговорим потом."};
tr[34667] = {H:"Джибер, посоветуешь место для путешествий?"};
tr[34668] = {OId:270,H:"Больше всего я люблю Европу. Сейчас расскажу тебе о самых крутых местах."};
tr[34669] = {H:"О, старушка-Европа! Класс."};
tr[34670] = {H:"Страница 1"};
tr[34671] = {OId:270,H:"Пляжник хочет путешествий? Поверь моему опыту, нет ничего важнее флагов!"};
tr[34672] = {H:"Карыч, сейчас я не готов к твоим загадкам."};
tr[34673] = {H:"А почему?"};
tr[34674] = {OId:270,H:"А как без флага ты поймёшь, в какую страну прибыл? Я тебе сейчас всё объясню."};
tr[34675] = {H:"Интересно, интересно."};
tr[34676] = {OId:270,H:"Привет! Я как маг тебе говорю: лучше всего путешествовать по сказочному и чудесному миру."};
tr[34677] = {H:"Прости Шарри, но реальность мне интереснее."};
tr[34678] = {H:"Чудесному миру?"};
tr[34679] = {OId:270,H:"Я расскажу тебе о 7 чудесах света! С помощью колдовства можно и к ним отправиться."};
tr[34680] = {H:"Ух ты как круто!"};
tr[34681] = {OId:270,H:"Привет! Далеко ли уплывёт Пляжник, если не познает тайны мореходства?"};
tr[34682] = {H:"Далеко! И надолго. Ну а я на диване посижу."};
tr[34683] = {H:"Верное замечание, Джо! Научишь меня мореходству?"};
tr[34684] = {OId:270,H:"Киль мне в румпель, конечно! Начинаем."};
tr[34685] = {H:"Ура!"};
tr[34686] = {H:" Я научил Смешариков путешествовать. Скорее за приключениями в Шарарам!"};
