tr[34701] = {H:"Морской фестиваль"};
tr[34702] = {H:"Морской царь Аквариус велел мне устроить в Шарараме праздник моря. А я суши-то, знаешь, побаиваюсь. Поможешь мне?"};
tr[34703] = {H:"Чтобы сделать рекламу, порисуй. Сыграй в Волшебный карандаш в Школе магов."};
tr[34704] = {H:"На празднике нужна Позитивная энергия. Заработай {0} штук в любых играх."};
tr[34705] = {H:"Напиши в общий чат: " + "\"" + "Давайте устроим морской праздник!" + "\"" + ""};
tr[34706] = {H:"Ура! Теперь все знают про праздник. Держи награду!"};
tr[34707] = {H:"Морской фестиваль"};
tr[34708] = {H:"Гости начнут праздновать на Пляже. Давай там всё подготовим."};
tr[34709] = {H:"Приходи на Пляж."};
tr[34710] = {H:"Проверь, чтобы в песке не было острых предметов. Выиграй в Секретики."};
tr[34711] = {H:"Накорми гостей. Заработай {0} Смешинок в Кафе " + "\"" + "Улыбка" + "\"" + " за 1 раз."};
tr[34712] = {H:"Гости начали праздник в отличном настроении. Ты молодец, держи Смешинки."};
tr[34713] = {H:"Морской фестиваль"};
tr[34714] = {H:"Давай устроим на Снежной горе уголок Ледникового моря."};
tr[34715] = {H:"Приходи на Снежную гору."};
tr[34716] = {H:"Покажи мастер-класс на катке. Купи в Смешмаге коньки " + "\"" + "Фигурные" + "\"" + "."};
tr[34717] = {H:"Проверь трассу для катания. Сыграй в Сноуборд."};
tr[34718] = {H:"Ура! Хоть на горе и холодно, там весело. Это твоя заслуга."};
tr[34719] = {H:"Морской фестиваль"};
tr[34720] = {H:"Какой праздник без подарков? Давай позаботимся о призах."};
tr[34721] = {H:"Из кораллов получатся крутые украшения. Собери в Подводном мире {0} штук."};
tr[34722] = {H:"Собери дары моря. Прокатись на Катере в Порту и заработай {0} Смешинок."};
tr[34723] = {H:"Всё готово к празднику. Царь Аквариус велел наградить тебя морским сокровищем."};
tr[34724] = {H:"Расскажи о празднике!"};
tr[34725] = {H:"Празднуем на пляже!"};
tr[34726] = {H:"Празднуем на леднике!"};
tr[34727] = {H:"Призы для праздника"};
tr[34728] = {H:"Я спас пиратов! Приходи в Шарарам - тут скелеты подарки дарят!"};
