tr[34732] = {H:"Гавайский набор"};
tr[34733] = {H:"Голограмма Нюши"};
tr[34734] = {H:"Фруктовый шарафон"};
tr[34735] = {H:"Хочешь выйти и пропустить эту игру?"};
tr[34736] = {H:"Кресло-гамак"};
tr[34737] = {H:"Фон " + "\"" + "Лимон с мятой" + "\"" + ""};
tr[34738] = {H:"Куртка " + "\"" + "Фреш" + "\"" + ""};
tr[34739] = {H:"Причёска " + "\"" + "Фреш" + "\"" + ""};
tr[34740] = {H:"Спутник Эмми"};
tr[34741] = {H:"Шарафон " + "\"" + "Морской" + "\"" + ""};
tr[34742] = {OId:270,H:"Злобного тебе дня! Я решил поддержать Дока. Вдруг его изобретение окажется шаром всемогущества?"};
tr[34743] = {H:"Хитрый Злобикус! Мы не позволим тебе отобрать то, что изобрёл Док."};
tr[34744] = {OId:270,H:"Как бы то ни было, прими от меня драконовую смолу. Ни у кого в Шарараме такой нет."};
tr[34745] = {H:"Ого! В списке Дока она есть, спасибо!"};
tr[34746] = {OId:270,H:"Я очень хочу помочь Доку с изобретением! Передай ему эту пачку бодрящего чая. Он поможет привести мысли в порядок."};
tr[34747] = {H:"Спасибо, Лосяш!"};
tr[34748] = {OId:270,H:"Я мечтаю, чтобы изобретением Дока стало чудо-зеркало, усиливающее красоту."};
tr[34749] = {H:"Я как раз не могу найти одну деталь для Дока. У тебя случайно нет диффузора Д57?"};
tr[34750] = {OId:270,H:"Конечно есть! Это же деталь моего любимого фена... Который постоянно ломается. Забирай, у меня куча запасных."};
tr[34751] = {H:"Спасибо, Нюша! Наука не забудет твой вклад."};
tr[34752] = {OId:270,H:"Надеюсь, Док изобретёт работающий вечный двигатель."};
tr[34753] = {OId:150,H:"Никто не следит за здоровьем! Надеюсь, Док изобретёт весёлый тренажёр. С супчиком!"};
tr[34754] = {OId:270,H:"Агенты ждут, что Док изобретёт универсальное средство против призраков!"};
tr[34755] = {OId:270,H:"Помогай мне готовить новогодние сладости и получай за это призы!"};
tr[34756] = {OId:270,H:"Поскорее бы увидеть изобретение!"};
tr[34757] = {OId:577,H:"Велосипед? Не смешите мои рога - какое же это изобретение?"};
tr[34758] = {OId:579,H:"А что? Такое уже есть? Кто-то уже изобрёл велосипед?!!"};
tr[34759] = {OId:581,H:"А мне нравится велосипед."};
tr[34760] = {H:"Док, да. У всех есть велосипеды."};
tr[34761] = {OId:578,H:"Как я разочарован. С таким изобретение злодейство не провернёшь..."};
tr[34762] = {OId:581,H:"Прикольный велосипед."};
tr[34763] = {H:"Может, ты ошибся в расчётах, Док?"};
tr[34764] = {OId:579,H:"Нет... Машина обещала изобрести лучшую вещь на свете... И вот она."};
tr[34765] = {OId:581,H:"Какой крутой велосипед."};
tr[34766] = {H:"Ну ладно, зато покатаемся!"};
tr[34767] = {OId:582,H:"Давай кататься! Кликни на велосипед."};
tr[34768] = {OId:583,H:"Хорошая новость: я изобрёл телепортацию. Плохая новость: Макс пропал."};
tr[34769] = {H:"Док, а что такое телепортация?"};
tr[34770] = {H:"А куда пропал Макс?"};
tr[34771] = {OId:583,H:"Телепортация - это мгновенное путешествие в любую точку мира."};
tr[34772] = {H:"А при чём тут велосипед?"};
tr[34773] = {OId:583,H:"Велосипед - устройство для телепорта. И он унёс Макса туда, куда мой внучок хотел отправиться больше всего."};
tr[34774] = {H:"В лавку сладостей?"};
tr[34775] = {H:"В Парк аттракционов?"};
tr[34776] = {OId:583,H:"Ты же знаешь, что Макс... странный. Чтобы понять, куда он улетел, нужно знать, о чём он думал. А это..."};
tr[34777] = {H:"Сложнейшая задача во Вселенной!"};
tr[34778] = {H:"Грелка|Грелка нагреется через {0} мин."};
tr[34779] = {H:"Ушастик Том"};
tr[34780] = {H:"Ракета Том"};
tr[34781] = {H:"Месье Том"};
tr[34783] = {OId:583,H:"Итак, Максу снились подвиги, зубная паста, лава и змеи. Куда он хотел отправиться?"};
tr[34784] = {H:"Кабинет стоматолога? Отправиться туда - подвиг."};
tr[34785] = {H:"Зоопарк, где тренированные змеи чистят зубы?"};
tr[34786] = {H:"Лава и змея - огнедышащий дракон... Хм?"};
tr[34787] = {OId:583,H:"Но при чём тут лава и змеи? Непонятно."};
tr[34788] = {H:"Попробуем снова."};
tr[34789] = {OId:583,H:"Такого места не существует, а значит велосипед не смог бы унести туда Макса."};
