tr[34974] = {OId:270,H:"Посмотри, какой тортик приготовили Смешарики. Нравится?"};
tr[34975] = {H:"Красиво! Сразу видно - Шарараму 11 лет."};
tr[34976] = {H:"Вот бы ещё розочек побольше и шоколадной крошкой посыпать..."};
tr[34977] = {OId:270,H:"Ёлки-иголки, а ты кто такой?"};
tr[34978] = {OId:586,H:"Ты что, не видишь? Я полный Ноль!"};
tr[34979] = {H:"Привет, Ноль! А мы тут день рождения Шарарама празднуем."};
tr[34980] = {OId:586,H:"Да-да! Какие аппетитные единицы у вас на торте. Одну заберу себе!"};
tr[34981] = {H:"Эй, так не честно! Это общий тортик..."};
