tr[35009] = {H:"Привет, а я в цветочке пряталась. Хочешь подарок? Ответь, как звали змея из русских сказок?"};
tr[35010] = {H:"Копатыч."};
tr[35011] = {H:"Карыч."};
tr[35012] = {H:"Горыныч."};
tr[35013] = {H:"Привет, а я в цветочке пряталась. Хочешь подарок? Ответь, кому на день рождения Крош подарил путёвку от агентства ДежаВю?"};
tr[35014] = {H:"Тигриции."};
tr[35015] = {H:"Мышарику."};
tr[35016] = {H:"Копатычу."};
tr[35017] = {H:"Не зли меня!"};
tr[35018] = {H:"Будешь у меня нолём без палочки!"};
tr[35019] = {H:"Я из тебя дырку от бублика сделаю."};
tr[35020] = {H:"Отведай магии чисел."};
tr[35021] = {H:"Приготовься к обнулению!"};
tr[35022] = {H:"Полный ноль!"};
tr[35023] = {H:"Меткость у тебя на нуле..."};
tr[35024] = {H:"Пхаха! Ничего у тебя не выйдет."};
tr[35025] = {H:"Единичка держит удар."};
tr[35026] = {H:"Ноль внимания..."};
tr[35027] = {H:"Минусую!"};
tr[35028] = {H:"Вот сделаю из тебя нормальную цифру!"};
tr[35029] = {H:"Лови подачу!"};
tr[35030] = {H:"Один-ноль в мою пользу!"};
tr[35031] = {H:"От тебя пустого места не останется!"};
tr[35032] = {H:"Ай, как неприятно!"};
tr[35033] = {H:"Хватит-хватит."};
tr[35034] = {H:"Я тебе этого не забуду."};
tr[35035] = {H:"А мне твои минусы нипочём... Почти."};
tr[35036] = {H:"Вот это было внезапно!"};
tr[35037] = {H:"А я домике, я в домике!"};
tr[35038] = {H:"Защищаюсь!"};
tr[35039] = {H:"Ну и чего ты прячешься?"};
tr[35040] = {H:"Всё равно достану!"};
tr[35041] = {H:"Делю на ноль!"};
tr[35042] = {H:"Как тебе такой ход?"};
tr[35043] = {H:"Ааа, запрещённые приёмчики?"};
tr[35044] = {H:"Нельзя делить на ноль, тебе в школе не говорили?"};
tr[35045] = {H:"Энергия мне сейчас в самый раз!"};
tr[35046] = {H:"Сил у меня прибавилось!"};
