tr[35146] = {OId:270,H:"Мадам Жабо хочет открыть наш фан-клуб. Поговори с ней в Сити!"};
tr[35147] = {OId:270,H:"Привет! Я Джибер - суперзвезда. Хочешь, дам тебе автограф? Бесплатно!"};
tr[35148] = {H:"Нет, спасибо. Мне нужно что-то посерьёзнее - для фан-клуба Мадам Жабо."};
tr[35149] = {H:"Хочу! Автограф это крутой экспонат для фан-клуба."};
tr[35150] = {OId:270,H:"О, фан-клуб! Ради такого я готов дать тебе не простой, а волшебный автограф! Идёт?"};
tr[35151] = {H:"Идёт! А волшебный автограф - это что?"};
tr[35152] = {OId:270,H:"Хэй, потрясно выглядишь! Как дела?"};
tr[35153] = {H:"Эйджей, отдай мне какую-нибудь вещь. Для фан-клуба."};
tr[35154] = {OId:270,H:"Мне нравится твоя уверенность. Могу дать тебе свой самый первый прикид, когда я был совсем юным."};
tr[35155] = {H:"Давай!"};
tr[35156] = {OId:150,H:"Я знаю, знаю! Мадам открывает фан-клуб, но у меня столько вещей! И все классные..."};
tr[35157] = {H:"Отдай мадам коньки с Ледового шоу."};
tr[35158] = {H:"Отдай мадам лиану из Шоу на выживание."};
tr[35159] = {H:"Отдай мадам костюм капусты из Шоу с розыгрышами."};
tr[35160] = {OId:150,H:"Нет, они напоминают мне о победе в Ледовом шоу..."};
tr[35161] = {H:"Эх, Сирена! Так ты ни с чем не расстанешься. Давай лучше сделаем что-нибудь своими руками."};
tr[35162] = {OId:150,H:"Нет, я на этой лиане до сих пор люблю покачаться. Когда грущу..."};
tr[35163] = {OId:150,H:"Нет, этот костюм такой страшный, что помогает мне не забыть, какая же я сама красивая."};
tr[35164] = {OId:150,H:"Ой, отличная идея! С новой вещью мне не жалко будет расстаться."};
tr[35165] = {H:"Приступим."};
tr[35166] = {OId:270,H:"Привет! Сто ты исесшь сдесь? Выглядис как цветок лотоса в хмурый день."};
tr[35167] = {H:"Сяо, я собираю коллекцию звёздных вещей для фан-клуба. Можешь помочь?"};
tr[35168] = {OId:270,H:"Могу подарить тебе свои парики. Только по насей японской традисии их охраняет..."};
tr[35169] = {H:"Кто?"};
tr[35170] = {OId:270,H:"Гросный робот-осьминог с супальцами! Пройди его испытание в Смесмаге и полусис парики!"};
tr[35171] = {H:"Я справлюсь!"};
tr[35172] = {H:"Фон " + "\"" + "Гроза" + "\"" + ""};
tr[35173] = {H:"Пижама солнечного зайчика"};
