tr[35183] = {H:"Костюм ученика мага"};
tr[35184] = {H:"Я спас Кроша и научился крутым приёмчикам в Школе магов в Шарараме. Приходи на занятия и ты!"};
tr[35185] = {OId:270,H:"Пройди испытание осьминога в Смесмаге и получишь мои локоны!"};
tr[35186] = {OId:0,H:"Перо с чернилами|Перо принесут через {0} мин."};
tr[35187] = {OId:270,H:"Найди звёзд в Шарараме и собери предметы для фан-клуба!"};
tr[35188] = {OId:270,H:"Привет! Какой чудесный день. Спасибо, что помог мне собрать коллекцию звёздных вещей."};
tr[35189] = {H:"Мадам, а где же фан-клуб, который вы обещали?"};
tr[35190] = {OId:270,H:"Где? Да он повсюду! Я поставила в разных местах Шарарама голограммы звёзд."};
tr[35191] = {H:"Голограммы? Что это за чудеса? Вы сами их построили?"};
tr[35192] = {OId:270,H:"Мне помог один гениальный тролль из Тёмного царства. И ты помог."};
tr[35193] = {H:"Но что делают эти голограммы?"};
tr[35194] = {OId:270,H:"А ты возьми и проверь. Например, здесь в Сити или в других местах. А потом возвращайся ко мне."};
tr[35195] = {H:"Хорошо, сейчас посмотрю."};
tr[35196] = {OId:270,H:"Испытай голограмму - кликни на автомат с ней. А потом возвращайся ко мне."};
tr[35197] = {H:"Автомат пока не работает. Сначала поговори с мадам Жабо в Сити!"};
tr[35198] = {OId:592,H:"У нас нет работы! Никто не приглашает нас выступать, ведь есть голограммы. Деньги кончаются..."};
tr[35199] = {OId:593,H:"Раньше я завтракала клубникой, а теперь кашей. Фу!"};
tr[35200] = {H:"Бедные звёзды. Надо отключить голограммы, чтобы богатство к вам вернулось"};
tr[35201] = {H:"Просто вы обленились. Устройте крутой концерт, и всё наладится."};
tr[35202] = {OId:594,H:"А как же Смешарики, которых радуют мои голограммы. Всего 10 Смешинок - и ты на концерте звезды."};
tr[35203] = {H:"Да уж, настоящий концерт будет подороже."};
tr[35204] = {OId:594,H:"Вот и я так считаю. Мои голограммы приносят радость всем Смешарикам! И всего за 10 Смешинок."};
tr[35205] = {H:"Да уж, это подешевле концерта звёзд."};
tr[35206] = {OId:593,H:"Наши концерты лучше! Они живые, яркие и неповторимые."};
tr[35207] = {OId:594,H:"Зато мои голограммы не устают, не капризничают и всегда попадают в ноты!"};
tr[35208] = {H:"Сирена права. Голограммы надо убрать."};
tr[35209] = {H:"Мадам права. Голограммы Смешарикам принесут больше пользы."};
tr[35210] = {OId:593,H:"Юху! Голограммы больше никому не интересны. А мы снова богаты."};
tr[35211] = {OId:594,H:"Но почему? Мои голограммы прекрасно работали..."};
tr[35212] = {H:"Из каждого автомата с голограммой я вытащил ГипноЧип. Что это?"};
tr[35213] = {OId:596,H:"ГипноЧип? Значит голограммы никому не нравились. А Смешарики были ими загипнотизированы!"};
tr[35214] = {OId:594,H:"Не может быть..."};
tr[35215] = {H:"Мадам, голограммы создали вы. Не хотите рассказать про ГипноЧип?"};
tr[35216] = {OId:594,H:"Если только... тот гениальный слуга Злобикуса, который мне помогал..."};
tr[35217] = {H:"Ох, Мадам, зачем просить помощи у злодея?"};
tr[35218] = {OId:596,H:"Служу Злобикусу!"};
tr[35219] = {OId:595,H:"А затем, чтобы загипнотизировать всех и подчинить моему хозяину, Злобикусу!"};
tr[35220] = {OId:594,H:"Служу Злобикусу!"};
