tr[35443] = {OId:270,H:"Сяо Мяо принесла мне новый альбом. Удивительно: ни одного слова по-японски не знаю, а всё равно понял, что все песни о дружбе."};
tr[35444] = {H:"Ба-Босс, просто у тебя чутьё на музыку! Поможешь мне?"};
tr[35445] = {OId:270,H:"А ты принёс мне что-то послушать? Да я с удовольствием!"};
tr[35446] = {H:"Да, у меня есть запись рыбьих песен. Хочу выучить по ней рыбий язык."};
tr[35447] = {OId:270,H:"Поговори с рыбами - теперь мы знаем их язык!"};
tr[35448] = {OId:599,H:"Гы-гы! Эти дурашки совсем не понимают, что мы говорим. Давай притворимся немыми рыбами?"};
tr[35449] = {OId:600,H:"Давай!"};
tr[35450] = {H:"..."};
tr[35451] = {OId:599,H:"Гыыы! Они никогда не узнают, что мы слуги Злобикуса и шпионим за Шарарамом."};
tr[35452] = {OId:600,H:"И готовим нападение злобырей с моря!"};
tr[35453] = {H:"А зачем же нападать с моря?"};
tr[35454] = {OId:599,H:"Потому никто, даже агенты, не ждут атаки с моря. А ещё наша летающая субмарина всех отвлекает."};
tr[35455] = {OId:600,H:"Эй... А мне показалось, или этот Смешарик нас..."};
tr[35456] = {H:"Да-да! Я вас понимаю. И очень хорошо. Так что там с нападением?"};
tr[35457] = {OId:599,H:"Нас раскрыли! О Смешарик, пощади мои плавники!"};
tr[35458] = {OId:600,H:"Мы всё скажем! Всё! Например, про подводную базу злобырей..."};
tr[35459] = {H:"А вот это уже интересно!"};
tr[35460] = {OId:270,H:"Прогнать злобырей помогут рыбы! Поговори с ними."};
tr[35461] = {OId:598,H:"Подводные злобыри? Не дай им напасть на Шарарам!"};
tr[35462] = {H:"Совы не спят?"};
tr[35463] = {H:"Я птица ночная! Ещё бы - столько хлопот, спать не хочется! Но для здоровья надо... Поможешь мне победить бессонницу?"};
tr[35464] = {H:"Я усну, если устану. Приходи на Пляж."};
tr[35465] = {H:"Поиграй с Крошем волейбол и заработай {0} Смешинок. А я буду за вами наблюдать."};
tr[35466] = {H:"А ещё в сон клонит после обеда. Поработай в кафе."};
tr[35467] = {H:"Ох, я так утомилась, глядя, как вы играете. Да и ещё и объелась. Но сон так и не пришёл."};
tr[35468] = {H:"Совы не спят?"};
tr[35469] = {H:"Я вычитала, что от жары хочется спать."};
tr[35470] = {H:"Отправляйся в Египет."};
tr[35471] = {H:"Сыграй в игру богини Солнца Сехмет."};
tr[35472] = {H:"Кокосовое молоко успокаивает. Собери {0} кокосов."};
tr[35473] = {H:"Тепло и уютно! Баю-бай, баю-бай... Ух, Смешинки забирай..."};
tr[35474] = {H:"Совы не спят?"};
tr[35475] = {H:"Совунья уснула! Но кто теперь позаботится о Смешариках? Кроме неё этого никто не умел."};
tr[35476] = {H:"Болельщики шалят. Приходи в Парк аттракционов."};
tr[35477] = {H:"Успокой болельщиков. Покажи им хорошую игру - сыграй в Футбол."};
tr[35478] = {H:"Устрой зарядку с помидорами. Кинь {0} штук."};
tr[35479] = {H:"Спасибо! В Шарараме стало спокойнее. Держи награду."};
tr[35480] = {H:"Совы не спят?"};
tr[35481] = {H:"Крошки остались без присмотра. Скорее к ним!"};
tr[35482] = {H:"Приходи в Детский сад."};
tr[35483] = {H:"Поработай няней в Детском саду и заработай {0} Смешинок за 1 раз."};
tr[35484] = {H:"Для компота крошкам собери {0} груш в Ромашковой долине."};
tr[35485] = {H:"Дружище, ты отлично справляешься. Держи Смешинки!"};
tr[35486] = {H:"Совы не спят?"};
tr[35487] = {H:"Уах... Как приятно проснуться утром и никуда не спешить. Я поняла: безделье в меру полезно. Научишь меня?"};
tr[35488] = {H:"Никаких серьёзных дел! Сходи в гости к {0} друзьям."};
tr[35489] = {H:"Поболтай со Смешариками. Отправь {0} сообщений на Шарафон."};
tr[35490] = {H:"Отдохнём в уютном креслице. Найди в магазине кресло " + "\"" + "Воздушный шар" + "\"" + " и купи."};
tr[35491] = {H:"Спасибо! Ты и мне помог, и за Смешариками проследил. Держи награду."};
tr[35492] = {H:"Как устать?"};
tr[35493] = {H:"Жара клонит в сон!"};
tr[35494] = {H:"Успокой Смешариков!"};
tr[35495] = {H:"Забота о крошках"};
tr[35496] = {H:"Полезное безделье"};
tr[35497] = {H:"Костюм Кибер-Самурая"};
tr[35498] = {H:"Шкаф в домик"};
tr[35499] = {H:"Пирамида в домик"};
tr[35500] = {H:"Кресло для друга"};
tr[35501] = {H:"Кресло для подруги"};
tr[35502] = {H:"Кубок дружбы.|За участие в дружеском турнире по Смешарикам."};
tr[35503] = {H:"Стул " + "\"" + "Бугага" + "\"" + ""};
tr[35504] = {H:"Бомбер " + "\"" + "Звёзды зажигают!" + "\"" + ""};
tr[35505] = {H:"Спутник " + "\"" + "Белый тигр" + "\"" + ""};
tr[35506] = {H:"Фон " + "\"" + "Звёзды зажигают!" + "\"" + ""};
tr[35507] = {H:"Дверь к морю"};
tr[35508] = {H:"СмеШутка " + "\"" + "Принцесса" + "\"" + ""};
tr[35509] = {H:"СмеШутка " + "\"" + "Крутыш" + "\"" + ""};
tr[35510] = {H:"СмеШутка " + "\"" + "Лучший друг" + "\"" + ""};
tr[35511] = {H:"СмеШутка " + "\"" + "Любимая подружка" + "\"" + ""};
tr[35512] = {H:"СмеШутка " + "\"" + "Любимая подружка" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!"};
tr[35513] = {H:"СмеШутка " + "\"" + "Лучший друг" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!"};
tr[35514] = {H:"СмеШутка " + "\"" + "Крутыш" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!"};
tr[35515] = {H:"СмеШутка " + "\"" + "Принцесса" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!"};
tr[35516] = {H:"Домик Шаролёт"};
tr[35517] = {H:"СмеШутка " + "\"" + "Субмарина" + "\"" + ""};
tr[35518] = {H:"СмеШутка " + "\"" + "Загадочная субмарина" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь призывать субмарину ещё дней: {0}|Ты можешь призывать субмарину всегда!"};
tr[35519] = {H:"Спутник " + "\"" + "Рыбка-страж" + "\"" + ""};
tr[35521] = {H:"Я спас Смешариков от злобных рыб! Заходи в игру и стань героем!"};
tr[35522] = {H:"Как устроить вечеринку?"};
tr[35523] = {H:"Уже 4 вечеринки подряд я посвящаю пиратам... Потому что идеи кончились! Помоги мне придумать крутые темы для тусовок в клубах."};
tr[35524] = {H:"Приходи в Ромашковую долину."};
tr[35525] = {H:"Спроси в общем чате: " + "\"" + "Какую вечеринку устроить?" + "\"" + ""};
tr[35526] = {H:"Накопи Позитивную энергию. Заработай {0} штук в играх."};
tr[35527] = {H:"Ты подбросил мне идею! Темы для вечеринок помогут придумать профи своего дела."};
tr[35528] = {H:"Как устроить вечеринку?"};
tr[35529] = {H:"Вечеринку красят гости! А гостей - костюмы. Давай подберём красивые наряды для похода в клубы."};
tr[35530] = {H:"Украсим костюм цветами. Собери {0} штук в Турфирме."};
tr[35531] = {H:"Посмотри, как наряжается фея в Джунглях - съезди туда."};
tr[35532] = {H:"Поработай с коллекцией. Сыграй в Модельера в Доме мод."};
tr[35533] = {H:"Мы совместили высокую моду и экзотические наряды. Молодец!"};
tr[35534] = {H:"Как устроить вечеринку?"};
tr[35535] = {H:"Я считаю, что на вечеринке важнее всего интерьер!"};
tr[35536] = {H:"Посмотри, как оформляют клубы Смешарики. Посети {0} вечеринок."};
tr[35537] = {H:"В моде натуральные материалы. Собери их - сыграй в Дары леса."};
tr[35538] = {H:"Неожиданный декор есть на Пляже. Выиграй в Секретики."};
tr[35539] = {H:"Ура! Ты собрал дары моря и леса - они украсят любую вечеринку."};
tr[35540] = {H:"Как устроить вечеринку?"};
tr[35541] = {H:"Ба-Босс потерял идеи? Так ему надо просто сытно пообедать. Как и гостям любой вечеринки!"};
tr[35542] = {H:"Научись заботиться о гостях. Сыграй в Кафе на Пляже."};
tr[35543] = {H:"Узнай, чем кормят в клубах. Собери {0} флаерса в Клубном квартале."};
tr[35544] = {H:"Напиши {0} сообщений на Шарафон: " + "\"" + "А какое у тебя любимое блюдо?" + "\"" + "."};
tr[35545] = {H:"Ай молодца! Лови награду."};
tr[35546] = {H:"Как устроить вечеринку?"};
tr[35547] = {H:"Я придумал! Устроим вечеринку в стиле туземцев. Клуб будет на необитаемом острове, а на закуски подадим бутерброды с мармеладными червячками."};
tr[35548] = {H:"Исследуй море в поисках острова. Сыграй в Катер в Порту и набери {0} Смешинок"};
tr[35549] = {H:"Накопи {0} Смешинок на мармелад."};
tr[35550] = {H:"Вечеринка прошла на ура! Теперь у меня много свежих идей - спасибо."};
tr[35551] = {H:"Ищем идеи."};
tr[35552] = {H:"Придумываем костюмы."};
tr[35553] = {H:"Украшаем клубы."};
tr[35554] = {H:"Составляем меню."};
tr[35555] = {H:"Веселимся!"};
tr[35556] = {H:"Противогаз Копатыча"};
tr[35557] = {H:"Фон " + "\"" + "Котики" + "\"" + ""};
tr[35558] = {H:"Шапка " + "\"" + "Всегда тепло" + "\"" + ""};
tr[35559] = {H:"Жилет " + "\"" + "Всегда тепло" + "\"" + ""};
tr[35560] = {H:"Кроссовки с носочком"};
tr[35561] = {H:"Фонтан-зонтик"};
tr[35562] = {H:"Смайлы №3"};
tr[35563] = {H:"Диван " + "\"" + "Стильная зебра" + "\"" + ""};
tr[35564] = {H:"Причёска " + "\"" + "Смарт-косы" + "\"" + ""};
tr[35565] = {H:"Шарафон " + "\"" + "Божья коровка" + "\"" + ""};
tr[35566] = {OId:270,H:"В космос собрался? А ну марш на медосмотр! Заодно расскажу тебе про чудеса медицины."};
tr[35567] = {H:"Это полезно! Смогу вылечить туристов, если что."};
tr[35568] = {OId:270,H:"Хочешь стать экскурсоводом? Сначала я сам проведу для тебя экскурсию!"};
tr[35569] = {H:"Ура, расскажи мне про чудеса космоса."};
tr[35570] = {OId:270,H:"Ну и планетка! Туристов мы сюда привезём, а кормить их чем? Кругом одни сорняки."};
tr[35571] = {H:"И что же делать?"};
tr[35572] = {OId:270,H:"Я задумал посадить космо-огород. Сейчас и тебя обучу."};
tr[35573] = {H:"Ура!"};
tr[35574] = {OId:270,H:"Скорее на корабль. Космос ждёт!"};
tr[35575] = {H:"Кого? Меня?"};
tr[35576] = {H:"И я подожду..."};
tr[35577] = {OId:270,H:"Конечно! Хватай штурвал и полетели."};
tr[35578] = {H:"Но я... не умею. Научишь?"};
tr[35579] = {H:" Я отправил туристов в космос! Приходи в Шарарам и веселись."};
tr[35580] = {H:"Куртка космонавта"};
tr[35581] = {H:"Постер " + "\"" + "Космический корабль" + "\"" + ""};
tr[35582] = {H:"Задорная кепка"};
tr[35583] = {H:"Кепка с косичками"};
tr[35584] = {H:"2 задорные кепки"};
tr[35585] = {OId:270,H:"Приготовь супчик и тортик, стань СуперКулинаром и выиграй призы."};
tr[35587] = {H:"Кресло для тебя"};
tr[35588] = {H:"Кресло для пёсика"};
tr[35589] = {H:"Кресла для тебя и пёсика"};
tr[35590] = {H:"Фон " + "\"" + "Чудеса" + "\"" + ""};
tr[35591] = {H:"Свитшот " + "\"" + "На удачу" + "\"" + ""};
tr[35592] = {H:"Сказочное дерево"};
tr[35593] = {H:"Счастливая толстовка"};
tr[35594] = {H:"Причёска " + "\"" + "Счастливые кудри" + "\"" + ""};
tr[35595] = {H:"Счастливые кеды"};
tr[35596] = {H:"Фон " + "\"" + "Слайм" + "\"" + ""};
tr[35597] = {H:"Куртка " + "\"" + "MC" + "\"" + ""};
tr[35598] = {H:"Причёска " + "\"" + "MC" + "\"" + ""};
tr[35599] = {H:"Причёска " + "\"" + "MC" + "\"" + ""};
tr[35600] = {H:"Очки " + "\"" + "MC" + "\"" + ""};
tr[35601] = {H:"Кроссовки " + "\"" + "На стиле" + "\"" + ""};
tr[35602] = {H:"Пальто " + "\"" + "Краски осени" + "\"" + ""};
tr[35603] = {H:"Причёска " + "\"" + "Геометрия" + "\"" + ""};
tr[35604] = {H:"Причёска " + "\"" + "Геометрия" + "\"" + ""};
tr[35605] = {H:"Ботильоны " + "\"" + "Яркая осень" + "\"" + ""};
tr[35606] = {H:"Тренч " + "\"" + "Краски осени" + "\"" + ""};
tr[35607] = {H:"Умные часы"};
tr[35608] = {H:"Усатый фон"};
tr[35609] = {H:"Кепка " + "\"" + "Осенняя прогулка" + "\"" + ""};
tr[35610] = {OId:270,H:"Не трогай холодильник. Лучше Доку позвони!"};
tr[35611] = {OId:603,H:"Тебя заперли во сне. Позвонить Доку нельзя."};
tr[35612] = {OId:270,H:"Избавь номера от тёмных сил. Кликни на лифт, чтобы начать."};
tr[35613] = {OId:270,H:"Тёмных сил стало меньше. Кликни на лифт, чтобы продолжить их изгонять."};
tr[35614] = {OId:270,H:"Скоро ты спасёшь отель от тьмы. Кликни на лифт, чтобы изгнать остатки нечисти."};
tr[35615] = {OId:270,H:"Избавь номера от тёмных сил. Кликни на лифт, чтобы начать."};
tr[35616] = {OId:603,H:"Дунь в свисток - кликни на него в чемоданчике!"};
tr[35617] = {OId:603,H:"Поговори с нечистью!"};
tr[35618] = {OId:603,H:"Победи Марашек!"};
tr[35619] = {OId:603,H:"Поговори с девчонками в номере!"};
tr[35620] = {OId:603,H:"Вымани домового! Кликай на ванну."};
tr[35621] = {OId:603,H:"Разузнай, где домовой спрятал Смешариков!"};
tr[35622] = {OId:603,H:"Освободи Смешариков из паутины!"};
tr[35623] = {OId:270,H:"Смотри паутины-то сколько! В этом номере давно не убирались..."};
tr[35624] = {OId:603,H:"Найди в номере еду для котёнка!"};
tr[35625] = {OId:270,H:"Мя, мя, мя, мя, мя, мя, мя!"};
tr[35626] = {OId:603,H:"Найди в номере еду для котёнка!"};
tr[35627] = {OId:603,H:"Открой холодильник!"};
tr[35628] = {OId:603,H:"Покорми котёнка!"};
tr[35629] = {OId:603,H:"Ложись спать и защити котёнка от кошмаров."};
tr[35630] = {OId:270,H:"Кликни на кровать - так и ночь быстрее пройдёт."};
tr[35631] = {OId:270,H:"Ну и ну..."};
tr[35632] = {OId:270,H:"Ну вот! Я настоящий. А теперь проверь котёнка."};
tr[35633] = {OId:603,H:"Победи чудище - кликай на холодильник!"};
tr[35634] = {OId:605,H:"Рррр... Я раскрыт..."};
tr[35635] = {OId:604,H:"Слабость чудища в холодильнике. Кликай на него!"};
tr[35636] = {OId:270,H:"Ааа! Какой чистенький и красивый Смешарик... Иди к нам! Иди, иди."};
tr[35637] = {H:"Не пойду я! Подозрительные вы."};
tr[35638] = {OId:270,H:"Смотри на эти картины. Правда, красивые? Это мы сделали: заперли внутри Нюшу, Сирену и Эллис."};
tr[35639] = {H:"Так вы... охотники за красотой?"};
tr[35640] = {OId:270,H:"Ага! Всех красавчиков и красавиц превращаем в картины. Сейчас и тебя в рисунок превратим и в рамочку вставим!"};
tr[35641] = {H:"Ну уж нет!"};
tr[35642] = {OId:270,H:"Призрачные марашки пленили нас за то, что мы красивые!"};
tr[35643] = {H:"Это комплимент. Даже призраки ценят красоту."};
tr[35644] = {H:"Это урок. Важна не красота, а друзья, готовые прийти на помощь (это я)."};
tr[35645] = {OId:601,H:"Уииии! А можно я снова буду картиной, чтобы мной все любовались?"};
tr[35646] = {H:"Нет, Нюша! Ты нужна нам настоящей, а не нарисованной."};
tr[35647] = {OId:602,H:"Какие мудрые слова! Спасибо, что спас меня и гостей моего отеля."};
tr[35648] = {H:"Не за что!"};
tr[35649] = {OId:270,H:"В каждом доме есть домовой! То есть я. Ежели кто меня не уважает, то я начинаю пакостить."};
tr[35650] = {H:"Домовой-домовой, не сердись, я не злой!"};
tr[35651] = {OId:270,H:"Охохо! Люблю стихи. Говори, зачем пришёл."};
tr[35652] = {H:"Служащие отеля куда-то запропастились? Нет ли их у тебя?"};
tr[35653] = {OId:270,H:"Видал тут парочку. Сказали - пыльный я. А я не пыльный... Просто шерстистый..."};
tr[35654] = {H:"И где же они теперь?"};
tr[35655] = {OId:270,H:"Так запер я их! Они меня метлой вздумали гнать, вот я и начал буянить."};
tr[35656] = {H:"Домовой-домовой, отпусти Смешариков! Они не будут тебя обижать."};
tr[35657] = {OId:270,H:"Не отпущу! Хотя пирожки у тебя вкусные... И водичка тёплая... Ладно, отпущу!"};
tr[35658] = {H:"Спасибо!"};
tr[35659] = {OId:270,H:"Мя-мя, мя-мя, мя-мя. Маааау... Мааааау...."};
tr[35660] = {H:"Ня-ня-ня, ня-ня, ня-мааааау!"};
tr[35661] = {H:"Котёночек, тебя не пугают призраки?"};
tr[35662] = {H:"(оба варианта продолжают)"};
tr[35663] = {OId:270,H:"Мя, мя, мя, мя, мя, мя, мя!"};
tr[35664] = {H:"Наверное, ты голоден. Поищу для тебя еды! Может, в холодильнике есть корм?"};
tr[35665] = {OId:603,H:"Бедная киса! Наверняка корм для неё лежит в холодильнике... Только это выглядит как ловушка."};
tr[35666] = {H:"Давай откроем холодильник! Заодно и призрака победим."};
tr[35667] = {OId:603,H:"Верно... Да-да... Будем смотреть в лицо страху! И котёнка спасём!"};
tr[35668] = {H:"Отлично, Док! Открываю холодильник."};
tr[35669] = {OId:270,H:"Мррр, мрррр, мммм! Очень вкусно, спасибо!"};
tr[35670] = {H:"Ой, а котёнок-то - говорящий!"};
tr[35671] = {OId:270,H:"Ничего удивительного! В Шарараме и не такое бывает. Можешь мне помочь?"};
tr[35672] = {H:"Конечно, могу!"};
tr[35673] = {OId:270,H:"Защити меня от призраков - переночуй в этом номере. Я таааак боююююсь!!!"};
tr[35674] = {H:"Не бойся! Буду охранять твой сон."};
tr[35675] = {OId:270,H:"Котик, давай лучше уйдём из отеля к Совунье. У неё безопаснее!"};
tr[35676] = {OId:270,H:"Нет, нет, нет! Я же кот! Мне чужие дома не нравятся. Мне только в отеле хорошо."};
tr[35677] = {H:"Хорошо. Буду охранять твой сон!"};
tr[35678] = {OId:270,H:"Ура! Ложись спать - кликни на кровать."};
tr[35679] = {H:"Окей."};
tr[35680] = {OId:270,H:"Ёлки-иголки... Я же написал: " + "\"" + "не открывай холодильник" + "\"" + "! Теперь ты накормил котика, и его силы стали ещё больше."};
tr[35681] = {H:"Крош, где мы?"};
tr[35682] = {OId:270,H:"Во сне! Котик запер нас во сне... Злой призрак - это он! Мне едва хватило сил оставить эту надпись и предупредить, но..."};
tr[35683] = {H:"Трудно поверить, что котик злой. Хорошо, что у меня есть рассеиватель иллюзий."};
tr[35684] = {OId:270,H:"Рассеиватель иллюзий? Что это?"};
tr[35685] = {H:"Изобретение Дока! Сейчас я направлю его на тебя и на котика. Вот и узнаем, кто из вас призрак!"};
tr[35686] = {OId:606,H:"Я повелеваю морским ужасом! Ты никогда не отгадаешь мою загадку! Скажи, кто в морской пучине умеет жалить?"};
tr[35687] = {H:"Ха, да это же пчела жалит. Подводная... Есть же подводные пчёлы?"};
tr[35688] = {H:"Медуза."};
tr[35689] = {OId:606,H:"Ты ошибся... Мне это нравится!"};
tr[35690] = {H:"Попробую ответить снова."};
tr[35691] = {OId:606,H:"Не может быть! Вот ещё загадка: кто создаёт жемчуг?"};
tr[35692] = {H:"Краб."};
tr[35693] = {H:"Моллюск."};
tr[35694] = {OId:606,H:"Ррррр... И снова верно. Ответишь на эту загадку, и я сдамся! Сколько щупалец у спрута?"};
tr[35695] = {H:"Шесть."};
tr[35696] = {H:"Восемь."};
tr[35697] = {OId:270,H:"Я повелеваю страшными видениями. Скажи, как зовут ожившую говорящую тыкву?"};
tr[35698] = {H:"Джон."};
tr[35699] = {H:"Джек."};
tr[35700] = {OId:270,H:"Ха-ха-ха! Чем больше ты ошибаешься, тем больше я смеюсь."};
tr[35701] = {OId:270,H:"Ладно, это было легко. Вот ещё: как зовут доброго вампира из Шарарама?"};
tr[35702] = {H:"Сумрак."};
tr[35703] = {H:"Фредди."};
tr[35704] = {OId:270,H:"О, ты с ним знаком? Ладно, третий вопрос, и я отстану. В кого умеют превращаться вампиры?"};
tr[35705] = {H:"В паука."};
tr[35706] = {H:"В летучую мышь."};
tr[35707] = {OId:607,H:"В моей власти древний ужас. Ответь: кто охраняет пирамиды Египта?"};
tr[35708] = {H:"Минотавры."};
tr[35709] = {H:"Мумии."};
tr[35710] = {OId:607,H:"Ошибки делают меня сильнее. Продолжай ошибаться!"};
tr[35711] = {H:"А вот и нет. Попробую ответить снова и не ошибиться."};
tr[35712] = {OId:607,H:"Ладно... А как называется ведьминская встреча?"};
tr[35713] = {H:"Шабаш."};
tr[35714] = {H:"Полтергейст."};
tr[35715] = {OId:607,H:"У меня кончаются загадки... Эта - последняя. В каком краю обитают вампиры и прочие ужасы?"};
tr[35716] = {H:"В Пенсильвании."};
tr[35717] = {H:"В Трансильвании."};
tr[35718] = {OId:608,H:"Посмотри, сколько Смешариков ты спас!"};
tr[35719] = {OId:272,H:"Ты отлично справился! Тёмные силы покинули отель."};
tr[35720] = {H:"Ура!"};
tr[35721] = {OId:608,H:"Скоро я наведу здесь порядок. И тогда мы сможем снова принять гостей."};
tr[35722] = {OId:272,H:"Ну а тебе полагается награда!"};
tr[35723] = {H:"Ура-ура!"};
tr[35724] = {OId:270,H:"Возьми фотоаппарат из чемоданчика и перенеси на этот предмет."};
tr[35725] = {OId:270,H:"Возьми корм, наведи на котёнка и кликни."};
tr[35726] = {H:"Рассеиватель иллюзий!"};
tr[35727] = {OId:270,H:"Тебя заперли во сне. Позвонить Доку нельзя."};
tr[35728] = {OId:270,H:"Возьми фонарь из чемоданчика и перенеси на котёнка или Кроша"};
tr[35729] = {OId:17,H:"Батарейка|Батарейка зарядится\nчерез {0} мин."};
