tr[35866] = {H:"СмеШутка " + "\"" + "Зов Вселенной" + "\"" + ""};
tr[35867] = {H:"СмеШутка " + "\"" + "Зов Вселенной" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней:{0}|Ты можешь шутить всегда!"};
tr[35868] = {OId:270,H:"Первое задание: разыщи в Шарараме агентов и подготовься к операции."};
tr[35869] = {OId:270,H:"Готовишься к операции в Тёмном царстве? Позволь-ка тебя... понюхать!"};
tr[35870] = {H:"Эй! Что за шутки?"};
tr[35871] = {OId:270,H:"Нюх-нюх! Нет, не годится. У Злобырей прекрасный нюх на Смешариков. Надо замаскировать твой запах."};
tr[35872] = {H:"А как это сделать?"};
tr[35873] = {OId:270,H:"Наряд у тебя, конечно, модный, но в Тёмном царстве так ходить не принято. Ты будешь выделяться."};
tr[35874] = {H:"Давай я превращусь в злобыря! И тогда никаких вопросов."};
tr[35875] = {OId:270,H:"Если бы... Это тебе кажется, что Злобыри одинаковые. А на самом деле – разные. И все между собой знакомы!"};
tr[35876] = {H:"Значит, надо притвориться кем-то злым. И незнакомым!"};
tr[35877] = {OId:270,H:"Верно. Однажды Босс Ба-Босс съел мороженое чудиков и превратился в монстра. Вот под него тебя и замаскируем."};
tr[35878] = {H:"Под монстра Ба-Босса? Любопытно!"};
tr[35879] = {OId:270,H:"В Тёмном царстве говорят на змеином языке. Выучишшшь его, и тогда тебя примут за своего."};
tr[35880] = {H:"А я уже говорю по-змеиному. Слушай: " + "\"" + "Шшшуу, шши, шшш, шаа" + "\"" + "!"};
tr[35881] = {OId:270,H:"Говоришь, я съела носки Копатыча? Но это неправда! Они... Просто пропали. А вот язык стоит подучить."};
tr[35882] = {H:"Верно. А то наговорю лишнего."};
tr[35883] = {H:"Чёрная роза|Роза распустится через {0} мин."};
tr[35884] = {OId:270,H:"Знаешь, что такое легенда для секретного агента?"};
tr[35885] = {H:"Рассказ о его подвигах."};
tr[35886] = {H:"Сказка на ночь."};
tr[35887] = {OId:270,H:"Никак нет. В Тёмном царстве ты притворишься монстром. А злобыри спросят, зачем ты пришёл."};
tr[35888] = {H:"И я расскажу им... свою легенду?"};
tr[35889] = {OId:270,H:"Точно. Это выдуманная история для шпиона, чтобы не выдать себя. Сейчас сочиним!"};
tr[35890] = {H:"Давай."};
tr[35891] = {OId:270,H:"Ну и злобный же у тебя вид! Чего пришёл?!"};
tr[35892] = {H:"Я пришёл освободить Снежинок!"};
tr[35893] = {H:"Я ключник. Пришёл чинить замки в темнице."};
tr[35894] = {OId:270,H:"Подозрительно! У меня в списке ничего про тебя нет."};
tr[35895] = {H:"А ты не в список гляди! Лучше у Злобикуса спроси. Да скажи ему, что отказался меня впускать."};
tr[35896] = {H:"Ты прав. Я на самом деле секретный агент."};
tr[35897] = {OId:270,H:"Щщщщ... Ладно, проходи. Двери у нас и вправду скрипучие. Так громко скрипят, что вздохов пленников не слышно, ахаха!"};
tr[35898] = {H:"Ах ты негодяй! Над пленниками издеваешься? Я тебе покажу!"};
tr[35899] = {H:"Ты в сторону-то отойди, злобырёк, а то невзначай рогами зацеплю. Поранишься!"};
tr[35900] = {OId:270,H:"Проберись в Тёмное царство и найди Снежинок. Кликни на вертолёт, чтобы туда улететь."};
tr[35901] = {OId:270,H:"Ууу, рогатый, не нервируй меня! Ступай в темницу и делай свои дела."};
tr[35902] = {OId:270,H:"Ничего тут не трогай! Пленники Злобикуса под моей охраной."};
tr[35903] = {OId:270,H:"Ты чего это двери дёргаешь?"};
tr[35904] = {H:"Злобикус послал меня проверить, как вы тут справляетесь. Вижу вот, замки хлипкие."};
tr[35905] = {H:"Отпирай двери – я хочу Снежинок освободить."};
tr[35906] = {OId:270,H:"О, сам Злобикус! И давно он попросил тебя?"};
tr[35907] = {H:"Да... Вот... Прямо сегодня! Прямо утром!"};
tr[35908] = {H:"Он и не просил, это Шеф отправил меня на миссию."};
tr[35909] = {OId:270,H:"Враньё! В нашем царстве не бывает утра... Сознавайся, откуда ты?"};
tr[35910] = {H:"Сейчас расскажу!"};
tr[35911] = {OId:270,H:"Прими командование космофлотом, обыграй соперников и выиграй призы!"};
tr[35912] = {H:"Командуй флотом!"};
tr[35913] = {H:"Фон " + "\"" + "Хозяин космоса" + "\"" + ""};
tr[35914] = {H:"Китель " + "\"" + "Адмиральский" + "\"" + ""};
tr[35915] = {H:"Китель " + "\"" + "Адмиральский" + "\"" + ""};
tr[35916] = {H:"Адмиральская награда.|За создание самого сильного космофлота!"};
tr[35917] = {OId:270,H:"Спасибо, мы свободны! Но как отсюда выбраться?"};
tr[35918] = {H:"Картинка " + "\"" + "Боулинг" + "\"" + ""};
tr[35919] = {H:"Платье " + "\"" + "Смекалка" + "\"" + ""};
tr[35920] = {H:"Спутник " + "\"" + "Умный ЗяброКот" + "\"" + ""};
tr[35921] = {H:"Спортивные стикеры"};
tr[35922] = {OId:270,H:"Страшно! Поскорее бы отсюда уйти..."};
tr[35923] = {OId:270,H:"Тааак. Не понял. Ты должен был замки чинить... А пленников-то куда повёл?"};
tr[35924] = {H:"Это не пленники! Это... Злобыри..."};
tr[35925] = {H:"Это секретная информация! Ты мои рога видел? Вопросы есть?"};
tr[35926] = {OId:270,H:"Чего-то не похожи на Злобырей. Ты мне врёшь?"};
tr[35927] = {H:"Нет, конечно! Злобикус сам их создал, чтобы Шарарам заморозить. Я туда и веду."};
tr[35928] = {H:"Да, я вру. Это пленники, а я их спасаю."};
tr[35929] = {OId:270,H:"Видел-видел... Но что мне хозяину-то сказать?"};
tr[35930] = {H:"Злобикусу? Ничего не говори, он сам всё знает."};
tr[35931] = {H:"Скажи, что секретный агент из Шарарама передаёт привет."};
tr[35932] = {OId:270,H:"Ну хорошо. Тогда ступай, не буду тебя тревожить."};
tr[35933] = {H:"Ага-ага. Мы уходим."};
tr[35934] = {OId:610,H:"Операция " + "\"" + "Снежинка" + "\"" + " прошла успешно! Позволь вручить тебе..."};
tr[35935] = {OId:609,H:"Ой, а что это там в небе?"};
tr[35936] = {H:"Где?"};
tr[35937] = {OId:610,H:"Я ничего не вижу!"};
tr[35938] = {H:"И я!"};
tr[35939] = {OId:610,H:"О, нет! Это сам Злобикус!"};
tr[35940] = {OId:609,H:"Он прилетел нас похитить. Снова!"};
tr[35941] = {H:"Сейчас я его достану! Хорошо, что вертолёт ещё здесь."};
tr[35942] = {OId:610,H:"Кликни на вертолёт и прогони Злобикуса!"};
tr[35943] = {H:"Парка " + "\"" + "Агент холода" + "\"" + ""};
tr[35944] = {H:"Бейсболка " + "\"" + "Агент холода" + "\"" + ""};
tr[35945] = {H:"Шарафон-невидимка"};
tr[35946] = {H:"Золотая кошечка и Спутник Енотик-девочка"};
tr[35947] = {H:"Пилюля для робота"};
tr[35948] = {H:"Ко мне заглянул необычный пациент. Робот! Что ж, попробую его вылечить. Поможешь мне?"};
tr[35949] = {H:"Пропишу роботу ванны из морской воды. Соберём её – сыграй в Катер в Порту."};
tr[35950] = {H:"Напиши в общий чат мою рекомендацию: " + "\"" + "Для здоровья нужен отдых и покой" + "\"" + "."};
tr[35951] = {H:"Приготовим микстуру. Собери {0} эликсиров в Школе магов."};
tr[35952] = {H:"Молодец! Лови Смешинки за помощь."};
tr[35953] = {H:"Пилюля для робота"};
tr[35954] = {H:"Моё лечение почему-то не помогает. Может, роботу нужен не врач, а кто-то другой? Давай разберёмся."};
tr[35955] = {H:"Узнай побольше о наших железных друзьях. Отправляйся в Страну роботов."};
tr[35956] = {H:"Сыграй в игру " + "\"" + "Собери робота" + "\"" + " и заработай {0} Смешинок за 1 раз."};
tr[35957] = {H:"Изучи детали. Поработай на конвейере и заработай {0} Смешинок."};
tr[35958] = {H:"Я получил письмо из железной страны. И узнал, что вылечить робота может не врач, а механик!"};
tr[35959] = {H:"Пилюля для робота"};
tr[35960] = {H:"Привет, я механик Яша. Сейчас в два счёта робота подлатаю."};
tr[35961] = {H:"Сходи в Автосалон и собери {0} чемоданчика с инструментами."};
tr[35962] = {H:"Запасись Позитивной энергией. Заработай {0} штуки в играх."};
tr[35963] = {H:"Накопи {0} Смешинок на новые детали для робота."};
tr[35964] = {H:"Клац-клац-дзинь. Готово, я починил робота! А тебе спасибо за помощь."};
tr[35965] = {H:"Пилюля для робота"};
tr[35966] = {H:"Выполняю приветствие. Включаю программу благодарности: " + "\"" + "Спасибо, что помог. Давай устроим вечеринку!" + "\"" + ""};
tr[35967] = {H:"Устроим марафон вечеринок. Посети {0} клубов."};
tr[35968] = {H:"Приглашай друзей. Напиши {0} сообщений на Шарафоны: " + "\"" + "Приходи веселиться в клубы!" + "\"" + ""};
tr[35969] = {H:"Развлекайся с друзьями. Сыграй в Секретики на Пляже."};
tr[35970] = {H:"Оцениваю праздник на 10 000 баллов. Вручаю тебе робо-подарок."};
tr[35971] = {H:"Лечебные процедуры"};
tr[35972] = {H:"Кто поможет роботу?"};
tr[35973] = {H:"Как починить робота?"};
tr[35974] = {H:"Железная погоня"};
tr[35975] = {H:"Я побывал в Тёмном царстве и подарил зиму Смешарикам!"};
tr[35976] = {H:"Тёмное царство"};
tr[35977] = {H:"Темница"};
tr[35978] = {H:"Кресло для раздумий"};
tr[35979] = {H:"Куртка " + "\"" + "Свет разума" + "\"" + ""};
tr[35980] = {H:"Стикеры " + "\"" + "Пончики" + "\"" + ""};
tr[35981] = {H:"Причёска " + "\"" + "Каменный дозор" + "\"" + ""};
tr[35982] = {H:"Костюм " + "\"" + "Среди песков" + "\"" + ""};
tr[35983] = {H:"Шапка с узором"};
tr[35984] = {H:"Шапка с очками " + "\"" + "Горнолыжник" + "\"" + ""};
tr[35985] = {H:"Куртка " + "\"" + "Горнолыжник" + "\"" + ""};
tr[35986] = {H:"Биг-Бен"};
tr[35987] = {H:"Кресло " + "\"" + "Уютные лепестки" + "\"" + ""};
tr[35988] = {H:"Фон " + "\"" + "Райский сад" + "\"" + ""};
tr[35989] = {H:"Причёска " + "\"" + "КосмоРок" + "\"" + ""};
tr[35990] = {H:"Платье " + "\"" + "КосмоРок" + "\"" + ""};
tr[35991] = {H:"Магия " + "\"" + "Эльф" + "\"" + " навсегда"};
tr[35992] = {H:"Камин " + "\"" + "Горизонты разума" + "\"" + ""};
tr[35993] = {H:"Очки " + "\"" + "Свет разума" + "\"" + ""};
tr[35994] = {H:"Куртка " + "\"" + "Свежая идея" + "\"" + ""};
tr[35995] = {H:"Сквиши-лисичка"};
tr[35996] = {H:"Милая игрушка для хорошего настроения!|Ищи на складе в домике.|Кликни, чтобы снять стресс."};
tr[35997] = {H:"Платье парикмахера"};
tr[35998] = {H:"Фартук барбера"};
tr[35999] = {H:"Куртка " + "\"" + "Вселенная" + "\"" + ""};
tr[36000] = {H:"Причёска " + "\"" + "Локоны Вселенной" + "\"" + ""};
tr[36001] = {H:"Фон " + "\"" + "Парикмахерская" + "\"" + ""};
tr[36002] = {H:"Причёска " + "\"" + "Галактика" + "\"" + ""};
tr[36003] = {H:"Причёска " + "\"" + "Орбита" + "\"" + ""};
tr[36004] = {H:"Знак парикмахерской"};
tr[36005] = {H:"Пушистый коврик"};
tr[36006] = {H:"Лохматый коврик"};
tr[36007] = {H:"Костюм " + "\"" + "Локоны Вселенной" + "\"" + ""};
tr[36008] = {H:"Мы привезли в Шарарам Праздник весёлых волосатиков! Нарядись к нему в Летающей тарелке в Бухте и приходи снова!"};
tr[36009] = {OId:270,H:"Я зябрийский Лохматеус. Поговори с Зюзелем и празднуй с нами!"};
tr[36010] = {OId:611,H:"Ищи Дедов Морозов в Шарараме и узнай, кто из них настоящий!"};
tr[36011] = {OId:613,H:"Разберись с подарками на площади у Больнички!"};
tr[36012] = {OId:616,H:"Да он издевается! Время избавить Шарарам от поддельных дедушек – кликай на них."};
tr[36013] = {OId:270,H:"Праздник, праздник... Да никакой это не праздник! Ты же знаешь, что на самом деле Дед Мороз это..."};
tr[36014] = {H:"Не дед, а внук?"};
tr[36015] = {H:"Робот?"};
tr[36016] = {OId:270,H:"Нет! Дед Мороз – переодетый взрослый. И никакой волшебной силы у него нет."};
tr[36017] = {H:"Взрослые, конечно, переодеваются. Но и реальный Дед Мороз существует!"};
tr[36018] = {H:"Ну и что? Новый год всё равно классный праздник."};
tr[36019] = {OId:270,H:"А ты докажи! Пока не увижу волшебства, ни во что не поверю."};
tr[36020] = {H:"Легко! Найду в Шарараме настоящего Деда Мороза и принесу тебе волшебства."};
tr[36021] = {OId:270,H:"Ху-ху, ху-ху! С наступающим! Я – Дед Мороз."};
tr[36022] = {H:"Привет, Совунья!"};
tr[36023] = {OId:270,H:"Ху-ху! Я не Совунья, говорю же, я – Дед Мороз."};
tr[36024] = {H:"А давай проверим?"};
tr[36025] = {OId:270,H:"Ху-ху, ху-ху! С наступающим! Я – Дед Мороз."};
tr[36026] = {H:"Привет, Карыч!"};
tr[36027] = {OId:270,H:"Ху-ху! Дружище, ты обознался. Говорю, я – Дед Мороз."};
tr[36028] = {H:"Хм. Развей мои сомнения!"};
tr[36029] = {OId:270,H:"Ху-ху, ху-ху! С наступающий! Я – Дед Мороз."};
tr[36030] = {H:"Привет, Пин!"};
tr[36031] = {OId:270,H:"Ху-ху! Ты сказайт ошибка, я реалистиш гросс-фатер."};
tr[36032] = {H:"Кто-кто?"};
tr[36033] = {OId:270,H:"Ху-ху, ху-ху! С наступающим, друг мой новогодний! Я – Дед Мороз."};
tr[36034] = {H:"Привет, Лосяш!"};
tr[36035] = {OId:270,H:"Ху-ху! Твоё утверждение ошибочно. Я настоящий дедушка."};
tr[36036] = {H:"А ты докажи!"};
tr[36037] = {OId:612,H:"Попались! Ну и что вы тут задумали?"};
tr[36038] = {OId:611,H:"Крош, мы хотим познакомить тебя с настоящим Дедом Морозом!"};
tr[36039] = {H:"И он уже спешит сюда."};
tr[36040] = {OId:612,H:"Ха! Быть такого не может, ведь все знают, что дед ненастоящий."};
tr[36041] = {H:"А с кем мы тогда только что по телефону говорили?"};
tr[36042] = {OId:612,H:"Ха-ха! Да с кем угодно! Вы его даже не видели."};
tr[36043] = {OId:611,H:"Ура! А вот и сообщение от Деда Мороза. Кажется, он уже рядом."};
tr[36044] = {H:"Какое сообщение?"};
tr[36045] = {OId:613,H:"Ху-ху, ху-ху! Я – Дед Мороз. Спасибо, что мне грелочку принёс."};
tr[36046] = {H:"Не за что, дедушка! И как тебя угораздило оледенеть?"};
tr[36047] = {OId:613,H:"Прохладно в пещерке-то, не замечаешь? Я хоть и Мороз, но сам холод не люблю."};
tr[36048] = {H:"Неожиданно! Дедушка, поможешь мне убедить Кроша, что ты настоящий?"};
tr[36049] = {OId:613,H:"Возможно, возможно... Но потом. У нас сейчас полно других дел, ведь праздник под угрозой!"};
tr[36050] = {H:"Не может быть! Что случилось?"};
tr[36051] = {OId:613,H:"Я уже отправил подарки Смешарикам, но они перепутались. Теперь Нюша получит сувенир Копатыча."};
tr[36052] = {H:"А Копатыч?"};
tr[36053] = {OId:613,H:"А Копатычу прилетит коробка Злобикуса! И так – всем. Беги к почте и разберись с подарками. Ты – моя единственная надежда."};
tr[36054] = {H:"Я спасу Новый год!"};
tr[36055] = {OId:615,H:"Ха! Опять поддельный дед. Или скажешь, что этот настоящий?"};
tr[36056] = {OId:614,H:"Я настоящий. Посмотри, сколько подарков. Все мои!"};
tr[36057] = {H:"Да! Раз столько подарков, значит дедушка настоящий."};
tr[36058] = {OId:615,H:"Неужели ты не видишь? У него ж борода – ватная."};
tr[36059] = {H:"Сам ты ватный. Не трогай дедушку!"};
tr[36060] = {OId:614,H:"Ааа! Разоблачили меня? Зато я все подарочки прибрал, а вам ничего не достанется."};
tr[36061] = {H:"Так ты специально притворился дедушкой, чтобы я добыл тебе подарки?"};
tr[36062] = {OId:615,H:"Обман, кругом обман..."};
tr[36063] = {OId:614,H:"Конечно, специально притворился! Но времени болтать у меня нет, прощайте!"};
tr[36064] = {H:"Мы тебя остановим!"};
