tr[36562] = {OId:270,H:"Посети все испытания турнира в Шарараме!"};
tr[36563] = {OId:270,H:"Беда! Поговори с рыцарем и узнай, что случилось."};
tr[36564] = {OId:270,H:"Отправляйся на поиски улик на Пляж!"};
tr[36565] = {OId:270,H:"Прошу помоги! Рыцарь подскажет, что делать."};
tr[36566] = {OId:270,H:"Отправляйся в убежище тайного общества на Пляже!"};
tr[36567] = {OId:270,H:"Найди место, где спрятаться!"};
tr[36568] = {OId:622,H:"Сходи на кухню и приготовь мармелад для нашего кубка!"};
tr[36569] = {OId:270,H:"Это случилось опять! Кубок украден, участники турнира... испачканы жвачкой и желе. Рыцарская честь посрамлена..."};
tr[36570] = {H:"А что произошло? И почему " + "\"" + "опять" + "\"" + "?"};
tr[36571] = {OId:270,H:"Ордену Шоколадных рыцарей уже много лет противостоит тайное общество, о котором мы ничего не знаем."};
tr[36572] = {H:"О! Тайное общество это интересно. Я помогу защититься от его нападок!"};
tr[36573] = {H:"Бррр... Тайное общество это страшно. Давай с ним быстрее разберёмся!"};
tr[36574] = {OId:270,H:"Спасибо! Эти загадочные, кхм, неизвестно кто, сорвали нам не один турнир... Ты совершишь подвиг, если найдёшь их."};
tr[36575] = {H:"И с чего же мне начать?"};
tr[36576] = {OId:270,H:"Одна дама сказала, что видела что-то подозрительное на Пляже. Проверь там. А я пока посторожу этих несчастных."};
tr[36577] = {H:"Договорились! Иду на Пляж."};
tr[36578] = {OId:270,H:"Наш кубок здесь! Значит, это действительно убежище тайного общества."};
tr[36579] = {H:"Забираем кубок и бежим!"};
tr[36580] = {OId:270,H:"Но как же рыцарская честь? Мы должны её отстоять и узнать, что затевает тайное общество."};
tr[36581] = {H:"Хорошо! Давай устроим засаду. Надо найти место, где спрятаться."};
tr[36582] = {OId:621,H:"Мармеладки! Так это вы испортили наш турнир!"};
tr[36583] = {OId:622,H:"Мы..."};
tr[36584] = {H:"Как не стыдно... Ваше тайное общество раскрыто!"};
tr[36585] = {OId:622,H:"Да это... это... Это вы должны извиняться! Вот!"};
tr[36586] = {H:"Почему это?"};
tr[36587] = {OId:622,H:"Потому что во время шоколадного турнира все забывают про нас и наши угощения."};
tr[36588] = {H:"Все любят шоколад, это правда."};
tr[36589] = {OId:622,H:"А как же мы? Наш мармелад очень вкусный! Но его никто не хочет во время турнира..."};
tr[36590] = {H:"А давайте совместим одно с другим. И никто не обидится!"};
tr[36591] = {OId:621,H:"Даю добро! Надо украсить наш шоколадный кубок мармеладками."};
tr[36592] = {OId:622,H:" Мы согласны!"};
tr[36593] = {H:"У вас же тут кухня? Приготовим мармелад там."};
tr[36594] = {OId:270,H:"Кубок - загляденье. И объеденье!"};
tr[36595] = {OId:270,H:"Хорошие новости!"};
tr[36596] = {OId:270,H:"Объявляю турнир закрытым! Победитель - ты. А за подвиги положена награда."};
