tr[36737] = {H:"СмеШутка " + "\"" + "Сундучок" + "\"" + "|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!"};
tr[36738] = {H:"Я отыскал сокровища вместе со Смешариками! Приходи в Шарарам – подарки ждут."};
tr[36739] = {H:"Гости из прошлого"};
tr[36740] = {H:"Привет! Раньше я возил туристов из настоящего в прошлое. А теперь наоборот - хочу привезти в Шарарам гостей из былых времён."};
tr[36741] = {H:"Чем кормить туристов в Шарараме? Поработай в Кафе на Пляже и получи {0} Смешинок."};
tr[36742] = {H:"Для рекламных буклетов собери {0} флаерса в Клубном квартале."};
tr[36743] = {H:"Спасибо за помощь! Скоро мы придумаем замечательные экскурсии."};
tr[36744] = {H:"Гости из прошлого"};
tr[36745] = {H:"Туристы из Ледникового периода никогда не купались в море. Помоги устроить им экскурсию по побережью."};
tr[36746] = {H:"Приходи на Пляж."};
tr[36747] = {H:"Изучи морские виды. Посмотри в подзорную трубу."};
tr[36748] = {H:"Изучи морские маршруты. Покатайся на Катере в Порту и заработай {0} Смешинок."};
tr[36749] = {H:"Туристам понравится. Лови Смешинки!"};
tr[36750] = {H:"Гости из прошлого"};
tr[36751] = {H:"Туристы из Древней Греции хотят прикоснуться к будущему. Придумай для них экскурсию по Стране Роботов."};
tr[36752] = {H:"Приезжай в Страну роботов."};
tr[36753] = {H:"Сыграй в игру Собери робота и заработай {0} Смешинок."};
tr[36754] = {H:"Туристы любят кататься с ветерком. И ты покатайся - сыграй в Шахты."};
tr[36755] = {H:"Отличная выйдет экскурсия. Держи награду!"};
tr[36756] = {H:"Гости из прошлого"};
tr[36757] = {H:"Туристы с Древнего Востока интересуются товарами из Шарарама. Придумай для них экскурсию с покупками."};
tr[36758] = {H:"Приходи на главную площадь."};
tr[36759] = {H:"Приготовь для туристов лучшие наряды. Сыграй в модельера в Доме мод."};
tr[36760] = {H:"Подговь магические сувениры. Выиграй в поединок магов в Волшебном саду."};
tr[36761] = {H:"Спасибо за идей для экскурсий. Держи награду!"};
tr[36762] = {H:"Подготовка к экскурсиям"};
tr[36763] = {H:"Экскурсия по побережью"};
tr[36764] = {H:"Экскурсия к роботам"};
tr[36765] = {H:"Шоппинг-тур"};
tr[36766] = {OId:270,H:"Всё рухнуло! Нужны мастера-строители, чтобы починить. Кликни на кран и приступай."};
tr[36767] = {OId:270,H:"Горим! Срочно нужны герои-пожарные. Хватай огнетушитель и потуши лес!"};
tr[36768] = {H:"Белка Бэлла"};
tr[36770] = {H:"Наклейка " + "\"" + "Красавица" + "\"" + ""};
tr[36771] = {H:"Светильник " + "\"" + "Шар мудрости" + "\"" + ""};
tr[36772] = {H:"Бейсболка с хвостиками"};
tr[36773] = {H:"Шарафон " + "\"" + "Робот" + "\"" + ""};
tr[36774] = {H:"Урок Великих изобретений"};
tr[36775] = {H:"Фон " + "\"" + "Тысяча идей" + "\"" + ""};
tr[36776] = {H:"Футболка " + "\"" + "Жрец" + "\"" + ""};
tr[36777] = {H:"Пальма в домик"};
tr[36778] = {OId:270,H:"Найди Ёжика! Отправляйся в лесную чащу."};
tr[36779] = {OId:270,H:"3 тропы! Какую выбрать? Проверь, нет ли на них следов Ёжика."};
tr[36780] = {OId:270,H:"Надо выбрать из двух тропинок. Всё просто!"};
tr[36781] = {OId:270,H:"Ёжик пошёл по тропе, где нет сломанных деревьев. Иди налево!"};
tr[36782] = {OId:270,H:"Ёжик пошёл по тропе, откуда не доносится шум. Иди налево!"};
tr[36783] = {OId:270,H:"Пошли искать мусорных злодеев в лесную чащу!"};
tr[36784] = {OId:270,H:"Найди тех, кто разбросал по лесу мусор!"};
tr[36785] = {OId:270,H:"Пошли искать мусорных злодеев в лесную чащу!"};
tr[36786] = {OId:270,H:"Поговори с Шефом на Главной площади!"};
tr[36787] = {OId:270,H:"Поговори с Шефом на Главной площади!"};
tr[36788] = {OId:270,H:"Заправь вертолёт безопасным топливом, чтобы не вредить лесу."};
tr[36789] = {OId:624,H:"Ёжик, даже не пытайся спрятаться в этих мешках! Мы тебя нашли."};
tr[36790] = {OId:623,H:"Но это же... мешки для мусора. Зачем мне в них лезть. Я порядок навожу."};
tr[36791] = {H:"Ёжик, а как же игра в прятки?"};
tr[36792] = {OId:623,H:"Да какие тут игры! Посмотрите – полный лес мусора. Надо скорее убраться, а то природу жалко."};
tr[36793] = {H:"Интересно, откуда столько хлама?"};
tr[36794] = {OId:624,H:"Я знаю: это мусорный монстр! Он расхаживает по чаще и всюду разбрасывает хлам."};
tr[36795] = {OId:623,H:"Не бывает таких монстров! Мусор принёс кто-то другой... Кто-то круглый... Как Смешарик."};
tr[36796] = {H:"Интрига! Крош, мы должны провести расследование!"};
tr[36797] = {OId:624,H:"Хорошая идея! Будем искать монстра. Или... Смешарика! Уууу, страшно!"};
tr[36798] = {OId:623,H:"Монстров не существует. А вот расследование - это здорово! Я вам даже карту леса дам."};
tr[36799] = {H:"Спасибо, Ёжик! С чего же начать?"};
tr[36800] = {OId:625,H:"Подходи, не стесняйся, садись к огоньку – гостем будешь."};
tr[36801] = {H:"Ух, сколько мусора от вашего пикника!"};
tr[36802] = {OId:626,H:"Значит, скоро придёт мусорный монстр и всё это съест."};
tr[36803] = {OId:625,H:"Да нам и не жалко – новых блюд приготовим. Только дровишек подкинем."};
tr[36804] = {H:"Ну уж нет. Пора убрать мусор, а костёр затушить – пожар нам не нужен."};
tr[36805] = {OId:627,H:"Мы решили устроить тут огород. Но ветер сдул бутылки с удобрениями в озеро."};
tr[36806] = {OId:625,H:"Поможешь их выловить?"};
tr[36807] = {H:"Но удобрения могут отравить воду!"};
tr[36808] = {OId:631,H:"Мммм, удобрения! Мусорный монстр их обожает."};
tr[36809] = {OId:625,H:"Шо за монстр? Зови его скорее! Будет на грядках работать. А удобрения..."};
tr[36810] = {H:"Удобрения и мусор надо убрать! А огород и у Копатыча есть."};
tr[36811] = {OId:270,H:"Врум-врум-врум, попробуй догони! Или слабо?"};
tr[36812] = {H:"Гадкие злобыри! Из-за ваших выхлопов бабочки летают в противогазах!"};
tr[36813] = {OId:628,H:"Мусорный монстр любит выхлопы! Берегитесь, Злобыри, он уже к вам бежит."};
tr[36814] = {OId:270,H:"Гххх, какой монстр? Мы тут монстры!"};
tr[36815] = {H:"Монстры - не монстры, а прогонять вас придётся."};
tr[36816] = {OId:629,H:"Говори громче, ничего не слышно. А лучше – танцуй!"};
tr[36817] = {OId:625,H:"И пой!"};
tr[36818] = {H:"Нет настроения. У вас тут слишком грязно и шумно."};
tr[36819] = {OId:626,H:"А сильный шум – тоже мусор. Монстру очень нравится!"};
tr[36820] = {OId:625,H:"Монстр? Больше гостей – круче вечеринка!"};
tr[36821] = {H:"Но от шума у вас меньше гостей... Все птички и зверьки разбежались."};
tr[36822] = {OId:625,H:"Люблю птичек и зверьков! Раз мы напугали их шумом, надо всё исправить!"};
tr[36823] = {H:"Верно. Долой шумовое загрязнение!"};
tr[36824] = {OId:270,H:"Какая чистая поляна! Но медведя не проведёшь."};
tr[36825] = {H:"Копатыч, в чём дело? Тут есть мусор?"};
tr[36826] = {OId:270,H:"Ещё как! Бросишь в лесу что-нибудь, а оно может тут и 100, и даже 1000 лет пролежать."};
tr[36827] = {H:"Но я же ничего не вижу!"};
tr[36828] = {OId:270,H:"А вот приглядись. Старый мусор может скрываться где угодно."};
tr[36829] = {H:"Сейчас посмотрим!"};
tr[36830] = {OId:627,H:"Ёлки-иголки! Мусорный монстр. Но... Но... Я ЖЕ ЕГО ВЫДУМАЛ!"};
tr[36831] = {OId:630,H:"Крош, тебе показалось. Это просто гора мусора. Но вреда от неё – похлеще, чем от монстра."};
tr[36832] = {H:"Какое неприятное зрелище. Надо её отсюда убрать."};
tr[36833] = {OId:630,H:"Боюсь, пока мы будем тащить мусор по лесу, всё кругом будет отравлено."};
tr[36834] = {H:"Тогда давай сожжём мусор прямо тут."};
tr[36835] = {H:"Давай закопаем мусор на этой полянке."};
tr[36836] = {H:"Давай попросим помощи у агентов. Они продвинутые!"};
tr[36837] = {OId:630,H:"Ядовитого дыма станет ещё больше. Нужно придумать что-то другое."};
tr[36838] = {H:"Давай попросим помощи у агентов."};
tr[36839] = {OId:630,H:"Яд от мусора попадёт в подземную воду. И всё в Шарараме будет отравлено."};
tr[36840] = {H:"Давай попросим помощи у агентов."};
tr[36841] = {OId:627,H:"Агенты крутые! У них есть бункеры, лазеры, электроловушки и даже вертолёты."};
tr[36842] = {OId:630,H:"Вертолёты! То, что нужно. Увезём мусор по воздуху."};
tr[36843] = {H:"Чур, я пилот! Бегу к Шефу за вертолётом на Главную площадь."};
tr[36844] = {OId:270,H:"Операция по спасению леса прошла удачно. Но мусор – штука коварная. Надо его утилизировать."};
tr[36845] = {H:"Ой. А что это значит?"};
tr[36846] = {OId:270,H:"Рассортируем мусор. Полезные вещи отправим в переработку. А опасные – аккуратно уничтожим."};
tr[36847] = {H:"Всё понятно. Приступаем к сортировке!"};
tr[36848] = {H:"А расскажи подробнее про опасный и безопасный мусор."};
tr[36849] = {OId:270,H:"Безопасный мусор это, например, пластиковые бутылки. Пустим их в переработку и сможем сделать из них новые вещи. Удобно!"};
tr[36850] = {H:"Круто! Не знал, что из мусора можно сделать что-то полезное."};
tr[36851] = {OId:270,H:"А опасный мусор это, например, батарейки. Из него ничего не сделаешь, поэтому мы их аккуратно уничтожим, чтобы ничему не навредить."};
tr[36852] = {H:"Всё понятно. Приступаем к сортировке!"};
tr[36853] = {OId:627,H:"Ёжик, а в лесу и вправду стало лучше."};
tr[36854] = {OId:623,H:"Да... Но как защитить его в будущем? Вдруг мусор вернётся."};
tr[36855] = {H:"Попросим не разводить костры, не мусорить и не шуметь..."};
tr[36856] = {OId:627,H:"Крутая идея! Пусть природа останется дикой, и никто её не тревожит."};
tr[36857] = {OId:623,H:"Это же будет... настоящий заповедник!"};
tr[36858] = {H:"Ого! Получается мы основали целый заповедник в Шарараме?"};
tr[36859] = {OId:623,H:"Да! И теперь ты знаешь, как в нём себя вести. Время для награды."};
tr[36860] = {H:"Ура!"};
