tr[36908] = {H:"Гости из прошлого"};
tr[36909] = {H:"Привет! Раньше я возил туристов из настоящего в прошлое. А теперь наоборот - хочу привезти в Шарарам гостей из былых времён."};
tr[36910] = {H:"Чем кормить туристов в Шарараме? Поработай в Кафе на Пляже и получи {0} Смешинок."};
tr[36911] = {H:"Для рекламных буклетов собери {0} флаерса в Клубном квартале."};
tr[36912] = {H:"Спасибо за помощь! Скоро мы придумаем замечательные экскурсии."};
tr[36913] = {H:"Гости из прошлого"};
tr[36914] = {H:"Туристы из Ледникового периода никогда не купались в море. Помоги устроить им экскурсию по побережью."};
tr[36915] = {H:"Приходи на Пляж."};
tr[36916] = {H:"Изучи морские виды. Посмотри в подзорную трубу."};
tr[36917] = {H:"Изучи морские маршруты. Покатайся на Катере в Порту и заработай {0} Смешинок."};
tr[36918] = {H:"Туристам понравится. Лови Смешинки!"};
tr[36919] = {H:"Гости из прошлого"};
tr[36920] = {H:"Туристы из Древней Греции хотят прикоснуться к будущему. Придумай для них экскурсию по Стране Роботов."};
tr[36921] = {H:"Приезжай в Страну роботов."};
tr[36922] = {H:"Сыграй в игру Собери робота и заработай {0} Смешинок."};
tr[36923] = {H:"Туристы любят кататься с ветерком. И ты покатайся - сыграй в Шахты."};
tr[36924] = {H:"Отличная выйдет экскурсия. Держи награду!"};
tr[36925] = {H:"Гости из прошлого"};
tr[36926] = {H:"Туристы с Древнего Востока интересуются товарами из Шарарама. Придумай для них экскурсию с покупками."};
tr[36927] = {H:"Приходи на Главную площадь."};
tr[36928] = {H:"Приготовь для туристов лучшие наряды. Сыграй в модельера в Доме мод."};
tr[36929] = {H:"Подговь магические сувениры. Выиграй в поединок магов в Волшебном саду."};
tr[36930] = {H:"Спасибо за идей для экскурсий. Держи награду!"};
tr[36931] = {H:"Зяброку негде упасть!"};
tr[36932] = {H:"На Зябре каждый день весна. И осень тоже - каждый день. Значит, пришла пора сажать и собирать зябрийские яблоки - зяброки!"};
tr[36933] = {H:"Но растить мы их будем в Шарараме. Приходи на Пляж."};
tr[36934] = {H:"Зяброкам нужна хорошая погода. Нет ли облаков? Посмотри в Подзорную трубу."};
tr[36935] = {H:"Измерь силу ветра. Победи в сноуборд на Снежной горе."};
tr[36936] = {H:"Итак, я составил прогноз - погода будет отличной. Зяброки можно смело сажать."};
tr[36937] = {H:"Зяброку негде упасть!"};
tr[36938] = {H:"Нигде не могу найти семена зяброк. Не беда! Что-нибудь на ходу придумаем."};
tr[36939] = {H:"Поспеши в Ромашковую долину."};
tr[36940] = {H:"Собери {0} груш."};
tr[36941] = {H:"Сыграй в Метеориты на Космодроме и заработай {0} Смешинок за 1 раз."};
tr[36942] = {H:"Ну вот - космическая энергия метеоритов превратила семена груш в зяброчные. Мы отлично поработали!"};
tr[36943] = {H:"Зяброку негде упасть!"};
tr[36944] = {H:"Зяброки растут не в земле, а в камнях. Надо найти скалы в Шарараме. И вскопать!"};
tr[36945] = {H:"Скала может скрываться под песком. Сыграй в Секретики на Пляже."};
tr[36946] = {H:"Построим экскаватор. Собери {0} коробок инструментов в Автосалоне."};
tr[36947] = {H:"Сыграй в вечный двигатель в Ромашковой долине и заработай {0} Смешинок."};
tr[36948] = {H:"Спасибо! Благодаря вечному двигателю наш экскаватор вскопал каменные грядки."};
tr[36949] = {H:"Зяброку негде упасть!"};
tr[36950] = {H:"Зяброкам нужен особый уход - забудь всё, что знал о земных растениях. Зяброки - совсем другие."};
tr[36951] = {H:"Полей зяброки горячим шоколадом. Найди и купи его в меню клубов."};
tr[36952] = {H:"Нужен свет космоса. Купи гирлянду " + "\"" + "Созвездие" + "\"" + " в магазине, разделе Мебель - Свет"};
