tr[37030] = {H:"Поработай Няней и получи {0} Смешинок за 1 раз."};
tr[37031] = {H:"Спасибо! Теперь я готова идти на свидание с муравьём."};
tr[37032] = {H:"По следам агента-муравья"};
tr[37033] = {H:"О, нет! На наше свидание ворвались Злобыри. Я напугал злодеев, и они разбежались. Но теперь разгуливают в Каньоне - останови их."};
tr[37034] = {H:"Подготовь питомца к бою. Покорми его."};
