tr[37071] = {OId:270,H:"Беги к Лосяшу в Ромашковую долину и узнай, какие растения под угрозой."};
tr[37072] = {OId:270,H:"Друг мой, ты вовремя. Я как раз отыскал нужную книгу... Красную!"};
tr[37073] = {H:"О! Красный - цвет опасности."};
tr[37074] = {OId:270,H:"Поразительные знания! В этой книге много опасного! А ещё там список редких растений."};
tr[37075] = {H:"Понятно! В твоей книге опасные растения-монстры. Ух!"};
tr[37076] = {OId:270,H:"Друг мой, не торопись. Никаких монстров. Растения в книге самые прекрасные! Но они в любой момент могут исчезнуть..."};
tr[37077] = {H:"Так вот в чём опасность! Растения пропадают. Жалко..."};
tr[37078] = {OId:270,H:"Верно! Если редкие растения похитят из Заповедника, то новые уже не вырастут."};
tr[37079] = {H:"Но почему?"};
tr[37080] = {H:"Где описаны растения и животные под угрозой исчезновения?"};
tr[37081] = {H:"Зачем нужна Красная книга растений и животных?"};
tr[37082] = {H:"Что происходит с растениями, когда вырубают лес?"};
tr[37083] = {H:"Раньше в парке росли ландыши, а теперь нет. Отметь, почему это могло случиться."};
tr[37084] = {H:"Весна наступила, но в лесу нет подснежников. Отметь, почему это могло случиться."};
tr[37085] = {H:"Почему некоторые заводы вредят диким растениям?"};
tr[37086] = {H:"Этот цветок из Красной книги является символом чистоты в Азии."};
tr[37087] = {H:"Что такое венерин башмачок?"};
tr[37088] = {H:"Почему нельзя срывать растения, взятые под охрану Красной книгой?"};
tr[37089] = {H:"Где в России растёт занесённый в Красную книгу японский клён?"};
