tr[37257] = {H:"Электро-пианино"};
tr[37258] = {H:"Бейсболка " + "\"" + "Оки" + "\"" + ""};
tr[37259] = {H:"Свитшот " + "\"" + "Оки" + "\"" + ""};
tr[37260] = {H:"Скейт " + "\"" + "Эко" + "\"" + ""};
tr[37261] = {H:"Корзина " + "\"" + "Уличные игры" + "\"" + ""};
tr[37262] = {OId:270,H:"Это мой город, мой район. А колесо твоё. Крути и получай подарки."};
tr[37263] = {OId:0,H:"Ищи на складе в домике."};
tr[37264] = {OId:0,H:"Магия " + "\"" + "Граффити" + "\"" + " навсегда"};
