tr[37287] = {OId:270,H:"Что-то мне страшно! В Заповеднике появились следы зверя, которого раньше не было..."};
tr[37288] = {H:"Ёжик, а что это за зверь?"};
tr[37289] = {OId:270,H:"Не знаю... Он выполз из воды, поломал кусты, не стал есть ягоды и разодрал когтями пень. А ты как думаешь, кто он?"};
tr[37290] = {H:"Кто-то хищный. И водяной. Крокодил?"};
tr[37291] = {H:"Кто-то тяжёлый, и ягоды не любит... Это гигантская белка-носорог!"};
tr[37292] = {OId:270,H:"Ха-ха! Белки-носороги если и встречаются, то только в сказках."};
tr[37293] = {H:"Значит, у нас не белка, а крокодил – живёт в воде, ягоды не любит, когти точит."};
tr[37294] = {OId:270,H:"Кро-ко-д-д-дил... Этого я и боялся! Каждому зверю в природе отведено свое место. Своя среда - естественная."};
tr[37295] = {H:"Вот-вот! Крокодилу место где-нибудь в джунглях, а не в нашем лесу."};
tr[37296] = {H:"Да! Обычно крокодилы встречаются на севере, среди льдов Арктики. А не у нас."};
tr[37297] = {OId:270,H:"Ну и фантазия у тебя! Не надо Арктики, отправим крокодила в Джунгли. Туда, где ему будет лучше."};
tr[37298] = {H:"Только как мы отправим его в Джунгли?"};
tr[37299] = {OId:270,H:"Правильно! У нас в Заповеднике крокодилу будет худо. Вот и отправим его в Джунгли."};
tr[37300] = {H:"Но как мы это сделаем?"};
tr[37301] = {H:"Гость в домик - Лосяш!"};
tr[37302] = {H:"Пригласи самого умного Смешарика в гости! Ищи на складе в домике."};
tr[37303] = {OId:270,H:"Выманим крокодила и отвезём в Джунгли! Начинаем?"};
tr[37304] = {H:"Вперёд!"};
tr[37305] = {H:"Стол " + "\"" + "Фрутто Перфекто" + "\"" + ""};
tr[37306] = {H:"Костюм с гитарой"};
