tr[37323] = {H:"10000"};
tr[37324] = {H:"Сенсация! Посетительница Диско сменила на танцполе 568 стилетов. Хо-хо, я совсем отстала от моды - что такое стилеты?"};
tr[37325] = {H:"Брюки"};
tr[37326] = {H:"Перчатки"};
tr[37327] = {H:"Туфли"};
tr[37328] = {H:"Сенсация! Я прилетел сюда наблюдать за пролётом астероида 1998 OR2. Подскажи, на каком расстоянии от Земли он пройдёт?"};
tr[37329] = {H:"380 000 километров"};
tr[37330] = {H:"6,29 миллиона километра"};
tr[37331] = {H:"1 миллион морских миль"};
tr[37332] = {H:"Сенсация! На Мюре целых три луны! Подскажи, как назвать их правильнее?"};
