tr[37337] = {H:"Костюм телеведущего"};
tr[37338] = {H:"Ушастый шериф"};
tr[37339] = {H:"Ёлки-иголки, Ёжик в такое вляпался! Встретил чудика и со страху куда-то спрятался. Поможешь отыскать моего колючего друга?"};
tr[37340] = {H:"Найди в Шарараме чудика и прогони."};
tr[37341] = {H:"Позитивная энергия победит страх! Собери {0} штуки в Шарараме."};
tr[37342] = {H:"Ёжик успокоится, если поест ягод! Собери Дары леса и заработай {0} Смешинок."};
tr[37343] = {H:"Ура, Ёжик спасён. А мы с тобой - крутая команда! Давай сделаем что-нибудь ещё крутое?"};
tr[37344] = {H:"Ушастый шериф"};
tr[37345] = {H:"Придумал: мы с тобой станем шерифами Шарарама! Будем следить за порядком и спасать всех, кому нужна помощь."};
tr[37346] = {H:"Приходи в Порт."};
tr[37347] = {H:"Проверь обстановку в море. Посмотри в перископ."};
tr[37348] = {H:"Прокатись на катере и заработай {0} Смешинок за 1 раз."};
tr[37349] = {H:"В море всё спокойно. Но мы же шерифы! Не будем терять бдительность."};
tr[37350] = {H:"Ушастый шериф"};
tr[37351] = {H:"Срочно: нянечки в Детском саду не справляются с крошками. А я... Я боюсь нянечек. И крошек боюсь! Только ты сможешь навести там порядок."};
tr[37352] = {H:"Приходи в Детский сад."};
tr[37353] = {H:"Поухаживай за Крошками и заработай {0} Смешинок."};
tr[37354] = {H:"Успокой нянь: накорми их в Кафе на Пляже и заработай {0} Смешинок."};
tr[37355] = {H:"Порядок в детском саду восстановлен. Ты отлично справляешься с делами шерифа."};
tr[37356] = {H:"Ушастый шериф"};
tr[37357] = {H:"В Парке аттракционов шум и гам. Отправляйся туда и во всём разберись."};
tr[37358] = {H:"Приходи в Парк аттракционов."};
tr[37359] = {H:"Это болельщики шумят и требует завершить матч. Сыграй в футбол!"};
tr[37360] = {H:"Отправь болельщиков праздновать в клубы. Собери {0} флаерса в Клубном квартале."};
tr[37361] = {H:"Ловко! Держи награду за работу в Парке."};
tr[37362] = {H:"Ушастый шериф"};
tr[37363] = {H:"Призрак на горе украл у Нюши шарафон. Скорее в погоню!"};
tr[37364] = {H:"Приходи на Снежую гору."};
tr[37365] = {H:"Выиграй в Сноуборд."};
tr[37366] = {H:"Приготовь снежную ловушку - кинь {0} помидоров."};
tr[37367] = {H:"Мы снова справились! Вот твоя награда - звезда шерифа."};
tr[37368] = {H:"Спасти Ёжика!"};
tr[37369] = {H:"Охраняем море!"};
tr[37370] = {H:"Канитель в Детском саду!"};
tr[37371] = {H:"Болельщики под контролем"};
tr[37372] = {H:"Ледяная погоня"};
tr[37373] = {H:"Рыба|Рыбу приготовят через {0} мин."};
tr[37374] = {OId:635,H:"Нарушители! Вы зачем по Заповеднику ходите?"};
tr[37375] = {OId:270,H:"Какие ж мы нарушители? Мы лесники! Лучше объясните, что это за чудо крокодиловое."};
tr[37376] = {H:"Это же робот. Крокодил-робот!"};
tr[37377] = {OId:635,H:"Это наша новинка. Робот ходит по Заповеднику, следит за порядком и снимает всё на камеру."};
tr[37378] = {OId:634,H:"А крокодила мы сделали, чтобы звери не пугались и приняли его за своего."};
tr[37379] = {H:"Но в Заповеднике нет крокодилов. Лучше бы сделали робота-бобра."};
tr[37380] = {OId:635,H:"Но крокодил – это круто! А бобры не очень... Мы, агенты, любим крутые штуки."};
tr[37381] = {OId:270,H:"Чем вам бобры не угодили? Они здесь естественные обитатели! А крокодил – нет."};
tr[37382] = {H:"Хватит спорить. Давайте посмотрим, что наснимал этот крокодил."};
tr[37383] = {OId:634,H:"Да-да! Робот подал сигнал, что его память заполнена. Кликни на него и узнаешь, что разведал крокодил."};
tr[37384] = {H:"Сейчас посмотрим!"};
tr[37385] = {OId:270,H:"Кликни на крокодила и узнаешь, что он разведал."};
tr[37386] = {OId:270,H:"Спаси зверей! Отправляйся в Тёмное царство с Площади у Больнички!"};
tr[37387] = {OId:270,H:"Спаси зверей! Кликни на замок, чтобы отправиться в Тёмное царство!"};
tr[37388] = {OId:270,H:"А вот и цирк Злобикуса! Кликни на проход справа - звери, наверное, там!"};
tr[37389] = {OId:270,H:"Это наши звери! В цирке им не место – поговори со Злобырём, чтобы освободить зверей."};
tr[37390] = {OId:270,H:"Что ты тут забы... А! Поклонник! Вижу. Проходи, смотри, какое я зверьё изловил. Эх, жаль, что такое дикое."};
tr[37391] = {H:"Я не поклонник. Я секретный агент. Сдавайся!"};
tr[37392] = {H:"Я поклонник! Расскажи подробнее про этот цирк."};
tr[37393] = {OId:270,H:"Смешная шутка. Только вот я смеяться не люблю."};
tr[37394] = {H:"Ладно, ладно. Попробую быть серьёзнее."};
tr[37395] = {OId:270,H:"Да вот, балуем Злобырей трюками с дикими зверями. Только звери непослушные. Приходится их магией... того!"};
tr[37396] = {H:"Дрессировать?"};
tr[37397] = {OId:270,H:"Ага! По-другому они не понимают! Ух, дикари. Ну ничего, чёрная магия всех исправит."};
tr[37398] = {H:"А я вот подход к зверям знаю. Хочешь покажу? Ты только клетки открой!"};
tr[37399] = {OId:270,H:"Что?! Считаешь, я плохой дрессировщик?! Варгх. Я тебе сейчас такое шоу устрою!"};
tr[37400] = {H:"Лучше не надо..."};
tr[37401] = {H:"Зубр слишком крупный для телепортации."};
tr[37402] = {H:"Рысь не сможет поймать шарик. У неё лапки."};
tr[37403] = {H:"Дрон не сможет поднять в воздух зубра."};
tr[37404] = {H:"Норка слишком маленькая для этого колпака."};
tr[37405] = {H:"Рысь боится быть маленькой. Нельзя её уменьшать."};
tr[37406] = {H:"Если норка станет маленькой, то уронит шарики на себя."};
tr[37407] = {OId:270,H:"Спасибо! Звери вернулись в Заповедник невредимыми. Но я всё равно о них волнуюсь."};
tr[37408] = {OId:634,H:"Не бойся, Ёжик! Я основательно доработал наше изобретение."};
tr[37409] = {H:"Ты про крокодила?"};
tr[37410] = {OId:634,H:"Крокодилом это теперь не назвать. Я сделал настоящую ФОТОЛОВУШКУ!"};
tr[37411] = {H:"Звучит опасно! Ёжику не понравятся ловушки для зверей..."};
tr[37412] = {OId:635,H:"Не бойтесь. Фотоловушка – незаметная камера. У нас и звери будут под присмотром, и нарушители не пройдут."};
tr[37413] = {OId:634,H:"А ещё мы надёжно замаскируем этот фотик!"};
tr[37414] = {H:"Круто! Ваша штука и зверей не напугает, и про нарушителей сообщит."};
tr[37415] = {OId:634,H:"Проверишь фотоловушку? Вон она – видишь кустик с камерой? Кликни на него!"};
tr[37416] = {H:"Сейчас посмотрим."};
tr[37417] = {OId:634,H:"Проверь фотоловушку – кликни на кустик с камерой!"};
