tr[37436] = {H:"Ботинки " + "\"" + "Изящные" + "\"" + ""};
tr[37437] = {H:"Чудо-ферма"};
tr[37438] = {H:"Загрустил я на грядках... Хочется чего-то эдакого! А давай... Давай построим необычную ферму и посадим на ней что-нибудь фантастическое?"};
tr[37439] = {H:"Напиши в общий чат: Какие фрукты вы любите?"};
tr[37440] = {H:"Чтобы обустроить ферму, накопи {0} Смешинок."};
tr[37441] = {H:"Подыщи место для фермы. Сходи в гости к {0} Смешарикам."};
tr[37442] = {H:"Спасибо! За стройку я возьмусь сам, а для тебя у меня будет новое заданьице."};
tr[37443] = {H:"Чудо-ферма"};
tr[37444] = {H:"Думаешь, посадить фрукты так просто? Нужен добротный грунт. Земля с удобрениями, то бишь."};
tr[37445] = {H:"Песок хорошо держит влагу: собери его - выиграй в Секретики на Пляже."};
tr[37446] = {H:"Шелуха от шишек удобрит грунт. Собери {0} штук на Снежной горе."};
tr[37447] = {H:"Нужны краски. Выиграй в Волшебный карандаш в Школе магов."};
tr[37448] = {H:"Ну шо, с таким грунтом только фантастические фрукты и выращивать! Спасибо."};
tr[37449] = {H:"Чудо-ферма"};
tr[37450] = {H:"Ну шо, пришло время сажать фрукты. Для интересу добавим к семенам немного волшебства."};
tr[37451] = {H:"Фермеру нужна удобная обувь. Купи кеды " + "\"" + "Лондон" + "\"" + " в Смешмаге."};
tr[37452] = {H:"Овладей волшебством. Выиграй в поединок магов в Волшебном саду."};
tr[37453] = {H:""};
tr[37454] = {H:"Чую, фрукты вырастут знатные. Спасибо за подмогу!"};
tr[37455] = {H:"Чудо-ферма"};
tr[37456] = {H:"Айда собирать урожай - фрукты поспели! Ты только поаккуратнее с ними - фрукты-то необычные, нежные."};
tr[37457] = {H:"Научись аккуратно рвать плоды. Собери Дары леса и заработай {0} Смешинок."};
