tr[37464] = {H:"Собираем урожай!"};
tr[37465] = {OId:270,H:"Привет! Надевай маску гепарда и приготовься исполнить танец зулусов!"};
tr[37466] = {H:"Что-что?"};
tr[37467] = {OId:270,H:"Не знаешь? Значит, время рассказать про повадки диких племён."};
