tr[37620] = {OId:270,H:"Помоги Доку с Максом в Каньоне вернуть электричество в Шарарам!"};
tr[37621] = {OId:270,H:"Найди находчивого Смешарика, который знает, где взять электричества."};
tr[37622] = {OId:270,H:"Я хочу добывать энергию из картохи. Но пока не получается. Поищи идеи у кого-то другого."};
tr[37623] = {OId:270,H:"Я хочу создавать электричество своим голосом. Но пока не выходит. Поищи идеи у кого-то другого."};
tr[37624] = {OId:270,H:"Поговори с Пином в Порту."};
tr[37625] = {OId:270,H:"Кликни на трубу с вентиль, чтобы начать строительство."};
tr[37626] = {OId:270,H:"Расскажи об успехе Лосяш в Ромашковой долина!"};
tr[37627] = {OId:461,H:"Привет! Я построил плотину. Гордитесь мной."};
tr[37628] = {OId:117,H:"Феноменально! Что ж, теперь всё сходится."};
tr[37629] = {H:"Лосяш, объясни-ка."};
tr[37630] = {OId:602,H:"Плотина Макса перегородила горную реку. Вода стала прибывать и затопила Шарарам."};
tr[37631] = {H:"Макс, зачем ты так с нами?"};
tr[37632] = {OId:461,H:"Но... Смешарики сами попросили. Сказали, что хотят больше электричества. Вот я и сделал плотину по совету дедушки."};
tr[37633] = {H:"Лосяш, плотины правда добывают электричество?"};
tr[37634] = {OId:117,H:"Правда. Ведь плотины - это целые электростанции! Как думаешь, что нам делать?"};
tr[37635] = {H:"Остановим наводнение. А потом решим, где взять электричество!"};
tr[37636] = {H:"Плотину надо оставить. Электричество нам нужнее."};
tr[37637] = {OId:461,H:"Так и быть... Разберу плотину."};
tr[37638] = {OId:117,H:"А мы с вами, коллега, построим водопровод и откачаем лишнюю воду."};
tr[37639] = {H:"Приступаем!"};
tr[37640] = {OId:461,H:"Мой дедушка знает про электричество всё! Давайте спросим совета у него?"};
tr[37641] = {OId:117,H:"Хорошая мысль. Но сначала надо разобрать плотину и спасти Шарарам от наводнения."};
tr[37642] = {H:"Приступаем!"};
tr[37643] = {OId:637,H:"Плотину разобрали. Это хорошо – наводнение миновало. И это плохо - электричества теперь не хватает."};
tr[37644] = {H:"Раньше же хватало! Куда оно девается?"};
tr[37645] = {OId:637,H:"Всё дело в гаджетах! У Нюши вот новый телефон, у Совуньи мультиварка, а Лосяш купил огромное..."};
tr[37646] = {H:"Понятно! Все эти предметы расходуют энергию."};
tr[37647] = {OId:637,H:"Ага. И если мы не хотим возвращаться в каменный век, нам нужно добыть электричество!"};
tr[37648] = {H:"Док, ты же учёный! Сможешь найти решение?"};
tr[37649] = {OId:637,H:"Конечно! Я с лёгкостью всё рассчитаю на своём суперкомпьютере... Ааа... Подожди-ка...."};
tr[37650] = {H:"Компьютеру тоже нужно электричество..?"};
tr[37651] = {OId:637,H:"Ага.... Без компьютера придётся думать головой. Но я... Я... Я к этому совсем не привык!"};
tr[37652] = {H:"Тогда я поищу Смешарика, который знает, где взять электричество."};
tr[37653] = {OId:270,H:"Газ - очень полезный штука. Энергию даёт, а природе не вредит. У меня даже готова электростанция для газа!"};
tr[37654] = {H:"Ух ты! Так почему ты её не включил?"};
tr[37655] = {OId:270,H:"Станция есть, а газа нет! Добыть и доставить его в Шарарам не так-то просто."};
tr[37656] = {H:"А где добывают газ?"};
tr[37657] = {OId:270,H:"Конечно, в России! В Сибири, к северу от легендарный город Омск. Это место называйся - Ямал."};
tr[37658] = {H:"Я знаю, там бывали Крош с Ёжиком!"};
tr[37659] = {OId:270,H:"Вот именно! Добирайся туда тяжёло, а руками газа много не унести. Нужен газопровод."};
tr[37660] = {H:"С водопроводом я уже возился. Так что и с газопроводом справлюсь!"};
tr[37661] = {OId:270,H:" Фантастиш! Я рад, что ты помогайт. Кликни на трубу с вентиль, чтобы начать строительство газопровод."};
tr[37662] = {H:"От винта!"};
tr[37663] = {OId:233,H:"Коллега, электричества теперь так много, что хватило даже на эти мигающие шляпы!"};
tr[37664] = {OId:117,H:"Где тебе удалось найти столько энергии?"};
tr[37665] = {H:"Мы построили трубы и добыли электричество из газа!"};
tr[37666] = {OId:233,H:"Феноменально! К тому же я не наблюдаю катастроф - значит, газовая станция безопасна."};
tr[37667] = {OId:117,H:"Никаких больше наводнений."};
tr[37668] = {H:"А ещё газа надолго хватит."};
tr[37669] = {OId:233,H:"Великолепно! Мы с Доком, умнейшие из Смешариков, подтверждаем..."};
tr[37670] = {OId:117,H:"...тебе удалось найти лучший источник энергии для Шарарама!"};
tr[37671] = {H:"Ура!"};
tr[37672] = {H:"Если выйдешь, газопровод придётся строить заново. Хочешь выйти?"};
tr[37673] = {H:"Монстрик побеждён! Приходи в Шарарам и стань героем!"};
tr[37674] = {H:"Шоу в клуб на месяц. Ищи среди своих артистов."};
tr[37675] = {OId:0,H:"Урок Летняя магия"};
tr[37676] = {H:"Летняя магия|Пройди урок в Школе магов и получи эту магию!|Ты можешь превращаться ещё дней: {0}|Ты можешь превращаться всегда!"};
tr[37677] = {H:"Столбик с огнём"};
tr[37678] = {H:"Панама " + "\"" + "Звёздочки" + "\"" + ""};
tr[37679] = {H:"Ветровка " + "\"" + "Сила" + "\"" + ""};
tr[37680] = {H:"Фон " + "\"" + "Энергия" + "\"" + ""};
tr[37681] = {H:"Бейсболка " + "\"" + "Электро" + "\"" + ""};
tr[37682] = {H:"Футболка " + "\"" + "Электро" + "\"" + ""};
tr[37683] = {H:"Я добыл электричество для Смешариков! Приходи в Шарарам и играй с любимыми героями!"};
tr[37684] = {H:"Каска " + "\"" + "Мечты сбываются" + "\"" + ""};
tr[37685] = {H:"Фон " + "\"" + "Приятное путешествие" + "\"" + ""};
tr[37686] = {H:"Фон " + "\"" + "Король дорог" + "\"" + ""};
tr[37687] = {H:"Фон " + "\"" + "Серьёзный Смешарик" + "\"" + ""};
tr[37688] = {H:"Фон " + "\"" + "Тихий огонёк" + "\"" + ""};
tr[37689] = {H:"Фон " + "\"" + "Как в сказке" + "\"" + ""};
tr[37690] = {H:"Тумба " + "\"" + "Бриз" + "\"" + ""};
tr[37691] = {H:"Очки " + "\"" + "Бриз" + "\"" + ""};
tr[37692] = {H:"Причёска " + "\"" + "Тик-так" + "\"" + ""};
tr[37693] = {H:"Кто в огороде хозяин?"};
tr[37694] = {H:"Прихожу я, значит, на грядки, а там натоптано! Лапищи воот такие, и пол-урожая всмятку. В общем, кто-то мне весь огород разворотил. Давай найдём проказника, ух!"};
tr[37695] = {H:"Может, Смешарики что-то видели? Приходи на Пляж."};
tr[37696] = {H:"Послушаем разговорчики. Поработай в Кафе и набери {0} Смешинок."};
tr[37697] = {H:"Напиши в общий чат: " + "\"" + "Кто испортил огород?" + "\"" + "."};
tr[37698] = {H:"Никто ничего не видел. Значится, по моему огороду прошёлся... Смешарик-невидимка!"};
tr[37699] = {H:"Кто в огороде хозяин?"};
tr[37700] = {H:"Совунья подсказала, как искать невидимку. Надо насыпать на него муки, и он сразу станет заметным."};
tr[37701] = {H:"Сова поделится мукой в обмен на варенье. Приходи в Дремучий лес."};
tr[37702] = {H:"Собери Дары леса и заработай {0} Смешинок."};
tr[37703] = {H:"Собери {0} груш в Ромашковой долине."};
tr[37704] = {H:"Варенье готово. А я рассыпал муку на огороде и обнаружил невидимку. Это зябриец Зак!"};
tr[37705] = {H:"Кто в огороде хозяин?"};
tr[37706] = {H:"Уф, спасибо! Зябрийцы становятся невидимыми от страха. Я не хотел громить огород, но меня так напугали...Боюсь вспоминать!"};
tr[37707] = {H:"Помоги мне одолеть страх. Приходи на Снежную гору."};
tr[37708] = {H:"Боюсь кататься с горки. Покажи, что это не страшно - победи в Сноуборде."};
tr[37709] = {H:"Наберись смелости! Найди в Шарараме 1 чудика и прогони."};
tr[37710] = {H:"Страх прошёл, и я вспомнил: на огороде был монстр, каких нет на Зябре. Маленький, красивый и с крыльями."};
tr[37711] = {H:"Кто в огороде хозяин?"};
tr[37712] = {H:"Я напугала зябрийца? Да, а ведь я и вправду порхала над огородом Копатыча в тот день... Помоги мне подружиться с Заком, чтобы он больше не боялся!"};
tr[37713] = {H:"Отправляйся в Джунгли."};
tr[37714] = {H:"Бабочки не страшные. Сыграй в игру с ними и заработай {0} Смешинок."};
tr[37715] = {H:"У бабочек фиалки - символ дружбы. Собери {0} штуки в Джунглях."};
tr[37716] = {H:"Зак больше не считает меня монстром. Он наведёт на огороде порядок. А ты держи награду!"};
tr[37717] = {H:"Загадки на грядке"};
tr[37718] = {H:"Видимое и невидимое"};
tr[37719] = {H:"Зябрийские пугалки"};
tr[37720] = {H:"Бабочка и дружба"};
tr[37721] = {H:"Ушанка с Зябры"};
