tr[37782] = {H:"Смайлы " + "\"" + "Профи" + "\"" + ""};
tr[37783] = {H:"Тайны Египта"};
tr[37784] = {H:"Обожаю пирамиды! И хочу построить одну у себя на даче. Но не знаю, как. Интересно, а как строили пирамиды в Древнем Египте?"};
tr[37785] = {H:"Подготовься к поездке в Египет. Сначала приходи в Дом мод."};
tr[37786] = {H:"Подбери наряд для путешествия. Сыграй в модельера."};
tr[37787] = {H:"Запасайся Позитивной энергией. Собери {0} штуки в любых играх."};
tr[37788] = {H:"Отлично! А вот тебе ещё Смешинки в дорогу."};
tr[37789] = {H:"Тайны Египта"};
tr[37790] = {H:"Поехали в Египет - узнаем, как строили пирамиды."};
tr[37791] = {H:"Отправляйся в Египет."};
tr[37792] = {H:"Познай тайны пирамид. Сыграй в игру богини истины Маат и заработай  {0} Смешинок."};
tr[37793] = {H:"Утоли жажду. Собери  {0} кокосов."};
tr[37794] = {H:"О, нет! Мы нечаянно потревожили египетского бога Ра!"};
tr[37795] = {H:"Тайны Египта"};
tr[37796] = {H:"Я поведаю вам секрет пирамид. Но сначала вы помогите мне. Злобыри в Шарараме вытягивают мою колдовскую силу. Нужно их остановить!"};
tr[37797] = {H:"Приходи в Каньон."};
tr[37798] = {H:"Покорми своего питомца."};
tr[37799] = {H:"Выходи на арену и победи {0} Злобыря."};
tr[37800] = {H:"Уговор есть уговор. Я раскрою секрет пирамид Доре."};
tr[37801] = {H:"Тайны Египта"};
tr[37802] = {H:"Теперь я знаю, что в центр каждой пирамиды прячут перо феникса! Какая удача - у меня как раз парочка завалялась. Поможешь мне на стройке?"};
tr[37803] = {H:"Пока Дора трудится, угости её ягодами. Собери Дары леса и заработай {0} Смешинок."};
tr[37804] = {H:"Напиши в общий чат: " + "\"" + "Дора - лучшая!" + "\"" + "."};
tr[37805] = {H:"Спасибо! Моя пирамида готова. И твоя тоже - забирай!"};
tr[37806] = {H:"Собираемся в дорогу!"};
tr[37807] = {H:"Изучаем Египет!"};
