tr[37815] = {H:"Шапка моряка"};
tr[37816] = {H:"Рубашка моряка"};
tr[37817] = {H:"Фон " + "\"" + "Пружинки" + "\"" + ""};
tr[37818] = {H:"Спутник-голограмма " + "\"" + "Шарри на каникулах" + "\"" + ""};
tr[37819] = {H:"Причёска " + "\"" + "Солнечная" + "\"" + ""};
tr[37820] = {H:"Футболка " + "\"" + "Ананас" + "\"" + ""};
tr[37821] = {H:"Кубок-пружинка|За самые высокие прыжки во время каникул."};
tr[37822] = {H:"Кубок " + "\"" + "Ту-ту" + "\"" + "|За победу в весёлых гонках на паровозе."};
tr[37823] = {H:"Я капитан корабля! Сыграй в морской бой со Смешариками в Шарараме!"};
tr[37824] = {H:"Спутник " + "\"" + "Летучая рыбка" + "\"" + ""};
tr[37825] = {H:"Песочный Карыч"};
tr[37826] = {H:"Песочный Крош"};
tr[37827] = {H:"Песочная Нюша"};
tr[37828] = {H:"Скорее в Шарарам! Вместе построим скульптуру из песка!"};
tr[37829] = {H:"Кресло " + "\"" + "Ананас" + "\"" + ""};
tr[37830] = {H:"Причёска " + "\"" + "Острый ум" + "\"" + ""};
tr[37831] = {H:"Бомбер " + "\"" + "Вундеркинд" + "\"" + ""};
tr[37832] = {H:"Урок загадочного дракона"};
tr[37833] = {H:"Причёска " + "\"" + "Драконьи локоны" + "\"" + ""};
tr[37834] = {H:"Хит Все жалюзи"};
tr[37835] = {H:"Песнь рыцаря"};
tr[37836] = {H:"Я сочинил поэму о подвигах для прекрасной дамы. Но чтобы впечатлить её, одних слов мало. Помоги мне подкрепить стихи делом!"};
tr[37837] = {H:"Удача вслед за рыцарём идёт, а ты приходи в Морской порт."};
tr[37838] = {H:"Прокатись по воде среди кувшинок - набери на катере {0} Смешинок."};
tr[37839] = {H:"В перископе видел - плавают киты. Посмотри в него и ты."};
tr[37840] = {H:"Хорошее начало. Лови Смешинки!"};
tr[37841] = {H:"Песнь рыцаря"};
tr[37842] = {H:"Однажды я оседлал дракона, но боюсь, эта история напугает даму. Расскажем ей о других деяниях."};
tr[37843] = {H:"Ради подвигов рыцарь с дракона слез, ну а ты отправляйся в Дремучий лес."};
tr[37844] = {H:"Не унывай, рыцарский друг, - собери орехов {0} штук."};
tr[37845] = {H:"Испеки пирог, приготовь грибы: собери скорее леса дары."};
tr[37846] = {H:"Даму впечатлили кулинарные подвиги с орехами и грибами!"};
tr[37847] = {H:"Песнь рыцаря"};
tr[37848] = {H:"В 21 веке даму не впечатлить рыцарскими латами. Нужна одежда модная и современная."};
tr[37849] = {H:"Рыцаря модой не сбить с пути, вот и ты на Главную площадь иди."};
tr[37850] = {H:"Не бойся, рыцарь, высоких цен - купи в Смешмаге кроссовки " + "\"" + "Спортсмен" + "\"" + "."};
tr[37851] = {H:"Похвастайся стилем новых ботинок - сходи-ка в клубы на {0} вечеринок."};
