tr[37854] = {H:"Обычно рыцари побаиваются волшебства, но только не тогда, когда нужно впечатлить даму."};
tr[37855] = {H:"Колдовать сегодня рад - приходи в Волшебный сад."};
tr[37856] = {H:"Колдовство ждёт впереди - в волшебном поединке победи."};
tr[37857] = {H:"Чудеса мне по душе - выиграй в Волшебном карандаше."};
tr[37858] = {H:"Вот это я понимаю, настоящая магия стихов!"};
tr[37859] = {H:"Песнь рыцаря"};
tr[37860] = {H:"Дама устала от подвигов, шумных вечеринок и колдовства. Почитаю ей стихи о тихой природе."};
tr[37861] = {H:"Скорей от шума отдохни - в Заповедник приходи."};
tr[37862] = {H:"Звери скачут на опушке - набери {0} Смешинок в фотоловушке."};
tr[37863] = {H:"Перед тобой цветочная интрига: сыграй-ка ты в Красную книгу."};
tr[37864] = {H:"Спасибо! Мои стихи особенно прекрасны, когда ты подкрепляешь их своими делами."};
tr[37865] = {H:"Подвиг в Порту"};
tr[37866] = {H:"Стихи о пирогах"};
tr[37867] = {H:"Рыцарь и мода"};
tr[37868] = {H:"Магия стихов"};
tr[37869] = {H:"Поэзия природы"};
