tr[37893] = {H:"Очки " + "\"" + "Лайм" + "\"" + ""};
tr[37894] = {OId:270,H:" Я рада, что мы отметили все мои дни рождения. Ура!"};
tr[37895] = {H:"Шкаф-гардероб"};
tr[37896] = {H:"Кеды " + "\"" + "Путь к мудрости" + "\"" + ""};
tr[37897] = {H:"Причёска " + "\"" + "Мудрость мастера" + "\"" + ""};
