tr[37899] = {H:"Фон " + "\"" + "Бумажный самолётик" + "\"" + ""};
tr[37900] = {H:"Пончо " + "\"" + "Птичка" + "\"" + ""};
tr[37901] = {H:"Причёска " + "\"" + "В полёт" + "\"" + ""};
