tr[37906] = {H:"Домик " + "\"" + "Самолёт" + "\"" + ""};
tr[37907] = {H:"Я добыл сокровища с Летучего корабля. В Шарараме и тебя ждут сюрпризы!"};
tr[37908] = {H:"Фон " + "\"" + "Перья грифона" + "\"" + ""};
tr[37909] = {H:"Спутник-грифон"};
tr[37910] = {H:"Дождевик " + "\"" + "Защитный" + "\"" + ""};
tr[37911] = {H:"Диван " + "\"" + "Ягоды" + "\"" + ""};
tr[37912] = {H:"Очки " + "\"" + "Ясный взгляд" + "\"" + ""};
tr[37913] = {H:"Футболка " + "\"" + "Путь к мудрости" + "\"" + ""};
tr[37914] = {H:"Можно автограф?"};
tr[37915] = {H:"Моя любимая певица - Леди Кря-Кря. Поможешь добыть её автограф? Только я стесняюсь вот так сразу... просить. Лучше сначала помечтать."};
tr[37916] = {H:"Отправляйся мечтать к морю на Пляж."};
tr[37917] = {H:"Мечтательно всмотрись в морскую даль - посмотри в Подзорную трубу."};
tr[37918] = {H:"Помечтай в тишине у морского дна. Сыграй в Батискаф в Подводном мире."};
tr[37919] = {H:"Ура, мечты прогнали стеснение. Идём в клубы за автографом!"};
tr[37920] = {H:"Можно автограф?"};
tr[37921] = {H:"Нет, не идём. Опять стесняюсь. В клубах все такие классные! Давай сначала ты сходишь? А я издалека посмотрю."};
tr[37922] = {H:"Разомни ноги перед танцами. Прогуляйся по лесу и собери его Дары."};
tr[37923] = {H:"Отправь {0} сообщений друзьям на Шарафон: " + "\"" + "Приходи в клубы танцевать!" + "\"" + "."};
tr[37924] = {H:"Посети {0} клубов."};
tr[37925] = {H:"Я набрался смелости, пошёл в клуб... и встретил ЕЁ!"};
tr[37926] = {H:"Можно автограф?"};
tr[37927] = {H:"Макс - такой стесняшка! Конечно, я дам ему автограф, только вот ни бумаги, ни ручки..."};
tr[37928] = {H:"Добудь волшебные чернила. Выиграй в Волшебный карандаш."};
tr[37929] = {H:"Поставим автограф на флаерсы. Собери {0} штуки в Клубном квартале."};
tr[37930] = {H:"Готово! У Макса теперь есть автограф. А тебе вот Смешинки прилетели:"};
tr[37931] = {H:"Можно автограф?"};
tr[37932] = {H:"Признаюсь, я и сама фанатка. Обожаю проделки Макса - он такой непредсказуемый! Я научу его быть классным, чтобы не стесняться в клубах."};
tr[37933] = {H:"Узнай тренды в моде. Сыграй в Модельера и набери {0} Смешинок."};
tr[37934] = {H:"Чтобы не стесняться, надо признаться. Напиши в чат: " + "\"" + "Стесняюсь танцевать" + "\"" + "."};
tr[37935] = {H:"Ну вот! Теперь Макс сможет чаще ходить в клубы на мои концерты."};
tr[37936] = {H:"Можно автограф?"};
tr[37937] = {H:"Леди Кря-Кря вдохновила меня сделать что-нибудь странное - ну как ей нравится. Поможешь?"};
tr[37938] = {H:"Устрой фестиваль еды. Приходи на Пляж."};
tr[37939] = {H:"Разбросай там вкусных помидора - кинь {0} штук."};
tr[37940] = {H:"А потом покорми гостей в кафе и заработай {0} Смешинок."};
tr[37941] = {H:"Спасибо! Так люблю еду с песочком - чтоб на зубах скрипело. А ты лови в награду эту штуку."};
tr[37942] = {H:"Мечтай!"};
tr[37943] = {H:"В клубах классно!"};
tr[37944] = {H:"Получи автограф!"};
tr[37945] = {H:"Не стесняйся!"};
tr[37946] = {H:"Странная затея"};
