tr[37968] = {H:"Фон " + "\"" + "Отличная погодка" + "\"" + ""};
tr[37969] = {OId:270,H:"Найди все звёзды в Шарараме и зажги!"};
tr[37970] = {H:"Звезда храбрости|Звезда наполнится храбростью через {0} мин."};
tr[37971] = {H:"Лунная рубашка"};
tr[37972] = {H:"Царские стулья"};
tr[37973] = {OId:270,H:"Магия красоты поможет принцессе победить злые чары! Посмотри - я так прекрасна, что зло на меня не действует."};
tr[37974] = {H:"Сирена, научи меня магии красоты!"};
tr[37975] = {OId:270,H:"Я знаю, кто наложил на принцессу проклятие. Всё началось в лесу... Принцесса решила отведать ягод..."};
tr[37976] = {H:"И?"};
tr[37977] = {OId:270,H:"И наломала дров! Кустики потоптала, воду взболомутила, зверей распугала. Вот лесные духи и обозлились..."};
tr[37978] = {H:"Леший, расскажи, как их задобрить."};
tr[37979] = {OId:270,H:"А ты знаешь, что принцессы, побывав жабами, продолсают прыгать и квакать? Привыська такая."};
tr[37980] = {H:"Сяо, как же вернуть принцессе королевскую грацию?"};
tr[37981] = {OId:270,H:"Усись у меня! Грацию вернёт гимнастика."};
tr[37982] = {H:"Давай учиться!"};
tr[37983] = {OId:270,H:"Расколдовать принцессу не проблема. Но что защитит её от злых чар в будущем?"};
tr[37984] = {H:"Я не знаю. А ты?"};
tr[37985] = {OId:270,H:"Говорят, от проклятий защищает лунная магия. Но чтобы овладеть ею, нужно получше узнать о самой Луне."};
tr[37986] = {H:"Сумрак, ты же оборотень! Расскажи мне о Луне!"};
tr[37987] = {H:" Мы со Смешариками расколдовали принцессу! Приходи в Шарарам и окажись в сказке."};
tr[37988] = {H:"Домик-торт"};
tr[37989] = {H:"Стул-кристалл"};
tr[37990] = {H:"Куртка " + "\"" + "Скорость мысли" + "\"" + ""};
tr[37991] = {H:"Стикеры-ромашки"};
tr[37992] = {H:"Аллея славы"};
tr[37993] = {H:"Я уже получил свою звезду на Аллее славы актёров, а ты? Скорее снимись в разных фильмах и стань звездой!"};
tr[37994] = {H:"Начнём с рыцарской саги. Приходи в Парк аттракционов."};
tr[37995] = {H:"Снимем погоню на лошадях. Выиграй в Скачки."};
tr[37996] = {H:"А теперь сцена волшебного поединка. Выиграй в него в Волшебном саду."};
tr[37997] = {H:"Снято! Первый хит готов. Держи свой гонорар."};
tr[37998] = {H:"Аллея славы"};
tr[37999] = {H:"В кино медлить нельзя. Вперёд на съёмки следующей картины - детектива."};
