tr[38056] = {OId:638,H:"Коллега, этому нет научного объяснения, но Злобикус умудрился приклеить звёзды к небосводу."};
tr[38057] = {H:"Значит, звездопада не будет?"};
tr[38058] = {OId:638,H:"Боюсь, вы правы... Ведь звёзды крепко приклеены и не смогут упасть. Вот же Нюша расстроится..."};
tr[38059] = {H:"А я полечу в космос и отклею звёзды!"};
tr[38060] = {OId:638,H:"Правда? Тогда, коллега, вы спасёте наш праздник! Скорее - ракета доставит вас на самый небосвод!"};
tr[38061] = {H:"Лечу!"};
tr[38062] = {OId:638,H:"Лети в космос на ракете и отклей звёзды!"};
tr[38063] = {OId:639,H:"Злобикус приклеил наши звёзды! Лети в космос и верни нам звездопад!"};
tr[38064] = {OId:270,H:"Под покровом ночи так удобно устраивать злодейские проделки. Зря вы решили провести праздник в полутьме!"};
tr[38065] = {H:"Ничего! Скоро наступит рассвет и..."};
tr[38066] = {OId:270,H:"Вы не увидите звездопада? Аха, солнце затмит звёзды, и праздничку конец."};
tr[38067] = {H:"Нужно успеть, чтобы Смешарики загадали желания!"};
tr[38068] = {OId:270,H:"Конечно, конечно. Только вот я поставил на звёзды клейкие ловушки - тронешь одну и сам приклеешься."};
tr[38069] = {H:"Ух, злодей! Но ничего - друзья помогут мне тебя одолеть!"};
tr[38070] = {H:"Олимпийка"};
tr[38071] = {H:"Дом-шатёр"};
tr[38072] = {H:"Штанга в домик"};
tr[38073] = {H:"Стикеры с Бицепсом"};
tr[38074] = {H:"Кубок с брызгами|Лучшему тренеру по плаванию на дино-олимпиаде!"};
tr[38075] = {H:"Кубок силы|Лучшему тренеру по тяжёлой атлетике на дино-олимпиаде!"};
tr[38076] = {OId:270,H:"Твой рогатый друг хочет что-то сказать... Что вы задумали?"};
tr[38077] = {OId:270,H:"Отправь Злобикуса на землю, пока он не натворил дел."};
