tr[38175] = {H:"Магия Диско-Копатыч|Получи эту способность у лемура в Каньоне|Ты можешь превращаться ещё дней: {0}|Ты можешь превращаться всегда!"};
tr[38176] = {H:"Кроссовки для танцев"};
tr[38177] = {H:"Кроссовки Ноль-один"};
tr[38178] = {H:"Кроссовки Ноль-два"};
tr[38179] = {H:"Кроссовки Ноль-три"};
tr[38180] = {H:"Кроссовки для танцев"};
tr[38181] = {OId:270,H:"Заходи в машину и проследи за внучком!"};
tr[38182] = {OId:270,H:"Аааа, Няня даёт мне урок музыки. Останови её!"};
tr[38183] = {OId:270,H:"Хватит, хватит, хватит. Музыку-то я люблю! Только слушать Леди Кря-Кря, а не играть на пианино."};
tr[38184] = {H:"А Док говорит, что музыка сделает из тебя культурного Смешарика."};
tr[38185] = {OId:270,H:"Дедушка так думает, а меня не спрашивает. Вот стану взрослым и сам всё решу."};
tr[38186] = {H:"Стать взрослым? Очень уж долго ждать!"};
tr[38187] = {OId:270,H:"А мы не будем ждать! Вот машина времени. Надо нажать на кнопку и улетим на 30 лет вперёд."};
tr[38188] = {H:"О! Можно узнать, кем ты вырастешь."};
tr[38189] = {OId:270,H:"А то! Полетели в будущее. Докажем Доку, что уроки музыки не нужны."};
tr[38190] = {H:"Полетели! Сейчас нажму на ту красную кнопку!"};
tr[38191] = {OId:270,H:"Кликни на красную кнопку – будущее ждёт!"};
tr[38592] = {OId:640,H:"Что?!!! Кто вы? Подождите... Ты это я! А ты... С тобой мы дружили в детстве!"};
tr[38593] = {H:"Ага! Привет, взрослый Макс. Мы прилетели из настоящего в будущее!"};
tr[38594] = {OId:640,H:"Вы не вовремя. Я не ждал гостей. Да и вообще отвык разговаривать."};
tr[38595] = {H:"Почему же?"};
tr[38596] = {OId:640,H:"Потому что я великий музыкант. Успеваю только на пианино играть и премии получать. Вот кстати ещё одна!"};
tr[38597] = {H:"Где?"};
tr[38598] = {H:"Вывеска с чаем"};
tr[38599] = {H:"Кроссовки-ролики"};
tr[38600] = {H:"Бомбер " + "\"" + "Скоро в школу" + "\"" + ""};
tr[38601] = {H:"Печка"};
tr[38602] = {H:"Подиум " + "\"" + "Пицца" + "\"" + ""};
tr[38603] = {H:"Цветник с лавандой"};
tr[38604] = {H:"Эльфийский стул"};
tr[38605] = {H:"Стол с пиццей"};
tr[38606] = {H:"Зеркало эльфов"};
tr[38607] = {H:"Клуб эльфов"};
tr[38608] = {H:"Неизвестный факт об эльфах №758: " + "\"" + "Эльфы мастера в приготовлении пиццы" + "\"" + ""};
tr[38609] = {H:"Что-то не верится!"};
tr[38610] = {H:"А вот и убедись: посмотри, какой у нас клуб-пиццерия!"};
tr[38611] = {H:"Вот и посмотрю."};
tr[38612] = {OId:640,H:"Посмотри, что в посылке - кликни на дрона."};
tr[38613] = {OId:641,H:"Я стану успешным музыкантом? Ерунда какая-то. Это же так скучно!"};
tr[38614] = {H:"Но это успех! Почему вы не рады, эмм, Максы?"};
tr[38615] = {OId:640,H:"А чему радоваться? Одни премии. Даже друзей нет – всё время на музыку трачу. Хоть она мне и не нравится."};
tr[38616] = {H:"Так займись чем-то другим. В мире полно интересных занятий!"};
tr[38617] = {OId:640,H:"Но я не умею... Дедушка учил меня только музыке."};
tr[38618] = {OId:641,H:"Я это исправлю! Начну заниматься тем, что мне по душе."};
tr[38619] = {H:"Крутая идея! Так ты изменишь будущее."};
tr[38620] = {OId:640,H:"Правда? Тогда я смогу стать счастливым!"};
tr[38621] = {OId:641,H:"Но занятий так много. Какую профессию выбрать?"};
tr[38622] = {H:"Мы же в будущем! Давайте узнаем, чем здесь занимаются Смешарики?"};
tr[38623] = {OId:641,H:"Узнай о профессиях будущего! Изучи предметы в квартире."};
tr[38624] = {H:"Миллион поклонников"};
tr[38625] = {H:"Я вот подумала: в моей жизни столько всего интересного, а никто и не знает, как классно я живу. Надо всем рассказать! Давай снимать видео."};
tr[38626] = {H:"Начнём с моего любимого - с моды. Приходи в Дом мод."};
tr[38627] = {H:"Снимем ролик про наряды. Сыграй в модельера и заработай {0} Смешинок."};
tr[38628] = {H:"Обновками надо похвастаться. Сходи в {0} клубов."};
tr[38629] = {H:"Ух, надеюсь с такими роликами я соберу целый миллион поклонников."};
tr[38630] = {H:"Миллион поклонников"};
tr[38631] = {H:"Продолжим вести мой блог. Давай устроим фотосессию на природе."};
tr[38632] = {H:"Приходи в Заповедник."};
tr[38633] = {H:"Научись фотографировать. Сыграй в Фотоловушку и набери {0} Смешинок за 1 раз."};
tr[38634] = {H:"Чтобы фотосессия вышла забавнее, кинь {0} помидоров."};
tr[38635] = {H:"Наша смешная фотосессия - хит по просмотрам. Лови награду!"};
tr[38636] = {H:"Миллион поклонников"};
tr[38637] = {H:"Проведём стрим с ответами на вопросы. Заодно и мои видео прорекламируем."};
tr[38638] = {H:"Отправь {0} сообщений на Шарафон: " + "\"" + "А Нюша-то у нас блогер!" + "\"" + "."};
tr[38639] = {H:"Задай мне вопрос. Напиши в общий чат: " + "\"" + "Нюша, как дела?" + "\"" + "."};
tr[38640] = {H:"Зрители стрима собрались в Кафе на Пляже. Покорми их и заработай {0} Смешинок."};
tr[38641] = {H:"Стрим прошёл на ура! И у меня теперь много новых подписчиков."};
tr[38642] = {H:"Миллион поклонников"};
tr[38643] = {H:"Хочу снять видео о походе в лес. Поехали!"};
tr[38644] = {H:"Приходи в Дремучий лес."};
tr[38645] = {H:"Сделаем обзор на орехи. Собери {0} штук."};
tr[38646] = {H:"Сыграй в Дары леса и набери {0} Смешинок за 1 раз."};
tr[38647] = {H:"Ой, а где это я оказалась? Сейчас разберёмся."};
tr[38648] = {H:"Миллион поклонников"};
tr[38649] = {H:"Я заблудилась в лесу и ушла аж в самый Египет. Чего только не случится на съёмке блога!"};
tr[38650] = {H:"Приезжай ко мне - отправляйся в Египет."};
tr[38651] = {H:"Ну и жара! Сыграй в игру влаги Тефнут и набери {0} Смешинок."};
tr[38652] = {H:"Хочу фиников. Сыграй в игру Исиды."};
tr[38653] = {H:"Спасибочки! Новый выпуск принёс мне миллион подписчиков. А тебе - подарок!"};
tr[38654] = {H:"Видео про моду"};
tr[38655] = {H:"Смешная фотосессия"};
tr[38656] = {H:"Стрим для фанатов"};
tr[38657] = {H:"Видео в лесу"};
tr[38658] = {H:"Приключения на съёмках"};
tr[38659] = {H:"Чип|Чип привезут через {0} мин."};
tr[38660] = {OId:642,H:"Я растерялся. Столько крутых профессий. На моём месте ты бы что выбрал?"};
tr[38661] = {H:"Продолжил заниматься музыкой. Успех важнее счастья."};
tr[38662] = {H:"Будь тобой - я бы стал поваром. Почему? Потому."};
tr[38663] = {H:"На твоём месте? Техника и гаджеты интереснее всего!"};
tr[38664] = {OId:640,H:"А для меня интерес важнее. Может, заняться чем-то связанным с техникой? Стать инженером!"};
tr[38665] = {H:"Хорошая мысль. Давайте расскажем об этом Доку."};
tr[38666] = {OId:641,H:"Однажды я приготовил бутерброд с лимоном и медной проволокой. И добыл электричество!"};
tr[38667] = {H:"Хм... Может, лучше заняться техникой и стать инженером? Давай расскажем Доку!"};
tr[38668] = {OId:640,H:"У меня вся семья - изобретатели и инженеры. И мне это нравится!"};
tr[38669] = {H:"Давай расскажем Доку и убедим его отменить уроки музыки."};
tr[38670] = {OId:640,H:"План такой: возвращайтесь в настоящее и расскажите Доку, что музыка не сделала меня счастливым."};
tr[38671] = {OId:641,H:"И что профессию нужно выбирать так, чтобы было интересно!"};
tr[38672] = {H:"А вдруг он нам не поверит? Он строгий."};
tr[38673] = {OId:640,H:"Деда, привет!"};
tr[38674] = {OId:641,H:"Что за дела? Уроки не сделаны, а няня выключена."};
tr[38675] = {H:"А это Макс придумал, как её выключить."};
tr[38676] = {OId:641,H:"Но выключить робота может только талантливый инженер. Неужели Макс..."};
tr[38677] = {H:"Макс любит возиться с техникой! А музыку не любит."};
tr[38678] = {OId:640,H:"Да, деда. Мы слетали в будущее и узнали, что музыка - это не моё. Вот даже фотка есть."};
tr[38679] = {OId:641,H:"Но я думал, музыка сделает тебя счастливым! И культурным."};
tr[38680] = {H:"А вот и нет. Каждому своё, Док!"};
tr[38681] = {OId:641,H:"Ну вот ещё! Думал, это я воспитываю Макса. Но теперь вы воспитываете меня!"};
tr[38682] = {H:"Не кипятись, Док!"};
