tr[38856] = {H:"СмеШутка-Листопад|Получи эту способность у лемура в Каньоне|Ты можешь шутить ещё дней: {0}|Ты можешь шутить всегда!"};
tr[38857] = {OId:270,H:"Сними 1 серию на Главной площади!"};
tr[38858] = {OId:643,H:"1 серия снята! Чтобы зрители ждали продолжения, нужно выбрать финальный поворот."};
tr[38859] = {H:"Давай выберем!"};
tr[38860] = {OId:643,H:"Во время урагана у Сэнсэя было видение о большой угрозе! Какой?"};
tr[38861] = {H:"Пятирукий чудик!"};
tr[38862] = {H:"Электрический монстрик!"};
tr[38863] = {OId:643,H:"Значит, в следующей серии Лига пойдёт по следам злодея. Приходи на съёмки в Дремучий лес."};
tr[38864] = {H:"Бегу!"};
tr[38865] = {OId:270,H:"Сними 2 серию в Дремучем лесу!"};
tr[38866] = {H:"Шуруп для ИУ|Шуруп привезут через {0} мин."};
tr[38867] = {OId:644,H:"По сюжету я поймала злодея в лесу. Помоги снять сцену разговора: подскажи ему верные реплики."};
tr[38868] = {H:"Камера! Начали!"};
tr[38869] = {H:"Подожди, надо собраться с мыслями."};
tr[38870] = {OId:644,H:"Лига героев защитит Шарарам! Скажи, злодей, что ты задумал?"};
tr[38871] = {OId:645,H:"...пст, подскажите реплику..."};
tr[38872] = {H:"" + "\"" + "Выпить чаю с Лосяшем, да отведать французских булочек." + "\"" + ""};
tr[38873] = {H:"" + "\"" + "Ничего я вам не скажу!" + "\"" + ""};
tr[38874] = {OId:644,H:"Может, стаканчик апельсинового сока и щепотка заботы заставит тебя заговорить?"};
tr[38875] = {OId:645,H:"...ой, опять забыл...."};
tr[38876] = {H:"" + "\"" + "Ладно, скажу правду. Я просто шпионил для настоящих злодеев." + "\"" + ""};
tr[38877] = {H:"" + "\"" + "Так и быть. На самом деле Копатыч - конь. Это вы хотели услышать?" + "\"" + ""};
tr[38878] = {OId:644,H:"Что это за злодеи? Чего они хотят? "};
tr[38879] = {OId:645,H:"...что отвечать?"};
tr[38880] = {H:"" + "\"" + "Знаю только, что их логово в Порту." + "\"" + ""};
tr[38881] = {H:"" + "\"" + "Знаю только, что их логово в Парке аттракционов." + "\"" + ""};
tr[38882] = {OId:644,H:"Это заводит сюжет в тупик. Давай придумаем другую реплику."};
tr[38883] = {H:"Ок. Поехали с начала!"};
tr[38884] = {OId:270,H:"Сними 3 серию в Парке аттракционов!"};
tr[38885] = {OId:270,H:"Сними 3 серию в Порту!"};
tr[38886] = {OId:646,H:"Снимаем 3 серию. Логово злодеев в ангаре - иди туда!"};
tr[38887] = {OId:646,H:"Снимаем 3 серию. Логово злодеев в бункере под землёй - иди туда!"};
tr[38888] = {OId:647,H:"Съёмки проходят на ура! В 3 серии раскроется главная интрига сериала. А Лига проявит себя!"};
tr[38889] = {H:"Сначала напомни, какой там у нас сюжет?"};
tr[38890] = {H:"Давай сразу перейдём к интриге."};
tr[38891] = {OId:647,H:"У Сэнсэя было видение об угрозе для Шарарама. ИУ погнался за шпионом, и вместе с Медведусей они нашли логово злодеев."};
tr[38892] = {H:"Так в чём же интрига?"};
tr[38893] = {OId:647,H:"Здесь злодеи прячут свои коварные планы. По сюжету я должен взломать их компьютер."};
tr[38894] = {H:"И разведать планы? Ясно!"};
tr[38895] = {OId:647,H:"Кликни на компьютер, чтобы начать."};
tr[38896] = {H:"Отлично. Снимаем!"};
tr[38897] = {OId:647,H:"Кликни на компьютер, чтобы начать съёмки!"};
tr[38898] = {OId:270,H:"Сними 4 серию в Бухте!"};
