tr[38900] = {H:"А что ещё нужно?"};
tr[38901] = {OId:270,H:"Чтобы серия не вышла скучной, снимем крутую экшен-сцену. Покажем, как грозный робот летит к Шарараму."};
tr[38902] = {H:"Да, да. Надо убедить зрителя, что робот могуч."};
tr[38903] = {OId:643,H:"В финале нашего сериала Лига должна остановить монстра, которого создал Злобикус. Но для кино этого мало."};
tr[38904] = {OId:380,H:"Чтобы серия не вышла скучной, снимем крутую экшен-сцену. Покажем, как грозный монстр летит к Шарараму."};
tr[38905] = {H:"Да, да. Надо убедить зрителя, что монстр могуч."};
tr[38906] = {OId:380,H:"Начинай съёмки! Кликни на актёра."};
