tr[38910] = {H:"Давай сразу снимать!"};
tr[38911] = {OId:643,H:"Злобикус оживил статую и превратил в монстра, который... Ну просто злой. И всем угроза. Вот!"};
tr[38912] = {H:"Мда, а в сценарии-то у вас дыра! Чем этот монстр так плох?"};
tr[38913] = {OId:643,H:"Злобикус построил робота, который... Ну просто злой. И всем угроза. Вот!"};
tr[38914] = {H:"Мда, а в сценарии-то у вас дыра! Чем этот робот так плох?"};
tr[38915] = {OId:380,H:"Я, я придумал: злодей хочет похитить годовой запас варенья Совуньи!"};
tr[38916] = {H:"Вот, уже лучше. Давайте снимать!"};
tr[38917] = {OId:380,H:"В сериале Лига победит злодея хитростью. Сначала собьём его с пути, а потом заманим в ловушку."};
