tr[38966] = {H:"Подкрепи рассказ колдовством. Выиграй в Волшебный поединок."};
tr[38967] = {H:"Это удача! От колдовства моя поэма стала популярнее и прозвучала на весь Шарарам!"};
tr[38968] = {H:"Заколдованная поэма"};
tr[38969] = {H:"Укуси меня пчела! Бараш поди волшебник, но после его поэм овощи и вправду от меня разбежались. Ну дела! Надо их вернуть."};
tr[38970] = {H:"Крош поможет вернуть морковь. Приходи на Пляж."};
