tr[39030] = {OId:270,H:"То, что надо! Сначала подготовься к съёмкам: закажи реквизит и обсуди с Крошем сценарий."};
tr[39031] = {H:"Поехали!"};
tr[39032] = {OId:651,H:"Привет... А.... А можно... Можно?"};
