tr[39205] = {H:"Костюм " + "\"" + "Дракоша" + "\"" + ""};
tr[39206] = {H:"Я победил Монстрика! Ты тоже сможешь! Айда в Шарарам!"};
tr[39207] = {OId:270,H:"Дружище, вопросов в " + "\"" + "Царе горы" + "\"" + " так много, что ни один Смешарик бы столько не придумал."};
tr[39208] = {H:"Откуда же берутся эти вопросы?"};
tr[39209] = {OId:270,H:"Их придумывает искусственный интеллект! То есть компьютер. А мы потом выбираем самые удачные."};
tr[39210] = {H:"Так вот почему некоторые вопросы такие странные."};
tr[39211] = {OId:270,H:"Да! Компьютер, бывает, чудит... Помоги мне проверить его работу и составить вопросы для игры."};
tr[39212] = {H:"Окей. Поехали!"};
tr[39213] = {OId:270,H:"В " + "\"" + "Царе горы" + "\"" + " у меня очень важная работа. Я должна всем-всем игрокам рассказать, как они ответили. Причём одновременно!"};
tr[39214] = {H:"Как же ты справляешься, Нюша?"};
tr[39215] = {OId:270,H:"С помощью колдовства. Умникус научил меня одному заклинанию, которое поворачивает время вспять."};
tr[39216] = {H:"Сложно звучит!"};
tr[39217] = {OId:270,H:"Зато работает! Ради каждого игрока я возвращаюсь в прошлое, смотрю, как он ответил, и говорю результат."};
tr[39218] = {H:"И так ты всё успеваешь! А расскажешь про заклинание?"};
tr[39219] = {OId:270,H:"Ты же знайт, что подарки в " + "\"" + "Царе горы" + "\"" + " дарит Ёжик. Стоит там и следит, чтобы всем доставайся призы."};
tr[39220] = {H:"Ёжик, наверное, доволен, что кругом столько подарков."};
tr[39221] = {OId:270,H:"Йа. Только почта иногда не справляйся! Представь, сколько подарок надо привезти в Шарарам, чтобы всем хватило."};
tr[39222] = {H:"Ох уж эта почта! Давай её поторопим."};
tr[39223] = {OId:270,H:"Ради игры на Умной горе собирается огромная толпа Смешариков. Сидят там, колдуют, помидорами швыряются..."};
tr[39224] = {H:"Да! Чего там только не увидишь."};
tr[39225] = {OId:270,H:"Вот я, как хозяйка, вижу там сор и грязь. И каждую ночь прихожу на гору, чтобы всё помыть."};
tr[39226] = {H:"Совунья, это же настоящий подвиг!"};
tr[39227] = {OId:270,H:"А мне приятно! Радостно смотреть, что Смешарики сидят в чистоте. А ещё я им чай завариваю."};
tr[39228] = {H:"Может, тебе нужна помощь с уборкой?"};
tr[39229] = {H:"Мыло|Мыло принесут через {0} мин."};
tr[39230] = {OId:270,H:"Коллега, слушайте. Гора, на которую взбираются Смешарики - самое высокое место в Шарараме. "};
tr[39231] = {H:"Оно и видно."};
tr[39232] = {OId:270,H:"А ещё это древняя пирамида, построенная неизвестным нам народом. Такая старая, что ей нужен уход."};
tr[39233] = {H:"Намекаешь, что она может развалиться?"};
tr[39234] = {OId:270,H:"Ну а вдруг? Представь, сколько Смешариков по ней скачет. Давай заберёмся наверх и немного её подлатаем."};
tr[39235] = {H:"Давай."};
tr[39236] = {OId:270,H:"Что это за антенна? Скорее кликни на неё!"};
tr[39237] = {OId:270,H:"Феноменально! Джунгля - планета необитаемая. И всё же сигнал со знаниями летит именно туда."};
tr[39238] = {H:"Неужели там завелась жизнь, Лосяш? Надо проверить!"};
tr[39239] = {H:"Как это? А я вот помню, что на Джунгле..."};
tr[39240] = {OId:270,H:"...жили гусеницы, которые чуть не проглотили Сирену? Да, но они давно переехали на Зябру. Ради пончиков."};
tr[39241] = {H:"Ясно. Выходит, на Джунгле завелась новая жизнь? Надо проверить!"};
tr[39242] = {OId:270,H:"Отправляйся на Космодром и поговори с Копатычем. Вместе полетите на Джунглю!"};
tr[39243] = {H:"Бегу"};
tr[39244] = {OId:270,H:"Отправляйся на Космодром и поговори с Копатычем. Вместе полетите на Джунглю!"};
