tr[39258] = {OId:270,H:"Cадись в ракету - летим на Джунглю."};
tr[39259] = {OId:270,H:"Смешарики? Раз вы здесь, значит уже разнюхали, что мы воруем знания, чтобы создать суперсильного робота и завоевать Землю."};
tr[39260] = {H:"Нет... Подожди! Что? Завоевать?"};
tr[39261] = {OId:270,H:"Космопчелу мне в ус! Я проговорился. Робот выкачивает знания из Шарарама, чтобы стать умным и непобедимым."};
tr[39262] = {H:"Эй, не надо так! Ум нужно использовать ради добра."};
tr[39263] = {OId:270,H:"Поговори с пиратами. А я пока ракету подлатаю!"};
tr[39264] = {H:"Магия " + "\"" + "Зябро-Ёжик" + "\"" + " навсегда"};
tr[39265] = {OId:270,H:"Беги к Лосяшу на Умной горе!"};
tr[39266] = {OId:270,H:"Не подходи. Робот под нашей охраной."};
tr[39267] = {OId:270,H:"Друг мой спасающий, робот у пиратов действительно страшный. Но без ума он ничего не стоит."};
tr[39268] = {H:"А ум он ворует из наших ответов в " + "\"" + "Царе горы" + "\"" + "."};
tr[39269] = {OId:270,H:"Значит... Надо отправить ему не умные ответы, а глупые."};
tr[39270] = {H:"Как это?"};
tr[39271] = {OId:270,H:"Проведём секретную игру в " + "\"" + "Царя" + "\"" + ", где отвечать надо неправильно. Робот украдёт эти знания, и поглупеет."};
tr[39272] = {H:"Интересный план. Давай попробуем!"};
tr[39273] = {OId:270,H:"Лети на Джунглю с Космодрома!"};
tr[39274] = {OId:270,H:"Поговори с Пиратом - узнай, что стало с роботом!"};
tr[39275] = {OId:270,H:"Что... Что это... Что это было?!"};
tr[39276] = {H:"Ты мне расскажи!"};
tr[39277] = {OId:270,H:"Робот ожил, сказал, что он весна, надел на голову яблоко и пошёл читать озеро."};
tr[39278] = {H:"И?"};
tr[39279] = {OId:270,H:"Робот должен был стать умным, но оказался таким глупым, что открутил себе голову и кинул в воду. А потом..."};
tr[39280] = {H:"Что?"};
tr[39281] = {OId:270,H:"А потом всё заискрилось... Бум-бам, ба-бах! Мои приятели сбежали от страха. А я вот держусь."};
tr[39282] = {H:"Это успех! Значит, мы сломали робота, и миру больше ничего не грозит!"};
