tr[39822] = {H:"Диван " + "\"" + "Морской берег" + "\"" + ""};
tr[39823] = {OId:270,H:"Кликни на корабль, и поплывём!"};
tr[39824] = {OId:270,H:"Бедняжка кит. Поговори с ним!"};
tr[39825] = {OId:661,H:"Аааапчхи! Ааааа-осторожно... Чхи! Не подходи, а то заморожу."};
tr[39826] = {H:"Здравствуй, Кит. Мы со спрутиками тебя вылечим."};
tr[39827] = {OId:661,H:"Спаааа-чхибо. Жаль, меня ваши лекарства не берут. Посмотри, какой я ааааагромный. Чхи."};
tr[39828] = {H:"Как же тогда киты лечатся?"};
tr[39829] = {OId:661,H:"Не знаю! Я вот первый раз болею. Но поговаривают, одна звезда может указать путь к..."};
tr[39830] = {H:"Лекарству?"};
tr[39831] = {OId:661,H:"Апчхи! Правда, это всего лишь старая легенда. Но ты проверь – найди на небе созвездие Кита."};
tr[39832] = {H:"Давай попробуем!"};
tr[39833] = {OId:270,H:"И где же лекарство? Одни фонтаны бесполезные... Кит ошибся."};
tr[39834] = {H:"А вдруг не ошибся? Подозрительные эти фонтаны."};
tr[39835] = {OId:270,H:"Да! Кому пришло в голову поставить их на необитаемом острове? Может, это загадка?"};
tr[39836] = {H:"Надо проверить! Осмотрю фонтаны."};
tr[39837] = {OId:270,H:"Осмотри фонтаны и разгадай их тайну!"};
tr[39838] = {OId:661,H:"Приготовь лекарство со Спрутиками!"};
tr[39839] = {OId:270,H:"Ух ты! Сундук появился. Открой его!"};
tr[39840] = {OId:270,H:"Поговори с Китом!"};
tr[39841] = {OId:661,H:"Мне, конечно, стало лучше... Но в то же время поплохело..."};
tr[39842] = {H:"Ты так скоро всё море вскипятишь!"};
tr[39843] = {OId:661,H:"Может, в рецепте ошибка, и вы перестарались с лекарством?"};
tr[39844] = {H:"Не может быть! Сейчас проверю..."};
tr[39845] = {OId:661,H:"Поговори со Злобикусом! Пусть вылечит меня от своего зелья."};
tr[39846] = {OId:270,H:"Злобикус уже тут! Поговори с ним."};
tr[39847] = {OId:270,H:"Всё удалось! Поговори со Злобикусом."};
tr[39848] = {OId:661,H:"Поговори со Злобикусом! Пусть вылечит меня!"};
tr[39849] = {OId:660,H:"А водичка-то тёпленькая. Хоть лапшу заваривай. Но я не лапша, а великий злой маг!"};
tr[39850] = {H:"Вот сам в своё колдовство и плюхнулся! Это ты сделал кита огнедышащим."};
tr[39851] = {OId:660,H:"Твоя правда... Придётся излечить кита, чтобы самому не перегреться."};
tr[39852] = {H:"Вот-вот!"};
tr[39853] = {OId:270,H:"Кит благодарен! Поговори с ним и получи приз."};
tr[39854] = {OId:661,H:"Хорошо придумано! Злобикус сам пострадал от своих пакостей, а меня, наоборот, спас."};
tr[39855] = {H:"Ура! Хорошо, что ты больше не кипятишь море."};
tr[39856] = {OId:661,H:"А то! Я такой огромный, что всем морским обитателям мог навредить. Но этого не случилось – благодаря тебе. Спасибо!"};
