tr[40172] = {H:"Диван " + "\"" + "Гениальность" + "\"" + ""};
tr[40173] = {H:"Причёска " + "\"" + "Вызов" + "\"" + ""};
tr[40174] = {H:"Шарафон-Лампочка"};
tr[40175] = {H:"Краска|Краску нальют через {0} мин."};
tr[40176] = {OId:668,H:"Призрак обронил записку с кодом. Ушами клянусь, в этом доме должна быть потайная дверь!"};
tr[40177] = {H:"Хм... Давай проверим."};
tr[40178] = {OId:668,H:"Ага! Найди эту дверь. И запомни код: 1КСПР22. Ну или не запоминай – я всегда подскажу."};
