tr[40180] = {OId:668,H:"Найди в доме тайную дверь. И введи на ней код: 1КСПР22"};
tr[40181] = {OId:669,H:"Ага! Это же... Комната со всяким волшебным старьём. Ничего интересного."};
tr[40182] = {H:"А фонтан? Выглядит любопытно."};
tr[40183] = {OId:669,H:"Фонтан скучный. Мне такого не надо! Может просто подарим его кому-то, чтобы не пропадал?"};
tr[40184] = {H:"Копатычу! Он любит такие утончённые хрустальные штуки."};
tr[40185] = {H:"Нюше! Вроде это её любимый цвет."};
tr[40186] = {OId:669,H:"Копатыч растяпа. Разобьёт фонтан своими граблями и не заметит."};
tr[40187] = {H:"Подарим Нюше тогда. Поставит у себя в домике и будет любоваться."};
tr[40188] = {OId:669,H:"Крутая идея! Нюше такое точно понравится. Бежим к ней в домик."};
tr[40189] = {H:"Вперёд."};
tr[40190] = {OId:270,H:"Найди Бараша в Шарараме и пригласи на вечеринку."};
tr[40191] = {OId:270,H:"Тссс, дай дочитать... " + "\"" + "Призраки вселяются в предметы. Например, в чайник или кусок мыла..." + "\"" + ""};
tr[40192] = {H:"Что читаешь-то? Тебя там Нюша на вечеринке ждёт!"};
tr[40193] = {OId:270,H:"Нюша?! Бежим же к ней скорее! А книжка... Да так, про призраков всяких и про проклятия."};
tr[40194] = {H:"Ну и мрак. Идём веселиться. Скорее в домик Нюши!"};
tr[40195] = {OId:670,H:"Вы не поверите! Вечеринка шла хорошо, как вдруг все мы превратились... Будто проклятие какое-то."};
tr[40196] = {H:"Бараш. Твоё заклинание вернуло голос. Давай и остальное расколдуем?"};
tr[40197] = {OId:671,H:"Подходящего заклинания нет... Но есть кое-что про проклятие. Вы недавно не встречались с призраком?"};
tr[40198] = {H:"Ну-у... Да, было дело."};
tr[40199] = {OId:670,H:"А при чём тут я и моя вечеринка?!"};
tr[40200] = {H:"Нюша... Наверное, надо было сразу признаться. Этот фонтан из дома призрака!"};
tr[40201] = {OId:670,H:"Ааааа! Так значит... Сок из этого фонтана нас околдовал..."};
tr[40202] = {OId:671,H:"Возможно, фонтан проклят."};
tr[40203] = {H:"Как неловко вышло... А такой хороший был подарок. Давай снимем проклятие?"};
tr[40204] = {OId:270,H:"Иди в тайную комнату. Вход тут справа."};
tr[40205] = {OId:270,H:"Кликни на стол, чтобы вернуть фонтан"};
tr[40206] = {OId:270,H:"Беги к Нюше в гости. Кликни на её домик на полянке."};
tr[40207] = {OId:270,H:"На вечеринке ждут Бараша! Я его видел у Больнички."};
tr[40208] = {OId:270,H:"Беги в особняк призрака, чтобы снять проклятие."};
tr[40209] = {OId:672,H:"Вот и как мне теперь подарки принимать? Буду каждый раз спрашивать, нет ли в них проклятия."};
tr[40210] = {OId:673,H:"Прости, Нюша! Это я предложил подарить фонтан тебе."};
tr[40211] = {H:"Ну и хулиган же ты, Крош!"};
tr[40212] = {H:"Нюша, мы же от чистого сердца!"};
tr[40213] = {OId:672,H:"Ладно, я вовсе и не обижаюсь. Это было даже... весело! У кого ещё бывают такие вечеринки с превращениями?"};
tr[40214] = {H:"А ещё Бараш молодец. Если бы не его книга, мы бы не сняли проклятие."};
tr[40215] = {OId:672,H:"Ах, Барашик! Спасибо тебе."};
tr[40216] = {OId:674,H:"Раз такое дело... Давайте я вам подарки подарю? Они без всяких проклятий, обещаю!"};
tr[40217] = {H:"Ух ты! Давай посмотрим."};
