tr[40319] = {OId:270,H:"Проведи каникулы со звёздами на Пляже."};
tr[40320] = {OId:270,H:"Помоги Сирене!"};
tr[40321] = {H:"Крем от солнца|Крем принесут через {0} мин."};
tr[40322] = {OId:270,H:"Шок-контент! Я и не думал, что у нас на Пляже бывают такие волны."};
tr[40323] = {H:"Надо скорее спасать Сирену!"};
tr[40324] = {OId:270,H:"О! Ура! Сирена прислала мне сообщение. Видимо, связь в море есть."};
tr[40325] = {H:"Что она пишет?"};
tr[40326] = {OId:270,H:"Она скинула точку на карте с хэштегом " + "\"" + "Страшные дикари" + "\"" + ". Это на берегу безымянного острова."};
tr[40327] = {H:"Она достигла суши – это хорошо. А вот дикари... Не очень."};
tr[40328] = {H:"Фон " + "\"" + "Волшебный парк" + "\"" + ""};
tr[40329] = {H:"Фон " + "\"" + "Туманность" + "\"" + ""};
tr[40330] = {H:"Фон " + "\"" + "Розовое вдохновение" + "\"" + ""};
tr[40331] = {H:"Туземный костюм"};
tr[40332] = {OId:675,H:"Взгляни – само море принесло к нам эту красавицу."};
tr[40333] = {H:"Её зовут Сирена! И как вы посмели посадить её в клетку?!"};
tr[40334] = {OId:676,H:"Это не клетка, а туземный дворец. И я не сижу взаперти, потому что..."};
tr[40335] = {OId:675,H:"Она – богиня, обещанная нам пророчеством."};
tr[40336] = {H:"И что там в пророчестве?"};
tr[40337] = {OId:675,H:"Оно гласит: " + "\"" + "Сирена явится, чтобы спасти остров от страшного зверя" + "\"" + "."};
tr[40338] = {H:"И ты согласилась исполнить пророчество, Сирена?"};
tr[40339] = {OId:676,H:"Да! Туземцы меня накормили и обогрели. Конечно, я помогу!"};
tr[40340] = {H:"Хорошо. Но как ты справишься со зверем?"};
tr[40341] = {OId:675,H:"Кликни на указатель, чтобы отправиться к зверю."};
tr[40342] = {OId:270,H:"Никого нет. Найди предмет, чтобы выманить зверя."};
tr[40343] = {H:"Кресло " + "\"" + "Хай-тек" + "\"" + ""};
tr[40344] = {OId:270,H:"Страшно-то как! Выходит, зверь, которого все боятся – крокодил."};
tr[40345] = {H:"Ну и чудище! Его рык на весь остров разносится."};
tr[40346] = {OId:270,H:"Даже не знаю... Может, в пророчестве ошибка. Как мне его одолеть?"};
tr[40347] = {H:"Давай подумаем. Что у тебя получается лучше всего?"};
tr[40348] = {OId:270,H:"Лучше всего? Петь! Но разве песни могут успокоить крокодила?"};
tr[40349] = {H:"Спой свой главный танцевальный хит. Вдруг сработает."};
tr[40350] = {H:"Спой колыбельную! Эта песня создана, чтобы успокаивать."};
tr[40351] = {OId:270,H:"Ну... Этот крокодил выглядит как тот, кто не понимает современную музыку."};
tr[40352] = {H:"Мда. Может, тогда споёшь ему колыбельную?"};
tr[40353] = {OId:270,H:"Отличная идея! Правда, я не знаю ни одной колыбельной."};
tr[40354] = {H:"А давай новую сочиним?"};
tr[40355] = {H:"Славная кепка"};
tr[40356] = {H:"Славная безрукавка"};
tr[40357] = {OId:270,H:"Кликни на туземца и научи его колыбельной."};
tr[40358] = {OId:675,H:"Вы нам так помогли! Теперь зверь нам не страшен, и мы можем ходить вглубь острова."};
tr[40359] = {H:"Кстати, а зачем вам туда ходить?"};
tr[40360] = {OId:675,H:"Там самые чистые родники и самые вкусные тропические фрукты. Мы даже для тебя кое-что приготовили."};
