tr[40458] = {OId:270,H:"Найди Смешариков и помоги им оживить сказку!"};
tr[40459] = {OId:270,H:"Найди две новые сказки в Шарараме и забери призы!"};
tr[40460] = {OId:270,H:"Моё заклинание должно было подарить нам праздник и сказку, а не мрачные истории."};
tr[40461] = {H:"Да! А ещё там эти стихи про Злобырей."};
tr[40462] = {OId:270,H:"Нет сомнений – это Злобикус устроил. Украл моё заклинание и оживил кошмар, а не сказку."};
tr[40463] = {H:"Давай отправимся к нему и отменим заклинание."};
tr[40464] = {OId:270,H:"Круто придумано! Сейчас я открою портал – он перенесёт нас прямо к Злобикусу."};
tr[40465] = {H:"О, магия!"};
tr[40466] = {OId:270,H:"Зачем ворвался в мой дом? Я хочу побыть один... Помечтать."};
tr[40467] = {H:"Вот и сидел бы тут, а не колдовал кошмары для Шарарама."};
tr[40468] = {OId:270,H:"Это не я! Моё колдовство – японская сказка во славу любимой Сяо Мяо..."};
tr[40469] = {H:"Хм, я был в этой сказке. А подарок ты там какой оставил?"};
tr[40470] = {OId:270,H:"Сакуру, конечно! Я, может, и злодей, но в день рождения Шарарама и мне хочется праздника."};
tr[40471] = {H:"Кто же наколдовал кошмары? Там был стих про Злобырей."};
tr[40472] = {OId:270,H:"Терпеть не могу стихи! А ты меня обвиняешь. Лучше у Бараша спроси..."};
tr[40473] = {H:"Бараш? И вправду, из всех Смешариков он больше всех любит сочинять."};
tr[40474] = {OId:270,H:"Найди Бараша и расспроси про злобные стихи."};
tr[40475] = {OId:270,H:"Поговори с Барашем в Порту."};
tr[40476] = {OId:270,H:"В общем, я хотел как и все наколдовать сказку. А получился ужас."};
tr[40477] = {H:"Значит, ты наколдовал кошмаров на Пляже? Но почему?"};
tr[40478] = {OId:270,H:"У меня не получается сочинять весёлое! Даже Нюша говорит, что я тоскливый."};
