tr[40687] = {H:"Загляни в гости к Совунье!"};
tr[40688] = {OId:270,H:"Хо-хо! Кто это ко мне пожаловал?"};
tr[40689] = {H:"Это я! Очень хочется узнать, как поживает Совунья!"};
tr[40690] = {OId:270,H:"До сих пор хорошо поживала, но теперь начинаю беспокоиться..."};
tr[40691] = {H:"О чём беспокоиться? Я же ничего плохого не сделаю."};
tr[40692] = {OId:270,H:"Ты, может быть, и не сделаешь. А как же вирусы?"};
tr[40693] = {H:"Какие такие вирусы? У меня нет никаких вирусов!"};
tr[40694] = {OId:270,H:"Вот как! Может быть у тебя и справка имеется?"};
tr[40695] = {H:"Н-нет... И справки тоже нет..."};
tr[40696] = {OId:270,H:"Так дело не пойдёт. Я уже сова пожилая, нельзя ко мне без справки."};
tr[40697] = {H:"Где же мне эту справку взять?"};
tr[40698] = {OId:270,H:"Известно, где! Беги в Больничку к Доктору Бинтику!"};
tr[40699] = {H:"А если он выпишет справку, тогда я смогу к тебе в гости ходить?"};
tr[40700] = {OId:270,H:"Ну конечно, ещё и подарок от меня получишь!"};
tr[40701] = {H:"Ура! Уже бегу в Больничку!"};
tr[40702] = {OId:270,H:"Хо-хо! Сначала получи справку у доктора Бинтика, а потом приходи ко мне за подарком!"};
tr[40703] = {OId:270,H:"Здравствуйте! На что жалуетесь?"};
tr[40704] = {H:"Доктор, я ни на что не жалуюсь! Мне нужна справка."};
tr[40705] = {OId:270,H:"Но здесь же не справочное бюро. Это больница!"};
tr[40706] = {H:"Я знаю! Мне нужна справка, что у меня нет вирусов."};
tr[40707] = {OId:270,H:"Дайте-как, я угадаю! Вас ко мне отправила Совунья?"};
tr[40708] = {H:"Правильно! Она сказала, что у меня могут быть вирусы."};
tr[40709] = {OId:270,H:"Не скачивайте из интернета всякую ерунду и вирусов не будет."};
tr[40710] = {H:"Хм... Хорошо. Но можно мне всё-же получить эту справку?"};
tr[40711] = {OId:270,H:"Без обследования нельзя. Сначала надо сходить на рентген."};
tr[40712] = {H:"Круто! Уже бегу!"};
tr[40713] = {OId:270,H:"С результатом возвращайтесь ко мне."};
tr[40714] = {H:"Спасибо, доктор!"};
tr[40715] = {OId:270,H:"Сразу после обследования возвращайтесь ко мне за справкой!"};
tr[40716] = {H:"Коврик Кроша"};
tr[40717] = {H:"Пуфик " + "\"" + "Копатыч" + "\"" + ""};
tr[40718] = {H:"Футболка " + "\"" + "Крылья махаона" + "\"" + ""};
tr[40719] = {OId:270,H:"Уже закончили обследование?"};
tr[40720] = {H:"Да! Можете проверить диагноз."};
tr[40721] = {OId:270,H:"Позвольте взглянуть... Вирусов нет, поздравляю!"};
tr[40722] = {H:"А как же переутомление? Мне надо срочно бежать на пляж?"};
tr[40723] = {OId:270,H:"Не надо никуда бежать. Причина переутомления мне понятна."};
tr[40724] = {H:"Хотелось бы, чтобы она стала понятна и мне..."};
tr[40725] = {OId:270,H:"Это просто. Вы очень спешили ко мне от Совуньи и запыхались..."};
tr[40726] = {H:"Значит теперь я смогу получить справку?"};
tr[40727] = {OId:270,H:"Конечно! Идите и обрадуйте Совунью. Только не спешите!"};
tr[40728] = {H:"Спасибо, доктор! Пойду не спеша!"};
tr[40729] = {OId:270,H:"Хо-хо! Это снова ты? Какие новости?"};
tr[40730] = {H:"Совунья, у меня нет вирусов и есть справка от доктора!"};
tr[40731] = {OId:270,H:"Очень хорошо. Но здесь написано про переутомление..."};
tr[40732] = {H:"Бинтик сказал, что это от быстрого бега."};
tr[40733] = {OId:270,H:"Так я и думала. Тебе надо больше заниматься спортом."};
tr[40734] = {H:"А вот в диагнозе написано, что мне надо загорать на пляже!"};
tr[40735] = {OId:270,H:"Загорать на пляже, заниматься спортом и следить за здоровьем."};
tr[40736] = {H:"Понятно, но как-то сложно. И с чего же начать?"};
tr[40737] = {OId:270,H:"Начнём с главного! Никогда не выходи на улицу без шапки!"};
tr[40738] = {H:"Даже летом? Но, бабушка... Ой! Совунья..."};
tr[40739] = {OId:270,H:"И не спорь! Я как раз связала для тебя новую шапочку."};
tr[40740] = {H:"Спасибо... Теперь буду ходить в шапочке... Особенно летом..."};
tr[40741] = {OId:270,H:"Молодец! Кто молодец? Я молодец!"};
tr[40742] = {H:"Ещё раз спасибо, Совунья."};
tr[40743] = {OId:270,H:"Рецепт хорошего отдыха №23: устроиться в удобном кресле, взять любимые спицы и вязать, вязать, вязать..."};
