tr[40757] = {OId:270,H:"Жук и рак сошлись у речки..."};
tr[40758] = {H:"Привет, Бараш! Что ты хочешь этим сказать?"};
tr[40759] = {OId:270,H:"Жук и рак сошлись у речки разговаривать словечки..."};
tr[40760] = {H:"Ты же сочиняешь стихи! Ой, как интересно!"};
tr[40761] = {OId:270,H:"Выясняли, кто сильней... Тебе чего, незнакомый смешарик?"};
