tr[40763] = {OId:270,H:"Кхм... Только не мешай мне."};
tr[40764] = {H:"Я вовсе тебе не мешаю! Просто мне очень нравится твоя работа."};
tr[40765] = {OId:270,H:"Выясняли, кто сильней..."};
