tr[40767] = {OId:270,H:"Я так не могу! Ты же мне мешаешь сосредоточиться."};
tr[40768] = {H:"Но я же наоборот хочу помочь с рифмой!"};
tr[40769] = {OId:270,H:"Каждый думает, что это так легко... Хотя... Можем попробовать.."};
tr[40770] = {H:"Круто! Давай скорее пробовать!"};
