tr[41806] = {OId:270,H:"Ёжика рядом с тобой нет?"};
tr[41807] = {H:"Не-а, ты его здорово напугал! Да и на Кроша ты не похож."};
tr[41808] = {OId:270,H:"Эх, надо было нос красным покрасить! Так бы вы точно ни о чём не догадались..."};
tr[41809] = {H:"А ну говори, где настоящий Крош!"};
tr[41810] = {OId:270,H:"Л-ладно... только Ёжику ни слова! На самом деле, мы с Крошем друзья, и с ним всё хорошо... Кстати, меня зовут Акварик."};
tr[41811] = {H:"Хм..."};
tr[41812] = {OId:270,H:"В общем, мы решили поменяться друг с другом местами. Пока он занимается моими делами, я делаю вид, что занимаюсь его."};
tr[41813] = {H:"То есть ты просто притворяешься Крошем. А делами почему не занимаешься?"};
tr[41814] = {OId:270,H:"Я ничего здесь не знаю и не понимаю! Новые лица, новые вещи, новое ВСЁ! Но после встречи с тобой у меня появилась идея!"};
tr[41815] = {H:"Что-то я боюсь твоих идей..."};
tr[41816] = {OId:270,H:"Помоги мне выполнить все дела Кроша, а заодно покажешь тут всё. Поймаем двух зайцев сразу! А я тебе за это подарю ледяную морковку..."};
tr[41817] = {H:"Морковь? Ледяная? Годится!"};
tr[41818] = {H:"Морковь мне не нужна, но, так уж и быть, помогу! "};
