tr[41836] = {OId:678,H:"Какой загадочный господин. Я бы его каким-нибудь шпионом назначил."};
tr[41837] = {OId:677,H:"Агент007 к вашим услугам! Напали преступники? Проиграли в " + "\"" + "Секретики" + "\"" + "? Паранойя из-за слежки?"};
tr[41838] = {H:"Агент007, это Акварик. Крош попросил нас помочь тебе."};
tr[41839] = {OId:678,H:"Кажется, задание будет первостепенной важности."};
tr[41840] = {OId:677,H:"Так точно! Праздник на дворе, а Злобикус решил что-то задумать... Нужно помешать его пакостям! "};
tr[41841] = {H:"Так точно, Агент007. Приступаем к миссии!"};
tr[41842] = {OId:678,H:"Йо-хо-хо! Это же Капитан зелёная борода! Ещё и клешни! Да ты мне приходишься шестиюродным родственником по линии моей троюродной бабушки!"};
tr[41843] = {OId:677,H:"Быть такого не может, я живу на планете Зябра!"};
tr[41844] = {H:"Капитан Зюзель, мы пришли помочь вам выполнить задание!"};
tr[41845] = {OId:677,H:"Отлично! А то я один, а хлопот - целых три планеты! "};
tr[41846] = {H:"Давай поможем, возьмём с Аквариком какую-нибудь одну планету!"};
tr[41847] = {H:"Что-то много у тебя хлопот. Мы позже зайдём."};
tr[41848] = {OId:678,H:"Тысяча горбатых моллюсков! Это же настоящий пират! Вы, наверное, весь мир уже успели увидеть!"};
tr[41849] = {OId:677,H:"Разрази меня гром, какой любопытный! Да, много я плавал, много видел. Помню, как мы с командой решили отыскать клад Снежного смешарика..."};
tr[41850] = {H:"Джо Ворон! Мы очень торопимся, а Крош попросил помочь тебе в одном деле."};
tr[41851] = {OId:677,H:"Эх, юнги, вечно куда-то торопитесь. Но вы в другой раз приходите, у меня много историй."};
