tr[41859] = {OId:678,H:"У меня диета - вода со льдом да ледяная морковка."};
tr[41860] = {OId:677,H:"Э-кхе, Акварик, это же не еда совсем! Ты смотри, весь прозрачный почти! И как тебя вьюгой ещё не сдуло?"};
tr[41861] = {H:"Чудной ты. Давай поможем Совунье с её делом!"};
