tr[41864] = {OId:678,H:"Какой-то Вы задумчивый. Не получается создать философский камень?"};
tr[41865] = {OId:677,H:"Один из учеников школы магов потерял мою книгу заклинаний. И теперь я пытаюсь вспомнить рецепт волшебного зелья..."};
tr[41866] = {H:"Умникус, совсем-совсем не помнишь ингредиенты?"};
tr[41867] = {OId:677,H:"Хм, дай-ка подумать... " + "\"" + "В чан добавьте водоросли, щепотку смелости..." + "\"" + ". Ещё что-то было. Ах, да! Ещё смешать эликсиры!"};
tr[41868] = {H:"Ну-ка, что за эликсиры? Давай приготовим это зелье!"};
tr[41869] = {H:"А что за зелье должно получиться?"};
tr[41870] = {OId:677,H:"" + "\"" + "Зелье от рычания под Луной" + "\"" + ". Сумрак попросил, а то его соседи жалуются."};
