tr[41873] = {OId:270,H:"Крош должен скоро прийти. Чем займёмся, пока его ждём?"};
tr[41874] = {H:"Не хочешь поговорить? А то у меня вопросов накопилось..."};
tr[41875] = {OId:270,H:"Вопросы! Вопросы! Я обожаю вопросы! Что тебя интересует?"};
tr[41876] = {H:"Где ты нашёл такой костюм?"};
tr[41877] = {H:"Как ты познакомился с Крошем?"};
tr[41878] = {H:"Кто же ты такой?"};
tr[41879] = {OId:270,H:"Да мне Крош одолжил и сказал, что взял его у Копатыча... Немного подлатать, правда, пришлось, а то уши вечно отваливались. Что, совсем не похож?"};
tr[41880] = {H:"Почти один в один! У меня к тебе ещё вопросы..."};
tr[41881] = {OId:270,H:"На рыбалке мы познакомились, точнее Крош выловил меня из моря. А там и разговорились, ну и такую шутку придумали, чтобы я вместо Кроша все дела его сделал! "};
tr[41882] = {H:"Шуточки у вас, конечно... У меня к тебе есть ещё вопросы..."};
tr[41883] = {OId:270,H:"Трудно сказать. Дело в том, что я заколдован. Хочешь узнать, что произошло? Предупреждаю, история длинная!"};
tr[41884] = {H:"Погоди, у меня остались ещё вопросы..."};
tr[41885] = {H:"Заколдован? Ну и ну! Расскажи, как так вышло!"};
