tr[42330] = {H:"Аксессуар-фонарик"};
tr[42331] = {OId:270,H:"Говоришь, чините старый дирижабль? Может, и я смогу чем-то помочь."};
tr[42332] = {H:"Не знаешь, где можно взять топливо для дирижабля?"};
tr[42333] = {OId:270,H:"Лягушку мне в колбу! Топливо - это очень неэкологично и совсем не по-нашему. "};
tr[42334] = {H:"А как ещё взлететь на дирижабле?"};
tr[42335] = {OId:270,H:"Я же волшебник. Вместо топлива можно использовать заклинание!"};
tr[42336] = {H:"Отличная идея!"};
tr[42337] = {H:"Роза|Роза появится через {0} мин."};
tr[42338] = {H:"Ромашка|Ромашка появится через {0} мин."};
tr[42339] = {H:"Пион|Пион появится через {0} мин."};
tr[42340] = {OId:681,H:"И что нам делать теперь с этой бандура?"};
tr[42341] = {OId:682,H:"Как что? Лететь в облачную страну!"};
tr[42342] = {H:"Думаю, для дирижабля нужно найти место повыше."};
tr[42343] = {OId:682,H:"Друг мой смышлённый, а это хорошая идея! Но где?"};
tr[42344] = {H:"Предлагаю в Дремучем лесу!"};
tr[42345] = {H:"Предлагаю на Снежной горе!"};
tr[42346] = {H:"Предлагаю в Каньоне!"};
tr[42347] = {OId:681,H:"Найн! Там же деревья!"};
tr[42348] = {OId:682,H:"Верно, нужно найти другое место."};
tr[42349] = {H:"Хм, дайте-ка подумать ещё."};
tr[42350] = {OId:682,H:"Прекрасная идея! Самая высокая и удобная точка. Отправляемся туда!"};
tr[42351] = {H:"Отлично!"};
tr[42352] = {OId:682,H:"В Каньоне слишком опасно - там много злобырей!"};
tr[42353] = {H:"И правда. Подумаю ещё."};
tr[42354] = {OId:270,H:"Эх, Пин сказал, что у него ещё куча дел. С нами он не полетит. Но мы справимся!"};
tr[42355] = {H:"Не боишься высоты?"};
tr[42356] = {OId:270,H:"Бабочки высот не боятся!"};
tr[42357] = {H:"Справедливо."};
tr[42358] = {OId:270,H:"Давай разберёмся с навигацией. Кликни на дирижабль!"};
tr[42359] = {H:"Хорошо."};
tr[42360] = {OId:270,H:"Ещё гости? Хватит с нас! Мы с этими хулиганами пока не разобрались, а сюда кто-то новый уже прилетел!"};
tr[42361] = {H:"Мы хорошие! А это злобыри, они и у нас пакостят!"};
tr[42362] = {OId:270,H:"Эти ваши " + "\"" + "злобыри" + "\"" + " сеют хаос и пугают жителей. Из-за этого Аэрополис погрузился во мрак."};
tr[42363] = {H:"Как мы можем вам помочь? "};
tr[42364] = {OId:270,H:"Видишь ли, погодные условия в Аэрополисе зависят от настроения обитателей страны."};
tr[42365] = {H:"Значит, их нужно как-то развеселить!"};
tr[42366] = {OId:270,H:"Именно! Также, моё собственное расследование показало, что монстры не любят хорошую погоду. Даю тебе задание - развесели жителей."};
tr[42367] = {H:"Будет сделано! Лосяш, а ты тоже помоги жителям!"};
tr[42368] = {OId:683,H:"Хм... Мы с новым знакомым подумаем"};
tr[42369] = {H:"Хорошо! Приступаем к задаче!"};
tr[42370] = {OId:683,H:"Друг мой любознательный, помоги жителям Аэрополиса! "};
tr[42371] = {OId:270,H:"Помоги поднять настроение жителям Аэрополиса!"};
tr[42372] = {OId:270,H:"Спасибо, что помог прогнать злобырей и вернуть хорошую погоду! Теперь в Аэрополисе всегда солнечно! "};
tr[42373] = {H:"Отлично! "};
