tr[42775] = {OId:270,H:"Помоги Аэрополису! Кликни на Шефа за подробностями!"};
tr[42776] = {OId:270,H:"Агент, немедленно приступай к миссии!"};
tr[42777] = {OId:270,H:"Эх, никакого праздника. А мы так хотели всех обрадовать! "};
tr[42778] = {OId:270,H:"Пока у меня ещё есть силы удерживать, но тебе срочно нужно найти причину поломки!"};
tr[42779] = {H:"Ты не замечал ничего странного?"};
tr[42780] = {OId:270,H:"Кроме этих роботов - ничего. Помоги скорее разобраться с причинами! "};
tr[42781] = {H:"Будет сделано!"};
tr[42782] = {OId:686,H:"Фух, я смог взломать систему и обездвижить одну робозвезду."};
tr[42783] = {H:"Отлично!"};
tr[42784] = {OId:686,H:"Но я не могу их починить. Вначале нужно узнать причину поломки."};
tr[42785] = {H:"Ты не замечал что-то странное помимо сумасшедших роботов? "};
tr[42786] = {H:"Давай лучше расследованием займётся Жёлтый клюв. "};
tr[42787] = {OId:686,H:"На нашей площади я заметил странное перо. Оно не похоже на те, что у жителей Аэрополиса."};
tr[42788] = {H:"Возможно, это и есть улика! Спасибо!"};
tr[42789] = {OId:686,H:"Перо принадлежит Злобикусу? Это очень любопытно... Что будете делать дальше?"};
tr[42790] = {H:"Узнаем у Умникуса подробности!"};
tr[42791] = {H:"Ну, лично я пойду заниматься своими делами, а вы там дальше сами."};
tr[42792] = {OId:686,H:"А вы нашли третью робозвезду? На медведя похож."};
tr[42793] = {H:"Я и забыл про него... А он очень хорошо спрятался!"};
tr[42794] = {OId:686,H:"Будьте аккуратнее, в таком состоянии он очень опасен!"};
tr[42795] = {H:"Мы - агенты! Нам нечего бояться."};
tr[42796] = {OId:270,H:"Агент, продолжай поиски! Допроси Умникуса в Школе Магов!"};
tr[42797] = {OId:270,H:"Узнаю перо своего брата. Но зачем ты мне его показываешь?"};
tr[42798] = {H:"В Аэрополисе сошли с ума роботы, а это единственная подозрительная улика!"};
tr[42799] = {OId:270,H:"Нам надо это проверить, но для этого нужно проникнуть в замок Злобикуса."};
tr[42800] = {H:"И как это сделать?"};
tr[42801] = {OId:270,H:"Магия, мой друг. Магия всё решает."};
tr[42802] = {H:"Это уж точно!"};
tr[42803] = {H:"Эй, а я думал, что технологии."};
tr[42804] = {OId:270,H:"С технологиями ты бы сейчас потерял кучу времени, чтобы проникнуть в замок Злобикуса. Но с магией ты это сейчас сделаешь в один щелчок."};
tr[42805] = {H:"Что-то я и не подумал..."};
tr[42806] = {OId:270,H:"Чего ждёшь?! Нужно как можно быстрее раскрыть дело!"};
tr[42807] = {OId:270,H:"Агент, продолжай поиски! Найди способ починить робозвёзд!"};
tr[42808] = {OId:686,H:"Что-то я не вижу у тебя способа починить робозвёзд!"};
tr[42809] = {OId:270,H:"Рр-рр, что здесь делает чужак?"};
tr[42810] = {H:"Говори, где Злобикус, и что он сделал с робозвёздами!"};
tr[42811] = {OId:270,H:"Робо-кто? Ты где такие слова выучил?! Я тебе ничего не скажу!"};
tr[42812] = {H:"И не надо. Я сам тогда всё найду."};
tr[42813] = {OId:270,H:"Ты ничего не найдёшь! Иди туда, куда шёл!"};
tr[42814] = {H:"Ну, нет! Я Агент, у меня специальный значок есть."};
tr[42815] = {OId:270,H:"Бла-бла, мне не интересно, что у тебя там есть."};
tr[42816] = {H:"У меня есть право осмотреть это место!"};
tr[42817] = {OId:678,H:"Ну, и что это было?!"};
tr[42818] = {OId:677,H:"Это всё Злобикус! Это он загипнотизировал ваших робозвёзд!"};
tr[42819] = {H:"И зачем?"};
tr[42820] = {OId:677,H:"Робозвёзды должны напугать и выселить жителей Аэрополиса. Злобикусу нужно больше территорий для своей армии! А нам больше мест для пакостей! Вам всё равно его не победить!"};
tr[42821] = {H:"Это мы ещё посмотрим..."};
tr[42822] = {H:"Да мы его постоянно побеждаем. И сейчас победим!"};
tr[42823] = {OId:678,H:"Больше ничего интересного мы от Чудика не узнаем. Найди книгу заклинаний. Там должно быть противоядие!"};
tr[42824] = {H:"Так точно!"};
tr[42825] = {OId:678,H:"Найди книгу заклинаний и дай её мне!"};
tr[42826] = {H:"Цветок|Цветок расцветёт через {0} мин."};
tr[42827] = {H:"Звезда|Звезда приползёт через {0} мин."};
tr[42828] = {OId:270,H:"Агент, это прорыв! Нет... Рывок! Теперь избавь робозвёзд от гипноза!"};
tr[42829] = {OId:270,H:"Сдавайся, Агент. У тебя ничего не выйдет. Робозвёзды находятся под моим контролем."};
tr[42830] = {H:"Это не так! Мы уже расколдовали Овли и Кроки!"};
tr[42831] = {OId:270,H:"Что?! Я же испортил бумажку с заклинанием! Как ты смог их расколдовать?!"};
tr[42832] = {H:"Я просто исправил ошибки в бумажке..."};
tr[42833] = {OId:270,H:"А ты умный Смешарик. Предлагаю поединок! "};
tr[42834] = {H:"Ну, давай!"};
tr[42835] = {H:"Гардероб " + "\"" + "Уютный дом" + "\"" + ""};
tr[42836] = {H:"Фон " + "\"" + "Геометрия" + "\"" + ""};
