tr[42840] = {H:"Шляпа Жёлтого клюва"};
tr[42841] = {H:"Плащ секретного агента"};
tr[42842] = {OId:685,H:"Так-так. Кто это у нас тут снова пытается нарушить мои планы?"};
tr[42843] = {H:"Ой... Да я тут... это... мимо просто проходил!"};
tr[42844] = {OId:685,H:"Мои слуги следили за каждым твоим шагом. Тебе это с рук не сойдёт, помощничек Шефа. Хе-хе."};
tr[42845] = {H:"Это тебе не сойдут пакости с крыльев!"};
tr[42846] = {OId:685,H:"А ты дерзок. Можешь оставить свои мечты о спасении Аэрополиса. Робозвёзды под гипнозом отлично справляются со своими обязанностями."};
tr[42847] = {H:"Это ненадолго, Злобикус!"};
tr[42848] = {OId:685,H:"Аэрополис всё равно будет моим!"};
tr[42849] = {H:"Стой!"};
tr[42850] = {H:"Я помог Шефу раскрыть дело в Аэрополисе! Заходи в Шарарам за приключениями и ты!"};
