tr[43400] = {H:"Открой свой собственный клуб!|Пригласи популярных артистов!|Жди в гости весёлых Смешариков!"};
tr[43401] = {H:"Фартук барбера"};
tr[43402] = {H:"Кресло " + "\"" + "Сочный ананас" + "\"" + ""};
tr[43403] = {H:"Кломпы " + "\"" + "Голландия" + "\"" + ""};
tr[43404] = {H:"Причёска " + "\"" + "Полярность" + "\"" + ""};
tr[43405] = {OId:270,H:"Найди всех магов в Шарараме и узнай об их способностях!"};
tr[43406] = {OId:17,H:"Лунный камень|Лунный камень зарядится через {0} мин."};
tr[43407] = {OId:707,H:"Грибы и лягушки, да лесные зверушки! Приготовим всем зелья со вкусом варенья! "};
tr[43408] = {H:"Сову... Ой, то есть, Колдовунья, что ты делаешь?"};
tr[43409] = {OId:707,H:"Перед тобой ведьма в седьмом поколении! О моих зельях ходят легенды. Все эликсиры, которые ты встречал, приготовлены лично мной по секретным рецептам! "};
tr[43410] = {H:"Круто! Я тоже хочу научиться варить зелья!"};
tr[43411] = {OId:270,H:"Вижу я, что придёт ко мне скоро кто-то круглый... Спрашивать что-то будет... Явись же ко мне! "};
tr[43412] = {H:"А вот и я!"};
tr[43413] = {OId:270,H:"Вот он, кого я увидела в чайной гуще! Вижу я... что знать о секретах моих способностей хочешь!  "};
tr[43414] = {H:"Очень хочу! Как ты поняла, что я круглый?"};
tr[43415] = {OId:270,H:"Тише! Духи говорят со мной... Хотят проверить твои способности..."};
tr[43416] = {H:"Ух, надо попробовать!"};
tr[43417] = {OId:270,H:"Тсс... Тише, иначе луковицы снова разбегутся!"};
tr[43418] = {H:"(Шёпотом) Хорошо, я просто хочу посмотреть, чем ты занимаешься."};
tr[43419] = {OId:270,H:"Чтобы поймать Прыгучих луковиц, нужно думать, как луковица. Вот я и вливаюсь в образ, так сказать!"};
tr[43420] = {H:"(Шёпотом) Круто! Я могу чем-нибудь помочь?"};
tr[43421] = {OId:270,H:"Ну, вот! Я хотел рассказать про Древние руны, но они не хотят мне подчиняться! "};
tr[43422] = {H:"Древние руны? Что-то сложное и непонятное..."};
tr[43423] = {OId:270,H:"Это на первый взгляд! На самом деле, это очень интересно! Давай ты мне поможешь их зарядить, чтобы они работали?"};
tr[43424] = {H:"Ого... Ну, давай!"};
tr[43425] = {OId:707,H:"Если ты слышишь шипение и свист из своего котла, то не время паниковать! Просто беги как можно дальше оттуда. "};
tr[43426] = {OId:707,H:"У эликсира тоже есть чувства! Напой ему весёлую мелодию, и твоё зелье забурлит от восторга!"};
tr[43427] = {OId:707,H:"Пока я не забыла, записывай рецепт эликсира бодрости: молоко, какао, зефирки. Всё это подогреть в микроволновке... Вжух! Готово!"};
tr[43428] = {OId:270,H:"Не забудь про необычный костюм! Тогда твои пророчества получатся ещё загадочнее!"};
tr[43429] = {OId:270,H:"Хм... Посмотрим на наше будущее. Башня? Ой, не та карта, перепутала. Лучше её не использовать при гадании."};
tr[43430] = {OId:270,H:"Если магический шар не светится, то просто попробуй подключить его шнур к розетке. У меня всегда так работало..."};
tr[43431] = {OId:270,H:"Главное правило клуба Фокусников - никогда не раскрывать тайны фокусов. Но сегодня это правило я нарушу для тебя..."};
tr[43432] = {OId:270,H:"Не повторяй один и тот же фокус дважды, иначе зрителям станет скучно!"};
tr[43433] = {OId:270,H:"Добавляй слова " + "\"" + "Сим-салабим" + "\"" + " и " + "\"" + "Абракадабра" + "\"" + ", чтобы вызвать у зрителей яркие эмоции от представления!"};
tr[43434] = {OId:270,H:"Прыгучие луковицы могут достигать размеров с дверной проём! В таком случае нужно произнести заклятие " + "\"" + "Уменьшариус" + "\"" + ", и тогда их можно будет поймать!"};
tr[43435] = {OId:270,H:"Трын-трава — очень полезное растение. Оно используется во многих лечебных отварах, а его цветки на вкус напоминают клубнику."};
tr[43436] = {OId:270,H:"Говорящие мандрагоры просто милашки! Если ты им понравился, то они готовы говорить с тобой без умолку! "};
tr[43437] = {OId:270,H:"Всего известно 4 магических вида рун: зябрийские, египетские, руны древних магов и злобырьские. У каждого из вида рун свой шифр."};
tr[43438] = {OId:270,H:"Древние руны нужны, чтобы расшифровывать древние книги и заклинания. В Школе Магов переводом с Древних рун занимаемся я и Умникус, чтобы вам было проще осваивать магию!"};
tr[43439] = {OId:270,H:"Первые руны изобрёл верховный маг Шарарама - отец Умникуса и Злобикуса. Магический шар, который хранится у Умникуса, зачарован Древними рунами, поэтому открыть волшебный портал может только тот, кто знает этот язык."};
tr[43440] = {H:"Магия " + "\"" + "Злобный Джинн" + "\"" + ""};
tr[43441] = {H:"Глаза " + "\"" + "Роковой взгляд" + "\"" + ""};
tr[43442] = {H:"Колпак светлого мага"};
tr[43443] = {H:"Очки волшебника"};
tr[43444] = {H:"Мантия светлого мага"};
tr[43445] = {H:"Аксессуар " + "\"" + "Волшебная палочка" + "\"" + ""};
tr[43446] = {H:"Аксессуар " + "\"" + "Бузинная палочка" + "\"" + ""};
tr[43447] = {H:"Колпак тёмного мага"};
tr[43448] = {H:"Мантия тёмного мага"};
tr[43449] = {OId:708,H:"Секретные Агенты обнаружили Злобного Джинна, когда тот хотел превратить магов в лягушек. А я им помог и заточил Джинна в магическое зеркало! Поговори с ним."};
tr[43450] = {H:"Джинн, что ты задумал?"};
tr[43451] = {H:"Джинн, ты же правда можешь исполнить любое желание?"};
tr[43452] = {OId:709,H:"Я не собираюсь вам ничего рассказывать. Всё равно скоро вашей Магической конференции придёт конец."};
tr[43453] = {H:"Хм, надо придумать к Джинну другой подход."};
tr[43454] = {OId:709,H:"Гхм, да, правда... Но у тебя одна попытка. "};
tr[43455] = {H:"Я желаю, чтобы ты рассказал мне, зачем ты превращаешь магов в лягушек."};
tr[43456] = {H:"Я желаю, чтобы у меня было миллион желаний!"};
tr[43457] = {OId:709,H:"Желание любого - закон. Тёмные маги, в том числе и я, хотят испортить вам праздник. Скоро у нас начнётся собрание в замке Злобикуса. Мы вам устроим настоящее веселье, хе-хе-хе."};
tr[43458] = {H:"Кошмар! Что нам делать, Умникус?"};
tr[43459] = {OId:709,H:"Так нельзя. Загадывай что-нибудь более реальное."};
tr[43460] = {H:"Эх, так бы я столько всего назагадывал..."};
tr[43461] = {OId:708,H:"Есть у меня мысль. Мы превратим тебя в клона Джинна с помощью заклинания. Ты проберёшься в замок Злобикуса и выяснишь, что произошло. Магическая операция " + "\"" + "Клонириум" + "\"" + " начинается!"};
tr[43462] = {H:"Так точно!"};
tr[43463] = {OId:270,H:"Нет времени объяснять! Иди ко мне в Тайную комнату! Кликни на иконку, чтобы телепортироваться."};
tr[43464] = {H:"Причёска " + "\"" + "Упавшая пальма" + "\"" + ""};
tr[43465] = {H:"Рубашка " + "\"" + "Морская звезда" + "\"" + ""};
tr[43466] = {H:"Кеды " + "\"" + "Водоросли" + "\"" + ""};
tr[43467] = {H:"Браслеты " + "\"" + "На память" + "\"" + ""};
tr[43468] = {H:"Причёска " + "\"" + "Вишенки" + "\"" + ""};
tr[43469] = {H:"Хаори " + "\"" + "Традиции" + "\"" + ""};
tr[43470] = {H:"Гэта " + "\"" + "Традиции" + "\"" + ""};
tr[43471] = {H:"Заколка " + "\"" + "Красный бархат" + "\"" + ""};
tr[43472] = {H:"Причёска " + "\"" + "Курьер" + "\"" + ""};
tr[43473] = {H:"Куртка " + "\"" + "Курьер" + "\"" + ""};
tr[43474] = {H:"Сапожки " + "\"" + "Курьер" + "\"" + ""};
tr[43475] = {H:"Курьерская термосумка"};
tr[43476] = {OId:270,H:"Стой! Кто идёт? И что Вы тут, собсна, забыли?"};
tr[43477] = {H:"Я Злобный Джинн, у-у-у! Пришёл на собрание тёмных магов!"};
tr[43478] = {OId:270,H:"Ой, как интересно! Но нужен пароль. Сами понимаете, дело секретное!"};
tr[43479] = {H:"Да-а-а. Сейчас, я его на бумажке записывал..."};
tr[43480] = {H:"Фуршетный стол с фруктами"};
tr[43481] = {H:"Очки " + "\"" + "Ясный взгляд" + "\"" + ""};
tr[43482] = {OId:270,H:"Ну и чего стоишь? Проходи!"};
tr[43483] = {OId:701,H:"Друзья мои! Все же в курсе, зачем мы собрались?"};
tr[43484] = {OId:703,H:"Да! Добрые маги решили устроить праздник и не пригласили нас!"};
tr[43485] = {OId:704,H:"Это просто возмутительно! Я нашлю на них песчаную бурю!"};
tr[43486] = {H:"..."};
tr[43487] = {OId:701,H:"А знаете, почему они так поступили? Они говорят, что это из-за наших проделок в Шарараме! Но тёмная магия тоже же может быть полезна для Смешариков!"};
tr[43488] = {OId:705,H:"Несправедливо! Надо бы их проучить!"};
tr[43489] = {OId:706,H:"Надо им за это напакостить! Я превращу их за это в пиявок!"};
tr[43490] = {H:"Да! Надо их проучить!"};
tr[43491] = {OId:701,H:"Зачем так радикально? Я предлагаю поговорить с Умникусом и рассказать ему о наших новинках в тёмной магии!"};
tr[43492] = {OId:703,H:"И мы просто их... простим? Я не хочу оставлять это безнаказанным!"};
tr[43493] = {OId:705,H:"Звучит разумно... Они всегда идут нам навстречу."};
tr[43494] = {H:"Очень хорошая идея! Поддерживаю!"};
tr[43495] = {OId:702,H:"МОЛЧАТЬ! Как же вы не понимаете? Они специально нас не пригласили, а ты, Злобикус, просто хочешь спустить им это с лап? Я не ожидал от тебя такого, мой ученик."};
tr[43496] = {OId:703,H:"Именно!"};
tr[43497] = {OId:706,H:"Точно!"};
tr[43498] = {OId:704,H:"Вот-вот!"};
tr[43499] = {H:"..."};
tr[43500] = {OId:702,H:"Мне надоело, что тёмные маги постоянно проигрывают, нас постоянно высмеивают и выставляют крайними. Сколько можно это терпеть? Нам нужно действовать здесь и сейчас!"};
tr[43501] = {OId:701,H:"Я не согласен..."};
tr[43502] = {OId:705,H:"Злобикус, дай дослушать!"};
tr[43503] = {H:"..."};
tr[43504] = {OId:702,H:"Пора показать тёмную магию с её главной стороны! Захватим Шарарам! Украдём, наконец-то, магический шар Умникуса! Покажем, кто здесь настоящая сила!"};
tr[43505] = {OId:704,H:"Веди нас, Титан!"};
tr[43506] = {OId:705,H:"Да! Наша магия ничем не хуже!"};
tr[43507] = {OId:703,H:"Давно пора, Титан! Переговоры Злобикуса ни к чему не приведут!"};
tr[43508] = {H:"Ура?!"};
tr[43509] = {OId:701,H:"Погодите! Я чувствую, что здесь кто-то использует силы доброй магии. Кажется, тут есть шпион!"};
tr[43510] = {OId:702,H:"КТО ПОСМЕЛ?!"};
tr[43511] = {H:"Ой..."};
tr[43512] = {OId:380,H:"Магический шар у меня, и ты с этим уже ничего не сделаешь!"};
tr[43513] = {H:"Это мы ещё посмотрим!"};
tr[45371] = {OId:150,H:"Вот мы и поймали вас! "};
tr[45372] = {H:"Значит, вы тоже хотите поделиться со Смешариками своей магией?"};
tr[45373] = {OId:580,H:"Да! Нам тоже есть, что показать"};
tr[45374] = {H:"Умникус, давай простим магов! Мне интересно, что они хотят показать нам! "};
tr[45375] = {OId:150,H:"Ладно, ладно, уговорили. Только, чур, без злодейских штучек! А за помощь, Смешарик, ты получишь награду! Не забудь потом прогуляться по разным местам Шарарама и послушать интересные советы от тёмных магов!"};
tr[45376] = {OId:580,H:"Ура! "};
tr[45377] = {H:"Ура!"};
tr[45378] = {H:"Спутник " + "\"" + "Злобный Джинн" + "\"" + ""};
tr[45379] = {H:"Домик " + "\"" + "Тайная комната Злобикуса" + "\"" + ""};
tr[45380] = {H:"Я спас Магическую конференцию от злых магов! Заходи и ты!"};
tr[45381] = {OId:270,H:"Любишь пыль и грязь? Тогда тебе отлично подойдут Марашки, уа-ха-ха. Эти пушистики обожают поддерживать " + "\"" + "непорядок" + "\"" + ". А ещё они любят пачкать одежду и мусорить в Шарараме!"};
tr[45382] = {OId:270,H:"У меня есть свои воины! Вот они слева-направо: Шмяк, Грох и Горюн. Этих любимчиков я кормлю болотной жижей, а спят они на подушке с сон-травой. "};
tr[45383] = {OId:270,H:"Монстрик - мой главный помощник,только очень любопытный! Вы постоянно его прогоняете в Шарараме! Будьте добрее, в конце концов, он ничего плохого не делает!"};
tr[45384] = {OId:270,H:"Зазеркалье хоть и кажется полной копией настоящего мира, но эта реальность очень искажена. Чем дольше находишься в Зазеркалье – тем больше это замечаешь."};
tr[45385] = {OId:270,H:"Все доверяют зеркалам, хе-хе... Очень зря! Именно зеркало видит истинное лицо Смешарика и может раскрыть все его тайны. Ещё никому не удавалось обмануть зеркала. Даже мне."};
tr[45386] = {OId:270,H:"Как попасть в Зазеркалье? Ну и вопросы, малец! В этот мир можно попасть только через зеркала, которые сделаны лично мной! Ты всегда можешь найти их в моём шатре. Буду ждать тебя в гости, хе-хе-хе!.."};
tr[45387] = {OId:270,H:"Все египтяне должны слушаться меня и только меня. А за неповиновение я насылаю на них пустынную лихорадку. Слушайся меня тоже, если не хочешь заболеть!"};
tr[45388] = {OId:270,H:"Моя сила заключается в управлении погодой. Это не так-то просто. Для контроля такой силы требуется крепкая выдержка. Хорошо, что я умничка."};
tr[45389] = {OId:270,H:"Я хоть и Бог Египта, но иногда мне просто лень помогать египтянам с погодой, поэтому вместо меня это делают Песчанки! Только тс-с-с!"};
tr[45390] = {H:"Портрет Желтого Клюва"};
tr[45391] = {H:"Портрет Умникуса"};
tr[45392] = {H:"Портрет Злобикуса"};
tr[45393] = {OId:711,H:"Несмеян хитрый, но мой фокус с появлением заклинания на зеркале получился ещё хитрее!"};
tr[45394] = {OId:710,H:"Всё же не зря я столько времени рунам посвятил!"};
tr[45395] = {OId:713,H:"Ловко мы эту ведьму! Зелья с трын-травой всегда действуют безотказно!"};
tr[45396] = {OId:712,H:"Карты меня ещё никогда не обманывали!"};
