tr[45790] = {H:"Плохо то, что для этого он украл наши ёлочные игрушки!"};
tr[45791] = {OId:270,H:"Но ведь на них наложено заклятие счастливого Нового года! Без него ёлочка не загорится, а Новый год не придёт в Шарарам!"};
tr[45792] = {H:"Подскажи, как мне попасть к Злобикусу и забрать игрушки?"};
tr[45793] = {OId:270,H:"У меня есть специальное заклинание, но записано оно таким почерком, что сам не могу разобрать. Поможешь?"};
tr[45794] = {H:"Давай попробуем!"};
tr[45795] = {OId:270,H:"Ла-ла-ла, новогодние игрушки, свечи и хлопушки! Ой... Привет! "};
tr[45796] = {H:"Учишься вокалу, Коттер?"};
tr[45797] = {OId:270,H:"У нас беда! Злобикус планирует украсть Новый год..."};
tr[45798] = {OId:270,H:"Ха-ха! Сейчас превращу тебя в лягушку, вот и посмеёмся. Так что случилось?"};
tr[45799] = {H:"Случилась беда! Злобикус хочет украсть Новый год!"};
tr[45800] = {OId:270,H:"Какой ужас! Тот, чьё имя не нужно называть, опять портит нам праздник? Ты уже разговаривал с Умникусом?"};
tr[45801] = {H:"Он отправил меня к тебе, чтобы узнать, почему не работает заклинание телепортации."};
tr[45802] = {OId:270,H:"Да-да, что-то такое волшебное мы создавали... Это заклинание не может работать без волшебной пыльцы."};
tr[45803] = {H:"И где мне найти эту пыльцу?"};
tr[45804] = {OId:270,H:"И чего тебе от меня надо? Не видишь, что у нас тут праздник?"};
tr[45805] = {H:"Злобикус, мне надо с тобой поговорить! Срочно!"};
tr[45806] = {OId:270,H:"Мы и так уже говорим. Сегодня я без настроения, а это значит, что просто так тратить время на тебя не буду."};
tr[45807] = {H:"Так давай я тебе настроение подниму!"};
tr[45808] = {OId:270,H:"У тебя это не получится. Хотя... Отгадаешь три мои загадки?"};
tr[45809] = {H:"Попробую!"};
tr[45810] = {OId:270,H:"Кто является символом 2025 года?"};
tr[45811] = {H:"Змея"};
tr[45812] = {H:"Дракон"};
tr[45813] = {H:"Бык"};
tr[45814] = {OId:270,H:"Ответ неверный, мха-ха-хах! "};
tr[45815] = {H:"Я попробую ещё раз!"};
tr[45816] = {OId:270,H:"Что весит больше: килограмм пушистого снега или килограмм твёрдых сосулек?"};
tr[45817] = {H:"Пушистый снег"};
tr[45818] = {H:"Одинаково весят"};
tr[45819] = {H:"Твёрдые сосульки"};
tr[45820] = {OId:270,H:"А вот и неправильно, бу-га-га! "};
tr[45821] = {H:"Декабрь"};
tr[45822] = {H:"Январь"};
tr[45823] = {H:"Февраль"};
tr[45824] = {OId:270,H:"Ну ты даёшь! Это неправильно!"};
tr[45825] = {H:"Можно я попробую ещё раз?!"};
tr[45826] = {OId:270,H:"В Новый год поднимется над Шарарамом мрак, Дедом Морозом в этому году будет...!"};
tr[45827] = {H:"Так нечестно! Это уже четвёртая загадка!"};
tr[45828] = {H:"Тёмный маг?"};
tr[45829] = {OId:270,H:"Назови мне первый месяц зимы!"};
tr[45830] = {H:"Подарки под ёлку"};
tr[45831] = {H:"Игрушка " + "\"" + "Змейка" + "\"" + ""};
tr[45832] = {H:"Новогодний носок"};
tr[45833] = {H:"Тапочки " + "\"" + "Змейки" + "\"" + ""};
tr[45834] = {H:"Стеклянный шар " + "\"" + "Змейка" + "\"" + ""};
tr[45835] = {H:"Чалма " + "\"" + "Заклинатель" + "\"" + ""};
tr[45836] = {H:"Новогодний плащ"};
tr[45837] = {H:"Новогодний фонарик " + "\"" + "Ёлочка" + "\"" + ""};
tr[45838] = {H:"Домик " + "\"" + "Северное сияние" + "\"" + ""};
tr[45839] = {OId:270,H:"Хо-хо, привет! С наступающим тебя! А я как раз иду из Экомаркета, покупала картошечку для ухи по-новогоднему рецепту."};
tr[45840] = {H:"Ты собралась готовить уху? Тогда я по адресу!"};
tr[45841] = {OId:270,H:"Так чегось случилось? Рассказывай Совунье."};
tr[45842] = {H:"Злобикус хочет украсть у нас Новый год. "};
tr[45843] = {OId:270,H:"Ай, ворон окаянный! Чем я могу помочь, чтобы спасти праздник?"};
tr[45844] = {H:"Прозвучит странно, но мне нужны рыбьи косточки!"};
tr[45845] = {OId:270,H:"Приветики! А чего это мы такие тревожные и не нарядные? Что-то стряслось?"};
tr[45846] = {H:"Эллис, некогда объяснять! Очень нужен пушистый мех!"};
tr[45847] = {OId:270,H:"Искусственный пушистый мех? Так, где-то был! Мы как раз недавно шили стильные зимние шубки."};
tr[45848] = {H:"Я могу его взять? "};
tr[45849] = {OId:270,H:"Конечно, я ведь лиса совсем не жадная. Только вот обрезки меха нужно поискать..."};
tr[45850] = {H:"Спасибо!"};
tr[45851] = {OId:270,H:"Ура, Новый год наступает! Мы с Крошем уже написали письмо Дедушке Морозу, а ты?"};
tr[45852] = {H:"Да погоди, Ёжик, с этим письмом! Злобикус хочет украсть Новый год!"};
tr[45853] = {OId:270,H:"Плохи дела! Я могу тебе чем-то помочь?"};
tr[45854] = {H:"Да, мне нужен какой-нибудь очень колючий кактус. Можешь ли ты мне его подарить?"};
tr[45855] = {OId:270,H:"Ой, у меня столько кактусов... Ради такого дела – конечно, подарю!"};
tr[45856] = {H:"Спасибо!"};
tr[45857] = {OId:270,H:"Друг мой торопливый, куда Вы так спешите?"};
tr[45858] = {H:"Лосяш, я же знаю, что ты очень любишь электронику!"};
tr[45859] = {OId:270,H:"Да, я же признанный компьютерный гений! А что стряслось?"};
tr[45860] = {H:"Чтобы нарушить коварный план Злобикуса, мне нужно что-нибудь электронное! Может, у тебя есть такое?"};
tr[45861] = {OId:270,H:"Феноменально! Мы не дадим Злобикусу испортить Новый год! Давай поищем какой-нибудь старый чип."};
tr[45862] = {H:"Давай."};
tr[45863] = {OId:270,H:"Таки, здравствуйте, уважаемый! Чего надобно?"};
tr[45864] = {H:"Хочу Новый год для тебя устроить, Симон!"};
tr[45865] = {OId:270,H:"Новый год? Таки, для меня? Ой, как неожиданно и приятно!"};
tr[45866] = {H:"Хочешь персональную ёлочную игрушку на ёлку?"};
tr[45867] = {OId:270,H:"Таки, персональную? О! У меня есть особые пожелания!"};
tr[45868] = {H:"Внимательно слушаю!"};
tr[45869] = {OId:270,H:"Кх... Ты... Чтокх.. Кхотел?"};
tr[45870] = {H:"Чего-чего ты сказал? Я, это, праздник хочу для тебя устроить!"};
tr[45871] = {OId:270,H:"Праздникх-х-х? Слышал-слышал! Кх..."};
tr[45872] = {H:"Очень хочу сделать тебе подарок - особую ёлочную игрушку!"};
tr[45873] = {OId:270,H:"Игрушкху? Такх. Я кхочу что-то острое и... кх... кхолючее!"};
tr[45874] = {H:"Будет тебе колючая ёлочная игрушка!"};
tr[45875] = {OId:270,H:"Привет! А что ты тут делаешь?"};
tr[45876] = {H:"Привет, Михаил! Я хочу подарить тебе ёлочную игрушку!"};
tr[45877] = {OId:270,H:"Ого-го! Никогда бы не подумал, что у монстриков может быть своя ёлочная игрушка."};
tr[45878] = {H:"Есть какие-нибудь особые пожелания?"};
tr[45879] = {OId:270,H:"Да! Я очень хочу ёлочную игрушку пушистую-пушистую, прям как я!"};
tr[45880] = {H:"Будет сделано!"};
tr[45881] = {OId:270,H:"Бз-з-з! Не подходи, а то током стрельну!"};
tr[45882] = {H:"Спокойствие-спокойствие! Я хочу подарить тебе ёлочную игрушку!"};
tr[45883] = {OId:270,H:"Думаешь, что я сразу стану добрым? А вот и нет! Хотя ради хорошего подарка... Хм... Ладно! Назовём это корыстной выгодой!"};
tr[45884] = {H:"Так, значит, у тебя есть особые пожелания?"};
tr[45885] = {OId:270,H:"Да-да! Бз-з-з. Я хочу какую-нибудь электронную ёлочную игрушку, бз-з-з!"};
tr[45886] = {H:"Записано, ожидай!"};
tr[45887] = {OId:714,H:"Ты собрал все материалы! Чтобы превратить их в волшебные ёлочные игрушки, бросай материалы в колдовской чан!"};
tr[45888] = {H:"Бросаю!"};
tr[45889] = {OId:714,H:"Магиус-Зачароварус-Игрушкацио!"};
tr[45890] = {H:"Вау! Ого! Вот это да!"};
tr[45891] = {OId:714,H:"У нас проблема! Злобикус разгадал секрет заклинания телепортации и заблокировал его!"};
tr[45892] = {H:"Так давайте придумаем новое!"};
tr[45893] = {OId:714,H:"Чтобы составить новое заклинание, нам потребуется очень много времени..."};
tr[45894] = {H:"И что же делать?"};
tr[45895] = {OId:715,H:"Надо придумать другой способ, чтобы попасть к Злобикусу в замок и обменять ёлочные игрушки!"};
tr[45896] = {H:"Кажется, я знаю, но придётся покричать!"};
tr[45897] = {OId:716,H:"Покричать?"};
tr[45898] = {H:"Да, давайте позовём Дедушку Мороза!"};
tr[45899] = {OId:717,H:"Дедушка Мороз!"};
tr[45900] = {H:"Дедушка Мороз!"};
tr[45901] = {OId:718,H:"Хо-хо-хо! Слышу-слышу, звали вы меня, ребята!"};
tr[45902] = {H:"Дедушка Мороз, нам нужна твоя помощь!"};
tr[45903] = {OId:718,H:"Знаю-знаю, слежу я, как у вас тут дела, у кого какое поведение."};
tr[45904] = {H:"Нам нужно попасть к Злобикусу!"};
tr[45905] = {OId:718,H:"К Злобикусу мы обязательно попадём! А тебе за проявленную смелость при спасении Нового года я дарю особенный подарок!"};
tr[45906] = {H:"Ура! Спасибо!"};
tr[45907] = {H:"Ободок " + "\"" + "Змея" + "\"" + ""};
tr[45908] = {OId:719,H:"Ты таки принёс мне обещанную ёлочную игрушку? Спасибо!"};
tr[45909] = {H:"Не за что!"};
tr[45910] = {OId:720,H:"Я рад! Спасибо!"};
tr[45911] = {H:"Пожалуйста!"};
tr[45912] = {OId:721,H:"Ну и ну, вот это крутая ёлочная игрушка!"};
tr[45913] = {H:"Это хорошо, что понравилась."};
tr[45914] = {OId:722,H:"Большое тебе спасибо, смешарик!"};
tr[45915] = {H:"С праздником!"};
tr[45916] = {OId:723,H:"Так уж и быть, обещание ты сдержал, а я сдержу своё."};
tr[45917] = {H:"Вернёшь ёлочные игрушки?"};
tr[45918] = {OId:724,H:"Скорее, до наступления Нового года остаётся совсем немного!"};
tr[45919] = {H:"Ёлочные игрушки уже у меня."};
tr[45920] = {OId:724,H:"Тогда скорее вешай их на ёлку!"};
tr[45921] = {H:"Бегу!"};
tr[45922] = {OId:724,H:"Ура! С новым 2025 годом, смешарики!"};
tr[45923] = {H:"Ура!"};
tr[45924] = {OId:725,H:"Ура! С праздником!"};
tr[45925] = {H:"А как же вечеринка в честь праздника?"};
tr[45926] = {OId:724,H:"Точно, я же для вас ещё праздничный концерт запланировала! Скорее в Диско!"};
tr[45927] = {H:"Ну что, повеселимся?"};
tr[45928] = {H:"Шляпа Киберковбоя"};
tr[45929] = {H:"Плащ Киберковбоя"};
tr[45930] = {H:"Гирлянда " + "\"" + "2025" + "\"" + ""};
tr[45931] = {H:"Шубка Санты"};
tr[45932] = {OId:270,H:"Так-так-так. Не хочешь ли ты испортить нам Новый год? Так ты тоже злодей, получается! Хах-ха-хах."};
tr[45933] = {H:"Я злодей? Это ты украл у нас волшебные ёлочные шары!"};
tr[45934] = {OId:270,H:"Потому что мы тоже хотим Новый год отмечать! По-своему!"};
tr[45935] = {H:"А портить наш праздник обязательно?"};
tr[45936] = {OId:270,H:"Ну, конечно! А иначе, какое же это веселье? Хе-хе-хе."};
tr[45937] = {H:"Злобикус, отдай то, что принадлежит нам."};
tr[45938] = {OId:270,H:"Если отдам, тогда у нас не будет праздника. А я уже всем своим пообещал, что мы устроим ЛУЧШИЙ Новый год!"};
tr[45939] = {H:"В таком случае, я пойду и поговорю с ними!"};
tr[45940] = {OId:270,H:"И о чём ты будешь с ними говорить? О том, что пришёл отнять игрушки? Так они тебя и послушают, ха-ха-ха!"};
tr[45941] = {H:"Я предложу им взамен другие игрушки, персональные!"};
tr[45942] = {OId:718,H:"Подарки все получили, теперь осталось доброе дело закончить!"};
tr[45943] = {H:"И как же попасть к Злобикусу?"};
tr[45944] = {OId:718,H:"Тебя доставят верные друзья моего коллеги – олени Рудольф, Метелица и Молния!"};
tr[45945] = {H:"Нельзя терять ни секунды."};
tr[45946] = {H:"Спутник " + "\"" + "Эльф-помощник" + "\"" + ""};
tr[45947] = {OId:17,H:"Обрезок меха|Обрезок меха появится через {0} мин."};
tr[45948] = {H:"Спутник " + "\"" + "Чудик Симон" + "\"" + ""};
tr[45949] = {H:"Домик " + "\"" + "Новогодняя опушка" + "\"" + ""};
tr[45950] = {H:"Трон " + "\"" + "Королевская кобра" + "\"" + ""};
tr[45951] = {H:"Драгоценная кобра"};
