tr[45953] = {H:"Пулятель резиновых уток"};
tr[45954] = {H:"Я помог смешарикам вернуть Новый год! Заходи и ты!"};
tr[45955] = {H:"Кресло " + "\"" + "Уютная кобра" + "\"" + ""};
tr[45956] = {H:"Фон " + "\"" + "Моя подруга Шуша" + "\"" + ""};
tr[45957] = {H:"Костюм " + "\"" + "Королевская кобра" + "\"" + ""};
tr[45958] = {H:"ВидеоСтул " + "\"" + "Январь" + "\"" + ""};
