tr[45963] = {H:"Дублёнка " + "\"" + "Снежный барс" + "\"" + ""};
tr[45964] = {H:"Валенки " + "\"" + "Снежный барс" + "\"" + ""};
tr[45965] = {H:"Аксессуар " + "\"" + "Петушок" + "\"" + ""};
tr[45966] = {H:"Причёска " + "\"" + "Россыпь икры" + "\"" + ""};
tr[45967] = {H:"Платье " + "\"" + "Рассыпчатое тесто" + "\"" + ""};
tr[45968] = {H:"Туфли " + "\"" + "Яркий акцент" + "\"" + ""};
tr[45969] = {H:"Аксессуар " + "\"" + "Тарталетка с икрой" + "\"" + ""};
tr[45970] = {H:"Шляпа " + "\"" + "Фарфоровая тарелка" + "\"" + ""};
tr[45971] = {H:"Куртка " + "\"" + "Нарезано кубиками" + "\"" + ""};
tr[45972] = {H:"Обувь " + "\"" + "Колбасные лоферы" + "\"" + ""};
tr[45973] = {H:"Аксессуар " + "\"" + "Большая ложка" + "\"" + ""};
