tr[45984] = {H:"Апартаменты " + "\"" + "Люкс в Лондоне" + "\"" + ""};
tr[45985] = {H:"Невероятный холодильник"};
tr[45986] = {H:"Шапка " + "\"" + "Купол мудрости" + "\"" + ""};
