tr[45988] = {H:"Причёска " + "\"" + "Масленица" + "\"" + ""};
tr[45989] = {OId:270,H:"Ох-ох... Это правда, что Почта сломалась? А я-то думаю, куда моя посылка запропастилась."};
tr[45990] = {H:"Правда. Но мы починим! А посылка твоя у меня, держи."};
tr[45991] = {OId:270,H:"О, спасибо! Это же мой любимый журнал " + "\"" + "Хозяюшка" + "\"" + "! Ого, какой интригующий рецептик..."};
tr[45992] = {H:"Что там за рецепт?"};
tr[45993] = {OId:17,H:"Ягоды|Ягоды созреют через {0} мин."};
tr[45994] = {OId:270,H:"Хныыы... Хрюк! Хныыык..."};
tr[45995] = {H:"Нюша, что случилось?"};
tr[45996] = {OId:270,H:"Трагедия! Настоящая катастрофа! Письма... от тайного поклонника... Они... они..."};
tr[45997] = {H:"Что с ними? Потерялись?"};
tr[45998] = {OId:270,H:"О, нет. Не потерялись! Их кто-то разорвал и подкинул мне! И теперь их невозможно прочесть."};
tr[45999] = {H:"И всего-то? Не переживай, сейчас всё склеим!"};
tr[46000] = {OId:726,H:"А вот и наш почтальон."};
tr[46001] = {OId:727,H:"Наконец-то! Я уже начал волноваться!"};
tr[46002] = {H:"И поволноваться есть из-за чего!"};
tr[46003] = {OId:726,H:"Для волнения должна быть веская причина."};
tr[46004] = {OId:727,H:"В чем дело?"};
tr[46005] = {H:"Пока я успокаивал Нюшу, я обнаружил еще одно очень важное письмо..."};
tr[46006] = {H:"Ой, да ничего на самом деле. Просто не будет весны."};
tr[46007] = {OId:726,H:"И это ты называешь " + "\"" + "ничего" + "\"" + "?!"};
tr[46008] = {OId:727,H:"Оба-на! Это всё из-за поломки на Почте?"};
tr[46009] = {H:"Эх, да... Письмо от Снежинок не дошло Веснушкам, и теперь..."};
tr[46010] = {OId:726,H:"Секретное? Не подавай виду. Говори тихо."};
tr[46011] = {OId:727,H:"Ну, не томи!"};
tr[46012] = {H:"Письмо от Снежинок не дошло Веснушкам из-за Почты, и теперь..."};
tr[46013] = {OId:726,H:"Весна не наступит, пока мы не решим проблему."};
tr[46014] = {OId:727,H:"Вот так да. Нужно срочно чинить Почту."};
tr[46015] = {H:"Да, нужно торопиться!"};
tr[46016] = {OId:726,H:"Идем на Почту. Пока ты доставлял посылки, мы с Крошем расчистили проход."};
tr[46017] = {OId:727,H:"Удачи вам! Я незаметно посторожу снаружи, а то мало ли..."};
tr[46018] = {H:"Договорились! Пойдем посмотрим, что случилось на Почте."};
tr[46019] = {OId:270,H:"Найди улики, которые укажут нам на личность злодея!"};
tr[46020] = {OId:270,H:"Хм, почему-то это перо кажется мне знакомым... Продолжай поиски улик!"};
tr[46021] = {OId:270,H:"И вправду следы... Я пока их поизучаю, а ты продолжай поиски улик!"};
tr[46022] = {OId:270,H:"Коллекционирует марки? Интересно, кто бы это мог быть... Продолжай поиски улик!"};
tr[46023] = {OId:270,H:"Да, этот туман сразу бросается в глаза. Продолжай поиски улик!"};
tr[46024] = {OId:270,H:"Хм... Еще совсем недавно здесь было... иначе."};
tr[46025] = {H:"Это точно. Как еще в бункер не пробрались!"};
tr[46026] = {OId:270,H:"Тс-с-с! Вдруг нарушитель ещё здесь? Давай лучше поищем улики."};
tr[46027] = {H:"Ты прав. Пойду осмотрюсь."};
tr[46028] = {OId:270,H:"Уу, а ты чего здесь забыл?! Сейчас как превращу в Злобыря!"};
tr[46029] = {H:"Ого, давай, всегда мечтал!"};
tr[46030] = {H:"Погоди-погоди, не торопись!"};
tr[46031] = {OId:270,H:"Мечтал, значит. Будешь мне служить? Есть пауков и змей? Творить  в Шарараме зло?"};
tr[46032] = {H:"Ой, нет... Я не это имел в виду!"};
tr[46033] = {OId:270,H:"Рр, мое терпение на исходе! Говори чего тебе, пока рога не выросли!"};
tr[46034] = {H:"Зачем ты сломал Почту? Теперь в Шарараме не наступит весна!"};
tr[46035] = {OId:270,H:"Не пользуетесь Почтой по назначению, вот и сломал! А что весна не придет, я не знал... Но это и к лучшему!"};
tr[46036] = {H:"Мы пользуемся Почтой! Пишем письма, отправляем посылки и открытки. Поздравляем друг друга..."};
tr[46037] = {OId:270,H:"Ага, значит друг друга вы поздравляете!.. А еще говорят, что я Злой..."};
tr[46038] = {H:"Ничего не понимаю..."};
tr[46039] = {OId:270,H:"Что тут понимать! На свой день рождения я не получил ни одного подарка..."};
tr[46040] = {H:"Ты празднуешь день рождения?!"};
tr[46041] = {H:"Ха, конечно! Ты же злой, кто тебя будет поздравлять?!"};
tr[46042] = {OId:270,H:"Да... Ни добрый братец Умникус, ни сестра, ни мои злейшие слуги не поздравили. Даже отец не прислал праздничную марку..."};
tr[46043] = {H:"Так вот, почему из Почты исчезли все марки... Слушай, а у меня для тебя кое-что есть!"};
tr[46044] = {H:"Почтовый ящик на ножке"};
tr[46045] = {H:"Почтовый ящик на стену"};
tr[46046] = {OId:726,H:"Как непривычно видеть Злобикуса и не защищаться... Он точно загипнотизирован?"};
tr[46047] = {OId:727,H:"Что нужно сделать, Смешарик?"};
tr[46048] = {H:"Да, точно, Шеф. Злобикус, тебе нужно снять чары, которыми ты тут все разрушил!"};
tr[46049] = {OId:726,H:"И побыстрее."};
tr[46050] = {OId:727,H:"Я... будто забыл все заклинания"};
tr[46051] = {H:"Только не это!"};
tr[46052] = {H:"Рубашка " + "\"" + "Согревающая мудрость" + "\"" + ""};
tr[46053] = {H:"Светильник " + "\"" + "Солнце и Луна" + "\"" + ""};
