tr[46105] = {H:"Берет и причёска " + "\"" + "Курьёз" + "\"" + "" + "\"" + ""};
tr[46106] = {H:"Комбинезон " + "\"" + "В порыве чувств" + "\"" + ""};
tr[46107] = {H:"Сапоги " + "\"" + "В поиске вдохновения" + "\"" + ""};
tr[46108] = {H:"Берет и косички " + "\"" + "Клюковка" + "\"" + ""};
tr[46109] = {H:"Пальто " + "\"" + "Согревающий морс" + "\"" + ""};
tr[46110] = {H:"Ботинки " + "\"" + "Иней" + "\"" + ""};
tr[46111] = {H:"Причёска " + "\"" + "Пламенная" + "\"" + ""};
tr[46112] = {H:"Плащ " + "\"" + "Не с этой планеты" + "\"" + ""};
tr[46113] = {H:"Очки " + "\"" + "Кометы" + "\"" + ""};
tr[46114] = {H:"Сапоги " + "\"" + "Из метеора" + "\"" + ""};
tr[46115] = {OId:270,H:"Так-так, космонавт. Ты по какому-то делу или решил просто в гости заглянуть?"};
tr[46116] = {H:"Привет, Базу! Я по делу. Хотел у тебя узнать, как вы в космосе растения выращиваете."};
tr[46117] = {OId:270,H:"Хм, такого вопроса не ожидал. Всё-таки я капитан, а не садовод. И в космоботанике не силён."};
tr[46118] = {H:"Неужели совсем? Копатыч расстроится... Он хочет у себя что-нибудь новое посадить. Космическое!"};
tr[46119] = {OId:270,H:"Копатыч, говоришь. Что ж, есть у меня кое-что, но не знаю подойдёт ли вам..."};
tr[46120] = {H:"Конечно, подойдёт! Рассказывай!"};
tr[46121] = {OId:270,H:"Ого! Привет, смешарик! Какая звезда тебя сегодня привела к нам?"};
tr[46122] = {H:"Привет, Зак! Можно сказать, звезда по имени Копатыч. Он бы хотел посадить в Шарараме что-то... инопланетное."};
tr[46123] = {OId:270,H:"Как интересно! Я как раз готовлюсь к одному празднику — собираю зябровощи и зягоды, чтобы накрыть вкусный стол."};
tr[46124] = {H:"Круто! Поделишься какими-нибудь семенами?"};
tr[46125] = {OId:270,H:"Мю-мю-мю... Угощайтесь, зябретки!"};
tr[46126] = {H:"Ро, привет! Что это ты тут делаешь?"};
tr[46127] = {OId:270,H:"О, здравствуй! Кормил зябретки космической пылью, а что?"};
tr[46128] = {H:"Зябретки... Это ещё кто такие?"};
tr[46129] = {H:"Кормил пылью?! Похоже, они тебе не слишком нравятся."};
tr[46130] = {OId:270,H:"С чего ты взял? Это их любимое лакомство!"};
tr[46131] = {H:"Как кому-то может нравится пыль?"};
tr[46132] = {OId:270,H:"Зябретки — это растения. Лучше растут, когда идёт метеоритный дождь, но если его нет, космическая пыль отлично спасает!"};
tr[46133] = {H:"Вот так да! Такого Копатыч явно не ожидает... Я тут, кстати, по делу."};
tr[46134] = {OId:270,H:"Ты вернулся! Ну как оно там, успешно?"};
tr[46135] = {H:"Обижаешь, Копатыч. Конечно!"};
tr[46136] = {H:"Увы... Там ничего не растёт."};
tr[46137] = {OId:270,H:"Да ты что?! Укуси меня пчела..."};
tr[46138] = {H:"Ха! Копатыч, я же пошутил! Привёз я твои семена."};
tr[46139] = {OId:270,H:"О! Значит, на других планетах тоже есть сады и огороды?"};
tr[46140] = {H:"Именно так. Только вместо воды и солнца инопланетным растениям нужны метеоритные дожди, лунный свет и космическая пыль!"};
tr[46141] = {OId:270,H:"Ну, дела! Дак где же нам всё это найти?"};
tr[46142] = {H:"Не переживай, сейчас что-нибудь придумаем."};
tr[46143] = {OId:270,H:"Вот, погляди! Я только посадил эти семена, песком присыпал да из лейки полил, а оно вон как вымахало!"};
tr[46144] = {H:"Странно... А ты точно несколько семян посадил? Я только одно растение вижу."};
tr[46145] = {OId:270,H:"То-то и оно! Посадил я все три семечка, которые ты мне привёз. А выросло это... чудо-юдо. И оно продолжает расти!"};
tr[46146] = {H:"Ты явно что-то напутал, Копатыч. А мне теперь расхлёбывать!"};
tr[46147] = {H:"Ой-ой! Нужно срочно что-то делать!"};
tr[46148] = {OId:270,H:"Да ничего я не путал! Сделал, как мы с тобой решили. Ох, плохая это была идея..."};
tr[46149] = {H:"Ладно-ладно, не горячись. Оба хороши."};
tr[46150] = {OId:728,H:"Что случилось? Мы получили ваш сигнал и тут же прилетели на своих самых быстрых ракетах!"};
tr[46151] = {H:"Копатыч посадил все ваши семена, но, кажется, что-то пошло не так..."};
tr[46152] = {OId:729,H:"Вы посадили растения на лунной стороне?"};
tr[46153] = {OId:730,H:"Посыпали космической пылью?"};
tr[46154] = {H:"Нет... Мы подумали, что сможем подобрать альтернативный уход."};
tr[46155] = {OId:728,H:"Что это значит? Каждое растение нуждается в конкретном уходе, тем более космическое! "};
tr[46156] = {H:"Да, вы правы! Стоит поторопиться к Копатычу — ваш монс... точнее, ваши семена растут с ужасной скоростью! "};
tr[46157] = {OId:731,H:"О, Галактика!"};
tr[46158] = {OId:732,H:"Помогите-е-е!"};
tr[46159] = {H:"Сейчас, держись! Что же нам делать?"};
tr[46160] = {OId:731,H:"Нужно усыпить растение, пока они друг друга не покалечили. Мы займемся раствором, а тебе придется отвлечь растение на себя."};
tr[46161] = {OId:732,H:"А-а-а! Давит!"};
tr[46162] = {H:"Ну, космический мутант, берегись!"};
tr[46163] = {OId:270,H:"Узнай, как обстоят дела с садоводством у инопланетян на Космостанции!"};
tr[46164] = {OId:270,H:"Базу сказал, что на Зябре тоже могут быть интересные семена? Вот здорово! Должон тебе буду, коли привезёшь их!"};
tr[46165] = {OId:270,H:"Базу сказал, что на Мюре тоже могут быть интересные семена? Вот здорово! Должон тебе буду, коли привезёшь их!"};
tr[46166] = {H:"Пиджак " + "\"" + "Ромашка" + "\"" + ""};
tr[46167] = {H:"Причёска " + "\"" + "Весеннее солнце" + "\"" + ""};
tr[46168] = {OId:733,H:"Спасибо, ребяты! Я уж думал... всё."};
tr[46169] = {OId:731,H:"Мы всегда рады помочь."};
tr[46170] = {H:"Без вас бы мы не справились! Правда, без вас бы и не было ничего этого..."};
tr[46171] = {OId:731,H:"Нужно внимательнее относиться к уходу за растениями! Это живые существа."};
tr[46172] = {OId:733,H:"Да-да, это точно. Но что же теперь делать с ним?"};
tr[46173] = {H:"Похоже в Шарараме ему не понравилось. Может на других планетах будет лучше?.."};
tr[46174] = {H:"Может вы заберёте его? Всё-таки этот монс... это растение из ваших семян проросло!"};
tr[46175] = {OId:731,H:"Думаю, мы сможем найти к нему подход. Так что он летит с нами."};
tr[46176] = {OId:733,H:"Ой, спасибо! Спасли, честное слово!"};
tr[46177] = {H:"Спасибо вам за помощь! Обещаем больше не вмешиваться в законы природы!"};
tr[46178] = {H:"Костюм " + "\"" + "Космический мутант" + "\"" + ""};
tr[46179] = {H:"Фон " + "\"" + "Межгалактический сад" + "\"" + ""};
tr[46180] = {OId:17,H:"Лампочки|Лампочки доставят через {0} мин."};
tr[46181] = {H:"Причёска " + "\"" + "Торнадо" + "\"" + ""};
tr[46182] = {H:"Куртка " + "\"" + "Вечерний стиль" + "\"" + ""};
tr[46183] = {H:"Я разбил космический огород прямо в Шарараме! Попробуй и ты!"};
tr[46184] = {OId:731,H:"Мы готовим усыпляющий раствор для растения. Пожалуйста, отвлеки его, чтобы мы успели закончить! "};
tr[46185] = {H:"Шапка " + "\"" + "Пнём-пень" + "\"" + ""};
tr[46186] = {H:"Куртка " + "\"" + "Древесный дух" + "\"" + ""};
tr[46187] = {H:"Ботинки " + "\"" + "Древесные шаги" + "\"" + ""};
tr[46188] = {H:"Причёска " + "\"" + "Звонкий ручеёк" + "\"" + ""};
tr[46189] = {H:"Курточка " + "\"" + "Подснежник" + "\"" + ""};
tr[46190] = {H:"Сандалии " + "\"" + "Росточек" + "\"" + ""};
