tr[46265] = {H:"Причёска " + "\"" + "Полуночный маллет" + "\"" + ""};
tr[46266] = {H:"Костюм " + "\"" + "Футбольный мяч" + "\"" + ""};
tr[46267] = {H:"Причёска " + "\"" + "На абордаж" + "\"" + ""};
