tr[46269] = {H:"Костюм " + "\"" + "На абордаж" + "\"" + ""};
tr[46270] = {OId:270,H:"Я помню чудное мгновенье! Вкус земляничного... варенья!"};
tr[46271] = {H:"Ух ты! Стихи пишешь? Не хочу тебе мешать, но Нюша ищет кавалера на вечеринку и..."};
tr[46272] = {OId:270,H:"Ка-кавалееера? На вечеринку?.. Ой! Чернила разлил. "};
tr[46273] = {H:"Не переживай, Бараш, с чернилами я разберусь! А ты пока подумай..."};
tr[46274] = {OId:270,H:"О, привет! Сыграем в волейбол? Или в " + "\"" + "Секретики" + "\"" + "?"};
tr[46275] = {H:"Привет, Крош. Не могу, извини. Тороплюсь — помогаю Нюше подготовиться к вечеринке."};
tr[46276] = {OId:270,H:"А, понятно. Занятые такие все! Ёжик с какой-то земляникой возится. У вас вечеринка..."};
tr[46277] = {H:"Не у нас, а у Джета Стета! Ты, кстати, тоже можешь пойти."};
tr[46278] = {OId:270,H:"А вот и ты. Ну-ка расскажи, что здесь произошло."};
tr[46279] = {H:"Ох, самому бы разобраться. А где Крош?"};
tr[46280] = {OId:270,H:"Крош как раз меня к тебе и прислал. У него похоже что-то с животом случилось... А где хозяин этого клуба?"};
tr[46281] = {H:"Здесь, перед тобой."};
tr[46282] = {H:"Джет Стет куда-то сбежал, как только всё начало рушиться!"};
tr[46283] = {OId:270,H:"Правда? А Крош мне говорил про какого-то актёра."};
tr[46284] = {H:"Ну вот, шутка не удалась... Да, хозяин клуба — Джет Стет. Похоже он сбежал."};
tr[46285] = {OId:270,H:"Что ж, далеко ему не уйти. Сейчас выложу его фото в Интернет, и моя аудитория сама его найдет."};
tr[46286] = {H:"Может, лучше обратиться к профессионалу? Жёлтому Клюву!"};
tr[46287] = {H:"Ух ты! Я могу помочь?"};
tr[46288] = {OId:740,H:"Куда-то направляетесь, мистер Стет?"};
tr[46289] = {OId:741,H:"Что?! Как вы меня нашли?"};
tr[46290] = {H:"Главное, что нашли. Ты что, собирался покинуть страну?"};
tr[46291] = {OId:740,H:"Нехорошо убегать от ответственности."};
tr[46292] = {OId:741,H:"Я... испугался. Всё вдруг начало ломаться..."};
tr[46293] = {H:"И ты решил оставить клуб и пострадавших посетителей?! Или ты отправлялся на кинопремию?"};
tr[46294] = {OId:741,H:"Но я не виноват, что они пострадали! А награду мне обещали доставить в клуб..."};
tr[46295] = {H:"С кинопремией разберемся позже. Но кто же тогда виноват в произошедшем в клубе?"};
tr[46296] = {OId:740,H:"Ответственность за посетителей всегда лежит на хозяине клуба."};
tr[46297] = {OId:741,H:"Какой же смысл мне портить вечеринку в свою честь?!"};
tr[46298] = {H:"Специально — никакого. А вот неосознанно..."};
tr[46299] = {H:"Злодею не нужен смысл, чтобы сделать пакость!"};
tr[46300] = {OId:740,H:"Так, давайте остынем. Уверен, Джет и сам не понимал, что натворил."};
tr[46301] = {OId:741,H:"Но как же можно навредить случайно?.."};
tr[46302] = {H:"Злодею не нужен смысл, чтобы сделать пакость!"};
tr[46303] = {OId:740,H:"Джет, ну-ка расскажи, как ты открыл свой клуб. Что сделал первым делом?"};
tr[46304] = {OId:741,H:"Потратил почти все деньги на... рекламу."};
tr[46305] = {H:"На рекламу? А что с оборудованием, едой и мебелью?"};
tr[46306] = {OId:741,H:"Подумал, что реклама привлечёт много людей, а чуть позже я бы всё заменил. Не знал, что это так важно."};
tr[46307] = {H:"Важно, Джет! Безопасность посетителей должна быть на первом месте!"};
tr[46308] = {OId:740,H:"Без хорошего оборудования и качественной еды клуб не может работать!"};
tr[46309] = {OId:741,H:"Но я просто хотел сделать праздник для всех..."};
tr[46310] = {H:"Праздник — это, конечно, хорошо..."};
tr[46311] = {OId:740,H:"Но не за счёт безопасности, Джет. Теперь нужно исправлять ошибки"};
tr[46312] = {H:"Да, и сначала нужно позаботиться о пострадавших. Ты готов взять на себя ответственность?"};
tr[46313] = {OId:741,H:"Да, я готов. Мистер Искусство сделает всё возможное, чтобы помочь!"};
tr[46314] = {OId:740,H:"Вот это правильный подход. "};
tr[46315] = {H:"Отлично! Тогда нам с тобой стоит заглянуть в больничку."};
tr[46316] = {OId:270,H:"Ёлки-иголки! Что это было? И куда все подевались?"};
tr[46317] = {H:"Самому интересно. Ха, а виновника торжества и след простыл!"};
tr[46318] = {OId:270,H:"Ну и ну! Слушай, раз вечеринка закончилась, а реклама до сих пор в Шарараме, то другие смешарики ещё могут прийти сюда."};
tr[46319] = {H:"Ты прав. Я пойду сниму объявления, а ты никого сюда не впускай! Мало ли..."};
tr[46320] = {OId:270,H:"Найди и убери всю рекламу о вечеринке Джета Стета в Шарараме!"};
tr[46321] = {OId:742,H:"Ещё пациенты? Неужели опять эпидемия..."};
tr[46322] = {H:"Нет-нет, доктор. Мы не пациенты. Кое-кто просто хочет вам помочь!"};
tr[46323] = {OId:742,H:"Правда?"};
tr[46324] = {OId:743,H:"Кхм, да... Похоже я виноват, что к вам сегодня поступило так много пациентов..."};
tr[46325] = {H:"В общем, он хочет помочь и заодно попросить у пострадавших прощения. Думаете, они его простят?"};
