tr[46348] = {H:"Подводный диван"};
tr[46349] = {OId:737,H:"Рад всех приветствовать на грандиозной вечеринке в честь номинанта и, конечно, будущего победителя великой кинопремии... В честь меня!"};
tr[46350] = {OId:734,H:"Ах, как хорош!"};
tr[46351] = {OId:738,H:"Йее!"};
tr[46352] = {OId:739,H:"Браво!"};
tr[46353] = {H:"А что за кинопремия-то?"};
tr[46354] = {OId:737,H:"Прошу прекратить глупые выкрики из зала..."};
tr[46355] = {OId:734,H:"Тс-с!.. Ну, ОсКар, конечно."};
tr[46356] = {OId:738,H:"Потише, народ."};
tr[46357] = {H:"Молчу-молчу..."};
tr[46358] = {OId:737,H:"Так вот... Давайте же отпразднуем это событие! Ешьте и веселитесь в мою честь! А теперь - музыку!"};
