tr[46574] = {H:"Урок пляжного колдовства"};
tr[46575] = {H:"Привет! С днём рождения Шарарама! Хочешь подарок? Ответь на мой вопрос!"};
tr[46576] = {H:"И тебя с праздником! Какой вопрос?"};
tr[46577] = {H:"Назови мне имя девочки, которая целую зиму прожила в мышиной норе!"};
tr[46578] = {H:"Дюймовочка."};
tr[46579] = {H:"Грета Тунберг."};
tr[46580] = {H:"Элли Смит."};
tr[46581] = {H:"Какой известный конь, сделав два шага вперёд, на третий обязательно сворачивает в сторону?"};
tr[46582] = {H:"Буцефал."};
tr[46583] = {H:"Троянский."};
tr[46584] = {H:"Шахматный."};
tr[46585] = {H:"Как называется самая большая змея на нашей планете?"};
tr[46586] = {H:"Кобра."};
tr[46587] = {H:"Анаконда."};
tr[46588] = {H:"Питон."};
tr[46589] = {H:"Какой известный город расположен на берегу реки Тигр?"};
tr[46590] = {H:"Пекин."};
tr[46591] = {H:"Каир."};
tr[46592] = {H:"Багдад."};
tr[46593] = {H:"Кресло " + "\"" + "Мышонок" + "\"" + ""};
tr[46594] = {H:"Лошадка"};
tr[46595] = {H:"Летучий змей"};
tr[46596] = {H:"Шарафон " + "\"" + "Жёлтый клюв" + "\"" + ""};
tr[46597] = {OId:270,H:"Ах, день рождения - это так прекрасно! Можно получать цветы, конфеты и поздравления круглые сутки!"};
tr[46598] = {H:"Хм... Нюша, а ты сегодня только принимала подарки или и сама кого-то поздравила?"};
tr[46599] = {OId:270,H:"Хрю... То есть - ой... Поздравить ещё никого не успела, но собиралась, конечно. Праздник-то общий!"};
tr[46600] = {H:"Ты права. Кого же поздравишь в первую очередь?"};
tr[46601] = {OId:17,H:"Клубника|Клубника созреет через {0} мин."};
tr[46602] = {OId:779,H:"С днём рождения Шарарама, друзья!"};
tr[46603] = {OId:780,H:"Поздравляяяю! Кстати, в честь праздника у меня есть стихотворение..."};
tr[46604] = {H:"Ура! Всех с праздником! О, ты уже отредактировал стих?"};
tr[46605] = {OId:781,H:"Погодите вы! Давайте сначала попробуем торт."};
tr[46606] = {OId:782,H:"Чур, я задуваю свечи!"};
tr[46607] = {OId:783,H:"А я запускать салют."};
tr[46608] = {H:"Ну, торт так торт! А ты пока порепетируй, Бараш."};
tr[46609] = {OId:782,H:"Тьфу! Эти свечки вообще не задуваются!"};
tr[46610] = {H:"А может вы просто плохо старались?"};
tr[46611] = {OId:782,H:"Да мы дули изо всех сил! Это явно со свечками что-то!"};
tr[46612] = {OId:783,H:"Йа-йа, и салюты не работать как надо."};
tr[46613] = {H:"Но как такое может быть?"};
tr[46614] = {OId:783,H:"Обычно мои салюты запускаться через десять секунд. А тут..."};
tr[46615] = {H:"А тут уже явно прошло больше. Ой! Или нет... У меня похоже часы встали."};
tr[46616] = {OId:784,H:"А, это ты. Подходи, не бойся."};
tr[46617] = {H:"Но... Что здесь делает Злобикус? Неужели вы стали заодно?"};
tr[46618] = {OId:784,H:"Нет-нет. Я лишь пригласил брата вместе отметить праздник."};
tr[46619] = {OId:785,H:"Ага, должно быть совесть замучила, что с моим днём рождения не поздравил..."};
tr[46620] = {H:"Подождите. Вы разве... ну, не в ссоре?"};
tr[46621] = {OId:784,H:"Не сегодня. Всё-таки такой день."};
tr[46622] = {OId:785,H:"У нас временное перемирие, ха."};
tr[46623] = {H:"Боюсь, что перемирию пришёл конец. Мы знаем, что ты остановил время, Злобикус!"};
tr[46624] = {H:"Ага, так я и поверил! Наверняка, он пришёл, чтобы как-то напакостить."};
tr[46625] = {OId:784,H:"Зачем же ты так говоришь?"};
tr[46626] = {OId:785,H:"Рр! И какую же гадость я по-твоему сделал?"};
tr[46627] = {H:"Остановил время! Не хочешь, чтобы Шарарам отметил свой день рождения!"};
tr[46628] = {OId:784,H:"Ох, остановить время... Проделать такое нам не под силу даже вместе."};
tr[46629] = {OId:785,H:"Хм, весьма польщён, что подумали на меня..."};
tr[46630] = {H:"Не понимаю. Кто же, если не вы?!"};
tr[46631] = {OId:784,H:"Найди смешариков, которые могут дать нужные ингредиенты."};
tr[46632] = {OId:270,H:"Пам-парам, дабу-ди, дабу-дай. Бара-будай, на-на..."};
tr[46633] = {H:"Какая знакомая мелодия!"};
tr[46634] = {OId:270,H:"Ай реп ту дай... Ой! Ты это мне говоришь?"};
tr[46635] = {H:"Тебе, конечно. Кому же ещё?"};
tr[46636] = {OId:270,H:"Но-но... Ты же не можешь меня видеть!"};
tr[46637] = {H:"Очень даже вижу. И слышу, как ты поёшь."};
tr[46638] = {OId:270,H:"Вот это да! А я думал, про меня все забыли. Давно со мной никто не говорил..."};
tr[46639] = {H:"Прости, конечно, но кто ты такой? Я тебя впервые вижу."};
tr[46640] = {OId:270,H:"А вот угадай! Мне без года - 18. Сегодняшний день я ждал 12 месяцев. И я знаю здесь всех-всех смешариков!"};
tr[46641] = {H:"Даже меня знаешь? И как же меня зовут, умник?"};
tr[46642] = {H:"Ну, без года 18 - это 17. Сегодня день рождения Шарарама, значит, ты год ждал его. Получается..."};
tr[46643] = {OId:270,H:"Ха! Это проще простого. Тебя зовут: {0}!"};
tr[46644] = {H:"Ничего себе! Значит, тебе 17 лет, ты всех-всех знаешь и год ждал день рождения Шарарама. Получается..."};
tr[46645] = {OId:270,H:"Получается, что у тебя угадать не получается! Хи-хи!"};
tr[46646] = {H:"Зато я догадываюсь, что это ты остановил время! Я прав?"};
tr[46647] = {OId:270,H:"Может я, а может не я. Ты меня сначала догони - тогда и расскажу!"};
tr[46648] = {H:"Эй, погоди!"};
tr[46649] = {OId:270,H:"В догонялки с тобой скучно играть. Очень ты медленный. Я уже заскучать успел, хи-хи!"};
tr[46650] = {H:"Ничего я не медленный! И вообще, признавайся давай: кто ты такой и зачем время остановил?"};
tr[46651] = {OId:270,H:"Да что ты заладил со своим временем... А ты разве любишь, когда у тебя день рождения заканчивается?"};
tr[46652] = {H:"Нет, конечно, кто ж это любит."};
tr[46653] = {OId:270,H:"Ну вот, и я не люблю. Такой классный день. Пусть он будет всегда!"};
tr[46654] = {H:"Но мы пытаемся день рождения Шарарама отметить. А из-за твоей  остановки времени даже салют запустить не можем."};
tr[46655] = {OId:270,H:"Ты так и не понял? Это мой праздник. Я - Дух Шарарама. И я не хочу, чтобы вы запускали салют!"};
tr[46656] = {H:"Ух ты! Так это же салют в твою честь! Чем же ты недоволен?"};
tr[46657] = {OId:270,H:"Да просто знаю я ваши праздники. Свечки задуете, тортик съедите. Потом салюты запустите - и по домам!"};
tr[46658] = {H:"А что же нам ещё делать?"};
tr[46659] = {OId:270,H:"Как что? Праздновать! Долго-долго!.. Ой, ты меня утомил. Давай лучше в " + "\"" + "Скачки" + "\"" + " сыграем."};
tr[46660] = {H:"Хорошо. Но потом тебе всё равно придётся запустить время!"};
tr[46661] = {OId:270,H:"Какую ещё минуточку? Я хочу веселиться!"};
tr[46662] = {H:"Я тоже. Но мои друзья ждут, когда ты снова запустишь время, и я обещал им помочь."};
tr[46663] = {OId:270,H:"Скучные у тебя друзья. И ничего я запускать не намерен.  Мой день рождения будет всегда!"};
tr[46664] = {H:"Ну вот, значит, теперь мой день рождения никогда не наступит?"};
tr[46665] = {H:"А как же другие времена года? Разве ты не любишь собирать осенью гербарий или играть зимой в снежки?"};
tr[46666] = {OId:270,H:"Ой, я об этом как-то не думал..."};
tr[46667] = {H:"А вот подумай. Если сегодня будет длиться вечно, то ты всех лишишь других праздников. И себя в том числе!"};
tr[46668] = {OId:270,H:"Ты прав, вокруг моего дня рождения игра... то есть земля не вертится."};
tr[46669] = {H:"Значит, ты всё-таки запустишь время?"};
tr[46670] = {OId:786,H:"Спаситель вы наш, как успехи?"};
tr[46671] = {OId:783,H:"Мои часы начать тикать! Время снова пойти вперёд!"};
tr[46672] = {H:"Всё отлично. Время и вправду больше не стоит на месте. Давайте отмечать!"};
tr[46673] = {OId:779,H:"Тогда ещё раз - всех с днём рождения Шарарама!"};
tr[46674] = {OId:782,H:"С праздником!"};
tr[46675] = {H:"Ура!"};
