tr[46823] = {OId:270,H:"Так-так, а куда это мы направляемся? Надеюсь, не на гоночную трассу?"};
tr[46824] = {H:"Нет, конечно! В такой туман не стоит устраивать гонки."};
tr[46825] = {OId:270,H:"Ай молодца! Возьми с полки пирожок!.. Ох-ох, а куда ж это они запропастились..."};
tr[46826] = {H:"Совунья, что случилось?"};
tr[46827] = {OId:17,H:"Вертушка|Вертушку сделают через {0} мин."};
tr[46828] = {OId:270,H:"Найди улики, которые укажут, что Ёжик тут был!"};
tr[46829] = {OId:270,H:"Ёлки-иголки! Да куда это он подевался?.."};
tr[46830] = {H:"Крош, ты потерял кого-то?"};
tr[46831] = {OId:270,H:"Ух! А я тебя и не заметил... Да, потерял. Ёжика! Что же делать?"};
tr[46832] = {H:"Не переживай. Мы его обязательно найдём! Наверное, в тумане заблудился"};
tr[46833] = {OId:270,H:"Где же его искать теперь в этом тумане?! Да я же чуть уши на себе не рву! Он ведь мой лучший друг..."};
tr[46834] = {H:"Вдох-выдох... Давай не будем рвать ни волосы на себе, ни уши. А лучше займемся поисками."};
tr[46835] = {OId:270,H:"Ничего себе! Я лап своих почти не вижу... не то что следов Ёжика."};
tr[46836] = {H:"Да, туман становится всё более густым. Если мы продолжим, то и сами заблудимся."};
tr[46837] = {OId:270,H:"И что делать? Не ждать же! Лосяш говорил, что туман не от погоды и сам не пройдёт..."};
tr[46838] = {H:"И ты ему веришь? Он ещё говорил, что Земля круглая! Забыл?"};
tr[46839] = {H:"Что же ты раньше молчал? Тогда я пошёл искать источник тумана!"};
tr[46840] = {OId:270,H:"Погоди! Ты же один заблудишься. Я с тобой!"};
tr[46841] = {H:"Нет, ты лучше здесь останься. Вдруг Ёжик вернётся? А я сам справлюсь."};
tr[46842] = {OId:270,H:"Ну, герой! Хорошо. Только не беги сразу. Давай сначала подумаем, что в чём может быть причина."};
tr[46843] = {H:"Может, авария на заводике в Сити?"};
tr[46844] = {H:"Кто-то сломал в автосалоне машину, вот она и дымится!"};
tr[46845] = {OId:270,H:"Ты уже проверил нашу теорию про задымление в Сити?"};
tr[46846] = {OId:270,H:"Не писал я Пину никакое письмо! Объясни это ему в Сити!"};
tr[46847] = {OId:270,H:"Помоги Пину отключить машину в Сити, чтобы спасти Шарарам от тумана!"};
tr[46848] = {OId:270,H:"Ахтунг! Кто здесь? Съёмка уже завершиться?"};
tr[46849] = {H:"Пин, это ты? Какая ещё съёмка?"};
tr[46850] = {H:"Нет, ещё идёт... Камерааа, мотор!"};
tr[46851] = {OId:270,H:"Йа-йа. Съёмка фильма, конечно. Иначе зачем я выпускайт столько тумана?"};
tr[46852] = {H:"Так это ты сделал? А ну, прекращай немедленно!"};
tr[46853] = {OId:270,H:"Ничего не понимайт. Кто же тогда просить туман?"};
tr[46854] = {H:"Уж точно не Крош. Из-за этого тумана потерялся его лучший друг!"};
tr[46855] = {OId:270,H:"Ёжик потеряться? О майн гот!.. Надо скорее выключать эту машину!"};
tr[46856] = {H:"Вот и я тебе о чём. Давай помогу!"};
tr[46857] = {OId:270,H:"Что там творится на Площади у Больнички? Ты посмотри, а я Ёжика искать!"};
tr[46858] = {OId:787,H:"Ррр!!! Что вы наделали? Почему туман исчез?"};
tr[46859] = {OId:788,H:"Потому что я отключайт туманную машину. Ты меня обмануть."};
tr[46860] = {OId:789,H:"Так вот, в чём была причина..."};
tr[46861] = {H:"Да, Злобикус написал поддельное письмо от Кроша, чтобы Пин создал генератор тумана."};
tr[46862] = {OId:787,H:"И зачем же мне таким заниматься?!"};
tr[46863] = {OId:788,H:"Должно быть, чтобы украсть всё это."};
tr[46864] = {OId:789,H:"Здесь не нужно быть гением, недруг наш."};
tr[46865] = {H:"Но подождите... Вряд ли он приходил сюда, чтобы напакостить Нюше или украсть грабли Копатыча."};
tr[46866] = {OId:787,H:"Р-р-разумеется, не за этим я приходил. А за магическим шаром братца!"};
tr[46867] = {OId:788,H:"Но что же помешать?"};
tr[46868] = {OId:789,H:"О, вероятно, Злобикус сам заблудился в тумане... Феноменально!"};
tr[46869] = {H:"Ха-ха-ха! На свои же грабли, Злобикус?"};
tr[46870] = {OId:787,H:"И какое странное место..."};
tr[46871] = {OId:789,H:"Невероятно. Заклятие Злобикуса отскочило и попало в него же!"};
tr[46872] = {H:"Вот это да! Да он сам себе память отшиб!"};
tr[46873] = {OId:788,H:"Сомневайтен, что это надолго. Нельзя терять время."};
tr[46874] = {OId:789,H:"Вы абсолютно правы!"};
tr[46875] = {H:"Тогда... Кхм! Тебя зовут Злобикус. Ты забрал вещи наших друзей. Вернёшь?"};
tr[46876] = {OId:787,H:"О, простите... Конечно. Вот!"};
tr[46877] = {OId:788,H:"Данке шон!"};
tr[46878] = {H:"Ого, это оказалось проще, чем я думал."};
tr[46879] = {OId:270,H:"Ёлки-иголки! Ёжик! Ты где был?."};
tr[46880] = {H:"Нашёлся, наконец-то. А мы тебя весь день искали!"};
tr[46881] = {OId:270,H:"Да! Из-за этого тумана весь день насмарку. Ни порыбачить, ни поиграть."};
tr[46882] = {OId:790,H:"Кажется, в прятки сегодня я бы выиграл..."};
tr[46883] = {H:"Неужели ты специально прятался?!"};
tr[46884] = {OId:270,H:"С ума сойти!"};
tr[46885] = {OId:790,H:"Нет, я правда заблудился. Пошёл просто..."};
tr[46886] = {H:"В туман пошёл? Но зачем?!"};
