tr[47001] = {H:"Камзол пирата-призрака"};
tr[47002] = {H:"Костюм " + "\"" + "Чудо-юдо" + "\"" + ""};
tr[47003] = {H:"Футболка " + "\"" + "Тыковка" + "\"" + ""};
tr[47004] = {H:"Наряд " + "\"" + "Граф" + "\"" + ""};
tr[47005] = {H:"Спутник " + "\"" + "Волшебная тыква" + "\"" + ""};
tr[47006] = {H:"Маска " + "\"" + "Угадай, кто?" + "\"" + ""};
tr[47007] = {H:"СмеШутка " + "\"" + "Без паники!" + "\"" + ""};
tr[47008] = {H:"МегаНабор " + "\"" + "Волшебная вечеринка!" + "\"" + ""};
tr[47009] = {H:"Набор " + "\"" + "Магическая ночь!" + "\"" + ""};
tr[47010] = {H:"Набор " + "\"" + "Тыквенное безумие!" + "\"" + ""};
tr[47011] = {H:"Набор " + "\"" + "Бу-у-у!" + "\"" + ""};
tr[47012] = {H:"Набор " + "\"" + "Крутая тыква!" + "\"" + ""};
tr[47013] = {OId:270,H:"Йо, дорогуша! Я вырастил тыкву, но не простую, а волшебную. Давай достанем из неё крутые призы!"};
tr[47014] = {OId:793,H:"Не-е-т! Кыш, глупая гусеница!.."};
tr[47015] = {H:"Бараш! Кто это с тобой? Ой, что она жуёт..!"};
tr[47016] = {OId:793,H:"Злостный истребитель моего творчества! Ладно бы плохие стихи ела, но эти..."};
tr[47017] = {H:"Вот так да! А ты пробовал переключить её на что-то повкуснее?"};
tr[47018] = {OId:791,H:"А-а-а, караул! Спасите!"};
tr[47019] = {H:"Ой, Нюша! То есть, Нюши... А от чего спасать?"};
tr[47020] = {OId:791,H:"Не видишь, что ли? От старости!"};
tr[47021] = {OId:792,H:"На кого это ты намекаешь?"};
tr[47022] = {H:"Кхм, похоже, кто-то давно не смотрелся в зеркало..."};
tr[47023] = {OId:792,H:"Зачем же смотреться? Я и так знаю, что прекрасна."};
tr[47025] = {H:"Это точно... Нюша, отойдем поговорить? Другая Нюша!"};
tr[47026] = {OId:270,H:"Ой-ой-ой..."};
tr[47027] = {H:"Крош, ты чего? Морковки испугался?"};
tr[47028] = {OId:270,H:"Это уже не морковка, а монстр какой-то! Такая и кролика слопать может!"};
tr[47029] = {H:"Правда?! Ой-ой, теперь и мне страшно... Пока!"};
tr[47030] = {H:"Скажешь тоже! Морковки кроликов не едят, даже большие."};
tr[47031] = {OId:270,H:"Да знаю. Но вот гляжу на неё и думаю, что всякое бывает..."};
tr[47032] = {H:"Отставить панику! Сейчас мы поставим эту морковку на место в пищевой цепочке!"};
tr[47033] = {OId:270,H:"Не понимаю, что я сделал не так... Почему клубы закрыли?"};
tr[47034] = {H:"Что? Никто никакие клубы не закрывал. Они работают!"};
tr[47035] = {OId:270,H:"Но вот же они. Разрушенные... Плакали мои денежки!"};
tr[47036] = {H:"Ба-Босс, с клубами всё в порядке. А это лишь страх! На деле твой бизнес процветает. Сейчас докажу!"};
tr[47037] = {OId:270,H:"Хнык... Так и думала, что я плохой архитектор!.."};
tr[47038] = {H:"Дора, что ты такое говоришь? Ты отличный архитектор! И дизайнер!"};
tr[47039] = {OId:270,H:"А вот мои клиенты с тобой не согласны..."};
tr[47040] = {OId:794,H:"Ещё бы! В доме кривые стены, да и пола местами нет!"};
tr[47041] = {H:"Глупость какая! Это же неправда."};
tr[47042] = {OId:270,H:"Раз пишут, значит, правда."};
tr[47043] = {H:"Нет, Дора. Письмо ненастоящее. Это лишь твой страх!"};
tr[47044] = {OId:17,H:"Яблоко|Яблоко созреет через {0} мин."};
tr[47045] = {OId:270,H:"Какой ужас... Поверить не могу!"};
tr[47046] = {H:"Так-так, Коттер. Делаешь вид, что напуган?"};
tr[47047] = {OId:270,H:"Я и вправду напуган! Зачем же мне делать такой вид?"};
tr[47048] = {H:"Ладно-ладно. И что же тебя так испугало?"};
tr[47049] = {H:"Чтобы никто на тебя не подумал. А ведь именно ты наколдовал страхи!"};
tr[47050] = {OId:270,H:"Оценки за эту неделю. Там одни двойки! А я ведь отличником был..."};
tr[47051] = {H:"Погоди... Зачем ты свой-то страх наколдовал?"};
tr[47052] = {OId:270,H:"Что? Ничего такого я не делал! Зачем мне двойки себе в дневник рисовать?"};
tr[47053] = {H:"Да, звучит странно... Но кто же тогда оживил страхи Смешариков?"};
tr[47054] = {OId:270,H:"Уж точно не я!"};
tr[47055] = {H:"Верю. Давай разберёмся с твоим страхом, а потом найдём негодяя!"};
tr[47056] = {OId:795,H:"Вот и вы! Значит, это Шарри наложил проклятие на Шарарам?"};
tr[47057] = {H:"Нет-нет, Ёжик, Шарри не виноват! Его страх тоже ожил."};
tr[47058] = {OId:796,H:"Как вы могли так на меня подумать?"};
tr[47059] = {OId:795,H:"Извини. Но страхи явно кто-то наколдовал."};
tr[47060] = {H:"А ты волшебник, Шарри. И был на вечере страшилок!"};
tr[47061] = {OId:796,H:"Да уж, подхожу по всем параметрам..."};
tr[47062] = {OId:795,H:"И всё же это не ты. Нужно найти настоящего злодея."};
tr[47063] = {H:"Согласен, осмотрим лес! Раз тут всё началось."};
tr[47064] = {OId:270,H:"Вот почему предметы такие разные... Злодей был не один!"};
tr[47065] = {OId:797,H:"Рр! Как я здесь оказался?"};
tr[47066] = {H:"С помощью магии, Злобикус! Нечего везде свои перья раскидывать!"};
tr[47067] = {OId:797,H:"Вот значит как... И зачем же вы нас призвали?"};
tr[47068] = {H:"Мы искали негодяя, который оживил страхи в Шарараме. И наткнулись на ваши вещи."};
tr[47069] = {OId:797,H:"Му-ха-ха! Что же, да, это я постарался."};
tr[47070] = {OId:798,H:"Никто не удивлён."};
tr[47071] = {H:"Но зачем тебе это? И что ещё интереснее, как ты узнал, какие у Смешариков страхи?"};
tr[47072] = {OId:270,H:"Тебе не прогнать нас из Шарарама какими-то страхами!"};
