tr[47216] = {H:"Новогодний венок в домик"};
tr[47217] = {H:"Кровать " + "\"" + "Сказочная карета" + "\"" + ""};
tr[47218] = {H:"Новогодний носок"};
tr[47219] = {H:"Шлем " + "\"" + "Весёлый жокей" + "\"" + ""};
tr[47220] = {H:"Куртка " + "\"" + "Весёлый жокей" + "\"" + ""};
tr[47221] = {H:"Сапоги " + "\"" + "Весёлый жокей" + "\"" + ""};
tr[47222] = {OId:270,H:"Обожаю Новый год! Все такие нарядные, а на праздничном столе так много вкусностей!"};
tr[47223] = {H:"Ты любишь Новый год только из-за нарядов и еды, что ли?"};
tr[47224] = {H:"Да-а! Это мой самый любимый праздник!"};
tr[47225] = {H:"Ну, не знаю. Мне вот Новый год не очень уж нравится..."};
tr[47226] = {OId:270,H:"Нет, конечно! Ещё за танцы, веселье, подарки, красивую ёлку в конце концов."};
tr[47227] = {H:"Точно! Нам же нужно нарядить огромную ёлку. У тебя случайно ничего нет?"};
tr[47228] = {OId:270,H:"Ах, как приятно, когда тебя понимают! Я ещё очень люблю наряжать ёлку, а ты?"};
tr[47229] = {H:"О, нам как раз нужно этим заняться! У тебя случайно ничего для этого нет?"};
tr[47230] = {OId:270,H:"Что?! А как же... Как же волшебство? Ты не загадываешь желание? Не наряжаешь ёлку?"};
tr[47231] = {H:"Да вот заставили наряжать... Может поможешь? У тебя наверняка что-нибудь есть!"};
tr[47232] = {OId:270,H:"Чтобы ёлку украсить? Нет. Я уже все игрушки у себя повесила... О!"};
tr[47233] = {H:"Ты что-то придумала?"};
tr[47234] = {OId:270,H:"Хо-хо, с наступающим! Чего это ты невесёлый какой-то?"};
tr[47235] = {H:"Весёлый! Просто тороплюсь. Скоро приедет журналист, а у нас даже ёлка не готова..."};
tr[47236] = {OId:270,H:"Отставить панику! Сейчас мы со всем разберёмся. Вам не хватает ёлочных игрушек?"};
tr[47237] = {H:"Так точно!"};
tr[47238] = {OId:17,H:"Лампочки|Лампочки доставят через {0} мин."};
tr[47239] = {OId:799,H:"Поразительно! Какая большая и нарядная ёлка!"};
tr[47240] = {OId:130,H:"Спасибо, мы старались."};
tr[47241] = {H:"Да! Всем Шарарамом её украшали."};
tr[47242] = {OId:799,H:"Как замечательно! Так, сейчас подберём нужный кадр..."};
tr[47243] = {H:"Чтобы зафиксировать рекорд на камеру?"};
tr[47244] = {OId:799,H:"Конечно! И подскажите, какая у ёлки точная высота?"};
tr[47245] = {OId:800,H:"Ой, да мы ещё не измеряли... На глаз только."};
tr[47246] = {H:"И так видно, что большущая!"};
tr[47247] = {OId:801,H:"Кхм... Извините, но что-то вы рано начали снимать украшения."};
tr[47248] = {OId:802,H:"Думаешь, она это нам?"};
tr[47249] = {OId:803,H:"Хы, кто знает..."};
tr[47250] = {H:"Да-да, мы с вами разговариваем! Кто вы такие и как тут вообще оказались?"};
tr[47251] = {OId:802,H:"Кто-кто! Мыши, конечно."};
tr[47252] = {OId:803,H:"Пи-пи-пи! Хы."};
tr[47253] = {H:"И зачем вы нам ёлку портите? Из-за вас наш рекорд могут не принять!"};
tr[47254] = {H:"А вы разве не на Сырном острове должны быть?.."};
tr[47255] = {OId:802,H:"Так он уже давно того... Закончился."};
tr[47256] = {OId:803,H:"Эх, а вкусный был."};
tr[47257] = {H:"Остров свой съели, теперь ёлку нам портите. Из-за вас ведь рекорд не примут!"};
tr[47258] = {OId:801,H:"Понимаете, меня пригласили зафиксировать рекорд по украшению самой высокой новогодней ёлки..."};
tr[47259] = {OId:802,H:"Ну извиняйте, эта ёлка нам и самим нужна."};
tr[47260] = {OId:803,H:"Ещё как нужна! Хы-хы."};
tr[47261] = {H:"Но Крош с Ёжиком нашли её первыми, значит, она наша!"};
tr[47262] = {H:"Вы же с неё просто игрушки снимаете... Зачем она вам?"};
tr[47263] = {OId:802,H:"Враки!"};
tr[47264] = {OId:803,H:"Мы гораздо раньше её себе присмотрели."};
tr[47265] = {H:"И для чего же?"};
tr[47266] = {OId:802,H:"А вам всё расскажи!"};
tr[47267] = {OId:803,H:"Хы, размечтались. Это наш секрет. Мышиный!"};
tr[47268] = {H:"Вот даже как..."};
tr[47269] = {OId:801,H:"Как интригующе! Может позволите взять у вас интервью?"};
tr[47270] = {OId:802,H:"Пармезан мне в рот!"};
tr[47271] = {OId:803,H:"Это как у звёзд, что ли?"};
tr[47272] = {H:"Конечно! Игогоша же у нас лучший журналист Шарарама!"};
tr[47273] = {OId:801,H:"Нам интересно, почему эта ёлка так вас заинтересовала?"};
tr[47274] = {OId:802,H:"Честно сказать, ёлка нас мало интересует..."};
tr[47275] = {OId:803,H:"А вот шишка на ней - очень!"};
tr[47276] = {H:"Что ещё за шишка?"};
tr[47277] = {OId:802,H:"Есть тут одна... Давным-давно волшебник наколдовал её на эту ёлку."};
tr[47278] = {OId:803,H:"Да не простую, а золотую! Хы."};
tr[47279] = {H:"Аа, так вы разбогатеть хотите?"};
tr[47280] = {OId:802,H:"Нет, мы хотим эту шишку съесть!"};
tr[47281] = {OId:803,H:"Она ведь любые желания исполняет."};
tr[47282] = {H:"Вот оно что!.. Значит, вы ёлку нам портите из-за сказки какой-то."};
tr[47283] = {OId:801,H:"Ах, как увлекательно! Обожаю легенды..."};
tr[47284] = {OId:802,H:"Это не легенда, а правда!"};
tr[47285] = {OId:803,H:"Да, мы сами видели эту шишку!"};
tr[47286] = {H:"Где же вы могли её видеть?"};
tr[47287] = {OId:802,H:"Среди веток, конечно!"};
tr[47288] = {OId:803,H:"Мы видели, как она блеснула, когда кролик с ежом ёлку тащили."};
tr[47289] = {H:"И теперь вы не остановитесь, пока не найдёте эту шишку?"};
tr[47290] = {OId:802,H:"Да! И если не хотите, чтобы мы испортили вашу нарядную ёлочку..."};
tr[47291] = {OId:803,H:"То сами найдите нам шишку! А лучше - того, кто её создал!"};
tr[47292] = {H:"Ой, а сам волшебник-то вам зачем?"};
tr[47293] = {OId:270,H:"Привет! С наступающим Новым годом тебя!"};
tr[47294] = {H:"Привет! Спасибо, и тебя! Слушай, Шарри, ты же волшебник?"};
tr[47295] = {OId:270,H:"Как ты догадался?"};
tr[47296] = {H:"Да так... Хотел просто узнать, не умеешь ли ты создавать предметы, которые желания исполняют?"};
tr[47297] = {OId:270,H:"Смотря какие. Как-то я даже сказки воплотил в жизнь!"};
tr[47298] = {H:"Ух ты! А шишку, исполняющую желания, ты случайно не делал?"};
tr[47299] = {OId:270,H:"Так... Чёрная роза есть, снегоцветик собрал... Что ж там ещё?.."};
tr[47300] = {H:"Там - это где?"};
tr[47301] = {OId:270,H:"А ты чего подслушиваешь? Нехорошо это."};
tr[47302] = {H:"Простите! Мне просто кое-что уточнить у вас нужно..."};
tr[47303] = {OId:270,H:"Занят я, не видно? Но коли поможешь мне, так и быть выслушаю. В честь праздничка."};
tr[47304] = {H:"Ох... А с чем помощь нужна?"};
tr[47305] = {OId:270,H:"Ой-ой! Как времени-то мало осталось..."};
tr[47306] = {H:"Привет! Торопишься куда-то?"};
tr[47307] = {OId:270,H:"Конечно! Новый год вот-вот наступит, а подарки отправлены не все!"};
tr[47308] = {H:"Так давай помогу! А потом и ты мне."};
tr[47309] = {OId:270,H:"Вот и ты... Расскажешь, что у вас стряслось?"};
tr[47310] = {H:"Не знаю, с чего и начать..."};
tr[47311] = {OId:270,H:"Начни с начала. Я слышал, Крош и Ёжик хотят установить какой-то рекорд?"};
tr[47312] = {H:"Да! Игогоша уже приехала, чтобы его зафиксировать, но какие-то мыши испортили нам ёлку!"};
tr[47313] = {OId:270,H:"Вот как. И почему же они это сделали?"};
tr[47314] = {H:"Потому что злодеи! Они просто хотят сорвать наш рекорд!"};
tr[47315] = {H:"Искали на ёлке какую-то волшебную золотую шишку, исполняющую желания."};
tr[47316] = {OId:270,H:"Хм.. Не думаю, что всё так однозначно."};
tr[47317] = {H:"Ты прав... На самом деле они искали на ёлке какую-то золотую шишку, исполняющую желания."};
tr[47318] = {OId:270,H:"Не слышал ни о чём подобном. Даже интересно взглянуть на эту ёлку, покажешь?"};
tr[47319] = {H:"Конечно! Может ты нам заодно и с мышами поможешь..."};
tr[47320] = {OId:801,H:"Неужели тебе удалось найти того самого волшебника?.."};
tr[47321] = {OId:802,H:"Ух ты!"};
tr[47322] = {OId:803,H:"Ура, мы станем королями!"};
tr[47323] = {H:"Нет-нет, Умникус пришёл просто на ёлку посмотреть. И с вами поговорить."};
tr[47324] = {OId:802,H:"Эй, мы так не договаривались!"};
tr[47325] = {OId:803,H:"Мы ведь вам всю ёлку испортим!"};
tr[47326] = {H:"Подождиты вы... Умникус, всё в порядке?"};
tr[47327] = {OId:808,H:"Да... Но очень странно. Эта ёлка кажется мне знакомой."};
tr[47328] = {OId:802,H:"Хы, неудивительно."};
tr[47329] = {OId:803,H:"Возможно, вы ровесники."};
tr[47330] = {H:"Что?! Как такое может быть?"};
tr[47331] = {OId:802,H:"Очень просто. Иначе почему она такая большая?"};
tr[47332] = {OId:803,H:"Ага! Вокруг этой ёлки ещё наши прадеды ходили, золотую шишку караулили."};
tr[47333] = {H:"Невероятно!"};
tr[47334] = {OId:801,H:"Звучит, как начало отличного выпуска!"};
tr[47335] = {OId:802,H:"Ну уж нет! Никаких съёмок, пока вы не выполните обещание!"};
tr[47336] = {OId:803,H:"Или вы находите нам шишку, или попрощайтесь с ёлкой!"};
tr[47337] = {H:"Ой-ой! Умникус?.."};
tr[47338] = {OId:801,H:"Какая трогательная история!"};
tr[47339] = {OId:802,H:"Да..."};
tr[47340] = {OId:803,H:"Но грустно, что шишка оказалась простой игрушкой."};
tr[47341] = {H:"Эх, я тоже надеялся, что она волшебная."};
tr[47342] = {H:"Не грустите! Лучше пойдёмте отмечать Новый год с нами."};
tr[47343] = {OId:808,H:"Нельзя полагаться на волшебные вещи. Нужно верить в волшебство внутри себя."};
tr[47344] = {OId:802,H:"Но нам так хотелось чуда!"};
tr[47345] = {OId:803,H:"И сыра..."};
tr[47346] = {H:"Не грустите! Пойдёмте лучше праздновать с нами Новый год."};
tr[47347] = {OId:802,H:"А можно?"};
tr[47348] = {OId:803,H:"Ух ты!"};
tr[47349] = {H:"Конечно, можно!"};
tr[47350] = {OId:808,H:"Спускайтесь. Я догоню вас, как только приведу ёлку в порядок."};
tr[47351] = {OId:801,H:"А я измерю её высоту!"};
tr[47352] = {H:"Круто! Тогда встретимся внизу!"};
tr[47353] = {OId:804,H:"Ёлки-иголки! Мы думали, что вы там до следующего Нового года застряли!"};
tr[47354] = {H:"Ну, была парочка... серых сложностей."};
tr[47355] = {OId:805,H:"Это ты о... них?"};
tr[47356] = {OId:806,H:"Ага."};
tr[47357] = {OId:807,H:"Простите, что чуть не загубили ваш рекорд."};
tr[47358] = {H:"Ничего. Умникус уже всё поправил. Просто будьте в следующий раз осторожнее!"};
tr[47359] = {OId:806,H:"Обязательно!"};
tr[47360] = {OId:807,H:"Обещаем!"};
tr[47361] = {H:"Вот и славно. А где же Игогоша?"};
tr[47362] = {H:"Гирлянда " + "\"" + "Праздник к нам приходит" + "\"" + ""};
tr[47363] = {H:"Свечи " + "\"" + "Светлый Новый год" + "\"" + ""};
tr[47364] = {H:"Ободок " + "\"" + "Снежинки" + "\"" + ""};
tr[47365] = {H:"Фон " + "\"" + "Подарочек" + "\"" + ""};
tr[47366] = {H:"Свитер " + "\"" + "Тепло заботы" + "\"" + ""};
tr[47367] = {OId:800,H:"Скорее лезь на ёлку, чтобы измерить её точную высоту с Игогошей!"};
tr[47368] = {OId:801,H:"Найди волшебника, который мог наколдовать золотую шишку!"};
tr[47369] = {OId:803,H:"Если не поторопишься, то мы снимем с ёлки все-все игрушки!"};
tr[47370] = {OId:800,H:"Поторопись, пока мыши снова не начали портить нашу ёлку!"};
tr[47371] = {OId:270,H:"И тут, и там веселится народ. Ведь скоро Земля завершит оборот..."};
tr[47372] = {H:"Привет, Бараш! Стихи про космос сочиняешь?"};
tr[47373] = {OId:270,H:"Про Новый год, на самом деле. Но и про космос там немного есть..."};
tr[47374] = {H:"Кстати, про Новый год! Нужна помощь с украшением огромной ёлки. Есть у тебя что-нибудь?"};
tr[47375] = {OId:270,H:"Если только свечи. Ты знаешь, что раньше смешарики украшали ими новогоднюю ёлку?"};
tr[47376] = {H:"Ой, а это разве не опасно?"};
tr[47377] = {H:"Дверь в Новый год"};
tr[47378] = {H:"Свитер " + "\"" + "Праздничный" + "\"" + ""};
tr[47379] = {H:"Фон " + "\"" + "Снежный" + "\"" + ""};
tr[47380] = {H:"Новогодняя шапка 2026"};
tr[47381] = {H:"Наклейка " + "\"" + "Год Игогоши" + "\"" + ""};
tr[47382] = {H:"Костюм " + "\"" + "Праздничная ель" + "\"" + ""};
tr[47383] = {H:"Домик " + "\"" + "На новогодней ёлке" + "\"" + ""};
tr[47384] = {H:"Обложка " + "\"" + "Праздник 2026" + "\"" + ""};
tr[47385] = {H:"Стикеры " + "\"" + "Игогоша 2026" + "\"" + ""};
tr[47386] = {OId:800,H:"На ёлке кто-то есть? Ёлки-иголки! Чего же ты тут стоишь, беги помогать Игогоше!"};
tr[47387] = {OId:800,H:"Как дела наверху? Договорились с мышами, чтобы они не портили ёлку?"};
tr[47388] = {OId:800,H:"Ого, Умникус что-то знает? Тогда скорее поговори с ним!"};
tr[47389] = {OId:800,H:"Скорее забирайся на Ёлку! Умникус уже там!"};
tr[47390] = {OId:800,H:"Скорее забирайся на Ёлку! Похоже, Умникус что-то вспомнил!"};
tr[47391] = {OId:809,H:"С Новым годом!"};
tr[47392] = {OId:810,H:"С Новым рекордом!"};
