tr[47458] = {H:"Чучело " + "\"" + "Масленица" + "\"" + ""};
tr[47459] = {H:"Гирлянда " + "\"" + "Баранки" + "\"" + ""};
tr[47460] = {H:"Балалайка"};
tr[47461] = {H:"Ободок " + "\"" + "Солнышко" + "\"" + ""};
tr[47462] = {H:"Рубашка " + "\"" + "Весна-красна" + "\"" + ""};
tr[47463] = {H:"Фон " + "\"" + "Ишь ты, Масленица!" + "\"" + ""};
tr[47464] = {H:"Куртка " + "\"" + "Встречай весну" + "\"" + ""};
tr[47465] = {H:"Заколдованный меч"};
tr[47466] = {H:"Причёска " + "\"" + "Белый волк" + "\"" + ""};
tr[47467] = {H:"Доспехи " + "\"" + "Белый волк" + "\"" + ""};
tr[47468] = {OId:270,H:"Эй, давай веселиться! Масленица пришла, блины да подарки принесла!"};
tr[47469] = {OId:17,H:"Морковь|Морковь привезут через {0} мин."};
tr[47470] = {OId:270,H:"А, ребяты! Привет! Чем занимаетесь?"};
tr[47471] = {H:"Да Крош тут столько дел напридумывал. И хочет все сделать за пару дней. Вот помочь пытаюсь."};
tr[47472] = {OId:270,H:"Укуси меня пчела! Вот это настрой! Раз пришли, значится, и со мной есть какое-то дело?"};
tr[47473] = {H:"Копатыч, ты... только не злись. Но Крош хотел поучиться у тебя танцевать диско..."};
tr[47474] = {OId:270,H:"Бонжур, мон ами! Какой чудесный день для прогулки, правда?"};
tr[47475] = {H:"Это точно! А ещё для достижения всех поставленных целей!"};
tr[47476] = {OId:270,H:"Вау! А что же у тебя за цели, если не секрет?"};
tr[47477] = {H:"Не у меня, а у Кроша. Французский хочет подтянуть. Поможешь?"};
tr[47478] = {OId:270,H:"Писать стихи - моя стихия! И день, и ночь пишу стихи я..."};
tr[47479] = {H:"Привет, Бараш! Научишь этой своей... стихии? Крош тоже хочет поэтом стать."};
tr[47480] = {OId:270,H:"Крош? Поэтом?! Ха, смееешная шутка."};
tr[47481] = {H:"Я вполне серьёзно. Это у него одна из целей на год!"};
tr[47482] = {OId:270,H:"Какое кощунство! Стихи - это же... это же искусство! Творческий порыв нельзя запланировать!"};
tr[47483] = {H:"Ты прав. Наверное... Но может хоть совет ему какой-нибудь дашь?"};
tr[47484] = {OId:270,H:"В чём дело?.. Чего мы ждём?"};
tr[47485] = {H:"Крош, посмотри на себя. Ты же устал! Нужно перерыв сделать."};
tr[47486] = {OId:270,H:"Неправда! Да и вообще - на перерывы нет времени... Ещё столько всего нужно успеть!.."};
tr[47487] = {H:"До конца года ещё полно времени. Ты всё успеешь!"};
tr[47488] = {OId:270,H:"Да... Я всегда так думаю, а в декабре потом 102 недоделанных дела! Лучше скажи, что там дальше по списку?"};
tr[47489] = {H:"Эх... Похоже, тебя не переубедить. Сейчас посмотрю..."};
tr[47490] = {OId:270,H:"Друг мой смышлёный, не хотите ли сыграть в шахматы?"};
tr[47491] = {H:"Сам не очень, зато Крош хочет! И не просто сыграть, а победить тебя!"};
tr[47492] = {OId:270,H:"Как любопытно! Что же, я готов принять этот вызов."};
tr[47493] = {H:"Отлично! Удачи, Крош!"};
tr[47494] = {OId:270,H:"Утро тумааанное, утро седооое..."};
tr[47495] = {H:"Привет, Карыч! Романсы поёшь?"};
tr[47496] = {OId:270,H:"Кхм-кхм!.. Да, пою. Моя душа требует музыки!"};
tr[47497] = {H:"Ой, а у Кроша ведь тоже! Только он играть на рояле хочет научиться. Поможешь?"};
tr[47498] = {OId:270,H:"И, силь ву пле, не забудь про дискотеку! Я же должен танцевать. Танцевать..."};
tr[47499] = {H:"Крош, не хочу тебя пугать, но с тобой явно что-то не так!"};
tr[47500] = {OId:270,H:"Ха, точно! Не так! Надо было лошадью ходить, лошадью..."};
tr[47501] = {H:"У-у, ясно... Пора вызывать подмогу! Сейчас я кое-кому позвоню."};
tr[47502] = {OId:270,H:"Так-так, и что же с вами приключилось, юноша?"};
tr[47503] = {OId:811,H:"До-ре-ми-фа-соль-ля-си-дооо!.."};
tr[47504] = {H:"Ты же видишь - нотная болезнь!"};
tr[47505] = {H:"Мне кажется, он перетрудился."};
tr[47506] = {OId:270,H:"Чепуха! Я вижу, что он не болен, просто чересчур переутомился. Но от чего?"};
tr[47507] = {H:"Ну... Крош составил список дел на год и решил их все выполнить разом!"};
tr[47508] = {OId:270,H:"Вот как? Как же он умудрился?"};
tr[47509] = {H:"Крош составил список дел на год и решил их все выполнить разом!"};
tr[47510] = {OId:270,H:"Совсем без отдыха, что ли? Да разве ж так можно?! Ох! Неудивительно, что его нервы сдали!"};
tr[47511] = {H:"Ой... А поправить-то его состояние можно?"};
tr[47512] = {OId:270,H:"Никаких подвигов, пока не восстановишься окончательно!"};
tr[47513] = {OId:811,H:"Да ладно! Со мной уже всё в порядке!"};
tr[47514] = {H:"А мы вот не уверены. Ты совсем недавно такооое говорил..."};
tr[47515] = {OId:270,H:"Нёс полнейшую околесицу!"};
tr[47516] = {OId:811,H:"Может я вас разыгрывал просто, а?"};
tr[47517] = {H:"Тогда несмешные у тебя шутки."};
tr[47518] = {H:"Да? Значит, ты ещё можешь говорить по-французски и играть на рояле?"};
tr[47519] = {OId:811,H:"Ну, ладно-ладно. Не шутил я. Просто подустал чуток. С кем не бывает?"};
tr[47520] = {H:"С теми, кто бережёт своё здоровье и не забывает отдыхать!"};
tr[47521] = {OId:811,H:"Ну... Сейчас не могу. Подзабыл немного. С кем не бывает?"};
tr[47522] = {H:"С теми, кто бережёт своё здоровье и не пренебрегает отдыхом!"};
tr[47523] = {OId:270,H:"Именно! Отдых невероятно важен для нашего организма!"};
tr[47524] = {OId:811,H:"Ёлки-иголки! И что мне теперь только спать?!"};
tr[47525] = {H:"Это же круто! Я вот люблю вздремнуть."};
tr[47526] = {H:"Как скууучно!"};
tr[47527] = {OId:270,H:"Постоянно спать не нужно. Но без сна нельзя, ведь в нём усваивается вся новая информация."};
tr[47528] = {OId:811,H:"Так вот, почему у меня вчера всё в голове перемешалось..."};
tr[47529] = {H:"Ага! Некогда голове было по полочкам всё разложить."};
tr[47530] = {OId:270,H:"А теперь тебе стоит подвигаться! Пассивно ты уже отдохнул, пора и активно."};
tr[47531] = {OId:811,H:"Ого! Это я с удовольствием!"};
tr[47532] = {H:"Может на сноуборде покатаешься?"};
tr[47533] = {OId:270,H:"Хо-хо! Превосходная мысль!"};
tr[47534] = {OId:811,H:"Я как раз хотел! Только... Не помню, где свой сноуборд оставил."};
tr[47535] = {H:"Давай поищем. Заодно и прогуляемся. А это тоже полезно!"};
tr[47536] = {OId:270,H:"Помоги найти сноуборд Кроша в Шарараме! А мы посмотрим нет ли его поблизости."};
tr[47537] = {OId:270,H:"Помоги мне выполнить ещё несколько крутых дел!"};
