tr[47671] = {OId:17,H:"Суши|Суши приготовят через {0} мин."};
tr[47672] = {OId:270,H:"Аууууууу!.."};
tr[47673] = {H:"Привет, Сумрак! Разве тебе не нужно собираться? Или ты репетируешь?"};
tr[47674] = {H:"Аууууу!"};
tr[47675] = {OId:270,H:"Лучше бы я репетиррровал... Грущу я. Не видать мне космических гастролей..."};
tr[47676] = {H:"Это ещё почему?"};
tr[47677] = {OId:270,H:"Луна в космосе - вот почему. Увижу её и сразу в волка превращусь. Не до концерррта будет..."};
tr[47678] = {H:"Ой, и правда... Но ведь можно что-то сделать, чтобы ты её не видел?"};
tr[47679] = {OId:270,H:"Напримеррр? Лететь в космос с закрытыми глазами?"};
tr[47680] = {H:"А что? Это идея!"};
tr[47681] = {H:"Или... создать очки, через линзы которых луна не сможет на тебя влиять!"};
tr[47682] = {OId:270,H:"Ррр... Нет уж, спасибо."};
tr[47683] = {H:"Тогда можно специальные очки создать. С такими линзами, чтобы луна тебя не меняла!"};
tr[47684] = {OId:270,H:"Думаешь, это возможно?"};
tr[47685] = {H:"Не уверен. Но попробовать стоит!"};
tr[47686] = {H:"Всё невозможное - возможно, знаю точно!"};
tr[47687] = {OId:812,H:"Ахтунг! Куда вы собраться?"};
tr[47688] = {OId:813,H:"Поближе к звёздам!"};
tr[47689] = {H:"У них гастроли в космосе! А я помогаю. Сейчас вот полетим..."};
tr[47690] = {OId:812,H:"Найн! Никуда вы не лететь!"};
tr[47691] = {OId:814,H:"Йоу! Как так?!"};
tr[47692] = {OId:815,H:"Нас ждут фанаты!"};
tr[47693] = {H:"Пин, почему мы не можем полететь?"};
tr[47694] = {OId:812,H:"Потому что без тщательной подготовка в космос нельзя!"};
tr[47695] = {OId:816,H:"Но мы полностью готовы!"};
tr[47696] = {H:"Ты можешь нас проверить, мы и вправду готовы к полёту."};
tr[47697] = {OId:817,H:"С физической подготовкой у нас всё в порррядке."};
tr[47698] = {H:"Ещё бы! Столько на сцене работаете."};
tr[47699] = {OId:812,H:"Йа-йа! Подготовка отличный. Но все ли здоровы?"};
tr[47700] = {OId:818,H:"Конечно! Мы проверялись у доктора Бинтика."};
tr[47701] = {H:"Ого! А справки есть?"};
tr[47702] = {OId:819,H:"Рад вас приветствовать. На время шоу космостанция в вашем распоряжении."};
tr[47703] = {OId:820,H:"Улёт!"};
tr[47704] = {H:"Значит, концерт пройдёт прямо здесь?"};
tr[47705] = {OId:819,H:"Так точно. Совсем скоро прибудут зрители."};
tr[47706] = {OId:816,H:"Тогда начинаем готовиться!"};
tr[47707] = {H:"Нужна помощь?"};
tr[47708] = {OId:821,H:"Что происходит?!"};
tr[47709] = {OId:822,H:"А-а-а!"};
tr[47710] = {OId:823,H:"О-ой!"};
tr[47711] = {OId:819,H:"Всем сохранять спокойствие!"};
tr[47712] = {H:"Спокойствие?! Да мы же падаем!"};
tr[47713] = {H:"Базу, в чём дело?"};
tr[47714] = {OId:819,H:"Похоже, наш мощный концерт вызвал метеоритный дождь."};
tr[47715] = {H:"Упс... И что теперь делать?"};
tr[47716] = {OId:821,H:"С ума сойти! Живые! Ребята, выходите из-за кулис, всё закончилось!"};
tr[47717] = {OId:822,H:"Кого же нам благодарить за спасение?"};
tr[47718] = {H:"Меня, конечно!"};
tr[47719] = {H:"Капитана! Базу не поддался панике и всех нас спас."};
tr[47720] = {OId:819,H:"Да, смешарик молодец..."};
tr[47721] = {OId:821,H:"А капитан тебе разве не помогал?"};
tr[47722] = {H:"Мы работали с ним вместе!"};
tr[47723] = {OId:819,H:"Без помощи смешарика у меня бы ничего не вышло."};
tr[47724] = {OId:823,H:"Спасибо вам!"};
tr[47725] = {H:"Пожалуйста!"};
