tr[47828] = {H:"Кеды " + "\"" + "Концерт в парке" + "\"" + ""};
tr[47829] = {H:"Светлый"};
tr[47830] = {H:"Тёмный"};
tr[47831] = {H:"Шаман"};
tr[47832] = {H:"Фея"};
tr[47833] = {H:"Верховный"};
tr[47834] = {OId:17,H:"Сливочные ягоды|Ягоды созреют через {0} мин."};
tr[47835] = {OId:270,H:"Бж-ж-ж!"};
tr[47836] = {H:"И тебе привет! Ты случайно не от Копатыча улетел?"};
tr[47837] = {OId:270,H:"Улетел, как и остальные. У наззз отпуск!"};
tr[47838] = {H:"А почему ты один? Где же все?"};
tr[47839] = {OId:270,H:"Самому интересно! Хотел перед полётом подкрепиться, а меня никто не подожжждал..."};
tr[47840] = {H:"Так ты голоден? Давай я тебя покормлю! А потом ты к Копатычу вернёшься."};
tr[47841] = {OId:270,H:"Кто мечтает собрать мёда. Очень смелый, видно, тот..."};
tr[47842] = {H:"Потому что только смелый сам полезет к пчёлам в дом!"};
tr[47843] = {H:"А ты неплохо жужжишь!"};
tr[47844] = {OId:270,H:"Бз-з-яу! Ты тожжже знаешь эту песню?!"};
tr[47845] = {H:"Конечно! У тебя хорошо её жужжать получается."};
tr[47846] = {OId:270,H:"Спасибо! Я самый музззыкальный в нашем улье."};
tr[47847] = {H:"Здорово! Кстати, про ульи... Не знаешь, где все твои соседи?"};
tr[47848] = {OId:270,H:"Отдыхать улетели. А я тут по пути зззаслушался музыкой и потерял их."};
tr[47849] = {H:"Не волнуйся, я их найду! Только тебя бы снова не потерять... Может, вернёшься?"};
tr[47850] = {OId:270,H:"Укуси меня... Шмель!"};
tr[47851] = {OId:824,H:"Прошу вас, милейшие, давайте беззз криков... Я только проснулся."};
tr[47852] = {H:"Министр Шмель, что случилось? "};
tr[47853] = {OId:270,H:"Мы уж думали, вы того... В отпуске вместе с остальными."};
tr[47854] = {OId:824,H:"Каком ещё отпуске? О чём вы говорите?"};
tr[47855] = {H:"Так все пчёлы улетели. Вот - записку только оставили."};
tr[47856] = {OId:270,H:"Ага. Пятерых ещё найти удалось, а остальные как испарились."};
tr[47857] = {OId:824,H:"Бж-ж! Усам своим не верю!"};
tr[47858] = {H:"Значит, вы ничего про отпуск не знаете?"};
tr[47859] = {OId:824,H:"Ничего. Но догадываюсь, что никакой это не отпуск, господа. Пчёл выкрали!"};
tr[47860] = {H:"Не может быть!"};
tr[47861] = {H:"Ой! И как мы не догадались?"};
tr[47862] = {OId:270,H:"Ох, чуяло моё сердце неладное!"};
tr[47863] = {OId:824,H:"Ночью меня выманил иззз улья странный тип и наслал чары сна... Хотел же я его проверить!"};
tr[47864] = {H:"Как он выглядел?"};
tr[47865] = {H:"А как вы могли его проверить?"};
tr[47866] = {OId:824,H:"Разве ж-ж-ж в темноте разберёшь? Крылат да полосат, как и все."};
tr[47867] = {H:"Верно. Но вы сказали, что хотели его как-то проверить?"};
tr[47868] = {OId:824,H:"Есть у нас особый пчелиный танец. Он раскрывает обман и снимает любые чары!"};
tr[47869] = {H:"Вот это да! А можете меня научить?"};
tr[47870] = {OId:824,H:"Хм... С одной стороны - это секрет. Но с другой - ты нам помогаешь и должен быть готов ко всему."};
tr[47871] = {H:"Я никому не расскажу!"};
tr[47872] = {OId:824,H:"Что ж, вот таким танцем мы всех обманщиков и раскрываем."};
tr[47873] = {H:"Спасибо, что научили, министр! "};
tr[47874] = {H:"Хореограф из вас прямо-таки волшебный!"};
tr[47875] = {OId:270,H:"Танцы - это, конечно, здорово. Но как ж они помогут нам пчёлок вернуть?"};
tr[47876] = {H:"Может есть специальный танец и для поисков?"};
tr[47877] = {OId:270,H:"Эх, было б славно..."};
tr[47878] = {OId:824,H:"К сожжжалению, нет. Придётся действовать иначе."};
tr[47879] = {H:"Ну, раз сами мы пчёл найти не смогли, пора обращаться к технике!"};
tr[47880] = {OId:824,H:"Что вы имеете в виду?"};
tr[47881] = {H:"Нужно придумать какое-нибудь устройство для поиска пчёл!"};
tr[47882] = {OId:270,H:"О, я сегодня как раз Пина в Порту видел. Наверняка, он чего придумает!"};
tr[47883] = {H:"Отлично, я пойду поговорю с ним. А вы сторожите вернувшихся пчёл!"};
tr[47884] = {OId:270,H:"Я сегодня видел Пина в Порту. Погляди, может наш технический гений ещё там."};
tr[47885] = {OId:824,H:"Надеюсь, Пин придумает что-нибудь для поиска пчёл. Копатыч говорит, он сейчас в Порту."};
tr[47886] = {OId:270,H:"Что-то случиться? Ты выглядеть грустно!"};
tr[47887] = {H:"Да у Копатыча кто-то пчёл украл. Пытаюсь их найти. Сможешь помочь?"};
tr[47888] = {OId:270,H:"Йа-йа! У меня есть фантастиш устройство - находить любые существа!"};
tr[47889] = {H:"Как раз то, что нужно! Можно воспользоваться?"};
tr[47890] = {OId:270,H:"С этим небольшой проблема... Я забыть, где его оставить."};
tr[47891] = {H:"Ну вот... А как это устройство хоть выглядит?"};
tr[47892] = {OId:270,H:"Помоги найти универсальный локатор в Шарараме! А я поискать поблизости."};
tr[47893] = {H:"Виниловый проигрыватель"};
tr[47894] = {H:"Телескоп Лосяша"};
tr[47895] = {H:"Причёска " + "\"" + "Лауреат" + "\"" + ""};
tr[47896] = {H:"Пиджак " + "\"" + "Торжество разума" + "\"" + ""};
tr[47897] = {H:"Ловушка для снов"};
tr[47898] = {OId:270,H:"О, это быть как ящик с антенна и много кнопка!"};
tr[47899] = {H:"Хм, похоже на детектор... А где ты его в последний раз видел?"};
tr[47900] = {OId:270,H:"Йа! Я помнит! В Амбар у Кар-Карыча ходить!"};
tr[47901] = {H:"Отлично, проверю там! Спасибо за помощь!"};
tr[47902] = {OId:270,H:"Давайте-давайте! Работайте! Солнца здесь не видно"};
tr[47903] = {H:"Правильно! Работников нужно мотивировать!"};
tr[47904] = {H:"Прекратите немедленно!"};
tr[47905] = {OId:270,H:"Именно! Хм... А ты кто такой?"};
tr[47906] = {H:"Да так, мимо проходил. Услышал ваши крики и решил взглянуть."};
tr[47907] = {OId:270,H:"Поглядел? Теперь уходи! Иначе превращу в пчелу и тоже у меня работать будешь!"};
tr[47908] = {H:"Ага, самозванец, попался! Настоящий Шмель колдовать-то не умеет."};
tr[47909] = {OId:270,H:"Ха! Да разве стали бы меня слушать пчёлы, будь я самозванцем?"};
tr[47910] = {H:"Пчёлы слушаются только королеву. А ты её заколдовал!"};
tr[47911] = {OId:270,H:"Так-так. Кто это мешает мне командовать? И почему я должен прекратить?"};
tr[47912] = {H:"Потому что ты ненастоящий Шмель! Лишь притворяешься им!"};
tr[47913] = {OId:270,H:"Рр... То есть, кхм! Бз-з-з... Зря ты злишь меня своими домыслами."};
tr[47914] = {H:"Это не домыслы, а правда. Сейчас я сниму с тебя чары и докажу это!"};
tr[47915] = {OId:270,H:"Что... Как ты это сделал?!"};
tr[47916] = {OId:825,H:"Святой нектар! В чём дело?"};
tr[47917] = {H:"Министр Шмель научил меня этому танцу, снимающему любые чары."};
tr[47918] = {OId:270,H:"Проклятье!.."};
tr[47919] = {OId:825,H:"Спасибо тебе! Министра я поблагодарю позжжже. Но где мы?"};
tr[47920] = {H:"Глубоко в лесу. Злобикус решил вам тут " + "\"" + "отпуск" + "\"" + " устроить."};
tr[47921] = {OId:270,H:"Р-р! А что мне оставалось делать? Проклятые пчёлы не желают работать в моём царстве!"};
tr[47922] = {OId:825,H:"Потому что нам нужжжно солнце!"};
tr[47923] = {H:"Ты мог бы попросить у Копатыча бочку мёда, раз так сладкого захотелось."};
tr[47924] = {OId:270,H:"У меня аллергия на весь мёд, кроме такого! Из чёрной розы."};
tr[47925] = {OId:825,H:"Боюсь, это не оправдывает твоего поведения..."};
tr[47926] = {H:"Ты выдавал себя за другого. Напал на министра и королеву!"};
tr[47927] = {OId:270,H:"Да разве это преступления... Просто смешно."};
tr[47928] = {OId:825,H:"Кажжжется, мои подданные думают иначе."};
tr[47929] = {H:"Ха! Ну, Злобикус, берегись!"};
tr[47930] = {OId:270,H:"Ну, что? Придумал Пин как пчёл найти? Чего же ты ждёшь, скорее иди по следу!"};
tr[47931] = {OId:270,H:"Жу-жу-жу! Как же классно я лежжжу!"};
tr[47932] = {H:"Привет! Смотрю, отдыхаешь?"};
tr[47933] = {OId:270,H:"Ага! Давно мечтал в отпуск слетать."};
tr[47934] = {H:"Недалеко ты что-то улетел... А остальные пчёлы где?"};
tr[47935] = {OId:270,H:"Они дальше полетели. Хотя зззачем? И тут круто! К тому жжже напрягаться не надо..."};
tr[47936] = {H:"Крылышки свои жалеешь?"};
tr[47937] = {H:"Неужели ты такой лентяй, что даже в отпуск не полетел?"};
tr[47938] = {OId:270,H:"Это я ещё жжжалею? Ха! Кому-то даже из сада Копатыча вылететь тяжко!"};
tr[47939] = {H:"Ого! Про кого это ты?"};
tr[47940] = {OId:270,H:"Про своего брата-близззнеца. Наверняка, в груше спрятался! Он там вечно отсиживается."};
tr[47941] = {H:"В груше говоришь? Как интересно..."};
tr[47942] = {OId:270,H:"Тс-с, я ж тебе по секрету это рассказззал! Не трогай его. И не кидайся ничем..."};
tr[47943] = {H:"Да понял я, понял... что вы два лентяя..."};
tr[47944] = {H:"Домик " + "\"" + "Пчелиная дача" + "\"" + ""};
tr[47945] = {H:"Шарафон " + "\"" + "Бз-з-з" + "\"" + ""};
tr[47946] = {OId:826,H:"Эй! Зззачем кидаешься?"};
tr[47947] = {H:"А ты зачем там прячешься?"};
tr[47948] = {OId:826,H:"" + "\"" + "Потому что секретный агент " + "\"" + "Полосатик" + "\"" + " на миссии!" + "\"" + ""};
tr[47949] = {H:"Ну... Теперь агент не такой уж секретный."};
tr[47950] = {OId:826,H:"Ты дажжже не спросишь про мою миссию?"};
