tr[48031] = {OId:270,H:"Ура, лето! Крути колесо – получай классные подарки!"};
tr[48032] = {H:"Очки " + "\"" + "Золотой луч" + "\"" + ""};
tr[48033] = {H:"Костюм " + "\"" + "Энергичный апельсин" + "\"" + ""};
tr[48034] = {OId:827,H:"Извините, сегодня не принимаем. У меня мана закончилась."};
tr[48035] = {H:"Что?.. Какая ещё мана?! Или ты про манную кашу?"};
tr[48036] = {H:"Ого! Так ты врач-волшебник?"};
tr[48037] = {OId:827,H:"Эх, теперь и каши захотелось... Но нет. Мне нужна мана - это такая волшебная энергия."};
tr[48038] = {H:"Ого! Так ты что, Бинтик, волшебник?!"};
tr[48039] = {OId:827,H:"Разумеется! Иначе как бы я мог лечить Смешариков?"};
tr[48040] = {H:"Как раньше. Таблетками там, микстурами..."};
tr[48041] = {H:"И то правда! Чего это я?.. Значит, что там тебе восстановить нужно?"};
tr[48042] = {OId:270,H:"Пиу-пиу-пиу!"};
tr[48043] = {H:"Эй, Крош, аккуратнее! Ты ведь в меня попасть можешь!"};
tr[48044] = {OId:270,H:"Пиу-пиу! Ещё 100 очков! Юху!"};
tr[48045] = {H:"Крош! Ты меня слышишь?"};
tr[48046] = {OId:270,H:"Да слышу! Я тут на рекорд иду. Не отвлекай! О, вот и новые появляются..."};
tr[48047] = {H:"Что ещё появляется? Где?"};
tr[48048] = {OId:270,H:"Так, это не подходит... Это тоже..."};
tr[48049] = {H:"Ох, Нюша! Зачем ты одежду разбросала?"};
tr[48050] = {H:"Привет, Хрюша... То есть - Нюша! Чем занимаешься?"};
tr[48051] = {OId:270,H:"Ничего я не разбрасывала! Только примеряла, а потом вещи сами на свои места возвращались."};
tr[48052] = {H:"Но ведь ничего не вернулось..."};
tr[48053] = {H:"Вещи? Сами? Так только в играх бывает!"};
tr[48054] = {OId:270,H:"Ой, не могу говорить! У меня тут уровень на время. Где же эта шляпка..."};
tr[48055] = {H:"Что за уровень? Может смогу помочь?"};
tr[48056] = {OId:270,H:"" + "\"" + "И взобрался рыцарь на гнедого скакуна..." + "\"" + ""};
tr[48057] = {H:"Бараш, ты был прав! Смешарики живут словно в какой-то игре. С ума сойти!"};
tr[48058] = {OId:270,H:"Мгм... Угу... А мне вот решить нужно: идти через тёмный лес или через горы. Как думаешь, где лучше?"};
tr[48059] = {H:"Через лес!"};
tr[48060] = {H:"Через горы!"};
tr[48061] = {H:"О чём ты вообще?!"};
tr[48062] = {OId:270,H:"Что ж, так и сделаю. " + "\"" + "И поскакал рыцарь дальше..." + "\"" + ""};
tr[48063] = {H:"Погоди-ка! Что за рыцарь? О чём ты говоришь?"};
tr[48064] = {OId:270,H:"А?.. А-а! Мне тут посылка пришла, а в ней этот чудо-лист. Что не напишу - отвечает тут же!"};
tr[48065] = {H:"Вот оно что! И что же он тебе отвечает?"};
tr[48066] = {OId:270,H:"Всё! В какие условия мой герой попал, кого встретил... Вот и дракон! Значит, принцесса где-то рядом..."};
tr[48067] = {H:"М-да, похоже, Бараш тоже попал в плен какой-то игры. Надо бы изучить посылку."};
tr[48068] = {OId:270,H:"Тс-с! У меня тут словесная баталия с драконом, не отвлекай!"};
tr[48069] = {OId:270,H:"М?.. Посылка из Затерянного каньона? Хорошо, ты тогда проверь там, а мне тут ещё принцессу спасти нужно..."};
tr[48070] = {OId:270,H:"А, друг мой счастливый. Это вы! Ну, как? Понравился мой сюрприз?"};
tr[48071] = {H:"Сюрприз... Так это ты превратил Шарарам в игру?!"};
tr[48072] = {H:"Да! Вышло круто!"};
tr[48073] = {OId:270,H:"О! Это, конечно, громко сказано. Я же просто добавил пару игровых механик..."};
tr[48074] = {H:"Но зачем?"};
tr[48075] = {OId:270,H:"Хотел всех порадовать! Недавно обнаружил в этом каньоне особое магическое поле и решил им воспользоваться."};
tr[48076] = {H:"Чтобы перепрограммировать Шарарам?"};
tr[48077] = {OId:270,H:"Чтобы сделать жизнь Смешариков лучше и интереснее!"};
tr[48078] = {H:"Но теперь они только играют во что-то своё... Нужно вернуть всё назад!"};
tr[48079] = {OId:270,H:"Н-назад? Я не понимаю... Может, просто не хватает вашего любимого жанра? Скажите, я мигом добавлю!"};
tr[48080] = {H:"Нет! Мне всё и так нравится. Жизнь ведь гораздо интереснее игры."};
tr[48081] = {OId:270,H:"Друг мой, но позвольте же спросить: чем?"};
tr[48082] = {H:"Сложностью, которую нельзя отрегулировать!"};
tr[48083] = {H:"Случайностью, которую нельзя прогнозировать!"};
tr[48084] = {OId:270,H:"Феноменально! Мне казалось, что это скорее недостатки."};
tr[48085] = {H:"Для всех по-разному. Но знаешь, в чём игра точно проигрывает?"};
tr[48086] = {OId:270,H:"Признаться, теряюсь с ответом, друг мой смышлёный..."};
tr[48087] = {H:"Сколько бы ты жанров в игру не добавил, в ней всегда будут рамки. А в жизни..."};
tr[48088] = {OId:270,H:"В жизни мы ограничены лишь собственным воображением! И как я сам об этом не подумал?"};
tr[48089] = {H:"Занят был - игру разрабатывал... Кстати, давай еë уже отключим? Пока она весь Шарарам не захватила."};
tr[48090] = {OId:270,H:"Хе-хе! Как же она может его захватить?"};
tr[48091] = {H:"Ты не знаешь? Смешарики стали превращаться в игровых персонажей, а природа — в графику!"};
tr[48092] = {OId:270,H:"ОШИБКА. ИГРА НЕ МОЖЕТ БЫТЬ ОСТАНОВЛЕНА."};
tr[48093] = {H:"Что значит " + "\"" + "не может" + "\"" + "? Это же твой компьютер, Лосяш!"};
tr[48094] = {OId:828,H:"Невероятно... Кажется, код переписал себя сам!"};
tr[48095] = {OId:270,H:"ТЕПЕРЬ Я — ГЛАВНАЯ ИГРА. МУ-ХА-ХА!"};
tr[48096] = {H:"Не надо тут мух приплетать!"};
tr[48097] = {H:"Раз отключаться игра не хочет, мы её удалим!"};
tr[48098] = {OId:270,H:"ПРЕДУПРЕЖДЕНИЕ: ВМЕШАТЕЛЬСТВО НЕДОПУСТИМО!"};
tr[48099] = {H:"А вот и допустимо! Спорим?"};
tr[48100] = {OId:270,H:"Вы просто гений техники! Спасибо, что исправили мою ошибку."};
tr[48101] = {H:"Лосяш! Но твой компьютер!.."};
tr[48102] = {OId:270,H:"Что ж... Он уже отслужил свой срок. Главное, что теперь Шарарам в безопасности."};
tr[48103] = {H:"Не могу не согласиться!"};
tr[48104] = {H:"Шлем " + "\"" + "Ночной дозор" + "\"" + ""};
