tr[48121] = {OId:829,H:"БУ! Испугался?"};
tr[48122] = {H:"А-а-а! Говорящие пиксели!"};
tr[48123] = {H:"Ещё чего!"};
tr[48124] = {OId:829,H:"ХА-ХА! От таких же говорящих пикселей слышу!"};
tr[48125] = {H:"Я смешарик, а не какие-то пиксели! И кто ты вообще такой?"};
