tr[48127] = {H:"А ты кто такой?"};
tr[48128] = {OId:829,H:"Ошибка в системе, сбежавшая из компьютера хозяина. ХА-ХА!"};
tr[48129] = {H:"Но разве ошибки могут жить не в программе или игре?"};
