tr[48142] = {H:"Спутник Мурзик"};
tr[48143] = {OId:270,H:"Хей, рад тебя видеть! Гастроли прошли супер! А вы тут как? Где Мурзик?"};
tr[48144] = {H:"У нас всё отлично! И Мурзик со мной. Ты что, не узнал своего кота?"};
tr[48145] = {OId:270,H:"Ха-ха! Ты же шутишь, да? "};
tr[48146] = {H:"Да вроде нет..."};
